  // W291 — dev-only Ascent balance sim. Runs the REAL engine for a MAX build
  // (base 20 + the 8 best-in-slot bonuses, weapon = weaponId) vs floor `floor`,
  // N seeded battles, reports win-rate. Drives the player with the engine's own
  // _arenaPickMove so both sides play competently. Additive/non-engine.
  function _arenaSimAscent(floor, weaponId, opts) {
    opts = opts || {};
    const n = opts.n || 2000, seed0 = (opts.seed0 != null) ? opts.seed0 : 1;
    const BIS = {
      helm:   'crown_of_eternal_night',
      weapon: weaponId,
      plate:  'mantle_of_the_sovereign',     // W563 — ARMOR/plate is body-only now (greaves/legs moved to BOOTS)
      cape:   'mantle_of_the_long_vigil',
      amulet: 'amulet_of_the_endless_stair',
      ring:   'skyward_vigil_ring',
      gloves: 'forgewarden_gauntlets',
      // W685 — instrument fix: boots were stale since the W563 legs→boots remap.
      // greaves_of_the_umbral_throne (S ultra Σ36, sovereign_regalia) strictly
      // dominates the A-tier striders (Σ31) AND completes the Sovereign 3pc with
      // mantle+crown — the sim under-reported the true min-maxed ceiling (the
      // "36.2%" F100 wall is really ~43% for a correctly built player). The wall
      // constants are UNTOUCHED; only the measurement is honest now.
      boots:  'greaves_of_the_umbral_throne',
    };
    // W686 — opts.bisOverride: swap specific slots (keys above; 'plate' = body)
    // BEFORE aggregation, so the set-count and upgrade loops below follow the
    // override automatically. Lets the balance sim measure ALTERNATE loadouts
    // (e.g. the Sleepless Crown class-BiS trios) instead of only the fixed BIS.
    if (opts.bisOverride) {
      Object.keys(opts.bisOverride).forEach((slot) => {
        if (BIS[slot] !== undefined && CARDS[opts.bisOverride[slot]]) BIS[slot] = opts.bisOverride[slot];
      });
    }
    const gear = { str: 0, vit: 0, int: 0, focus: 0, will: 0, wlt: 0 };
    Object.keys(BIS).forEach((slot) => {
      const c = CARDS[BIS[slot]];
      if (c && c.bonuses) ['str', 'vit', 'int', 'focus', 'will', 'wlt'].forEach((k) => { gear[k] += (c.bonuses[k] || 0); });
    });
    // W510 — INSTRUMENT FIX: the LIVE combat path (_aggregateBuildBonuses) folds in
    // W495/W506 SET BONUSES + W494 RELIC UPGRADES, but this sim historically built the
    // statline from BiS card bonuses ONLY. So it under-reported the true ceiling and the
    // fixed F100 wall silently softened every time a relic/upgrade/set shipped, unseen.
    // opts.invest models the real investment spread so the balance check stops measuring a
    // phantom: 'gear' (BiS only — legacy, byte-identical default), 'sets' (+ active set
    // bonuses), 'max' (+ both sets AND maxed relic upgrades = the true min-maxed ceiling).
    const invest = opts.invest || 'gear';
    if (invest === 'sets' || invest === 'max') {
      // Active set bonuses over the BiS build — mirrors _activeSetBonuses' single-highest-tier rule.
      const setCounts = {};
      Object.keys(BIS).forEach((slot) => { const c = CARDS[BIS[slot]]; if (c && c.set_id) setCounts[c.set_id] = (setCounts[c.set_id] || 0) + 1; });
      Object.keys(setCounts).forEach((sid) => {
        const set = (typeof SET_BONUSES !== 'undefined') ? SET_BONUSES[sid] : null;
        if (!set || !set.tiers) return;
        let best = null;
        for (const t of set.tiers) if (setCounts[sid] >= t.pieces && (!best || t.pieces > best.pieces)) best = t;
        if (best && best.bonus) Object.keys(best.bonus).forEach((k) => { if (Object.prototype.hasOwnProperty.call(gear, k)) gear[k] += (best.bonus[k] | 0); });
      });
    }
    if (invest === 'max') {
      // Maxed relic upgrades — +RELIC_UPGRADE_MAX to each upgradeable relic's dominant stat (W494).
      Object.keys(BIS).forEach((slot) => {
        const c = CARDS[BIS[slot]];
        if (!c || RELIC_UPGRADE_BASE_COST[c.tier] == null) return;   // commons / unpriced tiers are not upgradeable
        const dom = _relicDominantStatKey(c);
        if (dom && Object.prototype.hasOwnProperty.call(gear, dom)) gear[dom] += RELIC_UPGRADE_MAX;
      });
    }
    // W510 — opts.gearScale scales the GEAR contribution (base-20 innate stats are
    // untouched) so the sim can model the whole player spectrum, not just the whale:
    // gearScale 0 = a base-only fresh build, ~0.4 ≈ a strong-but-unmaxed A-rank build
    // (~283 raw, e.g. Rendiesel), 1.0 = full BiS. Lets us read the power→win-rate curve
    // at any floor and find what power a floor actually gates at.
    if (opts.gearScale != null) {
      const gs = +opts.gearScale;
      ['str', 'vit', 'int', 'focus', 'will', 'wlt'].forEach((k) => { gear[k] *= gs; });
    }
    const sline = { STR: 20 + gear.str, VIT: 20 + gear.vit, INT: 20 + gear.int, FOCUS: 20 + gear.focus, WILL: 20 + gear.will, WLT: 20 + gear.wlt };
    const prof = _arenaCombatProfile(sline);
    const player = { name: 'Hunter', attack: prof.attack, defense: prof.defense, edge: prof.edge, stats: sline, isBot: false };
    const playerArch = _arenaArchOf(player);
    let kitIds = (WEAPON_MOVES[weaponId] || WEAPON_MOVES.unarmed).slice();
    // W757 -- the 'max' invest tier includes maxed relic upgrades, which now
    // UNLOCK the ultra+ weapon's execute; lower tiers fight without it.
    if (invest === 'max') { const ex = _weaponExecuteId(weaponId); if (ex && kitIds.indexOf(ex) === -1) kitIds.push(ex); }
    const kit = kitIds.map((id) => Object.assign({ id }, ARENA_MOVE_LIB[id]));
    const attuned = (_WEAPON_ATTUNE[weaponId] || []).indexOf(playerArch) !== -1 ? _ATTUNED_MULT : 1;
    let wins = 0, koWins = 0, toWins = 0, foePower = 0;
    const turnsArr = [], marginArr = [];
    for (let i = 0; i < n; i++) {
      const opp = _ascentOpponent(floor);
      if (opts.foeAtkMul) opp.attack *= opts.foeAtkMul;     // experiment knob: lethality
      if (opts.foeDefMul) opp.defense *= opts.foeDefMul;    // experiment knob: HP / fight length
      opp.power = opp.attack + opp.defense + opp.edge;
      foePower = opp.power;
      const sess = arenaStartBattle({ floor: floor, advances: false, player: player, bot: opp }, seed0 + i);
      sess.pMoves = kit;          // headless: override the closure-read (empty) kit
      sess.pAttuned = attuned;    // load-bearing: real attunement, not the headless default 1
      let g = 0;
      while (!sess.done && g++ < 300) {
        const mv = _arenaPickMove({
          moves: sess.pMoves, cd: sess.cd,
          selfHP: sess.pHP, selfMax: sess.pMax, selfS: sess.pS,
          foeHP: sess.bHP, foeMax: sess.bMax, foeS: sess.bS,
          typeEff: sess.pEff, rng: sess.rng,
        });
        if (!arenaTakeTurn(sess, mv.id)) break;
      }
      if (sess.won) { wins++; if (sess.bHP <= 0) koWins++; else toWins++; }
      turnsArr.push(sess.turn);
      marginArr.push(sess.pHP / sess.pMax - sess.bHP / sess.bMax);
    }
    const med = (arr) => { const a = arr.slice().sort((x, y) => x - y); return a.length ? a[Math.floor(a.length / 2)] : 0; };
    return {
      floor: floor, weaponId: weaponId, n: n,
      playerPower: Math.round(prof.power), playerArch: playerArch, attuned: attuned,
      foePower: Math.round(foePower),
      winRate: +(wins / n).toFixed(3),
      medianTurns: med(turnsArr),
      medianHpMargin: +med(marginArr).toFixed(3),
      koWins: koWins, timeoutWins: toWins,
      effStats: sline,
    };
  }

  try {
    window.Arena = {
      matchup:         arenaMatchup,
      state:           getAscentState,
      livesLeft:       ascentLivesLeft,
      floorInfo:       ascentFloorInfo,
      bands:           () => ASCENT_BANDS.slice(),
      bosses:          () => ASCENT_BOSSES,
      titles:          () => ARENA_TITLES.slice(),
      unlockedTitles:  arenaUnlockedTitles,
      getTitle:        getEquippedArenaTitle,
      setTitle:        setEquippedArenaTitle,
      _statline:       _arenaPlayerStatline,   // debug
      selfTest:        _arenaSelfTest,         // W232 dev hook
      simAscent:       _arenaSimAscent,        // W291 balance-verification sim (max build vs floor N)
      _battle:         { start: arenaStartBattle, turn: arenaTakeTurn, finalize: arenaFinalizeBattle },
    };
  } catch (_) {}

  // ───────────────────────────────────────────────────────────────
  // THE ASCENT — Layer B: tower UI controller. Renders the tower view
  // (sticky header + bands + floor cards) into #arena-body, runs the
  // best-of-3 reveal, and shows the rating result. Presentation only —
  // every outcome + all state come from window.Arena (engine). The
  // persistent shell EXIT pill (#arena-close, W208) acts as Back: returns to
  // the tower from any sub-screen (W224), and only leaves the Arena from there.
  // ───────────────────────────────────────────────────────────────
  const _ASC_DISP = 10;   // display scale (engine power is raw; UI shows ×10)
  let _arView    = 'tower';
  let _arMatchup = null;
  let _arFight   = null;
  let _arTimers  = [];
  let _arReveal  = 0;
  let _arRevealing = false;   // W215 — true while the cinematic reveal driver is running (double-fire guard)
  let _arFlawless  = false;   // W216 — true when this fight is a ≥2× clean-sweep stomp (one-hit KO reveal)
  let _arSess      = null;    // W229 — interactive fight session (pick-a-move per round)

  function _arClearTimers() { _arTimers.forEach(t => { try { clearTimeout(t); } catch (_) {} }); _arTimers = []; }
  function _arAfter(ms, fn) { const id = setTimeout(fn, ms); _arTimers.push(id); return id; }
  function _arReduceMotion() {
    try { return !!(window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches); } catch (_) { return false; }
  }
  // W215 — portrait hook. Returns an <img> when a portrait asset exists for
  // this foe, else the silhouette. Midjourney NPC art is drop-in later:
  // bosses use their own file; regular floors look for assets/arena/<archKey>.png.
  // (No art ships in W215 — silhouettes remain until files + sw.js precache land.)
  function _arFoeArt(foe, big) {
    const cls = 'ar-foe-art' + (big ? ' big' : '');
    if (foe && foe.isBoss && foe.floor === 100) {
      const faPose = foe._faPhase === 2 ? 'first-awakened-unbound' : 'first-awakened-idle';   // W538 — Unbound portrait once he sheds the mask
      return '<img src="assets/coach/' + faPose + '.png" alt="" class="' + cls + ' fa">';
    }
    // W251 — generated NPC art. Milestone bosses get unique portraits
    // (boss_<floor>.webp, drop-in as they land); the 90 procedural floors
    // share their archetype's sprite (foe_<archKey>.webp — 6 cover all).
    // Absent file → graceful silhouette swap via onerror, logged honestly
    // (the W249 lesson: degradation must never silently mask a path bug).
    const art = (foe && foe.isBoss && foe.floor) ? 'boss_' + foe.floor
              : (foe && foe.archKey) ? 'foe_' + foe.archKey : null;
    if (art) {
      return '<img src="assets/arena/' + art + '.webp" alt="" class="' + cls + '" onerror="window.__arFoeArtFail(this)">';
    }
    return '<div class="ar-foe-sil-wrap' + (big ? ' big' : '') + '">' + _arFoeSil() + '</div>';
  }
  // onerror fallback for missing NPC art — swap to the silhouette, warn once per file.
  const _arArtWarned = {};
  window.__arFoeArtFail = function (img) {
    try {
      const file = (img.src || '').split('/').pop();
      if (!_arArtWarned[file]) { _arArtWarned[file] = 1; try { console.warn('[arena-art] missing: ' + file + ' — silhouette fallback'); } catch (_) {} }
      const wrap = document.createElement('div');
      wrap.className = 'ar-foe-sil-wrap' + ((img.className || '').indexOf('big') !== -1 ? ' big' : '');
      wrap.innerHTML = _arFoeSil();
      img.replaceWith(wrap);
    } catch (_) {}
  };
  function _arBody() { return document.getElementById('arena-body'); }
  function _arSet(html) { const b = _arBody(); if (b) b.innerHTML = html; }
  function _arBodyMode(tower) { const b = _arBody(); if (b) b.classList.toggle('ar-body--bleed', !!tower); }
  function _arD(n) { return Math.round((Number(n) || 0) * _ASC_DISP); }
  function _arFoeSil() {
    return '<svg viewBox="0 0 64 86" fill="none" aria-hidden="true">' +
      '<path d="M32 6c-8 0-13 6-13 15 0 5 2 9 5 12-6 3-12 9-13 20-1 9 0 21 0 21h42s1-12 0-21c-1-11-7-17-13-20 3-3 5-7 5-12 0-9-5-15-13-15z" fill="#1a1d28" stroke="#3a3f4d" stroke-width="1.4"/>' +
      '<path d="M24 22c0-6 3-10 8-10s8 4 8 10" stroke="#7e8597" stroke-width="1.2" opacity="0.6"/></svg>';
  }
  function _ascOdds(you, foe) {
    if (you <= 0) return 1;
    const p = 1 / (1 + Math.pow(Math.max(1, foe) / Math.max(1, you), 2.5));
    return Math.max(1, Math.min(99, Math.round(p * p * (3 - 2 * p) * 100)));
  }
  // W260 — the wire band: a 48–52% prediction reads DEAD EVEN to a human.
  // Framing only; the engine never sees it.
  function _arWireBand(odds) { return odds >= 48 && odds <= 52; }
  function _ascDiff(you, foe) {
    const r = you / Math.max(1, foe);
    if (r >= 1.12) return { key: 'FAVORED', cls: 'favored' };
    if (r >= 0.90) return { key: 'EVEN',    cls: 'even' };
    return { key: 'TOUGH', cls: 'tough' };
  }
  function _ascPlayerPower() { try { return _arenaCombatProfile(_arenaPlayerStatline()).power; } catch (_) { return 0; } }

  // ── W268 — The Ascent: opening challenge + home climb tracker
  // (ClaudeDesign 'Ascent Opening & Climb Tracker'). The 100-floor climb is the
  // game's stated objective; these two surfaces make it 'a big deal from the
  // beginning'. CSS-only tower silhouette (stacked segments, fills bottom-up).
  function _aoTowerHtml(pct, w, h, litColor, beacon) {
    const segs = 14, gap = 3, segH = (h / segs) - gap;
    const litCount = Math.round(pct * segs);
    let html = '<span class="ao-tower" style="position:relative;width:' + w + 'px;height:' + h + 'px;display:flex;flex-direction:column;justify-content:flex-end;align-items:center">';
    if (beacon) html += '<span class="ao-beacon" style="position:absolute;top:-2px;left:50%;transform:translateX(-50%);width:14px;height:14px;border-radius:50%;background:radial-gradient(circle,#ffe9b0,#f5b842 50%,transparent 75%);box-shadow:0 0 16px #f5b842"></span>';
    for (let i = 0; i < segs; i++) {
      const fromTop = segs - 1 - i, taper = 1 - (i / segs) * 0.42, isLit = fromTop < litCount, isCrown = i === 0;
      const bg = isLit ? 'linear-gradient(180deg,' + litColor + ',#c08418)' : 'rgba(255,255,255,0.045)';
      const bd = isLit ? 'rgba(245,184,66,0.5)' : 'rgba(255,255,255,0.08)';
      const sh = isLit ? '0 0 10px ' + litColor + '44' : 'none';
      const crownR = isCrown ? 'border-top-left-radius:5px;border-top-right-radius:5px;' : '';
      html += '<span style="width:' + (w * taper).toFixed(1) + 'px;height:' + segH.toFixed(1) + 'px;margin-bottom:' + gap + 'px;border-radius:2px;background:' + bg + ';border:1px solid ' + bd + ';box-shadow:' + sh + ';position:relative;' + crownR + '">';
      if (isCrown) {
        const nC = isLit ? litColor : 'rgba(255,255,255,0.12)';
        html += '<span style="position:absolute;top:-4px;left:0;right:0;height:4px;display:flex;justify-content:space-between;padding:0 3px">' +
          '<i style="width:4px;height:4px;background:' + nC + '"></i><i style="width:4px;height:4px;background:' + nC + '"></i><i style="width:4px;height:4px;background:' + nC + '"></i></span>';
      }
      html += '</span>';
    }
    html += '<span style="width:' + (w + 6) + 'px;height:5px;border-radius:2px;background:rgba(255,255,255,0.06);border:1px solid rgba(255,255,255,0.08)"></span></span>';
    return html;
  }
  // Home tracker strip — reads live ascent state; FLOOR N / 100 + band, tower
  // lights bottom-up. Rendered INSIDE button#sc-arena-btn so the existing
  // delegated open-arena handler is preserved unchanged.
  function _scClimbStripHtml() {
    let floor = 1, done = 0;
    try { const stx = getAscentState(); floor = Math.max(1, Math.min(100, stx.currentFloor || 1)); done = stx.highestCleared || 0; } catch (_) {}
    const finished = done >= 100;
    const dispFloor = finished ? 100 : floor;
    let bandName = ''; try { bandName = _ascentBandFor(dispFloor).name; } catch (_) {}
    if (finished) bandName = 'The Tower is Yours';
    const summit = finished || dispFloor >= 91;
    const litColor = (dispFloor >= 40 || summit) ? '#f5b842' : '#c8c6d8';
    return _aoTowerHtml(dispFloor / 100, 30, 92, litColor, summit) +
      '<span class="sc-climb-mid">' +
        '<span class="sc-climb-eyebrow">THE ASCENT</span>' +
        '<span class="sc-climb-floor"><b>' + dispFloor + '</b><span class="of">/ 100</span><span class="lbl">FLOORS</span></span>' +
        '<span class="sc-climb-band' + (summit ? ' summit' : '') + '">' + esc(bandName) + '</span>' +
      '</span>' +
      '<span class="sc-climb-right">' +
        '<span class="sc-climb-cta' + (summit ? ' summit' : '') + '">' + (summit ? 'SUMMIT' : 'CLIMB') + '</span>' +
        '<svg width="9" height="13" viewBox="0 0 8 12" aria-hidden="true"><path d="M1.5 1l5 5-5 5" stroke="#f5b842" stroke-width="1.6" fill="none" stroke-linecap="round" stroke-linejoin="round"/></svg>' +
      '</span>';
  }

  // W496 — ClaudeDesign "Merged Ascent + PvP Button" (Direction D). The owner
  // disliked the two stacked home buttons (the big Ascent banner + the W488 PvP
  // row), so this fuses them into ONE "THE ARENA" umbrella card with two
  // independently-tappable inset tiles: a gold ASCENT tile (climb) + a teal
  // RANKED PVP tile (duel). Reuses the existing #sc-arena-btn / #sc-pvp-btn ids,
  // so the delegated openArena / openArenaPvP handlers are unchanged — a tap on
  // either tile bubbles to closest('#…'). The tower stays floor-accurate via
  // _aoTowerHtml (the static mock hardcoded 7 lit segments; we read live state).
  function _scArenaMergedHtml() {
    let floor = 1, done = 0;
    try { const stx = getAscentState(); floor = Math.max(1, Math.min(100, stx.currentFloor || 1)); done = stx.highestCleared || 0; } catch (_) {}
    const finished = done >= 100;
    const dispFloor = finished ? 100 : floor;
    const summit = finished || dispFloor >= 91;
    const litColor = (dispFloor >= 40 || summit) ? '#f5b842' : '#c8c6d8';
    const climbCta = summit ? 'SUMMIT' : 'CLIMB';
    const chev = function (stroke) {
      return '<svg class="sc-am-chev" width="9" height="13" viewBox="0 0 8 12" aria-hidden="true"><path d="M1.5 1l5 5-5 5" stroke="' + stroke + '" stroke-width="1.6" fill="none" stroke-linecap="round" stroke-linejoin="round"/></svg>';
    };
    // Crossed-swords glyph (ported 1:1 from the mock's <Swords/>).
    const swords = '<svg class="sc-am-swords" width="30" height="30" viewBox="0 0 30 30" aria-hidden="true">' +
        '<g stroke="#cfd3e6" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" fill="none">' +
          '<path d="M6 6 L20 20"/><path d="M24 6 L10 20"/><path d="M4 22 L8 18"/><path d="M6 24 L10 20"/><path d="M26 22 L22 18"/><path d="M24 24 L20 20"/>' +
        '</g>' +
        '<g stroke="#cfd3e6" stroke-width="2.4" stroke-linecap="round"><path d="M5 21 L9 25"/><path d="M25 21 L21 25"/></g>' +
      '</svg>';
    const climbTile =
      '<button class="sc-am-tile sc-am-tile--climb" id="sc-arena-btn" type="button" aria-label="The Ascent - climb the tower">' +
        '<span class="sc-am-tile-top">' +
          '<span class="sc-am-tower">' + _aoTowerHtml(dispFloor / 100, 24, 44, litColor, summit) + '</span>' +
          '<span class="sc-am-tx">' +
            '<span class="sc-am-kick sc-am-kick--gold">The Ascent</span>' +
            '<span class="sc-am-floor"><b>' + dispFloor + '</b><span class="of">/100</span></span>' +
          '</span>' +
        '</span>' +
        '<span class="sc-am-foot"><span class="sc-am-cta sc-am-cta--gold">' + climbCta + '</span>' + chev('#f5b842') + '</span>' +
      '</button>';
    // W795 — while the ranked queue is sealed the tile stays visible (a tease, not a
    // hole in the layout) but reads LOCKED; the tap explains + points at the Ascent.
    const _pvpLocked = (typeof PVP_RANKED_LOCKED !== 'undefined') && PVP_RANKED_LOCKED;
    const lockGlyph = '<svg class="sc-am-lock" width="11" height="11" viewBox="0 0 24 24" fill="none" stroke="#8a8aa6" stroke-width="2.4" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><rect x="4" y="11" width="16" height="10" rx="2"/><path d="M8 11V7a4 4 0 0 1 8 0v4"/></svg>';
    const duelTile = PVP_ENABLED ?
      '<button class="sc-am-tile sc-am-tile--duel' + (_pvpLocked ? ' sc-am-tile--locked' : '') + '" id="sc-pvp-btn" type="button" aria-label="' + (_pvpLocked ? 'Ranked PvP - locked until more hunters join. Climb the Ascent meanwhile.' : 'Ranked PvP - duel another hunter') + '">' +
        '<span class="sc-am-tile-top">' +
          swords +
          '<span class="sc-am-tx">' +
            '<span class="sc-am-kick sc-am-kick--teal">Ranked PvP</span>' +
            '<span class="sc-am-duel">Duel</span>' +
          '</span>' +
        '</span>' +
        (_pvpLocked
          ? '<span class="sc-am-foot"><span class="sc-am-cta sc-am-cta--locked">' + lockGlyph + 'SEALED</span></span>'
          : '<span class="sc-am-foot"><span class="sc-am-cta sc-am-cta--teal">FIGHT</span>' + chev('#5eead4') + '</span>') +
      '</button>' : '';
    return '<div class="sc-arena-merged' + (PVP_ENABLED ? '' : ' sc-arena-merged--solo') + '">' +
        '<div class="sc-am-head">' +
          '<span class="sc-am-rule sc-am-rule--l" aria-hidden="true"></span>' +
          '<span class="sc-am-word">THE ARENA</span>' +
          '<span class="sc-am-rule sc-am-rule--r" aria-hidden="true"></span>' +
        '</div>' +
        '<div class="sc-am-tiles">' + climbTile + duelTile + '</div>' +
        // W522 — habit→power thread, home-screen end. The stat radar (discipline) sits
        // right above this card; this quiet line connects it to the combat below, so the
        // OSRS "habits are the engine" loop is legible at the entry point (the tappable
        // POWER breakdown inside the Ascent, W518, is the full explainer).
        '<div class="sc-am-thread"><span class="sc-am-thread-i" aria-hidden="true">✦</span> Powered by your <b>stats</b> + <b>relics</b> — earned through your vows</div>' +
      '</div>';
  }
  // Opening challenge overlay — the First Awakened issues the challenge and the
  // objective is declared (100 / 1 / 1). Shown ONCE (hb_ascent_opening_seen_v1),
  // fired from openArena() on first Arena entry (W295 — relocated off the post-
  // splash path so it can't fire mid-onboarding before the hunter is named).
  function _aoOpeningHtml() {
    return '<div class="ao-opening" id="ao-opening">' +
      '<div class="ao-open-portrait" aria-hidden="true">' +
        '<img src="assets/coach/first-awakened-idle.png" alt="">' +
        '<span class="ao-ember" style="top:30%;left:24%"></span>' +
        '<span class="ao-ember" style="top:44%;right:28%;animation-delay:1.4s"></span>' +
        '<span class="ao-open-scrim"></span>' +
      '</div>' +
      '<div class="ao-open-body">' +
        '<div class="ao-open-kicker">THE ASCENT</div>' +
        '<div class="ao-open-spacer"></div>' +
        '<div class="ao-open-line ao-rise"><span class="q">“I was the first to climb.<br>No one has reached me since.”</span>' +
          '<span class="by">— THE FIRST AWAKENED</span></div>' +
        '<div class="ao-open-obj">' +
          '<span class="cell"><b>100</b><i>FLOORS</i></span><span class="div"></span>' +
          '<span class="cell"><b>1</b><i>SUMMIT</i></span><span class="div"></span>' +
          '<span class="cell"><b>1</b><i>TO BEAT</i></span>' +
        '</div>' +
        '<button type="button" class="ao-open-cta ao-cta-glow" id="ao-begin-btn">BEGIN THE ASCENT ▸</button>' +
      '</div>' +
    '</div>';
  }
  function _aoMaybeShowOpening() {
    try {
      if (localStorage.getItem('hb_ascent_opening_seen_v1')) return;
      if (!localStorage.getItem('hb_onboarding_seen_v2')) return;
      if (document.getElementById('ao-opening')) return;
      const wrap = document.createElement('div');
      wrap.innerHTML = _aoOpeningHtml();
      const el = wrap.firstChild;
      document.body.appendChild(el);
      const dismiss = (openAfter) => {
        try { localStorage.setItem('hb_ascent_opening_seen_v1', '1'); } catch (_) {}
        el.classList.add('is-hiding');
        setTimeout(() => { try { el.remove(); } catch (_) {} if (openAfter) { try { if (typeof openArena === 'function') openArena(); } catch (_) {} } }, 420);
      };
      const btn = el.querySelector('#ao-begin-btn');
      if (btn) btn.addEventListener('click', () => dismiss(false));
    } catch (_) {}
  }
  function _ascDiffHtml(you, foe) {
    const d = _ascDiff(you, foe), o = _ascOdds(you, foe);
    return '<span class="asc-diff"><span class="pill ' + d.cls + '"><span class="d"></span>' + d.key + '</span>' +
      '<span class="odds">≈ <b>' + o + '%</b> WIN</span></span>';
  }
  function _ascFaceoffHtml(you, foe) {
    return '<div class="asc-faceoff">' +
      '<div class="side"><div class="v you">' + _arD(you) + '</div><div class="l">YOUR POWER</div></div>' +
      '<div class="vs">vs</div>' +
      '<div class="side"><div class="v foe">' + _arD(foe) + '</div><div class="l">FLOOR POWER</div></div></div>';
  }
  function _ascStar() {
    return '<svg width="16" height="16" viewBox="0 0 20 20" aria-hidden="true"><path d="M10 1.5l2.4 5 5.4.6-4 3.7 1.1 5.3L10 18.4 5.1 16l1.1-5.3-4-3.7 5.4-.6z" fill="none" stroke="currentColor" stroke-width="1.2" stroke-linejoin="round"/></svg>';
  }
  function _ascArchHtml(arch) { return '<span class="asc-arch">' + esc((arch || '').toUpperCase()) + '</span>'; }
  function _ascHeartHtml(on) {
    return '<span class="asc-heart' + (on ? ' on' : '') + '"><svg width="14" height="13" viewBox="0 0 14 13" aria-hidden="true"><path fill="currentColor" d="M7 12.2S0.8 8.1 0.8 4.2A3.2 3.2 0 017 2.5 3.2 3.2 0 0113.2 4.2C13.2 8.1 7 12.2 7 12.2z"/></svg></span>';
  }

  // ── tower header ──────────────────────────────────────────────────
  // W265 — Ledger header (ClaudeDesign "Ascent Ladder Remodel", direction A,
  // Richie's pick). One row of identity (wordmark + tappable equipped-title
  // chip), one row of numbers (rating · tier | lives). Replaces the W259
  // header strip; the title chip keeps the W259 data-ar="titles" entry point.
  function _ascHeaderHtml(st) {
    // W620 — members show a gold ∞ tag instead of the depleting 2-heart row
    // (W651: Founder lifetime OR active Premium — both tiers of the membership).
    const _founder = _ascentIsMember();
    const left = _founder ? Infinity : Math.max(0, ASCENT_DAILY_LIVES - st.dailyLosses);
    let hearts = '';
    for (let i = 0; i < ASCENT_DAILY_LIVES; i++) hearts += _ascHeartHtml(_founder || i < left);
    let eqTitle = null; try { const t = getEquippedArenaTitle(); eqTitle = t && t.name; } catch (_) {}
    // W272 — the left corner shows POWER (the climb's real progression metric)
    // instead of arena RATING. Rating still runs under the hood (it drives the
    // milestone titles in the chip above + the post-fight delta), it's just no
    // longer the headline number — one less competing ranking on screen.
    let pwr = 0; try { pwr = _arD(_ascPlayerPower()); } catch (_) {}
    return '<div class="al-head">' +
      '<div class="al-head-row"><span class="al-wordmark">THE ASCENT</span>' +
        '<button class="al-title-chip" data-ar="titles" type="button">' +
          (eqTitle ? '“' + esc(eqTitle) + '”' : 'TITLES') +
          '<svg width="7" height="9" viewBox="0 0 8 12" aria-hidden="true"><path d="M1.5 1l5 5-5 5" stroke="#9090a8" stroke-width="1.6" fill="none" stroke-linecap="round" stroke-linejoin="round"/></svg>' +
        '</button></div>' +
      '<div class="al-head-nums">' +
        '<div class="al-power" data-ar="powerinfo" role="button" tabindex="0" aria-label="What makes up your power — tap for the breakdown">' +
          '<span class="al-lbl">POWER <span class="al-power-i" aria-hidden="true">&#9432;</span></span>' +
          '<span class="al-rating-row"><span class="num">' + pwr.toLocaleString('en-US') + '</span></span></div>' +
        '<div class="al-lives' + (_founder ? ' al-lives--founder' : '') + '"><span class="al-lbl">LIVES' +
          // W652 — tier-aware tag: a Premium subscriber is not a FOUNDER.
          (_founder ? ' <span class="al-founder-tag">✦ PREMIUM</span>' : '') + '</span>' +
          '<span class="al-lives-row">' + hearts + '<span class="n">' +
            (_founder ? '∞' : left + '/' + ASCENT_DAILY_LIVES) + '</span>' +
            '<button class="al-tips" data-ar="tips" type="button" aria-label="Combat styles">?</button></span></div>' +
      '</div></div>';
  }

  // ── W518: habit→power thread (legibility keystone) ────────────────────
  // The Ascent header's POWER number is the END of the chain
  //   vows → stats + relics → power → the climb.
  // Tapping it opens this breakdown so a hunter SEES that their climb power is
  // forged from their discipline. Numbers are EXACT + additive: power is a
  // linear weighted stat sum (_arenaCombatProfile: STR×2.3 + (INT+VIT)×1.15 +
  // (FOCUS+WILL)×1.15) and each stat = level(earned from vows) + gear(relics),
  // so profile(base+gear) = profile(base) + profile(gear). We derive
  // relics = total − stats so the two ALWAYS sum to the headline number.
  function _arOpenPowerBreakdown() {
    let totalDisp = 0, statsDisp = 0, relicsDisp = 0;
    try {
      const base = {};
      STATS.forEach(st => { base[st.id] = statLevel((stats[st.id] && stats[st.id].pts) || 0); });
      totalDisp  = _arD(_arenaCombatProfile(_arenaPlayerStatline()).power);
      statsDisp  = _arD(_arenaCombatProfile(base).power);
      relicsDisp = Math.max(0, totalDisp - statsDisp);
    } catch (_) {}
    const n = (x) => (Number(x) || 0).toLocaleString('en-US');
    const bodyHtml =
      '<div class="pwr-bd">' +
        '<div class="pwr-bd-row"><span class="pwr-bd-n">' + n(statsDisp) + '</span>' +
          '<span class="pwr-bd-l"><b>Stats</b> — raised every time you complete a vow</span></div>' +
        '<div class="pwr-bd-row"><span class="pwr-bd-n">' + n(relicsDisp) + '</span>' +
          '<span class="pwr-bd-l"><b>Relics</b> — gear bought with souls you earn from vows</span></div>' +
        '<div class="pwr-bd-foot">Keep your vows. Stronger stats and better relics carry you higher.</div>' +
      '</div>';
    try { showNoticeCard({ title: 'YOUR POWER · ' + n(totalDisp), bodyHtml: bodyHtml, cta: 'Onward' }); } catch (_) {}
  }

  // ── floor cards ──  // ── the ledger (W265) ────────────────────────────────────────────
  // W260 — post-50 telegraph: the foe's full kit, now one tap deep behind the
  // hero card's class line (ClaudeDesign: "the known-moves chips live one tap
  // deep rather than always-on"). Same truth source as the fight itself.
  function _ascScoutHtml(info) {
    const tier = aiTierFor(info.floor);
    if (tier <= 2) return '';
    let names = [];
    try { names = _arenaFoeKit(info.opponent.archKey, info.floor).map((mv) => mv.name || mv.id); } catch (_) {}
    if (!names.length) return '';
    return '<div class="asc-scout"><span class="k">⚠ ' + AI_TIER_NAMES[tier] + '-CLASS FOE · KNOWN MOVES</span>' +
      '<div class="mv">' + names.map((n) => '<span>' + esc(n) + '</span>').join('') + '</div></div>';
  }
  // The foe's signature move — its highest-power option, the one the AI leans
  // on. Deterministic and human-knowable (fair-play charter: nothing the fight
  // wouldn't show you).
  function _ascFavoredMove(info) {
    let best = null;
    try {
      _arenaFoeKit(info.opponent.archKey, info.floor).forEach((mv) => {
        if ((mv.power || 0) > 0 && (!best || mv.power > best.power)) best = mv;
      });
    } catch (_) {}
    return best ? (best.name || best.id) : null;
  }
  // One italic read line: difficulty phrase + the foe's favored move + ≈odds.
  // Replaces the diff pill + odds row + faceoff power columns of the old card.
  function _ascReadLine(info) {
    const you = _ascPlayerPower(), foe = info.opponent.power;
    const o = _ascOdds(you, foe);
    const r = you / Math.max(1, foe);
    const phrase = _arWireBand(o) ? 'Dead even'
      : r >= 1.12 ? 'A favored read'
      : r >= 0.90 ? 'An even read'
      : 'A tough read';
    const name = info.opponent.name || '';
    const last = /^The\s/.test(name) ? 'the ' + name.split(' ').pop() : 'they';
    const verb = last === 'they' ? 'favor' : 'favors';
    const mv = _ascFavoredMove(info);
    return '<div class="al-hero-intel"><span class="read">' + esc(phrase) + ' — ' + esc(last) + ' ' + verb +
      (mv ? ' <b>' + esc(mv) + '</b>.' : ' a direct assault.') + '</span>' +
      '<span class="odds">≈' + o + '%</span></div>';
  }
  // The hero — the next fight, the only card on screen.
  function _ascHeroHtml(info, left) {
    const isBoss = !!info.isBoss, apex = info.floor === 100;
    const kick = isBoss ? (apex ? 'THE SUMMIT · FINAL BOSS' : 'FLOOR ' + info.floor + ' · MILESTONE BOSS')
                        : 'FLOOR ' + info.floor + ' · NEXT FIGHT';
    const tier = aiTierFor(info.floor);
    const archL = ((ASCENT_ARCHETYPES[info.opponent.archKey] || {}).label || info.opponent.archetype || '').toUpperCase();
    const scout = _ascScoutHtml(info);
    const tg = archL + (tier > 2 ? ' · ' + AI_TIER_NAMES[tier] + '-CLASS' : '');
    const img = apex ? '<img src="assets/coach/first-awakened-idle.png" alt="" class="asc-fa-img">'
      : isBoss ? '<img src="assets/arena/boss_' + info.floor + '.webp" alt="" class="asc-fa-img" onerror="window.__arFoeArtFail(this)">'
      : (info.opponent.archKey
          ? '<img src="assets/arena/foe_' + info.opponent.archKey + '.webp" alt="" class="asc-fa-img" onerror="window.__arFoeArtFail(this)">'
          : _arFoeSil());
    const reward = '';   // W266 — boss titles retired; the rating ladder is the only title source
    // W620 — membership benefit line under the CTA (members never reach the locked
    // branch: left = Infinity via ascentLivesLeft). W651: label follows the tier.
    const founderNote = _ascentIsMember()
      ? '<div class="al-founder-note">✦ ' +
        'PREMIUM' +
        ' BENEFIT · UNLIMITED ASCENT ATTEMPTS</div>'
      : '';
    const cta = (left > 0
      ? '<button class="al-fight" data-ar="fight" data-floor="' + info.floor + '" type="button">FIGHT ▸</button>'
      : '<div class="al-fight al-fight--locked">OUT OF LIVES<span>rated climb resumes tomorrow · fallen foes stay open</span></div>') + founderNote;
    return '<div class="al-hero' + (isBoss ? ' al-hero--boss' : '') + '" id="asc-current-card">' +
      '<div class="al-hero-top"><div class="al-hero-id">' +
        '<span class="kick">' + kick + '</span>' +
        '<span class="nm">' + esc(info.opponent.name) + '</span>' +
        (scout
          ? '<button class="al-hero-tg tap" data-ar="alscout" type="button">' + esc(tg) + ' ▾</button>'
          : '<span class="al-hero-tg">' + esc(tg) + '</span>') +
      '</div><div class="al-hero-med">' + img + '</div></div>' +
      (scout ? '<div id="al-scout-slot" style="display:none">' + scout + '</div>' : '') +
      reward +
      '<div class="al-hero-rule"></div>' + _ascReadLine(info) + cta +
    '</div>';
  }
  function _ascLedgerRule(band, right) {
    return '<div class="al-rule"><span class="lbl">' + esc(band.name).toUpperCase() + '</span><span class="line"></span>' +
      '<span class="right">' + right + '</span></div>';
  }
  // One fallen foe, one line. The whole row is the rematch target — the ↻
  // glyph is a hint, not a button (W240 exhibitions: free, unrated).
  function _ascLedgerRowHtml(info) {
    const boss = !!info.isBoss;
    const mark = boss
      ? '<span class="al-dia"></span>'
      : '<svg width="13" height="13" viewBox="0 0 14 14" aria-hidden="true"><path d="M3 7.3l2.6 2.6L11 4.4" stroke="#6b6b86" stroke-width="1.5" fill="none" stroke-linecap="round" stroke-linejoin="round"/></svg>';
    const title = '';   // W266 — boss titles retired (the gold diamond row remains)
    // W439 — a tiny gold "+N" on floors that still pay a Reclaim bounty today (nothing once
    // claimed or the daily cap is hit, so the list stays uncluttered).
    const st = getAscentState();
    const payable = st.reclaimFloors.indexOf(info.floor) === -1 && st.reclaimSouls < ASCENT_RECLAIM_DAILY_CAP;
    const bounty = payable ? '<span class="al-bounty">+' + _ascentReclaimBounty(info.floor) + '</span>' : '';
    return '<div class="al-row' + (boss ? ' al-row--milestone' : '') + '" data-ar="rematch" data-floor="' + info.floor + '">' +
      mark + '<span class="fl">' + info.floor + '</span>' +
      '<span class="nm">' + esc(info.opponent.name) + '</span>' + title + bounty +
      '<svg class="al-redo" width="12" height="12" viewBox="0 0 14 14" aria-hidden="true"><path d="M11.5 7a4.5 4.5 0 1 1-1.4-3.2M11.5 1.8v2.4H9.1" stroke="#6b6b86" stroke-width="1.3" fill="none" stroke-linecap="round" stroke-linejoin="round"/></svg></div>';
  }

  // ── tower view ────────────────────────────────────────────────────  // ── tower view ────────────────────────────────────────────────────
  // W265 — the Ledger (ClaudeDesign direction A): the next fight is the only
  // card on screen; history collapses to one-line entries grouped by band,
  // newest first. Locked floors and power columns are gone — the hero card's
  // read line carries the difficulty story. All flows reuse the existing
  // data-ar handlers (fight / rematch / titles).
  function _arRenderTower() {
    _arView = 'tower';
    _arClearTimers();
    _arRevealing = false;
    _arSess = null;
    try { _audWantMusic('arena_menu'); } catch (_) {}   // W248 — lofi menu loop (no-op if already playing)
    _arBodyMode(true);
    const st = getAscentState();
    const left = ascentLivesLeft();   // W620 — founder-aware (Infinity → the hero CTA never locks)
    const summitDone = st.highestCleared >= ASCENT_FLOORS;
    const cur = Math.min(st.currentFloor, ASCENT_FLOORS);
    const hero = summitDone
      ? '<div class="al-hero al-hero--done"><span class="kick">THE SUMMIT</span>' +
        '<span class="nm">The tower is climbed.</span>' +
        '<div class="al-hero-rule"></div>' +
        '<div class="al-hero-intel"><span class="read">Every floor has fallen. The ledger below is yours.</span></div>' +
        '<button type="button" class="al-fight" data-ar="hall" style="margin-top:14px">ENTER THE HALL ▸</button></div>'   // W269 — revisit the Hall of the Awakened
      : _ascHeroHtml(ascentFloorInfo(cur), left);
    let ledger = '';
    const curBandIdx = ASCENT_BANDS.indexOf(_ascentBandFor(cur));
    for (let bi = curBandIdx; bi >= 0; bi--) {
      const b = ASCENT_BANDS[bi];
      const hiF = Math.min(b.to, st.highestCleared);
      const total = b.to - b.from + 1;
      const done = Math.max(0, hiF - b.from + 1);
      const right = done >= total ? 'COMPLETE' : done + ' OF ' + total;
      ledger += _ascLedgerRule(b, right);
      for (let f = hiF; f >= b.from; f--) ledger += _ascLedgerRowHtml(ascentFloorInfo(f));
    }
    const hint = st.highestCleared >= 1
      ? '<div class="al-hint">TAP A FALLEN FOE TO REMATCH</div>'
      : '';
    // W513 — the in-tower "Enter the Arena" PvP banner was removed (owner: redundant with the
    // Status card's RANKED PVP / DUEL tile, the single PvP entry point now). _pvpTowerEntryHtml is
    // left defined but no longer rendered here.
    _arSet(_ascHeaderHtml(st) + '<div class="asc-scroll al-scroll">' + hero + ledger + hint + '</div>');
    // W424 — populate the Arena Entry banner's standing on first tower view (cached after).
    try { if (PVP_ENABLED && !_pvpRating && window.PvP && PvP.rating) _pvpFetchRating(); } catch (_) {}
  }

  // ── fight reveal ──────────────────────────────────────────────────  // ── fight reveal ──────────────────────────────────────────────────
  function _arNarr(round) {
    const hi = round.margin > 0.28;
    if (round.playerWon) {
      if (round.pCrit) return '<b>CRITICAL</b> — you shatter their guard.';
      if (round.bMiss) return 'They swing wide — you punish the opening.';
      return hi ? 'You break their guard — a decisive strike.'
                : 'You edge the exchange, <b>' + round.pRoll + '</b> to ' + round.bRoll + '.';
    }
    if (round.bCrit) return '<b>CRITICAL</b> — they shatter your guard.';
    if (round.pMiss) return 'Your strike whiffs — they capitalize.';
    return hi ? 'They overwhelm you — <b>' + round.bRoll + '</b> lands hard.'
              : 'They scrape the round, ' + round.bRoll + ' to ' + round.pRoll + '.';
  }
  // ── cinematic helpers (W215) ──────────────────────────────────────
  // ── W222 fill modules (presentation only — real engine state) ─────
  // Tale of the Tape: role-by-role you-vs-foe (ATTACK/DEFENSE/EDGE), ×10
  // display, tap a row to expand your stat + relic breakdown + the matchup.
  function _ascTaleHtml(m) {
    const P = m.player, F = m.bot;
    let gear = {}; try { gear = (_aggregateBuildBonuses() || {}).totals || {}; } catch (_) {}
    const lvl = (id) => { try { return statLevel((stats[id] && stats[id].pts) || 0); } catch (_) { return 1; } };
    const playerArch = _arenaArchOf(P), foeArch = F.archKey || _arenaArchOf(F);
    const eff = _arenaEffectiveness(playerArch, foeArch);
    const foeLabel = (ASCENT_ARCHETYPES[foeArch] || {}).label || 'Foe';
    const roles = [
      { key: 'ATTACK',  label: 'ATTACK · Melee',   pv: P.attack,  fv: F.attack,  parts: [['STR', 2.3]] },
      { key: 'DEFENSE', label: 'DEFENSE · Magic',  pv: P.defense, fv: F.defense, parts: [['INT', 1.15], ['VIT', 1.15]] },
      { key: 'EDGE',    label: 'EDGE · Ranged',    pv: P.edge,    fv: F.edge,    parts: [['FOCUS', 1.15], ['WILL', 1.15]] },
    ];
    let rows = '';
    roles.forEach((r) => {
      const pv = _arD(r.pv), fv = _arD(r.fv), max = Math.max(pv, fv, 1);
      const youLead = pv >= fv;
      // Per-stat contribution to the role value: (level + gear) × weight × 10.
      // These sum EXACTLY to pv — the point is to show HOW the breakdown reaches
      // the total (STR→608 + FOCUS→260 = 868), which the old "Lv 8 · Lv 8 · +48
      // relic" line could not.
      const partHtml = r.parts.map((p) => {
        const id = p[0], w = p[1], lv = lvl(id), g = Math.round(gear[id.toLowerCase()] || 0);
        const contrib = Math.round((lv + g) * w * _ASC_DISP);
        return '<span class="cp"><span class="s">' + id + '</span><span class="src">Lv ' + lv +
          (g > 0 ? ' <b class="rel">+' + g + '</b>' : '') + '</span><span class="ct">' + contrib + '</span></span>';
      }).join('');
      const detail = '<div class="asc-tale-calc">' + partHtml +
        '<span class="cp total"><span class="s">' + r.label + '</span><span class="src"></span>' +
        '<span class="ct">' + pv + '</span></span></div>' +
        '<div class="asc-tale-note">' + (youLead ? 'You lead this exchange.' : 'They lead this exchange.') + '</div>';
      rows += '<div class="asc-tale-row" data-ar="tale" data-role="' + r.key + '">' +
        '<div class="asc-tale-head">' +
          '<span class="pv' + (youLead ? ' lead' : '') + '">' + pv + '</span>' +
          '<span class="mid"><span class="rk">' + r.label + '<svg width="8" height="5" viewBox="0 0 8 5" class="chev"><path d="M1 1l3 3 3-3" stroke="currentColor" stroke-width="1.2" fill="none" stroke-linecap="round"/></svg></span>' +
            '<span class="asc-tale-bars"><span class="b you"><i style="width:' + Math.round(pv / max * 100) + '%"></i></span>' +
              '<span class="b foe"><i style="width:' + Math.round(fv / max * 100) + '%"></i></span></span></span>' +
          '<span class="fv' + (youLead ? '' : ' lead') + '">' + fv + '</span>' +
        '</div><div class="asc-tale-detail">' + detail + '</div></div>';
    });
    // W766 — the verdict tells BOTH truths: type matchup AND raw power. The old
    // neutral branch said "An even match" whenever no type advantage existed —
    // over a 4,255-vs-5,592 tape (F100, owner report) that read as a flat lie.
    // ±12% total-power gap = material; inside the band the tape genuinely is close.
    const pTot = (P.attack || 0) + (P.defense || 0) + (P.edge || 0);
    const fTot = (F.attack || 0) + (F.defense || 0) + (F.edge || 0);
    const gap = pTot > 0 ? (fTot - pTot) / pTot : 0;
    const powerClause = gap > 0.12
      ? ' They out-power you across the tape — every stat you close in the Armory counts.'
      : gap < -0.12
      ? ' And you out-power them across the tape.'
      : '';
    const typeLine = eff.key === 'super'
      ? (eff.tier === 'mild'
          ? 'Your style has the edge on the ' + esc(foeLabel) + ' — <b class="sup">' + esc(eff.label) + '</b>.'
          : 'Your style counters the ' + esc(foeLabel) + ' — <b class="sup">' + esc(eff.label) + '</b>.')
      : eff.key === 'weak'
      ? (eff.tier === 'mild'
          ? 'The ' + esc(foeLabel) + ' resists your style — <b class="wk">' + esc(eff.label) + '</b>.'
          : 'The ' + esc(foeLabel) + ' counters your style — <b class="wk">' + esc(eff.label) + '</b>.')
      : (powerClause
          ? 'No type advantage either way.'
          : 'A dead-even match — no type advantage either way.');
    const verdict = typeLine + powerClause;
    return '<div class="asc-fill"><div class="asc-fill-head"><span class="k">TALE OF THE TAPE</span><span class="a dim">TAP A ROW</span></div>' +
      '<div class="asc-tale">' + rows + '<div class="asc-tale-read">' + verdict + '</div></div></div>';
  }
  // Your Loadout: full 8-slot grid (ClaudeDesign "Loadout Module") — rarity gem
  // + primary bonus per cell, tap to expand full bonuses, a totals bar across
  // all gear, deep-links to the Armory modal. Read-only display.
  const _LDT_ACCENT = { common: '#c8c6d8', rare: '#5eead4', ultra_rare: '#a78bfa', 'ultra-rare': '#a78bfa', ultra: '#a78bfa' };
  const _LDT_RNAME  = { common: 'COMMON', rare: 'RARE', ultra_rare: 'ULTRA-RARE', 'ultra-rare': 'ULTRA-RARE', ultra: 'ULTRA-RARE' };
  function _ldtSlotLabels() {
    try { if (typeof EQUIPMENT_SLOTS !== 'undefined') return EQUIPMENT_SLOTS.map((s) => s.label); } catch (_) {}
    return ['HELM', 'AMULET', 'CAPE', 'WEAPON', 'ARMOR', 'GLOVES', 'BOOTS', 'RING'];
  }
  function _ldtCardAt(i) {
    try { let s = []; const b = getHunterBuild(); if (b && Array.isArray(b.slots)) s = b.slots;
      const id = s[i]; return (id && typeof CARDS !== 'undefined') ? CARDS[id] : null; } catch (_) { return null; }
  }
  function _ldtBonuses(card) {
    const b = (card && card.bonuses) || {};
    return Object.keys(b).filter((k) => (b[k] || 0) !== 0).map((k) => [k.toUpperCase(), b[k]]).sort((a, c) => c[1] - a[1]);
  }
  // expand strip for a tapped cell (full bonuses + rarity name)
  function _ascLoadExpHtml(i) {
    const card = _ldtCardAt(i);
    if (!card) return '';
    const col = _LDT_ACCENT[card.rarity] || '#c8c6d8';
    const pills = _ldtBonuses(card).map((p) => '<span class="pill" style="color:' + col + '">+' + p[1] + ' ' + esc(p[0]) + '</span>').join('');
    return '<span class="lgem" style="background:' + col + ';box-shadow:0 0 7px ' + col + '88"></span>' +
      '<div class="meta"><div class="t"><span class="nm">' + esc(card.name || 'Relic') + '</span>' +
      '<span class="rr" style="color:' + col + '">' + (_LDT_RNAME[card.rarity] || 'COMMON') + '</span></div>' +
      '<div class="sl">' + esc(_ldtSlotLabels()[i] || '') + '</div></div><div class="pills">' + pills + '</div>';
  }
  function _ascLoadoutHtml() {
    const labels = _ldtSlotLabels();
    let cells = '';
    for (let i = 0; i < labels.length; i++) {
      const card = _ldtCardAt(i);
      if (!card) {
        cells += '<div class="asc-load-cell empty"><span class="sl">' + esc(labels[i]) + '</span><span class="mt">＋ Empty</span></div>';
        continue;
      }
      const col = _LDT_ACCENT[card.rarity] || '#c8c6d8';
      const bl = _ldtBonuses(card), prim = bl[0] || ['', 0];
      cells += '<div class="asc-load-cell" data-ar="loadcell" data-slot="' + i + '">' +
        '<div class="top"><span class="ldt-gem" style="background:' + col + '"></span><span class="sl">' + esc(labels[i]) + '</span></div>' +
        '<div class="bn" style="color:' + col + '">+' + prim[1] + ' ' + esc(prim[0]) + (bl.length > 1 ? '<span class="pl"> +</span>' : '') + '</div>' +
        '<div class="nm">' + esc(card.name || 'Relic') + '</div></div>';
    }
    let totals = {}; try { totals = (_aggregateBuildBonuses() || {}).totals || {}; } catch (_) {}
    const tparts = ['str', 'vit', 'int', 'focus', 'will', 'wlt']
      .filter((k) => (totals[k] || 0) > 0).map((k) => '+' + Math.round(totals[k]) + ' ' + k.toUpperCase());
    const totalsHtml = tparts.length ? tparts.join('<span class="dot"> · </span>') : '—';
    return '<div class="asc-fill"><div class="asc-fill-head"><span class="k">YOUR LOADOUT</span>' +
      '<span class="a link" data-ar="armory">ADJUST IN ARMORY →</span></div>' +
      '<div class="asc-loadout-panel"><div class="asc-loadgrid">' + cells + '</div>' +
      '<div class="asc-load-exp" id="asc-load-exp"></div>' +
      '<div class="asc-load-totals"><span class="lbl">TOTAL GEAR BONUS</span><span class="v">' + totalsHtml + '</span></div></div></div>';
  }
  // On the Line — honest stakes (as-built: a boss loss costs rating + a life).
  function _ascStakesHtml(m) {
    const st = getAscentState();
    const boss = ASCENT_BOSSES[m.floor] || {};
    // W280 — arena rating wiped. The stakes are the CLIMB: a win ascends a
    // floor, a loss spends one of the day's lives. No points, no rating.
    if (!m.advances) {
      // W439 — Reclaim the Floor: a won re-fight of a cleared floor pays a daily-capped souls
      // bounty (first win per floor per day). Surface it in place of "nothing at stake".
      const cleared = m.floor <= st.highestCleared;
      const claimed = st.reclaimFloors.indexOf(m.floor) !== -1;
      const capHit = st.reclaimSouls >= ASCENT_RECLAIM_DAILY_CAP;
      const payable = cleared && !claimed && !capHit;
      const txt = payable
        ? '<b class="exb-bounty">Reclaim &middot; +' + _ascentReclaimBounty(m.floor) + ' souls</b> &mdash; your first win on this floor today.'
        : 'Nothing at stake' + (claimed ? ' &mdash; reclaimed today.' : capHit ? ' &mdash; daily reclaim cap reached.' : ' &mdash; floor already cleared.') +
          '<br><span class="dim">Replay for the fight, or to chase a FLAWLESS.</span>';
      return '<div class="asc-fill"><div class="asc-fill-head"><span class="k">ON THE LINE</span></div>' +
        '<div class="asc-stakes exhibition"><div class="exb"><div class="exb-tag">' + (payable ? 'RECLAIM' : 'EXHIBITION') + '</div>' +
        '<div class="exb-txt">' + txt + '</div></div></div></div>';
    }
    const nextFloor = Math.min(ASCENT_FLOORS, m.floor + 1);
    const winRows = '<div class="row"><span class="v">▲</span><span class="d">' +
      (m.floor >= ASCENT_FLOORS ? 'The summit — the First Awakened falls'
        : (_ascentIsBoss(m.floor) ? 'Slay the boss · ascend to floor ' + nextFloor : 'Ascend to floor ' + nextFloor)) + '</span></div>';
    const loseTxt = 'A life spent.<br><span class="dim">Grow stronger, return.</span>';
    return '<div class="asc-fill"><div class="asc-fill-head"><span class="k">ON THE LINE</span></div>' +
      '<div class="asc-stakes"><div class="col"><div class="lbl win">ON VICTORY</div>' + winRows + '</div>' +
      '<div class="vdiv"></div><div class="col"><div class="lbl">ON DEFEAT</div><div class="txt">' + loseTxt + '</div></div></div></div>';
  }
  // Fight Recap — blow-by-blow + honest stats (dmg = winning-side rolls).
  function _ascRecapHtml(f) {
    if (!f || !f.result) return '';
    const r = f.result;
    const stat = (v, l, win) => '<div class="st"><div class="v' + (win ? ' win' : '') + '">' + v + '</div><div class="l">' + l + '</div></div>';
    if (r.battle) {   // HP battle: remaining HP + damage dealt (timeout decider) + matchup
      const mt = r.eff && r.eff.key === 'super' ? 'SUPER' : r.eff && r.eff.key === 'weak' ? 'WEAK' : 'EVEN';
      const dmgRow = (typeof r.dpDealt === 'number')
        ? '<div class="asc-recap-stats">' + stat(r.dpDealt, 'DMG DEALT', r.dpDealt >= r.dbDealt) + stat(r.dbDealt, 'DMG TAKEN') +
          stat(r.reason === 'timeout' ? 'TIMEOUT' : 'K.O.', 'ENDED') + '</div>'
        : '';
      return '<div class="asc-fill"><div class="asc-fill-head"><span class="k">HOW IT ENDED</span></div>' +
        '<div class="asc-recap"><div class="asc-recap-stats">' +
          stat(Math.round(r.pHP) + '/' + r.pMax, 'YOUR HP', r.untouched) + stat(Math.round(r.bHP) + '/' + r.bMax, 'FOE HP') + stat(mt, 'MATCHUP') +
        '</div>' + dmgRow + '</div></div>';
    }
    if (!Array.isArray(r.rounds) || !r.rounds.length) return '';
    const rounds = r.rounds;
    let dealt = 0, taken = 0;
    rounds.forEach((rd) => { if (rd.playerWon) dealt += (rd.pRoll || 0); else taken += (rd.bRoll || 0); });
    const lines = rounds.map((rd) =>
      '<div class="ln ' + (rd.playerWon ? 'you' : 'foe') + '"><span class="dot"></span><span class="tx">' + _arNarr(rd) + '</span></div>').join('');
    return '<div class="asc-fill"><div class="asc-fill-head"><span class="k">HOW IT ENDED</span></div>' +
      '<div class="asc-recap">' + lines +
      '<div class="asc-recap-stats">' + stat(dealt, 'DMG DEALT') + stat(taken, 'DMG TAKEN', taken === 0) + stat(rounds.length, 'ROUNDS') + '</div></div></div>';
  }
  // VS intro — your avatar vs the foe portrait. Portrait hook (_arFoeArt)
