  function _megaSetPhase(cls) {
    const stage = document.getElementById('sigil-bloom-stage'); if (!stage) return;
    stage.classList.remove('is-mega-phase-0','is-mega-phase-1','is-mega-phase-2','is-mega-phase-3','is-mega-phase-4');
    if (cls) stage.classList.add(cls);
  }
  function _megaHaptic(pattern, force) {
    try {
      if (!force) { let r = false; try { r = !!(window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches); } catch (_) {} if (r) return; }
      if ('vibrate' in navigator) navigator.vibrate(pattern);
    } catch (_) {}
  }
  function _playMythicRevealSfx() {
    if (typeof soundEnabled !== 'undefined' && !soundEnabled) return;
    try {
      const Ctx = window.AudioContext || window.webkitAudioContext; if (!Ctx) return;
      if (!window.__bloomCtx) window.__bloomCtx = new Ctx();
      const ctx = window.__bloomCtx;
      if (ctx.state === 'suspended') { try { ctx.resume(); } catch (_) {} }
      _cutMythicSfx();
      // Decode + play through the app's already-unlocked reveal AudioContext
      // (more reliable on iOS WKWebView than a fresh HTMLAudio). m4a first, mp3
      // twin as the decode fallback; both precached so the fetch is instant.
      const playBuf = function(url, onFail) {
        fetch(url).then(function(r){ return r.arrayBuffer(); })
          .then(function(buf){ return ctx.decodeAudioData(buf); })
          .then(function(audioBuf){
            const src = ctx.createBufferSource(); src.buffer = audioBuf;
            const g = ctx.createGain(); g.gain.value = 0.9;
            src.connect(g); g.connect(ctx.destination); src.start();
            _megaAudio = src;
          })
          .catch(function(){ if (onFail) onFail(); });
      };
      playBuf('assets/audio/sfx_mythic_reveal.m4a', function(){ playBuf('assets/audio/sfx_mythic_reveal.mp3', null); });
    } catch (_) {}
  }
  function _cutMythicSfx() { try { if (_megaAudio) { try { _megaAudio.stop(); } catch (_) {} _megaAudio = null; } } catch (_) {} }
  function _megaRunLightDrain(drain) {
    if (!drain) return;
    const dur = 600, t0 = performance.now();
    cancelAnimationFrame(_megaRafId);
    (function step(now){ const p = Math.min(1, (now - t0) / dur), e = p * p;
      drain.style.setProperty('--drain', (150 - 150 * e) + '%');
      if (p < 1) _megaRafId = requestAnimationFrame(step); else drain.style.setProperty('--drain','0%');
    })(t0);
  }
  function _megaSpawnMotes(n, kind) {
    const stage = document.getElementById('sigil-bloom-stage'); if (!stage) return;
    const wrap = stage.querySelector('.mega-particles'); if (!wrap) return;
    wrap.innerHTML = '';
    const pal = ['#5eeaff','#ff5db1','#ffd24a','#b07bff'];
    for (let i = 0; i < n; i++) {
      const sp = document.createElement('span'); sp.className = 'mega-mote';
      const ang = Math.random() * Math.PI * 2, dist = 170 + Math.random() * 230;
      sp.style.setProperty('--sx', (Math.cos(ang) * dist).toFixed(0) + 'px');
      sp.style.setProperty('--sy', (Math.sin(ang) * dist).toFixed(0) + 'px');
      sp.style.setProperty('--ty', (((Math.random() * 2 - 1)) * 190).toFixed(0) + 'px');
      const c = pal[i % 4]; sp.style.background = c; sp.style.boxShadow = '0 0 8px ' + c;
      const sz = (kind === 'aftermath') ? (4 + Math.random() * 4) : (2 + Math.random() * 3);
      sp.style.width = sz + 'px'; sp.style.height = sz + 'px';
      if (kind === 'aftermath') { sp.classList.add('mega-mote--drift'); sp.style.setProperty('--dx', (((Math.random() * 2 - 1)) * 70) + 'px'); sp.style.animationDelay = (Math.random() * 1600) + 'ms'; }
      else { sp.style.animationDelay = (Math.random() * 260) + 'ms'; }
      wrap.appendChild(sp);
    }
  }
  function _megaRunOdometer() {
    const el = document.getElementById('megaOdo'); if (!el) return;
    const t0 = performance.now(), dur = 900;
    (function tick(now){ const p = Math.min(1, (now - t0) / dur); el.textContent = (p >= 1) ? '1%' : p.toFixed(2) + '%'; if (p < 1) requestAnimationFrame(tick); })(t0);
  }
  function _megaLockFinalState() {
    const stage = document.getElementById('sigil-bloom-stage'); if (!stage) return;
    const imp = function(e, prop, val){ if (e) e.style.setProperty(prop, val, 'important'); };
    const O = function(sel, v){ imp(stage.querySelector(sel), 'opacity', v || '1'); };
    ['.reveal-group','.mega-card','.rc-kicker','.rc-name-1','.rc-name-2','.rc-flex','.rc-onlypill','.rc-source','.rc-stats','.rc-flavor','.forever-mark','.aftermath-actions','.mega-continue-hint'].forEach(function(sel){ O(sel); });
    O('.prism-ring','0.85');
    imp(stage.querySelector('.blade-stage'),'clip-path','inset(0 0 0 0)');
    imp(stage.querySelector('.rc-name-1'),'clip-path','inset(0 0 0 0)');
    imp(stage.querySelector('.rc-name-2'),'clip-path','inset(0 0 0 0)');
    imp(stage.querySelector('.mega-card'),'transform','none');
    imp(stage.querySelector('.forever-mark'),'transform','none');
  }
  function _teardownMegaReveal() {
    _megaTimers.forEach(clearTimeout); _megaTimers = [];
    cancelAnimationFrame(_megaRafId);
    _cutMythicSfx();
    _megaState = 'idle';
    const overlay = document.getElementById('reveal-overlay');
    const stage = document.getElementById('sigil-bloom-stage');
    if (stage) { stage.classList.remove('is-mega-phase-0','is-mega-phase-1','is-mega-phase-2','is-mega-phase-3','is-mega-phase-4','is-strike-1','is-strike-2','is-revealed','is-aftermath','is-kick'); stage.innerHTML = ''; }
    if (overlay) overlay.classList.remove('is-reduced');
  }
  function _megaFastForwardToSettled() {
    const stage = document.getElementById('sigil-bloom-stage'); if (!stage) return;
    _megaTimers.forEach(clearTimeout); _megaTimers = [];
    _megaState = 'settled';
    stage.classList.add('is-strike-2','is-revealed','is-aftermath');
    const w = stage.querySelector('.mega-wordmark'); if (w) w.classList.remove('is-kicker','is-whisper');
    _megaSetPhase('is-mega-phase-4');
    const p = stage.querySelector('.mega-particles'); if (p) p.innerHTML = '';
    if (!stage.querySelector('.mega-mote--drift')) _megaSpawnMotes(7, 'aftermath');
    _megaLockFinalState();
  }
  function _megaPointerTap() {
    try {
      if (_megaState === 'reveal' || _megaState === 'aftermath') { _megaFastForwardToSettled(); return; }
      if (_megaState === 'settled') { closeCardRevealModal(); return; }
      // cut / totality / forge \u2014 you cannot rush reverence
    } catch (_) {}
  }
  function _megaRunReducedPath() {
    const overlay = document.getElementById('reveal-overlay');
    const stage = document.getElementById('sigil-bloom-stage');
    if (!overlay || !stage) return;
    _megaState = 'reveal';
    overlay.classList.add('is-reduced');
    stage.classList.add('is-revealed','is-aftermath');
    _megaSetPhase('is-mega-phase-4');
    _playMythicRevealSfx();
    _megaRunOdometer();
    _megaT(function(){ _megaHaptic(40, true); }, 600);
    _megaT(function(){ _megaState = 'settled'; _megaLockFinalState(); }, 2500);
  }
  function _runMegaReveal(card) {
    const overlay = document.getElementById('reveal-overlay');
    const stage = document.getElementById('sigil-bloom-stage');
    if (!overlay || !stage) return;
    _teardownMegaReveal();
    _buildMegaRevealDOM(card);
    try { const ia = document.getElementById('megaBladeArt'); if (ia) { const im = new Image(); im.onerror = function(){ ia.style.display = 'none'; }; im.src = (card && card.art_path) || 'assets/items/nightfall-blade-of-the-sovereign.png'; } } catch (_) {}
    let reduced = false; try { reduced = !!(window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches); } catch (_) {}
    if (reduced) { _megaRunReducedPath(); return; }
    const drain = stage.querySelector('.light-drain');
    // M0 — THE INTERRUPT
    _megaState = 'cut'; _megaSetPhase('is-mega-phase-0');
    _cutMythicSfx(); _megaRunLightDrain(drain); _playMythicRevealSfx(); _megaHaptic(60);
    // M1 — TOTALITY / THE HELD BREATH
    _megaT(function(){ _megaState = 'totality'; _megaSetPhase('is-mega-phase-1'); }, 900);
    _megaT(function(){ _megaHaptic([90,220,90]); }, 2700);
    _megaT(function(){ const w = stage.querySelector('.mega-wordmark'); if (w) w.classList.add('is-kicker'); }, 2650);
    _megaT(function(){ const w = stage.querySelector('.mega-wordmark'); if (w) w.classList.add('is-whisper'); }, 3450);
    // M2 — THE FORGING / EDGE FALLS TWICE
    _megaT(function(){ _megaState = 'forge'; _megaSetPhase('is-mega-phase-2'); const w = stage.querySelector('.mega-wordmark'); if (w) w.classList.remove('is-kicker','is-whisper'); _megaSpawnMotes(26, 'forge'); }, 4200);
    _megaT(function(){ stage.classList.add('is-strike-1'); _megaHaptic([40,30,80,30,140]); }, 6300);
    _megaT(function(){ stage.classList.add('is-strike-2'); stage.classList.add('is-kick'); _megaT(function(){ stage.classList.remove('is-kick'); }, 160); }, 6420);
    // M3 — THE REVEAL
    _megaT(function(){ _megaState = 'reveal'; _megaSetPhase('is-mega-phase-3'); stage.classList.add('is-revealed'); const p = stage.querySelector('.mega-particles'); if (p) p.innerHTML = ''; _megaRunOdometer(); }, 6800);
    _megaT(function(){ _megaHaptic(40); }, 8250);
    // M4 — THE FOREVER-MARK + AFTERMATH
    _megaT(function(){ _megaState = 'aftermath'; _megaSetPhase('is-mega-phase-4'); stage.classList.add('is-aftermath'); _megaSpawnMotes(7, 'aftermath'); }, 9800);
    _megaT(function(){ _megaState = 'settled'; _megaLockFinalState(); }, 11300);
  }

  // v3 Phase 1z.7 — short per-boss defeat-condition copy for the
  // overlay's gold-bordered VERIFIED row. Falls back to cfg.killCondShort
  // when no map entry exists.
  const BOSS_DEFEAT_CONDITIONS = {
    the_insomniac:     'Sleep goal achieved: 7+ hours',
    the_carouser:      '5 verified flights climbed',
    the_steel_wolf:    '6,000 verified steps',
    the_iron_warden:   'Workout verified (10+ min)',
    the_glass_strider: '7,500 verified steps',
    the_dream_tyrant:  '7.5 hours of sleep',
  };

  function _bossResultSeenKey(bossId, killCount) {
    return 'hb_boss_result_seen_' + bossId + '_' + killCount;
  }

  // v3 Phase 1z.56 — per-hunt seen-key for failure events. Keyed
  // by hunt_started_at so re-engaging the same boss and failing
  // again pops the modal again (different timestamp = different
  // hunt). Foregrounding the app after closing the failure modal
  // for the SAME failed hunt is a no-op.
  function _bossFailedSeenKey(bossId, huntStartedAt) {
    return 'hb_boss_failed_seen_' + bossId + '_' + (huntStartedAt || 0);
  }

  // v3 Phase 1z.7 — single-slot pending-result key. Drives the
  // HUNTING strip gold pill until the user acknowledges (closes the
  // overlay) OR 24h pass. Intentionally device-local; NEVER in
  // CloudSync.SNAPSHOT_KEYS (a restore onto a different device would
  // surface a phantom "you defeated X" pill for an event the user
  // never saw).
  const BOSS_RESULT_PENDING_KEY = 'hb_boss_result_pending';
  const BOSS_RESULT_AUTO_ACK_MS = 24 * 60 * 60 * 1000;

  function _writeBossResultPending(evt) {
    try {
      localStorage.setItem(BOSS_RESULT_PENDING_KEY, JSON.stringify({
        bossId:      evt.bossId,
        bossName:    evt.bossName,
        defeatedAt:  new Date().toISOString(),
        acknowledged: false,
        dropCardId:  evt.drop && evt.drop.cardId  || null,
        dropRarity:  evt.drop && evt.drop.rarity  || null,
        kill_count:  evt.kill_count || 1,
      }));
    } catch (_) {}
    try { if (typeof updateStatusPills === 'function') updateStatusPills(); } catch (_) {}
  }

  function _readBossResultPending() {
    try {
      const raw = localStorage.getItem(BOSS_RESULT_PENDING_KEY);
      if (!raw) return null;
      const parsed = JSON.parse(raw);
      if (!parsed || !parsed.bossId || !parsed.defeatedAt) return null;
      const age = Date.now() - Date.parse(parsed.defeatedAt);
      if (!isFinite(age) || age > BOSS_RESULT_AUTO_ACK_MS) {
        localStorage.removeItem(BOSS_RESULT_PENDING_KEY);
        return null;
      }
      if (parsed.acknowledged) return null;
      return parsed;
    } catch (_) { return null; }
  }

  function _clearBossResultPending() {
    try { localStorage.removeItem(BOSS_RESULT_PENDING_KEY); } catch (_) {}
    try { if (typeof updateStatusPills === 'function') updateStatusPills(); } catch (_) {}
  }
  try {
    window._readBossResultPending  = _readBossResultPending;
    window._clearBossResultPending = _clearBossResultPending;
  } catch (_) {}

  function _queueBossResult(evt) {
    if (!evt || !evt.bossId) return;
    // v3 Phase 1z.56 — branch on outcome so failure events get
    // their own per-hunt seen-key and do NOT write the gold
    // HUNTING-strip pending-result pill (the pill is meant to
    // celebrate a pending defeat; a failed hunt has nothing to
    // celebrate).
    const isFailed = evt.outcome === 'failed';
    try {
      const key = isFailed
        ? _bossFailedSeenKey(evt.bossId, evt.hunt_started_at)
        : _bossResultSeenKey(evt.bossId, evt.kill_count);
      if (localStorage.getItem(key) === '1') return;
    } catch (_) {}
    if (!isFailed) {
      // v3 Phase 1z.7 — write the pending-result envelope so the
      // HUNTING strip pill surfaces immediately, even before the
      // modal opens (kill-toast → 600ms → modal). Skipped for
      // failure events.
      try { _writeBossResultPending(evt); } catch (_) {}
    }
    _bossResultQueue.push(evt);
    _drainBossResultQueue();
  }

  function _drainBossResultQueue() {
    if (_bossResultBusy) return;
    const next = _bossResultQueue.shift();
    if (!next) {
      // v3 Phase 1z.73 — queue is empty. Chain to the cinematic
      // reveal queue (rare/ultra first-acquisition) so those modals
      // fire AFTER all boss-defeated modals are acknowledged.
      // Previously processRevealQueue fired from announceKillAndDrop
      // 500ms post-kill, which raced with the boss-defeated modal
      // when both a common-drop boss and a rare-drop boss fell in
      // the same tick. Centralising the trigger here guarantees
      // sequential UX.
      setTimeout(() => { try { processRevealQueue(); } catch (_) {} }, 200);
      return;
    }
    _bossResultBusy = true;
    // setTimeout 600ms — give the kill toast its moment first.
    setTimeout(() => { try { _showBossResult(next); } catch (_) { _bossResultBusy = false; } }, 600);
  }

  function _showBossResult(evt) {
    const overlay = document.getElementById('boss-result-overlay');
    if (!overlay) { _bossResultBusy = false; return; }

    // v3 Phase 1z.56 — branch on outcome. Failure events get a
    // different seen-key (keyed by hunt_started_at) and a
    // different render variant below.
    const isFailed = evt.outcome === 'failed';

    // Set seen flag FIRST so any re-render / aux path can't re-queue.
    try {
      const seenKey = isFailed
        ? _bossFailedSeenKey(evt.bossId, evt.hunt_started_at)
        : _bossResultSeenKey(evt.bossId, evt.kill_count);
      localStorage.setItem(seenKey, '1');
    } catch (_) {}

    // Theme the overlay via a class so CSS can mute the gold accents
    // for failure (red ember palette). Removed on close.
    overlay.classList.toggle('bro-overlay--failed', isFailed);

    _bossResultCurrent = evt;

    // v3 Phase 1z.56 — title + subline + "Fallen/Escaped" copy
    // diverge between defeat and failure paths.
    const titleEl = document.getElementById('bro-overlay-title');
    if (titleEl) titleEl.textContent = isFailed ? 'HUNT FAILED' : 'BOSS DEFEATED';
    const sublineEl = overlay.querySelector('.bro-subline');
    if (sublineEl) {
      sublineEl.textContent = isFailed
        ? ((evt.bossName ? 'The ' + evt.bossName.replace(/^The\s+/i, '') : 'The boss') + ' escaped.')
        : 'Your discipline broke the hunt.';
    }
    const fallenEl = overlay.querySelector('.bro-fallen');
    if (fallenEl) fallenEl.textContent = isFailed ? 'Escaped' : 'Has Fallen';

    // Boss card — name, rank pill, condition row, portrait
    const nameEl = document.getElementById('bro-boss-name');
    if (nameEl) nameEl.textContent = evt.bossName || '—';

    const rankPill = document.getElementById('bro-rank-pill');
    if (rankPill) {
      const rank = (evt.rank || 'E').toUpperCase();
      rankPill.textContent = rank + '-RANK BOSS';
      rankPill.setAttribute('data-rank', rank);
    }

    const portraitImg = document.getElementById('bro-boss-portrait');
    if (portraitImg) {
      portraitImg.removeAttribute('data-art');
      portraitImg.onerror = () => { portraitImg.setAttribute('data-art', 'missing'); };
      portraitImg.onload  = () => { portraitImg.removeAttribute('data-art'); };
      const path = getBossArtPath(evt.bossId);
      portraitImg.src = path;
      portraitImg.alt = evt.bossName || '';
    }

    // v3 Phase 1z.56 — hide the "VERIFIED" defeat row on failure
    // (no defeat happened). The row stays in the DOM so re-using
    // the same modal for a subsequent defeat repaints cleanly.
    const defeatRow = overlay.querySelector('.bro-defeat-row');
    if (defeatRow) defeatRow.classList.toggle('hidden', isFailed);

    const condEl = document.getElementById('bro-condition');
    if (condEl) {
      const short = (BOSS_DEFEAT_CONDITIONS && BOSS_DEFEAT_CONDITIONS[evt.bossId]) || null;
      condEl.textContent = short || evt.conditionLabel || 'Kill condition cleared';
    }

    const relicCard  = document.getElementById('bro-relic-card');
    const sealedCard = document.getElementById('bro-sealed-card');
    const nodropCard = document.getElementById('bro-nodrop-card');
    const failedCard = document.getElementById('bro-failed-card');
    const viewBtn    = document.getElementById('bro-view-relic');
    const viewMercy  = document.getElementById('bro-view-mercy');

    // v3 Phase 1z.83 — Sealed Mystery Relic. Show the sealed card
    // (NOT bro-relic-card) for rare / ultra FIRST acquisitions. The
    // relic identity stays entirely absent from the DOM until reveal.
    const _sealRelic = !!(evt.drop && evt.drop.wasFirst &&
      (evt.drop.rarity === 'rare' || evt.drop.rarity === 'ultra_rare'));

    if (isFailed) {
      // v3 Phase 1z.56 — failure variant: hide relic + mercy cards,
      // show the failed card with no-reward copy. HUNT AGAIN stays
      // available (engageBoss handles the souls cost gate).
      if (relicCard)  relicCard.classList.add('hidden');
      if (sealedCard) sealedCard.classList.add('hidden');
      if (nodropCard) nodropCard.classList.add('hidden');
      if (failedCard) failedCard.classList.remove('hidden');
      if (viewBtn)    viewBtn.classList.add('hidden');
      if (viewMercy)  viewMercy.classList.add('hidden');
      // Populate the failure body with the unmet condition so the
      // user understands WHAT they needed to do. Falls back to a
      // generic line if no condition copy is available.
      const failedBody = document.getElementById('bro-failed-body');
      if (failedBody) {
        const cond = (evt.conditionLabel || '').trim();
        failedBody.textContent = cond
          ? ('Objective not completed in time: ' + cond)
          : 'The hunt window closed before the objective was completed.';
      }
    } else if (evt.drop && _sealRelic) {
      // v3 Phase 1z.83 — sealed-mystery branch. The relic identity is
      // NOT rendered in the DOM. The sealed sigil + "A sealed relic
      // has emerged." copy stands in. Tap Reveal Relic → close →
      // queue drain → Sigil Bloom cinematic fires.
      if (failedCard) failedCard.classList.add('hidden');
      if (relicCard)  relicCard.classList.add('hidden');
      if (nodropCard) nodropCard.classList.add('hidden');
      if (sealedCard) sealedCard.classList.remove('hidden');
      if (viewMercy)  viewMercy.classList.add('hidden');
      if (viewBtn) {
        viewBtn.classList.remove('hidden');
        // cardId stays on the button so the queue chain can route
        // the right card to processRevealQueue post-close. data-masked
        // signals "tap → close + drain, don't open card detail."
        viewBtn.setAttribute('data-card-id', evt.drop.cardId);
        viewBtn.setAttribute('data-masked', '1');
        // Wipe any prior text + restore as "Reveal Relic" with the
        // seal-glyph icon. is-armed adds the violet pulse + glow.
        viewBtn.classList.add('is-armed');
        viewBtn.innerHTML =
          '<span class="bro-btn-seal-glyph" aria-hidden="true">' +
            '<svg viewBox="0 0 16 16">' +
              '<circle cx="8" cy="9" r="5.5" fill="none" stroke="currentColor" stroke-width="1.4"/>' +
              '<path d="M5 9 L11 9" stroke="currentColor" stroke-width="1.4" stroke-linecap="round"/>' +
              '<path d="M8 4 L8 6.5" stroke="currentColor" stroke-width="1.4" stroke-linecap="round"/>' +
            '</svg>' +
          '</span>' +
          'Reveal Relic';
      }
    } else if (evt.drop) {
      if (failedCard) failedCard.classList.add('hidden');
      if (sealedCard) sealedCard.classList.add('hidden');
      // Relic acquired — commons + duplicate rare/ultra fall here.
      if (relicCard)  relicCard.classList.remove('hidden');
      if (nodropCard) nodropCard.classList.add('hidden');
      if (viewBtn) {
        viewBtn.classList.remove('hidden');
        viewBtn.classList.remove('is-armed');
        viewBtn.removeAttribute('data-masked');
        viewBtn.setAttribute('data-card-id', evt.drop.cardId);
        viewBtn.textContent = 'View Relic';
      }
      if (viewMercy) viewMercy.classList.add('hidden');

      // Rarity pill + outer card border tint
      const rarityPill = document.getElementById('bro-relic-rarity-pill');
      if (rarityPill) {
        const rarityLabel = (RARITY_LABELS && RARITY_LABELS[evt.drop.rarity]) || evt.drop.rarity || '';
        rarityPill.textContent = String(rarityLabel).toUpperCase();
        rarityPill.setAttribute('data-rarity', evt.drop.rarity || 'common');
      }
      if (relicCard) relicCard.setAttribute('data-rarity', evt.drop.rarity || 'common');

      const eyebrowEl = document.getElementById('bro-relic-eyebrow');
      if (eyebrowEl) {
        // W611-fix — tell the truth about duplicates/capped (was always
        // "RELIC ACQUIRED", which contradicts the toast's "Duplicate · cap
        // reached"). The relic still shows; only the eyebrow is honest.
        let _eb;
        if (evt.drop.wasCapped)          _eb = 'DUPLICATE · CAP REACHED';
        else if (evt.drop.wasFirst === false) _eb = 'DUPLICATE';
        else if (evt.drop.fromPity)      _eb = (evt.drop.pityType === 'ultra_hard' ? 'FATE ANSWERED' : 'MERCY AWAKENED');
        else                             _eb = 'RELIC ACQUIRED';
        eyebrowEl.textContent = _eb;
      }
      // v3 Phase 1z.48 — route through the shared setModalCardArt
      // helper used by openCardDetailModal so the Boss Defeated
      // result modal and the relic-detail page render artwork
      // identically. The previous inline block paired the same
      // onload/onerror dance with a `loading="lazy"` <img>, which
      // (combined with `display: none` set before src) caused
      // browsers to defer the load and never fire `onload` — the
      // emoji slot-icon fallback stayed visible even though the
      // artwork exists. The img element now has no lazy attribute
      // (see index.html) and uses the same code path as the
      // working detail page.
      setModalCardArt('bro-relic-art', evt.drop.artPath);
      const slotIconEl = document.getElementById('bro-relic-slot-icon');
      if (slotIconEl) slotIconEl.textContent = (SLOT_ICONS && SLOT_ICONS[evt.drop.slot]) || '✦';
      const relicNameEl = document.getElementById('bro-relic-name');
      if (relicNameEl) relicNameEl.textContent = evt.drop.name || '';
      const metaEl = document.getElementById('bro-relic-meta');
      if (metaEl) {
        const slotLabel = (evt.drop.slot || '').toUpperCase();
        const sourceLabel = evt.bossName ? ('From ' + evt.bossName.toUpperCase()) : '';
        const newPill = evt.drop.wasFirst ? '<span class="bro-relic-new">NEW</span>' : '';
        metaEl.innerHTML =
          (slotLabel  ? '<span class="bro-relic-slot">' + slotLabel + '</span>' : '') +
          (sourceLabel ? '<span class="bro-relic-source">· ' + sourceLabel + '</span>' : '') +
          newPill;
      }
      const statsEl = document.getElementById('bro-relic-stats');
      if (statsEl) {
        const card = CARDS && CARDS[evt.drop.cardId];
        statsEl.innerHTML = card ? cardStatBadgesHtml(card) : '';
      }

      // v3 Phase 1z.83 — rare/ultra FIRST-acquisitions are now
      // handled by the `_sealRelic` branch above (Sealed Mystery
      // Relic card). The legacy 1z.82 "???" masking inside
      // bro-relic-card was retired with that move. Commons +
      // duplicate rare/ultra reach this branch and see the full
      // relic as before.
    } else {
      // No drop — mercy increased. Render 3-row mercy block with bar fills.
      if (relicCard)  relicCard.classList.add('hidden');
      if (sealedCard) sealedCard.classList.add('hidden');
      if (nodropCard) nodropCard.classList.remove('hidden');
      if (failedCard) failedCard.classList.add('hidden');
      if (viewBtn)    viewBtn.classList.add('hidden');
      if (viewMercy) {
        viewMercy.classList.remove('hidden');
        viewMercy.setAttribute('data-boss-id', evt.bossId);
      }
      const mercyBlock = document.getElementById('bro-mercy-block');
      if (mercyBlock && evt.mercy) {
        const m = evt.mercy;
        const cur1 = Math.min(m.anyDropCurrent || 0, m.anyDropTarget    || 0);
        const cur2 = Math.min(m.rareCurrent    || 0, m.rareTarget       || 0);
        const cur3 = Math.min(m.ultraCurrent   || 0, m.ultraHardTarget  || 0);
        const t1 = m.anyDropTarget    || 1;
        const t2 = m.rareTarget       || 1;
        const t3 = m.ultraHardTarget  || 1;
        const p1 = Math.min(100, (cur1 / t1) * 100);
        const p2 = Math.min(100, (cur2 / t2) * 100);
        const p3 = Math.min(100, (cur3 / t3) * 100);
        mercyBlock.innerHTML =
          '<div class="bro-mercy-row" data-tier="any">' +
            '<div class="bro-mercy-row-head"><span class="bro-mercy-label">Guaranteed Relic</span>' +
              '<span class="bro-mercy-val">' + cur1 + ' / ' + (m.anyDropTarget || 0) + '</span></div>' +
            '<div class="bro-mercy-bar"><div class="bro-mercy-bar-fill" style="width:' + p1 + '%"></div></div>' +
          '</div>' +
          '<div class="bro-mercy-row" data-tier="rare">' +
            '<div class="bro-mercy-row-head"><span class="bro-mercy-label">Rare Mercy</span>' +
              '<span class="bro-mercy-val">' + cur2 + ' / ' + (m.rareTarget || 0) + '</span></div>' +
            '<div class="bro-mercy-bar"><div class="bro-mercy-bar-fill" style="width:' + p2 + '%"></div></div>' +
          '</div>' +
          '<div class="bro-mercy-row" data-tier="ultra">' +
            '<div class="bro-mercy-row-head"><span class="bro-mercy-label">Ultra Mercy</span>' +
              '<span class="bro-mercy-val">' + cur3 + ' / ' + (m.ultraHardTarget || 0) + '</span></div>' +
            '<div class="bro-mercy-bar"><div class="bro-mercy-bar-fill" style="width:' + p3 + '%"></div></div>' +
          '</div>';
      } else if (mercyBlock) {
        mercyBlock.innerHTML = '';
      }
    }

    // Wire Hunt Again button data-boss-id.
    const huntAgainBtn = document.getElementById('bro-hunt-again');
    if (huntAgainBtn) huntAgainBtn.setAttribute('data-boss-id', evt.bossId);

    overlay.classList.remove('hidden');
    overlay.setAttribute('aria-hidden', 'false');
    document.body.classList.add('bro-locked');

    // v3 Phase 1z.73 — confetti + chime when the boss-defeated modal
    // opens with a rare or ultra_rare relic in evt.drop. Failed-outcome
    // events have no drop, so the celebration only ever fires for
    // genuine defeats. Cinematic reveals get their own celebration
    // hook in openCardRevealModal; duplicates that route through the
    // boss-defeated modal (not the cinematic) get their celebration
    // here.
    //
    // v3 Phase 1z.84 — skip the confetti+chime for SEALED first
    // acquisitions. The sealed sigil is intentionally quiet; the
    // Sigil Bloom cinematic carries the celebration. Without this
    // guard the legacy pdc-overlay reuse (confetti canvas + the
    // "PERFECT DAY" banner inside the same DOM element) leaked
    // through over the sealed card. Only duplicate rare/ultra
    // drops (wasFirst=false) reach the confetti path now.
    if (!isFailed && evt.drop && evt.drop.rarity && !_sealRelic &&
        (evt.drop.rarity === 'rare' || evt.drop.rarity === 'ultra_rare')) {
      try { celebrateRareDrop(evt.drop.rarity); } catch (_) {}
    }
  }

  function closeBossResult(opts) {
    const overlay = document.getElementById('boss-result-overlay');
    if (overlay) {
      overlay.classList.add('hidden');
      overlay.setAttribute('aria-hidden', 'true');
      // v3 Phase 1z.56 — strip the failure-theme class so a
      // subsequent defeat opens with the standard gold palette.
      overlay.classList.remove('bro-overlay--failed');
    }
    document.body.classList.remove('bro-locked');
    const _closingWin = !!(_bossResultCurrent && _bossResultCurrent.outcome !== 'failed');   // W541 — only a WIN dismissal may spend the review shot
    _bossResultCurrent = null;
    _bossResultBusy = false;
    // v3 Phase 1z.7 — clear pending-result envelope. The user opened
    // (and is now closing) the overlay; the gold HUNTING strip pill
    // has done its job and should retract.
    try { _clearBossResultPending(); } catch (_) {}
    // Drain the next queued result, if any.
    if (!(opts && opts.suppressDrain)) {
      _drainBossResultQueue();
    }
    // W541/W547 — review pre-prompt ONLY after a WIN dismissal (never a HUNT
    // FAILED close). The normal close flushes; a suppressDrain close flushes
    // ONLY when it's a deliberate "done with this win" engagement (View Relic /
    // View Mercy pass flushReview:true) — NOT a Hunt-Again re-engage, the masked-
    // relic reveal cinematic, or an incidental tab-switch (those leave it armed
    // for a later trigger, since the prompt is one-shot).
    if (_closingWin && (!(opts && opts.suppressDrain) || (opts && opts.flushReview))) {
      try { _reviewFlush(['boss', 'coop']); } catch (_) {}
    }
  }

  // v3 Phase 1z.7 — re-open the overlay when the HUNTING strip pill
  // is tapped. Rebuilds the evt envelope from the pending-result
  // localStorage payload + live BOSSES/CARDS lookups so the visuals
  // stay current even after a tab switch / cold launch.
  function openBossResultFromPending() {
    const pending = _readBossResultPending();
    if (!pending) return;
    const cfg = (typeof BOSSES !== 'undefined') ? BOSSES[pending.bossId] : null;
    let mercy = null;
    try {
      if (typeof getDropPityDisplay === 'function') {
        const m = getDropPityDisplay(pending.bossId);
        mercy = m ? {
          anyDropCurrent:   m.anyDropCurrent,
          anyDropTarget:    m.anyDropTarget,
          rareCurrent:      m.rareCurrent,
          rareTarget:       m.rareTarget,
          ultraCurrent:     m.ultraCurrent,
          ultraSoftTarget:  m.ultraSoftTarget,
          ultraHardTarget:  m.ultraHardTarget,
        } : null;
      }
    } catch (_) {}
    let drop = null;
    if (pending.dropCardId && typeof CARDS !== 'undefined' && CARDS[pending.dropCardId]) {
      const c = CARDS[pending.dropCardId];
      drop = {
        cardId:   c.id,
        name:     c.name,
        rarity:   c.rarity,
        slot:     c.slot,
        artPath:  c.art_path,
        wasFirst: false,  // re-open path; first-acq state already surfaced
      };
    }
    const evt = {
      bossId:        pending.bossId,
      bossName:      (cfg && cfg.name) || pending.bossName || '—',
      rank:          (cfg && cfg.rank) || 'E',
      kill_count:    pending.kill_count || 1,
      conditionLabel: (cfg && (cfg.killCondShort || cfg.killCondLong)) || '',
      drop:          drop,
      mercy:         mercy,
    };
    // Bypass the seen-flag dedupe — the user explicitly asked to re-open.
    _bossResultBusy = true;
    setTimeout(() => { try { _showBossResult(evt); } catch (_) { _bossResultBusy = false; } }, 60);
  }
  try { window.openBossResultFromPending = openBossResultFromPending; } catch (_) {}
  // v3 Phase 1z.83 — expose for QA/preview console snippets only.
  // Production code uses the IIFE-scoped originals; these globals let
  // localhost preview snippets simulate a sealed-relic flow without
  // grinding an actual boss defeat.
  try {
    window.__queueBossResult     = _queueBossResult;
    window.__processRevealQueue  = processRevealQueue;
    window.__loadInventory       = loadInventory;
  } catch (_) {}

  // ════════════════════════════════════════════════════════════════════════
  // W541 — App Store review PRE-PROMPT (compliant, one-shot). A branded screen
  // at a peak moment whose single CTA fires Apple's NATIVE review sheet via
  // @capacitor-community/in-app-review. Exactly two HARMLESS actions: "Rate
  // Awakened" (native sheet) + "Not now" (close only). NO sentiment fork, NO
  // custom stars, NO reward tied to rating. The native API gives no outcome
  // callback, so EVERY gate is on our own milestone flags — never on whether
  // the user rated. Guideline 1.1.6 / 5.6. Flags are localStorage (the app's
  // pattern) + added to CloudSync SNAPSHOT_KEYS so the one shot survives reinstall.
  // ════════════════════════════════════════════════════════════════════════
  var _RV = {
    seen:      'hb_review_prompt_v1_seen',   // the ONE auto-prompt; once set, never auto-prompt again
    firstBoss: 'hb_review_first_boss_done',
    firstCoop: 'hb_review_first_coop_done',
    pdayCount: 'hb_review_pday_count',
    pdayLast:  'hb_review_pday_last',
  };
  var _REVIEW_APP_ID = '6764727990';
  var _reviewPending = null;   // {trigger, ctx} armed by a celebration; fired on its close
  function _rvGet(k) { try { return localStorage.getItem(k); } catch (_) { return null; } }
  function _rvSet(k, v) { try { localStorage.setItem(k, v); } catch (_) {} }
  function _reviewDaysActive() { try { if (typeof completions === 'undefined' || !completions) return 0; return Object.keys(completions).filter(function (d) { return (completions[d] || []).length > 0; }).length; } catch (_) { return 0; } }
  function _reviewPerfectDayCount() { return parseInt(_rvGet(_RV.pdayCount), 10) || 0; }
  function _reviewBumpPerfectDay() {
    var d = (typeof perfectStreak !== 'undefined' && perfectStreak && perfectStreak.lastDate) || new Date().toISOString().slice(0, 10);
    if (_rvGet(_RV.pdayLast) === d) return;        // already counted for this perfect day
    _rvSet(_RV.pdayLast, d);
    _rvSet(_RV.pdayCount, String(_reviewPerfectDayCount() + 1));
  }
  // A qualifying celebration just began — fire the pre-prompt when it CLOSES so
  // the milestone's own animation plays first and fully.
  function _reviewArm(trigger, ctx) {
    // Priority: a co-op/boss win outranks a perfect day — never let a perfect-day
    // arm clobber a still-pending boss/coop win (that would silently drop the moment).
    if (trigger === 'perfectday' && _reviewPending && (_reviewPending.trigger === 'boss' || _reviewPending.trigger === 'coop')) return;
    _reviewPending = { trigger: trigger, ctx: ctx || {} };
  }
  function _reviewFlush(allowed) {
    var p = _reviewPending;
    if (!p || allowed.indexOf(p.trigger) < 0) return;
    _reviewPending = null;
    setTimeout(function () { try { _maybeReviewPrompt(p.trigger, p.ctx); } catch (_) {} }, 480);   // short gap after the celebration clears
  }
  function _maybeReviewPrompt(trigger, ctx) {
    if (_rvGet(_RV.seen)) return;                  // one shot already spent → never auto-prompt again
    if (trigger === 'perfectday') {
      // READY gate — never burn our one shot on a brand-new day-one perfect day.
      var ready = _reviewDaysActive() >= 3 || _reviewPerfectDayCount() >= 2 || _rvGet(_RV.firstBoss) || _rvGet(_RV.firstCoop);
      if (!ready) return;
    }
    _rvSet(_RV.seen, '1');                          // claim the one shot up front (idempotent)
    _showReviewPrePrompt(trigger, ctx);
  }
  // Native review sheet. No success/failure callback exists; fire-and-forget.
  function _reviewRequestNative() {
    try {
      var P = (window.Capacitor && window.Capacitor.Plugins) || {};
      if (P.InAppReview && typeof P.InAppReview.requestReview === 'function') { P.InAppReview.requestReview(); return true; }
    } catch (_) {}
    return false;
  }
  function _reviewWriteReviewUrl() { return 'https://apps.apple.com/app/id' + _REVIEW_APP_ID + '?action=write-review'; }
  function _reviewCTA() {
    // Native sheet on iOS; on web/PWA (plugin absent) fall back to the user-
    // initiated write-review composer. Both are compliant; neither gates on sentiment.
    if (!_reviewRequestNative()) { try { window.open(_reviewWriteReviewUrl(), '_system'); } catch (_) {} }
  }
  function _reviewEmblem(kind) {
    var o = '<svg viewBox="0 0 48 48" fill="none" stroke="currentColor" stroke-width="2.3" stroke-linecap="round" stroke-linejoin="round">';
    if (kind === 'party') return o + '<path d="M13 11 L29 29 M9 15 L13 11 L17 13 M29 29 L35 35 L37 31 L33 27"/><path d="M35 11 L19 29 M39 15 L35 11 L31 13 M19 29 L13 35 L11 31 L15 27"/></svg>';
    if (kind === 'shieldcheck') return o + '<path d="M24 6 L38 11 V21 C38 30 32 36 24 39 C16 36 10 30 10 21 V11 L24 6Z"/><path d="M17.5 22 L22 26.5 L31 16.5"/></svg>';
    return o + '<path d="M16 8 H32 V16 A8 8 0 0 1 16 16 Z"/><path d="M16 11 H10 A4 4 0 0 0 14.5 17.2"/><path d="M32 11 H38 A4 4 0 0 1 33.5 17.2"/><path d="M24 24 V31 M18 40 H30 M21 31 H27"/></svg>';
  }
  var _REVIEW_VARIANTS = {
    boss:       { eyebrow: 'BOSS DEFEATED',   emblem: 'trophy',     head: function (c) { return 'You bested<br>' + esc(c.bossName || 'the boss'); }, sub: function (c) { return 'FIRST BOSS · RANK ' + esc(c.rank || '—'); }, emo: 'Few hunters make it this far.', why: 'A rating helps other hunters find the climb.' },
    coop:       { eyebrow: 'DUNGEON CLEARED', emblem: 'party',      head: function (c) { return 'Your guild cleared<br>' + esc(c.dungeonName || 'the dungeon'); }, sub: function (c) { return 'FIRST CO-OP WIN · ' + ((c.partySize || 2)) + ' HUNTERS'; }, emo: 'Stronger together.', why: 'A rating helps other hunters find their guild.' },
    perfectday: { eyebrow: 'VOWS SEALED',     emblem: 'shieldcheck', head: function () { return 'A flawless<br>day'; }, sub: function () { return 'FIRST PERFECT DAY · ALL VOWS KEPT'; }, emo: 'You did what others won’t.', why: 'A rating helps other hunters start theirs.' },
  };
  function _reviewClose() { var ov = document.getElementById('review-pp-overlay'); if (ov) { ov.classList.add('closing'); setTimeout(function () { try { ov.remove(); } catch (_) {} }, 240); } }
  function _showReviewPrePrompt(trigger, ctx) {
    var v = _REVIEW_VARIANTS[trigger]; if (!v) return;
    ctx = ctx || {};
    var old = document.getElementById('review-pp-overlay'); if (old) old.remove();
    var checks = trigger === 'perfectday' ? '<div class="review-pp-checks"><i></i><i></i><i></i><i></i></div>' : '';
    var ov = document.createElement('div'); ov.id = 'review-pp-overlay'; ov.className = 'review-pp';
    ov.innerHTML =
      '<div class="review-pp-card" role="dialog" aria-modal="true" aria-label="Rate Awakened">' +
        '<div class="review-pp-eyebrow">' + esc(v.eyebrow) + '</div>' +
        '<div class="review-pp-emblem">' + _reviewEmblem(v.emblem) + '</div>' +
        '<div class="review-pp-head">' + v.head(ctx) + '</div>' +
        '<div class="review-pp-sub">' + v.sub(ctx) + '</div>' + checks +
        '<div class="review-pp-divider"></div>' +
        '<div class="review-pp-emo">' + esc(v.emo) + '</div>' +
        '<div class="review-pp-why">' + esc(v.why) + '</div>' +
        '<button type="button" class="review-pp-cta" id="review-pp-rate">Rate Awakened</button>' +
        '<button type="button" class="review-pp-not" id="review-pp-not">Not now</button>' +
        '<div class="review-pp-foot">Opens Apple’s rating prompt</div>' +
      '</div>';
    document.body.appendChild(ov);
    requestAnimationFrame(function () { ov.classList.add('on'); });
    var rate = ov.querySelector('#review-pp-rate'); if (rate) rate.addEventListener('click', function () { _reviewCTA(); _reviewClose(); });
    var not = ov.querySelector('#review-pp-not'); if (not) not.addEventListener('click', function () { _reviewClose(); });   // close only — does nothing else
  }

  // ════════════════════════════════════════════════════════════════════════
  // W542 — DEV TEST PANEL (hidden; long-press the Settings "Version" line ~0.85s).
  // Lets the owner SEE every new set-piece on-device without grinding the real
  // conditions: the F100 unbind cinematic + The Ascension finale, all 3 review
  // pre-prompt variants, the perfect-day + boss-defeated celebrations, and a
  // review-flag reset to re-test.
  //
  // ⚠️⚠️  W549 — PUBLIC-BUILD KILL SWITCH  ⚠️⚠️
  //    Flip DEV_BUILD to false for the public App Store build. That single flip
  //    makes the long-press gesture do nothing, so the panel is unreachable in
  //    production (the code below stays in the bundle but is dead/unentered).
  //    For TestFlight it stays true so the owner can keep testing set-pieces.
  //    This is the ONE switch to check before a public submission.
  // ════════════════════════════════════════════════════════════════════════
  const DEV_BUILD = false;  // ⚠️ set to false for the PUBLIC App Store build (disables the hidden dev panel) — FALSE for the 2.4.5 submission (build 450, W767)
  function _devToast(e) { try { showHabitToast(typeof e === 'string' ? e : ((e && e.message) || 'done')); } catch (_) {} }
  function _devClose() { var ov = document.getElementById('dev-panel'); if (ov) ov.remove(); }
  function _devBossCeleb() {
    try {
      var cfg = (typeof getBoss === 'function') ? (getBoss('the_steel_wolf') || getBoss('the_insomniac')) : null;
      if (!cfg) { _devToast('no boss cfg'); return; }
      _reviewArm('boss', { bossName: cfg.name || 'the boss', rank: cfg.rank || 'C' });
      announceKillAndDrop(cfg, 50, null);   // the REAL celebration path — builds the full evt + queues the modal + fanfare
    } catch (e) { _devToast(e); }
  }
  function _devResetReview() {
    try { ['hb_review_prompt_v1_seen', 'hb_review_first_boss_done', 'hb_review_first_coop_done', 'hb_review_pday_count', 'hb_review_pday_last'].forEach(function (k) { localStorage.removeItem(k); }); } catch (_) {}
    _reviewPending = null; _devToast('Review one-shot reset');
  }
  function _devOpenPanel() {
    if (document.getElementById('dev-panel')) { _devClose(); return; }
    var rows = [
      ['🎬  Unbind cinematic (F100)', function () { _devClose(); try { _faPlayUnbindCinematic(function () {}, function () {}); } catch (e) { _devToast(e); } }],
      ['👑  The Ascension (F100 victory finale)', function () { _devClose(); try { if (_AUD.musicLoop) _audStopMusic(0.4); _audPlayMusic(_AUD.buffers['first_awakened_win'] ? 'first_awakened_win' : 'victory_sting', false); _arPlayAscension({ onHall: function () { try { showTab && showTab('status'); } catch (_) {} } }); } catch (e) { _devToast(e); } }],
      ['🐺  Boss-defeated celebration → review', function () { _devClose(); _devBossCeleb(); }],
      ['🎉  Perfect-day celebration', function () { _devClose(); try { triggerPerfectDayCelebration(7); _reviewArm('perfectday', {}); } catch (e) { _devToast(e); } }],
      ['🗡️  Review pre-prompt: Boss', function () { _devClose(); _showReviewPrePrompt('boss', { bossName: 'The Steel Wolf', rank: 'C' }); }],
      ['🛡️  Co-op win (record kill + review)', function () { _devClose(); try { var _cid = Object.keys(COOP_BOSSES)[0]; _coopBumpKill(_cid); _devToast((COOP_BOSSES[_cid] || {}).name + ' logged'); } catch (_) {} _showReviewPrePrompt('coop', { dungeonName: 'The Twin Maw', partySize: 2 }); }],
      ['✦  Review pre-prompt: Perfect Day', function () { _devClose(); _showReviewPrePrompt('perfectday', {}); }],
      ['↺  Reset review one-shot (re-test)', function () { _devResetReview(); }],
    ];
    var ov = document.createElement('div'); ov.id = 'dev-panel';
    ov.style.cssText = 'position:fixed;inset:0;z-index:99999;background:rgba(0,0,0,.82);display:flex;align-items:center;justify-content:center;padding:24px;font-family:-apple-system,system-ui,sans-serif;';
    var html = '<div style="width:100%;max-width:310px;background:#16163a;border:1px solid rgba(245,158,11,.4);border-radius:16px;padding:18px;box-shadow:0 20px 60px rgba(0,0,0,.6);">' +
      '<div style="font-family:\'JetBrains Mono\',monospace;font-size:11px;letter-spacing:.22em;color:#f59e0b;text-align:center;margin-bottom:14px;">DEV TEST · W542</div>';
    rows.forEach(function (r, i) { html += '<button data-dev="' + i + '" style="display:block;width:100%;margin:0 0 8px;padding:13px;border:none;border-radius:10px;background:#22224a;color:#f2f2f7;font-size:14px;font-weight:600;text-align:left;cursor:pointer;">' + r[0] + '</button>'; });
    html += '<button data-dev="x" style="display:block;width:100%;margin:8px 0 0;padding:11px;border:none;border-radius:10px;background:none;color:#8e8e93;font-size:13px;cursor:pointer;">Close</button></div>';
    ov.innerHTML = html;
    document.body.appendChild(ov);
    ov.addEventListener('click', function (e) {
      if (e.target === ov) { _devClose(); return; }
      var b = e.target.closest('[data-dev]'); if (!b) return;
      var d = b.getAttribute('data-dev'); if (d === 'x') { _devClose(); return; }
      var idx = parseInt(d, 10); if (rows[idx]) rows[idx][1]();
    });
  }
  // Wire the hidden long-press opener onto the Settings version line.
  function _devWireLongPress() {
    var ver = document.getElementById('settings-app-ver'); if (!ver || ver._devWired) return;
    ver._devWired = true; var t = null;
    var start = function () { t = setTimeout(_devOpenPanel, 850); };
    var cancel = function () { if (t) { clearTimeout(t); t = null; } };
    ver.addEventListener('mousedown', start); ver.addEventListener('touchstart', start, { passive: true });
    ['mouseup', 'mouseleave', 'touchend', 'touchcancel'].forEach(function (ev) { ver.addEventListener(ev, cancel); });
  }

  function setupBossResultModal() {
    const overlay = document.getElementById('boss-result-overlay');
    if (!overlay) return;
    const closeBtn = document.getElementById('bro-close');
    if (closeBtn) closeBtn.addEventListener('click', () => closeBossResult());
    const closeX = document.getElementById('bro-close-x');
    if (closeX) closeX.addEventListener('click', () => closeBossResult());
    const huntAgainBtn = document.getElementById('bro-hunt-again');
    if (huntAgainBtn) {
      huntAgainBtn.addEventListener('click', () => {
        const id = huntAgainBtn.getAttribute('data-boss-id');
        // Close first so re-engage toasts aren't hidden behind the modal.
        // Suppress drain so the re-engage doesn't race with the next queued result.
        closeBossResult({ suppressDrain: true });
        if (id) {
          try { engageBoss(id); } catch (_) {}
        }
        // Now drain any remaining queued results.
        _drainBossResultQueue();
      });
    }
    const viewBtn = document.getElementById('bro-view-relic');
    if (viewBtn) {
      viewBtn.addEventListener('click', () => {
        const cardId = viewBtn.getAttribute('data-card-id');
        // v3 Phase 1z.82 — masked-drop branch. For rare/ultra first-
        // acquisitions, the boss-defeated modal hid the relic identity.
        // Tapping "Reveal Relic" should NOT open the static card-detail
        // page (that would spoil the relic without the cinematic). Just
        // close the modal — _drainBossResultQueue chains to
        // processRevealQueue when the boss-defeated queue empties,
        // and the Sigil Bloom fires from openCardRevealModal. The
        // cinematic itself marks the card as seen + clears the NEW
        // chip when the user taps to continue.
        const isMasked = viewBtn.getAttribute('data-masked') === '1';
        if (isMasked) {
          closeBossResult({ suppressDrain: true });
          _drainBossResultQueue();
          return;
        }
        closeBossResult({ suppressDrain: true, flushReview: true });   // W547 — View Relic is a deliberate win-engagement; still let the review pre-prompt flush
        try {
          // v3 Phase 1z.7 — viewing the relic clears its NEW chip.
          if (cardId) _markRelicSeen(cardId);
          const card = CARDS && CARDS[cardId];
          const inv = (typeof getInventory === 'function') ? getInventory() : null;
          const entry = inv && inv.cards && inv.cards[cardId];
          if (card && entry && typeof openCardDetailModal === 'function') {
            openCardDetailModal(card, entry);
          }
        } catch (_) {}
        _drainBossResultQueue();
      });
    }
    const viewMercy = document.getElementById('bro-view-mercy');
    if (viewMercy) {
      viewMercy.addEventListener('click', () => {
        const id = viewMercy.getAttribute('data-boss-id');
        closeBossResult({ suppressDrain: true, flushReview: true });   // W547 — View Mercy is a deliberate win-engagement; still let the review pre-prompt flush
        try { if (id && typeof openBossFullScreen === 'function') openBossFullScreen(id); } catch (_) {}
        _drainBossResultQueue();
      });
    }
    // ESC closes.
    document.addEventListener('keydown', (e) => {
      if (e.key !== 'Escape') return;
      if (overlay.classList.contains('hidden')) return;
      closeBossResult();
    });
  }

  try { window.closeBossResult = closeBossResult; } catch (_) {}

  // ── Reveal modal: cinematic card-drop ceremony ──────────────
  // Processes hb_inventory.reveal_queue one-at-a-time. If queue
  // empty, no-op. If already showing, no-op (the close handler
  // calls processRevealQueue again to chain).
  let _revealActive = false;

  function processRevealQueue() {
    if (_revealActive) return;
    const inv = getInventory();
    if (!inv.reveal_queue || inv.reveal_queue.length === 0) return;
    const nextId = inv.reveal_queue[0];
    const card = CARDS[nextId];
    if (!card) {
      // Stale id (CARDS schema may have changed) — drop from queue
      // and continue.
      inv.reveal_queue.shift();
      persistInventory();
      processRevealQueue();
      return;
    }
    openCardRevealModal(card);
  }

  function openCardRevealModal(card) {
    const overlay = document.getElementById('reveal-overlay');
    if (!overlay) return;
    _revealActive = true;
    document.body.classList.add('reveal-locked');
    // v3 Phase 1z.165 — Guild Hall feat row for ultra-rare drops.
    // Per-card-id idempotent so re-opening the modal (debug, queue
    // replay, etc.) doesn't dup. Only ultra-rare qualifies — common
    // and rare drops are not feats by themselves at this scale.
    // W697 — MYTHIC now also takes this prominent Tier-1 row. The Grinning
    // God's table is mythic-ONLY, so without this its (rarest-in-game) drops
    // would fall to the lesser card_drop row — the card_drop write below is
    // coordinated to skip mythic so there's exactly one row.
    try {
      if (card && (card.rarity === 'ultra_rare' || card.rarity === 'mythic')) {
        const _isMyth = card.rarity === 'mythic';
        recordGuildActivity('ultra_rare_drop', {
          cardId:   card.id || null,
          cardName: card.name || (_isMyth ? 'a mythic relic' : 'an ultra-rare relic'),
          mythic:   _isMyth || undefined,
        }, (_isMyth ? 'mythic_' : 'ultra_rare_') + (card.id || ('anon_' + Date.now())));
      }
    } catch (_) {}

    // v3 Phase 1z.223C — public friend activity submit (generic).
    // The backend (1z.223A/B) accepts ultra_rare_drop ONLY with
    // the strictly fixed privacy-safe shape: eventLabel "looted an
    // ultra-rare item", eventKey "ultra_rare", eventValue null,
    // rarity null. card.id, card.name, slot, rarity tier, pity
    // counter state, and any inventory identity are NEVER
    // forwarded — the Hunter-mode local row above retains the
    // card name privately on this device only.
    //
    // clientEventId is built from a per-card-id LOCALSTORAGE nonce
    // so repeat opens of the same reveal modal coalesce server-
    // side via UNIQUE(user_id, client_event_id), while distinct
    // ultra-rare drops produce distinct nonces. The card.id is
    // used only as the LOCAL lookup key for the nonce map; the
    // nonce itself is random and reveals no card identity.
    try {
      if (card && card.rarity === 'ultra_rare'
          && typeof _queuePublicAchievementEvent === 'function') {
        const nonce = _publicUltraRareNonce(card.id || null);
        _queuePublicAchievementEvent({
          eventType:       'ultra_rare_drop',
          eventKey:        'ultra_rare',
          eventLabel:      'looted an ultra-rare item',
          eventValue:      null,
          rarity:          null,
          clientEventId:   'ultra_rare:' + nonce,
          clientCreatedAt: new Date().toISOString(),
        });
      }
    } catch (_) {}

    // v3 Phase 1z.226C — generic public RARE-tier drop event.
    // Backend (1z.226A) accepts ultra-narrow shape: fixed eventKey
    // "rare", fixed eventLabel "found a rare item", null value &
    // rarity. card.id and card.name are NEVER forwarded — only
    // used as the local lookup key for the privacy-safe nonce
    // map. Gated to rarity === 'rare' so common drops never
    // surface publicly and the ultra-rare branch above stays
    // mutually exclusive (no double-submit).
    try {
      if (card && card.rarity === 'rare'
          && typeof _queuePublicAchievementEvent === 'function') {
        const nonce = _publicRareNonce(card.id || null);
        _queuePublicAchievementEvent({
          eventType:       'rare_item_drop',
          eventKey:        'rare',
          eventLabel:      'found a rare item',
          eventValue:      null,
          rarity:          null,
          clientEventId:   'rare:' + nonce,
          clientCreatedAt: new Date().toISOString(),
        });
      }
    } catch (_) {}

    // Populate fields.
    const slotIcon = SLOT_ICONS[card.slot] || '✦';
    overlay.className = 'reveal-overlay reveal-overlay--' + card.rarity;
    document.getElementById('reveal-slot-icon').textContent  = slotIcon;
    setModalCardArt('reveal-card-art-img', card.art_path);
    document.getElementById('reveal-card-name').textContent  = card.name;
    document.getElementById('reveal-card-source').textContent = 'From: ' + (BOSSES[card.source_boss] ? BOSSES[card.source_boss].name : '—');
    document.getElementById('reveal-card-rarity').textContent = RARITY_LABELS[card.rarity] || card.rarity;
    document.getElementById('reveal-card-flavor').textContent = card.flavor || '';
    const revealStats = document.getElementById('reveal-card-stats');
    if (revealStats) revealStats.innerHTML = cardStatBadgesHtml(card);

    overlay.classList.remove('hidden');
    // Force reflow so the .reveal-overlay--showing class triggers
    // the keyframe animations rather than instantly snapping.
    void overlay.offsetWidth;
    overlay.classList.add('reveal-overlay--showing');
    // v3 Phase 1z.74 — Sigil Bloom Relic Reveal (ClaudeDesign).
    // Replaces the 1z.73 confetti+chime celebration for first-
    // acquisition cinematic reveals. The boss-defeated modal path
    // still uses celebrateRareDrop for duplicate rare/ultra drops
    // (they don't reach this modal).
    try { if (card.rarity === 'mythic') { _runMegaReveal(card); } else { _runSigilBloom(card.rarity); } } catch (_) {}   // W296 — mythic = Eclipse Coronation
  }

  function closeCardRevealModal() {
    const overlay = document.getElementById('reveal-overlay');
    if (!overlay) return;
    overlay.classList.remove('reveal-overlay--showing');
    overlay.classList.add('reveal-overlay--closing');
    setTimeout(() => {
      overlay.classList.add('hidden');
      overlay.classList.remove('reveal-overlay--closing');
      document.body.classList.remove('reveal-locked');
      _revealActive = false;
      // v3 Phase 1z.74 — strip the sigil-bloom state so the next
      // reveal (if queued) starts clean.
      try { _teardownSigilBloom(); } catch (_) {}
      try { _teardownMegaReveal(); } catch (_) {}   // W296
      // Pop the head of the queue and chain to the next one if any.
      const inv = getInventory();
      if (inv.reveal_queue && inv.reveal_queue.length > 0) {
        inv.reveal_queue.shift();
        persistInventory();
      }
      // Re-render Pokédex if user is currently looking at Items tab,
      // so the new discovered card appears immediately.
      try { if (currentTab === 'items') renderPokedex(); } catch (_) {}
      // Continue queue.
      setTimeout(() => { try { processRevealQueue(); } catch (_) {} }, 250);
    }, 320); // matches CSS reveal-overlay--closing duration
  }

  function setupCardRevealModal() {
    const overlay = document.getElementById('reveal-overlay');
    if (!overlay) return;
    // v3 Phase 1z.75 — two-tap reveal for sigil bloom path.
    //   1st tap (bloom done, card not yet revealed) → reveal card.
    //   2nd tap (card revealed) → close modal.
    //   Common-drop fallback (no .reveal-overlay--sigil class) closes
    //   on first tap as before.
    overlay.addEventListener('click', () => {
      if (!overlay.classList.contains('reveal-overlay--showing')) return;
      if (overlay.classList.contains('reveal-overlay--mythic')) { try { _megaPointerTap(); } catch (_) {} return; }   // W296
      const isSigil = overlay.classList.contains('reveal-overlay--sigil');
      const cardRevealed = overlay.classList.contains('is-card-revealed');
      const bloomReady = overlay.classList.contains('is-bloom-ready');
      if (isSigil && bloomReady && !cardRevealed) {
        // Reveal the relic card; consume this tap. Next tap closes.
        overlay.classList.add('is-card-revealed');
        return;
      }
      if (isSigil && !bloomReady && !cardRevealed) {
        // User tapped DURING the bloom — let them skip ahead to the
        // reveal so the animation never feels gated.
        overlay.classList.add('is-bloom-ready', 'is-card-revealed');
        return;
      }
      closeCardRevealModal();
    });
    document.addEventListener('keydown', (e) => {
      if (e.key !== 'Escape') return;
      if (!overlay.classList.contains('reveal-overlay--showing')) return;
      // ESC always closes — bloom mid-flight or not.
      closeCardRevealModal();
    });
  }

  // ── v3 Phase 1g — Relic Archive helpers ───────────────────
  // Single source for "where did this drop?" copy. Used by the
  // archive grid and the mystery info modal. Returns a clean boss
  // display name or '' if the card has no source metadata. Never
  // returns the raw boss id (e.g. 'the_carouser') — we want
  // "The Carouser" everywhere user-facing.
  // v3 Phase 1z.7 — Relic Archive NEW state helpers.
  //
  // A relic enters NEW state the moment it lands in inventory (i.e.
  // `discovered: true` + `first_acquired_date` is set). NEW state
  // persists until the user explicitly views the relic — either by
  // tapping the discovered card in the archive (which opens the
  // detail modal) OR via the View Relic action on the Boss Defeated
  // overlay. We track per-relic via `hb_relic_seen_<cardId>` so the
  // chip flips cleanly without bookkeeping the entire inventory.
  //
  // NEW state intentionally does NOT live in CloudSync.SNAPSHOT_KEYS
  // (these are device-local "have I seen this on this device" flags;
  // restoring on a new device should re-surface every owned relic as
  // NEW until the user has actually seen it on that device).
  function _isRelicNew(cardId) {
    if (!cardId) return false;
    try {
      if (localStorage.getItem('hb_relic_seen_' + cardId) === '1') return false;
      const inv = (typeof getInventory === 'function') ? getInventory() : null;
      const entry = inv && inv.cards && inv.cards[cardId];
      return !!(entry && entry.discovered && entry.first_acquired_date);
    } catch (_) { return false; }
  }
  function _markRelicSeen(cardId) {
    if (!cardId) return;
    try { localStorage.setItem('hb_relic_seen_' + cardId, '1'); } catch (_) {}
  }
  function _countNewRelics() {
    try {
      if (typeof CARDS === 'undefined') return 0;
      return Object.keys(CARDS).filter(_isRelicNew).length;
    } catch (_) { return 0; }
  }

  // v3 Phase 1z.224 — Relic Archive header "NEW" badge with 24h
  // expiration. Pre-1z.224 the header count called _countNewRelics()
  // which counts every discovered relic that hasn't been viewed —
  // growing forever for hoarders. Product rule is now: the header
  // pill only counts relics acquired in the last 24 hours.
  //
  // Per-card NEW chips elsewhere (line ~7745) continue to use
  // _isRelicNew so individual cards can keep their "unviewed"
  // affordance; only the AGGREGATE badge is bounded.
  //
  // Storage: hb_relic_archive_new_since = { [cardId]: ms }. The
  // cardId is already on-device in inventory, so this key reveals
  // no new information. Timestamps are device-local ms. The map is
  // pruned of expired entries on every count call, so it can't
  // grow unbounded either.
  //
  // Legacy data migration: pre-1z.224 acquisitions have no
  // timestamp in this map. Per spec, those items quietly drop out
  // of the header count on first w88 render. Their seen-flag state
  // is preserved, so per-card chips still behave normally. Net
  // user-visible effect: stale "9 NEW" pill resets to 0 NEW on
  // first w88 boot until the next fresh acquisition.
  const _RELIC_NEW_SINCE_KEY  = 'hb_relic_archive_new_since';
  const _RELIC_NEW_WINDOW_MS  = 24 * 60 * 60 * 1000;

  function _readRelicArchiveNewSinceMap() {
    try {
      const raw = localStorage.getItem(_RELIC_NEW_SINCE_KEY);
      if (!raw) return {};
      const parsed = JSON.parse(raw);
      return (parsed && typeof parsed === 'object' && !Array.isArray(parsed)) ? parsed : {};
    } catch (_) { return {}; }
  }
  function _writeRelicArchiveNewSinceMap(map) {
    try { localStorage.setItem(_RELIC_NEW_SINCE_KEY, JSON.stringify(map || {})); } catch (_) {}
  }
  // Stamp a relic as "newly acquired right now." Called from the
  // two first-acquisition sites (rollBossDrop + forceDrop). No-op
  // for missing cardId or for already-stamped ids whose timestamp
  // is still inside the 24h window — avoids resetting a still-fresh
  // entry if the same drop path runs twice in quick succession.
  function _stampRelicArchiveNew(cardId) {
    if (!cardId) return;
    try {
      const map = _readRelicArchiveNewSinceMap();
      const now = Date.now();
      const existing = map[cardId];
      if (typeof existing === 'number' && (now - existing) < _RELIC_NEW_WINDOW_MS) return;
      map[cardId] = now;
      _writeRelicArchiveNewSinceMap(map);
    } catch (_) {}
  }
  // Bounded-list helper. Returns the array of cardIds whose
  // stamped time is within the 24h window. Also prunes stale
  // entries from the persisted map so it doesn't accumulate
  // forever even for unique-id collisions across long lifespans.
  function _activeRelicArchiveNewIds() {
    const map = _readRelicArchiveNewSinceMap();
    const now = Date.now();
    const fresh = [];
    let expiredCount = 0;
    let dirty = false;
    for (const cardId of Object.keys(map)) {
      const ts = map[cardId];
      if (typeof ts !== 'number' || !Number.isFinite(ts) || (now - ts) >= _RELIC_NEW_WINDOW_MS) {
        delete map[cardId];
        dirty = true;
        expiredCount++;
        continue;
      }
      fresh.push(cardId);
    }
    if (dirty) _writeRelicArchiveNewSinceMap(map);
    if (typeof _addHealthVerifyBreadcrumb === 'function' && expiredCount > 0) {
      try {
        _addHealthVerifyBreadcrumb('relic-archive-new-pruned', {
          beforeCount:  fresh.length + expiredCount,
          afterCount:   fresh.length,
          expiredCount: expiredCount,
        });
      } catch (_) {}
    }
    return fresh;
  }
  // Header pill counter. Uses the rolling-24h window only.
  function _countRelicArchiveNewLast24h() {
    return _activeRelicArchiveNewIds().length;
  }
  try {
    window._isRelicNew = _isRelicNew;
    window._markRelicSeen = _markRelicSeen;
    window._countNewRelics = _countNewRelics;
    window._stampRelicArchiveNew = _stampRelicArchiveNew;
    window._countRelicArchiveNewLast24h = _countRelicArchiveNewLast24h;
  } catch (_) {}

  function getCardDropSourceLabel(card) {
    if (!card) return '';
    const raw = card.source_boss || card.sourceBoss || card.boss ||
                card.boss_id    || card.drop_source || card.source || null;
    if (!raw) return '';
    if (typeof BOSSES !== 'undefined' && BOSSES[raw] && BOSSES[raw].name) {
      return BOSSES[raw].name;
    }
    // Fallback: prettify a snake_case id.
    return String(raw).split('_').map(w => w ? w.charAt(0).toUpperCase() + w.slice(1) : '').join(' ');
  }

  // Refreshes the "VIEW YOUR ARMORY" secondary line on the Items
  // tab with current Gear Power + equipped count. Called from
  // renderPokedex (every items-tab render) and after any equip /
  // unequip action so the CTA stays live. Safe no-op if the
  // helpers aren't loaded yet.
  function refreshArmoryCTAStatus() {
    const sub = document.getElementById('archive-armory-cta-sub');
    if (!sub) return;
    let power = 0;
    let equipped = 0;
    let total = (typeof HUNTER_BUILD_SLOT_COUNT === 'number') ? HUNTER_BUILD_SLOT_COUNT : 6;
    try {
      if (typeof aggregateBuildPower === 'function') power = aggregateBuildPower();
      if (typeof countEquippedBuildItems === 'function') equipped = countEquippedBuildItems();
    } catch (_) {}
    sub.textContent = 'Gear Power ' + power + ' · ' + equipped + ' / ' + total + ' Equipped';
  }

  // ── Pokédex (Items tab) ─────────────────────────────────────
  // Three sections grouped by rarity (Ultra-Rare → Rare → Common)
  // with discovered + undiscovered slots. Discovered card → tap to
  // open card detail. Undiscovered → open mystery info modal.
  // ════════════════════════════════════════════════════════════════════════
  // W570 — COLLECTION LOG (Items tab · Collection lens). Dungeons grouped by
  // RANK (co-op bosses merged into their rank, silently tagged) → bosses →
  // rare/ultra/mythic relic tiles with per-relic ×count + mystery states.
  // Built live from CARDS + BOSSES/COOP_BOSSES + hb_inventory — nothing is
  // hardcoded, so every current relic AND any future boss/drop auto-appears.
  // Commons are intentionally excluded (inventory, not collectibles).
  // ════════════════════════════════════════════════════════════════════════
  const _CL_RANK_HEX   = { E:'#8b5cf6', D:'#22d3ee', C:'#34d399', B:'#fbbf24', A:'#ef4444', S:'#e879f9', 'S+':'#facc15' };
  const _CL_RANK_ORDER = ['E','D','C','B','A','S','S+'];
  const _CL_RARTAG  = { rare:'RARE', ultra_rare:'ULTRA', mythic:'MYTHIC', legendary:'LEGENDARY' };
  const _CL_RARGLOW = { rare:'rgba(167,139,250,.30)', ultra_rare:'rgba(245,184,66,.32)', mythic:'rgba(251,113,133,.34)', legendary:'rgba(245,184,66,.32)' };
  const _CL_RARCLS  = { rare:'cl-r-rare', ultra_rare:'cl-r-ultra', mythic:'cl-r-mythic', legendary:'cl-r-ultra' };
  const _CL_RARHEX  = { rare:'#a78bfa', ultra_rare:'#f5b842', mythic:'#fb7185', legendary:'#f5b842' };
  const _CL_RARORD  = { mythic:0, legendary:1, ultra_rare:2, rare:3 };
  const _CL_SLOTG = {
    weapon:'<path d="M19 4l-9 9m-3 6l2-2m-2 2l-2 2m2-2l-2-2m12-13l-2 5-7 7" stroke="currentColor" stroke-width="1.6" fill="none" stroke-linecap="round" stroke-linejoin="round"/>',
    helm:'<path d="M4 13a8 8 0 0116 0v2H4zM8 15v3M16 15v3M12 15v4" stroke="currentColor" stroke-width="1.5" fill="none" stroke-linecap="round" stroke-linejoin="round"/>',
    amulet:'<path d="M8 3h8l-1 5a4 4 0 11-6 0z" stroke="currentColor" stroke-width="1.5" fill="none" stroke-linejoin="round"/><circle cx="12" cy="14" r="3" stroke="currentColor" stroke-width="1.5" fill="none"/>',
    boots:'<path d="M7 3v9l-2 2v5h11v-3l-3-2-1-2V3z" stroke="currentColor" stroke-width="1.5" fill="none" stroke-linejoin="round"/>',
    cape:'<path d="M8 3l4 2 4-2 2 16-6 2-6-2z" stroke="currentColor" stroke-width="1.5" fill="none" stroke-linejoin="round"/>',
    body:'<path d="M5 5l7-2 7 2-1 8-6 8-6-8z" stroke="currentColor" stroke-width="1.5" fill="none" stroke-linejoin="round"/>',
    gloves:'<path d="M6 9V5a1.5 1.5 0 013 0v3m0 0V4a1.5 1.5 0 013 0v4m0 0V5a1.5 1.5 0 013 0v6a6 6 0 01-12 0V9a1.5 1.5 0 013 0z" stroke="currentColor" stroke-width="1.4" fill="none" stroke-linejoin="round"/>',
    ring:'<circle cx="12" cy="14" r="6" stroke="currentColor" stroke-width="1.6" fill="none"/><path d="M9 7l3-4 3 4-3 2z" stroke="currentColor" stroke-width="1.4" fill="none" stroke-linejoin="round"/>',
  };
  const _CL_CHECK = '<svg viewBox="0 0 12 12"><path d="M2 6.4l2.6 2.6L10 3" stroke="currentColor" stroke-width="1.8" fill="none" stroke-linecap="round" stroke-linejoin="round"/></svg>';
  const _CL_LOCK  = '<svg viewBox="0 0 12 12"><rect x="2" y="5.2" width="8" height="5.3" rx="1.2" stroke="currentColor" stroke-width="1.2" fill="none"/><path d="M3.8 5.2V4a2.2 2.2 0 014.4 0v1.2" stroke="currentColor" stroke-width="1.2" fill="none"/></svg>';

  function _clHexA(hex, a) {
    try { const h = String(hex).replace('#',''); const n = parseInt(h.length === 3 ? h.split('').map(x=>x+x).join('') : h, 16);
      return 'rgba(' + ((n>>16)&255) + ',' + ((n>>8)&255) + ',' + (n&255) + ',' + a + ')'; } catch (_) { return 'rgba(139,92,246,' + a + ')'; }
  }
  function _clFmtDate(iso) {
    try { if (!iso) return ''; const d = new Date(String(iso).length <= 10 ? iso + 'T00:00:00' : iso); if (isNaN(d.getTime())) return '';
      return d.toLocaleDateString('en-US', { month: 'short', day: 'numeric' }); } catch (_) { return ''; }
  }

  // Live tree: [{rank, locked, current, have, total, bosses:[{name,coop,have,total,relics:[{id,name,rarity,slot,count,owned,date}]}]}]
  function _buildCollectionTree() {
    let inv = { cards: {} }; try { inv = getInventory() || inv; } catch (_) {}
    let playerRank = 'E'; try { playerRank = (getRank(totalPoints) || {}).id || 'E'; } catch (_) {}
    const pIdx = _CL_RANK_ORDER.indexOf(playerRank);
    const coop = (typeof COOP_BOSSES === 'object' && COOP_BOSSES) ? COOP_BOSSES : {};
    const byRank = {};
    for (const id in CARDS) {
      const c = CARDS[id];
      if (!c || !c.source_boss || c.rarity === 'common') continue;
      const b = (typeof BOSSES === 'object' && BOSSES && BOSSES[c.source_boss]) || coop[c.source_boss];
      if (!b) continue;
      const rank = b.rank || '?';
      const isCoop = !!(b.coopOnly || coop[c.source_boss]);
      byRank[rank] = byRank[rank] || {};
      const bg = byRank[rank][c.source_boss] = byRank[rank][c.source_boss] || { name: b.name || c.source_boss, coop: isCoop, relics: [] };
      const e = (inv.cards && inv.cards[id]) || {};
      bg.relics.push({ id: id, name: c.name, rarity: c.rarity, slot: c.slot, art: c.art_path || '', count: e.count || 0, owned: !!e.discovered, date: e.first_acquired_date || null });
    }
    // W697 — pool-driven boss nodes (the Grinning God). Its drop pool is the THREE
    // EXISTING mythics whose CARDS.source_boss point at their canonical bosses, so the
    // loop above never makes a node for it. Emit a display-only `shared` node so the
    // members raid shows its drop table (Nightfall/Reverie/Vigil). It is EXCLUDED from
    // the rank + overview aggregates so those same mythics aren't double-counted (they
    // already tally under Erebus / The Sleepless Crown).
    const _poolBossIds = {};
    try { if (typeof BOSSES === 'object' && BOSSES) for (const k in BOSSES) if (BOSSES[k] && BOSSES[k].pool) _poolBossIds[k] = 1; } catch (_) {}
    for (const k in coop) if (coop[k] && coop[k].pool) _poolBossIds[k] = 1;
    for (const bid in _poolBossIds) {
      const bDef = (typeof BOSSES === 'object' && BOSSES && BOSSES[bid]) || null;
      const cDef = coop[bid] || null;
      const pool = (bDef && bDef.pool) || (cDef && cDef.pool);
      if (!pool) continue;
      const meta = cDef || bDef || {};
      const rank = meta.rank || '?';
      byRank[rank] = byRank[rank] || {};
      if (byRank[rank][bid]) continue;   // a real source_boss card already owns this node
      const bg = byRank[rank][bid] = { name: meta.name || bid, coop: true, shared: true, relics: [] };
      const seen = {};
      for (const rar in pool) (pool[rar] || []).forEach(cid => {
        if (seen[cid]) return; seen[cid] = 1;
        const c = CARDS[cid]; if (!c) return;
        const e = (inv.cards && inv.cards[cid]) || {};
        bg.relics.push({ id: cid, name: c.name, rarity: c.rarity, slot: c.slot, art: c.art_path || '', count: e.count || 0, owned: !!e.discovered, date: e.first_acquired_date || null });
      });
    }
    const out = [];
    for (const rank of _CL_RANK_ORDER) {
      if (!byRank[rank]) continue;
      const locked = pIdx >= 0 && _CL_RANK_ORDER.indexOf(rank) > pIdx;
      const bosses = Object.keys(byRank[rank])
        .sort((a, b) => (byRank[rank][a].coop ? 1 : 0) - (byRank[rank][b].coop ? 1 : 0) || byRank[rank][a].name.localeCompare(byRank[rank][b].name))
        .map(bid => {
          const bg = byRank[rank][bid];
          bg.relics.sort((x, y) => (_CL_RARORD[x.rarity] - _CL_RARORD[y.rarity]) || x.name.localeCompare(y.name));
          const have = bg.relics.filter(r => r.owned).length;
          return { name: bg.name, coop: bg.coop, shared: !!bg.shared, relics: bg.relics, have: have, total: bg.relics.length };
        });
      // W697 — a `shared` pool node (the raid) renders its own block + local seal but is
      // NOT summed into the rank-gate totals (its mythics already count under their
      // canonical boss); double-counting would inflate the S-gate 'X / Y relics'.
      let have = 0, total = 0; bosses.forEach(b => { if (b.shared) return; have += b.have; total += b.total; });
      out.push({ rank: rank, locked: locked, current: rank === playerRank, bosses: bosses, have: have, total: total });
    }
    return out;
  }

  function _clRelicTile(r, locked) {
    const rcls = _CL_RARCLS[r.rarity] || 'cl-r-rare';
    const tag = _CL_RARTAG[r.rarity] || 'RARE';
    const hex = _CL_RARHEX[r.rarity] || '#a78bfa';
    const glyph = _CL_SLOTG[r.slot] || '';
    if (!r.owned) {
      return '<div class="cl-relic cl-mystery ' + rcls + '">' +
        '<div class="cl-art cl-myst">' +
          '<svg class="cl-slot" viewBox="0 0 24 24" style="color:' + hex + '">' + glyph + '</svg>' +
          '<span class="cl-q">?</span>' +
          '<span class="cl-rbadge cl-ghost ' + rcls + '" style="--bc:' + hex + '">' + tag + '</span>' +
        '</div>' +
        '<div class="cl-cmeta">' +
          '<div class="cl-cname cl-muted">' + (locked ? 'Sealed' : 'Undiscovered') + '</div>' +
          '<div class="cl-cdate">' + (locked ? 'Gate not yet open' : 'Not yet pulled') + '</div>' +
        '</div>' +
      '</div>';
    }
    const cnt = (r.count > 0) ? '<span class="cl-cnt"><span class="x">×</span><span class="nn">' + r.count + '</span></span>' : '';
    const dateStr = _clFmtDate(r.date);
    return '<div class="cl-relic ' + rcls + '">' +
      '<div class="cl-art" style="--glow:' + (_CL_RARGLOW[r.rarity] || '') + '">' +
        '<svg class="cl-slot" viewBox="0 0 24 24" style="color:' + hex + '">' + glyph + '</svg>' +
        (r.art ? '<img class="cl-art-img" data-cl-art="' + esc(r.art) + '" alt="" />' : '') +
        '<span class="cl-rbadge ' + rcls + '">' + tag + '</span>' + cnt +
      '</div>' +
      '<div class="cl-cmeta">' +
        '<div class="cl-cname">' + esc(r.name) + '</div>' +
        '<div class="cl-cdate"><span class="dt"></span>' + (dateStr ? 'First · ' + esc(dateStr) : 'Owned') + '</div>' +
      '</div>' +
    '</div>';
  }

  function _clBossBlock(b, locked) {
    const done = b.total > 0 && b.have === b.total && !locked;
    const seal = done ? '<span class="cl-bseal">' + _CL_CHECK + 'Full Clear</span>' : '<span class="cl-bfrac">' + b.have + ' / ' + b.total + '</span>';
    const coopTag = b.coop ? '<span class="cl-coop">Co-op</span>' : '';
    return '<div class="cl-boss' + (done ? ' cl-done' : '') + '">' +
      '<div class="cl-boss-head">' +
        '<svg class="cl-bossico" viewBox="0 0 22 22"><path d="M11 2l2.4 5.3L19 8l-4 3.7 1 5.5L11 14.6 6 17.2l1-5.5L3 8l5.6-.7z" stroke="currentColor" stroke-width="1.3" fill="none" stroke-linejoin="round"/></svg>' +
        '<span class="cl-bname">' + esc(b.name) + coopTag + '</span>' + seal +
      '</div>' +
      '<div class="cl-grid">' + b.relics.map(r => _clRelicTile(r, locked)).join('') + '</div>' +
    '</div>';
  }

  function _clDungeonSection(d) {
    const hex = _CL_RANK_HEX[d.rank] || '#8b5cf6';
    const soft = _clHexA(hex, 0.16), glow = _clHexA(hex, 0.22);
    const pct = d.total ? Math.round(d.have / d.total * 100) : 0;
    const done = d.total > 0 && d.have === d.total && !d.locked;
    let sub, right;
    if (d.locked) {
      sub = '<span class="cl-lockpill">' + _CL_LOCK + 'Rank ' + d.rank + ' required</span>';
      right = '<span class="cl-dfrac"><b>0</b> / ' + d.total + '</span><span class="cl-dbar"><i style="width:0%"></i></span>';
    } else if (done) {
      sub = '<span class="cl-gateseal">' + _CL_CHECK + 'Gate Cleared</span>';
      right = '<span class="cl-dfrac"><b>' + d.have + '</b> / ' + d.total + '</span><span class="cl-dbar"><i style="width:100%"></i></span>';
    } else {
      sub = d.current ? '<span class="cl-curpill">Current Gate</span>' : '';
      right = '<span class="cl-dfrac"><b>' + d.have + '</b> / ' + d.total + '</span><span class="cl-dbar"><i style="width:' + pct + '%"></i></span>';
    }
    const banner = d.locked
      ? '<div class="cl-sealbanner"><span class="lk">' + _CL_LOCK + '</span><span class="lt">Gate sealed — reach Rank ' + d.rank + ' to enter<span>Its relics remain unknown until the gate yields.</span></span></div>'
      : '';
    const open = d.current && !d.locked;
    return '<div class="cl-dungeon' + (open ? ' cl-open' : '') + (done ? ' cl-done' : '') + (d.locked ? ' cl-locked' : '') + '" ' +
        'style="--rc:' + hex + ';--rcs:' + soft + ';--rcg:' + glow + '">' +
      '<button class="cl-dhead" type="button">' +
        '<span class="cl-dcrest"><svg viewBox="0 0 40 40"><path d="M20 2.5L37.5 20 20 37.5 2.5 20Z" fill="var(--rcs)" stroke="var(--rc)" stroke-width="1.5"/></svg><b>' + d.rank + '</b></span>' +
        '<span class="cl-dtitle"><span class="cl-dname">' + d.rank + '-Rank Gate</span>' + (sub ? '<span class="cl-dsub">' + sub + '</span>' : '') + '</span>' +
        '<span class="cl-dright">' + right + '</span>' +
        '<span class="cl-dchev"><svg width="9" height="14" viewBox="0 0 9 14" fill="none"><path d="M1.5 1.5l6 5.5-6 5.5" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round"/></svg></span>' +
      '</button>' +
      '<div class="cl-dbody"><div class="cl-dinner"><div class="cl-dgate">' + banner + d.bosses.map(b => _clBossBlock(b, d.locked)).join('') + '</div></div></div>' +
    '</div>';
  }

  // W571 — reveal-on-load relic art (matches the app's robust loader pattern:
  // no inline onerror; img starts hidden, fades in on load, drops to the slot
  // glyph behind it on error). Owned relics show their real art_path image.
  function _clLoadArt(scope) {
    try {
      const imgs = (scope || document).querySelectorAll('img.cl-art-img[data-cl-art]:not([data-cl-armed])');
      imgs.forEach(function (img) {
        img.setAttribute('data-cl-armed', '1');
        const src = img.getAttribute('data-cl-art'); if (!src) { img.remove(); return; }
        img.addEventListener('load', function () { img.classList.add('cl-on'); });
        img.addEventListener('error', function () { try { img.remove(); } catch (_) {} });
        img.src = src;
      });
    } catch (_) {}
  }

  function renderCollectionLog() {
    const root = document.getElementById('cl-dungeons');
    if (!root) return;
    const tree = _buildCollectionTree();
    root.innerHTML = tree.map(_clDungeonSection).join('');
    try { _clLoadArt(root); } catch (_) {}
    let have = 0, total = 0, gatesCleared = 0, bossesMastered = 0, ultraHave = 0, ultraTotal = 0;
    tree.forEach(d => {
      have += d.have; total += d.total;
      if (!d.locked && d.total > 0 && d.have === d.total) gatesCleared++;
      d.bosses.forEach(b => {
        if (b.shared) return;   // W697 — the raid's pool node mirrors already-counted mythics; don't double-count them in Ultra Relics / Bosses Mastered
        if (!d.locked && b.total > 0 && b.have === b.total) bossesMastered++;
        b.relics.forEach(r => { if (r.rarity === 'ultra_rare' || r.rarity === 'mythic') { ultraTotal++; if (r.owned) ultraHave++; } });
      });
    });
    const pct = total ? Math.round(have / total * 100) : 0;
    const set = (id, v) => { const el = document.getElementById(id); if (el) el.textContent = v; };
    set('cl-ovHave', have); set('cl-ovTotal', '/ ' + total + ' relics'); set('cl-ovPct', pct + '%');
    const bar = document.getElementById('cl-ovBar'); if (bar) bar.style.width = pct + '%';
    const stats = document.getElementById('cl-ovStats');
    if (stats) stats.innerHTML =
      '<div class="cl-h-stat"><div class="sv"><b>' + gatesCleared + '</b> / ' + tree.length + '</div><div class="sl">Gates Cleared</div></div>' +
      '<div class="cl-h-stat"><div class="sv"><b>' + bossesMastered + '</b></div><div class="sl">Bosses Mastered</div></div>' +
      '<div class="cl-h-stat"><div class="sv"><b>' + ultraHave + '</b> / ' + ultraTotal + '</div><div class="sl">Ultra Relics</div></div>';
  }

  function _clSwitchLens(mode) {
    const arch = document.getElementById('items-archive');
    const coll = document.getElementById('items-collection');
    const lens = document.getElementById('cl-lens');
    if (!arch || !coll || !lens) return;
    const isColl = mode === 'collection';
    coll.classList.toggle('cl-show', isColl);
    arch.classList.toggle('hidden', isColl);
    lens.classList.toggle('cl-on-collection', isColl);
    lens.querySelectorAll('button').forEach(b => b.setAttribute('data-on', b.getAttribute('data-mode') === mode ? '1' : '0'));
    if (isColl) { try { renderCollectionLog(); } catch (_) {} }
  }
  function _clWire() {
    const lens = document.getElementById('cl-lens');
    if (lens && lens.getAttribute('data-wired') !== '1') {
      lens.setAttribute('data-wired', '1');
      lens.addEventListener('click', e => { const b = e.target.closest('button'); if (b) _clSwitchLens(b.getAttribute('data-mode')); });
    }
    const dg = document.getElementById('cl-dungeons');
    if (dg && dg.getAttribute('data-wired') !== '1') {
      dg.setAttribute('data-wired', '1');
      dg.addEventListener('click', e => { const h = e.target.closest('.cl-dhead'); if (h) h.closest('.cl-dungeon').classList.toggle('cl-open'); });
    }
  }
  try { window.renderCollectionLog = renderCollectionLog; } catch (_) {}


  function renderPokedex() {
    const root = document.getElementById('pokedex-sections');
    if (!root) return;

    const inv = getInventory();
    const allIds = Object.keys(CARDS);
    // W773 — the header's DISCOVERED counter / % Complete / progress-bar writes are
    // gone with the header itself (owner: Collection Log owns completion; the two
    // surfaces counted different pools and read as contradictory). Per-rarity
    // counts on the group cards below are untouched.

    // v3 Phase 1z.7 + 1z.224 — "1 NEW" header counter (gold pulse
    // pill). 1z.224 swap: now counts only relics acquired within
    // the last 24 hours via _countRelicArchiveNewLast24h, instead
    // of the unbounded "discovered but unviewed" set. Hidden when
    // no fresh relics qualify.
    try {
      const newCountEl = document.getElementById('archive-new-count');
      if (newCountEl) {
        const n = _countRelicArchiveNewLast24h();
        if (n > 0) {
          newCountEl.textContent = n + ' NEW';
          newCountEl.classList.remove('hidden');
        } else {
          newCountEl.classList.add('hidden');
        }
      }
    } catch (_) {}

    const sections = [
      { key: 'mythic',     label: 'MEGA RARE' },
      { key: 'ultra_rare', label: 'ULTRA-RARE RELICS' },
      { key: 'rare',       label: 'RARE RELICS' },
      { key: 'common',     label: 'COMMON RELICS' },
    ];
    // W475 — ClaudeDesign Relic Archive refresh: per-rarity accent colour, sigil,
    // and sub-label powering the enriched section headers (accent bar + glyph +
    // sub-label + per-section mini progress bar). Keys match the section keys.
    const ARCHIVE_RARITY_META = {
      mythic:     { ac: '#5eead4', acg: 'rgba(94,234,212,.5)',  sub: 'Mythic · trophy of the hunt',
        glyph: '<path d="M11 2l2.6 5.8L20 8.6l-5 4.2 1.6 6.2L11 15.6 5.4 19l1.6-6.2-5-4.2 6.4-.8z" stroke="currentColor" stroke-width="1.4" fill="none" stroke-linejoin="round"/>' },
      ultra_rare: { ac: '#f5b842', acg: 'rgba(245,184,66,.5)',  sub: 'Best-in-slot drops',
        glyph: '<path d="M11 3l5 4v8l-5 4-5-4V7z" stroke="currentColor" stroke-width="1.4" fill="none" stroke-linejoin="round"/><path d="M11 7v8M7 9l8 4M15 9l-8 4" stroke="currentColor" stroke-width="1.1" fill="none" stroke-linecap="round"/>' },
      rare:       { ac: '#a78bfa', acg: 'rgba(167,139,250,.5)', sub: 'Notable finds',
        glyph: '<path d="M11 3l6 4-2 11H7L5 7z" stroke="currentColor" stroke-width="1.4" fill="none" stroke-linejoin="round"/>' },
      common:     { ac: '#9aa0bd', acg: 'transparent',          sub: 'Steady gains',
        glyph: '<circle cx="11" cy="11" r="7" stroke="currentColor" stroke-width="1.4" fill="none"/><circle cx="11" cy="11" r="3" stroke="currentColor" stroke-width="1.3" fill="none"/>' },
    };

    const collapsed = loadPokedexCollapsed();
    const eqPwrBySlot = _equippedPowerBySlot();   // W450 — baseline for the "vs equipped" deltas

    const sectionsHtml = sections.map(s => {
      const sectionCards = allIds
        .map(id => CARDS[id])
        .filter(c => c.rarity === s.key);
      const sectionDiscovered = sectionCards.filter(c => inv.cards[c.id] && inv.cards[c.id].discovered).length;
      const sectionTotal = sectionCards.length;
      const isCollapsed = collapsed.has(s.key);
      // v3 Phase 1g — display order is now ACQUISITION CHRONOLOGY,
      // not CARDS-definition order. Discovered cards sort by
      // first_acquired_date ASC (earliest first) so the archive
      // reads like a discovery log. Undiscovered silhouettes get
      // appended after — EXCEPT in the COMMON section, where they
      // clutter (the user expects commons to roll in passively;
      // teasing them adds noise, not motivation). Rare + ultra
      // sections still show mystery slots to motivate hunting.
      let discoveredCards = sectionCards
        .filter(c => inv.cards[c.id] && inv.cards[c.id].discovered);
      // W450 — archetype filter (melee/ranged/magic) applied WITHIN the rarity section, so the
      // categories survive. Default order is acquisition chronology (the discovery log); the PWR
      // toggle re-sorts by power desc instead.
      if (_pokedexArch !== 'all') discoveredCards = discoveredCards.filter(c => _relicProfile(c).arch === _pokedexArch);
      discoveredCards.sort((a, b) => {
        if (_pokedexSortPwr) {
          const pa = _relicProfile(a).power, pb = _relicProfile(b).power;
          if (pa !== pb) return pb - pa;
        } else {
          const da = (inv.cards[a.id] && inv.cards[a.id].first_acquired_date) || '';
          const db = (inv.cards[b.id] && inv.cards[b.id].first_acquired_date) || '';
          if (da !== db) { if (!da) return -1; if (!db) return 1; return da.localeCompare(db); }
        }
        return (a.name || '').localeCompare(b.name || '');
      });
      // Undiscovered silhouettes hide when a specific archetype is selected (class is unknown
      // until discovered) — and always in the common section.
      const undiscoveredCards = (s.key === 'common' || _pokedexArch !== 'all')
        ? []
        : sectionCards.filter(c => !(inv.cards[c.id] && inv.cards[c.id].discovered));
      const visibleCards = discoveredCards.concat(undiscoveredCards);
      const cardsHtml = visibleCards.map(c => {
        const entry = inv.cards[c.id] || { discovered: false, count: 0 };
        const slotIcon = SLOT_ICONS[c.slot] || '✦';
        // v3 Phase 1g — slot + source helpers, scoped here so the
        // archive grid renders the same identity surface every card
        // shows in the detail modal.
        const slotKey = (typeof getCardEquipmentSlot === 'function') ? getCardEquipmentSlot(c) : (c.slot || null);
        const slotDef = (slotKey != null && typeof EQUIPMENT_SLOT_INDEX !== 'undefined' && typeof EQUIPMENT_SLOTS !== 'undefined')
          ? EQUIPMENT_SLOTS[EQUIPMENT_SLOT_INDEX[slotKey]] : null;
        const slotLabel = slotDef ? slotDef.label : (slotKey ? slotKey.toUpperCase() : '');
        const slotBadge = slotLabel
          ? '<span class="archive-slot-badge">' + esc(slotLabel) + '</span>'
          : '';
        const sourceLabel = (typeof getCardDropSourceLabel === 'function') ? getCardDropSourceLabel(c) : '';
        const sourceLine = sourceLabel
          ? '<div class="archive-item-source">' + esc(sourceLabel) + '</div>'
          : '';

        if (entry.discovered) {
          // Real art layered ON TOP of the emoji fallback. If art_path
          // 404s (most cards still placeholder), the post-render
          // attachCardArtFallback() removes the <img>, leaving the
          // emoji + rarity gradient visible underneath. Successful
          // loads cover the fallback with object-fit: cover.
          const artImg = c.art_path
            ? '<img class="pokedex-card-art-img" src="' + esc(c.art_path) + '" alt="" data-card-art="1">'
            : '';
          // v3 Phase 1d — equipped badge reads Hunter Build state
          const isEq = (typeof isItemEquippedInBuild === 'function') && isItemEquippedInBuild(c.id);
          // v3 Phase 1z.7 — NEW chip supersedes EQUIPPED until user
          // taps the card. Sparkle glyph + gold gradient + shimmer.
          const isNew = _isRelicNew(c.id);
          let chip = '';
          if (isNew) {
            chip = '<span class="archive-card-new-chip" aria-label="Newly acquired"><span class="archive-card-new-spark" aria-hidden="true">✦</span>NEW</span>';
          } else if (isEq) {
            chip = '<span class="pokedex-card-equipped-badge archive-equipped-badge" aria-label="Equipped">EQUIPPED</span>';
          }
          const newCls = isNew ? ' archive-card--new archive-card--new-' + c.rarity : '';
          // W450 — role + power signals. Role chip (dominant combat-triangle role: Melee/
          // Ranger/Mage) + PWR badge in the art footer; a power meter + a "vs equipped" delta.
          const prof = _relicProfile(c);
          const artFoot =
            '<div class="pdx-artfoot">' +
              '<span class="pdx-class" style="--cc:' + esc(prof.classColor) + '"><svg viewBox="0 0 14 14" aria-hidden="true">' + prof.classGlyph + '</svg>' + esc(prof.className) + '</span>' +
              '<span class="pdx-pwr"><span class="pn">' + prof.power + '</span><span class="pl">PWR</span></span>' +
            '</div>';
          const eqP = eqPwrBySlot[slotKey] || 0;
          let deltaHtml;
          if (isEq) deltaHtml = '<span class="pdx-delta pdx-delta--best">★ Equipped · Best</span>';
          else if (eqP === 0) deltaHtml = '<span class="pdx-delta pdx-delta--gain">▲ +' + prof.power + ' Equip Gain</span>';
          else { const d = prof.power - eqP; deltaHtml = d > 0 ? '<span class="pdx-delta pdx-delta--up">▲ +' + d + ' vs Equipped</span>' : d < 0 ? '<span class="pdx-delta pdx-delta--down">▼ ' + d + ' vs Equipped</span>' : '<span class="pdx-delta pdx-delta--down">= Even vs Equipped</span>'; }
          const pMeter = '<div class="pdx-pmeter"><i style="width:' + Math.max(4, Math.min(100, prof.power)) + '%;background:' + esc(prof.classColor) + '"></i></div>';
          return '<div class="pokedex-cell">' + (
            '<button class="pokedex-card pokedex-card--' + c.rarity + (isEq ? ' pokedex-card--equipped' : '') + newCls + '" type="button" data-card-id="' + esc(c.id) + '">' +
              '<div class="pokedex-card-art">' +
                '<span class="pokedex-card-slot-icon">' + slotIcon + '</span>' +
                artImg +
                slotBadge +
                chip +
                artFoot +
              '</div>' +
              '<div class="pokedex-card-name">' + esc(c.name) +
                ((entry.count || 0) > 1 ? ' <span class="pdx-count" aria-label="' + (entry.count || 0) + ' owned">×' + (entry.count || 0) + '</span>' : '') +
              '</div>' +
              sourceLine +
              pMeter +
              deltaHtml +
            '</button>'
          ) + _marketAffordanceHtml(c, entry) + '</div>';
        }
        // Undiscovered mystery card — show "?" + rarity teaser +
        // source hint so the user knows where to hunt. Item name
        // stays hidden until discovered.
        const rarityTeaser = RARITY_LABELS[c.rarity] || c.rarity;
        const mysteryHint = sourceLabel
          ? 'Drops from ' + sourceLabel
          : 'Defeat dungeon bosses to discover';
        return '<div class="pokedex-cell">' + (
          '<button class="pokedex-card pokedex-card--undiscovered pokedex-card--' + c.rarity + ' archive-mystery-card" type="button" data-card-id="' + esc(c.id) + '">' +
            '<div class="pokedex-card-art pokedex-card-art--undiscovered">' +
              '<span class="pokedex-card-mystery archive-mystery-mark">?</span>' +
              slotBadge +
            '</div>' +
            '<div class="archive-mystery-rarity">' + esc(rarityTeaser) + '</div>' +
            '<div class="archive-mystery-hint">' + esc(mysteryHint) + '</div>' +
          '</button>'
        ) + _marketAffordanceHtml(c, entry) + '</div>';
      }).join('');
      const bodyHtml = visibleCards.length === 0
        ? '<div class="pokedex-section-empty">No items in this tier yet.</div>'
        : '<div class="pokedex-grid">' + cardsHtml + '</div>';
      const headerExtra = s.key === 'mythic' ? ' archive-rarity-header--mythic' : (s.key === 'ultra_rare' ? ' archive-rarity-header--ultra' : '');
      const rm = ARCHIVE_RARITY_META[s.key] || ARCHIVE_RARITY_META.common;
      const secPct = sectionTotal > 0 ? Math.round(sectionDiscovered / sectionTotal * 100) : 0;
      return (
        '<div class="pokedex-section pokedex-section--' + s.key + (isCollapsed ? ' pokedex-section--collapsed' : '') + '" data-section-key="' + s.key + '" style="--ac:' + rm.ac + ';--acg:' + rm.acg + '">' +
          '<button class="pokedex-section-header archive-rarity-header' + headerExtra + '" type="button" data-section-toggle="' + s.key + '" aria-expanded="' + (isCollapsed ? 'false' : 'true') + '">' +
            '<span class="pdx-sec-accent" aria-hidden="true"></span>' +
            '<svg class="pdx-sec-glyph" viewBox="0 0 22 22" aria-hidden="true">' + rm.glyph + '</svg>' +
            '<span class="pdx-sec-titlewrap">' +
              '<span class="pokedex-section-label">' + s.label + '</span>' +
              '<span class="pdx-sec-sub">' + rm.sub + '</span>' +
            '</span>' +
            '<span class="pdx-sec-right">' +
              '<span class="pokedex-section-count"><b>' + sectionDiscovered + '</b> / ' + sectionTotal + '</span>' +
              '<span class="pdx-sec-minibar"><i style="width:' + secPct + '%"></i></span>' +
            '</span>' +
            '<span class="pokedex-section-chevron" aria-hidden="true"><svg viewBox="0 0 9 14" width="9" height="14" fill="none"><path d="M1.5 1.5l6 5.5-6 5.5" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round"/></svg></span>' +
          '</button>' +
          '<div class="pokedex-section-body">' + bodyHtml + '</div>' +
        '</div>'
      );
    }).join('');
    // W450 — the archetype filter + PWR sort ride above the rarity sections (which are preserved).
    root.innerHTML = _pokedexFilterBarHtml() + sectionsHtml;

    // Attach error handlers to all card-art images so a 404 cleanly
    // falls back to the emoji + rarity gradient underneath. inline
    // onerror would work but post-attach keeps the markup CSP-clean.
    root.querySelectorAll('img[data-card-art="1"]').forEach(img => {
      img.addEventListener('error', () => { img.remove(); }, { once: true });
    });

    // v3 Phase 1g — refresh the Armory CTA secondary status line so
    // it reflects current Gear Power + equipped count whenever the
    // archive re-renders (which fires after every equip/unequip).
    try { refreshArmoryCTAStatus(); } catch (_) {}

    // Relic Marketplace — wire the affordance + sheet delegation (idempotent).
    try { setupMarketplace(); } catch (_) {}
  }

  // Builds the stat-bonus badge row for a card. Returns an empty
  // string if all bonuses are zero (defensive — current launch set
  // always has at least one non-zero, but future items might be
  // cosmetic-only). One badge per non-zero stat, tinted with the
  // stat's color (CSS handles tint per .stat-badge--<id> modifier).
  // Order matches CLAUDE.md canonical: STR, VIT, INT, FOCUS, WILL, WLT.
  function cardStatBadgesHtml(card) {
    if (!card || !card.bonuses) return '';
    const order = ['str', 'vit', 'int', 'focus', 'will', 'wlt'];
    const labels = { str: 'STR', vit: 'VIT', int: 'INT', focus: 'FOCUS', will: 'WILL', wlt: 'WLT' };
    const icons  = {
      str:   'assets/stat-icons/stat-str.png',
      vit:   'assets/stat-icons/stat-vit.png',
      int:   'assets/stat-icons/stat-int.png',
      focus: 'assets/stat-icons/stat-focus.png',
      will:  'assets/stat-icons/stat-will.png',
      wlt:   'assets/stat-icons/stat-wlt.png',
    };
    const badges = order
      .filter(k => (card.bonuses[k] || 0) > 0)
      .map(k => (
        '<span class="stat-badge stat-badge--' + k + '">' +
          '<img class="stat-badge-icon" src="' + icons[k] + '" alt="" aria-hidden="true">' +
          '<span class="stat-badge-value">+' + card.bonuses[k] + '</span>' +
          '<span class="stat-badge-label">' + labels[k] + '</span>' +
        '</span>'
      ));
    if (badges.length === 0) return '';
    return '<div class="stat-row">' + badges.join('') + '</div>';
  }

  // Sets a card-art image src on a fixed-id <img> element used by the
  // reveal + carddetail modals. Cleanly hides the img on 404 so the
  // emoji slot icon underneath remains visible.
  function setModalCardArt(imgId, artPath) {
    const img = document.getElementById(imgId);
    if (!img) return;
    img.onerror = () => { img.style.display = 'none'; };
    img.onload  = () => { img.style.display = ''; };
    img.style.display = 'none';   // start hidden; onload reveals
    if (artPath) {
      img.src = artPath;
    } else {
      img.removeAttribute('src');
    }
  }

  // Persisted set of collapsed pokedex section keys. Default: ALL collapsed.
  // First-time visitors see a tidy stacked list of dropdown headers and tap
  // open whichever tier they want to browse.
  function loadPokedexCollapsed() {
    const ALL_KEYS = ['ultra_rare', 'rare', 'common'];
    try {
      const raw = localStorage.getItem('hb_pokedex_collapsed');
      if (!raw) return new Set(ALL_KEYS);
      const arr = JSON.parse(raw);
      return new Set(Array.isArray(arr) ? arr : ALL_KEYS);
    } catch (_) { return new Set(ALL_KEYS); }
  }
  function savePokedexCollapsed(set) {
    try { localStorage.setItem('hb_pokedex_collapsed', JSON.stringify([...set])); } catch (_) {}
  }
  function togglePokedexSection(key) {
    const set = loadPokedexCollapsed();
    if (set.has(key)) set.delete(key); else set.add(key);
    savePokedexCollapsed(set);
  }

  function setupPokedex() {
    const root = document.getElementById('pokedex-sections');
    if (!root) return;
    root.addEventListener('click', (e) => {
      // W616 — Rewards / Drop History (delegated: the filter bar re-renders).
      const rewBtn = e.target.closest('[data-drop-history]');
      if (rewBtn) { try { _audCue('ui_tap'); } catch (_) {} try { if (typeof openDropLedger === 'function') openDropLedger(); } catch (_) {} return; }
      // W450 — archetype filter + PWR sort (short-circuit before the card/section paths).
      const archBtn = e.target.closest('[data-pdx-arch]');
      if (archBtn) { _pokedexArch = archBtn.getAttribute('data-pdx-arch') || 'all'; try { _audCue('ui_tap'); } catch (_) {} renderPokedex(); return; }
      const sortBtn = e.target.closest('[data-pdx-sort]');
      if (sortBtn) { _pokedexSortPwr = !_pokedexSortPwr; try { _audCue('ui_tap'); } catch (_) {} renderPokedex(); return; }
      // Section-header toggle (collapsible). Check first so it short-circuits
      // before the card-click path.
      const hdr = e.target.closest('[data-section-toggle]');
      if (hdr) {
        const key = hdr.getAttribute('data-section-toggle');
        togglePokedexSection(key);
        const section = hdr.closest('.pokedex-section');
        if (section) {
          const nowCollapsed = section.classList.toggle('pokedex-section--collapsed');
          hdr.setAttribute('aria-expanded', nowCollapsed ? 'false' : 'true');
        }
        return;
      }
      const btn = e.target.closest('.pokedex-card[data-card-id]');
      if (!btn) return;
      const id = btn.getAttribute('data-card-id');
      const card = CARDS[id];
      if (!card) return;
      const entry = getInventory().cards[id];
      if (!entry || !entry.discovered) {
        // v3 Phase 1g — undiscovered tap opens the mystery info
        // modal (rarity + source teaser + "Hunt Boss" CTA). Never
        // reveals the item name.
        openMysteryCardModal(card);
        return;
      }
      // v3 Phase 1z.7 — clear NEW state for this card. Re-render the
      // archive so the chip + header counter flip immediately, then
      // open the detail modal.
      try { _markRelicSeen(id); } catch (_) {}
      try { renderPokedex(); } catch (_) {}
      openCardDetailModal(card, entry);
    });
  }

  // ── v3 Phase 1g — Mystery (undiscovered) info modal ─────────
  function openMysteryCardModal(card) {
    const overlay = document.getElementById('mystery-card-overlay');
    const modal   = document.getElementById('mystery-card-modal');
    if (!overlay || !modal || !card) return;
    const rarityEl = document.getElementById('mystery-card-rarity');
    const sourceEl = document.getElementById('mystery-card-source');
    const howEl    = document.getElementById('mystery-card-howto');
    const huntBtn  = document.getElementById('mystery-card-hunt');
    if (rarityEl) rarityEl.textContent = (RARITY_LABELS && RARITY_LABELS[card.rarity]) || card.rarity || '—';
    const sourceLabel = getCardDropSourceLabel(card);
    if (sourceEl) sourceEl.textContent = sourceLabel || 'Unknown';
    if (howEl) howEl.textContent = sourceLabel
      ? 'Defeat this boss for a chance to reveal this relic.'
      : 'Defeat dungeon bosses to discover this relic.';
    if (huntBtn) huntBtn.disabled = !sourceLabel; // No boss known → can't navigate
    overlay.classList.remove('hidden');
    modal.classList.remove('hidden');
  }
  function closeMysteryCardModal() {
    const overlay = document.getElementById('mystery-card-overlay');
    const modal   = document.getElementById('mystery-card-modal');
    if (overlay) overlay.classList.add('hidden');
    if (modal)   modal.classList.add('hidden');
  }
  function setupMysteryCardModal() {
    const overlay = document.getElementById('mystery-card-overlay');
    const closeBtn = document.getElementById('mystery-card-close');
    const cancelBtn = document.getElementById('mystery-card-cancel');
    const huntBtn = document.getElementById('mystery-card-hunt');
    if (overlay)   overlay.addEventListener('click', closeMysteryCardModal);
    if (closeBtn)  closeBtn.addEventListener('click', closeMysteryCardModal);
    if (cancelBtn) cancelBtn.addEventListener('click', closeMysteryCardModal);
    if (huntBtn) {
      huntBtn.addEventListener('click', () => {
        closeMysteryCardModal();
        try { if (typeof switchTab === 'function') switchTab('quests'); } catch (_) {}
      });
    }
    document.addEventListener('keydown', (e) => {
      if (e.key !== 'Escape') return;
      const m = document.getElementById('mystery-card-modal');
      if (m && !m.classList.contains('hidden')) closeMysteryCardModal();
    });
  }

  // ── Card detail modal (static, non-cinematic) ───────────────
  // Tap a discovered card in the Pokédex → review its details.
  // Same data as the reveal modal but without animations.
  // W494 — fills the Relic Upgrade row in the card-detail modal. Hidden unless
  // the relic is owned AND upgradeable (priced tier + has a dominant combat stat).
  // Shows level pips, the cumulative bonus so far, and the next-level UPGRADE
  // button (priced, +1 dominant stat) — or a MAX state. Re-run on every open so
  // it reflects the latest level + souls balance after an upgrade re-opens it.
  function _fillCardDetailUpgrade(card, entry) {
    const box = document.getElementById('carddetail-upgrade');
    if (!box) return;
    const owned = !!(entry && (entry.count || 0) > 0);
    const dom = _relicDominantStatKey(card);
    const upgradeable = owned && dom && _relicIsTradeable(card.id) && RELIC_UPGRADE_BASE_COST[card.tier] != null;
    if (!upgradeable) { box.classList.add('hidden'); box.innerHTML = ''; return; }
    const STAT_LABELS = { str: 'STR', vit: 'VIT', int: 'INT', focus: 'FOCUS', will: 'WILL' };
    const domLabel = STAT_LABELS[dom] || String(dom).toUpperCase();
    const level = getRelicLevel(card.id);
    const atMax = level >= RELIC_UPGRADE_MAX;
    let pips = '';
    for (let i = 0; i < RELIC_UPGRADE_MAX; i++) {
      pips += '<span class="cdu-pip' + (i < level ? ' cdu-pip--on' : '') + '"></span>';
    }
    let btnHtml;
    if (atMax) {
      btnHtml = '<button id="carddetail-upgrade-btn" class="cdu-btn cdu-btn--max" type="button" disabled>MAX LEVEL</button>';
    } else {
      const cost = relicUpgradeCost(card.id, level);
      const bal = (typeof getSoulsBalance === 'function') ? getSoulsBalance() : 0;
      const afford = bal >= cost;
      btnHtml = '<button id="carddetail-upgrade-btn" class="cdu-btn' + (afford ? '' : ' cdu-btn--short') + '" type="button"' + (afford ? '' : ' disabled') + '>' +
          '<span class="cdu-btn-main">UPGRADE</span>' +
          '<span class="cdu-btn-cost">−' + cost + _marketSoulsSvg('cdu-souls') + '</span>' +
        '</button>' +
        '<div class="cdu-gain">Next: +1 ' + domLabel + (afford ? '' : ' · need ' + (cost - bal) + ' more') + '</div>';
    }
    box.innerHTML =
      '<div class="cdu-head"><span class="cdu-title">RELIC LEVEL</span>' +
        '<span class="cdu-level">' + level + ' / ' + RELIC_UPGRADE_MAX + '</span></div>' +
      '<div class="cdu-pips">' + pips + '</div>' +
      (level > 0 ? '<div class="cdu-current">+' + level + ' ' + domLabel + ' from upgrades</div>' : '') +
      (function () {
        // W757 -- tell the hunter WHY max matters: ultra+ weapons earn their
        // archetype's special attack at max level.
        const exeId = (typeof _weaponExecuteId === 'function') ? _weaponExecuteId(card.id) : null;
        if (!exeId) return '';
        const mv = ARENA_MOVE_LIB[exeId] || { name: exeId };
        return atMax
          ? '<div class="cdu-exe cdu-exe--on">\u2694 SPECIAL ATTACK UNLOCKED \u2014 <b>' + esc(mv.name) + '</b></div>'
          : '<div class="cdu-exe">\u2694 MAX LEVEL unlocks <b>' + esc(mv.name) + '</b> \u2014 a special attack (\u00d7' + ((mv.exe && mv.exe.mult) || 2) + ' below ' + Math.round(((mv.exe && mv.exe.thr) || 0.3) * 100) + '%)</div>';
      })() +
      btnHtml;
    box.classList.remove('hidden');
  }

  function openCardDetailModal(card, entry) {
    const overlay = document.getElementById('carddetail-overlay');
    if (!overlay) return;
    const slotIcon = SLOT_ICONS[card.slot] || '✦';
    overlay.className = 'carddetail-overlay carddetail-overlay--' + card.rarity;
    document.getElementById('carddetail-slot-icon').textContent = slotIcon;
    setModalCardArt('carddetail-card-art-img', card.art_path);
    document.getElementById('carddetail-name').textContent = card.name;
    document.getElementById('carddetail-source').textContent =
      'Dropped from ' + (BOSSES[card.source_boss] ? BOSSES[card.source_boss].name : '—');
    document.getElementById('carddetail-rarity').textContent = RARITY_LABELS[card.rarity] || card.rarity;
    document.getElementById('carddetail-flavor').textContent = card.flavor || '';
    // W495 — set membership tag. Shows "◈ <Set> · n / total set pieces" when the
    // relic belongs to a defined set, so players discover the set + its bonus.
    const cdSet = document.getElementById('carddetail-set');
    if (cdSet) {
      const setDef = (card.set_id && typeof SET_BONUSES !== 'undefined') ? SET_BONUSES[card.set_id] : null;
      const topTier = (setDef && setDef.tiers && setDef.tiers.length) ? setDef.tiers[setDef.tiers.length - 1] : null;
      if (setDef && topTier) {
        cdSet.innerHTML = '<span class="carddetail-set-glyph" aria-hidden="true">◈</span>' +
          '<span class="carddetail-set-name">' + esc(setDef.name) + '</span>' +
          '<span class="carddetail-set-note">Set · wear ' + topTier.pieces + ' for the full bonus</span>';
        cdSet.classList.remove('hidden');
      } else {
        cdSet.classList.add('hidden');
        cdSet.innerHTML = '';
      }
    }
    const cdStats = document.getElementById('carddetail-stats');
    if (cdStats) cdStats.innerHTML = cardStatBadgesHtml(card);
    _fillCardDetailUpgrade(card, entry); // W494 — relic upgrade row
    const acqEl = document.getElementById('carddetail-acquired');
    if (acqEl) acqEl.textContent = entry.first_acquired_date
      ? 'First found ' + formatAcquiredDate(entry.first_acquired_date)
      : '';
    const stackEl = document.getElementById('carddetail-stack');
    if (stackEl) stackEl.textContent = (entry.count > 1 ? 'You have ' + entry.count : '');

    // v3 Phase 1d — Equip/Unequip button now uses the new Hunter
    // Build system. EQUIP pushes the card into the first available
    // unlocked slot. UNEQUIP removes it from whichever slot it
    // currently occupies. The button hides for cards without a slot.
    const equipBtn = document.getElementById('carddetail-equip-btn');
    if (equipBtn && card.slot) {
      equipBtn.classList.remove('hidden');
      _carddetailCurrentCardId = card.id;
      const equippedNow = (typeof isItemEquippedInBuild === 'function') && isItemEquippedInBuild(card.id);
      if (equippedNow) {
        equipBtn.textContent = 'UNEQUIP';
        equipBtn.classList.remove('carddetail-equip-btn--primary');
        equipBtn.classList.add('carddetail-equip-btn--unequip');
      } else {
        equipBtn.textContent = 'EQUIP TO BUILD';
        equipBtn.classList.add('carddetail-equip-btn--primary');
        equipBtn.classList.remove('carddetail-equip-btn--unequip');
      }
    } else if (equipBtn) {
      equipBtn.classList.add('hidden');
    }

    overlay.classList.remove('hidden');
  }
  // Stashed by openCardDetailModal so the single static click handler
  // wired in setupCardDetailModal() knows which card the modal is
  // currently showing. Set every open; cleared on close.
  let _carddetailCurrentCardId = null;
  function closeCardDetailModal() {
    const overlay = document.getElementById('carddetail-overlay');
    if (overlay) overlay.classList.add('hidden');
    _carddetailCurrentCardId = null; // W494 — honor the "cleared on close" contract the stash comment promises
  }
  function setupCardDetailModal() {
    const overlay = document.getElementById('carddetail-overlay');
    const closeBtn = document.getElementById('carddetail-close');
    if (overlay) overlay.addEventListener('click', (e) => {
      if (e.target === overlay) closeCardDetailModal();
    });
    if (closeBtn) closeBtn.addEventListener('click', closeCardDetailModal);
    document.addEventListener('keydown', (e) => {
      if (e.key !== 'Escape') return;
      const overlay = document.getElementById('carddetail-overlay');
      if (overlay && !overlay.classList.contains('hidden')) closeCardDetailModal();
    });

    // v3 Phase 1a — EQUIP/UNEQUIP click handler. Single static
    // binding (versus per-open) so re-renders don't stack listeners.
    // Reads _carddetailCurrentCardId stashed by openCardDetailModal.
    const equipBtn = document.getElementById('carddetail-equip-btn');
    if (equipBtn) {
      equipBtn.addEventListener('click', () => {
        const cardId = _carddetailCurrentCardId;
        if (!cardId) return;
        const card = CARDS[cardId];
        if (!card) return;
        // v3 Phase 1e — typed-slot routing. If already in the
        // build, unequip from its slot. Otherwise route to the
        // card's matching typed slot (helm card → HELM slot etc).
        const currentSlot = (typeof getBuildSlotIndexForCard === 'function') ? getBuildSlotIndexForCard(cardId) : -1;
        if (currentSlot >= 0) {
          unequipBuildItem(currentSlot);
          try { showHabitToast(card.name + ' unequipped.'); } catch (_) {}
        } else {
          const slotKey = getCardEquipmentSlot(card);
          const targetIdx = (slotKey != null) ? EQUIPMENT_SLOT_INDEX[slotKey] : -1;
          if (typeof targetIdx !== 'number' || targetIdx < 0) {
            try { showHabitToast(card.name + " can't be equipped — missing slot type."); } catch (_) {}
          } else if (!isBuildSlotUnlocked(targetIdx)) {
            const req = getRequiredRankForBuildSlot(targetIdx);
            const slotDef = EQUIPMENT_SLOTS[targetIdx];
            try { showHabitToast('Reach ' + req + ' Rank to unlock ' + slotDef.label + '.'); } catch (_) {}
          } else {
            const res = equipBuildItem(targetIdx, cardId);
            const slotDef = EQUIPMENT_SLOTS[targetIdx];
            if (res.ok) {
              if (res.prevCardId && CARDS[res.prevCardId]) {
                try { showHabitToast(card.name + ' equipped — replaced ' + CARDS[res.prevCardId].name + '.'); } catch (_) {}
              } else {
                try { showHabitToast(card.name + ' equipped to ' + slotDef.label + '.'); } catch (_) {}
              }
            } else if (res.code === 'DUPLICATE') {
              try { showHabitToast(card.name + ' is already in your build.'); } catch (_) {}
            } else if (res.code === 'WRONG_SLOT') {
              try { showHabitToast(card.name + " doesn't fit that slot."); } catch (_) {}
            }
          }
        }
        // Re-render the modal in place so the button state updates.
        const inv = getInventory();
        openCardDetailModal(card, inv.cards[cardId] || { discovered: true, count: 1, first_acquired_date: null });
        try { if (currentTab === 'items') renderPokedex(); } catch (_) {}
        try { refreshEquipmentModalIfOpen(); } catch (_) {}
      });
    }

    // W494 — Relic Upgrade handler. Delegated on the static container because
    // the button itself is re-rendered (innerHTML) on every open. Charges souls
    // via upgradeRelic, then re-opens the modal so level/cost/balance refresh.
    const upgradeBox = document.getElementById('carddetail-upgrade');
    if (upgradeBox) {
      upgradeBox.addEventListener('click', (e) => {
        const btn = e.target.closest && e.target.closest('#carddetail-upgrade-btn');
        if (!btn || btn.disabled) return;
        const cardId = _carddetailCurrentCardId;
        if (!cardId) return;
        const card = CARDS[cardId];
        if (!card) return;
        const res = (typeof upgradeRelic === 'function') ? upgradeRelic(cardId) : null;
        if (res && res.ok) {
          const STAT_LABELS = { str: 'STR', vit: 'VIT', int: 'INT', focus: 'FOCUS', will: 'WILL' };
          const sl = STAT_LABELS[res.stat] || String(res.stat || '').toUpperCase();
          try { showHabitToast(card.name + ' upgraded — LV ' + res.newLevel + ', +1 ' + sl); } catch (_) {}
          try { refreshSoulsDisplay(); } catch (_) {}
          const inv = getInventory();
          openCardDetailModal(card, inv.cards[cardId] || { discovered: true, count: 1, first_acquired_date: null, upgrade_level: res.newLevel });
          try { if (currentTab === 'items') renderPokedex(); } catch (_) {}
          try { refreshEquipmentModalIfOpen(); } catch (_) {}
        } else if (res && res.reason === 'insufficient') {
          try { showHabitToast('Not enough souls to upgrade this relic.'); } catch (_) {}
        } else if (res && res.reason === 'maxed') {
          try { showHabitToast(card.name + ' is already at max level.'); } catch (_) {}
        }
      });
    }
  }

  // Re-renders the armory modal's hunter build + summary when the
  // equip state changes. No-op if the modal isn't open. Pivoted to
  // Hunter Build in v3 Phase 1d (was renderEquippedSlotOverlays +
  // populateEquipmentStats).
  function refreshEquipmentModalIfOpen() {
    const modal = document.getElementById('equipment-modal');
    if (!modal || modal.classList.contains('hidden')) return;
    if (typeof renderHunterBuild        === 'function') renderHunterBuild();
    if (typeof renderHunterBuildSummary === 'function') renderHunterBuildSummary();
  }
  // Friendly date formatter for the card detail "first found" line.
  function formatAcquiredDate(iso) {
    if (!iso) return '';
    const today = getDeviceLocalDate();
    if (iso === today) return 'today';
    const yesterday = getDeviceLocalYesterday();
    if (iso === yesterday) return 'yesterday';
    // Calendar-day diff.
    const a = new Date(iso + 'T00:00:00');
    const b = new Date(today + 'T00:00:00');
    const days = Math.round((b - a) / (1000 * 60 * 60 * 24));
    if (days > 1 && days < 7) return days + ' days ago';
    return a.toLocaleDateString('en-US', { month: 'short', day: 'numeric', year: 'numeric' });
  }

  // v3 Phase 1h — console-only dry-run simulator. Runs N kills
  // through a clone of pity state, returns aggregate counts. Does
  // NOT mutate the real inventory.
  function simulateDrops(bossId, count) {
    const n = Math.max(1, Math.min(100000, count | 0));
    const cfg = BOSSES[bossId];
    if (!cfg) return null;
    const pityCfg = dropPityCfgFor(bossId);
    const rates = dropRatesFor(bossId);
    const realPity = getDropPityState(bossId);
    const realFirstCommon = hasPulledFirstCommonForBoss(bossId);
    // Snapshot — sim runs against a copy.
    const pity = Object.assign({}, realPity);
    let firstCommon = realFirstCommon;
    const tally = { common: 0, rare: 0, ultra_rare: 0, no_drop: 0, pity_drops: 0 };
    for (let i = 0; i < n; i++) {
      const effU = (pity.kills_since_ultra >= pityCfg.ultra_hard_pity_after) ? 1
        : (pity.kills_since_ultra >= pityCfg.ultra_soft_pity_after
            ? Math.min(rates.ultra_rare + (pity.kills_since_ultra - pityCfg.ultra_soft_pity_after + 1) * pityCfg.ultra_soft_pity_add, pityCfg.ultra_soft_pity_max)
            : rates.ultra_rare);
      const commonRate = firstCommon ? rates.common : rates.common_protected;
      let outcome = null;
      if (Math.random() < effU)        outcome = 'ultra_rare';
      else if (Math.random() < rates.rare) outcome = 'rare';
      else if (Math.random() < commonRate) outcome = 'common';
      // v3 Phase 1r — Rare Mercy floor. Upgrade null / common → rare
      // when the rare-mercy threshold is one kill away. Ultra outcome
      // is never downgraded.
      if ((outcome === null || outcome === 'common') &&
          (pity.kills_since_rare_or_better + 1) >= pityCfg.rare_mercy_after) {
        outcome = 'rare';
        tally.pity_drops += 1;
      }
      if (!outcome && pity.kills_since_any_drop + 1 >= pityCfg.any_drop_guarantee_after) {
        outcome = 'common'; // pity prefers common per forcePityDrop ordering
        tally.pity_drops += 1;
      }
      if (!outcome) {
        tally.no_drop += 1;
        pity.kills_since_any_drop      += 1;
        pity.kills_since_ultra         += 1;
        pity.kills_since_rare_or_better += 1;
      } else {
        tally[outcome] += 1;
        if (outcome === 'common') {
          pity.kills_since_any_drop = 0;
          pity.kills_since_ultra         += 1;
          pity.kills_since_rare_or_better += 1;
          firstCommon = true;
        } else if (outcome === 'rare') {
          pity.kills_since_any_drop = 0;
          pity.kills_since_rare_or_better = 0;
          pity.kills_since_ultra += 1;
        } else {
          pity.kills_since_any_drop = 0;
          pity.kills_since_rare_or_better = 0;
          pity.kills_since_ultra = 0;
        }
      }
    }
    return tally;
  }
  function resetPity(bossId) {
    setDropPityState(bossId, _freshPityState());
    persistInventory();
  }

  try {
    window.Drops = {
      get state()   { return getInventory(); },
      CARDS,
      forceRoll:    forceDrop,
      forceDrop,
      resetInventory,
      rollBossDrop,
      processRevealQueue,
      // Rate + cadence inspection
      getRates:     dropRatesFor,
      RATES:        DROP_RATES_BY_CADENCE,
      PITY:         DROP_PITY_BY_CADENCE,
      getCadence:   getBossCadence,
      // v3 Phase 1h — pity helpers
      getPity:      getDropPityState,
      getPityDisplay: getDropPityDisplay,
      resetPity,
      forcePityDrop,
      simulateDrops,
      // Per-boss first-common
      hasFirstCommon: hasPulledFirstCommonForBoss,
    };
  } catch (_) {}

  // Computes "yesterday" in device-local format. Used by the missed-
  // night reset (init-time) to set last_eval_date back one day so
  // tonight's evaluation can still proceed.
  function getDeviceLocalYesterday() {
    const d = new Date();
    d.setDate(d.getDate() - 1);
    return d.getFullYear() + '-' +
      String(d.getMonth() + 1).padStart(2, '0') + '-' +
      String(d.getDate()).padStart(2, '0');
  }

  // ── Insomniac kill-detection ─────────────────────────────────
  // Called from autoVerifySleep AFTER HealthKit returns sleep data.
  // Evaluates the most recent night's hours against the kill condition.
  // Idempotent on nightDate — a second call with the same date is a
  // no-op so visibility-change refires don't double-count.
  //
  // sleepHours: total asleep hours from Health.getSleepLastNight()
  // nightDate:  device-local 'YYYY-MM-DD' representing the morning
  //             the user is in (the morning that follows the night
  //             being evaluated). See spec.
  function evaluateInsomniacForNight(sleepHours, nightDate) {
    if (typeof sleepHours !== 'number' || !nightDate) return;
    const id = 'the_insomniac';
    const cfg = BOSSES[id];
    const state = getBossState(id);

    // Already evaluated this night — idempotent.
    if (state.last_eval_date === nightDate) return;

    // v2.0.1 engagement gate — habit data still flows to leaderboard
    // and habit auto-verify, but boss progress only advances for
    // engaged bosses. User opts in via the ENGAGE BOSS button on the
    // detail modal.
    if (state.engaged !== true) return;

    if (sleepHours >= cfg.sleepHours) {
      state.streak += 1;
      state.last_eval_date = nightDate;
      if (state.streak >= cfg.streakTarget) {
        state.kill_count += 1;
        state.streak = 0;
        // v3 Phase 1z.6 — hunt ends on defeat. Re-engagement is
        // explicit (user taps "Hunt Again" on result modal or boss
        // detail).
        // v3 Phase 1z.43 — also clear hunt-window fields.
        _clearBossHuntFields(state);
        state.last_defeated_at = new Date().toISOString();
        state.last_hunt_outcome = 'defeated';
        setBossState(id, state);
        // v2.0.1: kill grants tier-scaled souls. Earn happens here so
        // the toast message can include the actual amount awarded.
        // W465 — reward once per (boss, night), independent of boss-state churn.
        const _firstKill = _claimBossKillReward(id, nightDate);
        const reward = _firstKill ? killRewardSouls(cfg.rank) : 0;
        if (reward > 0) earnSouls(reward, 'kill_' + id);
        // v3 Phase 1z.277D — WLT Merchant bonus on kill reward.
        // Capped +20% reward at WLT Lv20. Separate earnSouls() so
        // the ledger shows it as its own row. Fires ONLY after a
        // real kill — gated by the same code path as the base
        // reward above, so failed hunts and engages never trigger.
        const _wltBonus_1 = _firstKill ? wltKillBonusSouls(cfg.rank) : 0;
        if (_wltBonus_1 > 0) earnSouls(_wltBonus_1, 'wlt_bonus_kill_' + id);
        // v2.0.1 DROPS: roll for a card drop. May return null (~70%
        // standard rate, less during first-common protection).
        const dropped = _firstKill ? rollBossDrop(id) : null;
        if (_firstKill) announceKillAndDrop(cfg, reward, dropped);
        // Re-render the Quests panel so the streak progress + kill
        // count update if user is currently looking at it.
        try { if (currentTab === 'quests') renderBossesPanel(currentDungeonRank); } catch (_) {}
        try { refreshBossFullScreenIfOpen && refreshBossFullScreenIfOpen(id); } catch (_) {}
        return;
      }
      setBossState(id, state);
    } else {
      // Sub-threshold sleep — break the streak. Still record the date
      // so we don't double-process this night.
      state.streak = 0;
      state.last_eval_date = nightDate;
      setBossState(id, state);
    }
    // Re-render Quests panel for streak progress visibility.
    try { if (currentTab === 'quests') renderBossesPanel(currentDungeonRank); } catch (_) {}
  }

  // Init-time missed-night detection. If the user skipped opening the
  // app for a calendar day or more, we reset the streak — a missing
  // night isn't a successful one, so the streak shouldn't survive.
  // last_eval_date is set to yesterday so tonight's evaluation can
  // still proceed (an eval for "today" remains valid).
  //
  // Only fires from init() per spec — visibilitychange would
  // mis-trigger on multi-foreground days.
  function checkMissedNightForInsomniac() {
    const id = 'the_insomniac';
    const state = getBossState(id);
    // Engagement gate — no point resetting streak on a boss the
    // user isn't hunting. The streak field is already 0 for
    // disengaged bosses (disengageBoss zeroes it).
    if (state.engaged !== true) return;
    // First install — never been evaluated. Don't treat as missed.
    if (!state.last_eval_date) return;

    const yesterday = getDeviceLocalYesterday();
    // last_eval_date strictly older than yesterday = at least one
    // calendar day was skipped → reset.
    if (state.last_eval_date < yesterday) {
      state.streak = 0;
      state.last_eval_date = yesterday;
      setBossState(id, state);
    }
  }

  // ── Steel Wolf kill-detection (v2.0.1, D-rank) ───────────────
  // Daily-cadence boss. Eval fires from autoVerifySleep's sibling
  // path — autoVerifyWalk — using the same step count fetched for
  // the Daily walk habit + leaderboard recording. No extra HealthKit
  // call. Mirrors Insomniac's structure exactly: idempotent on
  // dayDate, runtime missed-day reset, init-time missed-day reset.
  //
  // Field naming: cfg.stepThreshold (5000) — semantic-specific name
  // parallel to Insomniac's cfg.sleepHours. NOT a generic
  // `threshold` field; if a future generalization is wanted, refactor
  // all three bosses together.
  function evaluateSteelWolfForDay(stepCount, dayDate) {
    if (typeof stepCount !== 'number' || !dayDate) return;
    const id = 'the_steel_wolf';
    const cfg = BOSSES[id];
    if (!cfg) return;
    const state = getBossState(id);

    // Idempotent on dayDate — multiple calls in the same day no-op.
    if (state.last_eval_date === dayDate) return;

    // v2.0.1 engagement gate — same rule as the other bosses.
    if (state.engaged !== true) return;

    // Runtime missed-day reset: if the user opens the app after
    // skipping at least one calendar day (last_eval_date older than
    // yesterday-from-dayDate), the streak is dead before today's
    // eval. A missing day isn't a successful one. First-install
    // (null last_eval_date) skips this — fresh start.
    if (state.last_eval_date) {
      const d = new Date(dayDate + 'T00:00:00');
      d.setDate(d.getDate() - 1);
      const yesterdayFromDay = d.getFullYear() + '-' +
        String(d.getMonth() + 1).padStart(2, '0') + '-' +
        String(d.getDate()).padStart(2, '0');
      if (state.last_eval_date < yesterdayFromDay) {
        state.streak = 0;
      }
    }

    if (stepCount >= cfg.stepThreshold) {
      state.streak += 1;
      state.last_eval_date = dayDate;
      if (state.streak >= cfg.streakTarget) {
        state.kill_count += 1;
        state.streak = 0;
        // v3 Phase 1z.6 — hunt ends on defeat.
        // v3 Phase 1z.43 — also clear hunt-window fields.
        _clearBossHuntFields(state);
        state.last_defeated_at = new Date().toISOString();
        state.last_hunt_outcome = 'defeated';
        setBossState(id, state);
        // W465 — reward once per (boss, day), independent of boss-state churn.
        const _firstKill = _claimBossKillReward(id, dayDate);
        const reward = _firstKill ? killRewardSouls(cfg.rank) : 0;
        if (reward > 0) earnSouls(reward, 'kill_' + id);
        // v3 Phase 1z.277D — WLT Merchant bonus (per-day boss path).
        const _wltBonus_3 = _firstKill ? wltKillBonusSouls(cfg.rank) : 0;
        if (_wltBonus_3 > 0) earnSouls(_wltBonus_3, 'wlt_bonus_kill_' + id);
        const dropped = _firstKill ? rollBossDrop(id) : null;
        if (_firstKill) announceKillAndDrop(cfg, reward, dropped);
        try { if (currentTab === 'quests') renderBossesPanel(currentDungeonRank); } catch (_) {}
        try { refreshBossFullScreenIfOpen && refreshBossFullScreenIfOpen(id); } catch (_) {}
        return;
      }
      setBossState(id, state);
    } else {
      // Sub-threshold steps — break the streak. Record the date so
      // we don't double-process this day.
      state.streak = 0;
      state.last_eval_date = dayDate;
      setBossState(id, state);
    }
    try { if (currentTab === 'quests') renderBossesPanel(currentDungeonRank); } catch (_) {}
  }

  // Init-time missed-day check. Mirrors checkMissedNightForInsomniac
  // — runs once per cold launch, resets streak if last_eval_date is
  // older than yesterday. Covers the case where a user opens the app
  // after a multi-day absence and the eval doesn't fire because they
  // have no walk habit configured (the runtime reset inside the
  // evaluator only triggers if the eval actually runs).
  function checkMissedDayForSteelWolf() {
    const id = 'the_steel_wolf';
    const state = getBossState(id);
    // Engagement gate — disengaged bosses are already at streak 0.
    if (state.engaged !== true) return;
    if (!state.last_eval_date) return; // first install — leave alone
    const yesterday = getDeviceLocalYesterday();
    if (state.last_eval_date < yesterday) {
      state.streak = 0;
      state.last_eval_date = yesterday;
      setBossState(id, state);
    }
  }

  // ─────────────────────────────────────────────────────────────
  // v3 Phase 1v — D-rank evaluators (Iron Warden, Glass Strider,
  // Dream Tyrant). All three are TRUE daily-cadence bosses:
  //   - streakTarget = 1 (one qualifying day/night defeats them)
  //   - cadence = 'daily' (uses daily mercy + rate thresholds)
  //   - no weekly cap, no consecutive-day requirement
  //   - max 1 defeat per qualifying calendar day/night
  // Idempotency is enforced via state.last_eval_date — repeated
  // app opens on the same day/night don't re-kill the boss.
  // Engagement gate is the standard `state.engaged !== true` check.
  // ─────────────────────────────────────────────────────────────

  // Generic single-shot kill helper for daily-cadence streakTarget=1
  // bosses. Avoids duplicating the kill flow (soul reward + drop roll
  // + toast + UI refresh) across three evaluators. Caller is
  // responsible for the qualifying-condition check + idempotency
  // guard before invoking.
  // W465 — souls-farm exploit fix. Boss-kill REWARDS (souls + WLT bonus + drop +
  // guild feed) are once per (boss, calendar day), guarded by an INDEPENDENT
  // localStorage flag that survives the engage/disengage state churn. Root cause:
  // engageBoss does NOT reset boss `last_eval_date` (disengageBoss does), so a
  // re-engaged boss whose qualifying day was already credited got re-killed every
  // foreground via the UNGUARDED resolver backfill (_awardHuntKillFromBackfill →
  // _awardSingleShotKill) — +50/+5 souls per app entry. last_eval_date alone is
  // insufficient (disengage nulls it), so this flag is independent of boss state.
  // Returns true (and claims) the FIRST time today; false thereafter. Reset All
  // Progress sweeps hb_* (incl. this).
  const _killRewardClaimedMem = new Set();   // W465.1 — same-session fallback when localStorage throws (private mode / quota), so the reward guard can't fail OPEN and re-pay.
  function _claimBossKillReward(id, dateStr) {
    const k = 'hb_kill_reward_' + id + '_' + dateStr;
    if (_killRewardClaimedMem.has(k)) return false;   // already claimed this session
    let already = false;
    try {
      if (localStorage.getItem(k) === '1') already = true;
      else localStorage.setItem(k, '1');
    } catch (_) { /* storage unavailable — the in-memory Set below is the guard */ }
    _killRewardClaimedMem.add(k);
    return !already;   // true = first claim (grant reward); false = already claimed in storage
  }

  function _awardSingleShotKill(id, cfg, dayDate, state) {
    // W465 — gate the whole kill+reward per (boss, day). The resolver backfill
    // reaches here UNGUARDED; without this a re-engaged already-credited day
    // re-kills + re-pays every foreground (the reported souls-farm exploit).
    state.last_eval_date = dayDate;   // always stamp so the eval-path guard holds going forward
    if (!_claimBossKillReward(id, dayDate)) {
      state.streak = 0;
      _clearBossHuntFields(state);
      setBossState(id, state);
      return;
    }
    state.kill_count = (state.kill_count || 0) + 1;
    state.streak = 0;
    state.last_eval_date = dayDate;
    // v3 Phase 1z.6 — hunt ends on defeat. Re-engagement is explicit.
    // v3 Phase 1z.43 — also clear hunt-window fields.
    _clearBossHuntFields(state);
    state.last_defeated_at = new Date().toISOString();
    state.last_hunt_outcome = 'defeated';
    setBossState(id, state);
    const reward = killRewardSouls(cfg.rank);
    if (reward > 0) earnSouls(reward, 'kill_' + id);
    // v3 Phase 1z.277D — WLT Merchant bonus (single-shot kill path).
    const _wltBonus_4 = wltKillBonusSouls(cfg.rank);
    if (_wltBonus_4 > 0) earnSouls(_wltBonus_4, 'wlt_bonus_kill_' + id);
    const dropped = rollBossDrop(id);
    // W762 — one history row per solo kill (the Kill Log History tab's solo feed;
    // counters above stay the Kill Log tab's source — this is the chronology).
    try {
      _pushHuntHistory({
        mode: 'solo', boss_id: id, bossName: (cfg && cfg.name) || 'a boss',
        rank: (cfg && cfg.rank) || '', result: 'win',
        souls: (reward || 0) + (_wltBonus_4 || 0),
        drop: dropped ? { id: dropped.id, name: dropped.name, rarity: dropped.rarity } : null,
        ts: Date.now(),
      });
    } catch (_) {}
    announceKillAndDrop(cfg, reward, dropped);
    // W541 — solo boss win → mark first-boss + arm the review pre-prompt (fires on modal close).
    _rvSet(_RV.firstBoss, '1');
    try { var _rvRank = ''; try { _rvRank = String(getRank(totalPoints).label || '').replace(/\s*rank\s*$/i, ''); } catch (_) {} if (!_rvRank) _rvRank = (cfg && cfg.rank) || ''; _reviewArm('boss', { bossName: (cfg && cfg.name) || 'the boss', rank: _rvRank }); } catch (_) {}
    // v3 Phase 1z.165 — Guild Hall feat row. Boss kills are per-day
    // idempotent on (boss_id, kill_count) so the same kill can't
    // double-emit even if _awardSingleShotKill is called twice (e.g.
    // visibilitychange race).
    try {
      recordGuildActivity('boss_kill', {
        bossId:   id,
        bossName: cfg && cfg.name ? cfg.name : id,
        rank:     cfg && cfg.rank ? cfg.rank : null,
        dayDate:  dayDate,
      }, 'boss_kill_' + id + '_' + state.kill_count);
    } catch (_) {}
    // v3 Phase 1z.204 — public friend activity submit. Mirrors
    // the same canonical boss data into the backend so accepted
    // friends can see "<alias> defeated <bossName>" in their
    // Guild Activity feed. Idempotent on (user_id, clientEventId)
    // server-side; the killCount in the key means each kill is
    // its own row. Boss names are canonical game fiction (no PHI).
    try {
      const bossName = (cfg && cfg.name) ? cfg.name : id;
      const bossRank = (cfg && cfg.rank) ? cfg.rank : null;
      // Only submit if the boss has a recognised rank — the
      // backend regex requires one of {E,D,C,B,A,S,S+}. Defensive
      // guard against malformed boss config.
      if (bossRank && /^(E|D|C|B|A|S|S\+)$/.test(bossRank)) {
        _queuePublicAchievementEvent({
          eventType:       'boss_kill',
          eventKey:        id,
          eventLabel:      'defeated ' + bossName,
          eventValue:      state.kill_count,
          rarity:          bossRank,
          clientEventId:   'boss_kill:' + id + ':' + state.kill_count,
          clientCreatedAt: new Date().toISOString(),
        });
      }
    } catch (_) {}
    try { if (currentTab === 'quests') renderBossesPanel(currentDungeonRank); } catch (_) {}
    try { refreshBossFullScreenIfOpen && refreshBossFullScreenIfOpen(id); } catch (_) {}
  }

  // ── Iron Warden — verified workout ───────────────────────────
  // v3 Phase 1z.129 — broadened from strength-only to any Apple
  // Health workout. Fed by Health.getAnyWorkoutsToday() in
  // autoVerifyStrengthTraining. Shares the any-workout data source
  // with the "Workout 30 min" habit auto-verify; same per-sample
  // ≥1 min filter to drop zero-length junk samples. Kill rule:
  // total daily Apple Health workout minutes ≥ cfg.workoutMinutes
  // (10). Any activity type counts (HIIT, running, cycling,
  // strength, yoga, sports, etc.) — same rule as the Workout habit.
  // Strength Duel remains strength-only (intentionally).
  function evaluateIronWardenForDay(workoutData, dayDate) {
    if (!dayDate) return;
    // W729 — record the day's VERIFIED Apple Health workout minutes into a daily
    // map (mirrors steps_daily / sleep_hours_daily) so Weekly Insights can build a
    // verified workout→steps pattern + training-day counts. Objective HealthKit
    // data, not a self-reported check-box. Written before the engagement gate so
    // it accrues for every user (accumulates going forward). Keeps the day's max.
    try {
      const _wm = (workoutData && typeof workoutData.totalMinutes === 'number') ? Math.round(workoutData.totalMinutes) : 0;
      if (_wm > 0) {
        const _ls = loadLeaderboardState();
        if (!_ls.workout_daily) _ls.workout_daily = {};
        if ((_ls.workout_daily[dayDate] | 0) < _wm) {
          _ls.workout_daily[dayDate] = _wm;
          lbPruneDailyMap(_ls.workout_daily, LB_DAILY_RETENTION_DAYS);
          saveLeaderboardState(_ls);
        }
      }
    } catch (_) {}
    const id = 'the_iron_warden';
    const cfg = BOSSES[id];
    if (!cfg) return;
    const state = getBossState(id);
    if (state.last_eval_date === dayDate) return;   // idempotent
    if (state.engaged !== true) {
      try {
        if (typeof _addHealthVerifyBreadcrumb === 'function') {
          _addHealthVerifyBreadcrumb('iron-warden-skip', {
            reason: 'not-engaged', dayDate,
          });
        }
      } catch (_) {}
      return;                                       // engagement gate
    }

    const totalMinutes = (workoutData && typeof workoutData.totalMinutes === 'number')
      ? workoutData.totalMinutes : 0;
    const threshold = (typeof cfg.workoutMinutes === 'number') ? cfg.workoutMinutes : 10;

    try {
      if (typeof _addHealthVerifyBreadcrumb === 'function') {
        _addHealthVerifyBreadcrumb('iron-warden-eval', {
          dayDate,
          mode: 'any-workout',
          totalMinutes: Number(totalMinutes.toFixed(1)),
          threshold,
          qualifyingCount: (workoutData && typeof workoutData.count === 'number') ? workoutData.count : 0,
        });
      }
    } catch (_) {}

    if (totalMinutes >= threshold) {
      _awardSingleShotKill(id, cfg, dayDate, state);
      try {
        if (typeof _addHealthVerifyBreadcrumb === 'function') {
          _addHealthVerifyBreadcrumb('iron-warden-defeated', {
            dayDate, totalMinutes: Number(totalMinutes.toFixed(1)), threshold,
            mode: 'any-workout',
          });
        }
      } catch (_) {}
    } else {
      // Below threshold YET today — don't write a "no-kill"
      // last_eval_date because that would block a later check after
      // the user finishes more workout time. Stay silent until the
      // day rolls.
      try {
        if (typeof _addHealthVerifyBreadcrumb === 'function') {
          _addHealthVerifyBreadcrumb('iron-warden-skip', {
            reason: 'below-threshold', dayDate,
            totalMinutes: Number(totalMinutes.toFixed(1)),
            threshold,
          });
        }
      } catch (_) {}
    }
  }
  function checkMissedDayForIronWarden() {
    const id = 'the_iron_warden';
    const state = getBossState(id);
    if (state.engaged !== true) return;
    // streakTarget=1 daily means there's no streak to preserve —
    // last_eval_date alone gates idempotency. Nothing to reset.
  }

  // ── Glass Strider — 7,500 steps ──────────────────────────────
  // Fed by autoVerifyWalk's existing step-count fetch. Same data
  // path that powers the Daily walk habit, Steel Wolf eval, and the
  // leaderboard step recording. No extra HealthKit roundtrip.
  function evaluateGlassStriderForDay(stepCount, dayDate) {
    if (typeof stepCount !== 'number' || !dayDate) return;
    const id = 'the_glass_strider';
    const cfg = BOSSES[id];
    if (!cfg) return;
    const state = getBossState(id);
    if (state.last_eval_date === dayDate) return;
    if (state.engaged !== true) return;

    if (stepCount >= cfg.stepThreshold) {
      _awardSingleShotKill(id, cfg, dayDate, state);
    }
    // Sub-threshold: stay silent (no last_eval_date write) so a
    // later eval after more walking can still credit the kill.
  }
  function checkMissedDayForGlassStrider() {
    const id = 'the_glass_strider';
    const state = getBossState(id);
    if (state.engaged !== true) return;
    // Same as Iron Warden: no streak to preserve.
  }

  // ── Dream Tyrant — 7.5 hours of sleep ────────────────────────
  // Fed by autoVerifySleep's existing sleep-data fetch. Same data
  // path that powers Sleep / Sleep before midnight habit auto-verify,
  // the Insomniac eval, and leaderboard sleep recording.
  function evaluateDreamTyrantForNight(sleepHours, nightDate) {
    if (typeof sleepHours !== 'number' || !nightDate) return;
    const id = 'the_dream_tyrant';
    const cfg = BOSSES[id];
    if (!cfg) return;
    const state = getBossState(id);
    if (state.last_eval_date === nightDate) return;
    if (state.engaged !== true) return;

    if (sleepHours >= cfg.sleepHours) {
      _awardSingleShotKill(id, cfg, nightDate, state);
    } else {
      // Sub-threshold sleep — for sleep, the data is finalized once
      // it lands in HealthKit (no "I'll sleep more later today" path).
      // Record the date so we don't re-eval on every visibilitychange.
      state.last_eval_date = nightDate;
      setBossState(id, state);
    }
  }
  function checkMissedNightForDreamTyrant() {
    const id = 'the_dream_tyrant';
    const state = getBossState(id);
    if (state.engaged !== true) return;
    // Same as Iron Warden / Glass Strider: streakTarget=1, no streak
    // to preserve across days.
  }

  try {
    window.Bosses = {
      BOSSES, getBossState,
      _consecRunScan,   // W262 — pure run-scan helper (console verification)
      evaluateInsomniacForNight,    checkMissedNightForInsomniac,
      evaluateSteelWolfForDay,      checkMissedDayForSteelWolf,
      // v3 Phase 1v D-rank
      evaluateIronWardenForDay,     checkMissedDayForIronWarden,
      evaluateGlassStriderForDay,   checkMissedDayForGlassStrider,
      evaluateDreamTyrantForNight,  checkMissedNightForDreamTyrant,
      // Engagement model (v2.0.1) — opt-in gate for boss eval.
      engageBoss, disengageBoss, isBossEngaged, countEngagedBosses,
      MAX_ENGAGED_BOSSES,
    };
  } catch (_) {}

  // ── LEADERBOARD STATS (v2.0.2 accumulator, v2.1 live) ────────
  // Local accumulator for the three Apple-Health-verifiable metrics.
  // v2.0.2 shipped the silent tracking layer; v2.1 Phase C (commit
  // 7c5ada9) wired it to the live backend — values flow to
  // /v1/leaderboard/submit on app open + visibility change, and
  // ranking sheets fetch /v1/leaderboard/top with stale-while-
  // revalidate caching.
  //
  // Three Apple-Health-verifiable metrics — chosen because they cannot
  // be self-reported / gamed, which is the only honest basis for a
  // competitive leaderboard:
  //   1. Steps totaled in the last 7 days (rolling sum)
  //   2. Best streak of consecutive nights with sleep ≥ 7 hours
  //   3. Best streak of consecutive nights with bedtime before midnight
  //
  // "Best" = all-time peak, preserved separately from the running
  // current_* counters so a streak-break doesn't erase the user's
  // historical record. The current_* counters drive future "live"
  // leaderboard slots; the best_* counters drive "lifetime" slots.
  //
  // Independence: like bosses, this runs on raw HealthKit data and
  // IGNORES the Settings → Apple Health pause toggle. The pause is
  // scoped to habit auto-verify only — bosses and leaderboard stats
  // accumulate passively. A user who pauses habit auto-verify still
  // gets leaderboard credit. (If we want a privacy-style master kill
  // switch later, it should be a SEPARATE toggle, not this one.)
  //
  // Privacy: every stored field is local-only via localStorage. When
  // the leaderboard ships, only the explicit-opt-in subset will be
  // transmitted. No network calls happen here.
  //
  // Date semantics: device-local time, same as bosses + sleep windows
  // (CLAUDE.md: notifications + sleep + leaderboard use device-local;
  // streak math for habits uses PT). 'YYYY-MM-DD' keys throughout.
  const LB_DAILY_RETENTION_DAYS = 365;   // W726b — keep a YEAR of daily history so the Weekly
                                         // Insights correlations have a statistically meaningful
                                         // baseline (legit causation needs many days). Accumulates
                                         // going forward; can't recover already-pruned days.
                                         // ~1yr of small ints across the daily maps — sync-safe.
  const LB_STORAGE_KEY = 'hb_leaderboard';
  const LB_SLEEP_HOURS_THRESHOLD = 7; // matches Insomniac's kill condition
  // W714 — a first-class WALK streak (consecutive days ≥ threshold steps), durable
  // like the sleep streak. steps_daily is pruned to 30 days so a computed-only streak
  // would evaporate; best_walk_streak persists. 6,000 = The Steel Wolf's kill condition
  // (the E-rank walking boss), the app's canonical "you walked today" bar — parallel to
  // the sleep threshold matching The Insomniac. Feeds the bg-streak30 member border.
  const LB_WALK_STEPS_THRESHOLD = 6000;

  function loadLeaderboardState() {
    try {
      const raw = JSON.parse(localStorage.getItem(LB_STORAGE_KEY) || '{}');
      return {
        steps_daily:               raw.steps_daily               || {},
        sleep_hours_daily:         raw.sleep_hours_daily         || {},
        bedtime_daily:             raw.bedtime_daily             || {},
        workout_daily:             raw.workout_daily             || {},   // W729 — HK workout minutes/day (verified)
        current_sleep_streak:      raw.current_sleep_streak      || 0,
        best_sleep_streak:         raw.best_sleep_streak         || 0,
        last_sleep_eval_date:      raw.last_sleep_eval_date      || null,
        current_bedtime_streak:    raw.current_bedtime_streak    || 0,
        best_bedtime_streak:       raw.best_bedtime_streak       || 0,
        last_bedtime_eval_date:    raw.last_bedtime_eval_date    || null,
        // W714 — walk streak (consecutive days ≥ LB_WALK_STEPS_THRESHOLD steps)
        current_walk_streak:       raw.current_walk_streak       || 0,
        best_walk_streak:          raw.best_walk_streak          || 0,
        last_walk_eval_date:       raw.last_walk_eval_date       || null,
        best_7day_step_total:      raw.best_7day_step_total      || 0,
        best_7day_step_window_end: raw.best_7day_step_window_end || null,
        // v3 Phase 1z.125 — flights climbed daily map + best-week
        // total. Mirrors the steps_daily / best_7day_step_total
        // pattern. flights_daily[YYYY-MM-DD] = integer count.
        flights_daily:              raw.flights_daily              || {},
        best_7day_flights_total:    raw.best_7day_flights_total    || 0,
        best_7day_flights_window_end: raw.best_7day_flights_window_end || null,
        // W304 — lifetime avg steps/day: a running total + first-record date,
        // both of which survive the 30-day daily-map prune (the daily map alone
        // can't yield a true all-time average). Submitted on the profile heartbeat.
        lifetime_steps_total:      raw.lifetime_steps_total      || 0,
        lifetime_steps_start_date: raw.lifetime_steps_start_date || null,
      };
    } catch (e) {
      _logSwallow('loadLeaderboardState:parse', e);   // W491 — silently resets step/sleep streaks + lifetime totals
      return {
        steps_daily: {}, sleep_hours_daily: {}, bedtime_daily: {}, workout_daily: {},
        current_sleep_streak: 0, best_sleep_streak: 0, last_sleep_eval_date: null,
        current_bedtime_streak: 0, best_bedtime_streak: 0, last_bedtime_eval_date: null,
        current_walk_streak: 0, best_walk_streak: 0, last_walk_eval_date: null,
        best_7day_step_total: 0, best_7day_step_window_end: null,
        flights_daily: {},
        best_7day_flights_total: 0, best_7day_flights_window_end: null,
        lifetime_steps_total: 0, lifetime_steps_start_date: null,
      };
    }
  }

  function saveLeaderboardState(state) {
    try { localStorage.setItem(LB_STORAGE_KEY, JSON.stringify(state)); } catch (e) { _logSwallow('leaderboard_cache:persist', e); }
  }

  // Returns the device-local date 'YYYY-MM-DD' for (dateStr - 1 day).
  // Used by gap detection — a streak only continues if today's eval
  // date follows yesterday's eval date. Skipped nights = gap = reset.
  function lbPrevDate(dateStr) {
    if (!dateStr) return null;
    const d = new Date(dateStr + 'T00:00:00');
    d.setDate(d.getDate() - 1);
    return d.getFullYear() + '-' +
      String(d.getMonth() + 1).padStart(2, '0') + '-' +
      String(d.getDate()).padStart(2, '0');
  }

  // v3 Phase 1z.139 — anchor the weekly sum to the SAME Sunday-UTC
  // boundary the backend uses (see getAccoladeWeekStart() server-side
  // and lbGetCurrentWeekStartUTC() in this file). Prior implementation
  // walked back `today.getDay()` days using device-local DOW, then
  // lbSubmitAllMetrics tagged the submit with the backend's Sunday-UTC
  // `week_start`. During the gap window where device-local is still
  // Saturday but UTC has already rolled to Sunday, that produced a
  // catastrophic mismatch: the client summed 7 device-local days of
  // last week and tagged them with the new UTC week_start, so the
  // backend stored last week's total as the user's first submit of the
  // new week. Same bug class fixed for flights below.
  //
  // New behaviour: walk from today's device-local date backward as
  // long as the date string is >= the current Sunday-UTC week start
  // (lexicographic compare of 'YYYY-MM-DD' strings is safe). On a
  // normal Saturday this gives Sun→Sat = 7 days. In the
  // local-Saturday/UTC-Sunday gap window the loop body never runs and
  // we report 0 — correct for "the new UTC week just started, no
  // confirmed steps in it yet". Subsequent submits ratchet up via
  // 1z.131 backend monotonic max once HealthKit refreshes the new
  // week's daily buckets.
  function lbSumCurrentWeekSteps(stepsDaily) {
    // v3 Phase 1z.219 — Pacific anchor. The variable name stays
    // 'weekStartUTC' for git-blame continuity but the value is
    // now the Pacific Sunday key. The dateStr >= weekStartPT
    // compare still works because both sides are 'YYYY-MM-DD'
    // strings and lexicographic compare is timezone-blind.
    const weekStartUTC = lbGetCurrentWeekStartPT();
    let dateStr = getDeviceLocalDate();
    let sum = 0;
    // Hard cap of 8 iterations as a defensive guard against an
    // unexpected date-string compare anomaly.
    for (let i = 0; i < 8 && dateStr >= weekStartUTC; i++) {
      sum += (stepsDaily[dateStr] || 0);
      const prev = lbPrevDate(dateStr);
      if (prev === dateStr) break;
      dateStr = prev;
    }
    return sum;
  }

  // Drop entries older than retention window from a date-keyed map.
  // Keeps localStorage lean — the calendar-week step sum only needs
  // the last 7 entries, but we keep 30 for future "best week of
  // last 30 days"-style slots.
  function lbPruneDailyMap(map, retentionDays) {
    const cutoff = new Date();
    cutoff.setDate(cutoff.getDate() - retentionDays);
    const cutoffStr = cutoff.getFullYear() + '-' +
      String(cutoff.getMonth() + 1).padStart(2, '0') + '-' +
      String(cutoff.getDate()).padStart(2, '0');
    for (const k in map) {
      if (k < cutoffStr) delete map[k];
    }
  }

  // Step recording. Idempotent in the sense that re-calling with a
  // higher number for the same day overwrites (HealthKit step counts
  // can backfill upward as the day progresses; we want the latest
  // figure). Best peak is updated whenever the current-week running
  // sum exceeds the stored historical best. The field name is kept
  // as `best_7day_step_total` to avoid a localStorage migration —
  // semantics are now "best calendar-week sum (Sun→Sat) ever."
  function lbRecordStepsToday(steps) {
    if (typeof steps !== 'number' || !Number.isFinite(steps) || steps < 0) return;
    const state = loadLeaderboardState();
    const today = getDeviceLocalDate();
    const prev  = state.steps_daily[today] || 0;
    const next  = Math.round(steps);
    // W304 — lifetime steps accrual (for all-time avg steps/day on the profile
    // card). On the first-ever record, bootstrap from the retained daily map (up
    // to 30 days) so existing users start with a representative average, not a
    // 1-day one. Thereafter add only the delta (next - prev) so a backfilled-
    // upward HealthKit figure for today never double-counts. Runs BEFORE the
    // steps_daily[today] write so the seed sees today's previous value.
    if (!state.lifetime_steps_start_date) {
      const _keys = Object.keys(state.steps_daily);
      if (_keys.length) {
        state.lifetime_steps_start_date = _keys.sort()[0];
        let _seed = 0; _keys.forEach((k) => { _seed += (state.steps_daily[k] || 0); });
        state.lifetime_steps_total = _seed;   // includes today's prev; the delta below adds only the increase
      } else {
        state.lifetime_steps_start_date = today;
      }
    }
    const _stepDelta = next - prev;
    if (_stepDelta > 0) state.lifetime_steps_total = (state.lifetime_steps_total || 0) + _stepDelta;
    state.steps_daily[today] = next;
    lbPruneDailyMap(state.steps_daily, LB_DAILY_RETENTION_DAYS);

    // W714 — walk streak. Steps accumulate through the day, so credit today ONCE, the
    // moment it crosses the threshold (guard on last_walk_eval_date !== today so repeated
    // intraday HealthKit updates don't double-count). A missed day isn't reset here (the
    // day may still cross later) — instead the gap is caught when the NEXT qualifying day
    // arrives with last_walk_eval_date older than yesterday. Mirrors the sleep-streak eval.
    if (next >= LB_WALK_STEPS_THRESHOLD && state.last_walk_eval_date !== today) {
      const _wprev = lbPrevDate(today);
      state.current_walk_streak = (state.last_walk_eval_date === _wprev)
        ? (state.current_walk_streak || 0) + 1
        : 1;
      if (state.current_walk_streak > (state.best_walk_streak || 0)) {
        state.best_walk_streak = state.current_walk_streak;
      }
      state.last_walk_eval_date = today;
    }

    const weekSum = lbSumCurrentWeekSteps(state.steps_daily);
    if (weekSum > state.best_7day_step_total) {
      state.best_7day_step_total = weekSum;
      state.best_7day_step_window_end = today;
    }
    saveLeaderboardState(state);

    // v3 Phase 1z.254 — Re-push to backend when HealthKit step data
    // lands. Before this fix, the only triggers for lbSubmitAllMetrics
    // were cold-launch and visibilitychange resume. On a cold launch
    // the submit fires BEFORE HealthKit populates state.steps_daily,
    // so snap.steps_last_7_days = 0 → either allZero skips the submit
    // entirely (when streaks are also 0) or Branch 1 SELF-HEAL writes
    // 0 to the backend (when streaks are non-zero). Without a
    // re-submit when steps actually land, the row stays at 0 until
    // the user backgrounds + resumes 5+ min later — which is what
    // Galilea hit after updating to w121: her real 18,259 was visible
    // on her local UI but never reached the backend.
    // The debounced wrapper still throttles to 5 min so a flurry of
    // HK samples can't hammer the worker. Only re-submit when steps
    // actually changed (skip the rerun on idempotent same-value
    // refreshes that the comment at lbRecordStepsToday's caller
    // already protects against).
    if (next !== prev) {
      try { lbSubmitAllMetricsDebounced(); } catch (_) {}
    }
  }

  // v3 Phase 1z.125 / 1z.139 — flights climbed weekly sum.
  // Mirrors lbSumCurrentWeekSteps exactly. 1z.139 fixes the
  // device-local-vs-UTC week boundary bug that allowed last week's
  // total to be submitted under the new UTC week_start during the
  // local-Saturday/UTC-Sunday gap window. Same Sunday-UTC anchor
  // as the backend WEEKLY_METRICS scope.
  function lbSumCurrentWeekFlights(flightsDaily) {
    // v3 Phase 1z.219 — Pacific anchor; mirrors lbSumCurrentWeekSteps.
    const weekStartUTC = lbGetCurrentWeekStartPT();
    let dateStr = getDeviceLocalDate();
    let sum = 0;
    for (let i = 0; i < 8 && dateStr >= weekStartUTC; i++) {
      sum += (flightsDaily[dateStr] || 0);
      const prev = lbPrevDate(dateStr);
      if (prev === dateStr) break;
      dateStr = prev;
    }
    return sum;
  }

  // v3 Phase 1z.125 — flights climbed recording. Mirrors
  // lbRecordStepsToday. Idempotent: re-calling with a larger value
  // for the same day overwrites (HealthKit's flights counter
  // increments through the day; we want the latest figure). Best
  // peak updated when the current-week running sum exceeds the
  // historical best.
  function lbRecordFlightsToday(flights) {
    if (typeof flights !== 'number' || !Number.isFinite(flights) || flights < 0) return;
    const state = loadLeaderboardState();
    const today = getDeviceLocalDate();
    state.flights_daily[today] = Math.round(flights);
    lbPruneDailyMap(state.flights_daily, LB_DAILY_RETENTION_DAYS);

    const weekSum = lbSumCurrentWeekFlights(state.flights_daily);
    if (weekSum > state.best_7day_flights_total) {
      state.best_7day_flights_total = weekSum;
      state.best_7day_flights_window_end = today;
    }
    saveLeaderboardState(state);

    // v3 Phase 1z.273M — Public flights_milestone_bucket events.
    // Choke point: every code path that records today's flights
    // value (range refresh OK branch + today-only fallback) lands
    // here. Helper iterates 10/25/50/100 and fires at most once
    // per (dateKey, bucket) per device via localStorage marker.
    // Only the bucket integer ships in the payload — never the
    // raw flights count, which stays private in state.flights_daily.
    try { _emitFlightsBucketEventsIfNeeded(Math.round(flights), today); } catch (_) {}
  }

  // v3 Phase 1z.126 — fixes "Richie shows 0 flights this week even
  // though Apple Health has earlier-week flights" by backfilling the
  // entire current week from HealthKit on every autoVerifyWalk tick
  // (throttled) and whenever the Flights Climbed sheet opens.
  //
  // Why this is needed: lbRecordFlightsToday only writes today's value
  // forward. On first launch after the 1z.125 update lands, the
  // flights_daily map is empty and only today's bar is recorded —
  // historical days from the current week (which Health has) never
  // populate. lbSumCurrentWeekFlights then returns 0 → leaderboard
  // submit value = 0 → modal renders Richie at 0.
  //
  // Fix: walk each day from this week's Sunday → today inclusive and
  // query Health.getFlightsClimbedBetween for that day's [00:00, 23:59]
  // window, populating flights_daily so the existing sum logic
  // produces the correct weekly total. Per-day calls (instead of one
  // range call) preserve the daily breakdown needed for best-week
  // tracking and the future Stats-tab flights graph.
  //
  // Throttle: 5 minutes between non-forced refreshes (matches the
  // cadence of autoVerifyWalk's visibility-change rhythm without
  // hammering HealthKit). Forced refreshes (sheet open) bypass.
  let _lbFlightsWeekRefreshAt = 0;
  const _LB_FLIGHTS_WEEK_REFRESH_MIN_MS = 5 * 60 * 1000;

  async function lbRefreshFlightsThisWeekFromHealth(opts) {
    const force = !!(opts && opts.force);
    try {
      if (!force && (Date.now() - _lbFlightsWeekRefreshAt) < _LB_FLIGHTS_WEEK_REFRESH_MIN_MS) {
        return { ok: false, reason: 'throttled' };
      }
      if (!window.Health || typeof Health.isAvailable !== 'function' || !Health.isAvailable()) {
        return { ok: false, reason: 'health-unavailable' };
      }
      if (typeof Health.permissionStatus === 'function') {
        const st = Health.permissionStatus();
        if (st === 'denied' || st === 'unknown') return { ok: false, reason: 'permission-' + st };
      }
      if (typeof Health.getFlightsClimbedBetween !== 'function') {
        return { ok: false, reason: 'no-range-query' };
      }

      // W353 (G6) — build the day list to match the PT week the weekly SUM uses
      // (lbSumCurrentWeekFlights walks back to lbGetCurrentWeekStartPT). The old
      // device-local day-of-week range could miss PT-week days for non-PT users
      // near the Sunday-midnight-PT boundary -> those read 0 -> understated weekly
      // flights. Mirror lbSumCurrentWeekSteps. Always include today (no empty list).
      const _flWeekStart = lbGetCurrentWeekStartPT();
      const days = [getDeviceLocalDate()];
      let dateStr = lbPrevDate(days[0]);
      let _flGuard = 0;
      while (dateStr >= _flWeekStart && _flGuard++ < 8) {
        days.unshift(dateStr);
        dateStr = lbPrevDate(dateStr);
      }
      const weekStartISO = new Date(days[0] + 'T00:00:00').toISOString();
      const weekEndISO   = new Date().toISOString();

      const state = loadLeaderboardState();
      const previousSnapshotValue = lbSumCurrentWeekFlights(state.flights_daily);

      try {
        if (typeof _addHealthVerifyBreadcrumb === 'function') {
          _addHealthVerifyBreadcrumb('leaderboard-flights-week-refresh-start', {
            weekStartISO, weekEndISO, dayCount: days.length,
          });
        }
      } catch (_) {}

      // Per-day query so flights_daily keeps its day granularity.
      let total = 0;
      for (const day of days) {
        const startISO = new Date(day + 'T00:00:00').toISOString();
        const endISO   = new Date(day + 'T23:59:59.999').toISOString();
        let flights = null;
        try { flights = await Health.getFlightsClimbedBetween(startISO, endISO); }
        catch (_) { flights = null; }
        if (typeof flights === 'number' && Number.isFinite(flights) && flights >= 0) {
          const rounded = Math.min(Math.round(flights), 1000);
          state.flights_daily[day] = rounded;
          total += rounded;
        }
      }
      lbPruneDailyMap(state.flights_daily, LB_DAILY_RETENTION_DAYS);
      const weekSum = lbSumCurrentWeekFlights(state.flights_daily);
      if (weekSum > state.best_7day_flights_total) {
        state.best_7day_flights_total = weekSum;
        state.best_7day_flights_window_end = getDeviceLocalDate();
      }
      saveLeaderboardState(state);
      _lbFlightsWeekRefreshAt = Date.now();

      try {
        if (typeof _addHealthVerifyBreadcrumb === 'function') {
          _addHealthVerifyBreadcrumb('leaderboard-flights-week-refresh-success', {
            flightsThisWeek: weekSum,
            previousSnapshotValue: previousSnapshotValue,
            storedValue: weekSum,
            source: 'healthkit-range',
          });
        }
      } catch (_) {}
      return { ok: true, flightsThisWeek: weekSum };
    } catch (e) {
      try {
        if (typeof _addHealthVerifyBreadcrumb === 'function') {
          _addHealthVerifyBreadcrumb('leaderboard-flights-week-refresh-fail', {
            reason: (e && e.message) ? String(e.message).slice(0, 80) : 'unknown',
          });
        }
      } catch (_) {}
      return { ok: false, reason: 'exception' };
    }
  }

  // Sleep recording — both metrics (hours + bedtime) in one call,
  // since they come from the same Health.getSleepLastNight() roundtrip.
  // Each metric tracks independently and is idempotent on nightDate.
  //
  // Streak gap rule: if last_*_eval_date is set AND not equal to
  // (nightDate - 1 day), the streak is dead before tonight's eval
  // (a missed night = no qualifying entry = break). Tonight's outcome
  // then determines whether streak starts fresh at 1 or stays at 0.
  function lbRecordSleepNight(sleepHours, bedtimeBeforeMidnight, nightDate) {
    if (!nightDate) return;
    const state = loadLeaderboardState();
    let mutated = false;

    // ── Sleep hours ─────────────────────────────────────────
    if (typeof sleepHours === 'number' && Number.isFinite(sleepHours) && sleepHours >= 0) {
      state.sleep_hours_daily[nightDate] = Number(sleepHours.toFixed(2));
      lbPruneDailyMap(state.sleep_hours_daily, LB_DAILY_RETENTION_DAYS);
      mutated = true;

      if (state.last_sleep_eval_date !== nightDate) {
        const prev = lbPrevDate(nightDate);
        if (state.last_sleep_eval_date && state.last_sleep_eval_date !== prev) {
          state.current_sleep_streak = 0;
        }
        if (sleepHours >= LB_SLEEP_HOURS_THRESHOLD) {
          state.current_sleep_streak += 1;
          if (state.current_sleep_streak > state.best_sleep_streak) {
            state.best_sleep_streak = state.current_sleep_streak;
          }
        } else {
          state.current_sleep_streak = 0;
        }
        state.last_sleep_eval_date = nightDate;
      }
    }

    // ── Bedtime before midnight ─────────────────────────────
    if (typeof bedtimeBeforeMidnight === 'boolean') {
      state.bedtime_daily[nightDate] = bedtimeBeforeMidnight;
      lbPruneDailyMap(state.bedtime_daily, LB_DAILY_RETENTION_DAYS);
      mutated = true;

      if (state.last_bedtime_eval_date !== nightDate) {
        const prev = lbPrevDate(nightDate);
        if (state.last_bedtime_eval_date && state.last_bedtime_eval_date !== prev) {
          state.current_bedtime_streak = 0;
        }
        if (bedtimeBeforeMidnight === true) {
          state.current_bedtime_streak += 1;
          if (state.current_bedtime_streak > state.best_bedtime_streak) {
            state.best_bedtime_streak = state.current_bedtime_streak;
          }
        } else {
          state.current_bedtime_streak = 0;
        }
        state.last_bedtime_eval_date = nightDate;
      }
    }

    if (mutated) saveLeaderboardState(state);
  }

  // v3 Phase 1z.118 — derive workout streak from the habit completion
  // ledger. Mirrors _lbComputeSleepStreakFromCompletions exactly,
  // but for the canonical Workout habit (read-only HK-verified;
  // every entry in completions[date] for the Workout id was sealed
  // by autoVerifyStrengthTraining → toggleHabit). Also recognizes
  // the legacy 'Strength training' habit name (pre-1z.105) so a
  // device that hasn't run the rename migration yet still counts
  // those days. Returns { current, best, completionDateCount,
  // workoutHabitId, startedFromYesterday } or null on bad inputs.
  function _lbComputeWorkoutStreakFromCompletions() {
    try {
      if (typeof habits === 'undefined' || !Array.isArray(habits)) return null;
      if (typeof completions === 'undefined' || !completions) return null;
      if (typeof today !== 'string' || !today) return null;
      // Defensive: recognize both 'Workout' (canonical post-1z.105)
      // and 'Strength training' (legacy pre-1z.105) on non-custom
      // habits. 1z.107 ships the same dual-name guard in
      // findStrengthHabit / isStrengthWorkoutHabit.
      const workoutHabit = habits.find(h =>
        h && !h.custom && (h.name === 'Workout' || h.name === 'Strength training')
      );
      if (!workoutHabit) return null;
      const workoutId = workoutHabit.id;

      // Current streak: walk backwards from today. If today's Workout
      // hasn't been recorded yet (user pulls leaderboard at noon
      // before a workout), start from yesterday so the streak isn't
      // artificially zeroed by a not-yet-evaluated day.
      const start = new Date(today + 'T00:00:00');
      const todayList = completions[today];
      const todayDone = Array.isArray(todayList) && todayList.includes(workoutId);
      const startOffset = todayDone ? 0 : 1;

      let current = 0;
      for (let j = 0; j < 365; j++) {
        const d = new Date(start);
        d.setDate(start.getDate() - startOffset - j);
        const ds = d.getFullYear() + '-' +
                   String(d.getMonth() + 1).padStart(2, '0') + '-' +
                   String(d.getDate()).padStart(2, '0');
        const dayList = completions[ds];
        const done = Array.isArray(dayList) && dayList.includes(workoutId);
        if (done) current++;
        else break;
      }

      // Best streak: longest consecutive run across all completion
      // dates for this id.
      const allDates = Object.keys(completions || {})
        .filter(d => Array.isArray(completions[d]) && completions[d].includes(workoutId))
        .sort();
      let best = current;
      if (allDates.length > 0) {
        let run = 1;
        let longest = 1;
        for (let i = 1; i < allDates.length; i++) {
          const prev = new Date(allDates[i - 1] + 'T00:00:00');
          const cur  = new Date(allDates[i]     + 'T00:00:00');
          const diffDays = Math.round((cur - prev) / 86400000);
          if (diffDays === 1) {
            run++;
            if (run > longest) longest = run;
          } else {
            run = 1;
          }
        }
        if (longest > best) best = longest;
      }

      return {
        current: current,
        best:    best,
        completionDateCount: allDates.length,
        workoutHabitId: workoutId,
        startedFromYesterday: !todayDone,
      };
    } catch (_) {
      return null;
    }
  }

  // v3 Phase 1z.115 — derive sleep streak from the habit completion
  // ledger instead of the standalone state.current_sleep_streak field.
  //
  // ROOT CAUSE: lbRecordSleepNight's gap-reset rule (line ~6266) sees
  // any day where the user didn't open the app as a streak break,
  // even though HealthKit has data for that night. The habit
  // completion ledger (completions[dateStr] containing the Sleep id)
  // is the user-visible source-of-truth — it shows every night Sleep
  // was sealed, including via _backfillSleepYesterday on the next-day
  // open. By deriving the leaderboard streak from completions, we
  // always agree with the weekly ledger UI.
  //
  // Sleep is read-only (isReadOnlyAutoVerifyHabit('Sleep') === true).
  // Manual checking is impossible. So every Sleep entry in completions
  // got there via autoVerifySleep → toggleHabit, which means each
  // entry is HK-verified by construction. The "Verified by Apple
  // Health" leaderboard copy is preserved.
  function _lbComputeSleepStreakFromCompletions() {
    try {
      if (typeof habits === 'undefined' || !Array.isArray(habits)) return null;
      if (typeof completions === 'undefined' || !completions) return null;
      if (typeof today !== 'string' || !today) return null;
      const sleepHabit = habits.find(h => h && !h.custom && h.name === 'Sleep');
      if (!sleepHabit) return null;
      const sleepId = sleepHabit.id;

      // Current streak: walk backwards from today. If today's Sleep
      // hasn't been recorded yet (user pulls leaderboard at noon
      // before tonight's auto-verify), start from yesterday so the
      // streak isn't artificially zeroed by a not-yet-evaluated day.
      const start = new Date(today + 'T00:00:00');
      const todayList = completions[today];
      const todayDone = Array.isArray(todayList) && todayList.includes(sleepId);
      const startOffset = todayDone ? 0 : 1;

      let current = 0;
      for (let j = 0; j < 365; j++) {
        const d = new Date(start);
        d.setDate(start.getDate() - startOffset - j);
        const ds = d.getFullYear() + '-' +
                   String(d.getMonth() + 1).padStart(2, '0') + '-' +
                   String(d.getDate()).padStart(2, '0');
        const dayList = completions[ds];
        const done = Array.isArray(dayList) && dayList.includes(sleepId);
        if (done) current++;
        else break;
      }

      // Best streak: iterate over all dates where Sleep was completed,
      // sort, find the longest consecutive run.
      const allDates = Object.keys(completions || {})
        .filter(d => Array.isArray(completions[d]) && completions[d].includes(sleepId))
        .sort();
      let best = current;
      if (allDates.length > 0) {
        let run = 1;
        let longest = 1;
        for (let i = 1; i < allDates.length; i++) {
          const prev = new Date(allDates[i - 1] + 'T00:00:00');
          const cur  = new Date(allDates[i]     + 'T00:00:00');
          const diffDays = Math.round((cur - prev) / 86400000);
          if (diffDays === 1) {
            run++;
            if (run > longest) longest = run;
          } else {
            run = 1;
          }
        }
        if (longest > best) best = longest;
      }

      return {
        current: current,
        best:    best,
        completionDateCount: allDates.length,
        sleepHabitId: sleepId,
        startedFromYesterday: !todayDone,
      };
    } catch (_) {
      return null;
    }
  }

  // Read-only snapshot for UI + leaderboard submit. Computes the
  // current-week step sum on demand (Sunday 00:00 → today inclusive,
  // resets every Sunday at device-local midnight). The field name
  // `steps_last_7_days` is kept for callsite compatibility — its
  // semantics are now "current calendar-week step total."
  function lbGetSnapshot() {
    const state = loadLeaderboardState();

    // v3 Phase 1z.115 — prefer ledger-derived sleep streak. Falls
    // back to state.current_sleep_streak if completions/habits are
    // not yet initialized (defensive — shouldn't happen in practice).
    let currentSleepStreak = state.current_sleep_streak;
    let bestSleepStreak    = state.best_sleep_streak;
    let ledgerStreakInfo   = null;
    try {
      const fromLedger = _lbComputeSleepStreakFromCompletions();
      if (fromLedger && typeof fromLedger.current === 'number') {
        ledgerStreakInfo  = fromLedger;
        // Prefer the LARGER value — the ledger catches retroactive
        // _backfillSleepYesterday completions and any nights where
        // lbRecordSleepNight's gap-reset zeroed the standalone
        // counter despite HK data being present.
        currentSleepStreak = Math.max(currentSleepStreak || 0, fromLedger.current);
        bestSleepStreak    = Math.max(bestSleepStreak    || 0, fromLedger.best);
      }
    } catch (_) {}

    try {
      if (typeof _addHealthVerifyBreadcrumb === 'function') {
        _addHealthVerifyBreadcrumb('leaderboard-sleep-streak-result', {
          stateCurrent:  state.current_sleep_streak,
          stateBest:     state.best_sleep_streak,
          ledgerCurrent: ledgerStreakInfo ? ledgerStreakInfo.current : null,
          ledgerBest:    ledgerStreakInfo ? ledgerStreakInfo.best : null,
          ledgerCompletionDateCount: ledgerStreakInfo ? ledgerStreakInfo.completionDateCount : null,
          ledgerStartedFromYesterday: ledgerStreakInfo ? ledgerStreakInfo.startedFromYesterday : null,
          finalCurrent:  currentSleepStreak,
          finalBest:     bestSleepStreak,
        });
      }
    } catch (_) {}

    // v3 Phase 1z.165 — Guild Hall feat row for streak milestones.
    // We're already inside lbGetSnapshot, which is called every time
    // the leaderboard preview refreshes (i.e. on every habit toggle).
    // Compare current sleep/workout streaks against milestone bands
    // (7 / 14 / 30 / 100 / 365 days) and fire ONE row per habit per
    // milestone crossing — idempotency key bakes the habit name +
    // milestone into the seen-marker so each band fires at most once.
    try {
      const workoutFromLedger = _lbComputeWorkoutStreakFromCompletions();
      const workoutCurrent = (workoutFromLedger && typeof workoutFromLedger.current === 'number')
        ? workoutFromLedger.current : 0;
      _guildhallMaybeFireStreakMilestone('Sleep',   currentSleepStreak);
      _guildhallMaybeFireStreakMilestone('Workout', workoutCurrent);
    } catch (_) {}

    // W304 — lifetime avg steps/day = running total / days since first record.
    // Inclusive of the start day; divisor floored at 1 (never NaN/zero).
    let _avgStepsLifetime = 0;
    try {
      const _sd = state.lifetime_steps_start_date;
      let _days = 1;
      if (_sd) { const _ms = Date.now() - new Date(_sd + 'T00:00:00').getTime(); _days = Math.max(1, Math.floor(_ms / 86400000) + 1); }
      _avgStepsLifetime = Math.round((state.lifetime_steps_total || 0) / _days);
    } catch (_) {}
    return {
      steps_last_7_days:         lbSumCurrentWeekSteps(state.steps_daily),
      avg_steps_per_day_lifetime: _avgStepsLifetime,
      best_7day_step_total:      state.best_7day_step_total,
      best_7day_step_window_end: state.best_7day_step_window_end,
      current_sleep_streak:      currentSleepStreak,
      best_sleep_streak:         bestSleepStreak,
      current_bedtime_streak:    state.current_bedtime_streak,
      best_bedtime_streak:       state.best_bedtime_streak,
      // v3 Phase 1z.118 — workout streak derived from completion
      // ledger only. Not persisted to state, not submitted to
      // backend (workout_streak metric is client-only in this
      // patch). The leaderboard preview card + sheet read these
      // fields the same way they read sleep_streak.
      current_workout_streak:    (function () {
        try {
          const fromLedger = _lbComputeWorkoutStreakFromCompletions();
          return (fromLedger && typeof fromLedger.current === 'number') ? fromLedger.current : 0;
        } catch (_) { return 0; }
      })(),
      best_workout_streak:       (function () {
        try {
          const fromLedger = _lbComputeWorkoutStreakFromCompletions();
          return (fromLedger && typeof fromLedger.best === 'number') ? fromLedger.best : 0;
        } catch (_) { return 0; }
      })(),
      // v3 Phase 1z.125 — weekly flights climbed. Source-of-truth
      // is the state.flights_daily map written by
      // lbRecordFlightsToday(). The leaderboard preview card +
      // sheet read these fields the same way they read
      // steps_last_7_days / best_7day_step_total.
      flights_this_week:         lbSumCurrentWeekFlights(state.flights_daily),
      best_flights_week:         state.best_7day_flights_total,
      best_flights_window_end:   state.best_7day_flights_window_end,
    };
  }

  try {
    window.Leaderboard = {
      getSnapshot:      lbGetSnapshot,
      recordStepsToday: lbRecordStepsToday,
      // v3 Phase 1z.125 — flights climbed weekly recorder.
      recordFlightsToday: lbRecordFlightsToday,
      // v3 Phase 1z.126 — full-week HealthKit backfill for flights.
      refreshFlightsThisWeekFromHealth: lbRefreshFlightsThisWeekFromHealth,
      recordSleepNight: lbRecordSleepNight,
      _state:           loadLeaderboardState, // dev-only: full raw state
      // v3 Phase 1z.115 — exposed for Playwright regression tests.
      __test_computeSleepStreakFromCompletions: _lbComputeSleepStreakFromCompletions,
      // v3 Phase 1z.118 — workout streak ledger derivation, exposed
      // for Playwright regression tests.
      __test_computeWorkoutStreakFromCompletions: _lbComputeWorkoutStreakFromCompletions,
      // v3 Phase 1z.116 — min-qualifying-score table + simulate filter
      // surfaces for Playwright regression tests.
      __test_getMinQualifyingScore: function (metric) {
        try { return (typeof _LB_MIN_QUALIFYING_SCORE !== 'undefined') ? _LB_MIN_QUALIFYING_SCORE[metric] : undefined; }
        catch (_) { return undefined; }
      },
      __test_maybeSimulate: function (metric, top, me) {
        try { return (typeof _lbMaybeSimulate === 'function') ? _lbMaybeSimulate(metric, top, me) : null; }
        catch (_) { return null; }
      },
      // Getters returning live references to the outer-scope habits +
      // completions so test code can read what state the helper sees
      // and seed scenarios deterministically. Returns null if the
      // outer-scope vars aren't initialized yet (e.g. test runs before
      // the app's load() finished).
      __test_getHabits: function () {
        try { return (typeof habits !== 'undefined') ? habits : null; }
        catch (_) { return null; }
      },
      __test_getCompletions: function () {
        try { return (typeof completions !== 'undefined') ? completions : null; }
        catch (_) { return null; }
      },
      __test_getToday: function () {
        try { return (typeof today !== 'undefined') ? today : null; }
        catch (_) { return null; }
      },
    };
  } catch (_) {}

  // ── v2.1.0 Phase C — submission orchestration ───────────────
  // Pushes the user's current metric snapshot to the backend so the
  // leaderboard can rank them. Fires three POSTs in parallel:
  //   step_total      ← snap.steps_last_7_days
  //   sleep_streak    ← snap.current_sleep_streak
  //   bedtime_streak  ← snap.current_bedtime_streak
  // Each value is validated as a non-negative integer and clamped to
  // a sane client-side cap (the backend has its own validation; the
  // cap here just prevents accidental overflow from a corrupt local
  // state).
