  // ── Coachmark engine ────────────────────────────────────────────────
  // Stateful: tracks current beat + line + typewriter progress.
  // Tap behavior:
  //   - mid-typewriter → skip to end of current line
  //   - line typed, more lines in beat → advance to next line
  //   - last line of beat, more beats → advance to next beat
  //   - last line of last beat → show CTA; tap outside CTA does nothing
  // Storage key set on dismissal (regardless of where the user dismissed).
  function _faRunCoachmark(spec) {
    const overlay = document.getElementById('fa-coachmark-overlay');
    if (!overlay || !spec || !Array.isArray(spec.beats)) return;
    const sheet   = overlay.querySelector('.fa-coach-sheet');
    const figEl   = document.getElementById('fa-coach-figure');
    const speech  = document.getElementById('fa-coach-speech');
    const dots    = document.getElementById('fa-coach-dots');
    const footer  = document.getElementById('fa-coach-footer');
    const titleEl = document.getElementById('fa-coach-title');
    if (!sheet || !figEl || !speech || !dots || !footer || !titleEl) return;

    titleEl.textContent = 'THE FIRST AWAKENED';
    overlay.dataset.context = spec.context || '';

    const reducedMotion = (window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches);
    const tw = { timer: null };
    let bi = 0;
    let li = 0;

    function setFigure(pose) {
      const safe = (typeof pose === 'string') ? pose.replace(/[^a-z]/gi, '') : 'idle';
      figEl.innerHTML = '<img src="assets/coach/first-awakened-' + safe +
        '.png" alt="The First Awakened — ' + safe + ' pose" class="fa-coach-figure-img">';
    }

    function renderDots() {
      let html = '';
      for (let i = 0; i < spec.beats.length; i++) {
        const cls = (i === bi) ? 'fa-coach-dot is-active'
                  : (i < bi)  ? 'fa-coach-dot is-past'
                              : 'fa-coach-dot';
        html += '<span class="' + cls + '"></span>';
      }
      dots.innerHTML = html;
    }

    function renderFooter(mode, ctaLabel) {
      if (mode === 'cta') {
        footer.innerHTML = '<button id="fa-coach-cta" class="fa-coach-cta" type="button">' +
          (ctaLabel || 'CONTINUE').replace(/[<>&]/g, '') + '</button>';
        const btn = document.getElementById('fa-coach-cta');
        if (btn) btn.addEventListener('click', function (e) {
          e.stopPropagation();
          dismiss();
        });
      } else if (mode === 'skip') {
        footer.innerHTML = '<span class="fa-coach-hint">TAP TO SKIP ' +
          '<svg width="16" height="9" viewBox="0 0 16 9" aria-hidden="true">' +
          '<path d="M1 4.5h13M10 1l4 3.5L10 8" stroke="currentColor" stroke-width="1.3" fill="none" stroke-linecap="round" stroke-linejoin="round"/></svg></span>';
      } else { // 'next'
        footer.innerHTML = '<span class="fa-coach-hint">TAP TO CONTINUE ' +
          '<svg width="16" height="9" viewBox="0 0 16 9" aria-hidden="true">' +
          '<path d="M1 4.5h13M10 1l4 3.5L10 8" stroke="currentColor" stroke-width="1.3" fill="none" stroke-linecap="round" stroke-linejoin="round"/></svg></span>';
      }
    }

    function priorLinesHtml(beat, upToIdx) {
      let html = '';
      for (let i = 0; i < upToIdx; i++) {
        html += '<p class="fa-coach-line fa-coach-line--prior">' +
          esc(beat.lines[i]) + '</p>';
      }
      return html;
    }

    function startLine() {
      const beat = spec.beats[bi];
      const line = beat.lines[li];
      // build static prior lines + current line container
      speech.innerHTML = priorLinesHtml(beat, li) +
        '<p class="fa-coach-line fa-coach-line--current"><span id="fa-coach-typed"></span>' +
        '<span class="fa-coach-caret">▍</span></p>';
      const typed = document.getElementById('fa-coach-typed');
      if (!typed) return;
      if (reducedMotion) {
        typed.textContent = line;
        onTypewriterDone();
        return;
      }
      let i = 0;
      clearInterval(tw.timer);
      tw.timer = setInterval(function () {
        i += 1;
        typed.textContent = line.slice(0, i);
        if (i >= line.length) {
          clearInterval(tw.timer);
          tw.timer = null;
          onTypewriterDone();
        }
      }, 30);
      renderFooter('skip');
    }

    function onTypewriterDone() {
      // remove caret
      const caret = speech.querySelector('.fa-coach-caret');
      if (caret) caret.remove();
      const beat = spec.beats[bi];
      const isLastLine = li === beat.lines.length - 1;
      const isLastBeat = bi === spec.beats.length - 1;
      if (isLastBeat && isLastLine) {
        renderFooter('cta', spec.cta);
      } else {
        renderFooter('next');
      }
    }

    function advance() {
      const beat = spec.beats[bi];
      // mid-type → complete line
      if (tw.timer) {
        clearInterval(tw.timer);
        tw.timer = null;
        const typed = document.getElementById('fa-coach-typed');
        if (typed) typed.textContent = beat.lines[li];
        onTypewriterDone();
        return;
      }
      const isLastLine = li === beat.lines.length - 1;
      const isLastBeat = bi === spec.beats.length - 1;
      if (!isLastLine) {
        li += 1;
        startLine();
        return;
      }
      if (!isLastBeat) {
        bi += 1;
        li = 0;
        setFigure(spec.beats[bi].pose);
        renderDots();
        startLine();
        return;
      }
      // last line of last beat — wait for CTA
    }

    function dismiss() {
      try {
        clearInterval(tw.timer);
        tw.timer = null;
      } catch (_) {}
      overlay.classList.add('hidden');
      overlay.setAttribute('aria-hidden', 'true');
      // Persist seen flag
      if (spec.storageKey) {
        try { localStorage.setItem(spec.storageKey, '1'); } catch (_) {}
      }
      document.removeEventListener('keydown', onKey, true);
      sheet.removeEventListener('click', onSheetClick);
      overlay.removeEventListener('click', onOverlayClick);
      // v3 Phase 1z.282D — Post-dismiss callback for queue-driven
      // coachmarks (rank-up gifts call this to release levelUpActive
      // and drain the next queue item). Fire-and-forget; swallowed
      // exceptions cannot stall the dismiss flow.
      if (typeof spec.onDismiss === 'function') {
        try { spec.onDismiss(); } catch (_) {}
      }
    }

    function onKey(e) {
      if (e.key === 'Escape') dismiss();
    }
    function onSheetClick(e) {
      // Ignore clicks on the CTA button — its own handler dismisses.
      const target = e.target;
      if (target && target.id === 'fa-coach-cta') return;
      e.stopPropagation();
      advance();
    }
    // v3 Phase 1z.283 W179 — Backdrop tap NO LONGER dismisses the
    // coachmark. Smoke test caught the accidental-exit failure mode:
    // a user tapping a hair outside the sheet on the welcome beat
    // ("HUNTER.") would lose the moment entirely, the storage key
    // got marked seen on dismiss, and the coach never re-fired —
    // i.e., they permanently missed the First Awakened greeting on
    // a stray tap. Dismissal is now gated on the explicit "TAP TO
    // CONTINUE" CTA on the final beat (or ESC for keyboard users
    // in dev / web preview). Sheet-tap-to-advance is preserved —
    // tapping anywhere on the SHEET still skips the typewriter and
    // advances through beats; only the dark backdrop is inert.
    function onOverlayClick(e) {
      // Intentional no-op. Kept wired only so e.stopPropagation in
      // onSheetClick has a matching listener boundary; removing
      // the addEventListener entirely would also be fine, this
      // form keeps the symmetry obvious to future readers.
      if (e.target === overlay) {
        // Absorb the tap so it doesn't bubble out, but do not dismiss.
        e.stopPropagation();
      }
    }

    // Wire interactions
    document.addEventListener('keydown', onKey, true);
    sheet.addEventListener('click', onSheetClick);
    overlay.addEventListener('click', onOverlayClick);

    // Initial render
    setFigure(spec.beats[0].pose);
    renderDots();
    startLine();

    overlay.classList.remove('hidden');
    overlay.setAttribute('aria-hidden', 'false');
  }

  function showQuestsCoachmark() {
    if (localStorage.getItem('hb_tour_quests_v1') === '1') return;
    _faRunCoachmark({
      context: 'quests',
      beats: FA_QUESTS_BEATS,
      cta: 'I’M READY',
      storageKey: 'hb_tour_quests_v1',
    });
  }
  function showItemsCoachmark() {
    if (localStorage.getItem('hb_tour_items_v1') === '1') return;
    _faRunCoachmark({
      context: 'items',
      beats: FA_ITEMS_BEATS,
      cta: 'UNDERSTOOD',
      storageKey: 'hb_tour_items_v1',
    });
  }
  // v3 Phase 1z.282B — First-vow commit acknowledgment.
  // Returns true if the modal was shown (caller can suppress its
  // normal toast); false if already seen (caller falls through to
  // toast path). Single beat, single tap — "BEGIN" CTA dismisses.
  function showFirstVowCoachmark(opts) {
    if (localStorage.getItem('hb_tour_first_vow_v1') === '1') return false;
    // v3 Phase 1z.282C — Cross-flow guard. Eagerly set the welcome-
    // back key when a new user goes through the First Vow modal so
    // they never see a redundant existing-user welcome on next
    // launch. Eager (vs on-dismiss) so even a user who backgrounds
    // mid-modal still skips welcome.
    try { localStorage.setItem('hb_tour_welcome_back_v1', '1'); } catch (_) {}
    // v3 Phase 1z.283 W178 — Optional onDismiss hook so callers can
    // chain follow-on flows (e.g. the pack-add notif prompt) AFTER
    // the coach is dismissed, instead of racing it. Backward-
    // compatible: the custom-path caller passes nothing → no chain.
    const _onDismiss = (opts && typeof opts.onDismiss === 'function') ? opts.onDismiss : undefined;
    // W509 — de-conflict with the W504 first-vow POINTER banner. On the main pack
    // path _completeOnboardingFinish fires BOTH this coachmark AND the pointer, and
    // both say "seal your first vow" — a redundant double-cue. The coachmark is the
    // richer, more prominent guide, so the moment it COMMITS to showing (self-gate
    // above already passed) suppress the banner for THIS session (persist=false) and
    // remove any already-rendered copy. Session-only by design: _firstVowPointerDismissed
    // resets next launch, so the banner stays a SAFETY NET on coachmark-less paths
    // (custom / Forge-Your-Own, reset re-entry) where this never fires or self-gates off.
    try { _dismissFirstVowPointer(false); } catch (_) {}
    // W580 — jump-program users get the plain-spoken program walkthrough
    // instead of the standard first-vow acknowledgment. Same storage key +
    // dismissal chain: it IS their first-vow welcome, just with the right
    // content. Non-jump users are byte-identical to before.
    const _isJumpUser = (typeof _jumpProgramUnlocked === 'function') && _jumpProgramUnlocked();
    _faRunCoachmark({
      context: _isJumpUser ? 'jump_welcome' : 'first_vow',
      beats: _isJumpUser ? FA_JUMP_WELCOME_BEATS : FA_FIRST_VOW_BEATS,
      cta: _isJumpUser ? 'START TRAINING' : 'BEGIN',
      storageKey: 'hb_tour_first_vow_v1',
      onDismiss: _onDismiss,
    });
    return true;
  }
  // W584 — replayable jump-program walkthrough. The First Awakened lives as a
  // tappable guide row under the vows (jump users only; #fa-program-guide,
  // toggled in renderHabits) and re-delivers the SAME welcome beats on demand.
  // No storageKey → _faRunCoachmark persists nothing; replayable forever. Only
  // the closing line is swapped: "your first full cycle begins on Monday" is
  // signup-time copy and would read wrong weeks into the program.
  function _faJumpProgramReplayBeats() {
    const beats = FA_JUMP_WELCOME_BEATS.map(function (b) { return { pose: b.pose, lines: b.lines.slice() }; });
    const last = beats[beats.length - 1];
    last.lines[last.lines.length - 1] = 'That is the whole design. Check today’s list and do the work. Now go.';
    return beats;
  }
  function showJumpProgramReplay() {
    _faRunCoachmark({
      context: 'jump_welcome_replay',
      beats: _faJumpProgramReplayBeats(),
      cta: 'BACK TO TRAINING',
    });
  }
  let _faGuideWired = false;
  function _faGuideSync() {
    const el = document.getElementById('fa-program-guide');
    if (!el) return;
    const show = (typeof _jumpProgramUnlocked === 'function') && _jumpProgramUnlocked();
    el.classList.toggle('hidden', !show);
    if (show && !_faGuideWired) {
      _faGuideWired = true;
      el.addEventListener('click', function () { try { showJumpProgramReplay(); } catch (_) {} });
    }
  }

  // v3 Phase 1z.282C — Welcome modal for existing users.
  // Gated on (has-habits AND key-unset). New users without habits
  // never trigger this — they go through onboarding instead.
  // First-launch-after-upgrade hook in init() fires this; the
  // First Vow commit modal also eagerly sets the key so new users
  // who finished onboarding never see redundant welcome.
  function showWelcomeBackCoachmark() {
    // v3 Phase 1z.283 W176 — Active-count gate. An all-archived user
    // is functionally "new again"; welcome-back is the wrong moment
    // (First Vow picker is what they should see).
    if (!Array.isArray(habits) || getActiveHabitCount() === 0) return false;
    if (localStorage.getItem('hb_tour_welcome_back_v1') === '1') return false;
    _faRunCoachmark({
      context: 'welcome_back',
      beats: FA_WELCOME_BACK_BEATS,
      cta: 'CONTINUE',
      storageKey: 'hb_tour_welcome_back_v1',
    });
    return true; // W363 — joins the one-per-launch dispatcher ladder
  }

  // ──────────────────────────────────────────────────────────────
  // v3 Phase 1z.283 W186 — First Awakened retention moments.
  //
  // Three rare, ceremonial check-ins that protect the Day 0–7
  // window and dignify a missed streak. NONE grant XP, souls,
  // relics, or stats. None alter streak / XP / rank math. None
  // touch backend. Each is one-shot per device (or per break
  // date), gated by an hb_* localStorage key that Reset All
  // Progress wipes.
  //
  // Engine reuse: every moment is rendered by _faRunCoachmark,
  // the same spec-driven coach used for First Vow / Welcome Back /
  // Quests / Stats / Rank-up. No new modal shell, no new art —
  // each moment selects from the five already-shipped FA poses
  // (idle, pointing, speaking, nodding, scroll).
  //
  // Priority (highest first): Streak-loss > Day 7 > Day 3.
  // Only ONE retention moment may fire per launch. Higher-
  // priority modals (onboarding, rank-up, Daily Insight, Field
  // Manual, Manage Vows, System Full, Reveal) silently defer the
  // retention check to the next launch.
  // ──────────────────────────────────────────────────────────────

  const FA_DAY3_BEATS = [
    { pose: 'idle', lines: [
      'Hunter.',
      'Three days is not a legacy.',
      'It is the first proof that the vow survived contact with your life.',
      'Continue.',
    ]},
  ];

  const FA_DAY7_BEATS = [
    { pose: 'speaking', lines: [
      'Seven days.',
      'The system has seen enough to begin counting you differently.',
      'Do not mistake this for arrival.',
      'It is only the gate.',
    ]},
  ];

  const FA_STREAKLOSS_BEATS = [
    { pose: 'nodding', lines: [
      'The streak broke.',
      'The discipline did not.',
      'Return to the vow.',
    ]},
  ];

  // Day 3 — fires once when the user opens the app on calendar
  // day 3 or later from origin. Skips if no active vow exists
  // (an all-archived user is functionally new again).
  function showDay3Coachmark() {
    if (localStorage.getItem('hb_tour_day3_v1') === '1') return false;
    if (typeof getDaysSinceOrigin !== 'function') return false;
    const days = getDaysSinceOrigin();
    if (typeof days !== 'number' || days < 3) return false;
    if (!Array.isArray(habits) || (typeof getActiveHabitCount === 'function' && getActiveHabitCount() === 0)) return false;
    _faRunCoachmark({
      context: 'day3',
      beats: FA_DAY3_BEATS,
      cta: 'CONTINUE',
      storageKey: 'hb_tour_day3_v1',
    });
    return true;
  }

  // Day 7 — fires once when the user opens the app on calendar
  // day 7 or later from origin. Silent-marks Day 3 as seen so a
  // user who first returns on Day 7+ doesn't see a back-to-back
  // "Three days…" stale check-in on the following launch.
  function showDay7Coachmark() {
    if (localStorage.getItem('hb_tour_day7_v1') === '1') return false;
    if (typeof getDaysSinceOrigin !== 'function') return false;
    const days = getDaysSinceOrigin();
    if (typeof days !== 'number' || days < 7) return false;
    if (!Array.isArray(habits) || (typeof getActiveHabitCount === 'function' && getActiveHabitCount() === 0)) return false;
    // Silent-mark Day 3 so a Day 7-first user doesn't see a stale
    // Day 3 check-in on a subsequent launch. Follows the same
    // eager-mark pattern as showFirstVowCoachmark's welcome-back
    // cross-flow guard at line 21908.
    try { localStorage.setItem('hb_tour_day3_v1', '1'); } catch (_) {}
    _faRunCoachmark({
      context: 'day7',
      beats: FA_DAY7_BEATS,
      cta: 'CONTINUE',
      storageKey: 'hb_tour_day7_v1',
    });
    return true;
  }

  // Streak-loss recovery — fires once per break date when a
  // pending comeback with brokenStreak ≥ 3 exists. The 3-day
  // floor filters trivial 1/2-day "breaks" that are usually rest
  // days, vacations, or onboarding-noise. Dedup key is per
  // breakDate so future breaks fire again.
  //
  // IMPORTANT — does NOT clear pendingComeback. The existing
  // Comeback XP reward (checkComebackOnActivity at app.js:12832)
  // depends on pendingComeback being non-null when the user
  // completes their next habit. Clearing it here would steal the
  // existing XP reward. The per-break storage key alone prevents
  // re-fire of the retention moment for the same break.
  function showStreakLossCoachmark() {
    if (!pendingComeback) return false;
    if (typeof pendingComeback.brokenStreak !== 'number' || pendingComeback.brokenStreak < 3) return false;
    const breakDate = String(pendingComeback.breakDate || '');
    if (!/^\d{4}-\d{2}-\d{2}$/.test(breakDate)) return false;
    const seenKey = 'hb_streakloss_seen_' + breakDate;
    if (localStorage.getItem(seenKey) === '1') return false;
    // User has actively archived everything → effectively
    // restarting; the recovery moment is the wrong narrative beat.
    if (!Array.isArray(habits) || (typeof getActiveHabitCount === 'function' && getActiveHabitCount() === 0)) return false;
    _faRunCoachmark({
      context: 'streakloss',
      beats: FA_STREAKLOSS_BEATS,
      cta: 'RETURN',
      storageKey: seenKey,
    });
    return true;
  }

  // Higher-priority modal active? If so, defer all retention
  // moments to the next launch — never stack on top of another
  // narrative beat or a critical system surface.
  function _isAnyHigherPriorityModalActive() {
    try {
      if (typeof levelUpActive !== 'undefined' && levelUpActive) return true;
    } catch (_) {}
    const ids = [
      'fa-coachmark-overlay', // another FA coachmark already open
      'cin-onboarding',       // cinematic onboarding
      'daily-insight-overlay',// morning briefing
      'fa-manual-overlay',    // field manual
      'mv-overlay',           // manage vows
      'system-full-overlay',  // 25-cap modal
      'reveal-overlay',       // boss / card reveal
      'wn-overlay',      // W362 - post-update What’s New sheet must defer day-beats
      'welcome-back-overlay', // W377 - day-2 welcome-back screen
      'wr-overlay',           // W657 - Week Recap ceremony (day-beats defer under it)
      'wi-overlay',           // W723 - members-only Weekly Insights sheet
      'arena-overlay',        // W657 - never mount a beat over a live fight (Ascent/PvP)
    ];
    for (let i = 0; i < ids.length; i++) {
      const el = document.getElementById(ids[i]);
      if (el && !el.classList.contains('hidden')) return true;
    }
    return false;
  }

  // Single decision point — ONE beat per launch. Priority order:
  //   1. Day-2 welcome-back screen (day-2-ONLY; cannot defer, so it is first)
  //   2. Existing-user welcome coachmark (once-ever; W363)
  //   3. Streak-loss recovery (most emotionally important)
  //   4. Day 7   ·   5. Day 3   ·   6. Daily insight (lowest)
  // Returns silently if a higher-priority modal is mounted —
  // does not retry, does not queue. Next launch reconsiders.
  function maybeShowFirstAwakenedRetentionMoment() {
    if (_isAnyHigherPriorityModalActive()) return;
    if (_maybeShowWelcomeBack()) return; // W367 — day-2 welcome-back screen is day-2-ONLY (cannot defer); must outrank the deferrable intro/milestones
    if (showWelcomeBackCoachmark()) return; // W363 — existing-user intro; was a separate +1500ms timer that raced this dispatcher
    if (showStreakLossCoachmark()) return;
    if (showDay7Coachmark()) return;
    if (showDay3Coachmark()) return;
    if (typeof shouldShowDailyInsight === 'function' && shouldShowDailyInsight()) { showDailyInsight(); return; } // W361 — daily insight is the lowest-priority beat
  }

  try {
    window.__showDay3Coachmark = showDay3Coachmark;
    window.__showDay7Coachmark = showDay7Coachmark;
    window.__showStreakLossCoachmark = showStreakLossCoachmark;
    window.__maybeShowFirstAwakenedRetentionMoment = maybeShowFirstAwakenedRetentionMoment;
  } catch (_) {}

  // ──────────────────────────────────────────────────────────────
  // v3 Phase 1z.283 W187 — Hunter Report share card.
  //
  // A 1200×1500 PNG generated locally via Canvas API after a major
  // rank-up. Triggered from drainLevelUpQueue() as a 'hunter_report'
  // queue item inserted at position 2 (after 'rank' and 'fa_rankup').
  // Per-rank idempotency via hb_hr_offered_<rankId>. Privacy: aggregate
  // fields only (alias, class, rank, XP, streak, bosses, souls). Never
  // habit names. Never HealthKit values. Never other users' aliases.
  //
  // Architecture (per design canvas notes deliverable 08):
  //   _hrCollectData()     — pure data assembly from local state
  //   _hrPaletteForRank()  — rank → hue/letter/glow accent map
  //   _hrPickQuote()       — dayOfYear % 5 for stable-per-share rotation
  //   _hrLoadFonts()       — awaits all required font weights
  //   _hrRenderCanvas()    — main 2400×3000 backing-store renderer
  //   _hrCanvasToFile()    — toBlob → File for native share
  //   _hrShareReport()     — 3-tier fallback (files → text+url → clip)
  //   openHunterReportPreview() / closeHunterReportPreview()
  //
  // No new dependencies (canvas already proven in 4 prod call sites,
  // navigator.share already proven in production at the since-removed shareOriginStory).
  // ──────────────────────────────────────────────────────────────

  // Rank → accent palette. Hues match the live app (status disc + 100K
  // club badge). letter is legibility-tuned for navy. glow drives the
  // aura/halo behind the medallion + crest.
  // W559 — hue/letter/glow canonicalized to the [data-rank] palette (E purple,
  // D cyan, C emerald, B amber, A red, S fuchsia, S+ gold); tags unchanged.
  const HR_RANK_PALETTE = {
    E:    { hue: '#8b5cf6', letter: '#c4b5fd', glow: 'rgba(139,92,246,0.55)',  tag: 'AWAKENING' },
    D:    { hue: '#22d3ee', letter: '#a5f3fc', glow: 'rgba(34,211,238,0.52)',  tag: 'PROVEN'    },
    C:    { hue: '#34d399', letter: '#6ee7b7', glow: 'rgba(52,211,153,0.52)',  tag: 'TEMPERED'  },
    B:    { hue: '#fbbf24', letter: '#fde68a', glow: 'rgba(251,191,36,0.52)',  tag: 'ASCENDANT' },
    A:    { hue: '#ef4444', letter: '#fca5a5', glow: 'rgba(239,68,68,0.52)',   tag: 'ELITE'     },
    S:    { hue: '#e879f9', letter: '#f5d0fe', glow: 'rgba(232,121,249,0.55)', tag: 'SOVEREIGN' },
    'S+': { hue: '#facc15', letter: '#fef08a', glow: 'rgba(250,204,21,0.55)',  tag: 'MONARCH'   },
  };

  // Class → display name + asset. Maps STAT → class identity.
  const HR_CLASS_PALETTE = {
    STR:   { name: 'Warrior',  color: '#ef4444', asset: 'avatar-warrior.png'  },
    VIT:   { name: 'Ranger',   color: '#ec4899', asset: 'avatar-ranger.png'   },
    INT:   { name: 'Mage',     color: '#3b82f6', asset: 'avatar-mage.png'     },
    FOCUS: { name: 'Assassin', color: '#eab308', asset: 'avatar-assassin.png' },
    WILL:  { name: 'Paladin',  color: '#f97316', asset: 'avatar-paladin.png'  },
    WLT:   { name: 'Merchant', color: '#f59e0b', asset: 'avatar-merchant.png' },
    SAGE:  { name: 'Sage',     color: '#8b5cf6', asset: 'avatar-sage.png'     },
  };

  // The First Awakened's voice — 5 lines, terse / ancient / earned.
  // Rotated by (dayOfYear) % 5 so each user's card is stable for the
  // current day but varies across re-shares over time.
  const HR_QUOTE_POOL = [
    'The climb is not granted. It is recorded.',
    'A rank is not given. It is witnessed.',
    'What you repeated, you became.',
    'The vow became record.',
    'The threshold remains. So do you.',
  ];

  function _hrPickQuote() {
    const now = new Date();
    const start = new Date(now.getFullYear(), 0, 0);
    const day = Math.floor((now - start) / 86400000);
    return HR_QUOTE_POOL[day % HR_QUOTE_POOL.length];
  }

  function _hrPaletteForRank(rankId) {
    return HR_RANK_PALETTE[rankId] || HR_RANK_PALETTE.E;
  }
  function _hrClassFromStat(statId) {
    return HR_CLASS_PALETTE[statId] || { name: 'Awakened', color: '#a78bfa', asset: 'avatar-base.png' };
  }

  // Pure data assembly. Aggregate fields only — never habit names,
  // schedule, HealthKit values, friend/guild aliases.
  function _hrCollectData(rankCtx) {
    rankCtx = rankCtx || {};
    let alias = 'Hunter';
    try {
      const u = (window.Auth && typeof Auth.getCurrentUser === 'function') ? Auth.getCurrentUser() : null;
      if (u && typeof u.alias === 'string' && u.alias) alias = u.alias;
    } catch (_) {}
    // Rank from ctx or from current totalPoints
    let rankId = rankCtx.rank || (function () {
      try {
        // W391 — _publicRankSummary returns { rankTier, ... }, never `id`.
        // Reading sum.id (undefined) made the Hunter Report share card fall
        // back to 'E' for EVERY hunter opened from the profile (the W315
        // on-demand path passes no rankCtx), e.g. a Floor-59/5,960-pt hunter
        // shared as "RANK E". rankTier is the real major-rank letter.
        const sum = _publicRankSummary(totalPoints);
        return sum && sum.rankTier ? sum.rankTier : 'E';
      } catch (_) { return 'E'; }
    })();
    // S+ / S+ normalization — context may pass 'splus' or 'S+'
    if (rankId === 'splus' || rankId === 'SPLUS') rankId = 'S+';
    let division = 'I';
    try {
      if (typeof getRankDivisionInfo === 'function') {
        const di = getRankDivisionInfo(totalPoints);
        if (di && typeof di.division === 'string') division = di.division;
        else if (di && typeof di.fullLabel === 'string') {
          const m = di.fullLabel.match(/(I{1,3})$/);
          if (m) division = m[1];
        }
      }
    } catch (_) {}
    const cls = _hrClassFromStat(currentClass);
    // Longest active-vow streak
    let streak = 0;
    try {
      if (Array.isArray(habits)) {
        habits.forEach(function (h) {
          if (!h || h.archived) return;
          const s = (typeof getStreak === 'function') ? (getStreak(h.id) || 0) : 0;
          if (s > streak) streak = s;
        });
      }
    } catch (_) {}
    // Bosses slain — sum of kill_count
    let bosses = 0;
    try {
      const bossState = JSON.parse(localStorage.getItem('hb_bosses') || '{}');
      Object.keys(bossState).forEach(function (k) {
        const r = bossState[k];
        if (r && typeof r.kill_count === 'number') bosses += r.kill_count;
      });
    } catch (_) {}
    try { bosses += _coopKillTotal(); } catch (_) {}   // W546 — include co-op kills
    // Souls balance — read via the canonical accessor. hb_souls is
    // stored as JSON.stringify({ balance: N, ... }), NOT a flat int;
    // an earlier W187 revision used parseInt() and rendered 0 for
    // every hunter regardless of real balance. getSoulsBalance()
    // returns _souls.balance (loadSouls()-initialized) and is the
    // same function the in-app souls tile reads.
    let souls = 0;
    try {
      if (typeof getSoulsBalance === 'function') {
        souls = getSoulsBalance() || 0;
      } else {
        const sObj = JSON.parse(localStorage.getItem('hb_souls') || '{}');
        souls = (sObj && typeof sObj.balance === 'number') ? sObj.balance : 0;
      }
    } catch (_) {}
    // W316 — Ascent floor + band name, reusing the Status climb-strip's
    // source of truth (getAscentState + _ascentBandFor) so the card can't
    // drift. Omitted (floor 0) when the hunter hasn't started the Ascent.
    let ascFloor = 0, ascBand = '';
    try {
      const stx = (typeof getAscentState === 'function') ? getAscentState() : null;
      if (stx) {
        const cur = Math.max(1, Math.min(100, stx.currentFloor || 1));
        const cleared = stx.highestCleared || 0;
        const started = cleared >= 1 || (stx.currentFloor || 0) > 1;
        if (cleared >= 100) { ascFloor = 100; ascBand = 'The Tower is Yours'; }
        else if (started) { ascFloor = cur; ascBand = (typeof _ascentBandFor === 'function') ? (_ascentBandFor(cur).name || '') : ''; }
      }
    } catch (_) { ascFloor = 0; ascBand = ''; }
    // W323 — weekly Step Crown count (cached from the last-week recap fetch).
    let stepCrowns = 0;
    try { stepCrowns = parseInt(localStorage.getItem('hb_step_crowns') || '0', 10) || 0; } catch (_) { stepCrowns = 0; }
    return {
      floor:       ascFloor,
      bandName:    ascBand,
      crowns:      stepCrowns,
      alias:       alias,
      className:   cls.name,
      classStat:   currentClass || 'SAGE',
      classColor:  cls.color,
      // W675 — the shareable Hunter Report must show the EQUIPPED SKIN, not the
      // plain class default. getAvatarSrc() is the same skin-aware resolver the
      // home portrait / profile card / arena use (equipped hb_avatar_skin, else the
      // class default), so the card now matches what the player sees on Status.
      // The class palette still drives the ring COLOR (classColor above).
      classAsset:  (function () { try { return getAvatarSrc() || cls.asset; } catch (_) { return cls.asset; } })(),
      rank:        rankId,
      division:    division,
      totalXP:     totalPoints || 0,
      streak:      streak,
      bosses:      bosses,
      souls:       souls,
      quote:       _hrPickQuote(),
    };
  }

  function _hrFmtNum(n) {
    return (typeof n === 'number' ? n : 0).toLocaleString('en-US');
  }

  // Await every font weight the canvas uses. document.fonts.load
  // returns a Promise that resolves once the face is ready. Without
  // this, the first render after cold launch falls back to system
  // serif and the layout shifts.
  async function _hrLoadFonts() {
    if (!document.fonts || typeof document.fonts.load !== 'function') return;
    const specs = [
      '700 92px "Cinzel"',
      '600 26px "Cinzel"',
      '800 74px "JetBrains Mono"',
      '800 22px "JetBrains Mono"',
      '700 24px "JetBrains Mono"',
      '500 italic 44px "Cormorant Garamond"',
    ];
    try {
      await Promise.all(specs.map(function (s) {
        return document.fonts.load(s).catch(function () {});
      }));
    } catch (_) {}
  }

  function _hrWithAlpha(rgba, alpha) {
    // Replaces the alpha component of an rgba(r,g,b,a) string.
    return rgba.replace(/[\d.]+\)$/, alpha + ')');
  }

  // Draw a rounded rectangle path. Older iOS WebKit doesn't support
  // ctx.roundRect, so we hand-draw it.
  function _hrRoundRectPath(ctx, x, y, w, h, r) {
    if (typeof r === 'number') r = { tl: r, tr: r, br: r, bl: r };
    ctx.beginPath();
    ctx.moveTo(x + r.tl, y);
    ctx.lineTo(x + w - r.tr, y);
    ctx.quadraticCurveTo(x + w, y, x + w, y + r.tr);
    ctx.lineTo(x + w, y + h - r.br);
    ctx.quadraticCurveTo(x + w, y + h, x + w - r.br, y + h);
    ctx.lineTo(x + r.bl, y + h);
    ctx.quadraticCurveTo(x, y + h, x, y + h - r.bl);
    ctx.lineTo(x, y + r.tl);
    ctx.quadraticCurveTo(x, y, x + r.tl, y);
    ctx.closePath();
  }

  // Main renderer. Returns the canvas after every load completes.
  async function _hrRenderCanvas(data, opts) {
    opts = opts || {};
    const W = 1200, H = 1500;
    const DPR = 2;
    await _hrLoadFonts();
    // Preload class avatar (fall back to avatar-base.png on miss)
    const avatarImg = new Image();
    avatarImg.crossOrigin = 'anonymous';
    let avatarLoaded = false;
    try {
      avatarImg.src = data.classAsset || 'avatar-base.png';
      await avatarImg.decode();
      avatarLoaded = true;
    } catch (_) {
      try {
        avatarImg.src = 'avatar-base.png';
        await avatarImg.decode();
        avatarLoaded = true;
      } catch (_) { avatarLoaded = false; }
    }

    // W716 — a MEMBER's equipped card background paints behind the Hunter Report, so the
    // status symbol travels onto the shareable card (matches the board rows + profile
    // card). Gated on membership + an equipped catalog bg; non-members / "Basic" keep the
    // plain navy. Awaited like the avatar so the draw below has the bitmap ready.
    let hrBgImg = null;
    try {
      const _cbMember = (typeof _founderOwned === 'function') && _founderOwned();
      const _cbId = (_cbMember && typeof _cardBgEquipped === 'function') ? _cardBgEquipped() : '';
      const _cbArt = (_cbId && typeof _cardBgArt === 'function') ? _cardBgArt(_cbId) : '';
      if (_cbArt) {
        const _bi = new Image();
        _bi.crossOrigin = 'anonymous';
        _bi.src = _cbArt;
        await _bi.decode();
        if (_bi.width) hrBgImg = _bi;
      }
    } catch (_) { hrBgImg = null; }

    const canvas = opts.canvas || document.createElement('canvas');
    canvas.width  = W * DPR;
    canvas.height = H * DPR;
    canvas.style.width  = W + 'px';
    canvas.style.height = H + 'px';
    const ctx = canvas.getContext('2d');
    ctx.setTransform(DPR, 0, 0, DPR, 0, 0);

    const r = _hrPaletteForRank(data.rank);

    // ── 1. Opaque base + layered background gradients ──
    // Solid navy first → guarantees opacity (Apple icon 90717 lesson).
    ctx.fillStyle = '#08081a';
    ctx.fillRect(0, 0, W, H);

    const baseG = ctx.createLinearGradient(0, 0, 0, H);
    baseG.addColorStop(0,    '#0a0a1f');
    baseG.addColorStop(0.55, '#050513');
    baseG.addColorStop(1,    '#030309');
    ctx.fillStyle = baseG;
    ctx.fillRect(0, 0, W, H);

    // W716 — member card background: cover-fit + dimmed, then a readability scrim
    // (lighter up top where the art shows, solid at the bottom under the stats/tagline).
    // The rank/violet/vignette glows below still layer over it. Drawn here so it sits
    // behind the frame, avatar arch and all text.
    if (hrBgImg && hrBgImg.width) {
      const _iw = hrBgImg.width, _ih = hrBgImg.height;
      const _scale = Math.max(W / _iw, H / _ih);
      const _dw = _iw * _scale, _dh = _ih * _scale;
      ctx.save();
      ctx.globalAlpha = 0.55;
      ctx.drawImage(hrBgImg, (W - _dw) / 2, (H - _dh) / 2, _dw, _dh);
      ctx.restore();
      const _scrim = ctx.createLinearGradient(0, 0, 0, H);
      _scrim.addColorStop(0,    'rgba(5,5,16,0.52)');
      _scrim.addColorStop(0.40, 'rgba(5,5,16,0.40)');
      _scrim.addColorStop(0.62, 'rgba(5,5,16,0.74)');
      _scrim.addColorStop(1,    'rgba(3,3,9,0.95)');
      ctx.fillStyle = _scrim;
      ctx.fillRect(0, 0, W, H);
    }

    // Top rank-color glow
    const topGlow = ctx.createRadialGradient(W/2, -120, 0, W/2, -120, W * 0.85);
    topGlow.addColorStop(0,    _hrWithAlpha(r.glow, 0.20));
    topGlow.addColorStop(0.46, 'rgba(0,0,0,0)');
    ctx.fillStyle = topGlow;
    ctx.fillRect(0, 0, W, H);

    // Violet system accent
    const violetGlow = ctx.createRadialGradient(W/2, H * 0.08, 0, W/2, H * 0.08, W * 0.7);
    violetGlow.addColorStop(0,    'rgba(167,139,250,0.10)');
    violetGlow.addColorStop(0.5,  'rgba(0,0,0,0)');
    ctx.fillStyle = violetGlow;
    ctx.fillRect(0, 0, W, H);

    // Bottom vignette
    const botFade = ctx.createRadialGradient(W/2, H * 1.2, 0, W/2, H * 1.2, W);
    botFade.addColorStop(0,   '#02020a');
    botFade.addColorStop(0.6, 'rgba(0,0,0,0)');
    ctx.fillStyle = botFade;
    ctx.fillRect(0, 0, W, H);

    // Inset vignette shadow (simulates the design's boxShadow inset 220 0.8)
    const vignette = ctx.createRadialGradient(W/2, H/2, W * 0.35, W/2, H/2, W * 0.78);
    vignette.addColorStop(0, 'rgba(0,0,0,0)');
    vignette.addColorStop(1, 'rgba(0,0,0,0.55)');
    ctx.fillStyle = vignette;
    ctx.fillRect(0, 0, W, H);

    // ── 2. Double gold frame ──
    const frameInset = 40;
    const frameRadius = 18;
    // Outer thick gold border
    _hrRoundRectPath(ctx, frameInset, frameInset, W - frameInset * 2, H - frameInset * 2, frameRadius);
    const frameG = ctx.createLinearGradient(0, frameInset, 0, H - frameInset);
    frameG.addColorStop(0,    '#f7c558');
    frameG.addColorStop(0.5,  '#f5b842');
    frameG.addColorStop(1,    '#c08418');
    ctx.lineWidth = 2;
    ctx.strokeStyle = frameG;
    ctx.shadowColor = 'rgba(245,184,66,0.16)';
    ctx.shadowBlur = 40;
    ctx.stroke();
    ctx.shadowBlur = 0;
    // Inner hairline
    const innerInset = 52;
    _hrRoundRectPath(ctx, innerInset, innerInset, W - innerInset * 2, H - innerInset * 2, 12);
    ctx.lineWidth = 1;
    ctx.strokeStyle = 'rgba(245,184,66,0.28)';
    ctx.stroke();

    // ── 3. Corner sigils (small geometric brackets, 4 corners) ──
    function drawCornerSigil(cx, cy, rotation) {
      ctx.save();
      ctx.translate(cx, cy);
      ctx.rotate(rotation);
      ctx.strokeStyle = '#f5b842';
      ctx.lineWidth = 1.6;
      ctx.globalAlpha = 0.7;
      ctx.beginPath();
      ctx.moveTo(2, 14); ctx.lineTo(2, 2); ctx.lineTo(14, 2);
      ctx.stroke();
      ctx.lineWidth = 1.1;
      ctx.globalAlpha = 0.5;
      ctx.beginPath();
      ctx.moveTo(7, 7); ctx.lineTo(13, 13);
      ctx.stroke();
      ctx.globalAlpha = 0.8;
      ctx.fillStyle = '#f5b842';
      ctx.beginPath();
      ctx.arc(5.5, 5.5, 1.6, 0, Math.PI * 2);
      ctx.fill();
      ctx.restore();
    }
    const sigInset = 48;
    drawCornerSigil(sigInset, sigInset, 0);
    drawCornerSigil(W - sigInset, sigInset, Math.PI / 2);
    drawCornerSigil(W - sigInset, H - sigInset, Math.PI);
    drawCornerSigil(sigInset, H - sigInset, Math.PI * 1.5);

    // ── 4. Header: small diamond + AWAKENED · HUNTER REPORT + rule ──
    const headerY = 120;
    // Diamond glyph
    ctx.save();
    ctx.translate(W / 2, headerY);
    ctx.strokeStyle = '#f5b842';
    ctx.lineWidth = 1.5;
    ctx.globalAlpha = 0.85;
    ctx.beginPath();
    ctx.moveTo(0, -16); ctx.lineTo(16, 0); ctx.lineTo(0, 16); ctx.lineTo(-16, 0); ctx.closePath();
    ctx.stroke();
    ctx.fillStyle = '#f5b842';
    ctx.beginPath();
    ctx.moveTo(0, -8); ctx.lineTo(8, 0); ctx.lineTo(0, 8); ctx.lineTo(-8, 0); ctx.closePath();
    ctx.fill();
    ctx.restore();
    // Title text
    ctx.font = '700 24px "JetBrains Mono", "SF Mono", ui-monospace, monospace';
    ctx.textAlign = 'center';
    ctx.textBaseline = 'alphabetic';
    ctx.fillStyle = '#f5b842';
    ctx.shadowColor = 'rgba(245,184,66,0.30)';
    ctx.shadowBlur = 18;
    // letterSpacing not natively supported in canvas — emulate with text positioning
    const headerText = 'AWAKENED · HUNTER REPORT';
    _hrDrawSpacedText(ctx, headerText, W / 2, headerY + 56, 9);
    ctx.shadowBlur = 0;
    // Gold rule under header
    _hrDrawGoldRule(ctx, W / 2, headerY + 90, 560, true);

    // ── 5. PORTRAIT MEDALLION ──
    // Arched frame: rounded-rect with rounded TOP corners (radius ~ width/2)
    // and shallow BOTTOM corners (12% of size). Inside: tier accent ring,
    // navy well, class avatar PNG, floor glow.
    const medSize = 300;
    const medH = medSize * 1.14;
    const medCx = W / 2;
    const medTop = headerY + 130;
    const medLeft = medCx - medSize / 2;
    const arcRad = medSize * 0.46;
    const botRad = medSize * 0.12;

    // Glow halo behind
    const haloG = ctx.createRadialGradient(medCx, medTop + medH * 0.46, 0, medCx, medTop + medH * 0.46, medSize * 0.85);
    haloG.addColorStop(0,    r.glow);
    haloG.addColorStop(0.38, _hrWithAlpha(r.glow, 0.10));
    haloG.addColorStop(0.70, 'rgba(0,0,0,0)');
    ctx.fillStyle = haloG;
    ctx.fillRect(medLeft - medSize * 0.2, medTop - medSize * 0.2, medSize * 1.4, medH + medSize * 0.4);

    // Outer gold border (the medallion frame)
    const goldPad = Math.max(3, medSize * 0.012);
    _hrRoundRectPath(ctx, medLeft, medTop, medSize, medH, { tl: arcRad, tr: arcRad, br: botRad, bl: botRad });
    const medFrameG = ctx.createLinearGradient(0, medTop, 0, medTop + medH);
    medFrameG.addColorStop(0,    '#f7c558');
    medFrameG.addColorStop(0.48, '#f5b842');
    medFrameG.addColorStop(1,    '#c08418');
    ctx.fillStyle = medFrameG;
    ctx.shadowColor = r.glow;
    ctx.shadowBlur = medSize * 0.12;
    ctx.fill();
    ctx.shadowBlur = 0;

    // Tier accent ring (inset 1 padding inside gold)
    const ringInset = goldPad;
    const ringSize = medSize - ringInset * 2;
    const ringH = medH - ringInset * 2;
    const ringArc = arcRad - 4;
    const ringBot = medSize * 0.10;
    _hrRoundRectPath(ctx, medLeft + ringInset, medTop + ringInset, ringSize, ringH,
      { tl: ringArc, tr: ringArc, br: ringBot, bl: ringBot });
    const tierG = ctx.createLinearGradient(0, medTop + ringInset, 0, medTop + ringInset + ringH);
    tierG.addColorStop(0, r.hue + 'cc');
    tierG.addColorStop(1, r.hue + '33');
    ctx.fillStyle = tierG;
    ctx.fill();

    // Navy well (inside the tier ring)
    const wellInset = ringInset + Math.max(1, medSize * 0.006);
    const wellSize = medSize - wellInset * 2;
    const wellH = medH - wellInset * 2;
    const wellArc = arcRad - 6;
    const wellBot = medSize * 0.085;
    ctx.save();
    _hrRoundRectPath(ctx, medLeft + wellInset, medTop + wellInset, wellSize, wellH,
      { tl: wellArc, tr: wellArc, br: wellBot, bl: wellBot });
    ctx.clip();
    // Navy fill with rank-tint at top
    const wellTop = ctx.createRadialGradient(medCx, medTop + medH * 0.18, 0, medCx, medTop + medH * 0.18, medSize * 0.7);
    wellTop.addColorStop(0,    r.hue + '26');
    wellTop.addColorStop(0.52, 'rgba(0,0,0,0)');
    const wellBase = ctx.createRadialGradient(medCx, medTop + medH * 0.30, 0, medCx, medTop + medH * 0.30, medSize * 0.85);
    wellBase.addColorStop(0,    '#1a1640');
    wellBase.addColorStop(0.72, '#08081a');
    ctx.fillStyle = wellBase;
    ctx.fillRect(medLeft + wellInset, medTop + wellInset, wellSize, wellH);
    ctx.fillStyle = wellTop;
    ctx.fillRect(medLeft + wellInset, medTop + wellInset, wellSize, wellH);

    // Floor glow inside well
    const floorY = medTop + medH - medSize * 0.10;
    const floorG = ctx.createRadialGradient(medCx, floorY, 0, medCx, floorY, medSize * 0.35);
    floorG.addColorStop(0,   r.glow);
    floorG.addColorStop(0.7, 'rgba(0,0,0,0)');
    ctx.fillStyle = floorG;
    ctx.fillRect(medLeft + wellInset, medTop + wellInset, wellSize, wellH);

    // Class avatar PNG
    if (avatarLoaded) {
      const avH = wellH * 0.85;
      const avW = avH * (avatarImg.width / avatarImg.height || 1);
      const avX = medCx - avW / 2;
      const avY = medTop + medH - avH - medSize * 0.05;
      ctx.drawImage(avatarImg, avX, avY, avW, avH);
    } else {
      // Fallback: a class-color rim-lit oblong silhouette
      ctx.fillStyle = '#08081a';
      _hrRoundRectPath(ctx, medCx - medSize * 0.18, medTop + medH * 0.18, medSize * 0.36, medH * 0.66, 24);
      ctx.fill();
    }
    ctx.restore();

    // ── 6. RANK CREST pendant (overlaps medallion bottom) ──
    const crestSize = 112;
    const crestCx = W / 2;
    const crestCy = medTop + medH + 40;
    _hrDrawRankCrest(ctx, crestCx, crestCy, crestSize, data.rank, data.division, r);

    // ── 7. ALIAS (Cinzel 84) ──
    const aliasY = crestCy + crestSize / 2 + 72;
    ctx.font = '700 84px "Cinzel", Georgia, serif';
    ctx.fillStyle = '#f5f3fb';
    ctx.shadowColor = 'rgba(245,184,66,0.28)';
    ctx.shadowBlur = 34;
    ctx.textAlign = 'center';
    ctx.fillText((data.alias || 'HUNTER').toUpperCase(), W / 2, aliasY);
    ctx.shadowBlur = 0;

    // ── 8. Meta line: CLASS · RANK X · DIV Y ──
    const metaY = aliasY + 56;
    ctx.font = '700 22px "JetBrains Mono", monospace';
    const metaClass = (data.className || 'AWAKENED').toUpperCase();
    const metaRank  = 'RANK ' + (data.rank || 'E');
    const metaDiv   = 'DIV ' + (data.division || 'I');
    // Measure each segment to space evenly
    const segs = [
      { text: metaClass, color: data.classColor || '#a78bfa' },
      { text: '·',       color: '#5c5c78' },
      { text: metaRank,  color: r.letter },
      { text: '·',       color: '#5c5c78' },
      { text: metaDiv,   color: '#9090a8' },
    ];
    // W323 — weekly Step Crown flex on the identity line (if the hunter has
    // ever topped a weekly steps board). Omitted cleanly when crowns = 0.
    if (data.crowns && data.crowns > 0) {
      segs.push({ text: '·', color: '#5c5c78' });
      segs.push({ text: data.crowns + '\u00d7 CHAMPION', color: '#f5b842' });
    }
    const gap = 16;
    let metaTotal = 0;
    segs.forEach(function (s, i) {
      metaTotal += ctx.measureText(s.text).width;
      if (i < segs.length - 1) metaTotal += gap;
    });
    let metaX = W / 2 - metaTotal / 2;
    segs.forEach(function (s, i) {
      ctx.fillStyle = s.color;
      ctx.textAlign = 'left';
      _hrDrawSpacedText(ctx, s.text, metaX, metaY, 2);
      metaX += ctx.measureText(s.text).width + 2 * Math.max(0, s.text.length - 1) + gap;
    });
    ctx.textAlign = 'center';

    // ── 8b. ASCENT FLOOR headline (the spine of the app — headline weight) ──
    let floorBlockH = 0;
    if (data.floor && data.floor > 0) {
      const fY = metaY + 56;
      const fTxt = 'FLOOR ' + data.floor + (data.bandName ? ' · ' + String(data.bandName).toUpperCase() : '');
      ctx.textAlign = 'center';
      ctx.fillStyle = '#f5b842';
      ctx.shadowColor = 'rgba(245,184,66,0.30)';
      ctx.shadowBlur = 18;
      let fSize = 32;
      ctx.font = '800 ' + fSize + 'px "JetBrains Mono", monospace';
      while (ctx.measureText(fTxt).width + 3 * Math.max(0, fTxt.length - 1) > 900 && fSize > 22) {
        fSize -= 2; ctx.font = '800 ' + fSize + 'px "JetBrains Mono", monospace';
      }
      _hrDrawSpacedText(ctx, fTxt, W / 2, fY, 3);
      ctx.shadowBlur = 0;
      const fW = ctx.measureText(fTxt).width + 3 * Math.max(0, fTxt.length - 1);
      ctx.fillStyle = 'rgba(245,184,66,0.5)';
      ctx.fillRect(W / 2 - fW / 2 - 40, fY - 11, 26, 2);
      ctx.fillRect(W / 2 + fW / 2 + 14, fY - 11, 26, 2);
      floorBlockH = 70;
    }

    // ── 9. STAT GRID 2×2 ──
    const gridY = metaY + 60 + floorBlockH;
    const gridW = 880;
    const gridH = 240;
    const gridX = W / 2 - gridW / 2;
    // Hairline cross
    const hairV = ctx.createLinearGradient(W / 2, gridY, W / 2, gridY + gridH);
    hairV.addColorStop(0,   'rgba(245,184,66,0)');
    hairV.addColorStop(0.5, 'rgba(245,184,66,0.22)');
    hairV.addColorStop(1,   'rgba(245,184,66,0)');
    ctx.fillStyle = hairV;
    ctx.fillRect(W / 2 - 0.5, gridY + gridH * 0.08, 1, gridH * 0.84);
    const hairH = ctx.createLinearGradient(gridX, gridY + gridH / 2, gridX + gridW, gridY + gridH / 2);
    hairH.addColorStop(0,   'rgba(245,184,66,0)');
    hairH.addColorStop(0.5, 'rgba(245,184,66,0.22)');
    hairH.addColorStop(1,   'rgba(245,184,66,0)');
    ctx.fillStyle = hairH;
    ctx.fillRect(gridX + gridW * 0.06, gridY + gridH / 2 - 0.5, gridW * 0.88, 1);
    // 4 cells
    _hrDrawStatCell(ctx, gridX + gridW / 4, gridY + gridH / 4, 'TOTAL XP', _hrFmtNum(data.totalXP), true);
    _hrDrawStatCell(ctx, gridX + gridW * 3 / 4, gridY + gridH / 4, 'DAY STREAK', _hrFmtNum(data.streak), false, 'flame');
    _hrDrawStatCell(ctx, gridX + gridW / 4, gridY + gridH * 3 / 4, 'BOSSES SLAIN', _hrFmtNum(data.bosses), false);
    _hrDrawStatCell(ctx, gridX + gridW * 3 / 4, gridY + gridH * 3 / 4, 'SOULS', _hrFmtNum(data.souls), false, 'soul');

    // ── 10. QUOTE + attribution ──
    const quoteY = gridY + gridH + 96;
    // Flanking rules
    ctx.fillStyle = 'rgba(245,184,66,0.5)';
    ctx.fillRect(W / 2 - 280 - 40, quoteY - 18, 40, 1);
    ctx.fillRect(W / 2 + 280, quoteY - 18, 40, 1);
    ctx.font = '500 italic 44px "Cormorant Garamond", Georgia, serif';
    ctx.fillStyle = '#c8c6d8';
    ctx.textAlign = 'center';
    ctx.fillText('"' + data.quote + '"', W / 2, quoteY);
    ctx.font = '700 14px "JetBrains Mono", monospace';
    ctx.fillStyle = '#5c5c78';
    _hrDrawSpacedText(ctx, 'THE FIRST AWAKENED', W / 2, quoteY + 36, 4);

    // ── 11. FOOTER: gold rule + tagline + brand mark ──
    const footerBaseY = H - 110;
    _hrDrawGoldRule(ctx, W / 2, footerBaseY - 40, 620, false);
    ctx.font = '800 22px "JetBrains Mono", monospace';
    ctx.fillStyle = '#f5b842';
    ctx.shadowColor = 'rgba(245,184,66,0.16)';
    ctx.shadowBlur = 16;
    _hrDrawSpacedText(ctx, 'TURN YOUR HABITS INTO AN RPG', W / 2, footerBaseY, 5);
    ctx.shadowBlur = 0;
    // Brand row: small spark + AWAKENED: HABIT RPG · awakened.app
    ctx.font = '600 17px "JetBrains Mono", monospace';
    ctx.fillStyle = '#9090a8';
    const brandA = 'AWAKENED: HABIT RPG';
    const brandB = 'awakened.app';
    const sepW = 12, sparkW = 30;
    const brandAW = ctx.measureText(brandA).width;
    const brandBW = ctx.measureText(brandB).width;
    const brandTotal = sparkW + 10 + brandAW + sepW + brandBW;
    let brandX = W / 2 - brandTotal / 2;
    // Small spark mark (4-point star) glyph
    ctx.save();
    ctx.translate(brandX + 10, footerBaseY + 32);
    ctx.fillStyle = '#f5b842';
    ctx.globalAlpha = 0.85;
    ctx.beginPath();
    ctx.moveTo(0, -8); ctx.lineTo(2.5, -2.5); ctx.lineTo(8, 0); ctx.lineTo(2.5, 2.5);
    ctx.lineTo(0, 8); ctx.lineTo(-2.5, 2.5); ctx.lineTo(-8, 0); ctx.lineTo(-2.5, -2.5);
    ctx.closePath();
    ctx.fill();
    ctx.restore();
    brandX += sparkW + 10;
    ctx.fillStyle = '#9090a8';
    ctx.textAlign = 'left';
    ctx.fillText(brandA, brandX, footerBaseY + 36);
    brandX += brandAW + sepW / 2;
    ctx.fillStyle = '#5c5c78';
    ctx.fillRect(brandX - 2, footerBaseY + 30, 4, 4);
    brandX += sepW / 2;
    ctx.fillText(brandB, brandX, footerBaseY + 36);
    ctx.textAlign = 'center';

    return canvas;
  }

  // Spaced text — emulates CSS letter-spacing by drawing chars in
  // sequence with a fixed gap. Native canvas has no letter-spacing.
  function _hrDrawSpacedText(ctx, str, x, y, spacing) {
    const w = ctx.measureText(str).width + spacing * Math.max(0, str.length - 1);
    let cur = x - w / 2;
    const prevAlign = ctx.textAlign;
    ctx.textAlign = 'left';
    for (let i = 0; i < str.length; i++) {
      const ch = str[i];
      ctx.fillText(ch, cur, y);
      cur += ctx.measureText(ch).width + spacing;
    }
    ctx.textAlign = prevAlign;
  }

  // Gold horizontal rule with optional center diamond glyph.
  function _hrDrawGoldRule(ctx, cx, cy, width, glyph) {
    const halfW = width / 2;
    const gapW = glyph ? 18 : 0;
    const lineW = halfW - gapW - (glyph ? 8 : 0);
    // Left gradient
    const leftG = ctx.createLinearGradient(cx - halfW, cy, cx - halfW + lineW, cy);
    leftG.addColorStop(0, 'rgba(245,184,66,0)');
    leftG.addColorStop(1, 'rgba(245,184,66,0.6)');
    ctx.fillStyle = leftG;
    ctx.fillRect(cx - halfW, cy - 0.5, lineW, 1);
    // Right gradient
    const rightG = ctx.createLinearGradient(cx + halfW - lineW, cy, cx + halfW, cy);
    rightG.addColorStop(0, 'rgba(245,184,66,0.6)');
    rightG.addColorStop(1, 'rgba(245,184,66,0)');
    ctx.fillStyle = rightG;
    ctx.fillRect(cx + halfW - lineW, cy - 0.5, lineW, 1);
    // Glyph
    if (glyph) {
      ctx.save();
      ctx.translate(cx, cy);
      ctx.strokeStyle = '#f5b842';
      ctx.lineWidth = 1;
      ctx.globalAlpha = 0.8;
      ctx.beginPath();
      ctx.moveTo(0, -8); ctx.lineTo(8, 0); ctx.lineTo(0, 8); ctx.lineTo(-8, 0); ctx.closePath();
      ctx.stroke();
      ctx.fillStyle = '#f5b842';
      ctx.globalAlpha = 1;
      ctx.beginPath();
      ctx.moveTo(0, -4); ctx.lineTo(4, 0); ctx.lineTo(0, 4); ctx.lineTo(-4, 0); ctx.closePath();
      ctx.fill();
      ctx.restore();
    }
  }

  // Rank crest pendant — gilded round disc with tier letter + division.
  function _hrDrawRankCrest(ctx, cx, cy, size, rankId, division, r) {
    const isPlus = rankId === 'S+';
    const radius = size / 2;
    // Drop shadow under the crest
    ctx.save();
    ctx.shadowColor = 'rgba(0,0,0,0.5)';
    ctx.shadowBlur = size * 0.1;
    ctx.shadowOffsetY = size * 0.04;
    // Outer gold ring — approximate conic with linear gradient
    const goldRingG = ctx.createLinearGradient(cx - radius, cy - radius, cx + radius, cy + radius);
    goldRingG.addColorStop(0,    '#c08418');
    goldRingG.addColorStop(0.25, '#f7c558');
    goldRingG.addColorStop(0.5,  '#f5b842');
    goldRingG.addColorStop(0.72, '#c08418');
    goldRingG.addColorStop(1,    '#f7c558');
    ctx.fillStyle = goldRingG;
    ctx.beginPath();
    ctx.arc(cx, cy, radius, 0, Math.PI * 2);
    ctx.fill();
    ctx.restore();
    // Halo glow around ring
    ctx.save();
    ctx.shadowColor = 'rgba(245,184,66,0.45)';
    ctx.shadowBlur = size * 0.18;
    ctx.strokeStyle = 'rgba(245,184,66,0.0)';
    ctx.lineWidth = 0;
    ctx.beginPath();
    ctx.arc(cx, cy, radius, 0, Math.PI * 2);
    ctx.stroke();
    ctx.restore();
    // Inner well — rank-color tinted navy
    const innerR = radius - size * 0.05;
    const wellG = ctx.createRadialGradient(cx, cy - size * 0.18, 0, cx, cy - size * 0.18, innerR);
    wellG.addColorStop(0,    r.hue + '33');
    wellG.addColorStop(0.66, '#08081a');
    ctx.fillStyle = wellG;
    ctx.beginPath();
    ctx.arc(cx, cy, innerR, 0, Math.PI * 2);
    ctx.fill();
    // Tier color outline (inside the gold)
    ctx.strokeStyle = r.hue;
    ctx.lineWidth = Math.max(1, size * 0.012);
    ctx.beginPath();
    ctx.arc(cx, cy, innerR, 0, Math.PI * 2);
    ctx.stroke();
    // Rank letter
    const letterSize = size * (isPlus ? 0.40 : 0.50);
    ctx.font = '700 ' + letterSize + 'px "Cinzel", Georgia, serif';
    ctx.fillStyle = r.letter;
    ctx.textAlign = 'center';
    ctx.textBaseline = 'middle';
    ctx.shadowColor = r.glow;
    ctx.shadowBlur = size * 0.14;
    if (isPlus) {
      // Draw 'S' + smaller '+' superscript
      const sw = ctx.measureText('S').width;
      ctx.fillText('S', cx - size * 0.04, cy - size * 0.04);
      ctx.font = '700 ' + (size * 0.26) + 'px "Cinzel", Georgia, serif';
      ctx.fillText('+', cx + sw / 2 - size * 0.02, cy - size * 0.12);
    } else {
      ctx.fillText(rankId, cx, cy - size * 0.04);
    }
    ctx.shadowBlur = 0;
    // Division label
    ctx.font = '800 ' + (size * 0.12) + 'px "JetBrains Mono", monospace';
    ctx.fillStyle = '#f5b842';
    ctx.globalAlpha = 0.92;
    ctx.fillText(division || 'I', cx, cy + size * 0.24);
    ctx.globalAlpha = 1;
    ctx.textBaseline = 'alphabetic';
  }

  // Stat cell — label above, value below, optional glyph beside.
  function _hrDrawStatCell(ctx, cx, cy, label, value, highlight, glyphKind) {
    // Label
    ctx.font = '700 19px "JetBrains Mono", monospace';
    ctx.fillStyle = highlight ? '#f5b842' : '#9090a8';
    ctx.textAlign = 'center';
    _hrDrawSpacedText(ctx, label, cx, cy - 30, 3);
    // Value
    ctx.font = '800 66px "JetBrains Mono", monospace';
    ctx.fillStyle = highlight ? '#f5b842' : '#f5f3fb';
    if (highlight) {
      ctx.shadowColor = 'rgba(245,184,66,0.45)';
      ctx.shadowBlur = 26;
    }
    // If a glyph is present, offset the value left a bit
    const valueW = ctx.measureText(value).width;
    const glyphSize = 40;
    const glyphGap = 12;
    if (glyphKind) {
      ctx.textAlign = 'left';
      const totalW = valueW + glyphGap + glyphSize;
      const startX = cx - totalW / 2;
      ctx.fillText(value, startX, cy + 30);
      // Glyph
      ctx.shadowBlur = 0;
      const gx = startX + valueW + glyphGap + glyphSize / 2;
      const gy = cy + 12;
      if (glyphKind === 'flame') {
        ctx.fillStyle = '#f5b842';
        ctx.beginPath();
        ctx.moveTo(gx, gy - glyphSize * 0.5);
        ctx.bezierCurveTo(gx - glyphSize * 0.18, gy - glyphSize * 0.18, gx - glyphSize * 0.36, gy + glyphSize * 0.1, gx - glyphSize * 0.36, gy + glyphSize * 0.27);
        ctx.bezierCurveTo(gx - glyphSize * 0.36, gy + glyphSize * 0.45, gx - glyphSize * 0.12, gy + glyphSize * 0.5, gx, gy + glyphSize * 0.5);
        ctx.bezierCurveTo(gx + glyphSize * 0.12, gy + glyphSize * 0.5, gx + glyphSize * 0.36, gy + glyphSize * 0.45, gx + glyphSize * 0.36, gy + glyphSize * 0.27);
        ctx.bezierCurveTo(gx + glyphSize * 0.36, gy + glyphSize * 0.1, gx + glyphSize * 0.18, gy - glyphSize * 0.18, gx, gy - glyphSize * 0.5);
        ctx.closePath();
        ctx.fill();
      } else if (glyphKind === 'soul') {
        // Concentric gold rings (soul mark)
        ctx.strokeStyle = '#f5b842';
        ctx.lineWidth = 1.6;
        ctx.beginPath();
        ctx.arc(gx, gy, glyphSize * 0.32, 0, Math.PI * 2);
        ctx.stroke();
        ctx.fillStyle = '#f5b842';
        ctx.beginPath();
        ctx.arc(gx, gy, glyphSize * 0.12, 0, Math.PI * 2);
        ctx.fill();
      }
      ctx.textAlign = 'center';
    } else {
      ctx.fillText(value, cx, cy + 30);
    }
    ctx.shadowBlur = 0;
  }

  // Canvas → File for native share.
  async function _hrCanvasToFile(canvas) {
    return new Promise(function (resolve, reject) {
      try {
        canvas.toBlob(function (blob) {
          if (!blob) { reject(new Error('toBlob returned null')); return; }
          try {
            resolve(new File([blob], 'awakened-hunter-report.png', { type: 'image/png' }));
          } catch (e) { reject(e); }
        }, 'image/png', 0.92);
      } catch (e) { reject(e); }
    });
  }

  // Share orchestrator. Mirrors the (since-removed) shareOriginStory 3-tier fallback
  // (line ~25980): files → text+url → clipboard.
  // W317 — identity-aware share copy for the Hunter Report card (the generic
  // line felt unfinished). References class/rank + Ascent floor + bosses,
  // matching the casual voice of the boss-kill cards.
  function _hrShareCopy(data) {
    data = data || {};
    const cls = (data.className && data.className !== 'Awakened') ? data.className : 'hunter';
    const rank = data.rank || 'E';
    const bits = [];
    if (data.floor && data.floor > 0) bits.push('Floor ' + data.floor + ' of the Ascent');
    if (data.bosses && data.bosses > 0) bits.push(_hrFmtNum(data.bosses) + ' bosses down');
    const tail = bits.length ? (' — ' + bits.join(', ')) : '';
    return "I'm a Rank " + rank + ' ' + cls + ' in Awakened' + tail + '. Turn your habits into an RPG.';
  }

  async function _hrShareReport(data, canvas) {
    const APP_URL = 'https://apps.apple.com/app/awakened-habit-rpg/id6764727990';
    const TEXT = _hrShareCopy(data);
    try {
      const file = await _hrCanvasToFile(canvas);
      if (navigator.canShare && navigator.canShare({ files: [file] }) && navigator.share) {
        try {
          await navigator.share({ files: [file], text: TEXT, url: APP_URL });
          return { ok: true, mode: 'file' };
        } catch (_) { /* user cancelled or share failed → fall through */ }
      }
    } catch (_) { /* canvas/file failed → fall through */ }
    // Text + URL fallback
    if (navigator.share) {
      try {
        await navigator.share({ text: TEXT, url: APP_URL });
        return { ok: true, mode: 'text' };
      } catch (_) {}
    }
    // Clipboard final fallback
    try {
      await navigator.clipboard.writeText(TEXT + '\n' + APP_URL);
      if (typeof showHabitToast === 'function') showHabitToast('Link copied');
      return { ok: true, mode: 'clipboard' };
    } catch (_) {
      if (typeof showHabitToast === 'function') showHabitToast('Sharing not supported on this device');
      return { ok: false, mode: 'none' };
    }
  }

  // ── Modal lifecycle ───────────────────────────────────────────
  let _hrOnDismiss = null;
  let _hrCurrentData = null;
  let _hrCurrentCanvas = null;

  function _hrKeydown(e) {
    if (e.key === 'Escape') closeHunterReportPreview();
  }

  async function openHunterReportPreview(data, onDismiss) {
    const overlay = document.getElementById('hr-overlay');
    if (!overlay) {
      if (typeof onDismiss === 'function') onDismiss();
      return;
    }
    _hrOnDismiss = (typeof onDismiss === 'function') ? onDismiss : null;
    _hrCurrentData = data;
    const canvas = document.getElementById('hr-canvas');
    const loading = document.getElementById('hr-canvas-loading');
    if (loading) loading.classList.remove('is-done');
    overlay.classList.remove('hidden');
    overlay.setAttribute('aria-hidden', 'false');
    document.addEventListener('keydown', _hrKeydown, true);
    // Render the card into the canvas (async — fonts + avatar)
    try {
      _hrCurrentCanvas = await _hrRenderCanvas(data, { canvas: canvas });
      if (loading) loading.classList.add('is-done');
    } catch (_) {
      if (loading) loading.classList.add('is-done');
      // Canvas failed; SHARE button will still try the text fallback
      _hrCurrentCanvas = canvas;
    }
  }

  function closeHunterReportPreview() {
    const overlay = document.getElementById('hr-overlay');
    if (overlay) {
      overlay.classList.add('hidden');
      overlay.setAttribute('aria-hidden', 'true');
    }
    document.removeEventListener('keydown', _hrKeydown, true);
    const cb = _hrOnDismiss;
    _hrOnDismiss = null;
    _hrCurrentData = null;
    _hrCurrentCanvas = null;
    if (typeof cb === 'function') {
      try { cb(); } catch (_) {}
    }
  }

  // Wire CTAs once on DOMContentLoaded init.
  function _hrSetupOnce() {
    const overlay = document.getElementById('hr-overlay');
    if (!overlay || overlay.getAttribute('data-wired') === '1') return;
    overlay.setAttribute('data-wired', '1');
    const closeBtn = document.getElementById('hr-close-btn');
    const dismissBtn = document.getElementById('hr-dismiss-btn');
    const shareBtn = document.getElementById('hr-share-btn');
    if (closeBtn) closeBtn.addEventListener('click', closeHunterReportPreview);
    if (dismissBtn) dismissBtn.addEventListener('click', closeHunterReportPreview);
    if (shareBtn) shareBtn.addEventListener('click', async function () {
      if (!_hrCurrentData || !_hrCurrentCanvas) return;
      shareBtn.disabled = true;
      try {
        await _hrShareReport(_hrCurrentData, _hrCurrentCanvas);
      } catch (_) {}
      shareBtn.disabled = false;
      // Don't auto-close — let the user explicitly dismiss after seeing
      // the OS share sheet confirm. This respects the W179 stance:
      // dismissal is gated on the explicit CTA, never accidental.
    });
    // Backdrop tap = no-op (W179 lesson). Intentional.
    overlay.addEventListener('click', function (e) {
      if (e.target === overlay) {
        e.stopPropagation();
        // No-op: backdrop tap does NOT dismiss. Only buttons do.
      }
    });
  }

  try {
    window.__openHunterReportPreview  = openHunterReportPreview;
    window.__closeHunterReportPreview = closeHunterReportPreview;
    window.__hrRenderCanvas           = _hrRenderCanvas;
    window.__hrCollectData            = _hrCollectData;
  } catch (_) {}
  document.addEventListener('DOMContentLoaded', _hrSetupOnce);

  // ════════════════════════════════════════════════════════════════
  // W312 — Boss-Kill Share Card (the growth engine).
  //
  // A self-contained, PRESENTATION-ONLY module: it renders a 1080×1920
  // dark/gold card of a defeated boss to a canvas (reusing the Hunter-
  // Report _hr* draw helpers + the real boss art), then one-taps it
  // into the native share sheet via the SAME proven Web-Share path the
  // Hunter Report card uses (navigator.share with files → text+url →
  // clipboard). On iOS Capacitor this surfaces the system share sheet
  // (Stories / iMessage / X / Save Image).
  //
  // Triggered from: the Ascent result + summit screens, the boss-
  // defeated full-screen (which is also the persistent RE-TRIGGER
  // surface), and the Kill Log rows.
  //
  // Touches NO engine / economy / commit path / selfTest. If image
  // generation fails it falls back to a text share and never blocks
  // the originating screen. Ships ENABLED.
  // ════════════════════════════════════════════════════════════════

  function _bksShareIconSvg() {
    return '<svg class="bks-share-ico" viewBox="0 0 24 24" width="15" height="15" aria-hidden="true" focusable="false">' +
      '<path d="M12 3l4 4m-4-4L8 7m4-4v12" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"/>' +
      '<path d="M5 13v6a1 1 0 0 0 1 1h12a1 1 0 0 0 1-1v-6" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"/>' +
      '</svg>';
  }

  function _bksRankPalette(rankId) {
    return _hrPaletteForRank((rankId || 'E').toUpperCase());
  }

  // The canonical summit / F100 hero art — the same First Awakened
  // portrait the summit ending screen (_arRenderSummit) shows, so the
  // share card matches the moment the player just saw. Already in
  // sw.js PRECACHE_ASSETS (offline-safe); the renderer cover-fits it
  // into the boss-art plate exactly like dungeon art and falls back to
  // the rank crest if it ever fails to load.
  const _BKS_SUMMIT_ART = 'assets/coach/first-awakened-idle.png';

  // Normalize a kill into the card's data shape from any trigger.
  //   opts.source : 'dungeon' | 'ascent'
  //   dungeon : opts.bossId (+ optional opts.cfg)
  //   ascent  : opts.floor, opts.bossName, opts.bossId (optional)
  function _bksCollectData(opts) {
    opts = opts || {};
    let alias = 'Hunter';
    try {
      const u = (typeof Auth !== 'undefined' && Auth && Auth.getCurrentUser) ? Auth.getCurrentUser() : null;
      if (u && u.alias) alias = u.alias;
    } catch (_) {}

    if (opts.source === 'ascent') {
      const cap = (typeof ASCENT_FLOORS === 'number') ? ASCENT_FLOORS : 100;
      const floor = opts.floor || 0;
      const summit = floor >= cap;
      const name = opts.bossName || ('Floor ' + floor);
      return {
        source: 'ascent',
        floor: floor,
        alias: alias,
        bossName: name,
        artPath: summit ? _BKS_SUMMIT_ART : (opts.bossId ? getBossArtPath(opts.bossId) : null),
        rankId: 'S',
        context: summit ? 'THE ASCENT · THE SUMMIT' : ('THE ASCENT · FLOOR ' + floor),
        feat: summit ? ('Floor ' + cap + ' — the First Awakened, bested') : ('Floor ' + floor + ' cleared, the climb continues'),
        killNo: 0,
        stamp: summit ? 'SUMMIT' : 'CLEARED',
      };
    }

    // dungeon (solo OR co-op)
    const id  = opts.bossId;
    // W697 — a co-op boss (the Grinning God et al.) has its full config on COOP_BOSSES,
    // NOT the lean BOSSES drop-stub (which has no killCondShort → empty feat line). Prefer
    // COOP_BOSSES when the BOSSES entry is a coop-only stub or absent.
    const _bStub = (typeof BOSSES === 'object' && BOSSES && id) ? BOSSES[id] : null;
    const _coopCfg = (typeof COOP_BOSSES === 'object' && COOP_BOSSES && id) ? COOP_BOSSES[id] : null;
    const isCoop = !!_coopCfg && (!_bStub || _bStub.coopOnly);
    const cfg = opts.cfg || (isCoop ? _coopCfg : _bStub) || _coopCfg || _bStub || {};
    let killNo = 0;
    try {
      if (isCoop) {
        // W697 — co-op kills live in hb_coop_kills, not the solo loadBosses() store.
        const c = (_loadCoopKills()[id] || {}).count;
        if (typeof c === 'number') killNo = c;
      } else {
        const all = (typeof loadBosses === 'function') ? (loadBosses() || {}) : {};
        const s = all[id];
        if (s && typeof s.kill_count === 'number') killNo = s.kill_count;
      }
    } catch (_) {}
    const rank = (cfg.rank || 'E').toUpperCase();
    return {
      source: 'dungeon',
      alias: alias,
      bossName: cfg.name || 'The Boss',
      artPath: id ? getBossArtPath(id) : null,
      rankId: rank,
      context: rank + '-RANK · ' + (isCoop ? 'CO-OP HUNT' : 'DUNGEON HUNT'),
      feat: cfg.killCondShort || '',
      killNo: killNo,
      stamp: 'DEFEATED',
    };
  }

  // Center-aligned word-wrap, capped at maxLines (ellipsis on overflow).
  function _bksDrawWrapped(ctx, text, cx, y, maxW, lineH, maxLines) {
    const words = String(text || '').split(/\s+/).filter(Boolean);
    const lines = [];
    let cur = '';
    for (let i = 0; i < words.length; i++) {
      const test = cur ? (cur + ' ' + words[i]) : words[i];
      if (ctx.measureText(test).width > maxW && cur) { lines.push(cur); cur = words[i]; }
      else cur = test;
    }
    if (cur) lines.push(cur);
    const cap = maxLines || 2;
    const shown = lines.slice(0, cap);
    if (lines.length > cap && shown.length) {
      shown[shown.length - 1] = shown[shown.length - 1].replace(/[\s.,;:]*\S*$/, '') + '…';
    }
    for (let i = 0; i < shown.length; i++) ctx.fillText(shown[i], cx, y + i * lineH);
    return shown.length;
  }

  // Render the boss-kill card to a 1080×1920 canvas. Fail-soft on art.
  async function _bksRenderCanvas(d, canvasEl) {
    const W = 1080, H = 1920, DPR = 2;
    try { await _hrLoadFonts(); } catch (_) {}

    // Preload boss art (cover-fit). Missing art → rank-crest fallback.
    let art = null;
    if (d.artPath) {
      try {
        const img = new Image();
        img.crossOrigin = 'anonymous';
        img.src = d.artPath;
        await img.decode();
        art = img;
      } catch (_) { art = null; }
    }

    const canvas = canvasEl || document.createElement('canvas');
    canvas.width = W * DPR;
    canvas.height = H * DPR;
    canvas.style.width = W + 'px';
    canvas.style.height = H + 'px';
    const ctx = canvas.getContext('2d');
    ctx.setTransform(DPR, 0, 0, DPR, 0, 0);

    const r = _bksRankPalette(d.rankId);

    // ── 1. Opaque base + layered glows ──
    ctx.fillStyle = '#08081a';
    ctx.fillRect(0, 0, W, H);
    const baseG = ctx.createLinearGradient(0, 0, 0, H);
    baseG.addColorStop(0, '#0a0a1f');
    baseG.addColorStop(0.55, '#050513');
    baseG.addColorStop(1, '#030309');
    ctx.fillStyle = baseG;
    ctx.fillRect(0, 0, W, H);
    const topGlow = ctx.createRadialGradient(W / 2, -160, 0, W / 2, -160, W * 1.05);
    topGlow.addColorStop(0, _hrWithAlpha(r.glow, 0.22));
    topGlow.addColorStop(0.5, 'rgba(0,0,0,0)');
    ctx.fillStyle = topGlow;
    ctx.fillRect(0, 0, W, H);
    const violet = ctx.createRadialGradient(W / 2, H * 0.1, 0, W / 2, H * 0.1, W * 0.85);
    violet.addColorStop(0, 'rgba(167,139,250,0.10)');
    violet.addColorStop(0.5, 'rgba(0,0,0,0)');
    ctx.fillStyle = violet;
    ctx.fillRect(0, 0, W, H);
    const vign = ctx.createRadialGradient(W / 2, H / 2, W * 0.4, W / 2, H / 2, H * 0.62);
    vign.addColorStop(0, 'rgba(0,0,0,0)');
    vign.addColorStop(1, 'rgba(0,0,0,0.6)');
    ctx.fillStyle = vign;
    ctx.fillRect(0, 0, W, H);

    // ── 2. Double gold frame ──
    const fi = 44, fr = 24;
    const fg = ctx.createLinearGradient(0, fi, 0, H - fi);
    fg.addColorStop(0, '#f7c558');
    fg.addColorStop(0.5, '#c08418');
    fg.addColorStop(1, '#f5b842');
    ctx.strokeStyle = fg;
    ctx.lineWidth = 3;
    _hrRoundRectPath(ctx, fi, fi, W - fi * 2, H - fi * 2, fr);
    ctx.stroke();
    ctx.strokeStyle = 'rgba(245,184,66,0.32)';
    ctx.lineWidth = 1;
    _hrRoundRectPath(ctx, fi + 10, fi + 10, W - (fi + 10) * 2, H - (fi + 10) * 2, fr - 6);
    ctx.stroke();

    // ── 3. Header ──
    ctx.textAlign = 'center';
    ctx.textBaseline = 'alphabetic';
    ctx.font = '600 30px "Cinzel", Georgia, serif';
    ctx.fillStyle = '#f5b842';
    _hrDrawSpacedText(ctx, 'AWAKENED', W / 2, 152, 10);
    _hrDrawGoldRule(ctx, W / 2, 190, 480, true);
    ctx.font = '800 22px "JetBrains Mono", monospace';
    ctx.fillStyle = '#9090a8';
    _hrDrawSpacedText(ctx, d.context, W / 2, 244, 4);

    // ── 4. Boss-art plate ──
    const plateX = 110, plateY = 300, plateW = W - plateX * 2, plateH = 760;
    const pg = ctx.createRadialGradient(W / 2, plateY + plateH * 0.42, 0, W / 2, plateY + plateH * 0.42, plateW * 0.72);
    pg.addColorStop(0, _hrWithAlpha(r.glow, 0.32));
    pg.addColorStop(0.7, 'rgba(0,0,0,0)');
    ctx.fillStyle = pg;
    ctx.fillRect(plateX - 60, plateY - 60, plateW + 120, plateH + 120);

    ctx.save();
    _hrRoundRectPath(ctx, plateX, plateY, plateW, plateH, 26);
    const plg = ctx.createLinearGradient(0, plateY, 0, plateY + plateH);
    plg.addColorStop(0, '#0e0e24');
    plg.addColorStop(1, '#070713');
    ctx.fillStyle = plg;
    ctx.fill();
    ctx.clip();
    if (art) {
      const iw = art.naturalWidth || art.width || plateW;
      const ih = art.naturalHeight || art.height || plateH;
      const scale = Math.max(plateW / iw, plateH / ih);
      const dw = iw * scale, dh = ih * scale;
      // PvP cards use the player's AVATAR (a portrait, head at the top); center-cropping a tall
      // portrait cuts the head off (same as the W430 VS-avatar fix). Anchor its top to the plate
      // top so the head survives. Boss cards use ~square art -> keep them centered.
      const dy = (d.source === 'pvp') ? plateY : (plateY + plateH / 2 - dh / 2);
      ctx.drawImage(art, W / 2 - dw / 2, dy, dw, dh);
      const fade = ctx.createLinearGradient(0, plateY + plateH - 260, 0, plateY + plateH);
      fade.addColorStop(0, 'rgba(7,7,19,0)');
      fade.addColorStop(1, 'rgba(7,7,19,0.92)');
      ctx.fillStyle = fade;
      ctx.fillRect(plateX, plateY + plateH - 260, plateW, 260);
    } else {
      _hrDrawRankCrest(ctx, W / 2, plateY + plateH / 2, 320, d.rankId, '', r);
    }
    ctx.restore();
    ctx.strokeStyle = 'rgba(245,184,66,0.55)';
    ctx.lineWidth = 2;
    _hrRoundRectPath(ctx, plateX, plateY, plateW, plateH, 26);
    ctx.stroke();

    // ── 5. Stamp + boss name + feat ──
    ctx.textAlign = 'center';
    ctx.textBaseline = 'alphabetic';
    const stampY = plateY + plateH + 96;
    ctx.font = '700 76px "Cinzel", Georgia, serif';
    const stampGold = (d.source === 'ascent');
    ctx.fillStyle = stampGold ? '#f5b842' : '#ef5350';
    ctx.shadowColor = stampGold ? 'rgba(245,184,66,0.5)' : 'rgba(239,83,80,0.5)';
    ctx.shadowBlur = 24;
    _hrDrawSpacedText(ctx, d.stamp, W / 2, stampY, 14);
    ctx.shadowBlur = 0;

    const maxTextW = W - 200;
    let nameSize = 64;
    ctx.fillStyle = '#f4f4fa';
    ctx.font = '700 ' + nameSize + 'px "Cinzel", Georgia, serif';
    while (ctx.measureText(d.bossName).width > maxTextW && nameSize > 34) {
      nameSize -= 3;
      ctx.font = '700 ' + nameSize + 'px "Cinzel", Georgia, serif';
    }
    ctx.fillText(d.bossName, W / 2, stampY + 98);

    let featLines = 0;
    if (d.feat) {
      ctx.font = '500 italic 40px "Cormorant Garamond", Georgia, serif';
      ctx.fillStyle = r.letter;
      featLines = _bksDrawWrapped(ctx, d.feat, W / 2, stampY + 168, maxTextW, 50, 2);
    }

    // ── 6. Kill-count chip (repeat kills = social proof) ──
    if (d.killNo && d.killNo > 1) {
      const chipTxt = 'KILL #' + _hrFmtNum(d.killNo);
      ctx.font = '800 24px "JetBrains Mono", monospace';
      const cw = ctx.measureText(chipTxt).width + 64;
      const cx0 = W / 2 - cw / 2;
      const cy0 = stampY + 168 + (featLines > 0 ? featLines * 50 : 0) + 26;
      ctx.fillStyle = 'rgba(245,184,66,0.10)';
      _hrRoundRectPath(ctx, cx0, cy0, cw, 58, 29);
      ctx.fill();
      ctx.strokeStyle = 'rgba(245,184,66,0.5)';
      ctx.lineWidth = 1.5;
      _hrRoundRectPath(ctx, cx0, cy0, cw, 58, 29);
      ctx.stroke();
      ctx.fillStyle = '#f5b842';
      ctx.textBaseline = 'middle';
      _hrDrawSpacedText(ctx, chipTxt, W / 2, cy0 + 30, 2);
      ctx.textBaseline = 'alphabetic';
    }

    // ── 7. Footer: alias + wordmark ──
    _hrDrawGoldRule(ctx, W / 2, H - 240, 440, true);
    ctx.font = '500 italic 48px "Cormorant Garamond", Georgia, serif';
    ctx.fillStyle = '#cfcfe0';
    ctx.fillText('— ' + d.alias, W / 2, H - 174);
    ctx.font = '700 20px "JetBrains Mono", monospace';
    ctx.fillStyle = '#7a7a96';
    _hrDrawSpacedText(ctx, 'AWAKENED · TURN YOUR HABITS INTO AN RPG', W / 2, H - 116, 3);

    return canvas;
  }

  function _bksCanvasToFile(canvas, name) {
    return new Promise(function (resolve, reject) {
      try {
        canvas.toBlob(function (blob) {
          if (!blob) { reject(new Error('toBlob returned null')); return; }
          try { resolve(new File([blob], name || 'awakened-kill.png', { type: 'image/png' })); }
          catch (e) { reject(e); }
        }, 'image/png', 0.92);
      } catch (e) { reject(e); }
    });
  }

  function _bksShareCopy(d) {
    if (d && d.source === 'ascent') {
      const cap = (typeof ASCENT_FLOORS === 'number') ? ASCENT_FLOORS : 100;
      if (/SUMMIT/.test(d.context || '')) {
        return 'Just hit Floor ' + cap + ' in Awakened and beat the First Awakened. ' +
          'The whole game runs on real-world habits — turn yours into an RPG.';
      }
      return 'Just cleared Floor ' + (d.floor || 0) + ' of the Ascent in Awakened — ' +
        'powered by real-world movement. Turn your habits into an RPG.';
    }
    if (d && d.bossName) {
      return 'Just beat ' + d.bossName + ' in Awakened — you only kill bosses here ' +
        'by hitting real workout and step goals. It turns your habits into an RPG.';
    }
    return 'Turn your habits into an RPG. — Awakened';
  }

  // Share an already-rendered canvas. Mirrors _hrShareReport's 3-tier
  // fallback but with boss-named copy (the viral hook).
  async function _bksShareCanvas(canvas, d) {
    const APP_URL = 'https://apps.apple.com/app/awakened-habit-rpg/id6764727990';
    const TEXT = _bksShareCopy(d);
    try {
      const file = await _bksCanvasToFile(canvas, 'awakened-kill.png');
      if (navigator.canShare && navigator.canShare({ files: [file] }) && navigator.share) {
        try {
          await navigator.share({ files: [file], text: TEXT, url: APP_URL });
          return { ok: true, mode: 'file' };
        } catch (_) { /* cancelled / unsupported → fall through */ }
      }
    } catch (_) { /* canvas/file failed → fall through */ }
    return _bksShareText(d);
  }

  // Text-only fallback (also the path used when the canvas never renders).
  async function _bksShareText(d) {
    const APP_URL = 'https://apps.apple.com/app/awakened-habit-rpg/id6764727990';
    const TEXT = _bksShareCopy(d);
    if (navigator.share) {
      try { await navigator.share({ text: TEXT, url: APP_URL }); return { ok: true, mode: 'text' }; }
      catch (_) {}
    }
    try {
      await navigator.clipboard.writeText(TEXT + '\n' + APP_URL);
      if (typeof showHabitToast === 'function') showHabitToast('Copied — paste to share');
      return { ok: true, mode: 'clipboard' };
    } catch (_) {
      if (typeof showHabitToast === 'function') showHabitToast('Sharing not supported on this device');
      return { ok: false, mode: 'none' };
    }
  }

  // ── Public entries (never throw to the caller) ──
  async function shareBossKill(bossId) {
    let d = null;
    try {
      d = _bksCollectData({ source: 'dungeon', bossId: bossId });
      const canvas = await _bksRenderCanvas(d, null);
      await _bksShareCanvas(canvas, d);
    } catch (_) {
      try { await _bksShareText(d || { source: 'dungeon' }); } catch (_) {}
    }
  }

  async function shareAscentClear(floor, bossName, bossId) {
    let d = null;
    try {
      d = _bksCollectData({ source: 'ascent', floor: floor, bossName: bossName, bossId: bossId });
      const canvas = await _bksRenderCanvas(d, null);
      await _bksShareCanvas(canvas, d);
    } catch (_) {
      try { await _bksShareText(d || { source: 'ascent' }); } catch (_) {}
    }
  }

  // W411 (S2) — share a ranked PvP win. Reuses the boss-kill card pipeline; the numbers
  // (tier, ELO + delta, opponent) come from the server-broadcast result state.
  function _pvpTierRank(tier) {
    switch (tier) {
      case 'Awakened': case 'Master': case 'Diamond': return 'S';
      case 'Platinum': return 'A';
      case 'Gold': return 'B';
      case 'Silver': return 'C';
      default: return 'D';
    }
  }
  async function sharePvpResult() {
    let d = null;
    try {
      let alias = 'Hunter';
      try { const u = (typeof Auth !== 'undefined' && Auth.getCurrentUser) ? Auth.getCurrentUser() : null; if (u && u.alias) alias = u.alias; } catch (_) {}
      const opp = (_pvpView && _pvpView.opp) || {};
      const oppName = opp.alias || opp.name || (_pvpOpponentMeta && _pvpOpponentMeta.alias) || 'a rival';
      const er = _pvpEndRating;
      const tierName = (er && er.tier) || (_pvpRating && _pvpRating.tier) || 'Silver';
      const elo = er ? er.elo : (_pvpRating && _pvpRating.elo);
      const delta = (er && typeof er.delta === 'number') ? er.delta : null;
      let avatar = ''; try { avatar = getAvatarSrc(); } catch (_) {}
      const feat = 'Bested ' + oppName + (delta != null && delta > 0 ? ' · +' + delta + ' ELO' : '') + (elo != null ? ' → ' + _pvpNum(elo) : '');
      d = {
        source: 'pvp', alias: alias, bossName: 'vs ' + oppName,
        artPath: avatar || null, rankId: _pvpTierRank(tierName),
        context: 'RANKED DUEL · ' + String(tierName).toUpperCase(),
        feat: feat, killNo: 0, stamp: 'VICTORY',
      };
      const canvas = await _bksRenderCanvas(d, null);
      await _bksShareCanvas(canvas, d);
    } catch (_) {
      try { await _bksShareText(d || { source: 'pvp' }); } catch (_) {}
    }
  }
  try { window.__sharePvpResult = sharePvpResult; } catch (_) {}

  // One delegated, capture-phase listener for every [data-bkshare]
  // trigger (result/summit buttons, the defeated CTA, kill-log rows).
  function _bksSetupOnce() {
    if (document.__bksWired) return;
    document.__bksWired = true;
    document.addEventListener('click', function (e) {
      const btn = e.target && e.target.closest ? e.target.closest('[data-bkshare]') : null;
      if (!btn) return;
      e.preventDefault();
      e.stopPropagation();
      if (btn.__bksBusy) return;
      btn.__bksBusy = true;
      const release = function () { btn.__bksBusy = false; };
      const src = btn.getAttribute('data-bk-source') || 'dungeon';
      if (src === 'profile') {
        // W315 — open the existing Hunter Report card on demand (reuses the
        // #hr-overlay modal + 3-tier share). Bypasses the one-shot rank-up gate.
        let pdata = null;
        try { pdata = (typeof _hrCollectData === 'function') ? _hrCollectData({}) : null; } catch (_) {}
        if (pdata && typeof openHunterReportPreview === 'function') {
          Promise.resolve(openHunterReportPreview(pdata, null)).then(release, release);
        } else { release(); }
      } else if (src === 'ascent') {
        const floor = parseInt(btn.getAttribute('data-floor') || '0', 10) || 0;
        const name = btn.getAttribute('data-boss-name') || '';
        const id = btn.getAttribute('data-boss-id') || '';
        Promise.resolve(shareAscentClear(floor, name, id)).then(release, release);
      } else if (src === 'pvp') {
        Promise.resolve(sharePvpResult()).then(release, release);
      } else {
        const id = btn.getAttribute('data-boss-id') || '';
        Promise.resolve(shareBossKill(id)).then(release, release);
      }
    }, true);
  }
  if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', _bksSetupOnce);
  else _bksSetupOnce();

  try {
    window.__shareBossKill = shareBossKill;
    window.__shareAscentClear = shareAscentClear;
    window.__bksRenderCanvas = _bksRenderCanvas;
    window.__bksCollectData = _bksCollectData;
  } catch (_) {}


  // v3 Phase 1z.282D — Rank-up congratulations orchestrator.
  // Called from drainLevelUpQueue() when a 'fa_rankup' item is
  // dispatched (queued by toggleHabit immediately after the
  // existing 'rank' celebration item). Idempotent via the
  // hb_fa_rankup_seen_v1 set — already-seen ranks fall through
  // and release the queue without gifting souls or showing the
  // modal. The seen-set is marked EAGERLY (before the modal opens)
  // so a user who backgrounds mid-modal doesn't get re-gifted on
  // next launch.
  //
  // Souls reward: engageCostSouls(rankId) — gives exactly one
  // engagement at the new tier. S+ is treated as narrative-only
  // (no boss exists at that tier; the peer-status moment is the
  // reward).
  //
  // Ledger source label: fa_rankup_<rank>  (S+ → fa_rankup_splus).
  // Classified by _classifySoulsEvent to render as
  // "First Awakened's gift" with the rank in the detail row.
  function showFirstAwakenedRankUp(rankId) {
    const releaseQueue = function () {
      try {
        levelUpActive = false;
        drainLevelUpQueue();
      } catch (_) {}
    };
    if (!rankId || !FA_RANKUP_BEATS[rankId]) {
      releaseQueue();
      return;
    }
    if (_faRankupSeen(rankId)) {
      releaseQueue();
      return;
    }
    // Mark seen BEFORE any side effects so backgrounding mid-modal
    // (or a JS exception during earnSouls / modal mount) cannot
    // result in a re-gift on next launch. The user has "earned" the
    // moment by crossing the rank threshold.
    _faMarkRankupSeen(rankId);

    // Credit souls. Skip S+ entirely (no engage cost; narrative
    // moment is the reward).
    const isSPlus = (rankId === 'S+');
    if (!isSPlus) {
      try {
        const cost = (typeof engageCostSouls === 'function')
          ? engageCostSouls(rankId)
          : 0;
        if (cost > 0 && typeof earnSouls === 'function') {
          earnSouls(cost, _faRankupSource(rankId));
        }
      } catch (_) { /* ledger failure must not block the modal */ }
    }

    // CTA: declarative for D-S, single-glyph dismiss for S+.
    // The S+ moment is not an "I accept" — there is nothing to
    // accept. The user simply stands where The First Awakened
    // once stood.
    const cta = isSPlus ? 'CONTINUE' : 'I ACCEPT';

    _faRunCoachmark({
      context: 'rankup_' + String(rankId).toLowerCase(),
      beats: FA_RANKUP_BEATS[rankId],
      cta: cta,
      // No storageKey — we handle persistence via the seen-set above.
      onDismiss: releaseQueue,
    });
  }

  try {
    window.__showQuestsCoachmark      = showQuestsCoachmark;
    window.__showFirstVowCoachmark    = showFirstVowCoachmark;
    window.__showWelcomeBackCoachmark = showWelcomeBackCoachmark;
    window.__showFirstAwakenedRankUp  = showFirstAwakenedRankUp;
  } catch (_) {}

  // ════════════════════════════════════════════════════════════════════
  // v3 Phase 1z.283 — Manage Vows (soft archive sheet)
  // ════════════════════════════════════════════════════════════════════
  // Bottom sheet listing every active vow with an inline release
  // (Option A confirm pattern). Soft archive only — habit.archived=true
  // hides the habit from active reads (count, daily render, stat-feed)
  // while preserving streak, completions, and earned XP.
  //
  // Two entry points:
  //   1. System Full modal "Manage Vows" CTA (replaces switchTab no-op)
  //   2. Settings → "Manage Vows" row (below Field Manual)
  //
  // Voice: The First Awakened narrates the sheet header (one idle-pose
  // line) and the per-row confirm (one nodding-pose line). Not a modal —
  // just inline presence at two moments. Direct port of the ClaudeDesign
  // fa-managevows.jsx spec.
  // ════════════════════════════════════════════════════════════════════

  const MV_SORTS = [
    { id: 'az',     label: 'A–Z' },
    { id: 'streak', label: 'Streak' },
    { id: 'quiet',  label: 'Quietest' },
  ];
  let _mvSort = 'az';
  let _mvConfirmId = null;   // habit id currently in confirm state
  let _mvReleasingId = null; // habit id currently animating out
  let _mvRoomMadeTimer = null;

  // "Last done" formatter — Today / Yesterday / N days ago.
  function _mvLastDone(habitId) {
    try {
      const dates = Object.keys(completions || {});
      if (!dates.length) return 'Not yet kept';
      // Find most recent date this habit was checked.
      const todayKey = getCurrentDayName ? (typeof today !== 'undefined' ? today : null) : null;
      let mostRecent = null;
      dates.sort();
      for (let i = dates.length - 1; i >= 0; i--) {
        const d = dates[i];
        if (Array.isArray(completions[d]) && completions[d].indexOf(habitId) !== -1) {
          mostRecent = d;
          break;
        }
      }
      if (!mostRecent) return 'Not yet kept';
      if (todayKey && mostRecent === todayKey) return 'Today';
      // Compute days delta via date math.
      const mr = Date.parse(mostRecent + 'T12:00:00Z');
      const tk = (typeof today !== 'undefined' && today)
        ? Date.parse(today + 'T12:00:00Z')
        : Date.now();
      if (isNaN(mr) || isNaN(tk)) return 'Recently';
      const delta = Math.round((tk - mr) / 86400000);
      if (delta <= 0) return 'Today';
      if (delta === 1) return 'Yesterday';
      return delta + ' days ago';
    } catch (_) { return ''; }
  }

  // "Days since last done" numeric — for the Quietest sort.
  function _mvDaysSince(habitId) {
    try {
      const dates = Object.keys(completions || {});
      if (!dates.length) return 9999;
      dates.sort();
      let mostRecent = null;
      for (let i = dates.length - 1; i >= 0; i--) {
        const d = dates[i];
        if (Array.isArray(completions[d]) && completions[d].indexOf(habitId) !== -1) {
          mostRecent = d;
          break;
        }
      }
      if (!mostRecent) return 9999;
      const mr = Date.parse(mostRecent + 'T12:00:00Z');
      const tk = (typeof today !== 'undefined' && today)
        ? Date.parse(today + 'T12:00:00Z')
        : Date.now();
      return Math.max(0, Math.round((tk - mr) / 86400000));
    } catch (_) { return 9999; }
  }

  function _mvSortedActive() {
    const arr = (Array.isArray(habits) ? habits : []).filter(_isActiveHabit);
    const copy = arr.slice();
    if (_mvSort === 'az') {
      copy.sort(function (a, b) {
        return String(a.name || '').localeCompare(String(b.name || ''));
      });
    } else if (_mvSort === 'streak') {
      copy.sort(function (a, b) {
        const sa = (typeof getStreak === 'function') ? (getStreak(a.id) || 0) : 0;
        const sb = (typeof getStreak === 'function') ? (getStreak(b.id) || 0) : 0;
        return sb - sa;
      });
    } else if (_mvSort === 'quiet') {
      copy.sort(function (a, b) {
        const da = _mvDaysSince(a.id);
        const db = _mvDaysSince(b.id);
        if (db !== da) return db - da;
        const sa = (typeof getStreak === 'function') ? (getStreak(a.id) || 0) : 0;
        const sb = (typeof getStreak === 'function') ? (getStreak(b.id) || 0) : 0;
        return sa - sb;
      });
    }
    return copy;
  }

  function _mvStatColor(statId) {
    const map = {
      STR: '#ef4444', VIT: '#34d399', INT: '#3b82f6',
      FOCUS: '#eab308', WILL: '#f97316', WLT: '#f5b842',
    };
    return map[statId] || '#a78bfa';
  }

  function _mvRowHtml(h) {
    const id = String(h.id || '');
    const streak = (typeof getStreak === 'function') ? (getStreak(id) || 0) : 0;
    const statId = String(h.primaryStat || '').toUpperCase();
    const sc = _mvStatColor(statId);
    // Icon: reuse the existing app icon system (PNG/emoji per habit).
    const iconHtml = (typeof habitIconHtml === 'function')
      ? habitIconHtml(h, { size: 22 })
      : (h.emoji ? esc(h.emoji) : '');
    const last = _mvLastDone(id);
    const isConfirm = (_mvConfirmId === id);
    const isReleasing = (_mvReleasingId === id);

    const releaseLabel = (String(h.name || '').length > 14) ? 'Release vow' : ('Release ' + esc(h.name || ''));

    return (
      '<div class="mv-row' +
        (isConfirm ? ' mv-row--confirming' : '') +
        (isReleasing ? ' mv-row--releasing' : '') +
        '" data-mv-row-id="' + esc(id) + '">' +
        '<div class="mv-row-head">' +
          '<div class="mv-row-icon" aria-hidden="true">' + iconHtml + '</div>' +
          '<div class="mv-row-main">' +
            '<div class="mv-row-name">' + esc(h.name || '') + '</div>' +
            '<div class="mv-row-sub">' +
              '<span class="mv-row-statpill" style="color:' + sc + ';background:' + sc + '1f;">' + esc(statId || '') + '</span>' +
              '<span class="mv-row-streak">' +
                '<svg class="mv-row-streak-diamond" width="7" height="7" viewBox="0 0 10 10" aria-hidden="true">' +
                  '<path d="M5 0.5 L9.5 5 L5 9.5 L0.5 5 Z" fill="none" stroke="#f5b842" stroke-width="1"/>' +
                  '<path d="M5 3 L7 5 L5 7 L3 5 Z" fill="#f5b842"/>' +
                '</svg>' +
                '<span>' + streak + '-day</span>' +
              '</span>' +
              '<span class="mv-row-sep"></span>' +
              '<span class="mv-row-last">' + esc(last) + '</span>' +
            '</div>' +
          '</div>' +
          (isConfirm ? '' :
            '<button class="mv-row-releasebtn" type="button" data-mv-release="' + esc(id) + '"' +
              ' aria-label="Release ' + esc(h.name || '') + '">Release</button>'
          ) +
        '</div>' +
        '<div class="mv-row-confirm">' +
          '<div class="mv-row-confirm-inner">' +
            '<div class="mv-row-confirm-portrait">' +
              '<img src="assets/coach/first-awakened-nodding.png" alt="The First Awakened" class="mv-row-confirm-img">' +
            '</div>' +
            '<p class="mv-row-confirm-line" aria-live="polite">' +
              'Release ' + esc(h.name || '') + '? The discipline is already recorded. The vow only leaves the active list.' +
            '</p>' +
          '</div>' +
          '<div class="mv-row-confirm-actions">' +
            '<button class="mv-row-cancelbtn" type="button" data-mv-cancel="' + esc(id) + '" aria-label="Cancel release">Cancel</button>' +
            '<button class="mv-row-confirmbtn" type="button" data-mv-confirm="' + esc(id) + '"' +
              ' aria-label="Confirm release of ' + esc(h.name || '') + '">' + esc(releaseLabel) + '</button>' +
          '</div>' +
        '</div>' +
      '</div>'
    );
  }

  function _mvCounterHtml(roomMade) {
    const count = getActiveHabitCount();
    const over = count > MAX_ACTIVE_HABITS;
    const colorClass = roomMade ? 'mv-counter--room' : (over ? 'mv-counter--over' : 'mv-counter--ok');
    let badge = '';
    if (roomMade) {
      badge = '<span class="mv-counter-badge mv-counter-badge--room">' +
                '<svg width="7" height="7" viewBox="0 0 10 10" aria-hidden="true">' +
                  '<path d="M5 0.5 L9.5 5 L5 9.5 L0.5 5 Z" fill="none" stroke="#34d399" stroke-width="1"/>' +
                  '<path d="M5 3 L7 5 L5 7 L3 5 Z" fill="#34d399"/>' +
                '</svg> ROOM MADE</span>';
    } else if (over) {
      badge = '<span class="mv-counter-badge mv-counter-badge--over">OVER CAP</span>';
    }
    return (
      '<span class="mv-counter ' + colorClass + '">' +
        '<span class="mv-counter-num">' + count + ' / ' + MAX_ACTIVE_HABITS + '</span>' +
        '<span class="mv-counter-lbl">ACTIVE VOWS</span>' +
      '</span>' +
      badge
    );
  }

  function _mvSortPillsHtml() {
    return MV_SORTS.map(function (s) {
      const active = (s.id === _mvSort);
      return '<button class="mv-sortpill' + (active ? ' is-active' : '') + '" type="button"' +
        ' data-mv-sort="' + s.id + '" aria-pressed="' + (active ? 'true' : 'false') + '">' +
        esc(s.label) + '</button>';
    }).join('');
  }

  function _mvEmptyHtml() {
    return (
      '<div class="mv-empty">' +
        '<div class="mv-empty-sigil" aria-hidden="true">' +
          '<svg width="56" height="56" viewBox="0 0 56 56" fill="none">' +
            '<path d="M28 3 L53 28 L28 53 L3 28 Z" stroke="#a78bfa" stroke-width="1.4" fill="rgba(139,92,246,0.06)"/>' +
            '<path d="M28 12 L44 28 L28 44 L12 28 Z" stroke="#a78bfa" stroke-width="0.8" opacity="0.6" fill="none"/>' +
            '<path d="M28 19 L37 28 L28 37 L19 28 Z" fill="#f5b842" opacity="0.85"/>' +
          '</svg>' +
        '</div>' +
        '<p class="mv-empty-verse">No active vows.<br>The system waits for your first promise.</p>' +
        '<p class="mv-empty-sub">Every climb begins with one kept vow.</p>' +
        '<button id="mv-empty-add" class="mv-cta-gold" type="button">BIND A VOW</button>' +
      '</div>'
    );
  }

  function _mvRenderSheet(opts) {
    const overlay = document.getElementById('mv-overlay');
    if (!overlay) return;
    const sheet = overlay.querySelector('.mv-sheet');
    if (!sheet) return;
    const roomMade = !!(opts && opts.roomMade);

    const activeCount = getActiveHabitCount();
    const counterEl = document.getElementById('mv-counter-wrap');
    if (counterEl) counterEl.innerHTML = _mvCounterHtml(roomMade);
    if (opts && opts.tick) {
      const numEl = sheet.querySelector('.mv-counter-num');
      if (numEl) {
        try {
          numEl.classList.add('mv-counter-tick');
          setTimeout(function () { try { numEl.classList.remove('mv-counter-tick'); } catch (_) {} }, 160);
        } catch (_) {}
      }
    }

    const bodyEl = document.getElementById('mv-body');
    if (!bodyEl) return;

    if (activeCount === 0) {
      bodyEl.innerHTML = _mvEmptyHtml();
      const addBtn = document.getElementById('mv-empty-add');
      if (addBtn) addBtn.addEventListener('click', function () {
        closeManageVows();
        // Route to Habits tab — empty state means user is at 0, which
        // will surface the First Vow picker / Add Habits flow naturally.
        try { if (typeof switchTab === 'function') switchTab('habits'); } catch (_) {}
      });
      // Hide sort + character section in empty state.
      const charEl = document.getElementById('mv-character');
      if (charEl) charEl.classList.add('hidden');
      // v3 Phase 1z.283 W173 — toggle the sortbar WRAPPER so its
      // "SORT" label hides with the pills in empty state.
      const sortBarEl = document.getElementById('mv-sortbar');
      if (sortBarEl) sortBarEl.classList.add('hidden');
      const sortEl = document.getElementById('mv-sort');
      if (sortEl) sortEl.classList.add('hidden');
      return;
    }

    // Restore character + sort visibility (in case they were hidden by empty).
    const charEl = document.getElementById('mv-character');
    if (charEl) charEl.classList.remove('hidden');
    const sortBarEl = document.getElementById('mv-sortbar');
    if (sortBarEl) sortBarEl.classList.remove('hidden');
    const sortEl = document.getElementById('mv-sort');
    if (sortEl) {
      sortEl.classList.remove('hidden');
      sortEl.innerHTML = _mvSortPillsHtml();
      sortEl.querySelectorAll('[data-mv-sort]').forEach(function (b) {
        b.addEventListener('click', function () {
          const id = b.getAttribute('data-mv-sort');
          if (id && id !== _mvSort) {
            _mvSort = id;
            _mvRenderSheet();
          }
        });
      });
    }

    // List
    const rows = _mvSortedActive();
    let html = rows.map(_mvRowHtml).join('');
    if (rows.length === 1) {
      html += '<p class="mv-single-line">One vow remains. Release it and the system waits anew.</p>';
    }
    bodyEl.innerHTML = html;

    // Wire row buttons
    bodyEl.querySelectorAll('[data-mv-release]').forEach(function (b) {
      b.addEventListener('click', function () {
        const id = b.getAttribute('data-mv-release');
        if (id) {
          _mvConfirmId = id;
          _mvRenderSheet();
        }
      });
    });
    bodyEl.querySelectorAll('[data-mv-cancel]').forEach(function (b) {
      b.addEventListener('click', function () {
        _mvConfirmId = null;
        _mvRenderSheet();
      });
    });
    bodyEl.querySelectorAll('[data-mv-confirm]').forEach(function (b) {
      b.addEventListener('click', function () {
        const id = b.getAttribute('data-mv-confirm');
        if (id) _mvReleaseHabit(id);
      });
    });
  }

  function _mvReleaseHabit(habitId) {
    if (!Array.isArray(habits)) return;
    const idx = habits.findIndex(function (h) { return h && h.id === habitId; });
    if (idx === -1) return;
    const prevCount = getActiveHabitCount();

    // v3 Phase 1z.283 W172 — DURABILITY: persist the archive flag
    // BEFORE the 300ms collapse animation. The earlier flow deferred
    // the write inside the setTimeout, which could lose a release if
    // the app was backgrounded/killed during the animation. Now the
    // user's intent is durable the moment they tap Confirm; the
    // animation is purely visual and replayable from state.
    try {
      habits[idx].archived = true;
      if (typeof save === 'function') save();
    } catch (_) {}

    _mvConfirmId = null;
    _mvReleasingId = habitId;

    // Re-render to show the releasing animation class on the row.
    _mvRenderSheet();

    const reducedMotion = (window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches);
    const delay = reducedMotion ? 200 : 300;
    setTimeout(function () {
      _mvReleasingId = null;

      const newCount = getActiveHabitCount();
      const roomMade = (prevCount > MAX_ACTIVE_HABITS && newCount <= MAX_ACTIVE_HABITS);
      _mvRenderSheet({ tick: true, roomMade: roomMade });

      if (roomMade) {
        if (navigator.vibrate) { try { navigator.vibrate(12); } catch (_) {} }
        clearTimeout(_mvRoomMadeTimer);
        _mvRoomMadeTimer = setTimeout(function () {
          _mvRenderSheet({ tick: false, roomMade: false });
        }, 2200);
      }

      // Sync main app: re-render habits list (active list now shorter)
      // and refresh progress %.
      try { if (typeof renderHabits === 'function') renderHabits({ skipSideEffects: true }); } catch (_) {}
      try { if (typeof updateProgress === 'function') updateProgress(); } catch (_) {}
    }, delay);
  }

  function openManageVows() {
    const overlay = document.getElementById('mv-overlay');
    if (!overlay) return;
    _mvConfirmId = null;
    _mvReleasingId = null;
    _mvRenderSheet();
    overlay.classList.remove('hidden');
    overlay.setAttribute('aria-hidden', 'false');
    document.addEventListener('keydown', _mvKeydown, true);
  }
  function closeManageVows() {
    const overlay = document.getElementById('mv-overlay');
    if (!overlay) return;
    overlay.classList.add('hidden');
    overlay.setAttribute('aria-hidden', 'true');
    document.removeEventListener('keydown', _mvKeydown, true);
    clearTimeout(_mvRoomMadeTimer);
  }
  function _mvKeydown(e) {
    if (e.key === 'Escape') closeManageVows();
  }
  try {
    window.__openManageVows  = openManageVows;
    window.__closeManageVows = closeManageVows;
  } catch (_) {}

  // ── Field Manual engine ─────────────────────────────────────────────
  // Three views: cover → index → section. Section navigation via prev/
  // next buttons + jump-via-dots + ESC closes the sheet entirely.
  let _faManualView = 'cover'; // 'cover' | 'index' | 'section'
  let _faManualSi   = 0;       // section index when in 'section' view

  function openFieldManual() {
    const overlay = document.getElementById('fa-manual-overlay');
    if (!overlay) return;
    _faManualView = 'cover';
    _faManualSi   = 0;
    _faRenderManual();
    overlay.classList.remove('hidden');
    overlay.setAttribute('aria-hidden', 'false');
    document.addEventListener('keydown', _faManualKeydown, true);
  }
  function closeFieldManual() {
    const overlay = document.getElementById('fa-manual-overlay');
    if (!overlay) return;
    overlay.classList.add('hidden');
    overlay.setAttribute('aria-hidden', 'true');
    document.removeEventListener('keydown', _faManualKeydown, true);
  }
  function _faManualKeydown(e) {
    if (e.key === 'Escape') {
      closeFieldManual();
      return;
    }
    if (_faManualView !== 'section') return;
    if (e.key === 'ArrowRight' && _faManualSi < FA_MANUAL_SECTIONS.length - 1) {
      _faManualSi += 1;
      _faRenderManual();
    } else if (e.key === 'ArrowLeft' && _faManualSi > 0) {
      _faManualSi -= 1;
      _faRenderManual();
    }
  }
  function _faRenderManual() {
    const body = document.getElementById('fa-manual-body');
    if (!body) return;
    if (_faManualView === 'cover') body.innerHTML = _faManualCoverHtml();
    else if (_faManualView === 'index') body.innerHTML = _faManualIndexHtml();
    else body.innerHTML = _faManualSectionHtml(_faManualSi);
    _faRenderManualChrome();
    _faWireManualBody();
    // Scroll body to top on view/section change
    body.scrollTop = 0;
  }
  function _faRenderManualChrome() {
    // Top bar shows different content per view; pager footer only in 'section'.
    const top = document.getElementById('fa-manual-topbar');
    if (top) {
      if (_faManualView === 'section') {
        const num = String(_faManualSi + 1).padStart(2, '0');
        const total = String(FA_MANUAL_SECTIONS.length).padStart(2, '0');
        top.innerHTML =
          '<button id="fa-manual-back" class="fa-manual-navbtn" type="button" aria-label="Back to manual index">' +
            '<svg width="7" height="11" viewBox="0 0 7 11" aria-hidden="true"><path d="M6 1L1 5.5 6 10" stroke="currentColor" stroke-width="1.5" fill="none" stroke-linecap="round" stroke-linejoin="round"/></svg>' +
            '<span>INDEX</span>' +
          '</button>' +
          '<span class="fa-manual-progress">' + num + ' / ' + total + '</span>' +
          '<button id="fa-manual-close" class="fa-manual-navbtn fa-manual-navbtn--end" type="button" aria-label="Close Field Manual">' +
            '<svg width="13" height="13" viewBox="0 0 13 13" aria-hidden="true"><path d="M1 1l11 11M12 1L1 12" stroke="currentColor" stroke-width="1.4" stroke-linecap="round"/></svg>' +
          '</button>';
      } else {
        top.innerHTML =
          '<span class="fa-manual-navbtn"></span>' +
          '<span class="fa-manual-progress">THE FIELD MANUAL</span>' +
          '<button id="fa-manual-close" class="fa-manual-navbtn fa-manual-navbtn--end" type="button" aria-label="Close Field Manual">' +
            '<svg width="13" height="13" viewBox="0 0 13 13" aria-hidden="true"><path d="M1 1l11 11M12 1L1 12" stroke="currentColor" stroke-width="1.4" stroke-linecap="round"/></svg>' +
          '</button>';
      }
      const back = document.getElementById('fa-manual-back');
      if (back) back.addEventListener('click', function () {
        _faManualView = 'index';
        _faRenderManual();
      });
      const closeBtn = document.getElementById('fa-manual-close');
      if (closeBtn) closeBtn.addEventListener('click', closeFieldManual);
    }
    const pager = document.getElementById('fa-manual-pager');
    if (pager) {
      if (_faManualView === 'section') {
        pager.innerHTML = _faManualPagerHtml(_faManualSi);
        pager.classList.remove('hidden');
        const prev = document.getElementById('fa-manual-prev');
        if (prev) prev.addEventListener('click', function () {
          if (_faManualSi > 0) { _faManualSi -= 1; _faRenderManual(); }
        });
        const next = document.getElementById('fa-manual-next');
        if (next) next.addEventListener('click', function () {
          if (_faManualSi < FA_MANUAL_SECTIONS.length - 1) { _faManualSi += 1; _faRenderManual(); }
        });
        const dots = pager.querySelectorAll('.fa-manual-pager-dot');
        dots.forEach(function (d, i) {
          d.addEventListener('click', function () { _faManualSi = i; _faRenderManual(); });
        });
      } else {
        pager.innerHTML = '';
        pager.classList.add('hidden');
      }
    }
  }
  function _faWireManualBody() {
    const openBtn = document.getElementById('fa-manual-open-btn');
    if (openBtn) openBtn.addEventListener('click', function () {
      _faManualView = 'index';
      _faRenderManual();
    });
    const indexBtns = document.querySelectorAll('[data-fa-manual-jump]');
    indexBtns.forEach(function (b) {
      b.addEventListener('click', function () {
        const i = parseInt(b.getAttribute('data-fa-manual-jump'), 10);
        if (!isNaN(i)) { _faManualSi = i; _faManualView = 'section'; _faRenderManual(); }
      });
    });
  }
  function _faManualCoverHtml() {
    return (
      '<div class="fa-manual-cover">' +
        '<div class="fa-manual-cover-figure">' +
          '<img src="assets/coach/first-awakened-idle.png" alt="The First Awakened" class="fa-manual-figure-img">' +
        '</div>' +
        '<div class="fa-manual-kicker">' +
          '<span class="fa-manual-kicker-diamond"></span>' +
          '<span>THE FIELD MANUAL</span>' +
          '<span class="fa-manual-kicker-diamond"></span>' +
        '</div>' +
        '<h2 class="fa-manual-cover-title">The system, plainly stated.</h2>' +
        '<div class="fa-manual-divider"></div>' +
        '<p class="fa-manual-cover-verse">' +
          '“I keep no secrets here.<br>' +
          'The system has rules.<br>' +
          'I have only read them longer than you.”' +
        '</p>' +
        '<p class="fa-manual-cover-sub">A record kept by the first who finished.</p>' +
        '<div class="fa-manual-cover-cta-wrap">' +
          '<button id="fa-manual-open-btn" class="fa-coach-cta fa-manual-open-btn" type="button">OPEN THE MANUAL</button>' +
        '</div>' +
      '</div>'
    );
  }
  function _faManualIndexHtml() {
    let rows = '';
    for (let i = 0; i < FA_MANUAL_SECTIONS.length; i++) {
      const s = FA_MANUAL_SECTIONS[i];
      const num = String(i + 1).padStart(2, '0');
      rows +=
        '<button class="fa-manual-index-row" type="button" data-fa-manual-jump="' + i + '"' +
          ' aria-label="Read section ' + (i + 1) + ': ' + esc(s.title) + '">' +
          '<span class="fa-manual-index-num">' + num + '</span>' +
          '<span class="fa-manual-index-glyph">' + _faSectionGlyph(s.glyph, 26) + '</span>' +
          '<span class="fa-manual-index-title">' + esc(s.title) + '</span>' +
          '<svg width="7" height="11" viewBox="0 0 7 11" class="fa-manual-index-chev" aria-hidden="true"><path d="M1 1l5 4.5L1 10" stroke="currentColor" stroke-width="1.5" fill="none" stroke-linecap="round" stroke-linejoin="round"/></svg>' +
        '</button>';
    }
    return (
      '<div class="fa-manual-index">' +
        '<div class="fa-manual-index-head">' +
          '<img src="assets/coach/first-awakened-idle.png" alt="" class="fa-manual-index-figure">' +
          '<div class="fa-manual-index-headtxt">' +
            '<h2 class="fa-manual-index-title-h">The Manual</h2>' +
            '<p class="fa-manual-index-sub">Seven systems. Read in any order.</p>' +
          '</div>' +
        '</div>' +
        '<div class="fa-manual-index-list">' + rows + '</div>' +
      '</div>'
    );
  }
  function _faManualSectionHtml(idx) {
    const s = FA_MANUAL_SECTIONS[idx];
    if (!s) return '';
    return (
      '<div class="fa-manual-section">' +
        '<div class="fa-manual-section-head">' +
          '<div class="fa-manual-section-glyph">' + _faSectionGlyph(s.glyph, 40) + '</div>' +
          '<h2 class="fa-manual-section-title">' + esc(s.title) + '</h2>' +
          '<div class="fa-manual-divider"></div>' +
        '</div>' +
        '<p class="fa-manual-section-body">' + esc(s.body) + '</p>' +
        '<div class="fa-manual-section-tip">' +
          '<span class="fa-manual-tip-diamond"></span>' +
          '<p class="fa-manual-tip-text">' + esc(s.tip) + '</p>' +
        '</div>' +
      '</div>'
    );
  }
  function _faManualPagerHtml(idx) {
    let dots = '';
    for (let i = 0; i < FA_MANUAL_SECTIONS.length; i++) {
      dots += '<span class="fa-manual-pager-dot' + (i === idx ? ' is-active' : '') + '"></span>';
    }
    const prevDis = (idx === 0) ? ' disabled aria-disabled="true"' : '';
    const nextDis = (idx === FA_MANUAL_SECTIONS.length - 1) ? ' disabled aria-disabled="true"' : '';
    return (
      '<button id="fa-manual-prev" class="fa-manual-pager-btn"' + prevDis + ' aria-label="Previous section">' +
        '<svg width="7" height="11" viewBox="0 0 7 11" aria-hidden="true"><path d="M6 1L1 5.5 6 10" stroke="currentColor" stroke-width="1.5" fill="none" stroke-linecap="round" stroke-linejoin="round"/></svg>' +
        'PREV' +
      '</button>' +
      '<div class="fa-manual-pager-dots">' + dots + '</div>' +
      '<button id="fa-manual-next" class="fa-manual-pager-btn"' + nextDis + ' aria-label="Next section">' +
        'NEXT' +
        '<svg width="7" height="11" viewBox="0 0 7 11" aria-hidden="true"><path d="M1 1l5 4.5L1 10" stroke="currentColor" stroke-width="1.5" fill="none" stroke-linecap="round" stroke-linejoin="round"/></svg>' +
      '</button>'
    );
  }
  try { window.__openFieldManual = openFieldManual; } catch (_) {}

  // W489 — custom habits now pick easy/medium/hard (default medium). Legendary is EXCLUDED
  // (the anti-gaming clamp): a user-authored habit tops out at hard (5 XP / 1.3x compound),
  // never the 1.5x legendary tier. Default medium keeps the economy byte-identical for anyone
  // who doesn't touch the picker. Capped at MAX_CUSTOM_HABITS.
  let _customEmoji   = '⚡';
  let _customStatId  = null;
  let _customDiff    = CUSTOM_HABIT_DIFFICULTY;   // 'medium' default; user-selectable easy/medium/hard

  // v3 Phase 1z.270 — Custom habit icon picker state.
  // v3 Phase 1z.270B — `_customEmojiModeChosen` tracks whether the
  // user explicitly opted into the emoji fallback (via "Use emoji
  // instead"). Create Habit is gated on (iconKey OR emojiModeChosen)
  // so a fresh modal can't silently ship with the default lightning
  // bolt — the user must consciously choose.
  let _customIconKey = null;
  let _customEmojiModeChosen = false;
  // v3 Phase 1z.273D — schedule selection state for the Create
  // Your Own Habit modal. Defaults to all 7 days (= "Every day").
  // saveCustomHabit only writes habit.days when the user picked a
  // subset; if all 7 remain selected, the field is omitted entirely
  // and isScheduledToday's length-7 / no-field shortcut keeps the
  // habit on daily cadence. Minimum 1 day is enforced via the same
  // click-handler pattern as the schedule sheet's day pills.
  let _customDays = [...ALL_DAYS];
  function openCustomHabitModal() {
    if (habits.filter(h => h.custom).length >= MAX_CUSTOM_HABITS) return;
    _customEmoji  = '⚡';
    _customStatId = null;
    _customIconKey = null;
    _customEmojiModeChosen = false;
    _customDays = [...ALL_DAYS];
    _customDiff = CUSTOM_HABIT_DIFFICULTY;
    document.getElementById('custom-name-input').value = '';
    document.getElementById('custom-error').classList.add('hidden');
    _renderCustomIconBtn();
    _renderCustomIconGrid();
    _renderCustomDays();
    // v3 Phase 1z.270B — picker grid OPENS by default so the choice
    // is the first thing the user sees. 1z.270 hid it; on-device QA
    // showed users tapped Create Habit without realizing the
    // lightning bolt was a picker trigger.
    const grid = document.getElementById('custom-icon-grid');
    if (grid) grid.classList.remove('hidden');
    renderCustomStatGrid();
    _renderCustomDiff();
    updateCustomSaveBtn();
    document.getElementById('custom-overlay').classList.remove('hidden');
    setTimeout(() => {
      try { document.getElementById('custom-name-input').focus(); } catch (_) {}
    }, 80);
  }

  // Render the identity button.
  //   - PNG icon if iconKey selected → <img> centered via flex parent
  //   - Emoji if emoji-mode opted in  → emoji glyph centered via flex
  //   - Otherwise (fresh state)       → minimal dark placeholder tile
  //
  // v3 Phase 1z.270C — removed the ⚡ default visual. A fresh modal
  // now shows a clean dark placeholder tile instead of a lightning
  // emoji so the resting state reads as "intentional empty," not as
  // "lightning is your icon."
  function _renderCustomIconBtn() {
    const btn = document.getElementById('custom-emoji-btn');
    if (!btn) return;
    if (_customIconKey && HABIT_ICON_BY_KEY[_customIconKey]) {
      btn.innerHTML = '<img class="custom-emoji-btn-img" src="' +
        HABIT_ICON_BY_KEY[_customIconKey] + '" alt="" draggable="false" loading="eager" decoding="async">';
    } else if (_customEmojiModeChosen && _customEmoji) {
      // User explicitly opted into emoji mode — render whatever
      // emoji they chose (including ⚡ if that's what they picked).
      // The placeholder is reserved for the resting "nothing picked
      // yet" state.
      btn.innerHTML = '<span class="custom-emoji-btn-glyph">' + esc(_customEmoji) + '</span>';
    } else {
      btn.innerHTML = '<span class="custom-emoji-btn-placeholder" aria-hidden="true"></span>';
    }
  }

  // Build the icon grid the first time the modal opens. Idempotent.
  function _renderCustomIconGrid() {
    const grid = document.getElementById('custom-icon-grid');
    if (!grid) return;
    if (grid.dataset.built === '1') {
      _refreshCustomIconGridSelection();
      return;
    }
    grid.dataset.built = '1';
    let html = '';
    for (const cat of HABIT_ICON_CATEGORY_ORDER) {
      const items = HABIT_ICON_OPTIONS.filter(o => o.cat === cat);
      if (!items.length) continue;
      html += '<div class="custom-icon-section-label">' + esc(cat) + '</div>';
      html += '<div class="custom-icon-row">';
      for (const o of items) {
        html += '<button type="button" class="custom-icon-tile" data-icon-key="' + esc(o.key) +
          '" aria-label="' + esc(o.label) + '" title="' + esc(o.label) + '">' +
          '<img src="' + o.path + '" alt="" draggable="false" loading="lazy" decoding="async">' +
          '</button>';
      }
      html += '</div>';
    }
    grid.innerHTML = html;
    grid.querySelectorAll('.custom-icon-tile').forEach(tile => {
      tile.addEventListener('click', () => {
        _customIconKey = tile.getAttribute('data-icon-key') || null;
        // v3 Phase 1z.270B — selecting an icon supersedes any prior
        // emoji-mode opt-in. Clears the warning if it was showing.
        _customEmojiModeChosen = false;
        const errEl = document.getElementById('custom-error');
        if (errEl) errEl.classList.add('hidden');
        _refreshCustomIconGridSelection();
        _renderCustomIconBtn();
        try { updateCustomSaveBtn(); } catch (_) {}
        // Auto-collapse the grid after selection so the modal stays compact.
        try { grid.classList.add('hidden'); } catch (_) {}
      });
    });
    _refreshCustomIconGridSelection();
  }
  function _refreshCustomIconGridSelection() {
    const grid = document.getElementById('custom-icon-grid');
    if (!grid) return;
    grid.querySelectorAll('.custom-icon-tile').forEach(tile => {
      const isSelected = (_customIconKey && tile.getAttribute('data-icon-key') === _customIconKey);
      tile.classList.toggle('is-selected', !!isSelected);
    });
  }

  function closeCustomHabitModal() {
    document.getElementById('custom-overlay').classList.add('hidden');
  }

  // v3 Phase 1z.273D — Days row renderer/wiring for the Create Your
  // Own Habit modal. Reuses the shared `.days-row .day-btn[data-day]`
  // pattern + setActiveDays() helper from the schedule sheet so CSS
  // and selection visuals stay identical. Min-1-day rule mirrors the
  // schedule sheet pattern (line ~23805). Idempotent: re-binding is
  // gated by a data-wired flag so reopening the modal doesn't stack
  // listeners.
  function _renderCustomDays() {
    const row = document.getElementById('custom-days-row');
    if (!row) return;
    setActiveDays('custom-days-row', _customDays);
    _refreshCustomDaysSub();
    if (row.dataset.wired === '1') return;
    row.dataset.wired = '1';
    row.querySelectorAll('.day-btn').forEach(btn => {
      btn.addEventListener('click', () => {
        btn.classList.toggle('active');
        _customDays = [...row.querySelectorAll('.day-btn.active')].map(b => b.dataset.day);
        if (_customDays.length === 0) {
          // Minimum 1 day — revert and toast (mirrors schedule sheet).
          btn.classList.add('active');
          _customDays = [btn.dataset.day];
          try {
            if (typeof showHabitToast === 'function') {
              showHabitToast('Choose at least one day.');
            }
          } catch (_) {}
        }
        _refreshCustomDaysSub();
      });
    });
  }
  function _refreshCustomDaysSub() {
    const sub = document.getElementById('custom-days-sub');
    if (!sub) return;
    sub.textContent = (_customDays.length === 7) ? 'Every day' : 'Scheduled days';
  }

  // W489 — custom-habit difficulty picker (easy/medium/hard; NO legendary — the anti-gaming clamp).
  // 3 layers: legendary is omitted from the markup, ignored in this handler, AND clamped on persist,
  // so a user-authored habit can never exceed hard (5 XP / 1.3x compound). Mirrors the days-row
  // wiring (idempotent via data-wired so reopening the modal can't stack listeners).
  const CUSTOM_DIFF_ALLOWED = ['easy', 'medium', 'hard'];
  function _clampCustomDiff(d) { return CUSTOM_DIFF_ALLOWED.indexOf(d) >= 0 ? d : 'medium'; }
  // W508 — surface the W485 difficulty tilt (Economy transparency). The custom
  // compound is ~90% of rank XP and scales by the routine's AVERAGE habit
  // difficulty, but that lever was invisible at create-time. Paints a muted
  // help line showing the per-tier "if your whole routine were this hard"
  // multiplier, derived LIVE from the SAME economy function the award path uses
  // (AwakenedEconomy.customCompoundDifficultyFactor over DIFFICULTY[d].pts) so
  // it can never disagree. Pure read — awards no XP, sets no state; self-guarded
  // so a missing AwakenedEconomy (W480 fail-mode) just blanks the line.
  function _paintCustomDiffMult() {
    const el = document.getElementById('custom-diff-mult');
    if (!el) return;
    try {
      const f = d => AwakenedEconomy.customCompoundDifficultyFactor(DIFFICULTY[d].pts).toFixed(1);
      el.textContent = 'Daily Compound (routine avg) — all-Easy ' + f('easy') +
        '×, Medium ' + f('medium') + '× base, all-Hard ' + f('hard') + '×.';
    } catch (_) { el.textContent = ''; }
  }
  function _renderCustomDiff() {
    const row = document.getElementById('custom-diff-row');
    if (!row) return;
    setActiveDiff('custom-diff-row', _customDiff);
    _paintCustomDiffMult();   // W508 — surface the routine compound tilt
    if (row.dataset.wired === '1') return;
    row.dataset.wired = '1';
    row.querySelectorAll('.diff-btn').forEach(btn => {
      btn.addEventListener('click', () => {
        _customDiff = _clampCustomDiff(btn.dataset.diff);   // ignore legendary / unknown
        setActiveDiff('custom-diff-row', _customDiff);
      });
    });
  }

  function renderCustomStatGrid() {
    const grid = document.getElementById('custom-stat-grid');
    if (!grid) return;
    grid.innerHTML = '';
    STATS.forEach(st => {
      const btn = document.createElement('button');
      btn.type = 'button';
      btn.className = 'custom-stat-btn' + (_customStatId === st.id ? ' selected' : '');
      btn.style.setProperty('--cs-color', st.color);
      btn.style.setProperty('--cs-glow',  colorWithAlpha(st.color, 0.32));
      btn.innerHTML =
        '<span class="custom-stat-icon">' + statIconHtml(st, { size: 22 }) + '</span>' +
        '<span class="custom-stat-name">' + esc(st.label) + '</span>';
      btn.addEventListener('click', () => {
        _customStatId = st.id;
        renderCustomStatGrid();
        updateCustomSaveBtn();
      });
      grid.appendChild(btn);
    });
  }

  function updateCustomSaveBtn() {
    const name = (document.getElementById('custom-name-input').value || '').trim();
    // v3 Phase 1z.270B — Create Habit now requires an explicit icon
    // choice (or a deliberate "Use emoji instead" opt-in). Prevents
    // the silent default-lightning-bolt outcome surfaced in QA.
    const iconChosen = !!_customIconKey || !!_customEmojiModeChosen;
    document.getElementById('custom-save-btn').disabled =
      !(name.length > 0 && _customStatId && iconChosen);
  }

  function saveCustomHabit() {
    try { _addHabitBreadcrumb('custom-create-click'); } catch (_) {}
    const name = (document.getElementById('custom-name-input').value || '').trim();
    const errEl = document.getElementById('custom-error');
    const showErr = (msg) => {
      try { _addHabitBreadcrumb('custom-create-validation-failed', { reason: msg }); } catch (_) {}
      errEl.textContent = msg; errEl.classList.remove('hidden');
    };

    if (!name)            return showErr('Give your habit a name.');
    if (!_customStatId)   return showErr('Pick the stat this habit trains.');
    // v3 Phase 1z.270B — belt-and-braces icon-choice guard. The Create
    // button is disabled until the user picks an icon or opts into
    // emoji mode, but if anything bypasses that (cached HTML, keyboard
    // submit, etc.) this surfaces a clear inline message and re-opens
    // the picker grid.
    if (!_customIconKey && !_customEmojiModeChosen) {
      try {
        const grid = document.getElementById('custom-icon-grid');
        if (grid) grid.classList.remove('hidden');
      } catch (_) {}
      return showErr('Choose an icon first.');
    }
    // v3 Phase 1z.283 W177 — Active-only dedup + archived restore path.
    // Custom habits have no library entry to surface them, so before
    // W177 a custom vow archived via Manage Vows was effectively
    // destroyed: name collision blocked recreation, no UI exposed the
    // archived entry, and its MAX_CUSTOM_HABITS slot stayed consumed
    // forever. Mirroring W176's built-in Option B: case-insensitive
    // active-only dedup; if the name matches an ARCHIVED habit (custom
    // or built-in), un-archive it instead of erroring.
    const _nameKey = name.toLowerCase();
    const _activeNameCollision = habits.some(h => _isActiveHabit(h) && typeof h.name === 'string' && h.name.toLowerCase() === _nameKey);
    if (_activeNameCollision) {
      return showErr('You already have a habit with that name.');
    }
    const _archivedMatch = habits.find(h => h && h.archived === true && typeof h.name === 'string' && h.name.toLowerCase() === _nameKey);
    if (_archivedMatch) {
      // Active habit cap still applies — restoring brings the count up
      // by 1, so the System Full gate must pass before the un-archive.
      if (!canAddHabits(1)) {
        try { _addHabitBreadcrumb('custom-create-restore-blocked-system-full', {
          activeCount: getActiveHabitCount(),
        }); } catch (_) {}
        try { showSystemFullModal({ context: 'custom', attemptedCount: 1 }); } catch (_) {}
        return;
      }
      _archivedMatch.archived = false;
      try {
        _addHabitBreadcrumb('custom-create-restored', {
          name:        _archivedMatch.name,
          activeCount: getActiveHabitCount(),
          wasCustom:   !!_archivedMatch.custom,
        });
      } catch (_) {}
      try { save(); } catch (_) {}
      try { closeCustomHabitModal(); } catch (_) {}
      try { closeLibrary(); } catch (_) {}
      try { renderHabits({ skipSideEffects: true }); } catch (_) {}
      try { renderLibrary(); } catch (_) {}
      try { showHabitToast('Vow restored — ' + _archivedMatch.name); } catch (_) {}
      return;
    }
    // v3 Phase 1z.280 — Active habit cap. Gate BEFORE MAX_CUSTOM_HABITS
    // so the broader cap wins if both fail (the user shouldn't see a
    // "5 custom habit cap" error when their real problem is "25 active
    // vow cap"). Surfaces the System Full modal, dismisses the custom
    // modal context naturally on dismissal.
    if (!canAddHabits(1)) {
      try { _addHabitBreadcrumb('custom-create-blocked-system-full', {
        activeCount: getActiveHabitCount(),
      }); } catch (_) {}
      try { showSystemFullModal({ context: 'custom', attemptedCount: 1 }); } catch (_) {}
      return;
    }
    // v3 Phase 1z.283 W177 — Custom-habit cap counts ACTIVE customs
    // only. Archived customs no longer consume slots indefinitely.
    if (habits.filter(h => _isActiveHabit(h) && h.custom).length >= MAX_CUSTOM_HABITS) {
      return showErr('You\'ve reached the ' + MAX_CUSTOM_HABITS + '-custom-habit cap.');
    }

    // v3 Phase 1z.273D — defensive zero-day guard (UI prevents this
    // via min-1 click handler, but belt-and-braces against any future
    // path that could land here with an empty array).
    if (Array.isArray(_customDays) && _customDays.length === 0) {
      return showErr('Choose at least one day.');
    }
    const newH = {
      id:          uid(),
      emoji:       _customEmoji || '⚡',
      name:        name,
      difficulty:  _clampCustomDiff(_customDiff),
      type:        'build',
      primaryStat: _customStatId,
      custom:      true,
    };
    // v3 Phase 1z.270 — persist optional icon picker selection. Legacy
    // habits without iconKey still render emoji via the existing
    // habitIconHtml fallback. Field is purely additive — no migration.
    if (_customIconKey && HABIT_ICON_BY_KEY[_customIconKey]) {
      newH.iconKey = _customIconKey;
    }
    // v3 Phase 1z.273D — persist schedule subset. All 7 days = field
    // omitted = daily via isScheduledToday's length-7 / no-field
    // shortcut. Matches the schedule sheet's save convention.
    if (Array.isArray(_customDays) && _customDays.length > 0 && _customDays.length < 7) {
      newH.days = _customDays.slice();
    }
    try {
      _addHabitBreadcrumb('custom-create-validated', {
        nameLen: name.length,
        stat: _customStatId,
        customCount: habits.filter(h => h.custom).length + 1,
      });
    } catch (_) {}

    habits.push(newH);
    // v3 Phase 1z.34 -- close BEFORE rendering. Same iOS post-save
    // freeze pattern as commitEdit: a thrown render exception would
    // otherwise strand the Add Custom Habit overlay.
    try { _addHabitBreadcrumb('custom-create-persist-start'); } catch (_) {}
    let saveOK = false;
    try { save(); saveOK = true; } catch (e) {
      try { console.warn('[custom] save failed', e); } catch (_) {}
      try { _addHabitBreadcrumb('custom-create-persist-threw', { err: String(e && e.message || e) }); } catch (_) {}
    }
    try { _addHabitBreadcrumb('custom-create-persist-ok', { saveOK }); } catch (_) {}

    // v3 Phase 1z.106 — close the parent Add Habits library sheet
    // too, mirroring the 1z.89 preset-add UX. Previous bug: the
    // custom-overlay closed cleanly, but lib-sheet + lib-overlay
    // stayed mounted, intercepting pointer events on the tab bar
    // and reading as a "freeze" to the user. Each close is wrapped
    // independently so a throw in one doesn't strand the others.
    try { closeCustomHabitModal(); } catch (e) { try { console.warn('[custom] close custom modal failed', e); } catch (_) {} }
    try { closeLibrary(); } catch (e) { try { console.warn('[custom] close library failed', e); } catch (_) {} }
    try { _addHabitBreadcrumb('custom-create-close-modal'); } catch (_) {}

    // v3 Phase 1z.97 — skipSideEffects to avoid HealthKit native-bridge
    // cascade. Same root cause as the Add Habits freeze (1z.95) — every
    // user-mutation render path was vulnerable, this is custom-habit save.
    try { _addHabitBreadcrumb('custom-create-render-start'); } catch (_) {}
    try {
      renderHabits({ skipSideEffects: true });
      try { _addHabitBreadcrumb('custom-create-render-ok'); } catch (_) {}
    } catch (e) {
      try { console.warn('[custom] post-save renderHabits failed', e); } catch (_) {}
      try { _addHabitBreadcrumb('custom-create-render-threw', { err: String(e && e.message || e) }); } catch (_) {}
    }
    // renderLibrary still runs so the "X left" counter / "Full" state
    // is correct the next time the sheet opens.
    try { renderLibrary(); } catch (e) {
      try { console.warn('[custom] post-save renderLibrary failed', e); } catch (_) {}
      try { _addHabitBreadcrumb('custom-create-render-library-threw', { err: String(e && e.message || e) }); } catch (_) {}
    }

    // Toast confirms the add so the user has unambiguous feedback
    // (mirrors confirmPackAdd's pattern). Non-blocking.
    try { showHabitToast('"' + name + '" added'); } catch (_) {}

    try { _addHabitBreadcrumb('custom-create-complete'); } catch (_) {}
    // Per-habit reminder offers were removed in v1.1.3 — Awakened sends
    // ONE morning digest by default, no per-habit prompts. Power users
    // can still set per-habit reminders via Edit Habit.
  }

  function setupCustomHabitModal() {
    const overlay = document.getElementById('custom-overlay');
    if (!overlay) return;
    document.getElementById('custom-cancel-btn').addEventListener('click', closeCustomHabitModal);
    document.getElementById('custom-save-btn').addEventListener('click', saveCustomHabit);
    overlay.addEventListener('click', (e) => {
      if (e.target === overlay) closeCustomHabitModal();
    });
    document.getElementById('custom-name-input').addEventListener('input', updateCustomSaveBtn);
    document.getElementById('custom-name-input').addEventListener('keydown', (e) => {
      if (e.key === 'Enter' && !document.getElementById('custom-save-btn').disabled) {
        e.preventDefault();
        saveCustomHabit();
      }
    });
    // v3 Phase 1z.270 — Identity button now toggles the icon grid
    // (PNG picker) instead of opening the emoji picker. Emoji is kept
    // as a fallback for users who clear their icon selection — see the
    // "Use emoji instead" link below. Pre-1z.270 behavior (emoji-only)
    // is preserved for any legacy custom habits via _renderCustomIconBtn.
    document.getElementById('custom-emoji-btn').addEventListener('click', () => {
      const grid = document.getElementById('custom-icon-grid');
      if (!grid) return;
      grid.classList.toggle('hidden');
    });
    // "Use emoji instead" affordance — clears iconKey + opens the
    // legacy emoji picker so the user can pick an emoji as their
    // identity. Hidden by default; shown only after grid is built.
    const emojiLink = document.getElementById('custom-emoji-fallback');
    if (emojiLink) {
      emojiLink.addEventListener('click', (e) => {
        e.preventDefault();
        _customIconKey = null;
        _refreshCustomIconGridSelection();
        const btn = document.getElementById('custom-emoji-btn');
        openEmojiPicker(btn, _customEmoji, (em) => {
          _customEmoji = em || '⚡';
          // v3 Phase 1z.270B — user has now consciously opted into
          // emoji mode. Unblocks Create Habit.
          _customEmojiModeChosen = true;
          const errEl = document.getElementById('custom-error');
          if (errEl) errEl.classList.add('hidden');
          _renderCustomIconBtn();
          try { updateCustomSaveBtn(); } catch (_) {}
        });
      });
    }
  }

  function closeMorningPackModal() {
    document.getElementById('mr-overlay').classList.add('hidden');
  }

  function confirmPackAdd() {
    const packId  = _packModalActiveId;
    const missing = getMissingPackHabits(packId);
    if (missing.length === 0) { closeMorningPackModal(); return; }

    // v3 Phase 1z.280 — Active habit cap, pack bulk-add gate. `missing`
    // is already dedup-filtered against existing names, so its length
    // IS the effective add count. Blocking entirely (no partial add)
    // matches the bulk-add convention — the user picked the pack
    // expecting the whole set; adding only some without explanation
    // would be confusing.
    if (!canAddHabits(missing.length)) {
      closeMorningPackModal();
      try { showSystemFullModal({ context: 'pack', attemptedCount: missing.length }); } catch (_) {}
      return;
    }

    // Add in canonical pack order, preserving each habit's defaults.
    // Dedup: getMissingPackHabits already filtered to absent names.
    // Existing streaks/progress on existing entries remain untouched.
    const _justAdded = [];
    missing.forEach(def => {
      const newH = {
        id:          uid(),
        emoji:       def.emoji,
        name:        def.name,
        difficulty:  def.difficulty,
        type:        def.type || 'build',
        primaryStat: def.primaryStat,
      };
      habits.push(newH);
      _justAdded.push(newH);
      if (def.note) habitNotes[newH.id] = def.note;
    });
    save();
    // W659 — the auto-verify-first sort now lives inside the coalesced (deferred)
    // _saveNow, so a pack that adds an auto-verify habit (e.g. Daily walk) would
    // paint in the unsorted tail until the next render trigger. Sort synchronously
    // here so the immediate re-render below shows canonical order. Idempotent with
    // the deferred sort; persisted order is unaffected either way.
    try { sortHabitsAutoVerifyFirst(habits); } catch (_) {}

    // Mark the player's path (only on first MR add — Locked-In doesn't override)
    if (packId === 'morning' && !selectedPackId) {
      selectedPackId = 'morning';
      try { localStorage.setItem('hb_path', selectedPackId); } catch (_) {}
    }

    const pack = getPackById(packId);
    // v3 Phase 1z.34 -- iOS post-save freeze hardening. The Lock-In /
    // Morning Routine pack-add modal was reported stuck after Save on
    // TestFlight. The close calls run first (good), but any throw in
    // the render/update chain that follows would prevent the toast
    // from firing and -- depending on which call throws -- could
    // leave overlay state inconsistent. Each step now isolated.
    try { closeMorningPackModal(); } catch (e) { try { console.warn('[pack] close modal failed', e); } catch (_) {} }
    try { closeLibrary();          } catch (e) { try { console.warn('[pack] close library failed', e); } catch (_) {} }
    try { renderHabits({ skipSideEffects: true });          } catch (e) { try { console.warn('[pack] post-save render failed', e); } catch (_) {} }
    try { updateMorningButtonVisibility();  } catch (_) {}
    try { updateLockedInButtonVisibility(); } catch (_) {}

    // v3 Phase 1z.283 W178 — Greeting parity with the custom path.
    // Before W178: onboarding users who picked the Morning Routine /
    // Locked-In pack added 10/16 vows in one tap and were greeted
    // by a quick toast and (for reminderable packs) the notif prompt
    // — but the custom path (First Vow picker) fires the FA_FIRST_VOW
    // coachmark, so pack-path users were the only new hunters who
    // never met The First Awakened during onboarding.
    //
    // Fix: try showFirstVowCoachmark() after pack-add. It self-gates
    // on the hb_tour_first_vow_v1 storage key, so existing users
    // adding packs later get the toast as before; only new users
    // (key unset) see the coach. The notif prompt is chained via
    // onDismiss so it fires AFTER coach dismissal rather than
    // racing it on top of the FA modal.
    const isReminderable = (packId === 'morning' || packId === 'locked-in');
    const scheduleNotifPrompt = function () {
      if (!isReminderable) return;
      try {
        if (Notif && Notif.permAskedBefore && !Notif.permAskedBefore()) {
          setTimeout(() => runOnboardingNotifPrompt(() => {}), 600);
        }
      } catch (_) {}
    };

    let _faCoachShown = false;
    try {
      _faCoachShown = showFirstVowCoachmark({ onDismiss: scheduleNotifPrompt });
    } catch (_) { _faCoachShown = false; }

    if (!_faCoachShown) {
      // Existing-user path: toast as before, then notif prompt.
      try {
        if (pack && pack.name) {
          showHabitToast(pack.name + ' added — ' + missing.length + ' habit' + (missing.length === 1 ? '' : 's'));
        }
      } catch (_) {}
      scheduleNotifPrompt();
    }
  }

  // Backward-compat alias for existing wiring
  function confirmMorningPackAdd() { confirmPackAdd(); }

  // ── v3 Phase 1z.247 — FIRST VOW QUICK-PICKS ──────────────────
  // Six curated quick-pick vows shown in the Habits-tab empty
  // state when habits.length === 0. Each entry maps to an index
  // in DEFAULT_HABITS so habit-icon art, difficulty, and goal
  // semantics flow through the canonical paths (HABIT_ICONS,
  // isStepGoalHabit, isSleepDurationHabit, MEASURABLE_HABITS).
  //   • Hydrate                — DEFAULT_HABITS[0]
  //   • Sleep (7 hours)        — DEFAULT_HABITS[1]
  //   • Daily walk             — DEFAULT_HABITS[6]
  //   • Read                   — DEFAULT_HABITS[11]
  //   • Meditate & Breathwork  — DEFAULT_HABITS[12]
  //   • Get morning sunlight   — DEFAULT_HABITS[16]
  const FIRST_VOW_PICKS = [
    { idx: 0,  cadence: 'DAILY'   },
    { idx: 1,  cadence: 'NIGHTLY' },
    { idx: 6,  cadence: 'DAILY'   },
    { idx: 12, cadence: 'DAILY'   },
    { idx: 16, cadence: 'MORNING' },
    { idx: 11, cadence: 'DAILY'   },
  ];

  // v3 Phase 1z.250 — Multi-select state for First Vow quick-picks.
  // In-memory only; the empty state is shown ONLY when
  // getActiveHabitCount() === 0 (per v3 Phase 1z.283 W172 — was
  // habits.length === 0 prior), and is rebuilt from FIRST_VOW_PICKS
  // on every render, so selection is ephemeral by design. After
  // commit the empty state vanishes and this Set is irrelevant.
  // Cleared on successful commit so re-entry (via Reset all
  // progress, or via archiving every vow) starts clean.
  const _firstVowSelected = new Set();
  // Guard against rapid double-tap on the commit CTA so habits can't
  // duplicate while save() / renderHabits() are in flight.
  let _firstVowCommitting = false;

  function _renderFirstVowQuickPicks() {
    const grid = document.getElementById('empty-state-quickgrid');
    if (!grid) return;
    const fp = FIRST_VOW_PICKS
      .map(p => ({ p, def: DEFAULT_HABITS[p.idx] }))
      .filter(x => x.def);
    grid.innerHTML = fp.map(({ p, def }) => {
      const iconHtml = habitIconHtml(def, { size: 28, eager: true });
      const selected = _firstVowSelected.has(p.idx);
      return '' +
        '<button type="button" class="ev-chip' + (selected ? ' is-selected' : '') +
              '" data-quickpick-idx="' + p.idx + '"' +
              ' aria-pressed="' + (selected ? 'true' : 'false') + '">' +
          '<span class="ev-chip-check" aria-hidden="true">' +
            '<svg width="11" height="11" viewBox="0 0 12 12"><path d="M2 6.2 5 9l5-6" stroke="#1b1405" stroke-width="2" fill="none" stroke-linecap="round" stroke-linejoin="round"/></svg>' +
          '</span>' +
          '<span class="ev-chip-ic">' + iconHtml + '</span>' +
          '<span class="ev-chip-body">' +
            '<span class="ev-chip-name">' + esc(def.name) + '</span>' +
            '<span class="ev-chip-cad">' + esc(p.cadence) + '</span>' +
          '</span>' +
        '</button>';
    }).join('');
    _wireFirstVowQuickPicks();
    _updateFirstVowCommitCta();
  }

  function _updateFirstVowCommitCta() {
    const cta = document.getElementById('empty-state-commit');
    if (!cta) return;
    const n = _firstVowSelected.size;
    if (n === 0) {
      cta.textContent = 'SELECT A VOW';
      cta.disabled = true;
    } else {
      cta.textContent = 'BEGIN WITH ' + n + (n === 1 ? ' VOW' : ' VOWS');
      cta.disabled = false;
    }
  }

  function _toggleFirstVowSelection(idx, btnEl) {
    if (_firstVowSelected.has(idx)) {
      _firstVowSelected.delete(idx);
      if (btnEl) {
        btnEl.classList.remove('is-selected');
        btnEl.setAttribute('aria-pressed', 'false');
      }
      try { _addHabitBreadcrumb && _addHabitBreadcrumb('first-vow-quickpick-deselect', {
        idx, selectedCount: _firstVowSelected.size,
      }); } catch (_) {}
    } else {
      // v3 Phase 1z.280 — Active habit cap, onboarding selection guard.
      // Reject silently with a small inline toast rather than firing
      // the full System Full modal — first-run shouldn't see a heavy
      // system message during habit selection. The post-commit cap
      // check below is the structural fallback.
      const remainingSlots = Math.max(0, MAX_ACTIVE_HABITS - (getActiveHabitCount() + _firstVowSelected.size));
      if (remainingSlots <= 0) {
        try {
          if (typeof showHabitToast === 'function') {
            showHabitToast(MAX_ACTIVE_HABITS + ' vow max — deselect one to swap.');
          }
        } catch (_) {}
        try { _addHabitBreadcrumb && _addHabitBreadcrumb('first-vow-quickpick-cap-block', {
          idx, selectedCount: _firstVowSelected.size, max: MAX_ACTIVE_HABITS,
        }); } catch (_) {}
        return;
      }
      _firstVowSelected.add(idx);
      if (btnEl) {
        btnEl.classList.add('is-selected');
        btnEl.setAttribute('aria-pressed', 'true');
      }
      try { _addHabitBreadcrumb && _addHabitBreadcrumb('first-vow-quickpick-select', {
        idx, selectedCount: _firstVowSelected.size,
      }); } catch (_) {}
    }
    _updateFirstVowCommitCta();
  }

  function _wireFirstVowQuickPicks() {
    const grid = document.getElementById('empty-state-quickgrid');
    if (grid && !grid.dataset.wired) {
      grid.dataset.wired = '1';
      grid.addEventListener('click', (e) => {
        const btn = e.target && e.target.closest && e.target.closest('.ev-chip');
        if (!btn) return;
        const idx = parseInt(btn.dataset.quickpickIdx, 10);
        if (isNaN(idx)) return;
        _toggleFirstVowSelection(idx, btn);
      });
    }
    const cta = document.getElementById('empty-state-commit');
    if (cta && !cta.dataset.wired) {
      cta.dataset.wired = '1';
      cta.addEventListener('click', () => {
        if (cta.disabled) return;
        _commitFirstVowSelection();
      });
    }
    const browse = document.getElementById('empty-state-browse');
    if (browse && !browse.dataset.wired) {
      browse.dataset.wired = '1';
      browse.addEventListener('click', () => {
        try { _addHabitBreadcrumb && _addHabitBreadcrumb('habits-empty-browse-library'); } catch (_) {}
        try { openLibrary(); } catch (_) {}
      });
    }
  }

  // v3 Phase 1z.250 — Build a single habit row from a DEFAULT_HABITS
  // index. Used by the multi-commit path below. Mirrors the goal-default
  // branches in _completeOnboardingFinish so curated step / sleep habits
  // get canonical thresholds without forcing the user to open a detail
  // sheet. Returns null on bad input; never throws.
  function _buildQuickPickHabitRow(idx) {
    const def = DEFAULT_HABITS && DEFAULT_HABITS[idx];
    if (!def || !def.name) return null;
    const newH = {
      id:          uid(),
      emoji:       def.emoji,
      name:        def.name,
      difficulty:  def.difficulty,
      type:        def.type || 'build',
    };
    if (def.primaryStat) newH.primaryStat = def.primaryStat;
    // W575 — carry the 14-day jump cadence onto library-added jump habits so
    // isScheduledToday's cycle branch governs them (only jump templates set it).
    if (Array.isArray(def.cycleDays) && def.cycleDays.length) newH.cycleDays = def.cycleDays.slice();
    // W579 — program tag: pre-anchor days are off-days for ALL jump habits.
    if (def.library) newH.library = def.library;
    try {
      if (typeof isStepGoalHabit === 'function' && isStepGoalHabit(def) &&
          typeof HEALTHKIT_WALK_DEFAULT_THRESHOLD === 'number') {
        newH.stepGoal = HEALTHKIT_WALK_DEFAULT_THRESHOLD;
      } else if (typeof isSleepDurationHabit === 'function' && isSleepDurationHabit(def) &&
          typeof HEALTHKIT_SLEEP_DEFAULT_GOAL_HOURS === 'number') {
        newH.sleepGoalHours = HEALTHKIT_SLEEP_DEFAULT_GOAL_HOURS;
      } else if (typeof MEASURABLE_HABITS !== 'undefined') {
        const m = MEASURABLE_HABITS[def.name];
        if (m) {
          const defVal = m.bodyweightMin
            ? Math.max(m.def, parseInt(localStorage.getItem('hb_bodyweight') || '0', 10))
            : Math.max(m.min, m.def);
          newH.goal = { value: defVal, unit: m.unit };
        }
      }
    } catch (_) {}
    return { def, newH };
  }

  // v3 Phase 1z.250 — Commit the in-memory selection. Builds rows for
  // each selected quick-pick, dedupes against existing habits by exact
  // name (same rule as getMissingPackHabits), pushes them all, then
  // performs a SINGLE save() + renderHabits({skipSideEffects:true}).
  //
  // Does NOT auto-complete, does NOT award XP, does NOT trigger
  // HealthKit verification on creation, does NOT emit public events.
  // Guarded against rapid double-tap via _firstVowCommitting.
  function _commitFirstVowSelection() {
    if (_firstVowCommitting) return;
    _firstVowCommitting = true;
    try {
      const picked = Array.from(_firstVowSelected);
      if (picked.length === 0) return;

      // v3 Phase 1z.283 W176 — Active-only dedup. Archived names no
      // longer block re-binding (Option B: re-add = un-archive). The
      // archive lookup below preserves streak/completions/XP history.
      const existingNames = new Set(habits.filter(_isActiveHabit).map(h => h && h.name));
      // v3 Phase 1z.280 — Active habit cap, defensive commit-time trim.
      // _toggleFirstVowSelection already blocks selection past 25, so
      // this is normally a no-op. But if the user comes through here
      // via a state restore (Reset → onboarding while legacy state
      // somehow held 26+ selections), trim safely to MAX_ACTIVE_HABITS
      // and breadcrumb. NEVER trap the user — onboarding must succeed.
      let trimmed = 0;
      const slotsLeft = Math.max(0, MAX_ACTIVE_HABITS - getActiveHabitCount());
      if (picked.length > slotsLeft) {
        trimmed = picked.length - slotsLeft;
        picked.length = slotsLeft;
        try { _addHabitBreadcrumb && _addHabitBreadcrumb('first-vow-commit-trim', {
          originalCount: picked.length + trimmed,
          trimmedTo: picked.length,
          slotsLeft: slotsLeft,
        }); } catch (_) {}
      }
      const created = [];
      const restored = []; // v3 Phase 1z.283 W176 — un-archived re-binds
      let skippedDup = 0;

      for (let i = 0; i < picked.length; i++) {
        const idx = picked[i];
        const built = _buildQuickPickHabitRow(idx);
        if (!built) continue;
        const { def, newH } = built;
        if (existingNames.has(def.name)) {
          skippedDup++;
          continue;
        }
        // v3 Phase 1z.283 W176 — Option B: re-add un-archives.
        // If an archived habit matches by name, flip archived=false
        // on the existing object (streak/completions/XP preserved)
        // instead of creating a new habit with a fresh streak.
        const archivedMatch = _findArchivedHabitByName(def.name);
        if (archivedMatch) {
          archivedMatch.archived = false;
          existingNames.add(def.name);
          restored.push(def.name);
          continue;
        }
        habits.push(newH);
        if (def.note) habitNotes[newH.id] = def.note;
        existingNames.add(def.name);
        created.push(def.name);
      }

      // Clear selection so re-entry (Reset all progress → onboarding)
      // starts clean. Empty state will be re-rendered if habits is still 0.
      _firstVowSelected.clear();

      try { save(); } catch (_) {}
      try {
        _addHabitBreadcrumb && _addHabitBreadcrumb('first-vow-commit', {
          selectedCount:        picked.length,
          createdCount:         created.length,
          restoredCount:        restored.length,
          skippedDuplicateCount: skippedDup,
          habitCount:           habits.length,
          activeCount:          getActiveHabitCount(),
        });
      } catch (_) {}

      if (created.length === 0 && restored.length === 0) {
        try { showHabitToast('Those vows are already in your list.'); } catch (_) {}
        // Still re-render the empty state so the CTA resets even if
        // every selection was already a duplicate (edge case).
        try { renderHabits({ skipSideEffects: true }); } catch (_) {}
        return;
      }

      // skipSideEffects matches the pack-add path — avoids the HealthKit
      // native-bridge cascade on freshly added habits.
      try { renderHabits({ skipSideEffects: true }); } catch (_) {}
      // v3 Phase 1z.282B — First-vow commit acknowledgment. On the
      // very first commit (storage key unset), surface the coach
      // modal in lieu of the toast. After-the-fact commits (e.g.
      // post-Reset re-entry) fall through to the toast as before.
      let _faCoachShown = false;
      try { _faCoachShown = showFirstVowCoachmark(); } catch (_) { _faCoachShown = false; }
      if (!_faCoachShown) {
        try {
          const msg = created.length === 1
            ? 'Vow added — ' + created[0]
            : created.length + ' vows added.';
          showHabitToast(msg);
        } catch (_) {}
      }
    } finally {
      _firstVowCommitting = false;
    }
  }

  function openLibrary() {
    // v3 Phase 1z.252B — Reset filter / search / selection state on every
    // open so re-entry starts clean. Carries over the prior session's
    // chip selection would be confusing.
    _libActiveChip = 'pop';
    _libQuery      = '';
    _libSelected.clear();
    _libCommitting = false;
    renderLibrary();
    document.getElementById('lib-overlay').classList.remove('hidden');
    document.getElementById('lib-sheet').classList.remove('hidden');
  }

  function closeLibrary() {
    document.getElementById('lib-overlay').classList.add('hidden');
    document.getElementById('lib-sheet').classList.add('hidden');
    // Drop selection state so a future open doesn't show stale picks.
    _libSelected.clear();
    _libCommitting = false;
  }

  // v3 Phase 1z.252B — Add Habits sheet redesign state (in-memory).
  // _libActiveChip: 'pop' | 'cat:<labelKey>' — which chip is selected.
  // _libQuery:      current search text (lowercased, trimmed).
  // _libSelected:   Set<defaultHabitIdx> awaiting commit.
  // _libCommitting: guard against rapid double-tap on the CTA.
  let _libActiveChip = 'pop';
  let _libQuery      = '';
  const _libSelected = new Set();
  let _libCommitting = false;

  // Chip key → existing OB_CATEGORIES label. Order matches the design.
  const LIB_CHIPS = [
    { key: 'pop',    label: 'Popular',         catLabel: null                                },
    { key: 'phys',   label: 'Physical',        catLabel: 'Physical Performance'              },
    { key: 'mental', label: 'Mental & Focus',  catLabel: 'Mental & Focus'                    },
    { key: 'nutr',   label: 'Nutrition',       catLabel: 'Nutrition'                         },
    { key: 'disc',   label: 'Discipline',      catLabel: 'Discipline & Productivity'         },
    { key: 'fin',    label: 'Financial',       catLabel: 'Financial & Growth'                },
    { key: 'learn',  label: 'Learning',        catLabel: 'Learning & Skills'                 },
    { key: 'well',   label: 'Wellbeing',       catLabel: 'Wellbeing & Relationships'         },
  ];

  // Curated POPULAR list — exact names that exist in DEFAULT_HABITS.
  // Filtered at render time to indices, so a name typo here just drops
  // the row (no crash). Order is the rendered order.
  const LIB_POPULAR_NAMES = [
    'Sleep before midnight',
    'Workout',
    'Cold shower',
    'Daily walk',
    'Meditate & Breathwork',
    'Get morning sunlight',
    'Hydrate',
    'Read',
    'Protein goal',
    'Mobility & Stretching',
    'Cardio workout',
  ];

  // W574 — Vertical Jump Program partition. Templates tagged
  // library:'jump_program' are visible/addable ONLY to users whose onboarding
  // goal is the jump program (hb_onboarding_goal, server-authoritative + mirrored
  // locally). Undefined library on every other habit = unrestricted (backward-
  // compatible; visible to all).
  function _jumpProgramUnlocked() {
    try { return localStorage.getItem('hb_onboarding_goal') === 'jump_program'; } catch (_) { return false; }
  }
  function _habitHiddenForGoal(h) {
    return !!(h && h.library === 'jump_program' && !_jumpProgramUnlocked());
  }

  function _libGetVisibleIndices(activeNames) {
    // Search overrides chip filter.
    if (_libQuery) {
      const q = _libQuery;
      const out = [];
      for (let i = 0; i < DEFAULT_HABITS.length; i++) {
        const h = DEFAULT_HABITS[i];
        if (!h || !h.name) continue;
        if (_habitHiddenForGoal(h)) continue;   // W574 — jump-library partition
        if (activeNames.has(h.name)) continue;
        if (h.name.toLowerCase().includes(q)) out.push(i);
      }
      return out;
    }
    // Popular: index lookup by exact name.
    if (_libActiveChip === 'pop') {
      const idxByName = {};
      for (let i = 0; i < DEFAULT_HABITS.length; i++) {
        if (DEFAULT_HABITS[i] && DEFAULT_HABITS[i].name) {
          idxByName[DEFAULT_HABITS[i].name] = i;
        }
      }
      const out = [];
      for (let i = 0; i < LIB_POPULAR_NAMES.length; i++) {
        const idx = idxByName[LIB_POPULAR_NAMES[i]];
        if (typeof idx !== 'number') continue;
        if (_habitHiddenForGoal(DEFAULT_HABITS[idx])) continue;   // W576 — jump-library partition (defense-in-depth; matches search + category branches)
        if (activeNames.has(DEFAULT_HABITS[idx].name)) continue;
        out.push(idx);
      }
      return out;
    }
    // Category chip: walk OB_CATEGORIES slice.
    const chip = LIB_CHIPS.find(c => c.key === _libActiveChip);
    if (!chip || !chip.catLabel) return [];
    const cat = OB_CATEGORIES.find(c => c.label === chip.catLabel);
    if (!cat) return [];
    const out = [];
    for (let i = cat.start; i < cat.end; i++) {
      if (_habitHiddenForGoal(DEFAULT_HABITS[i])) continue;   // W574 — jump-library partition
      if (!activeNames.has(DEFAULT_HABITS[i].name)) out.push(i);
    }
    return out;
  }

  // Stat → text color for the row meta line.
  const LIB_STAT_COLOR = {
    STR:   '#ef4444',
    VIT:   '#34d399',
    INT:   '#3b82f6',
    FOCUS: '#eab308',
    WILL:  '#f97316',
    WLT:   '#f5b842',
  };

  // Resolve a habit's primaryStat (1z.247-era data) without throwing
  // if the field is missing on an older row.
  function _libHabitStat(h) {
    if (!h) return null;
    if (h.primaryStat) return h.primaryStat;
    if (typeof HABIT_PRIMARY_STAT === 'object' && HABIT_PRIMARY_STAT[h.name]) {
      return HABIT_PRIMARY_STAT[h.name];
    }
    return null;
  }

  function _libUpdateCta() {
    const cta = document.getElementById('lib-cta');
    if (!cta) return;
    const n = _libSelected.size;
    if (n === 0) {
      cta.disabled = true;
      cta.textContent = 'Select habits to add';
    } else {
      cta.disabled = false;
      cta.innerHTML = 'Add <span class="lib-cta-n">' + n + '</span> habit' +
        (n !== 1 ? 's' : '') + ' to my list';
    }
  }

  function _libCommitSelection() {
    if (_libCommitting) return;
    if (!_libSelected.size) return;
    _libCommitting = true;
    try {
      const picked = Array.from(_libSelected);
      // v3 Phase 1z.283 W176 — Active-only dedup. Names of archived
      // vows no longer block re-binding; the restore path below
      // un-archives the existing object (preserving streak history).
      const existingNames = new Set(habits.filter(_isActiveHabit).map(h => h && h.name));
      // v3 Phase 1z.280 — Active habit cap. Bulk add gate. Count the
      // effective add count AFTER dedup against ACTIVE names — picks
      // that match an already-active habit don't count. Picks that
      // match an ARCHIVED habit DO count (a restore consumes a slot,
      // because it becomes active again). The active-only set above
      // makes this distinction implicit.
      const effectiveAddCount = picked.reduce(function (sum, idx) {
        const built = _buildQuickPickHabitRow(idx);
        if (!built) return sum;
        return existingNames.has(built.def.name) ? sum : sum + 1;
      }, 0);
      if (effectiveAddCount > 0 && !canAddHabits(effectiveAddCount)) {
        try { showSystemFullModal({ context: 'library', attemptedCount: effectiveAddCount }); } catch (_) {}
        _libCommitting = false;
        return;
      }
      const created = [];
      const restored = []; // v3 Phase 1z.283 W176 — un-archived re-binds
      let skippedDup = 0;
      for (let i = 0; i < picked.length; i++) {
        const idx = picked[i];
        const built = _buildQuickPickHabitRow(idx);
        if (!built) continue;
        const { def, newH } = built;
        if (existingNames.has(def.name)) { skippedDup++; continue; }
        // v3 Phase 1z.283 W176 — Option B: re-add un-archives.
        const archivedMatch = _findArchivedHabitByName(def.name);
        if (archivedMatch) {
          archivedMatch.archived = false;
          existingNames.add(def.name);
          restored.push(def.name);
          continue;
        }
        habits.push(newH);
        if (def.note) habitNotes[newH.id] = def.note;
        existingNames.add(def.name);
        created.push(def.name);
      }
      _libSelected.clear();
      try { save(); } catch (_) {}
      try {
        _addHabitBreadcrumb && _addHabitBreadcrumb('add-habits-commit', {
          selectedCount:         picked.length,
          createdCount:          created.length,
          restoredCount:         restored.length,
          skippedDuplicateCount: skippedDup,
          habitCount:            habits.length,
          activeCount:           getActiveHabitCount(),
        });
      } catch (_) {}
      // skipSideEffects matches the pack-add path — no HealthKit cascade.
      try { renderHabits({ skipSideEffects: true }); } catch (_) {}
      try {
        // v3 Phase 1z.283 W176 — Toast prefers "restored" wording when
        // every effective addition was an un-archive. Mixed batches and
        // create-only batches keep the original "added" wording — the
        // user-visible outcome (it's in your active list now) is the
        // same, and adding more variants risks toast clutter.
        const effective = created.length + restored.length;
        let msg;
        if (effective === 0) {
          msg = 'Those vows are already in your list.';
        } else if (created.length === 0 && restored.length === 1) {
          msg = 'Vow restored — ' + restored[0];
        } else if (created.length === 0) {
          msg = restored.length + ' vows restored.';
        } else if (effective === 1) {
          msg = 'Vow added — ' + (created[0] || restored[0]);
        } else {
          msg = effective + ' vows added.';
        }
        showHabitToast(msg);
      } catch (_) {}
      closeLibrary();
    } finally {
      _libCommitting = false;
    }
  }

  function renderLibrary() {
    const sheet = document.getElementById('lib-sheet');
    const list  = document.getElementById('lib-list');
    if (!sheet || !list) return;
    // v3 Phase 1z.283 W176 — Active-only. Archived vows display as
    // available; tapping triggers un-archive in _libCommitSelection.
    const activeNames = new Set(habits.filter(_isActiveHabit).map(h => h.name));

    // ── Chips ────────────────────────────────────────────────
    const chipsEl = document.getElementById('lib-chips');
    if (chipsEl && !chipsEl.dataset.wired) {
      chipsEl.dataset.wired = '1';
      chipsEl.innerHTML = LIB_CHIPS.map(c =>
        '<button type="button" class="lib-chip" data-chip="' + c.key + '">' +
          esc(c.label) +
        '</button>'
      ).join('');
      chipsEl.addEventListener('click', (e) => {
        const btn = e.target && e.target.closest && e.target.closest('.lib-chip');
        if (!btn) return;
        _libActiveChip = btn.dataset.chip;
        _libQuery      = '';
        const si = document.getElementById('lib-search-input');
        if (si) si.value = '';
        try {
          _addHabitBreadcrumb && _addHabitBreadcrumb('add-habits-filter-change', {
            filterKey: _libActiveChip,
          });
        } catch (_) {}
        renderLibrary();
      });
    }
    if (chipsEl) {
      chipsEl.querySelectorAll('.lib-chip').forEach(btn => {
        btn.classList.toggle('is-on',
          btn.dataset.chip === _libActiveChip && !_libQuery);
      });
    }

    // ── Search ───────────────────────────────────────────────
    const searchEl = document.getElementById('lib-search-input');
    if (searchEl && !searchEl.dataset.wired) {
      searchEl.dataset.wired = '1';
      searchEl.addEventListener('input', () => {
        _libQuery = (searchEl.value || '').trim().toLowerCase();
        try {
          _addHabitBreadcrumb && _addHabitBreadcrumb('add-habits-search', {
            queryLength: _libQuery.length,
          });
        } catch (_) {}
        renderLibrary();
      });
    }

    // ── Start-fast strip (packs + Create Your Own) ──────────
    // Hidden on search or non-Popular chip — focus on the filtered list.
    const starter = document.getElementById('lib-starter');
    if (starter) {
      const showStarter = !_libQuery && _libActiveChip === 'pop';
      starter.style.display = showStarter ? 'block' : 'none';
    }
    const packsEl = document.getElementById('lib-packs');
    if (packsEl) {
      const mrMissing = getMissingMorningHabits().length;
      const liMissing = getMissingPackHabits('locked-in').length;
      packsEl.innerHTML =
        '<button type="button" class="lib-packcard lib-packcard--gold" id="lib-pack-morning">' +
          '<span class="lib-packcard-head">' +
            '<span class="lib-packcard-ic">' + packIconHtml('morning', { size: 22 }) + '</span>' +
            '<span class="lib-packcard-name">Morning Routine</span>' +
          '</span>' +
          '<span class="lib-packcard-count">' +
            (mrMissing === 0 ? 'All added' : mrMissing + ' habits') +
          '</span>' +
          '<span class="lib-packcard-desc">The 10-habit starter pack.</span>' +
        '</button>' +
        '<button type="button" class="lib-packcard lib-packcard--violet" id="lib-pack-lockedin">' +
          '<span class="lib-packcard-head">' +
            '<span class="lib-packcard-ic">' + packIconHtml('lockedin', { size: 22 }) + '</span>' +
            '<span class="lib-packcard-name">Locked-In</span>' +
          '</span>' +
          '<span class="lib-packcard-count">' +
            (liMissing === 0 ? 'All added' : liMissing + ' habits') +
          '</span>' +
          '<span class="lib-packcard-desc">The full discipline cycle.</span>' +
        '</button>';
      const mrBtn = document.getElementById('lib-pack-morning');
      const liBtn = document.getElementById('lib-pack-lockedin');
      if (mrBtn) mrBtn.addEventListener('click', () => {
        try { _addHabitBreadcrumb && _addHabitBreadcrumb('add-habits-pack-tap', { packId: 'morning' }); } catch (_) {}
        openMorningPackModal();
      });
      if (liBtn) liBtn.addEventListener('click', () => {
        try { _addHabitBreadcrumb && _addHabitBreadcrumb('add-habits-pack-tap', { packId: 'locked-in' }); } catch (_) {}
        openLockedInPackModal();
      });
    }
    const createRow = document.getElementById('lib-create-row');
    if (createRow) {
      const customCount = habits.filter(h => h.custom).length;
      const customsLeft = Math.max(0, MAX_CUSTOM_HABITS - customCount);
      createRow.classList.toggle('is-disabled', customsLeft === 0);
      createRow.innerHTML =
        '<span class="lib-create-ic">' + packIconHtml('custom', { size: 24 }) + '</span>' +
        '<span class="lib-create-body">' +
          '<span class="lib-create-name">Create your own</span>' +
          '<span class="lib-create-sub">' +
            (customsLeft === 0
              ? 'Cap reached (' + MAX_CUSTOM_HABITS + ' custom habits)'
              : 'Your habit, your stat · +3 XP') +
          '</span>' +
        '</span>' +
        '<span class="lib-create-left">' +
          (customsLeft === 0 ? 'Full' : customsLeft + ' left') +
        '</span>';
      createRow.onclick = customsLeft > 0 ? openCustomHabitModal : null;
    }

    // ── List of available habits ─────────────────────────────
    const items = _libGetVisibleIndices(activeNames);
    const listCount = document.getElementById('lib-listcount');
    if (listCount) {
      if (_libQuery) {
        listCount.textContent = items.length + ' result' +
          (items.length !== 1 ? 's' : '');
      } else {
        const chip = LIB_CHIPS.find(c => c.key === _libActiveChip);
        listCount.textContent = ((chip && chip.label) || 'Popular') +
          ' · ' + items.length;
      }
    }

    list.innerHTML = '';
    if (!items.length) {
      const empty = document.createElement('div');
      empty.className = 'lib-empty';
      empty.textContent = _libQuery
        ? 'No habits match “' + _libQuery + '”.'
        : 'All habits in this category are already in your list.';
      list.appendChild(empty);
      try {
        _addHabitBreadcrumb && _addHabitBreadcrumb('add-habits-sheet-render', {
          filterKey:    _libActiveChip,
          visibleCount: 0,
          queryLength:  _libQuery.length,
        });
      } catch (_) {}
      _libUpdateCta();
      _wireLibFooter();
      return;
    }

    const frag = document.createDocumentFragment();
    items.forEach(idx => {
      const h = DEFAULT_HABITS[idx];
      if (!h) return;
      const diff   = h.difficulty || 'medium';
      const xp     = (DIFFICULTY[diff] && DIFFICULTY[diff].pts) || 0;
      const stat   = _libHabitStat(h);
      const statCl = (stat && LIB_STAT_COLOR[stat]) ? LIB_STAT_COLOR[stat] : '#a78bfa';
      const isSel  = _libSelected.has(idx);
      const row = document.createElement('button');
      row.type      = 'button';
      row.className = 'lib-row' + (isSel ? ' is-selected' : '');
      row.dataset.idx = String(idx);
      row.setAttribute('aria-pressed', isSel ? 'true' : 'false');
      row.innerHTML =
        '<span class="lib-row-ic">' + habitIconHtml(h, { size: 26, eager: false }) + '</span>' +
        '<span class="lib-row-mid">' +
          '<span class="lib-row-name">' + esc(h.name) + '</span>' +
          '<span class="lib-row-meta">' +
            '<span class="lib-row-dpill lib-row-dpill--' + diff + '">' +
              ((DIFFICULTY[diff] && DIFFICULTY[diff].label) || diff) +
            '</span>' +
            (stat
              ? '<span class="lib-row-xp"><span class="lib-row-stat" style="color:' + statCl + '">' +
                  stat + '</span> · +' + xp + ' XP</span>'
              : '<span class="lib-row-xp">+' + xp + ' XP</span>'
            ) +
          '</span>' +
        '</span>' +
        '<span class="lib-row-add" aria-hidden="true">' + (isSel ? '✓' : '+') + '</span>';
      frag.appendChild(row);
    });
    list.appendChild(frag);

    // Single delegated handler — tapping anywhere on the row toggles.
    if (!list.dataset.wired) {
      list.dataset.wired = '1';
      list.addEventListener('click', (e) => {
        const row = e.target && e.target.closest && e.target.closest('.lib-row');
        if (!row) return;
        const idx = parseInt(row.dataset.idx, 10);
        if (isNaN(idx)) return;
        if (_libSelected.has(idx)) {
          _libSelected.delete(idx);
          row.classList.remove('is-selected');
          row.setAttribute('aria-pressed', 'false');
          const add = row.querySelector('.lib-row-add');
          if (add) add.textContent = '+';
        } else {
          _libSelected.add(idx);
          row.classList.add('is-selected');
          row.setAttribute('aria-pressed', 'true');
          const add = row.querySelector('.lib-row-add');
          if (add) add.textContent = '✓';
        }
        try {
          _addHabitBreadcrumb && _addHabitBreadcrumb('add-habits-add-tap', {
            idx, selectedCount: _libSelected.size,
          });
        } catch (_) {}
        _libUpdateCta();
      });
    }

    _libUpdateCta();
    _wireLibFooter();

    try {
      _addHabitBreadcrumb && _addHabitBreadcrumb('add-habits-sheet-render', {
        filterKey:    _libActiveChip,
        visibleCount: items.length,
        queryLength:  _libQuery.length,
      });
    } catch (_) {}
  }

  function _wireLibFooter() {
    const cta = document.getElementById('lib-cta');
    if (cta && !cta.dataset.wired) {
      cta.dataset.wired = '1';
      cta.addEventListener('click', () => {
        if (cta.disabled) return;
        _libCommitSelection();
      });
    }
  }
  // v3 Phase 1z.252B — Legacy renderLibrary() body (pack-entry cards,
  // 7-accordion category list, per-row openHabitDetail confirm flow)
  // removed here. The new compact sheet above (search + chips +
  // start-fast strip + one-tap multi-select rows + sticky CTA) owns
  // this surface entirely. openHabitDetail() remains callable from
  // other surfaces (Habits tab card menu edit pencil).

  // v3 Phase 1z.88 — canonical "is this preset already in the user's habits"
  // check. Name-based because preset habit identity is the display name
  // (custom-built habits set .custom and are excluded). Used by both
  // openHabitDetail render-time and the addBtn click-time defensive guard
  // so the two paths cannot disagree. Lives in the IIFE so it closes over
  // the `habits` array reference.
  function isHabitAlreadyAdded(h) {
    if (!h || !h.name) return false;
    // v3 Phase 1z.283 W177 — Active-only. Archived built-ins must
    // surface as re-addable here; the downstream add path
    // (addHabitFromStatSheet / library) routes through the un-archive
    // restore branch.
    try { return habits.some(a => _isActiveHabit(a) && !a.custom && a.name === h.name); }
    catch (_) { return false; }
  }

  // v3 Phase 1z.96 — persistent breadcrumb ring for the notification
  // permission auto-recovery path. Mirror of _addHabitBreadcrumb but
  // for a separate localStorage key so the two diagnostic surfaces
  // don't collide. Cap 40 entries (lower than habits since notif
  // events are rarer). Included in the Copy Debug Info export below.
  function _addNotifBreadcrumb(step, data) {
    try {
      const key = 'hb_notif_debug_v1';
      let existing;
      try { existing = JSON.parse(localStorage.getItem(key) || '[]'); }
      catch (_) { existing = []; }
      if (!Array.isArray(existing)) existing = [];
      const entry = { t: Date.now(), step: String(step) };
      if (data !== undefined && data !== null) {
        try { entry.data = JSON.parse(JSON.stringify(data)); } catch (_) {}
      }
      existing.push(entry);
      if (existing.length > 40) existing.splice(0, existing.length - 40);
      try { localStorage.setItem(key, JSON.stringify(existing)); } catch (_) {}
    } catch (_) {}
    try { console.log('[notif-debug]', step, data || ''); } catch (_) {}
  }

  // v3 Phase 1z.104 — persistent breadcrumb ring for HealthKit auto-
  // verification (Daily walk / Sleep / Strength training). Mirror of
  // _addNotifBreadcrumb. User reported their Strength training and
  // Daily walk habits weren't auto-checking despite Apple Health
  // showing qualifying data. Static audit couldn't distinguish between:
  //   (a) workout type classification mismatch (Health says "Workouts
  //       3h 12min" but the underlying workoutActivityName/Id isn't one
  //       of our STRENGTH_KEYWORDS_NORM allowlist)
  //   (b) auto-verify trigger not firing at all
  //   (c) cache staleness
  //   (d) per-habit gates (wasUncheckedToday, isChecked, etc.)
  //
  // The existing _hkDebug() console log requires
  //   localStorage.hb_debug_healthkit === '1'
  // AND console access — which is unreadable on App Store-signed
  // TestFlight builds. This breadcrumb ring surfaces the same
  // diagnostic via Copy Debug Info → payload.healthVerify.debug.
  //
  // Cap 60 entries (per-render fires multiple breadcrumbs).
  // W660 — cached debug flag: the per-call console.log on the two breadcrumb
  // writers (~160 call sites, several on hot boot/render paths) is pure overhead
  // in production (no console reads it on iOS). Read the flag ONCE.
  let _bcDebug = null;
  function _bcDebugOn() {
    if (_bcDebug === null) { try { _bcDebug = (localStorage.getItem('hb_debug') === '1'); } catch (_) { _bcDebug = false; } }
    return _bcDebug === true;
  }
  // W660 — in-memory ring so the per-call getItem+JSON.parse is paid ONCE per
  // session (lazy load), not on every call. The setItem persist stays (Copy Debug
  // Info + the smoke E2E read the localStorage key) and cross-session history is
  // preserved via the lazy load — zero behavior change to the persisted payload.
  let _hkVerifyRing = null;
  function _addHealthVerifyBreadcrumb(step, data) {
    try {
      const key = 'hb_health_verify_debug_v1';
      if (_hkVerifyRing === null) {
        try { _hkVerifyRing = JSON.parse(localStorage.getItem(key) || '[]'); } catch (_) { _hkVerifyRing = []; }
        if (!Array.isArray(_hkVerifyRing)) _hkVerifyRing = [];
      }
      const entry = { t: Date.now(), step: String(step) };
      if (data !== undefined && data !== null) {
        try { entry.data = JSON.parse(JSON.stringify(data)); } catch (_) {}
      }
      _hkVerifyRing.push(entry);
      if (_hkVerifyRing.length > 60) _hkVerifyRing.splice(0, _hkVerifyRing.length - 60);
      try { localStorage.setItem(key, JSON.stringify(_hkVerifyRing)); } catch (_) {}
    } catch (_) {}
    if (_bcDebugOn()) { try { console.log('[hk-verify-debug]', step, data || ''); } catch (_) {} }
  }

  // v3 Phase 1z.96 — notification permission auto-recovery.
  //
  // Problem: iOS can silently drop an app's notification permission
  // entry (multiple TestFlight reinstalls in one day, iOS updates,
  // user clearing system caches, etc.). When this happens:
  //   - The app's localStorage still has hb_notif_perm_requested='1'
  //     (we previously asked the user, they tapped Allow).
  //   - iOS no longer lists the app in Settings → Notifications.
  //   - Calling LocalNotifications.schedule() silently no-ops.
  //   - User sees no notifications and has no recovery path inside
  //     the app (the onboarding-time permission prompt is the only
  //     re-prompt site, and it's gated by hb_notif_perm_requested='1').
  //
  // Fix: on every app launch, compare the in-app "we previously
  // requested" flag against the current iOS permission status. If
  // they mismatch (we asked previously but iOS now reports prompt /
  // undetermined), iOS silently dropped our entry. Re-request once.
  // iOS will:
  //   - Show its native dialog if the entry was truly wiped → user
  //     taps Allow → state recovered.
  //   - Return the prior decision without prompting if iOS still
  //     remembers it (no UI shown — silent no-op for the user).
  // Either way, no repeated prompts, App Review compliant.
  //
  // After a successful recovery (status returns to 'granted'), all
  // existing schedules are re-armed so notifications resume the same
  // day instead of waiting for the next habit toggle / tab switch.
  async function recoverNotifPermissionIfDropped() {
    _addNotifBreadcrumb('recover-start', {
      build: (typeof APP_BUILD_TAG !== 'undefined') ? APP_BUILD_TAG : null,
    });
    try {
      // Bail if Notif module isn't available (very early boot edge case).
      if (typeof Notif !== 'object' || !Notif || typeof Notif.checkPermission !== 'function') {
        _addNotifBreadcrumb('recover-skip-no-notif-module');
        return;
      }
      // Bail on non-native (web). Web Notifications API has its own
      // flow and doesn't suffer this iOS-specific issue.
      let isNative = false;
      try { isNative = !!(window.Capacitor && window.Capacitor.isNativePlatform && window.Capacitor.isNativePlatform()); } catch (_) {}
      if (!isNative) {
        _addNotifBreadcrumb('recover-skip-not-native');
        return;
      }
      // Bail if we've never requested permission before. The onboarding
      // flow will handle the first-time prompt for new users.
      let askedBefore = false;
      try { askedBefore = localStorage.getItem('hb_notif_perm_requested') === '1'; } catch (_) {}
      if (!askedBefore) {
        _addNotifBreadcrumb('recover-skip-onboarding-will-handle');
        return;
      }
      // Read current iOS permission status.
      let status = 'unknown';
      try { status = await Notif.checkPermission(); } catch (err) {
        _addNotifBreadcrumb('recover-checkPermission-threw', { err: String(err && err.message || err) });
        return;
      }
      _addNotifBreadcrumb('recover-status-read', { status });
      // If iOS already says granted, we're fine. No action needed.
      if (status === 'granted') {
        _addNotifBreadcrumb('recover-already-granted-noop');
        return;
      }
      // If iOS reports 'denied' (user previously declined OR iOS has
      // explicitly disabled), don't auto-prompt — iOS won't show the
      // dialog anyway, and a sticky toast directing to Settings is
      // more user-friendly than a silent no-op.
      if (status === 'denied') {
        _addNotifBreadcrumb('recover-denied-show-toast');
        try {
          if (typeof showHabitToast === 'function') {
            showHabitToast(
              'Reminders are off. Enable in iOS Settings → Awakened to receive them.',
              { duration: 3500 }   // W516 — was sticky:true (never cleared, trailed across all tabs on native)
            );
          }
        } catch (_) {}
        return;
      }
      // status === 'prompt' or 'unsupported' or 'unknown' — this is
      // the state mismatch we recover from. iOS thinks we haven't
      // asked (or doesn't remember the prior grant). Re-request.
      // App Review safe: this is exactly the same call as the
      // onboarding prompt, gated to fire at most once per launch.
      _addNotifBreadcrumb('recover-mismatch-re-requesting', { status });
      let result = 'unknown';
      try { result = await Notif.requestPermission(); } catch (err) {
        _addNotifBreadcrumb('recover-requestPermission-threw', { err: String(err && err.message || err) });
        return;
      }
      _addNotifBreadcrumb('recover-request-result', { result });
      // Re-arm all schedules so notifications resume immediately.
      if (result === 'granted') {
        try {
          if (typeof Notif.rescheduleAll === 'function') { await Notif.rescheduleAll(habits, today, completions[today] || []); }
          if (typeof Notif.reapplyDigest === 'function') { await Notif.reapplyDigest(); }
          if (typeof Notif.reapplyCheckin === 'function') { await Notif.reapplyCheckin(); }
          if (typeof Notif.reapplyMidDay === 'function') { await Notif.reapplyMidDay(); }
          _addNotifBreadcrumb('recover-reschedule-ok');
        } catch (err) {
          _addNotifBreadcrumb('recover-reschedule-threw', { err: String(err && err.message || err) });
        }
      }
      _addNotifBreadcrumb('recover-complete', { finalStatus: result });
    } catch (err) {
      _addNotifBreadcrumb('recover-outer-threw', { err: String(err && err.message || err) });
    }
  }

  // v3 Phase 1z.91 — persistent breadcrumb for the Add Habits add path.
  // The freeze repros on iOS Capacitor only and the app has to be
  // force-killed to recover, which destroys the console log buffer.
  // We persist a tiny ring of breadcrumbs to localStorage so that after
  // force-quit + relaunch we can inspect `hb_add_habit_debug_v1` and
  // see EXACTLY which step the previous freeze stopped at.
  //
  // Ring is capped at 80 entries to bound localStorage growth. Each
  // entry is { t, step, data? } — `t` is ms since epoch, `step` is a
  // short identifier (e.g. 'tap-start', 'after-save'), `data` is an
  // optional small JSON-safe payload (no DOM nodes, no huge objects).
  //
  // EVERY call is independently try-wrapped so a localStorage failure
  // (quota, private mode, disabled) can never break the add path.
  let _addHabitRing = null;   // W660 — in-memory ring (see _addHealthVerifyBreadcrumb)
  function _addHabitBreadcrumb(step, data) {
    try {
      const key = 'hb_add_habit_debug_v1';
      if (_addHabitRing === null) {
        try { _addHabitRing = JSON.parse(localStorage.getItem(key) || '[]'); } catch (_) { _addHabitRing = []; }
        if (!Array.isArray(_addHabitRing)) _addHabitRing = [];
      }
      const entry = { t: Date.now(), step: String(step) };
      if (data !== undefined && data !== null) {
        try { entry.data = JSON.parse(JSON.stringify(data)); } catch (_) {}
      }
      _addHabitRing.push(entry);
      if (_addHabitRing.length > 80) _addHabitRing.splice(0, _addHabitRing.length - 80);
      try { localStorage.setItem(key, JSON.stringify(_addHabitRing)); } catch (_) {}
    } catch (_) {}
    if (_bcDebugOn()) { try { console.log('[add-habit-debug]', step, data || ''); } catch (_) {} }
  }

  // v3 Phase 1z.92 — in-app debug-info export. Safari Web Inspector
  // does NOT show the Awakened TestFlight build under the iPhone's
  // Develop menu (Capacitor WKWebView's Web Inspector flag is off in
  // App Store-signed IPAs by Apple policy), so the 1z.91 breadcrumbs
  // in localStorage have no way to leave the device. This module
  // gives the user a hidden "Copy Debug Info" button in Settings —
  // tap the version line 5 times within 3 seconds to reveal it.
  //
  // Payload assembled here is local-only — no network transmission,
  // no PII outside what's already in localStorage. Copy-only. The
  // user pastes the result into chat for diagnosis.
  function _buildAwakenedDebugPayload() {
    const payload = {
      kind: 'awakened-debug',
      schema: 1,
    };
    // ── Build / runtime identity ─────────────────────────────
    try { payload.version    = (typeof APP_VERSION    !== 'undefined') ? APP_VERSION    : null; } catch (_) { payload.version = null; }
    try { payload.build      = (typeof APP_BUILD_TAG  !== 'undefined') ? APP_BUILD_TAG  : null; } catch (_) { payload.build   = null; }
    try { payload.createdAt  = new Date().toISOString(); } catch (_) {}
    try { payload.href       = location.href; } catch (_) {}
    try { payload.userAgent  = navigator.userAgent; } catch (_) {}
    try { payload.isCapacitor = !!(window.Capacitor && window.Capacitor.isNativePlatform && window.Capacitor.isNativePlatform()); } catch (_) {}
    try { payload.platform   = (window.Capacitor && window.Capacitor.getPlatform && window.Capacitor.getPlatform()) || null; } catch (_) {}

    // ── W246 — battle audio state (the music-silent diagnostic) ──
    try {
      payload.audio = {
        ctx: _AUD.ctx ? _AUD.ctx.state : 'not-created',
        soundEnabled: !!soundEnabled,
        musicOn: _audMusicOn(), musicVol: _audMusicVol(), sfxVol: _audSfxVol(),
        slots: _AUD.status, lastPlay: _AUD.lastPlay, playingNow: !!_AUD.musicSrc,
      };
    } catch (err) { payload.audioErr = String(err && err.message || err); }

    // ── Add Habits breadcrumbs (the main diagnostic) ─────────
    try {
      const raw = localStorage.getItem('hb_add_habit_debug_v1');
      if (raw) {
        try { payload.addHabitDebug = JSON.parse(raw); }
        catch (parseErr) {
          payload.addHabitDebugRaw = raw.slice(0, 4000);
          payload.addHabitDebugParseErr = String(parseErr && parseErr.message || parseErr);
        }
      } else {
        payload.addHabitDebug = [];
      }
    } catch (err) {
      payload.addHabitDebugErr = String(err && err.message || err);
    }

    // ── Current UI state ─────────────────────────────────────
    payload.uiState = {};
    try {
      const sheetIds = ['hd-sheet', 'lib-sheet', 'lib-overlay', 'modal-overlay', 'edit-modal', 'mr-overlay'];
      payload.uiState.sheets = sheetIds.map(id => {
        const el = document.getElementById(id);
        if (!el) return { id, exists: false };
        const cs = (() => { try { return getComputedStyle(el); } catch (_) { return null; } })();
        return {
          id,
          exists: true,
          hasHiddenClass: el.classList.contains('hidden'),
          inlineDisplay: el.style.display || null,
          inlinePointerEvents: el.style.pointerEvents || null,
          inlineTransform: el.style.transform || null,
          inlineTransition: el.style.transition || null,
          inlineOpacity: el.style.opacity || null,
          computedDisplay: cs ? cs.display : null,
          computedPointerEvents: cs ? cs.pointerEvents : null,
          className: el.className || '',
        };
      });
    } catch (_) {}
    try {
      const activeTab = document.querySelector('.tab-btn.active');
      payload.uiState.activeTab = activeTab ? activeTab.id : null;
    } catch (_) {}
    try {
      payload.uiState.bodyClass = (document.body && document.body.className) || '';
    } catch (_) {}
    try {
      const ae = document.activeElement;
      payload.uiState.activeElement = ae ? ((ae.id ? ('#' + ae.id) : '') + (ae.className ? ('.' + String(ae.className).split(' ').join('.')) : '')) : null;
    } catch (_) {}

    // ── Habit summary (no PII beyond what user typed as habit names) ─
    payload.habitSummary = {};
    try {
      if (Array.isArray(habits)) {
        payload.habitSummary.count = habits.length;
        payload.habitSummary.lastFew = habits.slice(-5).map(h => ({ name: h && h.name, type: h && h.type, custom: !!(h && h.custom) }));
      }
    } catch (_) {}

    // ── Storage / SW hints ───────────────────────────────────
    try {
      payload.swController = !!(navigator.serviceWorker && navigator.serviceWorker.controller);
    } catch (_) {}
    try {
      payload.knownSwVersion = localStorage.getItem('hb_sw_known_version') || null;
    } catch (_) {}

    // ── 1z.96 — notification state + breadcrumbs ─────────────
    payload.notif = {};
    try {
      payload.notif.permAskedBefore = localStorage.getItem('hb_notif_perm_requested') === '1';
    } catch (_) {}
    try {
      payload.notif.disabled = localStorage.getItem('hb_notif_disabled') === '1';
    } catch (_) {}
    try {
      const pausedUntil = parseInt(localStorage.getItem('hb_notif_paused_until') || '0', 10);
      payload.notif.pausedUntil = pausedUntil;
      payload.notif.currentlyPaused = pausedUntil > Date.now();
    } catch (_) {}
    try {
      payload.notif.dailyDigestTime = localStorage.getItem('hb_notif_daily_digest_time') || null;
    } catch (_) {}
    try {
      const raw = localStorage.getItem('hb_notif_debug_v1');
      if (raw) {
        try { payload.notif.debug = JSON.parse(raw); }
        catch (_) { payload.notif.debugRaw = raw.slice(0, 4000); }
      } else {
        payload.notif.debug = [];
      }
    } catch (_) {}

    // v3 Phase 1z.279 — Duels permanently retired; the
    // `hb_duels_debug_v1` breadcrumb store is no longer written.

    // ── 1z.104 — HealthKit auto-verify breadcrumbs ───────────
    // Surfaces the per-call breadcrumb trail for autoVerifyWalk /
    // autoVerifySleep / autoVerifyStrengthTraining. Lets us diagnose
    // why a habit didn't seal despite Apple Health showing qualifying
    // data — without needing Safari Web Inspector (which is disabled
    // on App Store-signed TestFlight builds).
    payload.healthVerify = {};
    try {
      const raw = localStorage.getItem('hb_health_verify_debug_v1');
      if (raw) {
        try { payload.healthVerify.debug = JSON.parse(raw); }
        catch (_) { payload.healthVerify.debugRaw = raw.slice(0, 4000); }
      } else {
        payload.healthVerify.debug = [];
      }
    } catch (_) {}

    return payload;
  }

  // Async copy with progressive fallbacks. Returns a Promise<boolean>
  // indicating success. Independent of toast/modal — caller handles UX.
  function _copyTextToClipboard(text) {
    return new Promise(resolve => {
      // Path 1 — modern Clipboard API.
      try {
        if (navigator.clipboard && navigator.clipboard.writeText) {
          navigator.clipboard.writeText(text)
            .then(() => resolve(true))
            .catch(() => { _legacyCopyFallback(text, resolve); });
          return;
        }
      } catch (_) {}
      // Path 2 — legacy textarea + execCommand.
      _legacyCopyFallback(text, resolve);
    });
  }
  function _legacyCopyFallback(text, resolve) {
    try {
      const ta = document.createElement('textarea');
      ta.value = text;
      ta.setAttribute('readonly', '');
      ta.style.position = 'fixed';
      ta.style.top = '-9999px';
      ta.style.left = '0';
      ta.style.opacity = '0';
      document.body.appendChild(ta);
      ta.select();
      ta.setSelectionRange(0, text.length);
      let ok = false;
      try { ok = document.execCommand && document.execCommand('copy'); } catch (_) {}
      try { document.body.removeChild(ta); } catch (_) {}
      resolve(!!ok);
    } catch (_) {
      resolve(false);
    }
  }

  // Fallback modal when clipboard fails — user can manually select +
  // copy from a textarea. Created dynamically so no index.html change
  // is needed. Tap backdrop or Close to dismiss.
  function _showDebugTextFallback(text) {
    try {
      // Remove any prior instance.
      const prior = document.getElementById('awk-debug-fallback');
      if (prior) try { prior.parentNode.removeChild(prior); } catch (_) {}
      const overlay = document.createElement('div');
      overlay.id = 'awk-debug-fallback';
      overlay.style.cssText = [
        'position:fixed','inset:0','z-index:99999','background:rgba(0,0,0,0.82)',
        'display:flex','flex-direction:column','align-items:stretch','justify-content:flex-start',
        'padding:env(safe-area-inset-top,16px) 12px env(safe-area-inset-bottom,16px) 12px',
        'box-sizing:border-box',
      ].join(';');
      const card = document.createElement('div');
      card.style.cssText = [
        'background:#15151f','color:#e2e8f0','border:1px solid rgba(245,158,11,0.4)',
        'border-radius:14px','padding:14px','display:flex','flex-direction:column','gap:10px',
        'flex:1','min-height:0',
      ].join(';');
      const title = document.createElement('div');
      title.textContent = 'Debug Info — long-press inside to Select All, then Copy';
      title.style.cssText = 'font-size:0.86rem;font-weight:700;color:#f5b842;';
      const ta = document.createElement('textarea');
      ta.value = text;
      ta.setAttribute('readonly', '');
      ta.style.cssText = [
        'flex:1','min-height:0','width:100%','box-sizing:border-box',
        'font-family:ui-monospace,SFMono-Regular,Menlo,monospace','font-size:0.74rem',
        'background:#0a0a12','color:#cbd5e1','border:1px solid rgba(255,255,255,0.1)',
        'border-radius:8px','padding:10px','resize:none','-webkit-user-select:text','user-select:text',
      ].join(';');
      const row = document.createElement('div');
      row.style.cssText = 'display:flex;gap:8px;';
      const selectAllBtn = document.createElement('button');
      selectAllBtn.textContent = 'Select All';
      selectAllBtn.style.cssText = 'flex:1;padding:12px;border-radius:10px;background:#8b5cf6;color:#fff;font-weight:700;border:none;font-size:0.92rem;';
      selectAllBtn.addEventListener('click', () => {
        try { ta.focus(); ta.select(); ta.setSelectionRange(0, ta.value.length); } catch (_) {}
      });
      const closeBtn = document.createElement('button');
      closeBtn.textContent = 'Close';
      closeBtn.style.cssText = 'flex:1;padding:12px;border-radius:10px;background:#1f1f2e;color:#e2e8f0;font-weight:700;border:1px solid rgba(255,255,255,0.18);font-size:0.92rem;';
      closeBtn.addEventListener('click', () => { try { overlay.parentNode.removeChild(overlay); } catch (_) {} });
      row.appendChild(selectAllBtn);
      row.appendChild(closeBtn);
      card.appendChild(title);
      card.appendChild(ta);
      card.appendChild(row);
      overlay.appendChild(card);
      // Tap backdrop (NOT the card) to dismiss.
      overlay.addEventListener('click', e => {
        if (e.target === overlay) { try { overlay.parentNode.removeChild(overlay); } catch (_) {} }
      });
      document.body.appendChild(overlay);
    } catch (err) {
      try { console.error('[debug-export] fallback modal failed', err); } catch (_) {}
    }
  }

  // The actual export action — assembles payload, attempts copy,
  // falls back to the modal on failure. Always safe to call (never
  // throws past its own try block).
  function _exportAwakenedDebugInfo() {
    let text;
    try {
      const payload = _buildAwakenedDebugPayload();
      text = JSON.stringify(payload, null, 2);
    } catch (err) {
      try {
        if (typeof showHabitToast === 'function') showHabitToast('Could not build debug info.');
      } catch (_) {}
      try { console.error('[debug-export] build failed', err); } catch (_) {}
      return;
    }
    _copyTextToClipboard(text).then(ok => {
      if (ok) {
        try {
          if (typeof showHabitToast === 'function') showHabitToast('Debug info copied — paste it in chat.');
        } catch (_) {}
      } else {
        // Clipboard failed — show selectable textarea as fallback.
        try { _showDebugTextFallback(text); } catch (_) {}
      }
    });
  }

  // 5-tap unlock on the Settings version line. Hides debug surface
  // entirely from normal users; only reveals after the gesture. Once
  // unlocked, the button stays visible for the lifetime of the sheet
  // (re-opening Settings hides it again).
  function _setupDebugInfoUnlock() {
    const verEl = document.getElementById('settings-app-ver');
    if (!verEl) return;
    // Avoid double-binding if init runs more than once.
    if (verEl.dataset.debugUnlockWired === '1') return;
    verEl.dataset.debugUnlockWired = '1';
    // Visual affordance: pointer cursor on web; harmless on iOS.
    try { verEl.style.cursor = 'pointer'; } catch (_) {}
    let taps = 0;
    let firstTapAt = 0;
    verEl.addEventListener('click', () => {
      const now = Date.now();
      if (now - firstTapAt > 3000) { taps = 0; firstTapAt = now; }
      taps += 1;
      if (taps >= 5) {
        taps = 0; firstTapAt = 0;
        try { _revealDebugInfoButton(); } catch (_) {}
        try {
          if (typeof showHabitToast === 'function') showHabitToast('Diagnostics unlocked.');
        } catch (_) {}
      }
    });
  }

  // Inserts the Copy Debug Info button into the Settings sheet (right
  // below the version line) if not already present. Idempotent.
  function _revealDebugInfoButton() {
    if (document.getElementById('awk-debug-copy-btn')) return;
    const verEl = document.getElementById('settings-app-ver');
    if (!verEl || !verEl.parentNode) return;
    const wrap = document.createElement('div');
    wrap.id = 'awk-debug-row';
    wrap.style.cssText = 'margin-top:8px;display:flex;flex-direction:column;gap:6px;';
    const btn = document.createElement('button');
    btn.id = 'awk-debug-copy-btn';
    btn.type = 'button';
    btn.textContent = 'Copy Debug Info';
    btn.style.cssText = [
      'padding:10px 14px','border-radius:10px',
      'background:rgba(245,158,11,0.14)','color:#f5b842',
      'border:1px solid rgba(245,158,11,0.45)','font-weight:700',
      'font-size:0.86rem','cursor:pointer',
    ].join(';');
    btn.addEventListener('click', () => {
      try { _exportAwakenedDebugInfo(); } catch (_) {}
    });
    const hint = document.createElement('div');
    hint.textContent = 'Local-only diagnostic snapshot. Paste in chat to help debug.';
    hint.style.cssText = 'font-size:0.72rem;color:#94a3b8;line-height:1.3;';
    wrap.appendChild(btn);
    wrap.appendChild(hint);

    // v3 Phase 1z.237 — The 1z.234 "Reset to Fresh User" debug button
    // was removed after on-device QA confirmed it didn't reliably
    // trigger the cinematic onboarding on reload (cloud-sync state
    // re-populated localStorage before enterFirstRunFlow ran). The
    // standard two-step "Reset all progress" button in Settings does
    // route to the cinematic correctly and is the canonical QA path.

    try { verEl.parentNode.insertBefore(wrap, verEl.nextSibling); } catch (_) {}
  }

  // v3 Phase 1z.89 — deterministic interaction reset for the Add Habits
  // surface. After a successful preset add we close BOTH the detail
  // sheet (#hd-sheet) AND the parent library sheet (#lib-sheet) and
  // return the user to the Habits tab. The freeze user-reported on
  // TestFlight 2.2.2-w3 was the PARENT sheet stranding after the
  // child detail closed — most likely culprit was residual inline
  // transform / transition / opacity left on #lib-sheet by the swipe-
  // dismiss gesture handler (attachSheetDismissGesture in setupLibrary)
  // when the transitionend listener never fired through iOS WebView
  // DOM-thrash during renderLibrary. This helper hard-resets the
  // entire surface so no path can leave a sheet in a non-interactive
  // half-state. Each DOM op is independently try-wrapped so a missing
  // node can't break the chain.
  function resetAddHabitsInteractionState() {
    const ids = ['hd-sheet', 'lib-sheet', 'lib-overlay'];
    ids.forEach(id => {
      try {
        const el = document.getElementById(id);
        if (!el) return;
        // Hidden via class first; closeHabitDetail/closeLibrary already
        // do this but we re-apply belt-and-braces.
        try { el.classList.add('hidden'); } catch (_) {}
        // Clear any inline overrides the gesture handler may have left.
        // These survive across the next openLibrary() if not cleared,
        // because openLibrary only toggles .hidden — it never touches
        // inline transform/transition/opacity/pointer-events.
        try { el.style.removeProperty('transform'); } catch (_) {}
        try { el.style.removeProperty('transition'); } catch (_) {}
        try { el.style.removeProperty('opacity'); } catch (_) {}
        try { el.style.removeProperty('pointer-events'); } catch (_) {}
        // hd-sheet uses inline display:none !important (1z.88 belt-and-
        // braces) — preserve that for #hd-sheet, clear it for the others.
        if (id !== 'hd-sheet') {
          try { el.style.removeProperty('display'); } catch (_) {}
        }
      } catch (_) {}
    });
    // Clear lib content innerHTML lazily — renderLibrary will rebuild
    // it on the next openLibrary() call. We intentionally do NOT clear
    // it here because renderLibrary() runs on the deferred tick AFTER
    // this helper, and we want the rebuilt list to be ready for the
    // next open.
  }

  // v3 Phase 1z.91 — single deterministic close path for the Add Habits
  // stack. Bundles closeHabitDetail + closeLibrary +
  // resetAddHabitsInteractionState into one call with a reason string
  // so breadcrumbs identify the source. Each underlying call is wrapped
  // independently — a missing node / thrown DOM op cannot strand the
  // user. Safe to call any number of times (idempotent).
  //
  // Used by:
  //   - the success path inside addBtn click
  //   - the duplicate tap guard
  //   - the outer-catch on any unexpected throw
  //   - the post-add watchdog (~500ms after add) as belt-and-braces
  function forceCloseAddHabitsStack(reason) {
    _addHabitBreadcrumb('forceClose-start', { reason: reason || 'unspecified' });
    try { closeHabitDetail(); } catch (_) {}
    try { closeLibrary(); } catch (_) {}
    try { resetAddHabitsInteractionState(); } catch (_) {}
    // Belt-and-braces — even after the above, a stray pointer-events
    // on the body or the overlay roots could still intercept taps.
    // Walk the known Add Habits roots one more time and force interactive.
    try {
      const overlay = document.getElementById('lib-overlay');
      if (overlay) {
        try { overlay.classList.add('hidden'); } catch (_) {}
        try { overlay.style.removeProperty('pointer-events'); } catch (_) {}
        try { overlay.style.removeProperty('opacity'); } catch (_) {}
      }
    } catch (_) {}
    _addHabitBreadcrumb('forceClose-complete', { reason: reason || 'unspecified' });
  }

  // v3 Phase 1z.91 — post-add interactive guard. Confirms the Habits
  // tab is active and the bottom tab bar is responsive. If a stale
  // overlay survived, log a breadcrumb so the next freeze repro tells
  // us exactly which element is intercepting. NEVER throws.
  function ensureHabitsTabInteractive() {
    try {
      const tabBar = document.getElementById('bottom-tabs');
      const tabHabits = document.getElementById('tab-habits');
      _addHabitBreadcrumb('ensureInteractive', {
        tabBarVisible: !!(tabBar && !tabBar.classList.contains('hidden')),
        tabHabitsActive: !!(tabHabits && tabHabits.classList.contains('active')),
        bodyClass: (document.body && document.body.className) || '',
        libSheetHidden: !!(document.getElementById('lib-sheet') || {}).classList?.contains('hidden'),
        hdSheetHidden:  !!(document.getElementById('hd-sheet')  || {}).classList?.contains('hidden'),
        libOverlayHidden: !!(document.getElementById('lib-overlay') || {}).classList?.contains('hidden'),
      });
    } catch (_) {}
  }

  // ── HABIT DETAIL SCREEN ───────────────────────────────────
  // opts: { context, isSelected, existingConfig, onConfirm, onRemove }
  //   context       'library' (default) | 'onboarding'
  //   isSelected    onboarding only — true if habit already in obSelected
  //   existingConfig previously saved config to pre-populate fields
  //   onConfirm(cfg) called when user taps Add / Update
  //   onRemove()     onboarding only — called when user taps Remove
  function openHabitDetail(h, opts) {
    opts = opts || {};
    const isOnboarding = opts.context === 'onboarding';
    const isSelected   = isOnboarding && (opts.isSelected || false);
    const alreadyAdded = !isOnboarding && isHabitAlreadyAdded(h);
    const measurable   = MEASURABLE_HABITS[h.name] || null;

    // Pre-populate from existing config (re-opening a selected onboarding habit)
    const ec = opts.existingConfig || {};

    // Mutable state for this screen
    let hdType  = ec.type       || h.type || 'build';
    // v3 Phase 1z.273E — prefer the DEFAULT_HABITS entry's defaultDays
    // when no explicit ec.sched / ec.days has been set yet. Lets the
    // schedule sheet open already reflecting the recommended training
    // cadence so the visible UI matches what will actually save.
    // User can change to daily/ndays/etc. like normal.
    const _defDays = Array.isArray(h && h.defaultDays) ? h.defaultDays : null;
    const _useDefDays = !ec.days && _defDays && _defDays.length > 0 && _defDays.length < 7;
    let hdSched = ec.sched      || (_useDefDays ? 'specific' : 'daily');
    let hdDays  = ec.days       ? [...ec.days] : (_useDefDays ? [..._defDays] : []);
    let hdNdays = ec.ndays      || 3;
    let hdGoal;
    if (ec.goal) {
      hdGoal = ec.goal.value;
    } else if (measurable) {
      if (measurable.bodyweightMin) {
        const bw = parseInt(localStorage.getItem('hb_bodyweight') || '0', 10);
        hdGoal = bw > 0 ? bw : measurable.def;
      } else {
        hdGoal = Math.max(measurable.min, measurable.def);
      }
    } else {
      hdGoal = 0;
    }
    // Step-goal staging — same pattern as hdGoal, mutually exclusive
    // with the time/count stepper for canonical Daily walk.
    const hdIsStepGoal = isStepGoalHabit(h);
    let hdStepGoal;
    if (typeof ec.stepGoal === 'number') hdStepGoal = ec.stepGoal;
    else                                  hdStepGoal = HEALTHKIT_WALK_DEFAULT_THRESHOLD;
    // Sleep-goal staging (canonical "Sleep" only). Mutually exclusive
    // with both the step-goal chips above AND the time/count stepper
    // below — branching is in the render() goal-card section.
    const hdIsSleepGoal = isSleepDurationHabit(h);
    let hdSleepGoal;
    if (typeof ec.sleepGoalHours === 'number') hdSleepGoal = ec.sleepGoalHours;
    else                                        hdSleepGoal = HEALTHKIT_SLEEP_DEFAULT_GOAL_HOURS;
    let hdDiff  = ec.difficulty || h.difficulty;
    let hdStart = ec.startDate  || today;

    function getScheduleDays() {
      if (hdSched === 'daily')    return undefined;
      if (hdSched === 'specific') return hdDays.length ? ALL_DAYS.filter(d => hdDays.includes(d)) : undefined;
      // ndays: evenly distribute across week
      const all = ALL_DAYS, step = 7 / hdNdays, out = [];
      for (let i = 0; i < hdNdays; i++) out.push(all[Math.min(6, Math.round(i * step))]);
      return out;
    }

    function render() {
      const content = document.getElementById('hd-content');
      content.innerHTML = '';

      // ── Header ─────────────────────────────────────────────
      const hdr = document.createElement('div');
      hdr.className = 'hd-header';
      hdr.innerHTML =
        '<button class="hd-back-btn" id="hd-back" aria-label="Back">←</button>' +
        '<div class="hd-header-info">' +
          '<span class="hd-header-emoji">' + habitIconHtml(h, { size: 28 }) + '</span>' +
          '<span class="hd-header-name">' + esc(h.name) + '</span>' +
        '</div>';
      content.appendChild(hdr);
      document.getElementById('hd-back').addEventListener('click', closeHabitDetail);

      if (alreadyAdded) {
        const msg = document.createElement('div');
        msg.className = 'hd-already';
        msg.innerHTML = '<span class="hd-already-icon">✓</span><span>Already in your habits list</span>';
        content.appendChild(msg);
        return;
      }

      // ── Scrollable body ────────────────────────────────────
      const body = document.createElement('div');
      body.className = 'hd-body';

      // ── Section 1: Habit Type (read-only) ─────────────────
      const typeCard = hdSection('Habit Type');
      const typeBadge = document.createElement('span');
      typeBadge.className = 'hd-type-badge hd-type-badge--' + hdType;
      typeBadge.textContent = hdType === 'build' ? '⬆ Build' : '⛔ Quit';
      typeCard.appendChild(typeBadge);
      body.appendChild(typeCard);

      // ── Section 2: Schedule ────────────────────────────────
      const schedCard = hdSection('Goal Period');
      const schedOpts = document.createElement('div');
      schedOpts.className = 'hd-sched-opts';

      [['daily','Every Day'],['specific','Specific days'],['ndays','Days per week']].forEach(([id, lbl]) => {
        const row = document.createElement('div');
        row.className = 'hd-sched-opt' + (hdSched === id ? ' hd-sched-opt--active' : '');
        const dot = document.createElement('span');
        dot.className = 'hd-sched-dot';
        const txt = document.createElement('span');
        txt.textContent = lbl;
        row.append(dot, txt);
        row.addEventListener('click', e => {
          e.stopPropagation();
          if (hdSched !== id) { hdSched = id; hdDays = []; render(); }
        });
        schedOpts.appendChild(row);

        // Inline sub-controls for active option
        if (hdSched === id) {
          if (id === 'specific') {
            const daysRow = document.createElement('div');
            daysRow.className = 'hd-days-row';
            ALL_DAYS.forEach((day, di) => {
              const b = document.createElement('button');
              b.className = 'hd-day-btn' + (hdDays.includes(day) ? ' hd-day-btn--on' : '');
              b.textContent = DAY_LABELS[di];
              b.addEventListener('click', e => {
                e.stopPropagation();
                hdDays = hdDays.includes(day) ? hdDays.filter(d => d !== day) : [...hdDays, day];
                // re-render just the day btn states (minor optimisation)
                render();
              });
              daysRow.appendChild(b);
            });
            schedOpts.appendChild(daysRow);
          } else if (id === 'ndays') {
            const stepper = document.createElement('div');
            stepper.className = 'hd-stepper hd-stepper--sub';
            const dec = document.createElement('button');
            dec.className = 'hd-step-btn';
            dec.textContent = '−';
            dec.addEventListener('click', e => { e.stopPropagation(); if (hdNdays > 1) { hdNdays--; render(); } });
            const val = document.createElement('span');
            val.className = 'hd-step-val';
            val.textContent = hdNdays + 'x per week';
            const inc = document.createElement('button');
            inc.className = 'hd-step-btn';
            inc.textContent = '+';
            inc.addEventListener('click', e => { e.stopPropagation(); if (hdNdays < 7) { hdNdays++; render(); } });
            stepper.append(dec, val, inc);
            schedOpts.appendChild(stepper);
          }
        }
      });

      schedCard.appendChild(schedOpts);
      body.appendChild(schedCard);

      // ── Section 3: Goal Value ──────────────────────────────
      // Step-goal habits (canonical Daily walk) get the chip picker
      // here too — matches the post-onboarding Edit Habit modal so
      // there's no jarring difference between the two surfaces.
      if (hdIsStepGoal) {
        const goalCard = hdSection('Goal Value');
        const valueRow = document.createElement('div');
        valueRow.className = 'habit-edit-stepgoal-row';
        const valueLabel = document.createElement('span');
        valueLabel.className = 'habit-edit-stepgoal-label';
        valueLabel.textContent = 'Step goal';
        const valueDisplay = document.createElement('span');
        valueDisplay.className = 'habit-edit-stepgoal-value';
        valueDisplay.textContent = hdStepGoal.toLocaleString() + ' steps';
        valueRow.append(valueLabel, valueDisplay);
        goalCard.appendChild(valueRow);

        const chips = document.createElement('div');
        chips.className = 'habit-edit-stepgoal-chips';
        const chipDefs = HEALTHKIT_WALK_PRESETS.map(n => ({ preset: String(n), label: n.toLocaleString() }))
          .concat([{ preset: 'custom', label: 'Custom' }]);
        chipDefs.forEach(({ preset, label }) => {
          const btn = document.createElement('button');
          btn.type = 'button';
          btn.className = 'habit-edit-stepgoal-chip';
          btn.dataset.preset = preset;
          btn.textContent = label;
          chips.appendChild(btn);
        });
        const setActive = () => {
          const isCustom = !HEALTHKIT_WALK_PRESETS.includes(hdStepGoal);
          chips.querySelectorAll('.habit-edit-stepgoal-chip').forEach(chip => {
            const p = chip.dataset.preset;
            const active = (p === 'custom') ? isCustom : (parseInt(p, 10) === hdStepGoal);
            chip.classList.toggle('habit-edit-stepgoal-chip--active', active);
          });
        };
        setActive();

        const customRow = document.createElement('div');
        customRow.className = 'habit-edit-stepgoal-custom hidden';
        const customInput = document.createElement('input');
        customInput.type = 'number';
        customInput.inputMode = 'numeric';
        customInput.min = HEALTHKIT_WALK_THRESHOLD_MIN;
        customInput.max = HEALTHKIT_WALK_THRESHOLD_MAX;
        customInput.placeholder = 'Enter steps (100–50,000)';
        customInput.className = 'habit-edit-stepgoal-input';
        const customSave = document.createElement('button');
        customSave.type = 'button';
        customSave.className = 'habit-edit-stepgoal-save';
        customSave.textContent = 'Save';
        const customCancel = document.createElement('button');
        customCancel.type = 'button';
        customCancel.className = 'habit-edit-stepgoal-cancel';
        customCancel.textContent = 'Cancel';
        customRow.append(customInput, customSave, customCancel);

        chips.addEventListener('click', (e) => {
          const chip = e.target.closest('.habit-edit-stepgoal-chip');
          if (!chip) return;
          const p = chip.dataset.preset;
          if (p === 'custom') {
            customRow.classList.remove('hidden');
            customInput.value = String(hdStepGoal);
            setTimeout(() => customInput.focus(), 50);
            return;
          }
          const n = parseInt(p, 10);
          if (!Number.isFinite(n)) return;
          hdStepGoal = n;
          customRow.classList.add('hidden');
          valueDisplay.textContent = hdStepGoal.toLocaleString() + ' steps';
          setActive();
        });
        const commitCustom = () => {
          const parsed = parseInt(customInput.value, 10);
          const fallback = Number.isFinite(parsed) ? parsed : HEALTHKIT_WALK_DEFAULT_THRESHOLD;
          hdStepGoal = Math.max(HEALTHKIT_WALK_THRESHOLD_MIN, Math.min(HEALTHKIT_WALK_THRESHOLD_MAX, fallback));
          customRow.classList.add('hidden');
          valueDisplay.textContent = hdStepGoal.toLocaleString() + ' steps';
          setActive();
        };
        customSave.addEventListener('click', commitCustom);
        customInput.addEventListener('keydown', (e) => { if (e.key === 'Enter') commitCustom(); });
        customCancel.addEventListener('click', () => { customRow.classList.add('hidden'); });

        goalCard.appendChild(chips);
        goalCard.appendChild(customRow);
        body.appendChild(goalCard);
      } else if (hdIsSleepGoal) {
        // Sleep-goal chips — mirrors the step-goal block above with
        // hours instead of steps. Reuses the same .habit-edit-stepgoal-*
        // CSS classes so the visual treatment matches.
        const goalCard = hdSection('Goal Value');
        const valueRow = document.createElement('div');
        valueRow.className = 'habit-edit-stepgoal-row';
        const valueLabel = document.createElement('span');
        valueLabel.className = 'habit-edit-stepgoal-label';
        valueLabel.textContent = 'Sleep goal';
        const valueDisplay = document.createElement('span');
        valueDisplay.className = 'habit-edit-stepgoal-value';
        const fmtSleep = (n) => n + (n === 1 ? ' hour' : ' hours');
        valueDisplay.textContent = fmtSleep(hdSleepGoal);
        valueRow.append(valueLabel, valueDisplay);
        goalCard.appendChild(valueRow);

        const chips = document.createElement('div');
        chips.className = 'habit-edit-stepgoal-chips';
        const chipDefs = HEALTHKIT_SLEEP_PRESETS.map(n => ({ preset: String(n), label: n + ' hrs' }))
          .concat([{ preset: 'custom', label: 'Custom' }]);
        chipDefs.forEach(({ preset, label }) => {
          const btn = document.createElement('button');
          btn.type = 'button';
          btn.className = 'habit-edit-stepgoal-chip';
          btn.dataset.preset = preset;
          btn.textContent = label;
          chips.appendChild(btn);
        });
        const setActive = () => {
          const isCustom = !HEALTHKIT_SLEEP_PRESETS.includes(hdSleepGoal);
          chips.querySelectorAll('.habit-edit-stepgoal-chip').forEach(chip => {
            const p = chip.dataset.preset;
            const active = (p === 'custom') ? isCustom : (parseFloat(p) === hdSleepGoal);
            chip.classList.toggle('habit-edit-stepgoal-chip--active', active);
          });
        };
        setActive();

        const customRow = document.createElement('div');
        customRow.className = 'habit-edit-stepgoal-custom hidden';
        const customInput = document.createElement('input');
        customInput.type = 'number';
        customInput.inputMode = 'decimal';
        customInput.min = HEALTHKIT_SLEEP_GOAL_MIN_HOURS;
        customInput.max = HEALTHKIT_SLEEP_GOAL_MAX_HOURS;
        customInput.step = 0.5;
        customInput.placeholder = 'Enter hours (3–14, 0.5 step)';
        customInput.className = 'habit-edit-stepgoal-input';
        const customSave = document.createElement('button');
        customSave.type = 'button';
        customSave.className = 'habit-edit-stepgoal-save';
        customSave.textContent = 'Save';
        const customCancel = document.createElement('button');
        customCancel.type = 'button';
        customCancel.className = 'habit-edit-stepgoal-cancel';
        customCancel.textContent = 'Cancel';
        customRow.append(customInput, customSave, customCancel);

        chips.addEventListener('click', (e) => {
          const chip = e.target.closest('.habit-edit-stepgoal-chip');
          if (!chip) return;
          const p = chip.dataset.preset;
          if (p === 'custom') {
            customRow.classList.remove('hidden');
            customInput.value = String(hdSleepGoal);
            setTimeout(() => customInput.focus(), 50);
            return;
          }
          const n = parseFloat(p);
          if (!Number.isFinite(n)) return;
          hdSleepGoal = n;
          customRow.classList.add('hidden');
          valueDisplay.textContent = fmtSleep(hdSleepGoal);
          setActive();
        });
        const commitCustom = () => {
          const parsed = parseFloat(customInput.value);
          const fallback = Number.isFinite(parsed) ? parsed : HEALTHKIT_SLEEP_DEFAULT_GOAL_HOURS;
          hdSleepGoal = Math.max(HEALTHKIT_SLEEP_GOAL_MIN_HOURS, Math.min(HEALTHKIT_SLEEP_GOAL_MAX_HOURS, fallback));
          customRow.classList.add('hidden');
          valueDisplay.textContent = fmtSleep(hdSleepGoal);
          setActive();
        };
        customSave.addEventListener('click', commitCustom);
        customInput.addEventListener('keydown', (e) => { if (e.key === 'Enter') commitCustom(); });
        customCancel.addEventListener('click', () => { customRow.classList.add('hidden'); });

        goalCard.appendChild(chips);
        goalCard.appendChild(customRow);
        body.appendChild(goalCard);
      } else if (measurable) {
        const goalCard = hdSection('Goal Value');

        // Special bodyweight input for Protein goal
        if (measurable.bodyweightMin) {
          const bwWrap = document.createElement('div');
          bwWrap.className = 'hd-bw-wrap';
          const bwLabel = document.createElement('label');
          bwLabel.className = 'hd-bw-label';
          bwLabel.textContent = 'Your bodyweight (lbs)';
          const bwInput = document.createElement('input');
          bwInput.type = 'number';
          bwInput.className = 'hd-bw-input';
          bwInput.placeholder = 'Enter your bodyweight in lbs';
          bwInput.min = 50; bwInput.max = 500; bwInput.step = 1;
          const savedBW = localStorage.getItem('hb_bodyweight');
          if (savedBW) bwInput.value = savedBW;
          bwInput.addEventListener('input', () => {
            const bw = parseInt(bwInput.value, 10);
            if (bw > 0) {
              localStorage.setItem('hb_bodyweight', String(bw));
              if (hdGoal < bw) { hdGoal = bw; render(); }
            }
          });
          bwWrap.append(bwLabel, bwInput);
          goalCard.appendChild(bwWrap);
        }

        const stepper = document.createElement('div');
        stepper.className = 'hd-stepper';
        const dec = document.createElement('button');
        dec.className = 'hd-step-btn';
        dec.textContent = '−';
        dec.addEventListener('click', () => {
          const floor = measurable.bodyweightMin
            ? Math.max(measurable.step, parseInt(localStorage.getItem('hb_bodyweight') || '0', 10))
            : measurable.min;
          if (hdGoal - measurable.step >= Math.max(measurable.step, floor)) {
            hdGoal -= measurable.step; render();
          }
        });
        const val = document.createElement('span');
        val.className = 'hd-step-val';
        val.textContent = hdGoal.toLocaleString() + ' ' + measurable.unit + ' / day';
        const inc = document.createElement('button');
        inc.className = 'hd-step-btn';
        inc.textContent = '+';
        inc.addEventListener('click', () => { hdGoal += measurable.step; render(); });
        stepper.append(dec, val, inc);
        goalCard.appendChild(stepper);
        body.appendChild(goalCard);
      }

      // ── Section 4: Difficulty (read-only) ─────────────────
      const diffCard = hdSection('Difficulty');
      const diffRow  = document.createElement('div');
      diffRow.className = 'hd-diff-row';
      const badge = document.createElement('span');
      badge.className = 'diff-badge ' + hdDiff;
      badge.textContent = DIFFICULTY[hdDiff].label;
      const xpNote = document.createElement('div');
      xpNote.className = 'hd-xp-note';
      xpNote.innerHTML = iconify('⚡ +' + DIFFICULTY[hdDiff].pts + ' XP per completion', { size: 14 });
      diffRow.appendChild(badge);
      diffCard.append(diffRow, xpNote);
      body.appendChild(diffCard);

      // ── Section 5: Start Date ──────────────────────────────
      const dateCard = hdSection('Start Date');
      const dateInput = document.createElement('input');
      dateInput.type = 'date';
      dateInput.className = 'hd-date-input';
      dateInput.value = hdStart;
      dateInput.addEventListener('change', () => { hdStart = dateInput.value || today; });
      dateCard.appendChild(dateInput);
      body.appendChild(dateCard);

      content.appendChild(body);

      // ── Footer: Add / Update button ───────────────────────
      const footer = document.createElement('div');
      footer.className = 'hd-footer';
      const addBtn = document.createElement('button');
      addBtn.className = 'hd-add-btn';
      addBtn.textContent = (isOnboarding || !isSelected) ? 'Add to My Habits' : 'Update Habit';
      // v3 Phase 1z.85 — iOS post-save freeze fix (same class as 1z.34).
      // Previous pattern was:
      //   opts.onConfirm(cfg);  // pushes habit + save + renderHabits + renderLibrary
      //   closeHabitDetail();   // <— never runs if any of the above throws on iOS
      // A synchronous throw inside renderHabits (e.g. buildItem hitting an
      // unexpected habit shape) bubbled past closeHabitDetail and left the
      // sheet open intercepting all touches. Repro: Add Habits → Hydrate →
      // Add to My Habits → app frozen.
      //
      // New pattern: persist → close → render-in-try-catch. Each stage is
      // independently wrapped so a failure in one can't strand the sheet.
      // Renders are pulled OUT of the library onConfirm callback (line ~15758
      // post-fix) and called here so the contract is centralized:
      //   1. Validate + build cfg.
      //   2. Call opts.onConfirm (or run the default library push+save).
      //   3. closeHabitDetail() unconditionally.
      //   4. renderHabits + renderLibrary, each in its own try/catch.
      //   5. finally → clear button busy/disabled state.
      // Double-tap guard via dataset.busy prevents duplicate adds while the
      // handler is mid-flight.
      // v3 Phase 1z.91 — fully instrumented + conservative add path.
      // Persistent localStorage breadcrumbs at every step so a freeze
      // that requires force-quit can be diagnosed post-mortem. No
      // renderLibrary after successful add (the sheet is closed; the
      // library will re-render on next openLibrary). Renders deferred
      // to a real 150ms paint window. Watchdog at 500ms re-runs the
      // force-close as belt-and-braces against any stale overlay.
      addBtn.addEventListener('click', () => {
        _addHabitBreadcrumb('tap-start', {
          name: (h && h.name) || null,
          context: opts.context || null,
          build: (typeof APP_BUILD_TAG !== 'undefined') ? APP_BUILD_TAG : null,
        });
        if (addBtn.dataset.busy === '1') {
          _addHabitBreadcrumb('tap-busy-already-set');
          return;
        }
        addBtn.dataset.busy = '1';
        addBtn.disabled = true;
        _addHabitBreadcrumb('busy-guard-set');

        // ── Already-added tap guard ───────────────────────────────
        try {
          _addHabitBreadcrumb('dup-guard-start');
          if (!isOnboarding && isHabitAlreadyAdded(h)) {
            _addHabitBreadcrumb('dup-guard-tripped', { name: h && h.name });
            try {
              if (typeof showHabitToast === 'function') {
                showHabitToast((h && h.name ? h.name : 'Habit') + ' is already in your habits.');
              }
            } catch (_) {}
            try { forceCloseAddHabitsStack('dup-guard'); } catch (_) {}
            addBtn.dataset.busy = '';
            addBtn.disabled = false;
            _addHabitBreadcrumb('dup-guard-complete');
            return;
          }
          _addHabitBreadcrumb('dup-guard-passed');
        } catch (err) {
          _addHabitBreadcrumb('dup-guard-threw', { err: String(err && err.message || err) });
        }

        // ── Main add path ─────────────────────────────────────────
        let saveOK = false;
        try {
          _addHabitBreadcrumb('cfg-build-start');
          const days = getScheduleDays();
          const cfg  = {
            type:       hdType,
            sched:      hdSched,
            ndays:      hdNdays,
            difficulty: hdDiff,
            days:       days || undefined,
            goal:           (!hdIsStepGoal && !hdIsSleepGoal && measurable) ? { value: hdGoal, unit: measurable.unit } : undefined,
            stepGoal:       hdIsStepGoal  ? hdStepGoal  : undefined,
            sleepGoalHours: hdIsSleepGoal ? hdSleepGoal : undefined,
            startDate:  hdStart !== today ? hdStart : undefined,
          };
          _addHabitBreadcrumb('cfg-build-complete', {
            type: cfg.type, sched: cfg.sched, hasGoal: !!cfg.goal,
            hasStepGoal: typeof cfg.stepGoal === 'number',
            hasSleepGoal: typeof cfg.sleepGoalHours === 'number',
          });

          if (opts.onConfirm) {
            _addHabitBreadcrumb('onConfirm-start');
            try { opts.onConfirm(cfg); saveOK = true; }
            catch (err) {
              _addHabitBreadcrumb('onConfirm-threw', { err: String(err && err.message || err) });
            }
            _addHabitBreadcrumb('onConfirm-complete', { saveOK });
          } else {
            // v3 Phase 1z.280 — Active habit cap. Habit Detail create
            // branch. Block before constructing the new row.
            if (!canAddHabits(1)) {
              _addHabitBreadcrumb('default-save-blocked-system-full', {
                activeCount: getActiveHabitCount(),
              });
              try { showSystemFullModal({ context: 'detail', attemptedCount: 1 }); } catch (_) {}
              return;
            }
            _addHabitBreadcrumb('default-save-start');
            const newH = { id: uid(), emoji: h.emoji, name: h.name, difficulty: hdDiff, type: hdType };
            // v3 Phase 1z.273E — length guard. getScheduleDays() can
            // theoretically return all 7 (specific picker with all
            // pills toggled on). Mirror the schedule sheet's
            // convention: 1..6 writes, 7 omits → daily via the
            // isScheduledToday length-7 / no-field shortcut. Never
            // writes days: [].
            if (Array.isArray(days) && days.length > 0 && days.length < 7) {
              newH.days = days.slice();
            }
            if (hdIsStepGoal)       newH.stepGoal       = hdStepGoal;
            else if (hdIsSleepGoal) newH.sleepGoalHours = hdSleepGoal;
            else if (measurable)    newH.goal           = { value: hdGoal, unit: measurable.unit };
            if (hdStart !== today)  newH.startDate      = hdStart;
            habits.push(newH);
            try { save(); saveOK = true; }
            catch (err) {
              _addHabitBreadcrumb('default-save-threw', { err: String(err && err.message || err) });
            }
            _addHabitBreadcrumb('default-save-complete', { saveOK });
          }

          // Close BEFORE any render. 1z.91 routes everything through
          // forceCloseAddHabitsStack — single deterministic helper.
          _addHabitBreadcrumb('force-close-start');
          try { forceCloseAddHabitsStack('add-success'); } catch (_) {}
          _addHabitBreadcrumb('force-close-complete');

          // Success toast.
          if (saveOK && opts.context === 'library') {
            try {
              if (typeof showHabitToast === 'function' && h && h.name) {
                showHabitToast(h.name + ' added to your habits.');
                _addHabitBreadcrumb('toast-shown');
              }
            } catch (_) {}
          }
        } catch (err) {
          _addHabitBreadcrumb('outer-threw', { err: String(err && err.message || err) });
          try { forceCloseAddHabitsStack('outer-throw'); } catch (_) {}
        } finally {
          addBtn.dataset.busy = '';
          addBtn.disabled = false;
          _addHabitBreadcrumb('finally-cleanup');
        }

        // ── Deferred render — renderHabits with skipSideEffects ─
        // 1z.94 — TestFlight 2.2.2-w6 breadcrumbs proved the freeze
        // happens between render-tick-ok (+169ms) and alive-500
        // (which never fires). Diagnosis: renderHabits's tail-end
        // HealthKit auto-verify + boss-resolver calls dispatch
        // native-bridge work whose async callbacks fire heavy JS
        // 300–500ms later and block the main thread.
        //
        // Fix: pass {skipSideEffects:true} so renderHabits ONLY
        // updates the DOM (user sees the new habit immediately) and
        // does NOT dispatch the HealthKit/boss callbacks. The side
        // effects run on a separate 2000ms-deferred tick AFTER the
        // UI has fully settled.
        try {
          setTimeout(() => {
            _addHabitBreadcrumb('render-tick-start');
            try { renderHabits({ skipSideEffects: true }); _addHabitBreadcrumb('render-tick-ok'); }
            catch (err) {
              _addHabitBreadcrumb('render-tick-threw', { err: String(err && err.message || err) });
            }
          }, 150);
        } catch (_) {
          // Fallback if setTimeout is somehow unavailable — sync.
          try { renderHabits({ skipSideEffects: true }); } catch (_) {}
        }

        // ── Post-add watchdog (~500ms) ─────────────────────────────
        // Belt-and-braces: if ANY layer of the close path failed to
        // hide an overlay or clear pointer-events, this watchdog
        // re-runs forceCloseAddHabitsStack idempotently. Also logs
        // an interaction-state snapshot for the next freeze repro.
        try {
          setTimeout(() => {
            try { forceCloseAddHabitsStack('watchdog-500ms'); } catch (_) {}
            try { ensureHabitsTabInteractive(); } catch (_) {}
            _addHabitBreadcrumb('watchdog-complete');
          }, 500);
        } catch (_) {}

        // ── 1z.95 — NO side-effects dispatch from the add path ─────
        // TestFlight 2.2.2-w7 breadcrumbs proved the cascade pattern:
        // HealthKit native-bridge callbacks return as Promise
        // resolutions (microtasks). The handlers chain MORE native
        // calls (re-renderHabits → more autoVerify dispatches), and
        // the microtask queue keeps producing new microtasks
        // indefinitely. This STARVES the macrotask queue (setTimeout)
        // for 30-60 seconds, blocking touch handling.
        //
        // Confirmed in the w7 dump: alive-1000 fires, side-effects-
        // complete fires at t+2009ms, but alive-2000 (also a 2000ms
        // setTimeout) NEVER fires because the side-effects callback
        // ran and the microtask cascade that followed starved the
        // event loop. ensureInteractive at t+500ms also reported
        // tabBarVisible:false confirming the touch block.
        //
        // Fix: do NOT dispatch side effects from the add path at all.
        // They run on the next natural renderHabits trigger:
        //   - Tab switch (switchTab → renderHabits)
        //   - Visibility change (app foreground/background)
        //   - Day change (checkDayChange)
        // User flow becomes: add habit → app instantly interactive.
        // When user later switches tabs, the cascade runs but they're
        // already on a new tab and not trying to interact mid-cascade.
        _addHabitBreadcrumb('side-effects-skipped-on-add');

        // ── Alive probes (post-tap) ───────────────────────────────
        // Extended through 10 seconds. If alive-10000 lands, JS is
        // healthy throughout the entire post-add interaction window
        // and the freeze is gone.
        try { setTimeout(() => _addHabitBreadcrumb('alive-100'),   100); } catch (_) {}
        try { setTimeout(() => _addHabitBreadcrumb('alive-500'),   500); } catch (_) {}
        try { setTimeout(() => _addHabitBreadcrumb('alive-1000'),  1000); } catch (_) {}
        try { setTimeout(() => _addHabitBreadcrumb('alive-2000'),  2000); } catch (_) {}
        try { setTimeout(() => _addHabitBreadcrumb('alive-3000'),  3000); } catch (_) {}
        try { setTimeout(() => _addHabitBreadcrumb('alive-5000'),  5000); } catch (_) {}
        try { setTimeout(() => _addHabitBreadcrumb('alive-10000'), 10000); } catch (_) {}
      });
      footer.appendChild(addBtn);

      // Remove button — shown when re-configuring an already-selected onboarding habit
      if (isSelected && opts.onRemove) {
        const removeBtn = document.createElement('button');
        removeBtn.className = 'hd-remove-btn';
        removeBtn.textContent = 'Remove from list';
        removeBtn.addEventListener('click', () => {
          opts.onRemove();
          closeHabitDetail();
        });
        footer.appendChild(removeBtn);
      }

      content.appendChild(footer);
    }

    render();
    // v3 Phase 1z.88 — closeHabitDetail now sets inline display:none and
    // pointer-events:none on the sheet (belt-and-braces). Clear those
    // before un-hiding so the sheet re-opens reliably.
    const _hd = document.getElementById('hd-sheet');
    if (_hd) {
      try { _hd.style.removeProperty('display'); } catch (_) {}
      try { _hd.style.removeProperty('pointer-events'); } catch (_) {}
      _hd.classList.remove('hidden');
    }
  }

  // v3 Phase 1z.88 — belt-and-braces close. Earlier builds relied on the
  // `.hidden { display:none !important }` CSS class alone. If a stale style
  // attribute, leftover transform, or stray inline display:flex ever stuck
  // on the sheet, the user would be trapped behind an invisible-but-still-
  // interactive overlay. We now ALSO force inline display:none + clear
  // pointer-events, and wrap each DOM op in its own try so a broken node
  // can't strand the whole close path.
  function closeHabitDetail() {
    try {
      const sheet = document.getElementById('hd-sheet');
      if (sheet) {
        try { sheet.classList.add('hidden'); } catch (_) {}
        try { sheet.style.setProperty('display', 'none', 'important'); } catch (_) {}
        try { sheet.style.pointerEvents = 'none'; } catch (_) {}
      }
    } catch (_) {}
    try {
      const content = document.getElementById('hd-content');
      if (content) content.innerHTML = '';
    } catch (_) {}
  }

  function setupHabitDetailGesture() {
    if (typeof attachSheetDismissGesture !== 'function') return;
    const sheet = document.getElementById('hd-sheet');
    if (!sheet) return;
    attachSheetDismissGesture(sheet, null, closeHabitDetail, {
      baseTransform:  'translateX(-50%) ',
      handleSelector: '.hd-drag-handle',
      scrollTarget:   '#hd-content',
    });
  }

  // Creates a labelled section card for the detail screen
  function hdSection(label) {
    const sec = document.createElement('div');
    sec.className = 'hd-section';
    const lbl = document.createElement('div');
    lbl.className = 'hd-section-label';
    lbl.textContent = label;
    sec.appendChild(lbl);
    return sec;
  }

  function uid() {
    return Date.now().toString(36) + Math.random().toString(36).slice(2, 7);
  }

  // ── DIFFICULTY SELECTOR HELPER ────────────────────────────
  function setActiveDiff(rowId, diff) {
    document.getElementById(rowId).querySelectorAll('.diff-btn').forEach(b => {
      b.classList.toggle('active', b.dataset.diff === diff);
    });
  }

  function setActiveDays(rowId, days) {
    document.getElementById(rowId).querySelectorAll('.day-btn').forEach(b => {
      b.classList.toggle('active', days.includes(b.dataset.day));
    });
  }

  // ── LONG PRESS ────────────────────────────────────────────

  // ── SCHEDULE PICKER ──────────────────────────────────────
  const SCHED_PRESETS = {
    daily:    [...ALL_DAYS],
    weekdays: ['Mon','Tue','Wed','Thu','Fri'],
    weekends: ['Fri','Sat','Sun'],
    '3x':     ['Mon','Wed','Fri'],
  };

  function openSchedulePicker(id) {
    schedHabitId = id;
    const habit = habits.find(h => h.id === id);
    schedFormDays = habit?.days ? [...habit.days] : [...ALL_DAYS];
    setActiveDays('sched-days-row', schedFormDays);
    syncSchedPresets();
    refreshSchedReminderUI();
    document.getElementById('sched-overlay').classList.remove('hidden');
    document.getElementById('sched-sheet').classList.remove('hidden');
  }

  // Sync the Reminder row in the Schedule sheet to the habit's current
  // per-habit reminder state. Called on open + after change/clear.
  function refreshSchedReminderUI() {
    const btn   = document.getElementById('sched-reminder-btn');
    const clear = document.getElementById('sched-reminder-clear');
    if (!btn || !clear || !schedHabitId) return;
    let time = null;
    try { time = (Notif.reminderFor && Notif.reminderFor(schedHabitId)) || null; } catch (_) {}
    if (time) {
      const [hStr, mStr] = time.split(':');
      const h  = parseInt(hStr, 10) || 0;
      const m  = parseInt(mStr, 10) || 0;
      const pm = h >= 12;
      const h12 = ((h % 12) || 12);
      const label = h12 + ':' + String(m).padStart(2, '0') + ' ' + (pm ? 'PM' : 'AM');
      btn.textContent  = '⏰ ' + label;
      btn.classList.add('sched-reminder-btn--set');
      clear.classList.remove('hidden');
    } else {
      btn.textContent  = '+ Add reminder';
      btn.classList.remove('sched-reminder-btn--set');
      clear.classList.add('hidden');
    }
  }

  function closeSchedulePicker() {
    document.getElementById('sched-overlay').classList.add('hidden');
    document.getElementById('sched-sheet').classList.add('hidden');
    schedHabitId = null;
  }

  function syncSchedPresets() {
    document.querySelectorAll('.sched-preset').forEach(btn => {
      const preset = SCHED_PRESETS[btn.dataset.preset];
      const match  = preset.length === schedFormDays.length && preset.every(d => schedFormDays.includes(d));
      btn.classList.toggle('active', match);
    });
  }

  function setupSchedulePicker() {
    document.getElementById('sched-overlay').addEventListener('click', closeSchedulePicker);
    document.getElementById('sched-cancel-btn').addEventListener('click', closeSchedulePicker);

    // Swipe-down-to-dismiss
    if (typeof attachSheetDismissGesture === 'function') {
      const ss = document.getElementById('sched-sheet');
      const so = document.getElementById('sched-overlay');
      attachSheetDismissGesture(ss, so, closeSchedulePicker, {
        baseTransform:  'translateX(-50%) ',
        handleSelector: '.sched-drag-handle, .sched-header',
      });
    }

    document.getElementById('sched-save-btn').addEventListener('click', () => {
      const habit = habits.find(h => h.id === schedHabitId);
      if (habit) {
        if (schedFormDays.length === 7) delete habit.days;
        else habit.days = [...schedFormDays];
        // v3 Phase 1z.34 -- close picker BEFORE rendering so a render
        // throw can't leave the schedule sheet stuck on iOS.
        try { save(); } catch (e) { try { console.warn('[sched] save failed', e); } catch (_) {} }
      }
      closeSchedulePicker();
      // v3 Phase 1z.273F — invalidate the 1z.214 fingerprint so the
      // habit-schedule-chip refreshes on edit. The fingerprint reads
      // (id, checked, streakBand, autoVerify) only; a schedule edit
      // that doesn't shift today-visibility (e.g. MWF → MTWF when
      // viewing on Mon) would otherwise bail rebuild and leave the
      // chip stale until the next state change. One-line nudge —
      // does not touch the hot 214-perf path on toggle/render.
      try { _lastHabitsRenderFingerprint = null; } catch (_) {}
      // v3 Phase 1z.97 — skipSideEffects (HealthKit cascade fix).
      try { renderHabits({ skipSideEffects: true }); } catch (e) { try { console.warn('[sched] post-save render failed', e); } catch (_) {} }
    });

    document.getElementById('sched-days-row').querySelectorAll('.day-btn').forEach(btn => {
      btn.addEventListener('click', () => {
        btn.classList.toggle('active');
        schedFormDays = [...document.getElementById('sched-days-row').querySelectorAll('.day-btn.active')].map(b => b.dataset.day);
        if (schedFormDays.length === 0) { btn.classList.add('active'); schedFormDays = [btn.dataset.day]; }
        syncSchedPresets();
      });
    });

    document.querySelectorAll('.sched-preset').forEach(btn => {
      btn.addEventListener('click', () => {
        schedFormDays = [...SCHED_PRESETS[btn.dataset.preset]];
        setActiveDays('sched-days-row', schedFormDays);
        syncSchedPresets();
      });
    });

    // Per-habit reminder controls. The button opens the same custom
    // hour + 15-min minute picker used by Settings. The Remove button
    // clears the reminder and is hidden when none is set.
    const remBtn   = document.getElementById('sched-reminder-btn');
    const remClear = document.getElementById('sched-reminder-clear');
    if (remBtn) {
      remBtn.addEventListener('click', () => {
        if (!schedHabitId) return;
        const habit = habits.find(h => h.id === schedHabitId);
        const current = (Notif.reminderFor && Notif.reminderFor(schedHabitId))
          || (typeof defaultReminderTimeFor === 'function' ? defaultReminderTimeFor(habit) : '07:00');
        openDigestTimePickerModal(current, async (newT) => {
          try { await Notif.setReminder(schedHabitId, newT); } catch (_) {}
          refreshSchedReminderUI();
          if (typeof refreshRemindersPanel === 'function') refreshRemindersPanel();
        });
      });
    }
    if (remClear) {
      remClear.addEventListener('click', async () => {
        if (!schedHabitId) return;
        try { await Notif.clearReminder(schedHabitId); } catch (_) {}
        refreshSchedReminderUI();
        if (typeof refreshRemindersPanel === 'function') refreshRemindersPanel();
      });
    }
  }

  // ── CONTEXT MENU ─────────────────────────────────────────
  function showCtxMenu(id, el) {
    ctxHabitId = id;
    const menu = document.getElementById('ctx-menu');
    const overlay = document.getElementById('ctx-overlay');
    // View Note is now the full habit detail sheet (stats + editable note),
    // so always show it regardless of whether a note has been written yet.
    const ctxNoteBtn = document.getElementById('ctx-note');
    ctxNoteBtn.classList.remove('hidden');
    document.getElementById('ctx-note-label').textContent = 'View Note';
    menu.classList.remove('hidden');
    overlay.classList.remove('hidden');
    const rect = el.getBoundingClientRect();
    const mw = 210;
    let left = rect.right - mw, top = rect.bottom + 6;
    if (left < 8) left = 8;
    if (top + 160 > window.innerHeight - 20) top = rect.top - 166;
    menu.style.left = Math.max(8, left) + 'px';
    menu.style.top  = Math.max(8, top)  + 'px';
  }

  function hideCtxMenu() {
    document.getElementById('ctx-menu').classList.add('hidden');
    document.getElementById('ctx-overlay').classList.add('hidden');
    ctxHabitId = null;
  }

  function setupCtxMenu() {
    document.getElementById('ctx-overlay').addEventListener('click', hideCtxMenu);
    document.getElementById('ctx-overlay').addEventListener('touchstart', hideCtxMenu, { passive: true });
    document.getElementById('ctx-edit').addEventListener('click', () => { const id = ctxHabitId; hideCtxMenu(); openEditModal(id); });
    document.getElementById('ctx-note').addEventListener('click', () => { const id = ctxHabitId; hideCtxMenu(); openNoteModal(id); });
    document.getElementById('ctx-schedule').addEventListener('click', () => { const id = ctxHabitId; hideCtxMenu(); openSchedulePicker(id); });
    document.getElementById('ctx-delete').addEventListener('click', () => { const id = ctxHabitId; hideCtxMenu(); deleteHabit(id); });
  }

  // ── COMPOUND EFFECT BONUS ─────────────────────────────────
  let compoundPopupTimer = null;

  // v2.0.1 compound bonus rewrite. Per-day curve with milestone
  // spikes at days 7/14/30/90/180/365. Locked-In is a 1.5× variant
  // of Morning Routine — same shape, bigger numbers (the Locked-In
  // pack is 16 habits vs MR's 10, harder to maintain, deserves more).
  // The new rank thresholds (S = 70,000 XP) are calibrated for THIS
  // curve — the previous coarse 6-tier function (5/10/20/30/50/75)
  // was nowhere near enough to support a 6-month-to-S progression.
  //
  // Pattern: days 1-6 ramp linearly, then steady-state with milestone
  // spikes at 7/14/30/90/180/365. After day 90 the steady-state drops
  // back below the milestone (200<300, 250<500, 300<1000) so milestones
  // feel like genuine spikes rather than permanent step-ups.
  function getCompoundXP(packId, streak) {
    if (typeof streak !== 'number' || streak <= 0) return 0;

    if (packId === 'morning') {
      // Days 1-6: linear ramp 5 → 30 (5×streakDay)
      if (streak <= 6) return streak * 5;
      // Day 7 milestone + steady-state through day 13 (both 50)
      if (streak <= 13) return 50;
      // Day 14 milestone + steady-state through day 29 (both 75)
      if (streak <= 29) return 75;
      // Day 30 milestone + steady-state through day 89 (both 150)
      if (streak <= 89) return 150;
      // Day 90 spike, then drop to higher steady-state
      if (streak === 90) return 300;
      if (streak <= 179) return 200;
      // 6-month spike
      if (streak === 180) return 500;
      if (streak <= 364) return 250;
      // 1-year spike
      if (streak === 365) return 1000;
      return 300; // year+ steady-state
    }

    if (packId === 'locked-in') {
      // 1.5× Morning Routine values (rounded as spec'd)
      if (streak <= 6) {
        const ramp = [0, 8, 15, 23, 30, 38, 45];
        return ramp[streak];
      }
      if (streak <= 13) return 75;
      if (streak <= 29) return 112;
      if (streak <= 89) return 225;
      if (streak === 90) return 450;
      if (streak <= 179) return 300;
      if (streak === 180) return 750;
      if (streak <= 364) return 375;
      if (streak === 365) return 1500;
      return 450;
    }

    return 0;
  }

  function getCompoundMotivation(streak) {
    if (streak >= 366) return 'You are the Compound Effect personified.';
    if (streak === 365) return 'One full year. You have fully awakened.';
    if (streak === 180) return 'Six months. You are not the same person who started.';
    if (streak === 90)  return 'Ninety days. Science says this change is now permanent.';
    if (streak === 30)  return 'Thirty days. This is no longer a habit. This is your identity.';
    if (streak === 14)  return 'Two weeks strong. This is becoming who you are.';
    if (streak === 7)   return 'One week of excellence. Your brain is rewiring.';
    return 'The compound effect has begun.';
  }

  // W597 — the escalating compound-XP curve (getCompoundXP) is a real reward
  // loop, but it was invisible: a user saw "Day 12" with no sense of what the
  // next milestone pays or how close it is. Given the current streak, returns the
  // NEXT day at which the daily compound payout steps up, its XP, and how far
  // away it is — so the climb has a visible target. null when the pack has no
  // compound curve (custom) or the streak is already past the final milestone.
  function _nextStreakMilestone(packId, streak) {
    const MS = [7, 14, 30, 90, 180, 365];
    const s = (typeof streak === 'number' && streak > 0) ? streak : 0;
    for (let i = 0; i < MS.length; i++) {
      if (MS[i] > s) {
        const xp = getCompoundXP(packId, MS[i]);
        if (!xp) return null;            // no compound curve for this pack
        return { day: MS[i], xp: xp, daysAway: MS[i] - s };
      }
    }
    return null;                          // past the final milestone (maxed)
  }

  function getPackHabitNames(packId) {
    const pack = PACKS.find(p => p.id === packId);
    if (!pack || !pack.habits || !pack.habits.length) return [];
    return pack.habits.map(i => DEFAULT_HABITS[i].name);
  }

  function getPackProgress(packId) {
    const names = getPackHabitNames(packId);
    const owned = names.filter(n => {
      const h = habits.find(hh => hh.name === n);
      return h && isScheduledToday(h);
    });
    const done = owned.filter(n => {
      const h = habits.find(hh => hh.name === n);
      return h && isChecked(h.id);
    });
    return { done: done.length, total: owned.length };
  }

  // Bonus-popup queue — guarantees Locked-In's modal never overlaps the
  // Compound Effect modal. Items are { packId, newStreak, finalXP, doubled }.
  let _bonusPopupQueue  = [];
  let _bonusPopupActive = false;

  // W459 — graded partial credit helpers. compoundPartial tracks the cumulative
  // compound XP already paid for a pack TODAY (lazily reset on date rollover),
  // so the full-completion path pays only the remainder and the day always
  // totals exactly the full bonus.
  function _compoundPartialGiven(packId) {
    const e = compoundPartial[packId];
    return (e && e.date === today) ? (e.given || 0) : 0;
  }
  function _setCompoundPartialGiven(packId, given) {
    compoundPartial[packId] = { date: today, given: given };
  }
  // The full compound bonus this pack WOULD pay if completed right now — the
  // EXACT base awardCompoundEffect uses (streak-projected + weekend ×2), so the
  // partial fractions and the full remainder always reconcile to it.
  function _compoundFullBonusToday(packId) {
    const cs = compoundStreaks[packId] || { streak: 0, lastDate: null };
    const projStreak = (cs.lastDate === prevDay(today)) ? (cs.streak + 1) : 1;
    const baseXP = getCompoundXP(packId, projStreak);
    return isWeekend() ? baseXP * 2 : baseXP;
  }
  // W481 — centered, tap-to-continue NOTICE CARD. Generalized from the W477/W478
  // partial-compound nudge: a LONG / NARRATIVE / OUTCOME message belongs in the MIDDLE
  // of the screen, NOT a bottom toast that clips the text + auto-dismisses before it can
  // be read (Richie's report). Backdrop + card + a pulsing "Tap to continue" cue; NO
  // auto-dismiss; a 350ms guard so the tap that triggered it can't carry through and
  // close it. Use this (not showHabitToast) for any message the user must actually READ.
  //   opts: { icon (html: emoji/svg), amount (text), title (text),
  //           body (text) | bodyHtml (trusted html), cta (text='Tap to continue'),
  //           tone ('loss' | 'warn' | undefined=gold), onClose (fn) }
  function showNoticeCard(opts) {
    try {
      opts = opts || {};
      try { document.querySelectorAll('.notice-card-wrap').forEach(n => n.remove()); } catch (_) {}
      const wrap = document.createElement('div');
      wrap.className = 'notice-card-wrap' + (opts.tone ? ' notice-card-wrap--' + opts.tone : '');
      wrap.setAttribute('role', 'dialog');
      wrap.setAttribute('aria-live', 'polite');
      const head = (opts.icon || opts.amount)
        ? '<div class="notice-card-head">' +
            (opts.icon ? '<span class="notice-card-ic">' + opts.icon + '</span>' : '') +
            (opts.amount ? '<span class="notice-card-amt">' + esc(opts.amount) + '</span>' : '') +
          '</div>'
        : '';
      const body = opts.bodyHtml ? opts.bodyHtml : (opts.body ? esc(opts.body) : '');
      wrap.innerHTML =
        '<div class="notice-card">' + head +
          (opts.title ? '<div class="notice-card-title">' + esc(opts.title) + '</div>' : '') +
          (body ? '<div class="notice-card-body">' + body + '</div>' : '') +
          '<div class="notice-card-cont">' + esc(opts.cta || 'Tap to continue') + '</div>' +
        '</div>';
      document.body.appendChild(wrap);
      requestAnimationFrame(() => requestAnimationFrame(() => wrap.classList.add('notice-card-wrap--visible')));
      const close = () => {
        wrap.classList.remove('notice-card-wrap--visible');
        setTimeout(() => { try { wrap.remove(); } catch (_) {} if (typeof opts.onClose === 'function') { try { opts.onClose(); } catch (_) {} } }, 260);
      };
      const shownAt = Date.now();
      wrap.addEventListener('click', () => { if (Date.now() - shownAt < 350) return; close(); });
    } catch (_) {}
  }

  function _showPartialCompoundToast(packId, xp) {
    try {
      const pack = getPackById(packId);
      // W479 — the custom pack's display name ('Make Your Own') reads oddly inline;
      // call a self-built routine just "routine" in the partial nudge.
      const name = (packId === 'custom') ? 'routine' : (pack ? pack.name : 'routine');
      // W477/W478 centered nudge; W481 routes it through the shared showNoticeCard.
      showNoticeCard({
        icon:     (typeof xpIconHtml === 'function') ? xpIconHtml({ size: 26 }) : '⚡',
        amount:   '+' + xp + ' XP',
        title:    'Partial ' + name + ' bonus',
        bodyHtml: 'Finish all of them to claim the full <b>Compound Effect</b>.',
      });
    } catch (_) {}
  }

  function checkCompoundEffect(habitId) {
    const habit = habits.find(h => h.id === habitId);
    if (!habit) return;
    // Walk every bonus-eligible pack in fire-order. Each is independently
    // gated by composition + completion. Packs both can fire on the same
    // tick — the modal queue sequences their celebration popups.
    BONUS_PACK_IDS.forEach(packId => {
      if (!isHabitInPack(habit, packId)) return;
      if (compoundAwarded[packId] === today) return;        // already full-awarded today
      if (!userHasAllPackHabits(packId)) return;
      const { done, total } = getPackProgress(packId);
      if (total === 0) return;
      if (done >= total) { awardCompoundEffect(packId); return; }   // FULL — pays the remainder, streak++

      // W459 — graded partial credit. Top the day's compound credit up to
      // E(done) = fullBonusToday × factor(missing); pay only the positive delta.
      // (full path stays strictly best; perfect days net identical XP.)
      const factor = compoundPartialFactor(total - done);
      if (factor <= 0) return;                               // missing 9+ → nothing yet
      const targetCumulative = Math.round(_compoundFullBonusToday(packId) * factor);
      const alreadyGiven = _compoundPartialGiven(packId);
      const delta = targetCumulative - alreadyGiven;
      if (delta <= 0) return;                                // already credited at this (or a higher) tier
      _refundOrphanCustomCompound();                         // W479 — pack supersedes any custom credit banked earlier today (no double-dip)
      totalPoints += delta;
      _setCompoundPartialGiven(packId, targetCumulative);
      prUpdate('total_xp_lifetime', getPR('total_xp_lifetime').value + delta);
      save();
      renderRank();
      if (currentTab === 'profile') renderProfile();
      try { renderCompoundProgress(); } catch (_) {}
      // W459 — re-record the day's peak XP now that this partial is paid (check()
      // computed most_xp_day before the compound fired, so a last-tap partial
      // would otherwise be missed by the monotonic PR).
      try { prUpdate('most_xp_day', computeTodayXP()); } catch (_) {}
      if (alreadyGiven === 0) _showPartialCompoundToast(packId, delta);   // one nudge per pack per day
    });
  }

  // W602 — non-XP streak-milestone reward (owner-requested). The compound curve
  // already pays escalating XP; this layers a SOULS payout at the big identity
  // thresholds so a long streak feeds the marketplace loop, not just rank pace.
  // Amounts sit alongside boss-kill souls (E:50 … S:1600): 30d ≈ a C-kill, 90d
  // ≈ an A-kill, 365d ≈ ~2× an S-kill.
  //   Idempotency: once EVER per (pack, milestone). A broken-and-reclimbed streak
  //   does NOT re-pay — a milestone is the first time you reach it, which keeps
  //   this exploit-proof (no break/reclimb farm) and bounded per the owner's
  //   "don't touch the economy too heavily" guidance. Per-pack, so a genuine
  //   30-day streak on Morning AND on Locked-In each pays once.
  const STREAK_SOULS_MILESTONES = { 30: 300, 90: 900, 365: 3000 };
  function _maybeGrantStreakMilestoneSouls(packId, streak) {
    const amount = STREAK_SOULS_MILESTONES[streak];
    if (!amount || !packId) return 0;
    const flag = 'hb_streak_souls_v1_' + packId + '_' + streak;
    try { if (localStorage.getItem(flag) === '1') return 0; } catch (_) {}
    try { localStorage.setItem(flag, '1'); } catch (_) {}
    try { if (typeof earnSouls === 'function') earnSouls(amount, 'streak_milestone_' + streak + 'd'); }
    catch (e) { _logSwallow('streakMilestoneSouls', e); return 0; }
    return amount;
  }

  function awardCompoundEffect(packId) {
    const cs        = compoundStreaks[packId] || { streak: 0, lastDate: null };
    const yesterday = prevDay(today);
    const newStreak = cs.lastDate === yesterday ? cs.streak + 1 : 1;

    compoundStreaks[packId]  = { streak: newStreak, lastDate: today };
    compoundAwarded[packId]  = today;
    _refundOrphanCustomCompound();   // W479 — pack supersedes any custom credit banked earlier today (no double-dip on a mid-day flip into a pack)

    const baseXP    = getCompoundXP(packId, newStreak);
    const fullBonus = isWeekend() ? baseXP * 2 : baseXP;   // the full compound — what the celebration shows
    // W459 — subtract any graded partial credit already paid today so the day's
    // compound XP totals EXACTLY the full bonus (perfect days are unchanged),
    // then clear this pack's partial ledger.
    const finalXP   = Math.max(0, fullBonus - _compoundPartialGiven(packId)); // remainder added now
    _setCompoundPartialGiven(packId, 0);
    totalPoints    += finalXP;   // W461 — compound is EXEMPT from the daily cap (bounded, not a farm vector; protects pack + spike-day loyalty)

    save();
    renderRank();
    if (currentTab === 'profile') renderProfile();
    renderCompoundProgress();
    // W459 — re-record the day's peak XP now the full compound is paid (check()
    // ran most_xp_day before this fired); compoundAwarded is already set above.
    try { prUpdate('most_xp_day', computeTodayXP()); } catch (_) {}

    // W484 — shields are no longer earned here; they're earned from DAYS ACTIVE
    // (tryEarnActivityShield in check()) into a single global pool. The pack streak still
    // drives the compound bonus + is what processStreakRollover protects.

    // ── Personal Records hooks for pack streaks + lifetime XP ─────
    prUpdate('total_xp_lifetime', getPR('total_xp_lifetime').value + finalXP);
    if (packId === 'morning')   prUpdate('longest_mr_streak', newStreak);
    if (packId === 'locked-in') prUpdate('longest_li_streak', newStreak);

    // W602 — grant milestone souls (once per pack/milestone) and let the
    // celebration show them alongside the XP.
    const _msSouls = _maybeGrantStreakMilestoneSouls(packId, newStreak);

    // Queue instead of show-now so multiple packs sequence cleanly.
    _bonusPopupQueue.push({
      packId,
      newStreak,
      finalXP: fullBonus,              // W459 — celebration shows the FULL compound, not the remainder
      doubled: isWeekend(),
      milestoneSouls: _msSouls,        // W602 — souls milestone bonus (0 if none)
    });
    drainBonusPopupQueue();
  }

  // ── W479 — CUSTOM-PATH COMPOUND ──────────────────────────────────
  // The pack Compound Effect rewards consistency, but a user who builds their OWN
  // routine matches no preset pack and earned ZERO compound — the two-tier economy
  // gap (pack users reach S+ ~45d, custom-path ~1,400d). This pays a daily compound
  // for completing a SELF-BUILT routine, on the SAME Morning streak curve, scaled by
  // routine size (full Morning rate at 10+ habits, proportionally less below, capped
  // there — the curated Locked-In cycle stays the premium). It is SELF-CONTAINED:
  // reuses the generic compoundStreaks/Awarded/Partial['custom'] ledgers (already
  // persisted) and mirrors checkCompoundEffect's W459 graded partial credit so a
  // near-complete custom day never pays zero (no re-introduced compound cliff).
  // Fires ONLY when the user is NOT on a preset pack (no double-dip) and runs a
  // routine of >= CUSTOM_COMPOUND_MIN_HABITS scheduled habits.
  const CUSTOM_COMPOUND_PACK_ID    = 'custom';
  const CUSTOM_COMPOUND_MIN_HABITS = 3;

  // True when the user already earns a preset-pack compound — in which case the
  // custom path stands down so the two never both pay (no double-dip).
  function _onPresetPack() {
    return userHasAllPackHabits('morning') || userHasAllPackHabits('locked-in');
  }
  // Today's self-built routine = all habits scheduled today; done = those checked.
  function _customRoutineProgress() {
    const todayHabits = habits.filter(isScheduledToday);
    const done = todayHabits.filter(h => isChecked(h.id)).length;
    return { done, total: todayHabits.length };
  }
  // W485 — average difficulty (pts) of the scheduled routine, for the compound difficulty tilt.
  // easy 1 / medium 3 / hard 5 / legendary 10; medium (3) is the rebalance pivot (factor 1.0).
  function _customRoutineAvgDifficulty() {
    const sched = habits.filter(isScheduledToday);
    if (!sched.length) return 3;   // medium baseline -> factor 1.0 (neutral)
    let sum = 0;
    sched.forEach(h => { sum += ((DIFFICULTY[h.difficulty || 'easy'] || DIFFICULTY.easy).pts || 0); });
    return sum / sched.length;
  }
  // The full custom compound this routine WOULD pay if completed right now — the EXACT base
  // awardCustomRoutineCompound uses (streak-projected Morning curve × size factor × difficulty
  // factor × weekend), so partial fractions + the full remainder reconcile to it.
  function _customFullBonusToday(size) {
    const cs = compoundStreaks[CUSTOM_COMPOUND_PACK_ID] || { streak: 0, lastDate: null };
    const projStreak = (cs.lastDate === prevDay(today)) ? (cs.streak + 1) : 1;
    const baseXP = Math.round(getCompoundXP('morning', projStreak) * AwakenedEconomy.customCompoundSizeFactor(size) * AwakenedEconomy.customCompoundDifficultyFactor(_customRoutineAvgDifficulty()));
    return isWeekend() ? baseXP * 2 : baseXP;
  }

  // W479 review fix — pack compound SUPERSEDES the custom-path compound. If the user
  // banked custom credit earlier today (a partial, OR a full award) and THEN completes a
  // preset pack, that custom credit is orphaned — refund it so the day nets EXACTLY the
  // pack compound, never both (covers a mid-day flip INTO a pack). The custom path's own
  // latch (below) covers the reverse flip OUT of a pack; both sides are required because
  // either compound can pay first. Called from the pack payment paths.
  function _refundOrphanCustomCompound() {
    const orphan = _compoundPartialGiven(CUSTOM_COMPOUND_PACK_ID);
    if (orphan > 0) {
      totalPoints = Math.max(0, totalPoints - orphan);
      _setCompoundPartialGiven(CUSTOM_COMPOUND_PACK_ID, 0);
      compoundAwarded[CUSTOM_COMPOUND_PACK_ID] = null;   // a superseded custom day is no longer an awarded custom day
      // W479 review fix — if a FULL custom routine was awarded today (streak advanced
      // with the prev snapshot), roll the streak back too, so a pack-superseded day does
      // NOT leave the custom streak inflated (which would pay the next custom-only day at
      // a higher tier). Partial-only orphans never advanced the streak (no prevStreak /
      // lastDate!==today), so this correctly no-ops there.
      const ccs = compoundStreaks[CUSTOM_COMPOUND_PACK_ID];
      if (ccs && ccs.lastDate === today) {
        if (Object.prototype.hasOwnProperty.call(ccs, 'prevStreak')) {
          // W479 snapshot present — exact rollback of the custom STREAK so a milestone day that
          // got superseded by a pack doesn't leave the streak inflated. (W484: shields are no
          // longer earned in the award — global activity pool — so there's nothing to roll back.)
          compoundStreaks[CUSTOM_COMPOUND_PACK_ID] = { streak: ccs.prevStreak || 0, lastDate: ccs.prevLastDate || null };
        } else {
          // W482 — pre-W482 save mid-pack-flip: a full custom award advanced the streak today
          // (newStreak = prev+1) but no prevStreak was snapshotted, so the W479 guard used to
          // SKIP the rollback and leave the streak inflated. Reconstruct the pre-award value as
          // streak-1 (the award's own +1) and drop lastDate so the next custom award re-evaluates
          // continuity cleanly. Neutralizes the inflation; fully inside the persisted ledger
          // (reload-safe — NOT a module-var snapshot).
          compoundStreaks[CUSTOM_COMPOUND_PACK_ID] = { streak: Math.max(0, (ccs.streak || 0) - 1), lastDate: null };
        }
      }
    }
  }

  function checkCustomRoutineCompound() {
    try {
      if (_onPresetPack()) return;                                   // pack users already covered — no double-dip
      // Symmetric day-scoped latch (review fix): _onPresetPack() is a point-in-time read
      // of MUTABLE habit composition. If a preset pack has already PAID or partially paid
      // today, the custom path must stand down for the rest of the day even if the user
      // then drops a pack habit (flipping _onPresetPack() back to false) — otherwise a
      // full custom compound stacks on the already-latched pack compound.
      if (compoundAwarded['morning'] === today || compoundAwarded['locked-in'] === today) return;
      if (_compoundPartialGiven('morning') > 0 || _compoundPartialGiven('locked-in') > 0) return;
      if (compoundAwarded[CUSTOM_COMPOUND_PACK_ID] === today) return;// already full-awarded today
      const { done, total } = _customRoutineProgress();
      if (total < CUSTOM_COMPOUND_MIN_HABITS) return;                // not a routine
      if (done <= 0) return;
      if (done >= total) { awardCustomRoutineCompound(total); return; } // FULL — reconciles + streak++

      // W459-parity graded partial credit, RECONCILED to the CURRENT routine size on every
      // tick: target = fullBonusToday(size) × factor(done/size). Pay the positive delta; if
      // the routine SHRANK since an earlier partial (target now lower — a larger partial was
      // banked at a bigger size factor), claw the excess back so the banked credit always
      // matches what the CURRENT routine warrants (no inflate-then-shrink overpay). The
      // ledger thus always holds the exact custom XP paid today.
      const factor = AwakenedEconomy.customCompoundPartialFactor(done, total);
      const targetCumulative = factor > 0 ? Math.round(_customFullBonusToday(total) * factor) : 0;
      const alreadyGiven = _compoundPartialGiven(CUSTOM_COMPOUND_PACK_ID);
      const delta = targetCumulative - alreadyGiven;
      if (delta === 0) return;                                       // already at the warranted tier
      totalPoints = Math.max(0, totalPoints + delta);                // delta < 0 = shrink clawback
      _setCompoundPartialGiven(CUSTOM_COMPOUND_PACK_ID, targetCumulative);
      if (delta > 0) prUpdate('total_xp_lifetime', getPR('total_xp_lifetime').value + delta);
      save();
      renderRank();
      if (currentTab === 'profile') renderProfile();
      try { renderCompoundProgress(); } catch (_) {}
      try { prUpdate('most_xp_day', computeTodayXP()); } catch (_) {}
      if (delta > 0 && alreadyGiven === 0) _showPartialCompoundToast(CUSTOM_COMPOUND_PACK_ID, delta); // one nudge per day
    } catch (e) { _logSwallow('checkCustomRoutineCompound', e); }   // W491 — a throw here silently drops compound XP (~90% of rank XP)
  }

  function awardCustomRoutineCompound(size) {
    const cs        = compoundStreaks[CUSTOM_COMPOUND_PACK_ID] || { streak: 0, lastDate: null };
    const yesterday = prevDay(today);
    const newStreak = cs.lastDate === yesterday ? cs.streak + 1 : 1;

    // W479 review fix — carry the PRE-award streak so _refundOrphanCustomCompound can
    // roll it back if a preset pack later supersedes this day (else a refunded full-custom
    // day would still advance the streak, paying the next custom-only day at an inflated
    // tier). Embedded in the persisted compoundStreaks entry (survives a mid-day reload),
    // mirroring perfectStreak's prevCount/prevLastDate pattern.
    compoundStreaks[CUSTOM_COMPOUND_PACK_ID] = {
      streak: newStreak, lastDate: today,
      prevStreak: cs.streak || 0, prevLastDate: cs.lastDate || null,
    };
    compoundAwarded[CUSTOM_COMPOUND_PACK_ID] = today;

    const baseXP    = Math.round(getCompoundXP('morning', newStreak) * AwakenedEconomy.customCompoundSizeFactor(size) * AwakenedEconomy.customCompoundDifficultyFactor(_customRoutineAvgDifficulty()));
    const fullBonus = isWeekend() ? baseXP * 2 : baseXP;
    // Reconcile to EXACTLY fullBonus at the CURRENT routine size. The remainder is
    // normally positive (the full path tops up any graded partial already paid today, so
    // a perfect day nets fullBonus). It can be NEGATIVE if a larger partial was banked
    // earlier today and the routine then SHRANK (size factor dropped) — then we claw the
    // excess back so an inflate-then-shrink can never bank more than the final routine
    // warrants. The ledger KEEPS the exact amount paid (not cleared to 0) so computeTodayXP
    // reads it instead of re-deriving from a mutable live size.
    const alreadyPaid = _compoundPartialGiven(CUSTOM_COMPOUND_PACK_ID);
    const remainder   = fullBonus - alreadyPaid;
    totalPoints = Math.max(0, totalPoints + remainder);   // compound is EXEMPT from the daily cap (matches packs); remainder<0 = shrink clawback
    _setCompoundPartialGiven(CUSTOM_COMPOUND_PACK_ID, fullBonus);

    save();
    renderRank();
    if (currentTab === 'profile') renderProfile();
    renderCompoundProgress();
    try { prUpdate('most_xp_day', computeTodayXP()); } catch (_) {}
    if (remainder > 0) prUpdate('total_xp_lifetime', getPR('total_xp_lifetime').value + remainder);

    // W484 — shields are earned from DAYS ACTIVE (global pool) in check(), not per routine
    // completion. processStreakRollover (FORGIVENESS_PACK_IDS incl 'custom') still CONSUMES a
    // shield to forgive a missed custom day, so the custom path stays a true peer of the packs.

    // W602 — self-built routines earn the same streak-milestone souls (once per
    // 'custom' pack/milestone) so custom-path users aren't excluded.
    const _msSoulsCustom = _maybeGrantStreakMilestoneSouls(CUSTOM_COMPOUND_PACK_ID, newStreak);

    _bonusPopupQueue.push({
      packId:    CUSTOM_COMPOUND_PACK_ID,
      newStreak,
      finalXP:   fullBonus,        // celebration shows the FULL compound, not the remainder
      doubled:   isWeekend(),
      milestoneSouls: _msSoulsCustom,   // W602
    });
    drainBonusPopupQueue();
  }

  function drainBonusPopupQueue() {
    if (_bonusPopupActive || !_bonusPopupQueue.length) return;
    const item = _bonusPopupQueue.shift();
    _bonusPopupActive = true;
    showCompoundPopup(item.packId, item.newStreak, item.finalXP, item.doubled, item.milestoneSouls);
  }

  function showCompoundPopup(packId, streak, xp, doubled, milestoneSouls) {
    const pack = getPackById(packId);
    if (!pack) { _bonusPopupActive = false; return; }
    const isLockedIn = packId === 'locked-in';
    const isCustom   = packId === CUSTOM_COMPOUND_PACK_ID;   // W479 — self-built routine

    // Pack-specific copy
    const labelEl = document.getElementById('cp-label');
    if (labelEl) labelEl.innerHTML = iconify(pack.bonusLabel || '⚡ COMPOUND EFFECT BONUS', { size: 22 });
    document.getElementById('cp-pack-msg').textContent =
      isLockedIn
        ? 'All 16 habits complete. You owned the day.'
        : isCustom
          ? 'Your whole routine, complete. The compound effect is yours.'
          : 'All ' + pack.name + ' habits complete!';
    document.getElementById('cp-xp').textContent     = '+' + xp + ' XP' + (doubled ? ' 2×' : '');
    // W602 — milestone souls line: only on a 30/90/365 threshold day (else hidden).
    try {
      const soulsEl = document.getElementById('cp-souls');
      if (soulsEl) {
        if (typeof milestoneSouls === 'number' && milestoneSouls > 0) {
          soulsEl.innerHTML = '<img class="cp-souls-icon" src="assets/icons/souls-icon.png" alt="" draggable="false" decoding="async">' +
            '<span>+' + milestoneSouls.toLocaleString('en-US') + ' Souls · Milestone Reward</span>';
          soulsEl.classList.remove('hidden');
        } else {
          soulsEl.textContent = '';
          soulsEl.classList.add('hidden');
        }
      }
    } catch (_) {}
    document.getElementById('cp-streak').innerHTML = streakify('Day ' + streak + ' in a row 🔥', 18);
    document.getElementById('cp-motivation').textContent = getCompoundMotivation(streak);

    const el = document.getElementById('compound-popup');
    // Theme the popup per pack (gold for MR, violet for Locked-In).
    el.classList.remove('cp--morning', 'cp--lockedin');
    el.classList.add(isLockedIn ? 'cp--lockedin' : 'cp--morning');

    el.classList.remove('hidden', 'cp-hide');
    void el.offsetWidth; // force reflow so animation replays
    el.classList.add('cp-show');
    // Pack-specific fanfare. Locked-In gets an extended flourish
    // because it's the bigger achievement.
    if (isLockedIn && typeof playFanfareLockedIn === 'function') {
      playFanfareLockedIn();
    } else {
      playFanfare();
    }
    if (compoundPopupTimer) clearTimeout(compoundPopupTimer);
    compoundPopupTimer = setTimeout(hideCompoundPopup, 3000);
  }

  function hideCompoundPopup() {
    const el = document.getElementById('compound-popup');
    el.classList.remove('cp-show');
    el.classList.add('cp-hide');
    el.addEventListener('animationend', () => {
      el.classList.remove('cp-hide');
      el.classList.add('hidden');
      // Now drain any queued bonuses (e.g., Locked-In after MR).
      _bonusPopupActive = false;
      // Small delay for breathing room between celebrations
      setTimeout(drainBonusPopupQueue, 320);
    }, { once: true });
    if (compoundPopupTimer) { clearTimeout(compoundPopupTimer); compoundPopupTimer = null; }
  }

  function setupCompoundPopup() {
    document.getElementById('compound-popup').addEventListener('click', hideCompoundPopup);
    // Delegated tap on a pack progress row → opens the Add Pack modal
    // for the matching pack so users can fill in the missing habits.
    // The ⚡ bolt and 🌙/🛡️ chips inside the row stop propagation via
    // their own handlers, so chip-tap doesn't trigger this row click.
    document.addEventListener('click', e => {
      const t = e.target;
      if (!t || !t.closest) return;
      // Honest Day chip
      const honest = t.closest('[data-honest-pack]');
      if (honest) {
        e.preventDefault();
        e.stopPropagation();
        openHonestDayModal(honest.getAttribute('data-honest-pack'));
        return;
      }
      // Shield info chip
      const shield = t.closest('[data-shield-info]');
      if (shield) {
        e.preventDefault();
        e.stopPropagation();
        openShieldInfoModal();
        return;
      }
      // Skip if the bolt was tapped (its handler runs first)
      if (t.closest('[data-bonus-info]')) return;
      const row = t.closest('[data-pack-add]');
      if (!row) return;
      e.preventDefault();
      e.stopPropagation();
      const packId = row.getAttribute('data-pack-add');
      if (packId === 'morning')   openMorningPackModal();
      else if (packId === 'locked-in') openLockedInPackModal();
    });
  }

  // ── setupOriginStorySheet — STALE NAME, LIVE CONTENTS. The origin
  // sheet itself was removed in the 2026-06-12 live flagged-item session
  // (Richie verdict: dead memory — its opener was orphaned long ago).
  // What remains is the DELEGATED ARENA-BUTTON OPENER that historically
  // lived here (the old comment claimed "Your Origin" — the code always
  // targeted #sc-arena-btn). Name kept so init order doesn't change;
  // rename candidate for a future pass.
  function setupOriginStorySheet() {
    // Delegated click — main-screen Arena button (#sc-arena-btn)
    document.addEventListener('click', e => {
      const t = e.target;
      if (!t || !t.closest) return;
      if (t.closest('#sc-pvp-btn')) {           // W488 — home-screen Ranked PvP entry
        e.preventDefault(); e.stopPropagation();
        try { openArenaPvP(); } catch (_) {}
        return;
      }
      const btn = t.closest('#sc-arena-btn');
      if (!btn) return;
      e.preventDefault();
      e.stopPropagation();
      try { openArena(); } catch (_) {}
    });
  }

  // ── HONEST DAY modal ─────────────────────────────────────
  let _honestPackPending = null;
  function openHonestDayModal(packId) {
    if (!canMarkHonestDayToday(packId)) return;
    _honestPackPending = packId;
    const pack = getPackById(packId);
    // W482 — the custom pack's display name ('Make Your Own') reads oddly inline; call a
    // self-built routine "your routine" in the Honest-Rest modal.
    const packName = (packId === 'custom') ? 'your routine' : (pack ? pack.name : packId);
    const remainingThisMonth = 1 - getHonestDayUsesThisMonth(packId); // always 1 when canMark is true
    document.getElementById('hm-body').innerHTML =
      "You'll skip <b>" + esc(packName) + "</b> today without breaking your streak. " +
      "Honest about what happened. <b>" + remainingThisMonth + "</b> use" +
      (remainingThisMonth === 1 ? '' : 's') + " left this month.";
    document.getElementById('honest-overlay').classList.remove('hidden');
    document.getElementById('honest-modal').classList.remove('hidden');
  }
  function closeHonestDayModal() {
    document.getElementById('honest-overlay').classList.add('hidden');
    document.getElementById('honest-modal').classList.add('hidden');
    _honestPackPending = null;
  }
  function confirmHonestDay() {
    if (!_honestPackPending) { closeHonestDayModal(); return; }
    const ok = markTodayAsHonestDay(_honestPackPending);
    closeHonestDayModal();
    // W481 — centered tap-to-continue card; a deliberate ritual moment, not a flash.
    if (ok) {
      try { showNoticeCard({ icon: '🌙', title: 'Honest Rest day', body: 'Your streak is held.' }); } catch (_) {}
    }
    if (currentTab === 'habits')   renderCompoundProgress();
    if (currentTab === 'profile')  renderProfile();
  }
  function setupHonestDayModal() {
    const cancel = document.getElementById('hm-cancel');
    const confirm = document.getElementById('hm-confirm');
    const overlay = document.getElementById('honest-overlay');
    if (cancel)  cancel.addEventListener('click', closeHonestDayModal);
    if (confirm) confirm.addEventListener('click', confirmHonestDay);
    if (overlay) overlay.addEventListener('click', closeHonestDayModal);
  }

  // ── SHIELD INFO modal ────────────────────────────────────
  function openShieldInfoModal() {
    document.getElementById('shield-overlay').classList.remove('hidden');
    document.getElementById('shield-modal').classList.remove('hidden');
  }
  function closeShieldInfoModal() {
    document.getElementById('shield-overlay').classList.add('hidden');
    document.getElementById('shield-modal').classList.add('hidden');
  }
  function setupShieldInfoModal() {
    const close = document.getElementById('sm-close');
    const ok    = document.getElementById('sm-ok');
    const ov    = document.getElementById('shield-overlay');
    if (close) close.addEventListener('click', closeShieldInfoModal);
    if (ok)    ok.addEventListener('click', closeShieldInfoModal);
    if (ov)    ov.addEventListener('click', closeShieldInfoModal);
  }

  // ── BONUS INFO POPUP ─────────────────────────────────────
  // Tapping the ⚡ on any pack progress row opens this popup. It explains
  // the Compound Effect XP tier formula AND the ROI rationale for both
  // Morning Routine and Locked-In packs.
  function openBonusInfoPopup() {
    const ov = document.getElementById('bonus-info-overlay');
    const md = document.getElementById('bonus-info-modal');
    if (!ov || !md) return;
    // Populate live shield + honest-day counts so users see their current state
    const shieldEl = document.getElementById('bi-shield-counts');
    if (shieldEl) {
      // W484 — shields are a single global pool now (earned from days-active), so show one count.
      shieldEl.innerHTML = '<span class="bi-stat-pill">🛡️ ' + (streakShields || 0) + '/' + SHIELD_MAX + ' shields</span>';
    }
    const honestEl = document.getElementById('bi-honest-counts');
    if (honestEl) {
      const mrUsed = getHonestDayUsesThisMonth('morning');
      const liUsed = getHonestDayUsesThisMonth('locked-in');
      const monthLabel = (function() {
        try { return new Date(today + 'T12:00:00').toLocaleDateString('en-US', { month: 'long' }); }
        catch (_) { return 'this month'; }
      })();
      honestEl.innerHTML =
        '<span class="bi-stat-pill">🌅 ' + (mrUsed ? 'used' : 'available') + '</span>' +
        '<span class="bi-stat-pill">🔒 ' + (liUsed ? 'used' : 'available') + '</span>' +
        '<span class="bi-stat-pill bi-stat-pill--quiet">' + monthLabel + '</span>';
    }
    ov.classList.remove('hidden');
    md.classList.remove('hidden');
  }
  function closeBonusInfoPopup() {
    const ov = document.getElementById('bonus-info-overlay');
    const md = document.getElementById('bonus-info-modal');
    if (!ov || !md) return;
    ov.classList.add('hidden');
    md.classList.add('hidden');
  }
  // ── PERSONAL RECORDS — detail popup, celebrations, queue ───
  function _prMetaSummary(prId, meta) {
    if (!meta) return '';
    if (prId === 'longest_habit_streak' && meta.habitName) return meta.habitName;
    if (prId === 'longest_stat_streak'  && meta.statId)    {
      const stat = STATS.find(s => s.id === meta.statId);
      return stat ? stat.icon + ' ' + stat.name : meta.statId;
    }
    return '';
  }

  function _prBeatHint(prId, value) {
    if (prId === 'highest_rank') {
      const idx = RANKS.findIndex(r => r.id === value);
      const next = (idx >= 0 && idx < RANKS.length - 1) ? RANKS[idx + 1].id : null;
      return next ? 'Reach ' + next + ' rank to break this.' : 'Max rank achieved — nothing left to beat.';
    }
    const v = Number(value) || 0;
    return 'Beat: ' + (v + 1).toLocaleString();
  }

  function openPRDetailSheet(prId) {
    const def = getPRDef(prId);
    if (!def) return;
    const rec   = personalRecords[prId] || { value: 0, meta: null, lastUpdated: null };
    const accent = _prTileAccent(def);
    const sheet = document.getElementById('pr-detail-sheet');
    const ov    = document.getElementById('pr-detail-overlay');
    if (!sheet || !ov) return;

    sheet.style.setProperty('--pr-accent', accent);
    document.getElementById('pr-detail-icon').textContent  = def.icon;
    document.getElementById('pr-detail-title').textContent = def.description;
    document.getElementById('pr-detail-value').textContent = _formatPRValue(prId, rec.value);
    const metaSummary = _prMetaSummary(prId, rec.meta);
    document.getElementById('pr-detail-meta').textContent = metaSummary
      ? metaSummary + (rec.lastUpdated ? '  ·  set ' + rec.lastUpdated : '')
      : (rec.lastUpdated ? 'Set ' + rec.lastUpdated : 'Not yet set');
    document.getElementById('pr-detail-desc').textContent       = '';
    document.getElementById('pr-detail-motivation').textContent = def.motivation;
    document.getElementById('pr-detail-beat').textContent       = _prBeatHint(prId, rec.value);

    ov.classList.remove('hidden');
    sheet.classList.remove('hidden');
  }

  function closePRDetailSheet() {
    document.getElementById('pr-detail-overlay').classList.add('hidden');
    document.getElementById('pr-detail-sheet').classList.add('hidden');
  }

  // ── ALL-PR SHEET — opens from the Status tab button ───────
  function openPRAllSheet() {
    const ov    = document.getElementById('pr-all-overlay');
    const sheet = document.getElementById('pr-all-sheet');
    const grid  = document.getElementById('pr-all-grid');
    if (!ov || !sheet || !grid) return;
    grid.innerHTML = buildAllPRTilesHTML();
    ov.classList.remove('hidden');
    sheet.classList.remove('hidden');
  }
  function closePRAllSheet() {
    document.getElementById('pr-all-overlay').classList.add('hidden');
    document.getElementById('pr-all-sheet').classList.add('hidden');
  }

  function setupPRDetailSheet() {
    const ov     = document.getElementById('pr-detail-overlay');
    const sheet  = document.getElementById('pr-detail-sheet');
    const close  = document.getElementById('pr-detail-close');
    const allOv    = document.getElementById('pr-all-overlay');
    const allSheet = document.getElementById('pr-all-sheet');
    const allClose = document.getElementById('pr-all-close');

    if (ov)    ov.addEventListener('click', closePRDetailSheet);
    if (close) close.addEventListener('click', closePRDetailSheet);
    if (allOv)    allOv.addEventListener('click', closePRAllSheet);
    if (allClose) allClose.addEventListener('click', closePRAllSheet);

    // Delegated taps:
    //   - #pr-open-btn (Status-tab button) → opens the All-PRs grid sheet
    //   - any [data-pr-id] tile → opens the per-PR detail sheet
    document.addEventListener('click', e => {
      const t = e.target;
      if (!t || !t.closest) return;
      const opener = t.closest('#pr-open-btn');
      if (opener) {
        e.stopPropagation();
        e.preventDefault();
        openPRAllSheet();
        return;
      }
      const tile = t.closest('[data-pr-id]');
      if (!tile) return;
      e.stopPropagation();
      e.preventDefault();
      const prId = tile.getAttribute('data-pr-id');
      // STACK the detail sheet on top of the All-PRs sheet (don't close
      // the parent). Closing the detail then leaves the user on the
      // All-PRs grid, which is what they expect when navigating back.
      openPRDetailSheet(prId);
    });

    // Swipe-down dismiss for both sheets
    if (sheet && ov && typeof attachSheetDismissGesture === 'function') {
      attachSheetDismissGesture(sheet, ov, () => {
        sheet.classList.add('hidden');
        ov.classList.add('hidden');
      }, {
        baseTransform:  'translateX(-50%) ',
        handleSelector: '.pr-drag-handle, .pr-detail-header',
        scrollTarget:   '.pr-detail-body',
      });
    }
    if (allSheet && allOv && typeof attachSheetDismissGesture === 'function') {
      attachSheetDismissGesture(allSheet, allOv, () => {
        allSheet.classList.add('hidden');
        allOv.classList.add('hidden');
      }, {
        baseTransform:  'translateX(-50%) ',
        handleSelector: '.pr-drag-handle, .pr-all-header',
        scrollTarget:   '.pr-all-grid',
      });
    }

    document.addEventListener('keydown', e => {
      if (e.key !== 'Escape') return;
      // Close the topmost sheet only — detail is stacked above All-PRs,
      // so close detail first; only close All-PRs if detail isn't open.
      if (sheet && !sheet.classList.contains('hidden')) {
        closePRDetailSheet();
      } else if (allSheet && !allSheet.classList.contains('hidden')) {
        closePRAllSheet();
      }
    });
  }

  // ── PR celebration sounds (Web Audio, distinct from fanfare) ──
  function playPRChime() {
    if (!soundEnabled) return;
    try {
      const ac = new (window.AudioContext || window.webkitAudioContext)();
      const t0 = ac.currentTime;
      // E5 → G5 → B5 quick uplift
      const notes = [659.25, 783.99, 987.77];
      notes.forEach((freq, i) => {
        ['sine', 'triangle'].forEach(type => {
          const osc = ac.createOscillator();
          const gain = ac.createGain();
          osc.type = type;
          osc.frequency.setValueAtTime(freq, t0 + i * 0.08);
          osc.connect(gain);
          gain.connect(ac.destination);
          const peak = type === 'sine' ? 0.18 : 0.08;
          gain.gain.setValueAtTime(0.0001, t0 + i * 0.08);
          gain.gain.exponentialRampToValueAtTime(peak, t0 + i * 0.08 + 0.02);
          gain.gain.exponentialRampToValueAtTime(0.0001, t0 + i * 0.08 + 0.30);
          osc.start(t0 + i * 0.08);
          osc.stop(t0 + i * 0.08 + 0.32);
        });
      });
    } catch (_) {}
  }

  function playPRTakeover() {
    if (!soundEnabled) return;
    try {
      const ac = new (window.AudioContext || window.webkitAudioContext)();
      const t0 = ac.currentTime;
      // Cinematic ascent: D4 → A4 → D5 → A5 sustained
      const notes = [
        { f: 293.66, s: 0.00, d: 0.30, p: 0.22 },
        { f: 440.00, s: 0.20, d: 0.30, p: 0.22 },
        { f: 587.33, s: 0.40, d: 0.50, p: 0.26 },
        { f: 880.00, s: 0.60, d: 1.20, p: 0.28 },
      ];
      notes.forEach(n => {
        ['sine', 'triangle'].forEach(type => {
          const osc = ac.createOscillator();
          const gain = ac.createGain();
          osc.type = type;
          osc.frequency.setValueAtTime(n.f, t0 + n.s);
          osc.connect(gain);
          gain.connect(ac.destination);
          const peak = type === 'sine' ? n.p : n.p * 0.5;
          gain.gain.setValueAtTime(0.0001, t0 + n.s);
          gain.gain.exponentialRampToValueAtTime(peak, t0 + n.s + 0.04);
          gain.gain.exponentialRampToValueAtTime(0.0001, t0 + n.s + n.d);
          osc.start(t0 + n.s);
          osc.stop(t0 + n.s + n.d + 0.05);
        });
      });
    } catch (_) {}
  }

  // ── Celebration display + queue ────────────────────────────
  function showPRTier2Modal(item) {
    const def = getPRDef(item.prId);
    if (!def) { _prCelebrationActive = false; drainPRCelebrationQueue(); return; }
    const accent = _prTileAccent(def);
    const popup  = document.getElementById('pr-popup');
    if (!popup) { _prCelebrationActive = false; drainPRCelebrationQueue(); return; }
    popup.style.setProperty('--pr-accent', accent);
    document.getElementById('pr-popup-icon').textContent  = def.icon;
    document.getElementById('pr-popup-title').textContent = def.description;
    document.getElementById('pr-popup-value').textContent = _formatPRValue(item.prId, item.newValue);
    const prevTxt = (item.prevValue && item.prevValue > 0)
      ? 'Previous: ' + _formatPRValue(item.prId, item.prevValue)
      : 'Your first record. Set the bar.';
    document.getElementById('pr-popup-prev').textContent = prevTxt;
    popup.classList.remove('hidden');
    void popup.offsetWidth;
    popup.classList.add('pr-popup--show');
    playPRChime();

    const dismiss = () => {
      popup.classList.remove('pr-popup--show');
      popup.classList.add('pr-popup--hide');
      popup.addEventListener('animationend', () => {
        popup.classList.remove('pr-popup--hide');
        popup.classList.add('hidden');
        _prCelebrationActive = false;
        setTimeout(drainPRCelebrationQueue, 260);
      }, { once: true });
      popup.removeEventListener('click', dismiss);
    };
    popup.addEventListener('click', dismiss);
    setTimeout(dismiss, 3200);
  }

  function showPRTier3Takeover(item) {
    const def = getPRDef(item.prId);
    if (!def) { _prCelebrationActive = false; drainPRCelebrationQueue(); return; }
    const accent  = _prTileAccent(def);
    const overlay = document.getElementById('pr-takeover');
    if (!overlay) { _prCelebrationActive = false; drainPRCelebrationQueue(); return; }
    overlay.style.setProperty('--pr-accent', accent);

    let headline = '';
    let sub = def.motivation;
    if (item.prId === 'longest_mr_streak')      headline = item.newValue + '-DAY MORNING ROUTINE';
    else if (item.prId === 'longest_li_streak') headline = item.newValue + '-DAY LOCKED-IN';
    else if (item.prId === 'highest_rank')      headline = item.newValue + ' RANK';
    else                                        headline = String(item.newValue) + ' ' + def.label.toUpperCase();

    document.getElementById('pr-takeover-headline').textContent = headline;
    document.getElementById('pr-takeover-sub').textContent      = sub;

    overlay.classList.remove('hidden');
    void overlay.offsetWidth;
    overlay.classList.add('pr-takeover--show');
    playPRTakeover();

    const dismiss = () => {
      overlay.classList.remove('pr-takeover--show');
      overlay.classList.add('pr-takeover--hide');
      overlay.addEventListener('animationend', () => {
        overlay.classList.remove('pr-takeover--hide');
        overlay.classList.add('hidden');
        _prCelebrationActive = false;
        setTimeout(drainPRCelebrationQueue, 320);
      }, { once: true });
      overlay.removeEventListener('click', dismiss);
    };
    overlay.addEventListener('click', dismiss);
    setTimeout(dismiss, 5000);
  }

  function drainPRCelebrationQueue() {
    if (_prCelebrationActive || !_prCelebrationQueue.length) return;
    // Don't fire PR celebrations until any queued bonus popups have finished.
    if (_bonusPopupActive || (_bonusPopupQueue && _bonusPopupQueue.length)) {
      setTimeout(drainPRCelebrationQueue, 400);
      return;
    }
    _prCelebrationActive = true;
    const item = _prCelebrationQueue.shift();
    const def  = getPRDef(item.prId);
    if (item.mode === 'tier1' || (def && def.tier === 1)) {
      // Tier 1 toast
      const valStr = _formatPRValue(item.prId, item.newValue);
      showHabitToast('🏆 ' + valStr + ' ' + def.label);
      setTimeout(() => {
        _prCelebrationActive = false;
        drainPRCelebrationQueue();
      }, 2400);
    } else if (item.mode === 'tier3') {
      showPRTier3Takeover(item);
    } else {
      showPRTier2Modal(item);
    }
  }

  function setupBonusInfoPopup() {
    const ov = document.getElementById('bonus-info-overlay');
    const closeBtn = document.getElementById('bi-close-btn');
    const doneBtn  = document.getElementById('bi-done-btn');
    if (ov)       ov.addEventListener('click', closeBonusInfoPopup);
    if (closeBtn) closeBtn.addEventListener('click', closeBonusInfoPopup);
    if (doneBtn)  doneBtn.addEventListener('click', closeBonusInfoPopup);

    // Delegated click — every ⚡ rendered with [data-bonus-info] is clickable
    // (current pack-progress strip rows, plus any future surfaces that opt in).
    document.addEventListener('click', e => {
      const t = e.target;
      if (!t || !t.closest) return;
      const bolt = t.closest('[data-bonus-info]');
      if (!bolt) return;
      e.stopPropagation();
      e.preventDefault();
      openBonusInfoPopup();
    });

    // ESC dismiss
    document.addEventListener('keydown', e => {
      if (e.key !== 'Escape') return;
      const md = document.getElementById('bonus-info-modal');
      if (md && !md.classList.contains('hidden')) closeBonusInfoPopup();
    });
  }


  // ── DUNGEON BOSSES UI ────────────────────────────────────────
  // Render path for the boss-card grid inside the dungeon view of
  // #quests-panel. Each card opens the full-screen detail modal
  // (#boss-fs-overlay) on tap. Builders + open/close + setup live
  // below, in that order.
  // ── LEADERBOARD (Social tab) — v2.1 Phase C live ──────────
  // Surfaces the user's three Apple-Health-verified stats with
  // live competitive rankings via /v1/leaderboard/top fetches.
  // Tap any card → opens the Top-N ranking sheet for that metric.
  //
  // Three cards, fixed order (matches the metric definitions in the
  // Leaderboard module):
  //   1. Steps — last 7 days (current trailing sum + best week peak)
  //   2. 7+ hour sleep streak (current + best)
  //   3. Before-midnight bedtime streak (current + best)
  //
  // Empty-state handling: web/non-iOS users + iOS users without
  // HealthKit permission see a single explainer card instead of
  // zeroed-out stat rows. The competitive framing requires verified
  // data — showing "0 steps · best 0" would be misleading.
  function renderLeaderboardPreview() {
    const list  = document.getElementById('lb-preview-list');
    const empty = document.getElementById('lb-preview-empty');
    if (!list || !empty) return;

    // Render the three stat cards always — even on web/no-permission.
    // On web the data will be zeros (no HealthKit feeding the module),
    // but the user explicitly asked to see the layout in their browser
    // for previewing purposes. We surface a small note inside the
    // empty-state box explaining that real data only flows on iOS,
    // rather than gating the whole preview behind it.
    const isAvailable = (typeof Health !== 'undefined') &&
                         Health.isAvailable && Health.isAvailable();
    const isGranted   = isAvailable && Health.permissionStatus &&
                         Health.permissionStatus() === 'granted';

    if (!isAvailable) {
      // Web / non-iOS: show a soft note above the cards. Cards still
      // render below (with whatever zeros are in storage) for layout
      // visibility. The leaderboard ranking itself is live for iOS
      // users; this note clarifies that the data feeding it requires
      // the iOS app + Apple Health.
      empty.classList.remove('hidden');
      empty.innerHTML =
        '<div style="font-weight:700; color: var(--text-primary); margin-bottom:4px;">iOS only</div>' +
        '<div style="font-size:0.82rem;">These stats populate from Apple Health on the iOS app. The cards below show your current values (zero on web).</div>';
    } else if (!isGranted) {
      // Native but no permission yet — actionable copy.
      empty.classList.remove('hidden');
      empty.innerHTML =
        '<div style="font-weight:700; color: var(--text-primary); margin-bottom:4px;">Apple Health not connected</div>' +
        '<div style="font-size:0.82rem;">Grant HealthKit permission to start tracking these stats. Visit the Habits tab to trigger the prompt, or enable it in iOS Settings → Privacy → Health → Awakened.</div>';
    } else {
      empty.classList.add('hidden');
    }

    const snap = lbGetSnapshot();

    const fmt = n => (n || 0).toLocaleString('en-US');
    const nightWord = n => n === 1 ? 'night' : 'nights';

    // Card-builder. Icon-led layout: each card is a button so it
    // exposes click + keyboard activation natively. data-metric is
    // read by the click handler to open the right Top-50 view.
    function buildCard(metric, iconHTML, valueHTML, metaHTML) {
      return '<button type="button" class="lb-stat-card" data-lb-metric="' + metric + '">' +
        '<div class="lb-stat-icon-wrap">' + iconHTML + '</div>' +
        '<div class="lb-stat-body">' +
          '<div class="lb-stat-value">' + valueHTML + '</div>' +
          '<div class="lb-stat-meta">' + metaHTML + '</div>' +
        '</div>' +
        '<div class="lb-stat-chev">›</div>' +
      '</button>';
    }

    const walkIcon    = '<img src="assets/habit-icons/icon-walk.png" alt="" draggable="false" loading="lazy" decoding="async">';
    const sleepIcon   = '<img src="assets/habit-icons/icon-sleep.png" alt="" draggable="false" loading="lazy" decoding="async">';
    // v3 Phase 1z.118 — workout streak card uses the same icon as
    // the Workout habit (icon-strength.png, kept after the 1z.105
    // rename). Replaces the moonIcon previously used by the
    // before-midnight bedtime streak card.
    const workoutIcon = '<img src="assets/habit-icons/icon-strength.png" alt="" draggable="false" loading="lazy" decoding="async">';

    // Card 1 — Steps this calendar week (Sunday 00:00 → Saturday
    // 23:59:59 device-local, resets every Sunday). The
    // `steps_last_7_days` field name on the snapshot is a legacy
    // identifier; semantics are now "current calendar week."
    const stepsValue = fmt(snap.steps_last_7_days) + '<span class="lb-stat-value-unit">steps this week</span>';
    const stepsMeta  = snap.best_7day_step_total > 0
      ? 'Best week: <b>' + fmt(snap.best_7day_step_total) + '</b>'
      : 'Best week: — (start walking to climb the leaderboard)';

    // Card 2 — 7+ hour sleep streak
    const sleepValue = snap.current_sleep_streak +
      '<span class="lb-stat-value-unit">sleep streak · 7+ hr</span>';
    const sleepMeta  = 'Best: <b>' + snap.best_sleep_streak + ' ' + nightWord(snap.best_sleep_streak) + '</b>';

    // Card 3 — Workout Streak (v3 Phase 1z.118)
    // Replaces the prior "Before-midnight bedtime streak" card. Source
    // is the completion ledger via _lbComputeWorkoutStreakFromCompletions
    // (already folded into snap.current_workout_streak /
    // .best_workout_streak by lbGetSnapshot). Workout is read-only
    // HK-verified (autoVerifyStrengthTraining sealed) so every
    // streak day is verified by construction — the "Verified by
    // Apple Health" leaderboard copy stays accurate.
    const workoutDayWord = n => n === 1 ? 'day' : 'days';
    const workoutValue = snap.current_workout_streak +
      '<span class="lb-stat-value-unit">workout streak · 30+ min</span>';
    const workoutMeta  = 'Best: <b>' + snap.best_workout_streak + ' ' + workoutDayWord(snap.best_workout_streak) + '</b>';

    list.innerHTML =
      buildCard('step_total',     walkIcon,    stepsValue,   stepsMeta) +
      buildCard('sleep_streak',   sleepIcon,   sleepValue,   sleepMeta) +
      buildCard('workout_streak', workoutIcon, workoutValue, workoutMeta) +
      // v3 Phase 1z.125 — sheet-only "More rankings" link. Opens the
      // Flights Climbed leaderboard modal without adding a 4th main
      // Status card (preserves the 3-card layout per product guard).
      // Styled as a subtle inline link, not a card. The button uses
      // a distinct class so it doesn't pick up `.lb-stat-card` hover
      // styling. data-lb-metric routes through the same click handler
      // as the cards.
      '<button type="button" class="lb-more-rankings" data-lb-metric="flights_climbed" ' +
        'style="display:block; width:100%; margin-top:8px; padding:10px 14px; ' +
        'background:transparent; border:1px dashed rgba(139,92,246,0.35); ' +
        'border-radius:10px; color:var(--text-primary, #c4b5fd); ' +
        'font-size:0.78rem; font-weight:600; letter-spacing:0.02em; ' +
        'text-align:center; cursor:pointer;">' +
        'More rankings · Flights climbed ›' +
      '</button>';
  }
  try { window.renderLeaderboardPreview = renderLeaderboardPreview; } catch (_) {}

  // ── SOCIAL TAB — FRIENDS (v3 Phase 1z.279 — Duels retired) ────
  // Friends section on the Social tab. Duels v1 (1x–1z) was
  // permanently retired; only friend-list rendering, friend add,
  // and friend row actions remain.

  // In-memory cache refreshed each Social-tab activation.
  let _friendsCache = null;
  // W772 — hydrate from the last-good disk snapshot (≤14 days) so a cold launch
  // paints the roster instantly; the on-open fetch still runs and swaps in fresh.
  try {
    const _fcRaw = JSON.parse(localStorage.getItem('hb_friends_cache_v1') || 'null');
    if (_fcRaw && Array.isArray(_fcRaw.friends) && (Date.now() - (_fcRaw.ts || 0)) < 14 * 86400000) {
      _friendsCache = { ok: true, friends: _fcRaw.friends, _fromDisk: true };
    }
  } catch (_) {}

  // v3 Phase 1z.209 — lowercase alias display for the Social/
  // Guild/Hunter surfaces. The product rule is "visible aliases
  // are lowercase everywhere" with ONE exception: the personal
  // display override map (LB_ALIAS_DISPLAY_OVERRIDES). Today
  // that map holds exactly { richie: 'Richie' } so the app's
  // creator keeps their capitalized treatment app-wide. Any
  // alias NOT in the override map is rendered strict lowercase.
  //
  // Stored data is never touched — backend payloads, local
  // hb_guild_activity rows, and friend objects retain their
  // original casing. This is a display-time normalization only.
  //
  // Use for: alias spans inside Guild Activity rows, Roster
  // rows, lower Guild accordion friend rows, joined-Guild
  // template, and incoming/outgoing friend requests. Do NOT
  // pass rank labels, boss names, or event labels through here.
  //
  // Behaviour matches lbNormalizeAliasForDisplay (also defined
  // in this file) — both helpers strip whitespace + lowercase +
  // consult the override map. _displayAliasLower exists as a
  // scoped re-entry point so future changes to Social/Guild
  // casing rules can diverge from the leaderboard's helper
  // without cross-impact.
  function _displayAliasLower(raw) {
    if (raw === undefined || raw === null) return '—';
    try {
      const stripped = String(raw).replace(/\s+/g, '');
      if (!stripped) return '—';
      const lower = stripped.toLowerCase();
      if (typeof LB_ALIAS_DISPLAY_OVERRIDES === 'object'
          && LB_ALIAS_DISPLAY_OVERRIDES
          && LB_ALIAS_DISPLAY_OVERRIDES[lower]) {
        return LB_ALIAS_DISPLAY_OVERRIDES[lower];
      }
      return lower;
    } catch (_) {
      return '—';
    }
  }

  // Defensive: if the static index.html shipped in the IPA is stale
  // (missing the v3 Phase 1x.1 Social-tab markup), inject the
  // friends section at runtime so the tab works as long as app.js
  // itself is fresh. The static markup is still the source of truth.
  // v3 Phase 1z.279 — duels page header, hero mount, and duels
  // section markup all removed (Duels retired).
  function _ensureSocialMarkup() {
    const panel = document.getElementById('social-panel');
    if (!panel) return;
    function makeNode(html) {
      const wrap = document.createElement('div');
      wrap.innerHTML = html.trim();
      return wrap.firstChild;
    }
    // Remove any legacy leaderboard preview / build marker that may
    // linger from older static index.html.
    const legacyLb = panel.querySelector('.lb-preview');
    if (legacyLb) legacyLb.remove();
    const legacyMarker = panel.querySelector('.social-build-marker');
    if (legacyMarker) legacyMarker.remove();
    // Friends section (collapsible — closed by default, v3 Phase 1x.4)
    if (!document.getElementById('social-friends-body')) {
      const section = makeNode(
        '<section class="social-section social-section--friends social-section--collapsible social-section--collapsed">' +
          '<button class="social-section-toggle" type="button" aria-expanded="false" data-collapsible-target="friends">' +
            '<div class="social-section-header-row">' +
              '<div class="social-section-header">FRIENDS</div>' +
              '<div class="social-section-header-right">' +
                '<span id="social-friends-count" class="social-section-count"></span>' +
                '<span class="social-section-chevron" aria-hidden="true">▾</span>' +
              '</div>' +
            '</div>' +
          '</button>' +
          '<div class="social-section-collapsible-body">' +
            '<div class="social-friend-add">' +
              '<input id="social-friend-input" class="social-friend-input" type="text" ' +
                'placeholder="find a hunter…" maxlength="20" autocomplete="off" ' +
                'autocorrect="off" autocapitalize="off" spellcheck="false">' +
              '<button id="social-friend-send" class="social-btn social-btn--primary" type="button">Send Request</button>' +
            '</div>' +
            // W596 — bring a NEW hunter into the app (adding by alias only works if
            // they already play). Shares an invite carrying your own hunter name.
            '<button id="social-friend-invite" class="social-invite-btn" type="button" data-guild-invite="1">' +
              '<span class="social-invite-ic" aria-hidden="true">🔗</span>' +
              '<span class="social-invite-txt"><b>Invite a hunter</b>' +
                '<span>Send your name so a friend can add you</span></span>' +
              '<span class="social-invite-chev" aria-hidden="true">›</span>' +
            '</button>' +
            '<div id="social-friends-body" class="social-section-body">' +
              '<div class="social-empty">Loading friends…</div>' +
            '</div>' +
          '</div>' +
        '</section>'
      );
      panel.appendChild(section);
    }
  }




  // ───────────────────────────────────────────────────────────
  // Verified Event Outbox (v3 Phase 1z.1)
  //
  // Local-only transport queue for verified events. v3 Phase 1z.279
  // retired Duels permanently, so this outbox no longer ENQUEUES new
  // events — the producer (`_buildEventsForActiveDuel`) is gone, and
  // the writer (_enqueueVerifiedEvents) was removed in the flagged-item
  // live session (2026-06-12, Richie verdict: cut). The
  // drain side is preserved so any pre-retirement queued events on
  // upgraded devices still get flushed to the backend on first
  // foreground / cold launch, after which the queue stays empty.
  //
  // Keys are device-local; NEVER added to CloudSync.SNAPSHOT_KEYS.
  // Backend's UNIQUE(user_id, client_event_id) protects against
  // double-insert even if the client retries the same event twice.
  // ───────────────────────────────────────────────────────────
  const VERIFIED_EVENT_OUTBOX_KEY = 'hb_verified_event_outbox';
  const VERIFIED_EVENT_OUTBOX_CAP = 250;
  let _outboxLast401At = 0;

  function _loadVerifiedEventOutbox() {
    try {
      const raw = localStorage.getItem(VERIFIED_EVENT_OUTBOX_KEY);
      if (!raw) return [];
      const arr = JSON.parse(raw);
      return Array.isArray(arr) ? arr : [];
    } catch (_) { return []; }
  }

  function _saveVerifiedEventOutbox(arr) {
    try {
      // FIFO drop when over cap.
      if (arr.length > VERIFIED_EVENT_OUTBOX_CAP) arr = arr.slice(arr.length - VERIFIED_EVENT_OUTBOX_CAP);
      localStorage.setItem(VERIFIED_EVENT_OUTBOX_KEY, JSON.stringify(arr));
    } catch (_) { /* quota exceeded — best effort */ }
  }

  // DEPRECATION (2026-06-12, live flagged-item session): the drain is a
  // MIGRATION PATH only — it flushes historical queues from pre-1z.279
  // installs in the wild. Nothing enqueues anymore (writer removed this
  // session). Remove no earlier than v2.2.7, once legacy queues can
  // reasonably be assumed empty. Richie verdict: KEEP until then.
  async function _drainVerifiedEventOutbox() {
    const queue = _loadVerifiedEventOutbox();
    if (queue.length === 0) return { drained: 0, kept: 0 };
    if (!window.Auth || typeof Auth.submitVerifiedEvents !== 'function') {
      return { drained: 0, kept: queue.length };
    }
    // 401 throttle — back off for 60s after an auth failure so we don't
    // hammer the server while the user re-auths.
    if (Date.now() - _outboxLast401At < 60 * 1000) {
      return { drained: 0, kept: queue.length };
    }

    let kept = [];
    let drained = 0;
    for (let i = 0; i < queue.length; i += 25) {
      const chunk = queue.slice(i, i + 25);
      let res;
      try { res = await Auth.submitVerifiedEvents(chunk); }
      catch (_) { res = null; }
      if (!res) {
        // Network error or thrown — keep batch, retry next trigger.
        kept = kept.concat(chunk);
        continue;
      }
      if (res.code === 'EXPIRED' || res.code === 'UNAUTHORIZED' || res.code === 'NOT_SIGNED_IN') {
        _outboxLast401At = Date.now();
        kept = kept.concat(chunk);
        continue;
      }
      if (!res.ok) {
        // Opaque non-ok (rate limit, 5xx, etc.) — keep batch.
        kept = kept.concat(chunk);
        continue;
      }
      // Success: the server either accepted or de-duped each event.
      // Either way, the row is on the backend and can leave the queue.
      drained += chunk.length;
    }
    _saveVerifiedEventOutbox(kept);
    try { console.log('[outbox] drained=' + drained + ' kept=' + kept.length); } catch (_) {}
    return { drained, kept: kept.length };
  }
  try { window._drainVerifiedEventOutbox = _drainVerifiedEventOutbox; } catch (_) {}

  // v3 Phase 1z.186 — future backend seam for friend rank labels.
  // Returns a real backend-provided division label (e.g. "D II",
  // "C I", "S I") when one exists on the friend object, else null.
  // Do NOT fabricate rank from alias, bosses slain, or local state.
  // When the backend lands a friend rank sync, prefer specific
  // division labels (rank letter + roman tier) over broad letters.
  function _friendRankLabel(friend) {
    if (!friend || typeof friend !== 'object') return null;
    const candidate = friend.rankLabel
      || friend.rank_label
      || friend.rankDivisionLabel
      || friend.rank_division_label
      || friend.currentRankLabel
      || friend.current_rank_label
      || null;
    if (typeof candidate !== 'string') return null;
    const trimmed = candidate.trim();
    if (!trimmed) return null;
    // Defensive cap so unexpectedly long backend strings can't
    // overflow the avatar circle. The avatar is sized for ~4-5
    // characters; anything longer is truncated rather than shown
    // raw. Real labels ("S I", "A II", "D III") stay intact.
    return trimmed.length > 5 ? trimmed.slice(0, 5) : trimmed;
  }

  // v3 Phase 1z.191 — friend rank sort seam, now consuming the
  // real `rankSortValue` field returned by /v1/friends LEFT JOIN
  // against public_profile_summary (1z.190). Returns null when
  // the friend has not submitted a public summary yet, so the
  // 1z.186 "preserve server order unless every friend has data"
  // policy still holds. No bosses-slain proxy. No alias-derived
  // rank. No client-side fabrication.
  function _friendAvatarHtml(alias, variant, friend) {
    // v3 Phase 1z.207 — Guild Roster redesign. The circle now
    // ALWAYS holds the alias initial; the exact rank label (e.g.
    // "D II") sits in a separate chip BELOW the circle so the
    // ring stays clean and the tier stays legible. The wrapper
    // carries data-rank-tier so per-tier CSS variables can paint
    // ring + chip + sub-line in the matching rank color. Tier
    // letter is parsed from the label's first word ("D II" → "D",
    // "S+" → "S+", anything else → safe fallback).
    //
    // Backward compat: incoming/outgoing/duel callers pass no
    // `friend` argument → no chip rendered, no tier attribute,
    // visual matches the original alias-initial circle.
    const rankTxt = (friend ? _friendRankLabel(friend) : null);
    const initial = (alias && alias[0]) ? alias[0].toUpperCase() : '—';
    const variantCls = variant ? (' friend-avatar--' + variant) : '';

    if (!rankTxt) {
      // Legacy single-element path. Preserves all existing
      // markup expectations (Duels rows, incoming/outgoing).
      return '<div class="friend-avatar' + variantCls + '">' + esc(initial) + '</div>';
    }

    // Parse the tier letter for the data attribute. Real labels
    // are "<tier>" or "<tier> <division>" (locked by the 1z.190
    // public-profile-summary regex). We accept S+ as a tier.
    let tier = 'E';
    const m = String(rankTxt).match(/^(S\+|S|A|B|C|D|E)(?: (I|II|III))?$/);
    if (m) tier = m[1];
    const tierAttr = ' data-rank-tier="' + esc(tier) + '"';
    // W453 — Prestige ✦ for S+ friends. The chip is tiny, so use the compact
    // "S+✦N" numeral form (glyph repetition would overflow the 5-char clamp).
    // friend.prestige is carried through the roster mapping (0 unless S+).
    const _fp = (tier === 'S+' && friend) ? (friend.prestige | 0) : 0;
    const chipTxt = (_fp > 0)
      ? ('S+✦' + _fp)
      : ((rankTxt.length > 5) ? rankTxt.slice(0, 5) : rankTxt);
    return (
      '<div class="friend-avatar-stack"' + tierAttr + '>' +
        '<div class="friend-avatar friend-avatar--rank-ring' + variantCls + '">' +
          esc(initial) +
        '</div>' +
        '<div class="friend-avatar-rank-chip">' + esc(chipTxt) + '</div>' +
      '</div>'
    );
  }

  async function renderFriendsSection() {
    _ensureSocialMarkup();
    try { _coopServerSyncPacts(); } catch (_) {}   // W664 P2 — canonical server pacts (once/session; falls back to the v1 _coopBackfillPacts if the endpoint is unavailable; re-renders if numbers change)
    try { _pfEnsureDefs(); } catch (_) {}   // W665 — flame gradient defs for the roster SVG chips
    const body = document.getElementById('social-friends-body');
    const countEl = document.getElementById('social-friends-count');
    if (!body) return;
    if (countEl) countEl.textContent = '';
    if (!window.Auth || typeof Auth.fetchFriends !== 'function') {
      body.innerHTML = '<div class="social-empty">Sign in to add friends.</div>';
      return;
    }
    // W659 — cache-first (stale-while-revalidate). If a roster is already in
    // hand (a prior open, or the 90s friend-request poller which fetches the
    // SAME /v1/friends payload), paint it INSTANTLY and revalidate in the
    // background; only show the skeleton on a genuine cold first load. Mirrors
    // the leaderboard-sheet + W633 profile-card SWR shape already shipped.
    const cached = (_friendsCache && _friendsCache.ok) ? _friendsCache : null;
    if (cached) {
      try { _paintFriendsSection(cached, false); } catch (_) {}
    } else {
      try { showLoading(body, 'rows', 4); } catch (_) { body.innerHTML = '<div class="social-empty">Loading friends…</div>'; }   // W590 — thematic skeleton
    }
    let res;
    try { res = await Auth.fetchFriends(); }
    catch (_) { res = { ok: false, code: 'NETWORK', detail: 'Could not reach server.' }; }
    if (!res || !res.ok) {
      // A transient failure must NOT wipe a good cache-first paint.
      if (cached) return;
      if (res && (res.code === 'NOT_SIGNED_IN' || res.code === 'STUB_USER' || res.code === 'LOCAL_DEV_SKIP')) {
        body.innerHTML = '<div class="social-empty">Sign in with Apple to add friends.</div>';
        return;
      }
      body.innerHTML = '<div class="social-error">Could not load friends: ' + esc((res && res.detail) || 'unknown error') + '</div>';
      return;
    }
    _friendsCache = res;
    _paintFriendsSection(res, true);
  }

  // W659 — pure render of the friends/incoming/outgoing roster from a fetched
  // `res`. `doReconcile` runs the (idempotent) Guild Board friend-backfill ONLY
  // on a live fetch, never on a cache-first repaint, so the instant paint costs
  // zero localStorage writes.
  function _paintFriendsSection(res, doReconcile) {
    const body = document.getElementById('social-friends-body');
    const countEl = document.getElementById('social-friends-count');
    if (!body) return;
    const friends  = Array.isArray(res.friends)  ? res.friends  : [];
    const incoming = Array.isArray(res.incoming) ? res.incoming : [];
    const outgoing = Array.isArray(res.outgoing) ? res.outgoing : [];

    // v3 Phase 1z.170 — Guild Board reconciliation pass. Records
    // a 'friend_added' event for every accepted friend that hasn't
    // been seen yet. Catches the case where the friendship was
    // accepted on a different device (or via a request the user
    // accepted in a previous session) — without this pass, those
    // friendships would silently never appear on the board.
    // Idempotent: the seenKey 'friend_added_<friendshipId>' guards
    // duplicates, so repeating this loop on every fetch is a
    // no-op once each friendship has been logged once. Skip
    // silently if recordGuildActivity isn't available (older
    // bundle path).
    try {
      if (doReconcile && typeof recordGuildActivity === 'function') {
        for (const f of friends) {
          if (!f || !f.id || !f.alias) continue;
          recordGuildActivity('friend_added',
            { alias: f.alias, friendshipId: f.id },
            'friend_added_' + f.id);
        }
      }
    } catch (_) { /* defensive — board failure must not block the friends list */ }

    if (countEl) {
      const n = friends.length;
      countEl.textContent = n === 0 ? '' : n + (n === 1 ? ' hunter' : ' hunters');
    }

    const parts = [];
    if (incoming.length) {
      parts.push('<div class="social-section-subhead">Incoming requests</div>');
      for (const f of incoming) {
        // v3 Phase 1z.209 — strict-lowercase alias display.
        const alias = _displayAliasLower(f.alias);
        parts.push(
          // v3 Phase 1z.170 — incoming rows now carry data-alias so
          // the accept handler can record a 'friend_added' Guild Board
          // event with the correct display name (without an extra
          // backend roundtrip to look it up post-accept).
          '<div class="social-row friend-row friend-row--incoming" data-friendship-id="' + esc(f.id) + '" data-alias="' + esc(f.alias) + '">' +
            _friendAvatarHtml(alias, 'gold') +
            '<div class="social-row-main">' +
              '<div class="social-row-alias">' + esc(alias) + '</div>' +
              '<div class="social-row-meta friend-row-meta--gold">wants to be friends</div>' +
            '</div>' +
            '<div class="social-row-actions">' +
              '<button class="social-btn social-btn--primary" data-friend-action="accept">Accept</button>' +
              '<button class="social-btn" data-friend-action="decline">Decline</button>' +
            '</div>' +
          '</div>'
        );
      }
    }
    if (outgoing.length) {
      parts.push('<div class="social-section-subhead">Outgoing</div>');
      for (const f of outgoing) {
        // v3 Phase 1z.209 — strict-lowercase alias display.
        const alias = _displayAliasLower(f.alias);
        parts.push(
          '<div class="social-row friend-row friend-row--outgoing" data-friendship-id="' + esc(f.id) + '">' +
            _friendAvatarHtml(alias, 'muted') +
            '<div class="social-row-main">' +
              '<div class="social-row-alias">' + esc(alias) + '</div>' +
              '<div class="social-row-meta">awaiting response</div>' +
            '</div>' +
            '<div class="social-row-actions">' +
              '<span class="ww-status ww-status--pending">Pending</span>' +
            '</div>' +
          '</div>'
        );
      }
    }
    if (friends.length) {
      // W667 — the Guild IS Pact Flames: render the whole roster as pact rows
      // (bonded → flame + streak + "N defeated together"; un-bonded → "no bond yet"),
      // wrapped in .pf-scope so the pact tokens apply outside the overlay. The proven
      // •••/Remove control rides along (guild:true), so friend-management is unchanged.
      // Sorted inside _pfBuildData (bonded by streak, then un-bonded) — do NOT pre-sort.
      try { _pfEnsureDefs(); } catch (_) {}
      var _pfRoster = _pfBuildData(friends, true);
      var _burning = 0, _hottest = 0;
      for (var _bi = 0; _bi < _pfRoster.length; _bi++) {
        var _rd = _pfRoster[_bi];
        if (_rd.state !== 'none' && _rd.state !== 'broken') { _burning++; if ((_rd.streak | 0) > _hottest) _hottest = _rd.streak | 0; }
      }
      var _subHtml = _burning
        ? ('<b>' + _burning + '</b> bond' + (_burning === 1 ? '' : 's') + ' burning<span class="pf-dot"></span>' + _pfFlame(11, false).replace('pf-flame', 'pf-flame pf-fl') + ' hottest <b>' + _hottest + 'd</b>')
        : ('<b>' + friends.length + '</b> ' + (friends.length === 1 ? 'hunter' : 'hunters') + ' · hunt together to light a flame');
      parts.push('<div class="pf-scope">' +
        '<div class="pf-guild-sub">' + _subHtml + '</div>' +
        '<div class="pf-list">' + _pfRoster.map(function (d) { return _pfRowHtml(d, { guild: true }); }).join('') + '</div>' +
      '</div>');
    }
    if (parts.length === 0) {
      // v3 Phase 1z.164 — Guild Hall zero-friends empty state.
      const socialHubOn = (typeof SOCIAL_HUB_ENABLED !== 'undefined') && !!SOCIAL_HUB_ENABLED;
      if (socialHubOn) {
        parts.push(
          '<div class="guildhall-empty-friends">' +
            '<div class="guildhall-empty-friends-icon">?</div>' +
            '<div class="guildhall-empty-friends-title">The guild hall stands empty.</div>' +
            '<div class="guildhall-empty-friends-sub">Bind another hunter — or invite one to join you.</div>' +
            // W598 (fix) — this is the LIVE empty state (SOCIAL_HUB_ENABLED=true);
            // give a brand-new user a discoverable invite CTA here.
            '<button class="social-empty-invite" type="button" data-guild-invite="1">' +
              '<span aria-hidden="true">🔗</span> Invite a hunter' +
            '</button>' +
          '</div>'
        );
      } else {
        parts.push(
          '<div class="social-empty social-empty--rich">' +
            '<div class="social-empty-title">No hunters added yet.</div>' +
            '<div class="social-empty-sub">Add a hunter by name — or invite one to join you.</div>' +
            // W598 — discoverable invite for a brand-new user with an empty guild
            // (delegated [data-guild-invite] handler → _guildInviteShare).
            '<button class="social-empty-invite" type="button" data-guild-invite="1">' +
              '<span aria-hidden="true">🔗</span> Invite a hunter' +
            '</button>' +
          '</div>'
        );
      }
    }
    body.innerHTML = parts.join('');
    // v3 Phase 1z.167 — friends fetch is the canonical source for
    // the HUNTERS tile and the friend initial chips. Repaint the
    // Guild Hall summary card so the count + chips stay in sync
    // with the just-rendered friends list. Cheap no-op if the v2
    // summary DOM isn't present.
    try {
      if (typeof renderGuildhallSummary === 'function') renderGuildhallSummary();
    } catch (_) {}
  }

  // ── Event wiring (delegated; runs once at init via setupSocialFriends) ──
  // v3 Phase 1z.279 — Renamed from setupSocialDuels. Duels wiring,
  // duel accordion state restore, duel collapsible persistence, and
  // the entire duels-body click handler + duel-detail overlay
  // handlers were removed when Duels were permanently retired.
  // Only the Friends section wiring remains.
  // W596 — Guild invite viral loop. The only way to add someone today is to
  // type their EXACT existing alias, so there is no path to bring a real-world
  // friend INTO the app. This shares a pre-filled invite carrying the user's own
  // hunter name (so the friend can add them back) + the App Store link, via the
  // same navigator.share → clipboard fallback the boss-kill share cards use.
  async function _guildInviteShare() {
    const APP_URL = 'https://apps.apple.com/app/awakened-habit-rpg/id6764727990';
    let alias = '';
    try { alias = (lbGetMyAlias() || localStorage.getItem('hb_name') || '').trim(); } catch (_) {}
    const TEXT = alias
      ? ('Come hunt with me in Awakened, hunter. Add me by my name: ' + alias + '. ' +
         'It turns your real-world habits — workouts, steps, focus — into an RPG.')
      : 'Turn your real-world habits into an RPG. Come hunt with me in Awakened.';
    if (navigator.share) {
      try {
        await navigator.share({ title: 'Awakened', text: TEXT, url: APP_URL });
        return { ok: true, mode: 'share' };
      } catch (e) {
        // User dismissed the native sheet → don't also dump to clipboard.
        if (e && e.name === 'AbortError') return { ok: false, mode: 'cancelled' };
        /* real failure → fall through to clipboard */
      }
    }
    try {
      await navigator.clipboard.writeText(TEXT + '\n' + APP_URL);
      if (typeof showHabitToast === 'function') showHabitToast('Invite copied — paste to send it');
      return { ok: true, mode: 'clipboard' };
    } catch (_) {
      if (typeof showHabitToast === 'function') showHabitToast('Sharing is not supported on this device');
      return { ok: false, mode: 'none' };
    }
  }
  try { window._guildInviteShare = _guildInviteShare; } catch (_) {}

  function setupSocialFriends() {
    // v3 Phase 1x.4 — collapsible Friends section.
    const socialPanel = document.getElementById('social-panel');
    if (socialPanel && !socialPanel._collapseWired) {
      socialPanel.addEventListener('click', (e) => {
        // W596/W598 — "Invite a hunter" (add-row + empty-state) share the same
        // delegated handler so both survive re-renders with no per-element wiring.
        const inviteEl = e.target.closest && e.target.closest('[data-guild-invite]');
        if (inviteEl) { try { _guildInviteShare(); } catch (_) {} return; }
        // W664 — general entry into the Pact Flames screen (full bond list, no
        // friend focused). Delegated here so it survives friends-section re-renders.
        const pfEl = e.target.closest && e.target.closest('[data-open-pactflames]');
        if (pfEl) { try { openPactFlames(); } catch (_) {} return; }
        const toggle = e.target.closest && e.target.closest('.social-section-toggle');
        if (!toggle) return;
        const section = toggle.closest('.social-section--collapsible');
        if (!section) return;
        const wasCollapsed = section.classList.contains('social-section--collapsed');
        section.classList.toggle('social-section--collapsed');
        toggle.setAttribute('aria-expanded', wasCollapsed ? 'true' : 'false');
        // W721 — dropped a write to hb_duels_friends_expanded here: write-only, never
        // read (the Duels UI it served was removed).
      });
      socialPanel._collapseWired = true;
    }

    // Friend add
    const sendBtn = document.getElementById('social-friend-send');
    const input   = document.getElementById('social-friend-input');
    if (sendBtn && input) {
      const submitRequest = async () => {
        const raw = (input.value || '').trim();
        if (!raw) { showHabitToast('Enter a hunter alias.'); return; }
        sendBtn.disabled = true;
        let res;
        try { res = await Auth.sendFriendRequest(raw); }
        catch (_) { res = { ok: false, detail: 'Network error' }; }
        sendBtn.disabled = false;
        if (!res || !res.ok) {
          showHabitToast((res && res.detail) || 'Could not send request.');
          return;
        }
        input.value = '';
        if (res.autoAccepted)        showHabitToast('Friend request accepted — they had already requested you.');
        else if (res.alreadyFriends) showHabitToast('Already friends.');
        else if (res.alreadyPending) showHabitToast('Request already pending.');
        else                          showHabitToast('Friend request sent.');
        renderFriendsSection();
      };
      sendBtn.addEventListener('click', submitRequest);
      input.addEventListener('keydown', (e) => {
        if (e.key === 'Enter') { e.preventDefault(); submitRequest(); }
      });
    }

    // W596/W598 — the "Invite a hunter" buttons (add-row + empty-state) are
    // handled by the socialPanel delegated [data-guild-invite] listener above.

    // Delegated handler for friend rows.
    const friendsBody = document.getElementById('social-friends-body');
    if (friendsBody) {
      friendsBody.addEventListener('click', async (e) => {
        // W667 — tapping a pact roster ROW (not one of its buttons) opens its detail:
        // the rich bond sheet for a bonded friend, the intro card for an un-bonded one.
        // Buttons (•••/Cancel/Remove) fall through to the friend-action handler below.
        const pfRow = e.target.closest && e.target.closest('.pf-row[data-pf-open]');
        if (pfRow && !e.target.closest('button')) {
          const uid = pfRow.getAttribute('data-pf-open');
          const al = pfRow.getAttribute('data-alias');
          if (pfRow.classList.contains('pf-row--nobond')) { try { _coopShowPactCard(uid, al); } catch (_) {} }
          else { try { _pfOpenBondDetail(uid); } catch (_) { try { _coopShowPactCard(uid, al); } catch (__) {} } }   // W670 — detail sheet only, not the redundant full page
          return;
        }
        const btn = e.target.closest('button[data-friend-action]');
        if (!btn) return;
        const row = btn.closest('.social-row');
        if (!row) return;
        const action = btn.getAttribute('data-friend-action');
        // W663 — the co-op Pact flame opens the "Pact with <ally>" detail. Handle it
        // BEFORE the fid/disabled machinery — it's a display flame (keyed by the
        // friend's user_id), not a friend-mutation button.
        if (action === 'pact') {
          // W664 — open the rich Pact Flames screen focused on this bond (falls back
          // to the plain text card if the screen fails for any reason).
          try { openPactFlames(btn.getAttribute('data-user-id')); }
          catch (_) { try { _coopShowPactCard(btn.getAttribute('data-user-id'), row.getAttribute('data-alias')); } catch (__) {} }
          return;
        }
        const fid    = row.getAttribute('data-friendship-id');
        if (!fid) return;
        btn.disabled = true;
        let res;
        try {
          if (action === 'accept')        res = await Auth.acceptFriendRequest(fid);
          else if (action === 'decline')  res = await Auth.declineFriendRequest(fid);
          else if (action === 'remove') {
            // Legacy fallback — direct Remove button. 1z.176 routes
            // friend rows through remove-init/confirm/cancel
            // instead; this branch only fires if some other call
            // site still emits `remove`.
            if (!window.confirm('Remove this friend?')) { btn.disabled = false; return; }
            res = await Auth.removeFriend(fid);
          } else if (action === 'remove-init') {
            // v3 Phase 1z.176 — two-step inline confirm. First
            // tap of "•••" flips the row to confirm mode (CSS
            // [data-row-mode="confirm"] reveals the Cancel /
            // Remove buttons and hides the overflow icon). Auto-
            // reset to idle after 6s in case the user walks away.
            btn.disabled = false;
            if (!row) return;
            row.setAttribute('data-row-mode', 'confirm');
            // Clear any prior pending timer for this row.
            const priorTimerId = row.getAttribute('data-row-confirm-timer');
            if (priorTimerId) {
              try { clearTimeout(Number(priorTimerId)); } catch (_) {}
            }
            const t = setTimeout(() => {
              if (row && row.getAttribute('data-row-mode') === 'confirm') {
                row.setAttribute('data-row-mode', 'idle');
                row.removeAttribute('data-row-confirm-timer');
              }
            }, 6000);
            row.setAttribute('data-row-confirm-timer', String(t));
            return;
          } else if (action === 'remove-cancel') {
            btn.disabled = false;
            if (row) {
              row.setAttribute('data-row-mode', 'idle');
              const tid = row.getAttribute('data-row-confirm-timer');
              if (tid) {
                try { clearTimeout(Number(tid)); } catch (_) {}
                row.removeAttribute('data-row-confirm-timer');
              }
            }
            return;
          } else if (action === 'remove-confirm') {
            // Confirmed — clear the auto-reset timer and call the
            // existing remove API. No native window.confirm needed
            // since the inline confirm IS the intentional gate.
            if (row) {
              const tid = row.getAttribute('data-row-confirm-timer');
              if (tid) {
                try { clearTimeout(Number(tid)); } catch (_) {}
                row.removeAttribute('data-row-confirm-timer');
              }
            }
            res = await Auth.removeFriend(fid);
          }
          // v3 Phase 1z.279 — 'challenge' friend-row action removed
          // along with the Duels subsystem.
        } catch (_) { res = { ok: false, detail: 'Network error' }; }
        btn.disabled = false;
        if (!res || !res.ok) {
          showHabitToast((res && res.detail) || 'Action failed.');
          return;
        }
        if (action !== 'challenge') {
          // v3 Phase 1z.170 — Guild Board friend event. Only the
          // "accept" path fires a feed row: declined/removed
          // friendships are intentionally NOT logged (decisions to
          // disconnect aren't celebratory events). renderFriendsSection
          // below will ALSO reconcile any accepted-from-another-device
          // friendships via its own backfill loop, but firing here
          // first gives an immediate row the moment the user taps
          // Accept, before the fetch round-trip returns.
          if (action === 'accept') {
            try {
              const alias = row.getAttribute('data-alias') || '';
              if (alias && typeof recordGuildActivity === 'function') {
                recordGuildActivity('friend_added',
                  { alias: alias, friendshipId: fid },
                  'friend_added_' + fid);
              }
            } catch (_) { /* board failure must not block the friend flow */ }
          }
          showHabitToast(action === 'accept' ? 'Friend added.' : action === 'decline' ? 'Request declined.' : 'Friend removed.');
          renderFriendsSection();
        }
      });
    }
  }
  try { window.renderFriendsSection = renderFriendsSection; } catch (_) {}

  // ── LEADERBOARD RANKING SHEET (v2.1.0 Phase C — LIVE) ───────
  // Tap any stat card on the Social tab → opens this bottom sheet
  // with the real Top-N for that metric, fetched from the
  // Cloudflare Workers backend at /v1/leaderboard/top.
  //
  // Cache strategy: stale-while-revalidate. On open, render any
  // cached entries from hb_lb_cache_<metric> instantly, then fire a
  // background fetch and swap to fresh data when it lands. If the
  // network fetch fails AND the cache is <24h old, keep showing
  // cached entries with a "last updated" footer. If both fail, show
  // an empty state.
  //
  // Backend metric IDs (per BACKEND.md §6):
  //   step_total      — cumulative steps over the rolling 7-day window
  //   sleep_streak    — current consecutive ≥7h sleep nights
  //   bedtime_streak  — current consecutive before-midnight nights
  //
  // The Social-tab cards use these same IDs as data-lb-metric so
  // open/fetch don't require any translation.

  // v3 Phase 1z.33 — weekly scoping for the Global Steps leaderboard.
  // The backend now scopes step_total rankings to the current Sunday-UTC
  // week (see migrations/0008_leaderboard_week_start.sql and
  // backend/src/handlers/leaderboard-top.ts). The client mirrors that
  // week-key convention so we can:
  //   1. render the visible date range below the sheet title
  //   2. invalidate the local step_total cache when the boundary rolls
  //      over so the World Rank card doesn't show last-week's rank
  // Format matches backend getAccoladeWeekStart(): 'YYYY-MM-DD'.
  // v3 Phase 1z.125 — flights_climbed joins step_total as a weekly
  // Sunday-UTC-scoped metric. Backend WEEKLY_METRICS in
  // backend/src/lib/metrics.ts mirrors this set.
  const LB_WEEKLY_METRICS = new Set(['step_total']);   // W634 — flights_climbed board retired

  // v3 Phase 1z.219 — Pacific Time weekly reset helper.
  // Mirrors the backend 1z.218 getAccoladeWeekStart() in
  // backend/src/lib/accolade-week.ts: anchors the global
  // leaderboard week boundary at Sunday 00:00 in
  // America/Los_Angeles, computed via Intl.DateTimeFormat so
  // DST transitions are handled natively (no fixed UTC-7/-8
  // offset, no manual spring-forward/fall-back math).
  //
  // Format unchanged: 'YYYY-MM-DD' — the date of the Pacific-
  // local Sunday that started the week containing nowMs. The
  // backend stamps every weekly snapshot row with the same
  // string under the Pacific anchor, so client-computed sums
  // and server-stamped period_keys agree.
  //
  // Single chokepoint: the four call sites (lbSumCurrentWeekSteps,
  // lbSumCurrentWeekFlights, the cache invalidation pair, and the
  // leaderboard subhead copy generator) all read through here.
  // The pre-1z.219 UTC helper is kept as an alias below so any
  // legacy reference (none expected at the call-site level after
  // 1z.219; included as defense-in-depth in case a future merge
  // resurrects the old name) continues to work AND now returns
  // the Pacific key transparently — there's no "mixed math" in
  // the client.
  const _PT_DOW_BACK = { Sun: 0, Mon: 1, Tue: 2, Wed: 3, Thu: 4, Fri: 5, Sat: 6 };
  // Pre-allocated formatter; constructing one per call is
  // expensive on iOS WebKit. Cached at module scope.
  let _ptDateParts = null;
  function _getPTDateParts() {
    if (_ptDateParts) return _ptDateParts;
    try {
      _ptDateParts = new Intl.DateTimeFormat('en-CA', {
        timeZone: 'America/Los_Angeles',
        year:    'numeric',
        month:   '2-digit',
        day:     '2-digit',
        weekday: 'short',
      });
    } catch (_) {
      _ptDateParts = null;
    }
    return _ptDateParts;
  }
  function lbGetCurrentWeekStartPT(nowMs) {
    const ms = (typeof nowMs === 'number') ? nowMs : Date.now();
    const fmt = _getPTDateParts();
    if (!fmt) {
      // Defensive fallback: Intl unavailable. Use the legacy UTC
      // computation so the helper never throws. This branch is
      // extremely unlikely on Capacitor's WebKit but keeps the
      // hot path safe.
      const d = new Date(ms);
      const dayOfWeek = d.getUTCDay();
      const sundayMs = ms - dayOfWeek * 24 * 60 * 60 * 1000;
      const s = new Date(sundayMs);
      const yyyy = s.getUTCFullYear();
      const mm   = String(s.getUTCMonth() + 1).padStart(2, '0');
      const dd   = String(s.getUTCDate()).padStart(2, '0');
      return yyyy + '-' + mm + '-' + dd;
    }
    let y = 0, m = 0, d = 0, wk = '';
    try {
      const parts = fmt.formatToParts(new Date(ms));
      for (let i = 0; i < parts.length; i++) {
        const p = parts[i];
        if      (p.type === 'year')    y  = parseInt(p.value, 10);
        else if (p.type === 'month')   m  = parseInt(p.value, 10);
        else if (p.type === 'day')     d  = parseInt(p.value, 10);
        else if (p.type === 'weekday') wk = p.value;
      }
    } catch (_) { /* fall through to fallback below */ }
    const back = _PT_DOW_BACK[wk];
    if (!Number.isFinite(y) || !Number.isFinite(m) || !Number.isFinite(d) || typeof back !== 'number') {
      // Same UTC fallback as above if Intl parts came out
      // unexpectedly.
      const dd2 = new Date(ms);
      const dayOfWeek = dd2.getUTCDay();
      const sundayMs = ms - dayOfWeek * 24 * 60 * 60 * 1000;
      const s = new Date(sundayMs);
      const yyyy = s.getUTCFullYear();
      const mm   = String(s.getUTCMonth() + 1).padStart(2, '0');
      const dd   = String(s.getUTCDate()).padStart(2, '0');
      return yyyy + '-' + mm + '-' + dd;
    }
    // Walk back `back` days from the Pacific-local Y-M-D to land
    // on the Pacific Sunday's date. Using Date.UTC + ms math is
    // safe because a fixed N-day step in ms equals exactly N days
    // on the calendar regardless of timezone or DST — we're not
    // crossing the DST transition with this arithmetic; we built
    // the source y/m/d from a Pacific-aware formatter already.
    const startMs = Date.UTC(y, m - 1, d) - back * 86400000;
    const s = new Date(startMs);
    const yyyy = s.getUTCFullYear();
    const mm   = String(s.getUTCMonth() + 1).padStart(2, '0');
    const dd   = String(s.getUTCDate()).padStart(2, '0');
    return yyyy + '-' + mm + '-' + dd;
  }
  // v3 Phase 1z.219 — Transition alias. Old helper name now
  // returns the Pacific key transparently so any merge that
  // accidentally resurrects the old name still produces the
  // current correct boundary. No active call site uses this
  // name after 1z.219; kept as defense-in-depth.
  function lbGetCurrentWeekStartUTC(nowMs) {
    return lbGetCurrentWeekStartPT(nowMs);
  }
  // Render "May 17–May 23" given the Sunday-UTC start date string.
  // The Saturday end is Sunday + 6 days. Uses UTC for the format so the
  // visible label matches the backend's bucket boundary exactly.
  function lbFormatWeekRange(weekStartIso) {
    if (!weekStartIso || !/^\d{4}-\d{2}-\d{2}$/.test(weekStartIso)) return '';
    const startMs = Date.UTC(
      parseInt(weekStartIso.slice(0, 4), 10),
      parseInt(weekStartIso.slice(5, 7), 10) - 1,
      parseInt(weekStartIso.slice(8, 10), 10),
    );
    const endMs = startMs + 6 * 24 * 60 * 60 * 1000;
    const MONTHS = ['Jan','Feb','Mar','Apr','May','Jun','Jul','Aug','Sep','Oct','Nov','Dec'];
    const s = new Date(startMs), e = new Date(endMs);
    const sLabel = MONTHS[s.getUTCMonth()] + ' ' + s.getUTCDate();
    const eLabel = MONTHS[e.getUTCMonth()] + ' ' + e.getUTCDate();
    return sLabel + '–' + eLabel; // en-dash
  }

  const LB_METRIC_META = {
    step_total: {
      title: 'Steps · this week',
      // Blurb is computed dynamically by openLeaderboardRanking() — the
      // visible date range needs to follow the current week, so we
      // resolve it at render time rather than baking the strings in
      // here. This static fallback is only used if the dynamic path
      // is ever bypassed.
      blurb: 'Resets every Sunday 12:00 AM UTC. Apple Health is the only source — no manual logging.',
      unit:  'steps',
      formatValue: n => (n || 0).toLocaleString('en-US'),
    },
    // W634 — sleep_streak / bedtime_streak / workout_streak / flights_climbed
    // leaderboard boards retired (owner). Their metric-meta entries are removed;
    // the Sleep / Workout HABIT streak tracking (lbRecordSleepNight etc.) and the
    // snapshot fields they read are untouched.
    // W274 — the race to Floor 100. All-time best Ascent floor (not weekly).
    // Companion to the Hall of the Awakened (the floor-100 finisher registry).
    floor_best: {
      title: 'Highest floor',
      blurb: 'The furthest anyone has climbed The Ascent. The first to clear Floor 100 is crowned forever in the Hall of the Awakened.',
      unit:  'floor',
      formatValue: n => 'Floor ' + (n || 0),
    },
    // W622 — the Collection Log race. Unique relics currently held in the log
    // (commons excluded). Rows read "43 / 59" against the live catalog total;
    // a completed log wears the gold crown (same finish-line language as
    // floor_best's Floor-100 crown). Count can DECREASE — selling your last
    // copy of a relic removes it from the log (W204).
    relics_collected: {
      title: 'Collection Log',
      blurb: 'The race to complete the relic Collection Log — every rare and ultra-rare from every boss. Sell your last copy and it leaves your log.',
      unit:  'relics',
      formatValue: n => (n || 0) + ' / ' + (_lbRelicsLogStats().total || '?'),
    },
    // W634 — rank_band ("Hunters in your rank") cohort board retired (owner).
  };

  // localStorage cache key per metric. Object shape:
  //   { top: [{rank, alias, current_value}], me: { rank, current_value } | null, fetched_at: <epoch_ms> }
  const LB_CACHE_KEY_PREFIX = 'hb_lb_cache_';
  const LB_CACHE_MAX_AGE_MS = 24 * 60 * 60 * 1000; // 24h — past this, treat as empty

  // v3 Phase 1z.36 — Weekly Steps Hall of Fame cache. Separate from
  // the current-week cache because the shape is different (records[]
  // not top[], me_best not me) and the TTL is shorter (the records
  // change less often per-user but should still feel fresh; 10 min
  // is long enough to snap the sheet open after a refresh and short
  // enough that a new PR appears soon).
  const LB_HOF_CACHE_KEY_PREFIX = 'hb_lb_hof_';
  const LB_HOF_CACHE_MAX_AGE_MS = 10 * 60 * 1000; // 10 min
  // Metrics that support the Hall of Fame tab. v1: step_total only.
  const LB_HOF_METRICS = new Set(['step_total']);

  // v3 Phase 1z.52 — 100K Step Club roster cache. Single-key cache
  // (the endpoint is not metric-scoped — it's a single accolade-
  // typed roster). 10-min TTL matches the HoF cache. Stores
  // backend response verbatim; no sim filler.
  const LB_100K_CLUB_CACHE_KEY = 'hb_lb_100k_club';
  const LB_100K_CLUB_CACHE_MAX_AGE_MS = 10 * 60 * 1000; // 10 min

  function lbCacheRead(metric) {
    try {
      const raw = localStorage.getItem(LB_CACHE_KEY_PREFIX + metric);
      if (!raw) return null;
      const parsed = JSON.parse(raw);
      if (!parsed || typeof parsed.fetched_at !== 'number') return null;
      if ((Date.now() - parsed.fetched_at) > LB_CACHE_MAX_AGE_MS) return null;
      // v3 Phase 1z.33 — weekly metrics get an extra cross-week guard.
      // The 24h TTL above isn't enough: a cache written Saturday 11pm
      // UTC is still <24h old at Sunday 12:01am UTC, but its data is
      // last week's ranking. Reject any weekly cache whose fetched_at
      // falls in a prior UTC week so the World Rank card + sheet
      // never paint stale prior-week rank/values after the boundary.
      // v3 Phase 1z.219 — Pacific anchor. Same cross-week guard,
      // now keyed on Pacific Sunday boundaries.
      if (LB_WEEKLY_METRICS.has(metric)) {
        const fetchedWeek = lbGetCurrentWeekStartPT(parsed.fetched_at);
        const currentWeek = lbGetCurrentWeekStartPT();
        if (fetchedWeek !== currentWeek) return null;
      }
      return parsed;
    } catch (_) { return null; }
  }
  function lbCacheWrite(metric, top, me) {
    try {
      localStorage.setItem(LB_CACHE_KEY_PREFIX + metric, JSON.stringify({
        top:        Array.isArray(top) ? top : [],
        me:         me || null,
        fetched_at: Date.now(),
      }));
    } catch (_) {}
  }
  // v3 Phase 1z.36 — HoF cache read/write. Records are read-only on
  // the client (no merging, no sim injection) so the shape is simple.
  function lbHofCacheRead(metric) {
    try {
      const raw = localStorage.getItem(LB_HOF_CACHE_KEY_PREFIX + metric);
      if (!raw) return null;
      const parsed = JSON.parse(raw);
      if (!parsed || typeof parsed.fetched_at !== 'number') return null;
      if ((Date.now() - parsed.fetched_at) > LB_HOF_CACHE_MAX_AGE_MS) return null;
      return parsed;
    } catch (_) { return null; }
  }
  function lbHofCacheWrite(metric, records, me_best) {
    try {
      localStorage.setItem(LB_HOF_CACHE_KEY_PREFIX + metric, JSON.stringify({
        records:    Array.isArray(records) ? records : [],
        me_best:    me_best || null,
        fetched_at: Date.now(),
      }));
    } catch (_) {}
  }

  // v3 Phase 1z.52 — 100K Step Club cache read/write. The endpoint
  // is global (not metric-scoped) so the key is a single string,
  // unlike the per-metric caches above. Stores backend response
  // shape: { members, me, fetched_at }.
  function lb100kClubCacheRead() {
    try {
      const raw = localStorage.getItem(LB_100K_CLUB_CACHE_KEY);
      if (!raw) return null;
      const parsed = JSON.parse(raw);
      if (!parsed || typeof parsed.fetched_at !== 'number') return null;
      if ((Date.now() - parsed.fetched_at) > LB_100K_CLUB_CACHE_MAX_AGE_MS) return null;
      return parsed;
    } catch (_) { return null; }
  }
  function lb100kClubCacheWrite(members, me) {
    try {
      localStorage.setItem(LB_100K_CLUB_CACHE_KEY, JSON.stringify({
        members:    Array.isArray(members) ? members : [],
        me:         me || null,
        fetched_at: Date.now(),
      }));
    } catch (_) {}
  }

  // Compact step count: 104821 -> "104.8K", 9999 -> "9,999".
  // Used in HoF rows where space is tight and the precise digits
  // matter less than the magnitude.
  function lbFormatStepsCompact(n) {
    const v = Number(n) || 0;
    if (v < 10000) return v.toLocaleString('en-US');
    const k = v / 1000;
    // 1 decimal under 1000K, 0 decimal at/above.
    return (k >= 100 ? Math.round(k) : k.toFixed(1)) + 'K';
  }

  // Format a "Week of May 17–May 23" label given two ISO YYYY-MM-DD
  // strings. Used for the HoF row tagline.
  function lbFormatWeekRangeFromIso(weekStartIso, weekEndIso) {
    if (!weekStartIso || !weekEndIso) return '';
    const MONTHS = ['Jan','Feb','Mar','Apr','May','Jun','Jul','Aug','Sep','Oct','Nov','Dec'];
    function parts(iso) {
      const m = /^(\d{4})-(\d{2})-(\d{2})$/.exec(iso);
      if (!m) return null;
      return { mo: parseInt(m[2], 10), d: parseInt(m[3], 10) };
    }
    const a = parts(weekStartIso), b = parts(weekEndIso);
    if (!a || !b) return '';
    return 'Week of ' + MONTHS[a.mo - 1] + ' ' + a.d + '–' + MONTHS[b.mo - 1] + ' ' + b.d;
  }

  function lbFormatRelativeTime(epochMs) {
    const diffMs = Date.now() - epochMs;
    const mins = Math.floor(diffMs / 60000);
    if (mins < 1) return 'just now';
    if (mins < 60) return mins + ' min ago';
    const hrs = Math.floor(mins / 60);
    if (hrs < 24) return hrs + ' hr ago';
    return 'a while ago';
  }

  // ── Display-side alias normalization ────────────────────────
  // The backend returns whatever alias each user typed at signup.
  // For the public leaderboard we want a clean, uniform feed:
  //   • lowercase + no spaces (web-handle aesthetic)
  //   • single allowlist exception: "richie" displays as "Richie"
  //     (the product owner's handle keeps its capital R)
  //   • dedupe collisions within the rendered list by appending a
  //     numeric suffix (_2, _3, …). This is cosmetic-only — the
  //     underlying user row is unchanged and "isMe" matching still
  //     uses the raw alias field returned by the API.
  const LB_ALIAS_ALLOWLIST_LOWER = new Set(['richie']);
  const LB_ALIAS_DISPLAY_OVERRIDES = { richie: 'Richie' };

  function lbNormalizeAliasForDisplay(raw) {
    if (!raw) return '—';
    const stripped = String(raw).replace(/\s+/g, '');
    const lower = stripped.toLowerCase();
    if (LB_ALIAS_DISPLAY_OVERRIDES[lower]) return LB_ALIAS_DISPLAY_OVERRIDES[lower];
    return lower;
  }

  // Walks a list of {alias, ...} rows, applies normalization, and
  // disambiguates collisions in-place. Returns an array of the
  // normalized display strings, parallel to the input rows.
  function lbBuildDisplayAliases(rows) {
    const seen = Object.create(null);
    return rows.map(row => {
      const norm = lbNormalizeAliasForDisplay(row && row.alias);
      // Allowlist names skip the dedup suffix — "Richie" is unique.
      const lowerRaw = (row && row.alias) ? String(row.alias).toLowerCase().replace(/\s+/g, '') : '';
      if (LB_ALIAS_ALLOWLIST_LOWER.has(lowerRaw)) {
        seen[norm] = (seen[norm] || 0) + 1;
        return norm;
      }
      const count = seen[norm] || 0;
      seen[norm] = count + 1;
      return count === 0 ? norm : (norm + '_' + (count + 1));
    });
  }

  // ── W590 — Reusable skeleton / loading system ─────────────────────────────
  // showLoading(target, kind, count) paints an on-theme shimmer skeleton into a
  // host and marks it aria-busy; hideLoading(target) clears it (callers that
  // replace innerHTML with real content don't strictly need it, but it keeps
  // the busy flag honest). `kind` picks a composed template. See .skel* in
  // styles.css. Exposed on window for reuse. `target` = element or element id.
  const _SKEL_TPL = {
    line:  (n) => _skelRep(n || 3, '<div class="skel skel-line"></div>'),
    cards: (n) => _skelRep(n || 3, '<div class="skel skel-card"></div>'),
    rows:  (n) => _skelRep(n || 5,
      '<div class="skel-row"><div class="skel skel-avatar"></div>' +
      '<div class="skel-row-lines"><div class="skel skel-line skel-line--title"></div>' +
      '<div class="skel skel-line skel-line--sm"></div></div></div>'),
    grid:  (n) => '<div class="skel-grid">' + _skelRep(n || 6, '<div class="skel skel-tile"></div>') + '</div>',
    duo:   (n) => '<div class="skel-duo">' + _skelRep(n || 4, '<div class="skel skel-card" style="height:152px"></div>') + '</div>',
    hero:  ()  => '<div class="skel skel-hero"></div>' +
      '<div class="skel-duo" style="margin-top:12px">' + _skelRep(2, '<div class="skel skel-card" style="height:64px"></div>') + '</div>',
  };
  function _skelRep(n, html) { let s = ''; const c = (n | 0) || 1; for (let i = 0; i < c; i++) s += html; return s; }
  function _skelEl(t) { return (typeof t === 'string') ? document.getElementById(t) : t; }
  // W594 — returns the wrapped skeleton HTML string (no DOM write). Lets callers
  // that BUILD an innerHTML string (e.g. the co-op hunter picker) embed a
  // skeleton inline, sharing the exact markup showLoading paints.
  function _skelHtml(kind, count) {
    const tpl = _SKEL_TPL[kind] || _SKEL_TPL.cards;
    return '<div class="skel-wrap" data-skel="1">' + tpl(count) + '</div>';
  }
  function showLoading(target, kind, count) {
    const el = _skelEl(target);
    if (!el) return;
    el.classList.add('is-loading');
    el.setAttribute('aria-busy', 'true');
    el.innerHTML = _skelHtml(kind, count);
  }
  function hideLoading(target) {
    const el = _skelEl(target);
    if (!el) return;
    el.classList.remove('is-loading');
    el.removeAttribute('aria-busy');
    const w = el.querySelector('[data-skel="1"]');
    if (w) w.remove();
  }
  try { window.showLoading = showLoading; window.hideLoading = hideLoading; } catch (_) {}

  // W704 — leaderboard avatar crest. Resolves a board row to a small portrait <img>:
  // ── W706 — MEMBER CARD BACKGROUNDS ─────────────────────────────────────────
  // The catalog of member-exclusive card backgrounds (Higgsfield-painted webp in
  // assets/backgrounds/lb-bg-*.webp). Each design is UNLOCKED by an earned
  // achievement (client-checked, same trust model as rank) and EQUIPPABLE only by
  // a member (server-enforced at the profile-summary write — a non-member's equip
  // is coerced to null server-side, so the picker gate here is UX, not security).
  // Keep ids in sync with the backend CARD_BG_IDS whitelist.
  const CARD_BG_CATALOG = [
    { id: 'bg-100k',      name: 'The Hundred-K City', need: '100K Step Club' },
    { id: 'bg-floor100',  name: 'The Summit',         need: 'Clear Floor 100' },
    { id: 'bg-srank',     name: 'Stormbreaker',       need: 'Reach S Rank' },
    { id: 'bg-splus',     name: 'Beyond the Peak',    need: 'S+ Prestige' },
    { id: 'bg-boss500',   name: 'The Boneyard',       need: '500 Boss Kills' },
    { id: 'bg-arena',     name: "Champion's Ring",    need: 'Awakened Arena Tier' },
    { id: 'bg-mega',      name: 'The Vault',          need: 'Own a Mega-Rare' },
    { id: 'bg-streak365', name: 'The Eternal Flame',  need: '365-Day Streak' },
    { id: 'bg-god',       name: 'The Grinning Dark',  need: 'Defeat The Grinning God' },
    // W714 — six rank-Gate borders (clear every SOLO boss of that rank; art escalates in
    // intensity + is tinted the rank's color, E violet → S magenta) + three completion
    // trophies (all 3 mega-rares, full Collection Log, a 30-day walk-or-sleep streak).
    { id: 'bg-egate',     name: 'The E-Gate',         need: 'Clear every E-rank boss' },
    { id: 'bg-dgate',     name: 'The D-Gate',         need: 'Clear every D-rank boss' },
    { id: 'bg-cgate',     name: 'The C-Gate',         need: 'Clear every C-rank boss' },
    { id: 'bg-bgate',     name: 'The B-Gate',         need: 'Clear every B-rank boss' },
    { id: 'bg-agate',     name: 'The A-Gate',         need: 'Clear every A-rank boss' },
    { id: 'bg-sgate',     name: 'The S-Gate',         need: 'Clear every S-rank boss' },
    { id: 'bg-allmega',   name: 'The Full Vault',     need: 'Own all 3 Mega-Rares' },
    { id: 'bg-collog',    name: 'The Complete Log',   need: 'Complete the Collection Log' },
    { id: 'bg-streak30',  name: 'Thirty Days Sworn',  need: '30-Day Walk or Sleep Streak' },
    { id: 'bg-founder',   name: "Founder's Dawn",     need: 'Founder — only 20 exist' },
  ];
  function _cardBgById(id) {
    return CARD_BG_CATALOG.find(function (b) { return b.id === id; }) || null;
  }
  function _cardBgArt(id) {
    return _cardBgById(id) ? 'assets/backgrounds/lb-bg-' + id.replace(/^bg-/, '') + '.webp' : '';
  }
  // Local equip state. THREE states matter (W706 review):
  //   { set:false }            — never chosen on THIS device → the heartbeat OMITS
  //                              cardBg (server preserves; a reinstall/2nd device
  //                              must never silently clear a published equip)
  //   { set:true, id:null }    — EXPLICIT "Basic" (stored as '') → sole truth for
  //                              own display + an explicit null clear on the PUT
  //   { set:true, id:'bg-x' }  — an equipped catalog design
  // A non-member reads as { set:false } (display + payload fall back to the
  // published value, which the server nulls on their next PUT) — but the stored
  // key is kept so a re-subscribe restores the equip automatically.
  function _cardBgLocal() {
    try {
      const raw = localStorage.getItem('hb_card_bg');
      if (raw === null) return { set: false, id: null };
      if (!_founderOwned()) return { set: false, id: null };
      if (raw === '') return { set: true, id: null };
      return _cardBgById(raw) ? { set: true, id: raw } : { set: false, id: null };
    } catch (_) { return { set: false, id: null }; }
  }
  // The equipped background id for display (null = basic/unset).
  function _cardBgEquipped() { return _cardBgLocal().id; }
  // Inline paint fragment for a board row/card wearing `cardBg` (cross-user rows
  // pass the backend's row.card_bg; own surfaces pass _cardBgEquipped()). Unknown
  // ids render nothing — the row keeps the basic texture.
  function _cardBgPaintStyle(cardBg) {
    const art = cardBg ? _cardBgArt(cardBg) : '';
    return art ? "--lb-row-art:url('" + art + "');" : '';
  }
  // Has the CURRENT user EARNED the design's achievement? Client-checked (same
  // trust model as rank — cosmetic, no revenue exposure; membership itself is the
  // server-enforced gate). Every branch guards its source so a picker open can
  // never throw mid-render.
  function _cardBgUnlocked(id) {
    try {
      switch (id) {
        case 'bg-100k':      return accolades.has('step_100k_club');
        case 'bg-floor100':  return typeof getAscentState === 'function' && (getAscentState().highestCleared | 0) >= 100;
        case 'bg-srank': {
          const r = (typeof getRank === 'function') ? getRank(totalPoints).id : '';
          return r === 'S' || r === 'S+';
        }
        case 'bg-splus':     return getPrestigeLevel(totalPoints) >= 1;
        case 'bg-boss500':   return (_publicAchievementsSummary().bossesSlainTotal | 0) >= 500;
        case 'bg-arena':     return !!_pvpRating && (_pvpTier(_pvpRating.peakElo || _pvpRating.elo).name === 'Awakened' || _pvpRating.rank === 1);
        case 'bg-mega':      return typeof getInventory === 'function' && Object.keys(CARDS).some(function (cid) {
          return CARDS[cid].rarity === 'mythic' && (((getInventory().cards || {})[cid] || {}).count || 0) > 0;
        });
        case 'bg-streak365': return (buildAchievementContext().maxStreak | 0) >= 365;
        case 'bg-god':       return ((_loadCoopKills()['the_grinning_god'] || {}).count | 0) > 0;
        case 'bg-founder':   return !!(window.Auth && typeof Auth.founderSeq === 'function' && Auth.founderSeq() > 0);
        // W714 — own ALL mega-rares (vs bg-mega = own ANY one). Rarity-driven so it
        // becomes "all N" automatically if a 4th mythic is ever added. Today: exactly 3
        // (nightfall_blade, reverie_staff, vigil_bow).
        case 'bg-allmega': {
          if (typeof getInventory !== 'function') return false;
          const inv = getInventory().cards || {};
          const myth = Object.keys(CARDS).filter(function (cid) { return CARDS[cid].rarity === 'mythic'; });
          return myth.length > 0 && myth.every(function (cid) { return ((inv[cid] || {}).count || 0) > 0; });
        }
        // W714 — Collection Log 100%: every discoverable relic owned. Sums have/total
        // across the live tree, excluding the shared raid-pool node so the 3 mythics
        // aren't double-counted. Locked-rank relics still count toward total, so this
        // genuinely requires owning every relic in the game (incl. S-tier).
        case 'bg-collog': {
          if (typeof _buildCollectionTree !== 'function') return false;
          const tree = _buildCollectionTree();
          let have = 0, total = 0;
          tree.forEach(function (d) {
            (d.bosses || []).forEach(function (b) {
              if (b.shared) return;
              have += (b.have | 0); total += (b.total | 0);
            });
          });
          return total > 0 && have === total;
        }
        // W714 — 30-day WALK streak (6,000+ steps/day, durable best_walk_streak) OR
        // 30-day SLEEP streak (7h+ nights, best_sleep_streak). Honors the owner's
        // "walking or sleeping" wording with two independent first-class signals.
        case 'bg-streak30': {
          const st = (typeof loadLeaderboardState === 'function') ? loadLeaderboardState() : {};
          return (st.best_walk_streak | 0) >= 30 || (st.best_sleep_streak | 0) >= 30;
        }
        // W714 — Gate borders: clear every SOLO boss of that rank (coop bosses need a
        // partner + A/S coop is unfair/absent, so solo-only is the fair reading).
        case 'bg-egate':     return _gateSlain('E');
        case 'bg-dgate':     return _gateSlain('D');
        case 'bg-cgate':     return _gateSlain('C');
        case 'bg-bgate':     return _gateSlain('B');
        case 'bg-agate':     return _gateSlain('A');
        case 'bg-sgate':     return _gateSlain('S');
        default: return false;
      }
    } catch (_) { return false; }
  }
  // W714 — has the hunter felled every solo (non-coop) boss of `rank` at least once?
  // Solo kills live in loadBosses()[id].kill_count (hb_bosses). coopOnly stub bosses are
  // excluded (they're drop-source shells rendered from COOP_BOSSES, not the solo grid).
  function _gateSlain(rank) {
    try {
      if (typeof loadBosses !== 'function' || typeof BOSSES === 'undefined') return false;
      const solo = loadBosses() || {};
      const ids = Object.keys(BOSSES).filter(function (id) {
        return !BOSSES[id].coopOnly && BOSSES[id].rank === rank;
      });
      return ids.length > 0 && ids.every(function (id) { return ((solo[id] || {}).kill_count | 0) > 0; });
    } catch (_) { return false; }
  }
  // Equip/clear from the picker: persists locally (instant paint on own rows) and
  // nudges the profile heartbeat so the server adopts it (member-validated there).
  function _cardBgEquip(id) {
    // '' = the EXPLICIT-basic sentinel (never removeItem — an absent key means
    // "this device never chose", which the heartbeat must not turn into a clear).
    try { localStorage.setItem('hb_card_bg', id || ''); } catch (_) {}
    try { _maybeSubmitPublicRankSummary('card-bg-change'); } catch (_) {}
  }

  //   1. MY row → local getAvatarSrc() (instant on wardrobe change, pre-sync — same
  //      local-first rule the title chip uses)
  //   2. row.avatar_id / row.avatarId (cross-user, published via the profile heartbeat;
  //      snake_case is the board-row convention, camel covers the profile-shaped rows)
  //   3. sim bots → the same deterministic portrait their profile card synthesizes
  //   4. anything else / a stale cache row without the field → avatar-base.png
  // avatar_id is client-published untrusted data, so the PvP whitelist gate applies;
  // onerror falls back to the base portrait (an older build missing a newer skin file).
  // W711 — dedicated head-and-shoulders BUST portraits for the crest + profile
  // medallion. The battle/PvP/home art stays the full-body sprite (getAvatarSrc);
  // only the small round "who is this" surfaces swap to a face-filling bust so the
  // portrait reads at 48px instead of a zoomed torso-crop. Every class avatar + every
  // skin has a bust (assets/busts/<name>-bust.webp); an unknown avatar_id (old client,
  // unexpected value) returns '' → caller falls back to the full-body zoom, never blank.
  const _BUST_AVATARS = new Set([
    'avatar-base.png', 'avatar-warrior.png', 'avatar-ranger.png', 'avatar-mage.png',
    'avatar-assassin.png', 'avatar-paladin.png', 'avatar-merchant.png', 'avatar-sage.png',
    'avatar-skin-stardust.png', 'avatar-skin-dawnbringer.png', 'avatar-skin-nullprotocol.png',
    'avatar-skin-nullprotocol-2.png', 'avatar-skin-emberforged.png', 'avatar-skin-voidtouched.png',
    'avatar-skin-frostweaver.png', 'avatar-skin-tempest.png', 'avatar-skin-verdant.png',
    'avatar-skin-bloodmoon.png',
  ]);
  function _bustSrc(file) {
    return (file && _BUST_AVATARS.has(file)) ? 'assets/busts/' + file.replace(/\.png$/i, '') + '-bust.webp' : '';
  }
  function _lbCrestHtml(row, isMe, extraClass, opts) {
    let file = '';
    try {
      if (isMe && typeof getAvatarSrc === 'function') file = getAvatarSrc();
      if (!file) file = row.avatar_id || row.avatarId || '';
      if (!file && row._sim && window.SimulatedLeaderboard && typeof SimulatedLeaderboard.profile === 'function') {
        const dk = (typeof getDeviceLocalDate === 'function') ? getDeviceLocalDate() : '';
        const p = SimulatedLeaderboard.profile(row.alias, dk);
        file = (p && p.avatarId) || '';
      }
    } catch (_) { file = ''; }
    const safe = (typeof file === 'string' && /^avatar[a-z0-9_-]*\.png$/i.test(file)) ? file : 'avatar-base.png';
    // W705 — the crest now sits inside a rotated DIAMOND frame (the Rendell-mock
    // look); the img counter-rotates inside so the portrait stays upright. The
    // extraClass modifier ('lb-crest--leader' / 'lb-crest--foot') maps onto the
    // FRAME, which owns size + ring color; ring tints still key off row context
    // (.lb-rank-row--me / --medal2 / --medal3) in CSS.
    // NOTE: no loading="lazy" — the sheet is hidden while rows are inserted, and lazy
    // images inside a hidden-at-insert container can stay unloaded after it opens
    // (verified in the browser preview). These are ~10 small bundled PNGs; eager is free.
    const frameMod = extraClass ? ' ' + extraClass.replace(/lb-crest--/g, 'lb-crest-frame--') : '';
    // W706 — full handoff-21 crest anatomy: the frame carries an inline --rc ring
    // color (rank-mapped; me=gold, medals silver/bronze), a prestige ✦ star on top
    // and the Founder mark pinned bottom-right (both counter-rotated upright).
    const o = opts || {};
    const ring = o.ring ? ' style="--rc:' + o.ring + '"' : '';
    const star = o.star
      ? '<span class="lb-crest-star" aria-hidden="true">✦</span>' : '';
    // W707 — Founder mark is now the ✦ STAR coin (owner preferred the star over the 'F').
    const fMark = (o.founderSeq | 0) > 0
      ? '<span class="lb-crest-founder" title="Founder #' + (o.founderSeq | 0) + '">✦</span>' : '';
    // W707 — CIRCLE bust crest (reverted the W705 rotated diamond, which framed the
    // torso — the full-body avatar art has the head in the top ~15%, so the diamond
    // center-crop never showed a face). The portrait is a background layer zoomed to
    // head+shoulders (background-size 260% / position 50% 2%, tuned against the real
    // avatar art in a Playwright harness) on a dark well; `safe` is regex-validated
    // (avatar-base.png for anything unknown), so no <img> onerror is needed.
    // Structure: frame (circle, ring, NO overflow so the star + Founder coin hang past
    // its edge) > well (overflow:hidden circular clip) > por (the zoomed portrait).
    // W711 — prefer the bust portrait (face fills the well); fall back to the full-body
    // sprite with the old head-zoom crop (via .lb-crest-por default CSS) if no bust exists.
    const _bust = _bustSrc(safe);
    const _porSrc = _bust || safe;
    const _porCls = _bust ? ' lb-crest-por--bust' : '';
    return '<span class="lb-crest-frame' + frameMod + '"' + ring + ' aria-hidden="true">' +
      '<span class="lb-crest-well">' +
        '<span class="lb-crest-por' + _porCls + '" style="background-image:url(\'' + _porSrc + '\')"></span>' +
      '</span>' +
      star + fMark +
    '</span>';
  }
  // W706 — the handoff-21 rank color map (E–S+), the single source for the hexagon
  // rank badge tint + crest ring + gem hues on board rows.
  const _LB_RANK_COLORS = { E: '#8b5cf6', D: '#22d3ee', C: '#34d399', B: '#fbbf24', A: '#ef4444', S: '#e879f9', 'S+': '#e879f9' };
  function _lbRankColor(tier) { return _LB_RANK_COLORS[tier] || '#a78bfa'; }

  // W705 — faint right-side sigil watermark on standard rows (the mock's wolf/
  // swords/shield marks). Keyed off the same tier ladder as the gem class label
  // (iron/teal/violet/gold), so a hunter's sigil matches their title tier:
  // gold → crown, violet → wolf, teal → crossed blades, iron → shield.
  function _lbSigilHtml(tier) {
    const paths = {
      gold:   '<path d="M3 17.5h18M4 16l-1.5-8L8 12l4-8 4 8 5.5-4L20 16z" stroke="currentColor" stroke-width="1.4" stroke-linejoin="round" fill="none"/>',
      violet: '<path d="M12 21l-5-4-2-7 4-6 1 4h4l1-4 4 6-2 7z M9 12l1 2M15 12l-1 2M12 15v3" stroke="currentColor" stroke-width="1.3" stroke-linejoin="round" fill="none"/>',
      teal:   '<path d="M5 3l13 13M19 3L6 16M4 17l3 3M17 20l3-3M8 15l-3 4M16 15l3 4" stroke="currentColor" stroke-width="1.4" stroke-linecap="round" fill="none"/>',
      iron:   '<path d="M12 3l7 2.5V12c0 4-3 6.8-7 8.5C8 18.8 5 16 5 12V5.5z M12 7v9M8.5 10.5h7" stroke="currentColor" stroke-width="1.3" stroke-linejoin="round" fill="none"/>',
    };
    // Normalize unknown tiers (e.g. 'summit' — The Second Awakened) to gold for
    // BOTH the path and the color class, so the top title never renders untinted.
    const t = paths[tier] ? tier : 'gold';
    return '<span class="lb-sigil lb-sigil--' + t + '" aria-hidden="true">' +
      '<svg viewBox="0 0 24 24">' + paths[t] + '</svg>' +
    '</span>';
  }

  // Renders the rank-list content given a backend response. Splits
  // the user-row out of the top-N (or surfaces a separate "your rank"
  // line if me.rank > top.length). Empty top → first-to-rank message.
  function lbBuildRankList(metric, top, me, stale_footer) {
    const meta = LB_METRIC_META[metric];
    if (!meta) return '';

    // W718b — remember the user's DISPLAYED Steps-board position (post sim-merge,
    // exactly what renders here) for the home widget. Only the real Steps board
    // writes it; a change nudges the widget so the tile updates on board-open.
    // W720 — gate to the LIVE GLOBAL board only. The Friends tab (rank among
    // friends, e.g. #2 of 4) and archived past-week boards (a frozen rank) also
    // render metric 'step_total' through here; without this gate they'd clobber
    // the widget with a friends-relative or stale-week position.
    try {
      if (metric === 'step_total' && _lbCurrentTab === 'this-week' && _lbArchWeek === null
          && me && typeof me.rank === 'number' && me.rank > 0) {
        var _wr = String(me.rank | 0);
        if (localStorage.getItem('hb_lb_step_rank') !== _wr) {
          localStorage.setItem('hb_lb_step_rank', _wr);
          if (typeof _pushWidgetState === 'function') _pushWidgetState();
        }
      }
    } catch (_) {}

    if (!Array.isArray(top) || top.length === 0) {
      return (
        '<div class="lb-rank-empty">' +
          '<div class="lb-rank-empty-icon" aria-hidden="true">🏆</div>' +
          '<div class="lb-rank-empty-title">Be the first to rank.</div>' +
          '<div class="lb-rank-empty-body">Start tracking your ' + esc(meta.unit) + ' to claim the top spot.</div>' +
        '</div>'
      );
    }

    const myAlias = lbGetMyAlias();
    const myAliasDisplay = lbNormalizeAliasForDisplay(myAlias);
    let yourRankLine = '';

    // If the user is OUTSIDE the top-N (or has not submitted yet),
    // show a separate "Your rank: #N" line above the top-N list.
    if (me && typeof me.rank === 'number' && me.rank > 0) {
      const inTopN = top.some(r => r && r.alias === myAlias);
      if (!inTopN) {
        yourRankLine =
          '<div class="lb-rank-row lb-rank-row--me lb-rank-row--out-of-top" data-profile-alias="' + esc(myAlias || '') + '">' +
            '<span class="lb-rank-pos">' + me.rank + '</span>' +
            _lbCrestHtml({}, true, '') +   // W704 — own crest (this row is always the caller); keeps the name column aligned with crested rows below
            '<span class="lb-rank-name">' + esc(myAliasDisplay || 'You') + '</span>' +
            '<span class="lb-rank-value">' + meta.formatValue(me.current_value) + '</span>' +
          '</div>' +
          '<div class="lb-rank-divider" aria-hidden="true"></div>';
      }
    } else if (!me) {
      // me === null → user hasn't submitted this metric yet (or
      // lbSubmitAllMetrics hasn't fired since sign-in).
      //
      // v3 Phase 1z.116 — for metrics with a min-qualifying-score
      // (currently sleep_streak >= 3), suppress the pending
      // placeholder when the user's local snapshot is below the
      // floor. The board is meant to show only earned entries; a
      // "submitting…" row for someone with 0 verified nights reads
      // as the same noise we're filtering out from the top-N.
      let suppressPending = false;
      // W658 review fix — a closed FINAL week has no "submitting…" state: a
      // null me on an archived board simply means the user isn't on it.
      try { if (_lbArchWeek !== null) suppressPending = true; } catch (_) {}
      try {
        const _floor = (typeof _LB_MIN_QUALIFYING_SCORE !== 'undefined') && _LB_MIN_QUALIFYING_SCORE[metric];
        if (typeof _floor === 'number') {
          const _snap = lbGetSnapshot();
          let _myLocal = 0;
          if (metric === 'sleep_streak')        _myLocal = (_snap && _snap.current_sleep_streak)   || 0;
          // v3 Phase 1z.118 — workout_streak replaces bedtime_streak.
          else if (metric === 'workout_streak') _myLocal = (_snap && _snap.current_workout_streak) || 0;
          // v3 Phase 1z.125 — flights_climbed local fallback.
          else if (metric === 'flights_climbed') _myLocal = (_snap && _snap.flights_this_week) || 0;
          else if (metric === 'step_total')     _myLocal = (_snap && _snap.steps_last_7_days)      || 0;
          if (_myLocal < _floor) suppressPending = true;
        }
      } catch (_) {}

      if (!suppressPending) {
        yourRankLine =
          '<div class="lb-rank-row lb-rank-row--me lb-rank-row--pending">' +
            '<span class="lb-rank-pos">—</span>' +
            _lbCrestHtml({}, true, '') +   // W704 — keep the pending row aligned with crested rows
            '<span class="lb-rank-name">' + esc(myAliasDisplay || 'You') + ' <em class="lb-rank-name-sub">· submitting…</em></span>' +
            '<span class="lb-rank-value">—</span>' +
          '</div>' +
          '<div class="lb-rank-divider" aria-hidden="true"></div>';
      }
    }

    // Build display aliases for the top-N list — lowercase + no
    // spaces, dedup suffixes on collisions, allowlist for "Richie".
    const displayAliases = lbBuildDisplayAliases(top);
    // W333 — ClaudeDesign redesign: the top value sets the 100% baseline
    // for each row's gold progress fill.
    const _lbLeaderVal = (top[0] && Number(top[0].current_value)) || 0;
    // W386 — the leader eyebrow names the active board context
    // ("★ LEADER · THIS WEEK" in the redesign mock). Derived from the
    // open tab so Friends / Hall-of-Fame leaders read correctly too.
    // W631 — tab context applies ONLY to tabbed boards (LB_HOF_METRICS):
    // _lbCurrentTab defaults to 'this-week' on every open, so untabbed
    // boards (floor_best, relics_collected — both all-time races) wrongly
    // read "· THIS WEEK". They get the plain "★ LEADER".
    let _lbLeaderCtx = '';
    try {
      if (LB_HOF_METRICS.has(metric)) {
        const _t = (typeof _lbCurrentTab === 'string') ? _lbCurrentTab : 'this-week';
        // W658 — an archived week's leader is a FINAL result, never "THIS
        // WEEK": frozen history must not read as a live race.
        if      (_t === 'this-week') _lbLeaderCtx = (_lbArchWeek !== null) ? ' · FINAL' : ' · THIS WEEK';
        else if (_t === 'friends')   _lbLeaderCtx = ' · FRIENDS';
        else if (_t === 'hof')       _lbLeaderCtx = ' · ALL-TIME';
      }
    } catch (_) {}
    const topRows = top.map((row, i) => {
      const isMe = myAlias && row.alias === myAlias;
      const rankClass = isMe ? 'lb-rank-row lb-rank-row--me' : 'lb-rank-row';
      // W257 — equipped Arena title chip. The id comes from the backend row
      // (real users) or the sim merge (bots); MY row prefers local equipped
      // state so the chip updates instantly, before any backend round-trip.
      // Unknown/absent ids render nothing (back/forward compatible).
      let titleId = row.arena_title || null;
      if (isMe) { try { const t = getEquippedArenaTitle(); titleId = (t && t.id) || titleId; } catch (_) {} }
      // W267 — legacy ids from pre-W266 clients render as their ladder successors
      try { if (titleId && _ARENA_TITLE_LEGACY[titleId]) titleId = _ARENA_TITLE_LEGACY[titleId]; } catch (_) {}
      // W333 — ClaudeDesign redesign: the equipped title becomes a quiet
      // gem "class label" UNDER the name (tier-colored), replacing the inline
      // shard pill. Same tier ladder (iron / teal / violet / gold).
      let classLabel = '';
      // W705 — the tier drives BOTH the gem class label and the row's sigil
      // watermark; untitled hunters default to iron (the plain shield).
      let _lbTier = 'iron';
      if (titleId && typeof ARENA_TITLES !== 'undefined') {
        const tdef = ARENA_TITLES.find((t) => t.id === titleId);
        if (tdef) {
          _lbTier = tdef.tier || 'gold';
          // W388 — crimson stamp for the 100-boss-kills club, beside the gold
          // 100K stamp. Real backend data only (bosses_slain from pps); sims
          // are excluded so it's never faked. Dark until the backend ships
          // the field (older payloads omit it → no stamp).
          // W583 — the stamp UPGRADES every 100 kills: the label is the
          // highest century crossed (100, 200, 300…), so a 279-kill hunter
          // wears 200 and ticks to 300 at kill #300. Same chip, same rules —
          // only the number climbs (CSS width flexes for 3-4 digit tiers).
          const _bossKills = row._sim ? 0 : (Number(row.bosses_slain) || 0);
          const _bossTier  = Math.floor(_bossKills / 100) * 100;   // 0 below 100 → no stamp
          classLabel = '<span class="lb-rank-class lb-rank-class--' + _lbTier + '">' +
            '<i class="lb-rank-gem" aria-hidden="true"></i>' +
            '<span class="lb-rank-class-name">' + esc(tdef.name) + '</span>' +
            (row.club_100k ? '<i class="lb-rank-club100k" title="100K Step Club" aria-label="100K Step Club member">100K</i>' : '') +
            (_bossTier >= 100 ? '<i class="lb-rank-boss100" title="' + _bossTier + '+ boss kills slain" aria-label="' + _bossTier + '+ boss kills">' +
              '<svg viewBox="0 0 24 24" width="8" height="10" aria-hidden="true"><g fill="#fff1ec"><path d="M12 1.5 14 6 14 13.6 10 13.6 10 6Z"/><rect x="6.6" y="13" width="10.8" height="2.1" rx="1"/><rect x="10.7" y="15" width="2.6" height="3.8" rx="1"/><circle cx="12" cy="19.6" r="1.4"/></g></svg>' + _bossTier + '</i>' : '') +
          '</span>';
        }
      }
      // W274 — finishers (Floor 100, in the Hall of the Awakened) wear a gold
      // crown on the floor board, cross-linking the race to the finish line.
      // W622 — a COMPLETED Collection Log wears the same crown (finish-line
      // language shared across race boards). Total is runtime-derived from the
      // live catalog; guarded > 0 so an empty catalog can never crown everyone.
      const _relicsDone = metric === 'relics_collected' && (function () {
        try { const t = _lbRelicsLogStats().total; return t > 0 && (row.current_value || 0) >= t; } catch (_) { return false; }
      })();
      const crown = ((metric === 'floor_best' && (row.current_value || 0) >= 100) || _relicsDone)
        ? '<span class="lb-rank-crown" title="' + (_relicsDone ? 'Collection complete — every relic logged' : 'Awakened — cleared all 100 floors') + '" aria-label="' + (_relicsDone ? 'Collection complete' : 'Awakened') + '">' +
            '<svg viewBox="0 0 16 12" width="13" height="10" aria-hidden="true"><path d="M1 11h14l-1.2-7L10 7.5 8 1 6 7.5 2.2 4z" fill="#f5b842" stroke="#c08418" stroke-width="0.7" stroke-linejoin="round"/></svg>' +
          '</span>'
        : '';
      // W453 — Prestige ✦ on the board: the long-term S+ player base visibly
      // "stunts on noobs". Gold stars beside the name; data rides the top-N read
      // (row.prestige + row.rankTier from public_profile_summary). 0/absent → none.
      const _pNum = Number(row.prestige) || 0;
      const pStar = (row.rankTier === 'S+' && _pNum > 0)
        ? '<span class="lb-rank-prestige" title="Prestige ' + _pNum + '" aria-label="Prestige ' + _pNum + '">' + prestigeStars(_pNum) + '</span>'
        : '';
      // W333 — progress fill ratio (this value vs the current leader).
      const _pct = _lbLeaderVal > 0
        ? Math.max(5, Math.min(100, Math.round((Number(row.current_value) || 0) / _lbLeaderVal * 100)))
        : 0;
      const _medal = (row.rank >= 2 && row.rank <= 3) ? ' lb-rank-row--medal' + row.rank : '';
      const _youPill = isMe ? '<span class="lb-you-pill">YOU</span>' : '';
      // W656 — free Founder marker crest on ANY row that earned it (cross-user;
      // the board carries founderSeq from public_profile_summary). ✦ + the number.
      const _fSeq = (row.founderSeq | 0);
      const _founderChip = _fSeq > 0
        ? '<span class="lb-rank-founder" title="Founder #' + _fSeq + '" aria-label="Founder number ' + _fSeq + '">✦</span>' : '';
      const _nameDisp = esc(displayAliases[i] || '—');
      // W706 — handoff-21 anatomy: rank-mapped ring color (me=gold, medals
      // silver/bronze), prestige ✦ + Founder mark ride ON the crest, and a
      // member's chosen card background paints the row (own row reads the LOCAL
      // equip for instant feedback; others read the published row.card_bg).
      // W709 — the ring + number color is ALWAYS the hunter's rank tier (E→S+), so it
      // matches their profile-card rank badge everywhere (owner: "A-rank = red… make it
      // consistent"). The old me=gold / #2=silver / #3=bronze overrides made a hunter a
      // different color on their own row than on their card; placement is shown by the
      // number itself + the #1 hero card, not by recolouring the tier.
      const _ring = _lbRankColor(row.rankTier);
      const _crestOpts = { ring: _ring, star: (row.rankTier === 'S+' && _pNum > 0), founderSeq: _fSeq };
      // Own row: an EXPLICIT local state (equip OR Basic) is sole truth — a Basic
      // clear must not fall through to the stale published row.card_bg. A device
      // that never chose falls back to the published value (multi-device).
      let _bg = row.card_bg || null;
      if (isMe) { const _cb = _cardBgLocal(); if (_cb.set) _bg = _cb.id; }
      const _paint = _cardBgPaintStyle(_bg);
      const _paintCls = _paint ? ' lb-rank-row--painted' : '';

      // #1 is enthroned as a hero card; the rest form the calm list below.
      if (row.rank === 1) {
        return '<div class="lb-rank-leader' + (isMe ? ' lb-rank-leader--me' : '') + '"' +
          (_paint ? ' style="' + _paint + '"' : '') +   // W706 — leader's own chosen bg overrides the default citadel
          ' data-profile-alias="' + esc(row.alias || '') + '"' + (row._sim ? ' data-profile-sim="1"' : '') + '>' +
          '<span class="lb-rank-leader-glow" aria-hidden="true"></span>' +
          '<span class="lb-rank-leader-row">' +
            // W704 \u2014 left group wraps crest + info so the leader card's
            // space-between keeps the stat pinned right.
            '<span class="lb-rank-leader-left">' +
              // W706 — the #1 pennant hangs off the hero crest (handoff-21).
              '<span class="lb-crest-wrap"><span class="lb-pennant" aria-hidden="true">1</span>' +
                _lbCrestHtml(row, isMe, 'lb-crest--leader', { ring: _ring }) +   // W706 — ring only; name line carries prestige/founder
              '</span>' +
              '<span class="lb-rank-leader-info">' +
                // W709 \u2014 owner: just "LEADER" (the "\u00b7 THIS WEEK" ctx wrapped to a 2nd line).
                '<span class="lb-rank-leader-eyebrow">' + (isMe ? '\u2605 LEADER \u00b7 YOU' : '\u2605 LEADER') + '</span>' +
                // W706 — the roomy leader card keeps the RICH name-line indicators
                // (prestige star COUNT + Founder #N chip); its crest gets ring-only
                // opts (below) so nothing double-renders. Standard cramped rows do the
                // opposite: mark on the crest, nothing on the name line.
                '<span class="lb-rank-leader-name">' + _nameDisp + crown + pStar + _founderChip + '</span>' +
                classLabel +
              '</span>' +
            '</span>' +
            '<span class="lb-rank-leader-stat">' +
              '<span class="lb-rank-leader-value">' + meta.formatValue(row.current_value) + '</span>' +
              '<span class="lb-rank-leader-unit">' + esc(String(meta.unit || '').toUpperCase()) + '</span>' +
            '</span>' +
          '</span>' +
        '</div>';
      }

      return '<div class="' + rankClass + _medal + (crown ? ' lb-rank-row--awakened' : '') + _paintCls + '"' +
        ' style="--lb-fill:' + _pct + '%;' + _paint + '"' +
        ' data-profile-alias="' + esc(row.alias || '') + '"' + (row._sim ? ' data-profile-sim="1"' : '') + '>' +
        '<span class="lb-rank-fill" aria-hidden="true"></span>' +
        _lbSigilHtml(_lbTier) +   // W705 — faint tier sigil watermark, right side
        // W706 — hexagon rank badge, rank-color tinted (handoff-21 .rankno atom);
        // the ✦ prestige + Founder mark moved ONTO the crest (crest opts above).
        '<span class="lb-rank-pos lb-rankno" style="--rc:' + _ring + '">' + (row.rank || '?') + '</span>' +
        _lbCrestHtml(row, isMe, '', _crestOpts) +
        '<span class="lb-rank-id">' +
          '<span class="lb-rank-name-row">' +
            '<span class="lb-rank-name">' + _nameDisp + '</span>' + crown + _youPill +
          '</span>' +
          classLabel +
        '</span>' +
        '<span class="lb-rank-value">' + meta.formatValue(row.current_value) + '</span>' +
      '</div>';
    }).join('');

    const footer = stale_footer
      ? '<div class="lb-rank-footer">' + esc(stale_footer) + '</div>'
      : '';

    return yourRankLine + topRows + footer;
  }

  // v3 Phase 1z.36 — Hall of Fame list builder. Simpler than the
  // current-week renderer: no out-of-top row (me_best is its own
  // pinned card above the list), no simulated entries, no
  // alias dedupe gymnastics (HoF rows are independent records
  // and the same real user can appear multiple times under their
  // canonical alias). Empty state explicitly references the
  // "set a weekly record" framing instead of "be the first to rank".
  //
  // v3 Phase 1z.141 — capped to the top 10 ranked records. HoF is
  // meant to feel exclusive and clean ("highest verified weekly
  // totals ever") so #11+ is dropped at the render layer. The
  // backend can keep returning a larger window (currently `limit=50`)
  // without harm — the slice happens here only for the ranked list.
  // "Your Best" stays visible via lbBuildHofMeBest even when the
  // caller's best falls outside the top 10. 100K Club and This Week
  // tabs use different builders and are not affected.
  const HOF_DISPLAY_LIMIT = 10;
  function lbBuildHofList(records) {
    if (!Array.isArray(records) || records.length === 0) {
      return (
        '<div class="lb-rank-empty">' +
          '<div class="lb-rank-empty-icon" aria-hidden="true">🏆</div>' +
          '<div class="lb-rank-empty-title">No records yet</div>' +
          '<div class="lb-rank-empty-body">Be the first hunter to set a weekly record.</div>' +
        '</div>'
      );
    }
    const myAlias = lbGetMyAlias();
    return records.slice(0, HOF_DISPLAY_LIMIT).map(rec => {
      const isMe = myAlias && rec.alias === myAlias;
      const aliasDisplay = lbNormalizeAliasForDisplay(rec.alias);
      const weekLabel = lbFormatWeekRangeFromIso(rec.week_start, rec.week_end);
      // W713 — main-board parity: tier-colored ring + number, prestige ✦ / Founder mark
      // on the crest, and a member's card background paints the row (was a default violet
      // ring + grey #N + basic-only bg).
      const _ring = _lbRankColor(rec.rankTier);
      const _crestOpts = { ring: _ring, star: (rec.rankTier === 'S+' && (rec.prestige | 0) > 0), founderSeq: (rec.founderSeq | 0) };
      let _bg = rec.card_bg || null;
      if (isMe) { const _cb = _cardBgLocal(); if (_cb.set) _bg = _cb.id; }
      const _paint = _cardBgPaintStyle(_bg);
      const rowClass = 'lb-rank-row lb-rank-row--hof' + (isMe ? ' lb-rank-row--me' : '') + (_paint ? ' lb-rank-row--painted' : '');
      return '<div class="' + rowClass + '"' + (_paint ? ' style="' + _paint + '"' : '') + '>' +
        '<span class="lb-rank-pos lb-rankno" style="--rc:' + _ring + '">' + (rec.rank || '?') + '</span>' +
        _lbCrestHtml(rec, isMe, '', _crestOpts) +   // W704 crest + W713 tier/founder opts
        '<span class="lb-rank-name">' +
          esc(aliasDisplay || '—') +
          (weekLabel ? '<span class="lb-rank-row__weeks">' + esc(weekLabel) + '</span>' : '') +
        '</span>' +
        '<span class="lb-rank-value">' + esc(lbFormatStepsCompact(rec.steps)) + ' steps</span>' +
      '</div>';
    }).join('');
  }

  // Renders the pinned "YOUR BEST" me-best row above the HoF list.
  // Null me_best → empty-state copy. Setting the contents on the
  // dedicated element keeps the list scrollable without scrolling
  // the user's own pinned record off-screen.
  function lbBuildHofMeBest(meBest) {
    if (!meBest) {
      return (
        '<div class="lb-rank-mebest__empty">No Hall of Fame record yet.</div>'
      );
    }
    const weekLabel = lbFormatWeekRangeFromIso(meBest.week_start, meBest.week_end);
    return (
      '<div>' +
        '<div class="lb-rank-mebest__label">Your best</div>' +
        '<div class="lb-rank-mebest__value">' +
          '#' + (meBest.rank || '?') + ' · ' +
          esc(lbFormatStepsCompact(meBest.steps)) + ' steps' +
          (weekLabel ? ' · ' + esc(weekLabel) : '') +
        '</div>' +
      '</div>'
    );
  }

  // v3 Phase 1z.52 — 100K Step Club row + me-best builders.
  // Mirrors lbBuildHofList in shape (rank · alias · stat · week
  // range), but adds the `Qualified Nx` line for users with
  // repeat_count > 1 and uses a gold prestige accent in CSS to
  // signal that this is the exclusive board.
  function lbBuild100kClubList(members) {
    if (!Array.isArray(members) || members.length === 0) {
      return (
        '<div class="lb-rank-empty">' +
          '<div class="lb-rank-empty-icon" aria-hidden="true">🩸</div>' +
          '<div class="lb-rank-empty-title">No hunters in the 100K Club yet.</div>' +
          '<div class="lb-rank-empty-body">First to 100,000 verified steps in a single week claims the first seat.</div>' +
        '</div>'
      );
    }
    const myAlias = lbGetMyAlias();
    return members.map(m => {
      const isMe = myAlias && m.alias === myAlias;
      const aliasDisplay = lbNormalizeAliasForDisplay(m.alias);
      const weekLabel = lbFormatWeekRangeFromIso(m.unlock_week_start, m.unlock_week_end);
      // W368 — repeat qualifiers get a gold ×N prestige chip beside the name
      // (was a quiet grey "Qualified Nx" sub-line). best_value stays the headline.
      const mult = (typeof m.repeat_count === 'number' && m.repeat_count > 1)
        ? '<span class="lb-club-mult" title="Qualified ' + m.repeat_count + ' separate weeks">×' + m.repeat_count + '</span>'
        : '';
      // W713 — main-board parity (tier ring + number, prestige/founder crest, member bg).
      const _ring = _lbRankColor(m.rankTier);
      const _crestOpts = { ring: _ring, star: (m.rankTier === 'S+' && (m.prestige | 0) > 0), founderSeq: (m.founderSeq | 0) };
      let _bg = m.card_bg || null;
      if (isMe) { const _cb = _cardBgLocal(); if (_cb.set) _bg = _cb.id; }
      const _paint = _cardBgPaintStyle(_bg);
      const rowClass = 'lb-rank-row lb-rank-row--club-100k' + (isMe ? ' lb-rank-row--me' : '') + (_paint ? ' lb-rank-row--painted' : '');
      return '<div class="' + rowClass + '"' + (_paint ? ' style="' + _paint + '"' : '') + '>' +
        '<span class="lb-rank-pos lb-rankno" style="--rc:' + _ring + '">' + (m.rank || '?') + '</span>' +
        _lbCrestHtml(m, isMe, '', _crestOpts) +   // W704 crest + W713 tier/founder opts
        '<span class="lb-rank-name">' +
          esc(aliasDisplay || '—') + mult +
          (weekLabel ? '<span class="lb-rank-row__weeks">' + esc(weekLabel) + '</span>' : '') +
        '</span>' +
        '<span class="lb-rank-value">' + esc(lbFormatStepsCompact(m.best_value)) + ' steps</span>' +
      '</div>';
    }).join('');
  }

  // Renders the pinned "YOUR 100K CLUB RECORD" me-best row at the
  // top of the 100K Club tab. Null me → encouragement empty state.
  function lbBuild100kClubMeBest(me) {
    if (!me) {
      return '<div class="lb-rank-mebest__empty">No 100K Club record yet. Reach 100,000 verified steps in one week to join.</div>';
    }
    const weekLabel = lbFormatWeekRangeFromIso(me.unlock_week_start, me.unlock_week_end);
    const mult = (typeof me.repeat_count === 'number' && me.repeat_count > 1)
      ? ' <span class="lb-club-mult" title="Qualified ' + me.repeat_count + ' separate weeks">×' + me.repeat_count + '</span>'
      : '';
    return (
      '<div>' +
        '<div class="lb-rank-mebest__label">Your 100K Club record</div>' +
        '<div class="lb-rank-mebest__value">' +
          '#' + (me.rank || '?') + ' · ' +
          esc(lbFormatStepsCompact(me.best_value)) + ' steps' + mult +
          (weekLabel ? ' · ' + esc(weekLabel) : '') +
        '</div>' +
      '</div>'
    );
  }

  function lbBuildLoadingSkeleton() {
    let html = '';
    for (let i = 0; i < 5; i++) {
      html +=
        '<div class="lb-rank-row lb-rank-row--skeleton">' +
          '<span class="lb-rank-pos lb-skel-block"></span>' +
          '<span class="lb-rank-name lb-skel-block"></span>' +
          '<span class="lb-rank-value lb-skel-block"></span>' +
        '</div>';
    }
    return html;
  }

  function lbBuildErrorState(code) {
    if (code === 'STUB_USER' || code === 'NOT_SIGNED_IN' || code === 'LOCAL_DEV_SKIP') {
      return (
        '<div class="lb-rank-empty">' +
          '<div class="lb-rank-empty-icon" aria-hidden="true">🔒</div>' +
          '<div class="lb-rank-empty-title">Sign in to see live rankings.</div>' +
          '<div class="lb-rank-empty-body">Real leaderboard data requires an Awakened account.</div>' +
        '</div>'
      );
    }
    return (
      '<div class="lb-rank-empty">' +
        '<div class="lb-rank-empty-icon" aria-hidden="true">📡</div>' +
        '<div class="lb-rank-empty-title">Couldn’t load rankings.</div>' +
        '<div class="lb-rank-empty-body">Check your connection. The list updates each time you open this tab.</div>' +
      '</div>'
    );
  }

  // Reads the signed-in user's alias (for highlighting their row in
  // the leaderboard). Returns null if not signed in or on stub.
  function lbGetMyAlias() {
    try {
      if (typeof window.Auth === 'undefined') return null;
      const u = window.Auth.getCurrentUser();
      return (u && u.alias) ? u.alias : null;
    } catch (_) { return null; }
  }

  // Tracks the open metric so concurrent fetches don't write into
  // a stale DOM (user switched tabs mid-fetch).
  let _lbCurrentOpenMetric = null;

  // v3 Phase 1s — wrap the leaderboard `top` / `me` view-model with
  // client-side simulated hunters so a sparse board doesn't feel
  // empty. Pure render-layer enrichment: the cache + the backend
  // response stay untouched (caching path writes the REAL response
  // before this runs). Fires for all three metrics; the sim module
  // shapes values per-metric (continuous for steps, integer streak
  // for sleep / bedtime). Flip SIMULATE_USERS in
  // simulated-leaderboard.js to disable.
  // v3 Phase 1z.118 — bedtime_streak removed from sim metrics (the
  // leaderboard card was retired); workout_streak takes its place
  // with the same simulated-merge shape (small integer, ±jitter).
  // v3 Phase 1z.125 — flights_climbed joins the sim-eligible set.
  // W622 — relics_collected is deliberately ABSENT: the Collection Log board is
  // a real race among real hunters. Sim bots with fabricated relic counts would
  // be fake competitors on a finish-line board, not harmless filler.
  // W786 — relics_collected JOINS the sim set. It was absent, and _lbMaybeSimulate
  // returns EARLY for any metric not listed here — before the min-qualifying-score
  // filter further down. So the Collection board got no sim hunters AND its W622
  // 0-relic floor was unreachable, which is why the board rendered a wall of
  // '0 / 73' rows. Listing it fixes both in one move.
  const _LB_SIM_METRICS = { step_total: 1, sleep_streak: 1, workout_streak: 1, flights_climbed: 1, floor_best: 1, rank_band: 1, relics_collected: 1 };
  // v3 Phase 1z.116 — per-metric minimum-score filter applied AFTER
  // simulated-leaderboard merge but BEFORE the rank list renders.
  // Rationale: a "7+ hour sleep streak" leaderboard showing entries
  // with 0/1/2 nights looks unearned. Force a 3-night floor so the
  // board only shows users who've actually started a streak. Other
  // metrics (step_total, bedtime_streak) keep the default of 0 — no
  // floor — until a product decision changes that.
  const _LB_MIN_QUALIFYING_SCORE = { relics_collected: 5 };   // W622 no 0-relic rows; W786 raised 1 -> 5 (owner) so the collection race shows hunters with a real log, not a 1-relic row
  function _lbMaybeSimulate(metric, top, me) {
    if (!_LB_SIM_METRICS[metric]) return { top: top, me: me };
    if (typeof window.SimulatedLeaderboard === 'undefined') return { top: top, me: me };
    if (!window.SimulatedLeaderboard.SIMULATE_USERS) return { top: top, me: me };
    const myAlias = lbGetMyAlias();
    if (!myAlias) return { top: top, me: me };
    // Real user's current value — prefer the server's `me.current_value`
    // (already canonical), fall back to the local snapshot if the user
    // is mid-submit / has no server rank yet. Snapshot field varies by
    // metric.
    const backendMeValue = (me && typeof me.current_value === 'number') ? me.current_value : 0;
    let myValue = backendMeValue;

    // v3 Phase 1z.126 / 1z.127 — optimistic local override.
    //
    // Background: weekly Health metrics (step_total, flights_climbed)
    // refresh local snapshot from HealthKit then submit to backend.
    // The modal then fetches backend `top` for rendering. If submit
    // and fetch race, the backend can return a stale me row with the
    // pre-refresh value while the local snapshot already has the
    // fresh number. Without this override, the modal renders the
    // stale value (the 1z.125→1z.126 bug: local=38, backend=0,
    // modal shows 0).
    //
    // Rule: if the local snapshot value is HIGHER than the backend
    // value, prefer local. We never override DOWNWARD — a higher
    // backend value reflects either another device's submit or a
    // historical value the local snapshot hasn't loaded yet, and we
    // don't want to clobber that with a smaller local number. This
    // is a one-way ratchet: local wins only when it's strictly
    // greater.
    //
    // Applies to all sim-eligible metrics uniformly so step/sleep/
    // workout get the same race protection (in practice they almost
    // never trigger because their submit cadence has historically
    // kept backend ≥ local).
    let localSnapValue = 0;
    try {
      const snap = lbGetSnapshot();
      if (snap) {
        if (metric === 'step_total')          localSnapValue = snap.steps_last_7_days  || 0;
        else if (metric === 'sleep_streak')   localSnapValue = snap.current_sleep_streak   || 0;
        else if (metric === 'workout_streak') localSnapValue = snap.current_workout_streak || 0;
        else if (metric === 'flights_climbed') localSnapValue = snap.flights_this_week || 0;
        else if (metric === 'floor_best') { try { localSnapValue = (getAscentState().highestCleared | 0); } catch (_) { localSnapValue = 0; } }
        else if (metric === 'relics_collected') { try { localSnapValue = _lbRelicsLogStats().have; } catch (_) { localSnapValue = 0; } }   // W622
        else if (metric === 'rank_band') { try { localSnapValue = Math.max(0, Math.round(_ascPlayerPower())); } catch (_) { localSnapValue = 0; } }
      }
    } catch (_) {}

    let overrideApplied = false;
    if (localSnapValue > myValue) {
      myValue = localSnapValue;
      overrideApplied = true;
      // Patch the row in `top` (if present) so the merged list sorts
      // with the corrected value and the rendered current-user row
      // doesn't visually disagree with `me`.
      if (Array.isArray(top)) {
        for (let i = 0; i < top.length; i++) {
          if (top[i] && top[i].alias === myAlias) {
            top[i] = Object.assign({}, top[i], { current_value: localSnapValue });
            break;
          }
        }
      }
      // Also patch the `me` view-model so downstream renderers and
      // breadcrumbs reflect the override.
      if (me) {
        me = Object.assign({}, me, { current_value: localSnapValue });
      } else {
        me = { rank: null, current_value: localSnapValue };
      }
    }

    try {
      if (typeof _addHealthVerifyBreadcrumb === 'function') {
        _addHealthVerifyBreadcrumb('leaderboard-local-me-override', {
          metric: metric,
          backendValue: backendMeValue,
          localValue: localSnapValue,
          applied: overrideApplied,
        });
      }
    } catch (_) {}
    const dateKey = (typeof getDeviceLocalDate === 'function') ? getDeviceLocalDate() : '';
    let merged = window.SimulatedLeaderboard.merge(top || [], myAlias, myValue, dateKey, metric);

    // v3 Phase 1z.116 — apply the min-qualifying-score filter for
    // metrics with a configured floor. Re-rank the filtered list so
    // ranks are 1..N over visible rows.
    const minScore = _LB_MIN_QUALIFYING_SCORE[metric];
    if (typeof minScore === 'number' && Array.isArray(merged)) {
      // W787 — the floor gates REAL hunters only. Sims are deliberately kept BELOW
      // it (1-4 relics, owner: "no sim above 5"), so applying it to them too would
      // delete the very rows meant to fill the board and leave it short again.
      merged = merged
        .filter(r => r && (r._sim || (typeof r.current_value === 'number' && r.current_value >= minScore)))
        .map((r, i) => Object.assign({}, r, { rank: i + 1 }));
    }

    // Recompute the `me` view-model from the merged list so the
    // "out-of-top-N" row in lbBuildRankList correctly suppresses
    // when the user is now visible inside the merged board.
    let newMe = null;
    const myIdx = merged.findIndex(r => r && r.alias === myAlias);
    if (myIdx >= 0) {
      newMe = { rank: myIdx + 1, current_value: merged[myIdx].current_value };
    } else if (me && typeof minScore === 'number' && myValue < minScore) {
      // v3 Phase 1z.116 — user is below the qualifying floor. Hide
      // their out-of-top pinned row entirely (no rank, no value).
      // lbBuildRankList sees newMe = null and would normally show a
      // "submitting…" placeholder; we tag the meta below to suppress
      // even that for below-floor users.
      newMe = null;
    } else if (me) {
      newMe = me;
    }
    return { top: merged, me: newMe, _belowMinScore: (typeof minScore === 'number' && myValue < minScore) };
  }

  // v3 Phase 1z.36 — tracks the active tab inside the sheet for
  // metrics that have a Hall of Fame view. 'this-week' (default)
  // or 'hof'. Concurrent fetches on tab switch are gated by both
  // _lbCurrentOpenMetric and _lbCurrentTab.
  let _lbCurrentTab = 'this-week';

  // v3 Phase 1z.120 — feature flag for the workout_streak backend
  // migration. Backend metrics registry now whitelists
  // 'workout_streak' (see backend/src/lib/metrics.ts) and the
  // leaderboard_snapshots table is metric-agnostic — no schema
  // change required. When this flag flips true AFTER the backend
  // is redeployed:
  //   1. workout_streak drops out of _LB_CLIENT_ONLY_METRICS, so
  //      the modal load path hits Auth.fetchLeaderboardTop and
  //      real users surface alongside the sim merge.
  //   2. lbSubmitAllMetrics includes workout_streak in its submit
  //      array, so the user's row reaches the backend.
  // Default stays FALSE until both halves ship together. Flipping
  // the flag without the backend deploy would re-introduce the
  // 1z.119 "Couldn't load rankings" failure mode.
  // v3 Phase 1z.121 — flipped to true after backend Worker version
  // c9c943d9-4e03-4b69-91fd-a02d8d8e837c deployed with the
  // workout_streak metric whitelist entry. Frontend now submits
  // workout_streak via lbSubmitAllMetrics and the modal load path
  // hits Auth.fetchLeaderboardTop (no longer in
  // _LB_CLIENT_ONLY_METRICS). Simulated rows still fill sparse
  // boards via _lbMaybeSimulate, exactly as they do for step_total
  // and sleep_streak. Richie's local row continues to pull from
  // snap.current_workout_streak via the snapshot path.
  const LEADERBOARD_WORKOUT_BACKEND_ENABLED = true;
  // v3 Phase 1z.125 — flights_climbed backend leaderboard. Backend
  // Worker version 6c735ead-f187-4b45-bbe0-0c4521432df0 deployed
  // with flights_climbed in the metric whitelist (cap 1000/week,
  // Sunday-UTC scoped like step_total). When true, lbSubmitAll
  // Metrics submits flights_climbed and the modal load path hits
  // Auth.fetchLeaderboardTop. Sheet-only v1 — no preview card on
  // the Status tab; access via the "More rankings" link below the
  // 3 main cards.
  const LEADERBOARD_FLIGHTS_BACKEND_ENABLED = true;
  // W274 — floor_best (highest Ascent floor) global board. Stays FALSE until
  // the backend redeploys with 'floor_best' in metrics.ts (it's already added
  // there). While false, floor_best is a client-only metric: the sheet renders
  // the sim board (bots + the player's own highestCleared) with no backend
  // round-trip. Flip true AFTER `wrangler deploy` to go live cross-device.
  // W275 — flipped true after backend deploy (Worker version e4d721a0,
  // 2026-06-12) carrying floor_best in metrics.ts. Live cross-device.
  const LEADERBOARD_FLOOR_BACKEND_ENABLED = true;
  // W622 — relics_collected (Collection Log race) global board. Stays FALSE
  // until the backend redeploys with 'relics_collected' in metrics.ts (already
  // added there). While false, relics_collected is a client-only metric: the
  // sheet renders the local board (just the player's own log count — NO sim
  // bots, see _LB_SIM_METRICS note) with no backend round-trip. Flip true
  // AFTER `wrangler deploy` to go live cross-device.
  // W623 — flipped true after backend deploy (Worker version a8650a72,
  // 2026-07-08) carrying relics_collected in metrics.ts. Live cross-device.
  const LEADERBOARD_RELICS_BACKEND_ENABLED = true;

  // ───────────────────────────────────────────────────────────────
  // v3 Phase 1z.164 — Social Hub / Guild Hall.
  // v3 Phase 1z.279 — DUELS_PUBLIC_CHALLENGE_ENABLED,
  // DUELS_PUBLIC_TAB_VISIBLE, and DUELS_QA_OVERRIDE_ENABLED removed
  // along with the Duels subsystem. Only the Guild Hall master
  // switch remains.
  const SOCIAL_HUB_ENABLED              = true;

  // v3 Phase 1z.119 — client-only metrics never hit the backend.
  // workout_streak (added in 1z.118) is fully derived from the
  // local completion ledger — the backend has no /v1/leaderboard
  // route for it. Without this set, the modal load path would
  // call Auth.fetchLeaderboardTop('workout_streak'), get a NETWORK
  // / 404 response, find no cache, and render lbBuildErrorState's
  // "Couldn't load rankings" — exactly the bug reported on the
  // TestFlight build that followed 1z.118.
  //
  // v3 Phase 1z.120 — gated by LEADERBOARD_WORKOUT_BACKEND_ENABLED.
  // When the flag flips true, workout_streak is removed from this
  // set and routed through the standard backend fetch path, which
  // simulated-rows-merge fills around for sparse boards.
  const _LB_CLIENT_ONLY_METRICS = new Set([
    ...(LEADERBOARD_WORKOUT_BACKEND_ENABLED ? [] : ['workout_streak']),
    ...(LEADERBOARD_FLOOR_BACKEND_ENABLED ? [] : ['floor_best']),   // W274 — sim-only until backend deploy
    ...(LEADERBOARD_RELICS_BACKEND_ENABLED ? [] : ['relics_collected']),   // W622 — local-only until backend deploy
  ]);

  // Renders the "This Week" view (current-weekly ranking with sim
  // merge). Extracted from openLeaderboardRanking so the same flow
  // can be triggered on tab switch without re-opening the sheet.
  // W318 — days remaining until the next Sunday-Pacific weekly reset.
  // Reuses the single-sourced Pacific week key (lbGetCurrentWeekStartPT)
  // and _getPTDateParts; pure date-string math, DST-safe, no hour offset.
  function _lbWeekResetCountdownText() {
    try {
      const wk = lbGetCurrentWeekStartPT();
      if (!/^\d{4}-\d{2}-\d{2}$/.test(wk)) return '';
      const fmt = _getPTDateParts();
      let ty = 0, tm = 0, td = 0;
      if (fmt) {
        const parts = fmt.formatToParts(new Date());
        for (let i = 0; i < parts.length; i++) {
          const p = parts[i];
          if      (p.type === 'year')  ty = parseInt(p.value, 10);
          else if (p.type === 'month') tm = parseInt(p.value, 10);
          else if (p.type === 'day')   td = parseInt(p.value, 10);
        }
      }
      if (!ty) return '';
      const wkMs    = Date.UTC(parseInt(wk.slice(0, 4), 10), parseInt(wk.slice(5, 7), 10) - 1, parseInt(wk.slice(8, 10), 10));
      const todayMs = Date.UTC(ty, tm - 1, td);
      let elapsed = Math.round((todayMs - wkMs) / 86400000);
      if (elapsed < 0) elapsed = 0;
      if (elapsed > 6) elapsed = 6;
      const daysLeft = 7 - elapsed;
      if (daysLeft === 1) return 'Final day \u2014 resets Sunday';
      return daysLeft + ' days left \u00b7 resets Sunday';
    } catch (_) { return ''; }
  }

  // ── W386 · Global Leaderboard "Redesign" (ClaudeDesign handoff) ──────
  // Calmer hierarchy: the meta-clutter (countdown pill + reset paragraph)
  // collapses into one context line; the disclaimer drops to a quiet list
  // footer; the user's row pins at the bottom when out of the visible top.
  // The last-week champion threads into the leader card when (and only
  // when) THIS week's real #1 is the same hunter who won last week.

  // Last-week champion payload (from fetchLastWeekSteps), cached so the
  // leader-card fold-in survives the list re-render race.
  let _lbLastWeekData = null;

  // Bare integer days left in the Pacific week (1–7) or null — same week
  // math as _lbWeekResetCountdownText, just the number for the "Nd LEFT" pill.
  function _lbWeekDaysLeftNum() {
    try {
      const wk = lbGetCurrentWeekStartPT();
      if (!/^\d{4}-\d{2}-\d{2}$/.test(wk)) return null;
      const fmt = _getPTDateParts();
      let ty = 0, tm = 0, td = 0;
      if (fmt) {
        const parts = fmt.formatToParts(new Date());
        for (let i = 0; i < parts.length; i++) {
          const p = parts[i];
          if      (p.type === 'year')  ty = parseInt(p.value, 10);
          else if (p.type === 'month') tm = parseInt(p.value, 10);
          else if (p.type === 'day')   td = parseInt(p.value, 10);
        }
      }
      if (!ty) return null;
      const wkMs    = Date.UTC(parseInt(wk.slice(0, 4), 10), parseInt(wk.slice(5, 7), 10) - 1, parseInt(wk.slice(8, 10), 10));
      const todayMs = Date.UTC(ty, tm - 1, td);
      let elapsed = Math.round((todayMs - wkMs) / 86400000);
      if (elapsed < 0) elapsed = 0;
      if (elapsed > 6) elapsed = 6;
      return 7 - elapsed;
    } catch (_) { return null; }
  }

  // The consolidated context line: date range (left) + "↻ RESETS SUNDAY"
  // and a "Nd LEFT" pill (right). Replaces the old standalone pill.
  function _lbContextLineHtml() {
    let dateLabel = '';
    try {
      const range = lbFormatWeekRange(lbGetCurrentWeekStartPT()); // "Jun 14–Jun 20"
      if (range) {
        const parts = range.split('–');
        if (parts.length === 2) {
          const a = parts[0].trim(), b = parts[1].trim();
          const mA = a.split(' ')[0], pB = b.split(' ');
          // collapse the repeated month for a same-month week ("Jun 14 – 20")
          dateLabel = a + ' – ' + ((pB[0] === mA && pB[1]) ? pB[1] : b);
        } else {
          dateLabel = range.replace('–', ' – ');
        }
      }
    } catch (_) {}
    const days = _lbWeekDaysLeftNum();
    const pill = (typeof days === 'number') ? (days <= 1 ? 'FINAL DAY' : (days + 'D LEFT')) : '';
    // W658 — the ‹ arrow steps back into past weeks' FINAL boards (Steps only;
    // this line only renders for weekly metrics). No forward arrow live.
    return '<button type="button" class="lb-arch-nav" data-lb-arch="prev" aria-label="View past weeks">&#8249;</button>' +
      '<span class="lb-ctx-date">' + esc(dateLabel) + '</span>' +
      '<span class="lb-ctx-right">' +
        '<span class="lb-ctx-reset">↻ RESETS SUNDAY</span>' +
        (pill ? '<span class="lb-ctx-left">' + esc(pill) + '</span>' : '') +
      '</span>';
  }

  // The pinned YOU row (shown only when the signed-in user is OUTSIDE the
  // visible top-N). Mirrors the redesign's gold footer: rank · name · YOU
  // pill · equipped class label · value.
  function _lbYouFooterHtml(metric, me) {
    const meta = LB_METRIC_META[metric];
    const myAlias = lbGetMyAlias();
    const myAliasDisplay = lbNormalizeAliasForDisplay(myAlias) || 'You';
    let classLabel = '';
    try {
      const t = getEquippedArenaTitle();
      let titleId = (t && t.id) || null;
      if (titleId && typeof _ARENA_TITLE_LEGACY !== 'undefined' && _ARENA_TITLE_LEGACY[titleId]) titleId = _ARENA_TITLE_LEGACY[titleId];
      if (titleId && typeof ARENA_TITLES !== 'undefined') {
        const tdef = ARENA_TITLES.find((x) => x.id === titleId);
        if (tdef) {
          const tier = tdef.tier || 'gold';
          classLabel = '<span class="lb-rank-class lb-rank-class--' + tier + '">' +
            '<i class="lb-rank-gem" aria-hidden="true"></i>' + esc(tdef.name) + '</span>';
        }
      }
    } catch (_) {}
    const rankTxt = (me && typeof me.rank === 'number' && me.rank > 0) ? String(me.rank) : '—';
    const valTxt  = me ? meta.formatValue(me.current_value) : '—';
    // W706 — a below-top-10 member still sees their equipped background on THIS
    // pinned row (local equip = instant, no server round-trip needed).
    let _fPaint = ''; try { const _fcb = _cardBgLocal(); if (_fcb.id) _fPaint = _cardBgPaintStyle(_fcb.id); } catch (_) {}
    return '<div class="lb-you-foot-row' + (_fPaint ? ' lb-rank-row--painted' : '') + '"' +
        (_fPaint ? ' style="' + _fPaint + '"' : '') +
        ' data-profile-alias="' + esc(myAlias || '') + '">' +
        '<span class="lb-rank-pos">' + rankTxt + '</span>' +
        _lbCrestHtml({}, true, 'lb-crest--foot') +   // W704 — own crest, local getAvatarSrc()
        '<span class="lb-rank-id">' +
          '<span class="lb-rank-name-row">' +
            '<span class="lb-rank-name">' + esc(myAliasDisplay) + '</span>' +
            '<span class="lb-you-pill">YOU</span>' +
          '</span>' + classLabel +
        '</span>' +
        '<span class="lb-rank-value">' + valTxt + '</span>' +
      '</div>';
  }

  // The redesign board shows a focused TOP-N list with the signed-in
  // user's row PINNED at the bottom when they fall outside it (matches the
  // mock: leader + #2–10, then a pinned YOU row at #12). The sim always
  // injects an out-of-top user inline, so a cap is what surfaces the pin.
  const _LB_VISIBLE_CAP = 10;

  // Show / hide the pinned YOU footer from a {rank, current_value} payload.
  function _lbSetYouFooter(metric, pinData) {
    const sheet = document.getElementById('lb-rank-sheet');
    const foot  = document.getElementById('lb-you-footer');
    if (!sheet || !foot) return;
    if (pinData && typeof pinData.rank === 'number' && pinData.rank > 0) {
      foot.innerHTML = _lbYouFooterHtml(metric, pinData);
      foot.classList.remove('hidden');
      sheet.classList.add('lb-has-youfoot');
    } else {
      foot.innerHTML = '';
      foot.classList.add('hidden');
      sheet.classList.remove('lb-has-youfoot');
    }
  }

  // If THIS week's #1 is the SAME (real, non-sim) hunter who won last
  // week, fold the recap into the leader card as the "🏆 Also won last
  // week · N" divider. Idempotent; safe to call after every render.
  function _lbApplyLeaderLastWeek() {
    try {
      const leaderEl = document.querySelector('#lb-rank-list .lb-rank-leader');
      if (!leaderEl) return;
      const old = leaderEl.querySelector('.lb-leader-lastweek');
      if (old) old.remove();
      // W658 — no "Also won last week" chip on an archived board's leader
      // (the stale-chip removal above still runs, keeping archive cards clean).
      if (_lbCurrentTab !== 'this-week' || _lbCurrentOpenMetric !== 'step_total' || _lbArchWeek !== null) return;
      const d = _lbLastWeekData;
      const champAlias = d && d.champion && d.champion.alias;
      if (d && champAlias &&
          leaderEl.getAttribute('data-profile-alias') === champAlias &&
          !leaderEl.hasAttribute('data-profile-sim')) {
        const n = (Number(d.champion.steps) || 0).toLocaleString('en-US');
        const div = document.createElement('div');
        div.className = 'lb-leader-lastweek';
        div.innerHTML = '<span aria-hidden="true">🏆</span> Also won last week · <b>' + esc(n) + '</b>';
        leaderEl.appendChild(div);
      }
    } catch (_) {}
  }

  // Commit the This-Week list: cap to a focused top-N, render the rows + a
  // quiet disclaimer footer (steps only — Apple Health is the source), pin
  // the user's row when they fall below the cut, then fold in last week.
  // W387 — 100K Step Club membership, for the gold stamp on the global Steps
  // board. Sourced from the REAL accolades roster (Auth.fetchStep100kClub →
  // user_accolades), cached for the session. We never fake it: a hunter gets the
  // stamp only if they genuinely joined the club. Also honors a backend
  // row.club_100k flag, so if the leaderboard payload ever ships one it wins.
  let _lb100kMemberSet = null;   // Set<string> of lowercased aliases, or null until loaded
  let _lb100kFetchPromise = null;
  function _lbEnsure100kMembers() {
    if (_lb100kMemberSet) return Promise.resolve(_lb100kMemberSet);
    if (_lb100kFetchPromise) return _lb100kFetchPromise;
    _lb100kFetchPromise = (async () => {
      try {
        if (window.Auth && typeof Auth.fetchStep100kClub === 'function') {
          const res = await Auth.fetchStep100kClub(200);
          if (res && res.ok && Array.isArray(res.members)) {
            const set = new Set();
            for (const m of res.members) { if (m && m.alias) set.add(String(m.alias).toLowerCase()); }
            _lb100kMemberSet = set;   // cache only on a clean success
          }
        }
      } catch (_) { /* membership is cosmetic — never block the board */ }
      _lb100kFetchPromise = null;
      return _lb100kMemberSet;
    })();
    return _lb100kFetchPromise;
  }
  function _lbAnnotateClub100k(rows) {
    if (!Array.isArray(rows)) return rows;
    const set = _lb100kMemberSet;
    for (const r of rows) {
      if (!r || r.club_100k) continue;   // honor a backend-provided flag
      if (r._sim) continue;              // sims are never real club members
      r.club_100k = !!(set && set.has(String(r.alias || '').toLowerCase()));
    }
    return rows;
  }

  function _lbCommitWeekList(metric, top, me, staleNote) {
    const listEl = document.getElementById('lb-rank-list');
    if (!listEl) return;
    const myAlias = lbGetMyAlias();
    let renderTop = Array.isArray(top) ? top.slice() : [];
    // Locate the user's own row in the merged list (the sim injects an
    // out-of-top self; the backend returns it as `me`).
    const selfRow = myAlias ? (renderTop.find((r) => r && r.alias === myAlias) || null) : null;
    const selfRank = (selfRow && typeof selfRow.rank === 'number') ? selfRow.rank
                   : (me && typeof me.rank === 'number' ? me.rank : 0);
    const pinSelf = selfRank > _LB_VISIBLE_CAP;
    const pinData = pinSelf ? {
      rank: selfRank,
      current_value: selfRow ? selfRow.current_value : (me ? me.current_value : null),
    } : null;
    // When pinning, drop the user from the inline list so they show once.
    if (pinSelf) renderTop = renderTop.filter((r) => !(r && r.alias === myAlias));
    renderTop = renderTop.slice(0, _LB_VISIBLE_CAP);

    // W387 — flag genuine 100K Step Club members so the gold stamp renders next
    // to their class title (Steps board only; real data, sims excluded).
    if (metric === 'step_total') { try { _lbAnnotateClub100k(renderTop); } catch (_) {} }

    // Pass pinData as `me` when pinning so the builder emits an out-of-top
    // row (which we strip below) rather than a "submitting…" placeholder.
    let html = lbBuildRankList(metric, renderTop, (pinSelf ? pinData : me), staleNote);
    if (metric === 'step_total') {
      html += '<div class="lb-list-foot">Resets Sunday 12:00 AM Pacific · Apple Health is the only source</div>';
    }
    listEl.innerHTML = html;
    // Strip the inline out-of-top row ONLY when we're pinning a replacement —
    // never remove the user's row without putting it back in the footer.
    try {
      if (pinSelf) {
        const oot = listEl.querySelector('.lb-rank-row--out-of-top');
        if (oot) {
          const nx = oot.nextElementSibling;
          if (nx && nx.classList && nx.classList.contains('lb-rank-divider')) nx.remove();
          oot.remove();
        }
      }
    } catch (_) {}
    try { _lbSetYouFooter(metric, pinData); } catch (_) {}
    try { _lbApplyLeaderLastWeek(); } catch (_) {}
  }

  async function _lbRenderThisWeekTab(metric) {
    const listEl   = document.getElementById('lb-rank-list');
    const meBestEl = document.getElementById('lb-rank-mebest');
    const blurbEl  = document.getElementById('lb-rank-blurb');
    if (!listEl) return;
    // W658 — entering the live renderer always exits archive mode; the ‹ in
    // the context line is the only door back in.
    _lbArchReset();
    try { _lbArchWire(); } catch (_) {}
    if (meBestEl) meBestEl.classList.add('hidden');
    // W386 — reset the pinned YOU footer; _lbCommitWeekList re-shows it
    // only when the signed-in user is out of the visible top-N.
    try {
      const _yf = document.getElementById('lb-you-footer');
      if (_yf) { _yf.innerHTML = ''; _yf.classList.add('hidden'); }
      const _sh = document.getElementById('lb-rank-sheet');
      if (_sh) _sh.classList.remove('lb-has-youfoot');
    } catch (_) {}

    const meta = LB_METRIC_META[metric];
    const _isWeekly = LB_WEEKLY_METRICS.has(metric);
    // W387 — warm the 100K Step Club roster concurrently with the board fetch so
    // the gold member-stamp is ready by the time the canonical list renders.
    const _club100kP = (metric === 'step_total') ? _lbEnsure100kMembers() : null;
    // W386 — Steps board: the date range + reset collapse into the
    // consolidated context line below; the long paragraph blurb is retired
    // (its "Apple Health" detail reappears as a quiet footer under the
    // list). Other metrics keep their descriptive blurb.
    if (blurbEl) {
      if (metric === 'step_total') {
        blurbEl.textContent = '';
        blurbEl.classList.add('hidden');
      } else {
        let blurbText = meta.blurb;
        if (_isWeekly) {
          // v3 Phase 1z.219 — Pacific-Time copy, DST-independent.
          const range = lbFormatWeekRange(lbGetCurrentWeekStartPT());
          if (range) blurbText = range + ' · resets Sunday 12:00 AM Pacific Time. Apple Health is the only source.';
        }
        blurbEl.textContent = blurbText;
        blurbEl.classList.remove('hidden');
      }
    }
    // W386 — consolidated context line (date range · ↻ RESETS SUNDAY · Nd LEFT).
    // Weekly metrics only; replaces the old standalone countdown pill.
    const _resetEl = document.getElementById('lb-week-reset');
    if (_resetEl) {
      if (_isWeekly) { _resetEl.innerHTML = _lbContextLineHtml(); _resetEl.classList.remove('hidden'); }
      else { _resetEl.innerHTML = ''; _resetEl.classList.add('hidden'); }
    }
    // W321 — last-week recap (step_total only; non-blocking fire-and-forget).
    try { _lbPopulateLastWeekRecap(metric); } catch (_) {}

    // v3 Phase 1z.122 — decisive route breadcrumb at modal open.
    // Records exactly which branch the rendering will take so
    // Copy Debug Info proves the on-device flag state matched
    // expectations.
    const _bcLB = (typeof _addHealthVerifyBreadcrumb === 'function')
      ? _addHealthVerifyBreadcrumb
      : function () {};
    const cached = lbCacheRead(metric);
    const flagWorkoutBackend = (typeof LEADERBOARD_WORKOUT_BACKEND_ENABLED !== 'undefined')
      && !!LEADERBOARD_WORKOUT_BACKEND_ENABLED;
    const clientOnly = _LB_CLIENT_ONLY_METRICS.has(metric);
    try {
      _bcLB('leaderboard-modal-route', {
        metric,
        backendEnabled: metric === 'workout_streak' ? flagWorkoutBackend : true,
        clientOnly,
        hasCache: !!cached,
        simSupported: !!_LB_SIM_METRICS[metric],
      });
    } catch (_) {}

    // v3 Phase 1z.119 — client-only metrics short-circuit before
    // the backend fetch. workout_streak is derived from the local
    // completion ledger and the backend has no route for it; the
    // sim merge alone produces the full ranked list (bots + the
    // user's row pulled from lbGetSnapshot.current_workout_streak).
    // 1z.121 lifted workout_streak out of this set when the flag
    // is true — modal routes through the backend fetch + sim merge
    // path below.
    if (clientOnly) {
      try { _bcLB('leaderboard-modal-client-only', { metric }); } catch (_) {}
      let sim = _lbMaybeSimulate(metric, [], null);
      // W622 — sim-less client-only board (relics_collected pre-deploy): the sim
      // merge returns nothing, which read "Be the first to rank" to a hunter who
      // already HAS relics. Render the player's own local row at #1 instead so
      // the dark period is honest; the backend path replaces this at go-live.
      if (metric === 'relics_collected' && (!sim.top || !sim.top.length)) {
        try {
          const _clv = _lbRelicsLogStats().have;
          const _cla = lbGetMyAlias();
          if (_clv > 0 && _cla) {
            const _row = { rank: 1, alias: _cla, current_value: _clv };
            sim = { top: [_row], me: _row };
          }
        } catch (_) {}
      }
      try {
        _bcLB('leaderboard-modal-render-final', {
          metric,
          dataSource: 'client-only-sim',
          finalRowCount: (sim.top || []).length,
          currentUserIncluded: !!(sim.me && typeof sim.me.rank === 'number'),
          currentUserValue: (sim.me && sim.me.current_value) || 0,
          backendEnabled: false,
        });
      } catch (_) {}
      _lbCommitWeekList(metric, sim.top, sim.me);
      return;
    }

    if (cached) {
      const staleNote = 'Last updated ' + lbFormatRelativeTime(cached.fetched_at);
      const sim1 = _lbMaybeSimulate(metric, cached.top, cached.me);
      _lbCommitWeekList(metric, sim1.top, sim1.me, staleNote);
    } else {
      listEl.innerHTML = lbBuildLoadingSkeleton();
    }

    try { _bcLB('leaderboard-backend-fetch-start', { metric, kind: 'top', limit: 50 }); } catch (_) {}
    let result;
    try {
      result = await window.Auth.fetchLeaderboardTop(metric);
    } catch (e) {
      result = { ok: false, code: 'NETWORK' };
    }
    // Concurrency guard: user may have closed the sheet, switched
    // metrics, or switched tabs (to HoF) while the fetch was in
    // flight. Each of those races would otherwise paint stale.
    // W658 review fix — archive mode also owns the surface: a late live
    // fetch must never repaint the live race under a FINAL header.
    if (_lbCurrentOpenMetric !== metric || _lbCurrentTab !== 'this-week' || _lbArchWeek !== null) return;

    if (result && result.ok) {
      const realRowCount = Array.isArray(result.top) ? result.top.length : 0;
      try {
        _bcLB('leaderboard-backend-fetch-success', {
          metric,
          realRowCount,
          hasMeRow: !!(result.me && typeof result.me.current_value === 'number'),
          meCurrentValue: (result.me && typeof result.me.current_value === 'number') ? result.me.current_value : null,
          meRank: (result.me && typeof result.me.rank === 'number') ? result.me.rank : null,
        });
      } catch (_) {}
      lbCacheWrite(metric, result.top, result.me);

      // v3 Phase 1z.283 W181 — Weekly Steps leaderboard top-10 placement
      // → Guild Hall feat. Fires once when the user enters top 10 each
      // week, and re-fires on rank IMPROVEMENT (e.g. #8 → #4) — never
      // on regression (#4 → #7 stays silent). Each week is a fresh
      // slate; storage key includes weekStartIso so a new week reopens
      // the channel even at the same rank.
      //
      // Trigger: only on a successful Steps leaderboard fetch (this
      // function). That means the event surfaces in the Guild feed
      // when the user opens the leaderboard sheet — by design. No
      // background polling.
      // v3 Phase 1z.283 W185 — Minimum-effort threshold for the top-10
      // Steps feat. The original W181 trigger fired purely on rank,
      // which on a sparse early-stage leaderboard produces false
      // positives: a user with 71 weekly steps could legitimately
      // land at #8 when there were only 10 total competitors, then
      // slide to #18 as the audience grew — leaving a stale "You
      // reached #8" feat in the feed that looks like a lie. The W181
      // "never un-fire on regression" design (intentional, to avoid
      // demotion churn) combined with rank-based qualification meant
      // the feat could persist with embarrassingly low effort.
      //
      // The fix: require a real-effort floor before any top-10 feat
      // qualifies. 25,000 weekly steps ≈ 3,500/day, a basic active
      // baseline. Filters out sparse-leaderboard false positives
      // without gatekeeping legitimate top performers (true top-10
      // is 40K+ weekly). Threshold can be lifted later if the user
      // base grows enough that rank alone becomes a reliable signal.
      const LB_TOP10_STEP_MIN_VALUE = 25000;
      try {
        if (metric === 'step_total' && result.me &&
            typeof result.me.rank === 'number' &&
            typeof result.me.current_value === 'number' &&
            result.me.current_value >= LB_TOP10_STEP_MIN_VALUE) {
          const myRank = result.me.rank;
          if (myRank >= 1 && myRank <= 10 && typeof lbGetCurrentWeekStartPT === 'function') {
            const weekStart = lbGetCurrentWeekStartPT(Date.now());
            if (weekStart && /^\d{4}-\d{2}-\d{2}$/.test(weekStart)) {
              const bestKey = 'hb_lb_best_rank_' + metric + '_' + weekStart;
              let seenBest = 0;
              try {
                const raw = localStorage.getItem(bestKey);
                seenBest = raw ? parseInt(raw, 10) : 0;
                if (!(seenBest > 0 && seenBest <= 10)) seenBest = 0;
              } catch (_) { seenBest = 0; }

              const shouldFire = (seenBest === 0) || (myRank < seenBest);
              if (shouldFire) {
                recordGuildActivity('leaderboard_top10_step', {
                  rank:         myRank,
                  metric:       'step_total',
                  weekStartIso: weekStart,
                }, 'lb_top10_step_' + weekStart + '_r' + myRank);
                try { localStorage.setItem(bestKey, String(myRank)); } catch (e) { _logSwallow('pr_best:persist', e); }
              }
            }
          }
        } else if (metric === 'step_total' && result.me &&
                   typeof result.me.rank === 'number' &&
                   result.me.rank >= 1 && result.me.rank <= 10) {
          // Breadcrumb: threshold blocked an otherwise-qualifying fire.
          // Useful telemetry to confirm the gate is doing its job on
          // sparse leaderboards.
          try {
            _bcLB('leaderboard-top10-feat-threshold-block', {
              metric,
              rank: result.me.rank,
              value: (typeof result.me.current_value === 'number') ? result.me.current_value : null,
              threshold: LB_TOP10_STEP_MIN_VALUE,
            });
          } catch (_) {}
        }
      } catch (_) { /* feed is not load-bearing — never block render */ }

      const sim2 = _lbMaybeSimulate(metric, result.top, result.me);
      const finalRowCount = (sim2.top || []).length;
      try {
        _bcLB('leaderboard-modal-render-final', {
          metric,
          dataSource: realRowCount > 0 ? 'mixed' : 'simulated',
          finalRowCount,
          realRowCount,
          simulatedRowCount: Math.max(0, finalRowCount - realRowCount),
          currentUserIncluded: !!(sim2.me && typeof sim2.me.rank === 'number'),
          currentUserValue: (sim2.me && sim2.me.current_value) || 0,
          backendEnabled: metric === 'workout_streak' ? flagWorkoutBackend : true,
        });
      } catch (_) {}
      if (_club100kP) { try { await _club100kP; } catch (_) {} }
      _lbCommitWeekList(metric, sim2.top, sim2.me);
      if (metric === 'step_total') {
        try { updateStepsCard(); } catch (_) {}
      }
    } else if (result && result.code === 'EXPIRED') {
      try { _bcLB('leaderboard-backend-fetch-fail', { metric, code: 'EXPIRED' }); } catch (_) {}
      window.location.reload();
    } else if (!cached) {
      const failCode = (result && result.code) || 'UNKNOWN';
      try { _bcLB('leaderboard-backend-fetch-fail', { metric, code: failCode }); } catch (_) {}
      try { _bcLB('leaderboard-modal-load-error', { metric, code: failCode }); } catch (_) {}
      // v3 Phase 1z.121 — sim-supported metrics fall back to a
      // sim-merged render when the backend errors AND no cache
      // exists. Without this, a first-load-on-flaky-network user
      // (or a newly-deployed metric whose first writes haven't
      // landed in cache yet — e.g. workout_streak right after the
      // 1z.121 flag flip) sees "Couldn't load rankings" instead
      // of the populated board. Metrics without sim support still
      // fall through to the error state.
      if (_LB_SIM_METRICS[metric]) {
        const simFallback = _lbMaybeSimulate(metric, [], null);
        const fallbackCount = (simFallback.top || []).length;
        try {
          _bcLB('leaderboard-modal-sim-fallback', {
            metric,
            reason: 'backend-error-no-cache',
            realRowCount: 0,
            simulatedRowCount: fallbackCount,
            currentUserValue: (simFallback.me && simFallback.me.current_value) || 0,
          });
          _bcLB('leaderboard-modal-render-final', {
            metric,
            dataSource: 'fallback',
            finalRowCount: fallbackCount,
            realRowCount: 0,
            simulatedRowCount: fallbackCount,
            currentUserIncluded: !!(simFallback.me && typeof simFallback.me.rank === 'number'),
            currentUserValue: (simFallback.me && simFallback.me.current_value) || 0,
            backendEnabled: metric === 'workout_streak' ? flagWorkoutBackend : true,
          });
        } catch (_) {}
        _lbCommitWeekList(metric, simFallback.top, simFallback.me);
      } else {
        listEl.innerHTML = lbBuildErrorState(result && result.code);
      }
    }
  }

  // v3 Phase 1z.37/40 — Hall of Fame display merge. Combines real
  // backend records with deterministic simulated filler so the
  // board isn't empty at launch. Sims are CLIENT-ONLY: never
  // persisted, never sent to the backend, never written to D1,
  // and never used to derive accolades. Sims are capped at
  // SIM_STEP_WEEKLY_CAP (45,555) by the generator; real records
  // can exceed the cap and will naturally sort above all sims
  // after the merge re-sort.
  //
  // 1z.40 fix: returns BOTH the merged record list AND a
  // displayed-rank version of me_best. The pinned "YOUR BEST"
  // card used to render the BACKEND rank (real-records-only),
  // which was misleading: with 12 sims merged above a real user
  // at 3,110 steps, the pinned card showed "#1" while the visible
  // list put the real user at ~#13. The displayed rank now
  // matches the visible list. The real `me_best.steps` /
  // `week_start` / `week_end` are still sourced from the backend
  // response — only the rank number is recomputed against the
  // merged set.
  //
  // Also: if the caller's me_best record isn't already in the
  // real `records` array (e.g. it fell outside the limit window),
  // inject it as a synthetic row with `_injectedSelf: true` so
  // the user appears in the scrollable list, not only in the
  // pinned card. The injection preserves the same alias/steps/
  // week_start triple from the backend response.
  //
  // Returns: { records: [...], me_best_displayed: {...} | null }
  function _lbMergeHofRecords(realRecords, realMeBest) {
    const real = Array.isArray(realRecords) ? realRecords.slice() : [];
    const myAlias = lbGetMyAlias();

    // Inject the user's own me_best record if it isn't already in
    // the real records list. Matched by (alias, week_start) since
    // a user can have multiple records across weeks.
    let injectedMe = null;
    if (realMeBest && typeof realMeBest.steps === 'number' && myAlias) {
      const alreadyPresent = real.some(r =>
        r && r.alias === myAlias && r.week_start === realMeBest.week_start
      );
      if (!alreadyPresent) {
        injectedMe = {
          alias:        myAlias,
          steps:        realMeBest.steps,
          week_start:   realMeBest.week_start,
          week_end:     realMeBest.week_end,
          _injectedSelf: true,
        };
        real.push(injectedMe);
      }
    }

    let sims = [];
    try {
      if (typeof window.SimulatedLeaderboard !== 'undefined' &&
          window.SimulatedLeaderboard.SIMULATE_USERS &&
          typeof window.SimulatedLeaderboard.getHallOfFameRecords === 'function') {
        const dateKey = (typeof getDeviceLocalDate === 'function') ? getDeviceLocalDate() : '';
        sims = window.SimulatedLeaderboard.getHallOfFameRecords(dateKey, 'step_total') || [];
      }
    } catch (_) { sims = []; }
    // Defensive: if a real user happens to share an alias with a
    // bot, drop the sim row so the real user's record isn't
    // duplicated. This includes the caller's own alias.
    if (sims.length) {
      const realAliases = new Set(real.map(r => r && r.alias).filter(Boolean));
      if (myAlias) realAliases.add(myAlias);
      sims = sims.filter(s => !realAliases.has(s.alias));
    }
    const merged = real.concat(sims);
    // Re-sort: steps DESC, then older week_start ASC (matches
    // backend convention). Real records over 45,555 always rank
    // above sims.
    merged.sort((a, b) => {
      const da = (b.steps || 0) - (a.steps || 0);
      if (da !== 0) return da;
      return String(a.week_start || '').localeCompare(String(b.week_start || ''));
    });
    merged.forEach((r, i) => { r.rank = i + 1; });

    // v3 Phase 1z.142 — belt-and-suspenders top-N cap at the data
    // boundary, mirroring the render-layer cap in lbBuildHofList.
    // Two caps so any future renderer (or test fixture) that
    // consumes merged.records is also limited to the top 10 — no
    // way for a code path to leak #11+ into the visible UI.
    // Capping AFTER rank assignment so rank labels still read
    // 1..10 (not 1..25 truncated to 1..10 with some 5..14 mix).
    // Capping BEFORE me_best-displayed lookup so the lookup is
    // against the same visible window — if the user's record falls
    // off the top 10 the lookup falls back to backend rank (which
    // is what we want for the Your Best pinned card).
    const cappedMerged = merged.slice(0, HOF_DISPLAY_LIMIT);

    // Recompute the displayed rank for the pinned YOUR BEST card.
    // Match by (alias, week_start) so a user with multiple records
    // gets the correct rank for their *best* week. Falls back to
    // the backend rank if for some reason the row isn't found
    // (shouldn't happen after the injection above, but defensive).
    // Look up against the FULL merged array, not the capped slice —
    // a user whose best falls outside the top 10 still gets their
    // true rank shown on the Your Best card (it just won't appear
    // in the visible top-10 list, which is the intended UX).
    let meBestDisplayed = null;
    if (realMeBest) {
      const myRow = myAlias
        ? merged.find(r => r && r.alias === myAlias && r.week_start === realMeBest.week_start)
        : null;
      meBestDisplayed = {
        rank:       myRow ? myRow.rank : (typeof realMeBest.rank === 'number' ? realMeBest.rank : -1),
        steps:      realMeBest.steps,
        week_start: realMeBest.week_start,
        week_end:   realMeBest.week_end,
      };
    }

    return { records: cappedMerged, me_best_displayed: meBestDisplayed };
  }

  // v3 Phase 1z.36/37 — Hall of Fame tab renderer.
  // me_best is taken EXCLUSIVELY from the real backend response —
  // sims never affect a real user's "your best" surface. The cache
  // stores the raw backend response (records + me_best); the sim
  // merge happens at render time so paging the past-week boundary
  // refreshes the sim list naturally.
  async function _lbRenderHofTab(metric) {
    const listEl   = document.getElementById('lb-rank-list');
    const meBestEl = document.getElementById('lb-rank-mebest');
    const blurbEl  = document.getElementById('lb-rank-blurb');
    if (!listEl) return;
    var _hofRe = document.getElementById('lb-week-reset'); if (_hofRe) _hofRe.classList.add('hidden');

    if (blurbEl) blurbEl.textContent = 'Highest verified weekly totals ever recorded.';

    // Phase 1: render from cache instantly if fresh. Re-run the sim
    // merge on every render — sims are never cached, only the real
    // backend response is. v3 1z.40: me_best rank is recomputed
    // against the merged list so the pinned card matches the visible
    // ranking (it used to show backend-only rank, e.g. "#1", while
    // the user actually appeared at ~#13 once sims were merged in).
    const cached = lbHofCacheRead(metric);
    if (cached) {
      const m = _lbMergeHofRecords(cached.records, cached.me_best);
      if (meBestEl) {
        meBestEl.innerHTML = lbBuildHofMeBest(m.me_best_displayed);
        meBestEl.classList.remove('hidden');
      }
      listEl.innerHTML = lbBuildHofList(m.records);
      _bcHofRender('cached', cached.records, m.records);
    } else {
      if (meBestEl) meBestEl.classList.add('hidden');
      listEl.innerHTML = lbBuildLoadingSkeleton();
    }

    // Phase 2: fresh fetch.
    let result;
    try {
      result = await window.Auth.fetchLeaderboardHallOfFame(metric, 50);
    } catch (e) {
      result = { ok: false, code: 'NETWORK' };
    }
    if (_lbCurrentOpenMetric !== metric || _lbCurrentTab !== 'hof') return;

    if (result && result.ok) {
      // Cache the REAL response only — sims are regenerated at render
      // time, never persisted. Mirrors the "This Week" cache discipline.
      lbHofCacheWrite(metric, result.records, result.me_best);
      const m = _lbMergeHofRecords(result.records, result.me_best);
      if (meBestEl) {
        meBestEl.innerHTML = lbBuildHofMeBest(m.me_best_displayed);
        meBestEl.classList.remove('hidden');
      }
      listEl.innerHTML = lbBuildHofList(m.records);
      _bcHofRender('fresh', result.records, m.records);
    } else if (result && result.code === 'EXPIRED') {
      window.location.reload();
    } else if (!cached) {
      // No cache + fetch failed. Show sims as offline-friendly filler
      // so the board isn't completely empty during a transient outage.
      // me_best stays hidden — we have no real data to attribute.
      const m = _lbMergeHofRecords([], null);
      if (m.records.length > 0) {
        if (meBestEl) {
          meBestEl.innerHTML = lbBuildHofMeBest(null);
          meBestEl.classList.remove('hidden');
        }
        listEl.innerHTML = lbBuildHofList(m.records);
        _bcHofRender('sim-fallback', [], m.records);
      } else {
        listEl.innerHTML = lbBuildErrorState(result && result.code);
      }
    }
  }

  // v3 Phase 1z.142 — single-shot diagnostic breadcrumb for the
  // Hall of Fame render path. Fires once per render (not per row).
  // Decisive signal for the "HoF still shows >10 rows" class of
  // bug: payload shows the cap, the actual displayed count, the
  // build tag (so we can tell a stale TestFlight binary from a
  // logic bug), and which render path fired (cached vs fresh vs
  // sim-fallback). Privacy-safe: no aliases or step counts.
  function _bcHofRender(path, incoming, displayed) {
    try {
      if (typeof _addHealthVerifyBreadcrumb !== 'function') return;
      const incomingCount  = Array.isArray(incoming)  ? incoming.length  : 0;
      const displayedCount = Array.isArray(displayed) ? displayed.length : 0;
      const lastRank = (displayed && displayed.length) ? (displayed[displayed.length - 1].rank || displayed.length) : 0;
      _addHealthVerifyBreadcrumb('leaderboard-hof-render', {
        path: path,
        incomingCount: incomingCount,
        displayedCount: displayedCount,
        displayLimit: HOF_DISPLAY_LIMIT,
        firstRank: (displayed && displayed.length) ? (displayed[0].rank || 1) : 0,
        lastRank: lastRank,
        builder: 'lbBuildHofList',
        build: (typeof APP_BUILD_TAG !== 'undefined') ? APP_BUILD_TAG : 'unknown',
      });
    } catch (_) {}
  }

  // v3 Phase 1z.52 — 100K Step Club tab renderer.
  // Real-users-only board sourced from /v1/leaderboard/step-100k-club.
  // No sim filler ever runs here -- this is the exclusive prestige
  // surface. The pinned `YOUR 100K CLUB RECORD` card shows the
  // caller's status (rank + best week steps + repeat count) when
  // they're a member, or an encouragement prompt when they're not.
  //
  // Cache: `hb_lb_100k_club` (10-min TTL). Stores backend response
  // verbatim; client never injects extra rows.
  async function _lbRender100kClubTab(metric) {
    const listEl   = document.getElementById('lb-rank-list');
    const meBestEl = document.getElementById('lb-rank-mebest');
    const blurbEl  = document.getElementById('lb-rank-blurb');
    if (!listEl) return;
    var _clubRe = document.getElementById('lb-week-reset'); if (_clubRe) _clubRe.classList.add('hidden');

    if (blurbEl) blurbEl.textContent = 'Hunters who recorded 100,000+ verified steps in a single week.';

    // Phase 1: render from cache instantly if fresh.
    const cached = lb100kClubCacheRead();
    if (cached) {
      if (meBestEl) {
        meBestEl.innerHTML = lbBuild100kClubMeBest(cached.me);
        meBestEl.classList.remove('hidden');
      }
      listEl.innerHTML = lbBuild100kClubList(cached.members);
    } else {
      if (meBestEl) meBestEl.classList.add('hidden');
      listEl.innerHTML = lbBuildLoadingSkeleton();
    }

    // Phase 2: fresh fetch.
    let result;
    try {
      result = await window.Auth.fetchStep100kClub(50);
    } catch (e) {
      result = { ok: false, code: 'NETWORK' };
    }
    if (_lbCurrentOpenMetric !== metric || _lbCurrentTab !== 'club-100k') return;

    if (result && result.ok) {
      lb100kClubCacheWrite(result.members, result.me);
      if (meBestEl) {
        meBestEl.innerHTML = lbBuild100kClubMeBest(result.me);
        meBestEl.classList.remove('hidden');
      }
      listEl.innerHTML = lbBuild100kClubList(result.members);
    } else if (result && result.code === 'EXPIRED') {
      window.location.reload();
    } else if (!cached) {
      // No cache + fetch failed. 100K Club is real-users-only, so
      // there's no sim fallback like HoF -- just show the error/stub
      // state. me-best stays hidden in that path.
      if (meBestEl) meBestEl.classList.add('hidden');
      listEl.innerHTML = lbBuildErrorState(result && result.code);
    }
  }

  // W319 — "Hunters in your rank" cohort board. Fetches the caller's rank-
  // tier board (ranked by power) and blends sim filler so thin bands still
  // feel populated. Reuses lbBuildRankList (profile-card taps work for free)
  // + the _lbMaybeSimulate machinery. Not weekly, so the reset badge hides.
  async function _lbRenderRankBandTab(metric) {
    const listEl = document.getElementById('lb-rank-list');
    if (!listEl) return;
    var _rbRe = document.getElementById('lb-week-reset'); if (_rbRe) _rbRe.classList.add('hidden');
    const meBestEl = document.getElementById('lb-rank-mebest');
    if (meBestEl) meBestEl.classList.add('hidden');
    const blurbEl = document.getElementById('lb-rank-blurb');
    if (blurbEl) blurbEl.textContent = (LB_METRIC_META.rank_band && LB_METRIC_META.rank_band.blurb) || '';

    const cached = lbCacheRead('rank_band');
    if (cached) {
      const sim1 = _lbMaybeSimulate('rank_band', cached.top, cached.me);
      listEl.innerHTML = lbBuildRankList('rank_band', sim1.top, sim1.me);
    } else {
      listEl.innerHTML = lbBuildLoadingSkeleton();
    }

    let result;
    try {
      result = await window.Auth.fetchRankBand();
    } catch (e) {
      result = { ok: false, code: 'NETWORK' };
    }
    if (_lbCurrentOpenMetric !== 'rank_band') return;

    if (result && result.ok) {
      if (result.tier) {
        const tEl = document.getElementById('lb-rank-title');
        if (tEl) tEl.textContent = 'Rank ' + result.tier + ' Cohort';
      }
      lbCacheWrite('rank_band', result.top || [], result.me || null);
      const sim = _lbMaybeSimulate('rank_band', result.top || [], result.me || null);
      listEl.innerHTML = lbBuildRankList('rank_band', sim.top, sim.me);
    } else if (result && result.code === 'EXPIRED') {
      window.location.reload();
    } else if (!cached) {
      // Backend unreachable (pre-deploy / offline). Sim-only so the cohort
      // board still populates around the caller's local power.
      const sim = _lbMaybeSimulate('rank_band', [], null);
      listEl.innerHTML = lbBuildRankList('rank_band', sim.top, sim.me);
    }
  }

  // W320 — empty/solo state for the Friends tab. No sim filler ever (friends
  // are real people you added); a solo user gets an add-by-alias nudge.
  function _lbFriendsEmptyHtml() {
    return '<div class="lb-rank-empty">' +
      '<div class="lb-rank-empty-icon" aria-hidden="true">\uD83E\uDD1D</div>' +
      '<div class="lb-rank-empty-title">Race your friends.</div>' +
      '<div class="lb-rank-empty-body">Add hunters by alias from the Social tab, then chase their step count every week.</div>' +
    '</div>';
  }

  // W320 — "Friends" tab: steps this week among accepted friends + self.
  // Real-only (NO sim filler). Renders through lbBuildRankList with the
  // step_total meta so steps formatting + profile-card taps work for free.
  async function _lbRenderFriendsTab(metric) {
    const listEl = document.getElementById('lb-rank-list');
    if (!listEl) return;
    const meBestEl = document.getElementById('lb-rank-mebest');
    if (meBestEl) meBestEl.classList.add('hidden');
    const blurbEl = document.getElementById('lb-rank-blurb');
    if (blurbEl) blurbEl.textContent = 'Steps this week among your hunters. Apple Health is the only source.';
    // Friends-by-steps is weekly → keep the reset countdown badge visible.
    const _frRe = document.getElementById('lb-week-reset');
    if (_frRe) { const _cd = _lbWeekResetCountdownText(); if (_cd) { _frRe.textContent = _cd; _frRe.classList.remove('hidden'); } else { _frRe.classList.add('hidden'); } }

    listEl.innerHTML = lbBuildLoadingSkeleton();

    let result;
    try {
      result = await window.Auth.fetchFriendsLeaderboard('step_total');
    } catch (e) {
      result = { ok: false, code: 'NETWORK' };
    }
    if (_lbCurrentOpenMetric !== metric || _lbCurrentTab !== 'friends') return;

    if (result && result.ok) {
      const rows = Array.isArray(result.rows) ? result.rows : [];
      if (rows.length <= 1) {
        listEl.innerHTML = _lbFriendsEmptyHtml();
      } else {
        listEl.innerHTML = lbBuildRankList('step_total', rows, result.me);
      }
    } else if (result && result.code === 'EXPIRED') {
      window.location.reload();
    } else {
      listEl.innerHTML = lbBuildErrorState(result && result.code);
    }
  }

  // W321 — build the last-week recap line. champion + the caller's placement
  // (loss-aversion: "you placed #N — beat the champion this week").
  function _lbLastWeekRecapHtml(d) {
    const champ = d.champion;
    const me = d.me;
    const fmt = function (n) { return (Number(n) || 0).toLocaleString('en-US'); };
    const champAlias = esc(champ.alias || 'A hunter');
    let line;
    if (me && me.rank === 1) {
      var crowns = (d.myTitle && d.myTitle.count) ? d.myTitle.count : 1;
      var ord = (typeof _hallOrdinal === 'function') ? _hallOrdinal(crowns) : (crowns + 'x');
      line = '<span class="lb-lw-you">You won last week</span> — your ' + ord + ' Step Crown. Defend it.';
    } else if (me) {
      line = '<span class="lb-lw-champ">' + champAlias + '</span> won with ' + fmt(champ.steps) +
             ' · <span class="lb-lw-you">you placed #' + me.rank + ' of ' + (d.total || 0) + '</span>';
    } else {
      line = '<span class="lb-lw-champ">' + champAlias + '</span> won with ' + fmt(champ.steps) +
             ' steps · <span class="lb-lw-you">your week starts now</span>';
    }
    return '<span class="lb-lw-trophy" aria-hidden="true">\uD83C\uDFC6</span>' +
      '<span class="lb-lw-body">' +
        '<span class="lb-lw-eyebrow">LAST WEEK</span>' +
        '<span class="lb-lw-line">' + line + '</span>' +
      '</span>';
  }

  // Fetch + paint the last-week recap. step_total only; hides itself if
  // there is no completed prior week yet (new app) or on any error.
  async function _lbPopulateLastWeekRecap(metric) {
    const el = document.getElementById('lb-lastweek-recap');
    if (!el) return;
    if (metric !== 'step_total') { _lbLastWeekData = null; el.classList.add('hidden'); el.innerHTML = ''; return; }
    let result;
    try { result = await window.Auth.fetchLastWeekSteps(); }
    catch (_) { result = { ok: false }; }
    // Guard: the user may have switched metric/tab while the fetch was inflight.
    // W658 review fix — never re-show the LAST WEEK strip over an archive board.
    if (_lbCurrentOpenMetric !== 'step_total' || _lbCurrentTab !== 'this-week' || _lbArchWeek !== null) return;
    if (!result || !result.ok || !result.champion) {
      _lbLastWeekData = null;
      try { _lbApplyLeaderLastWeek(); } catch (_) {}
      el.classList.add('hidden'); el.innerHTML = '';
      return;
    }
    // W323 — cache the weekly Step Crown count for the Hunter Report card.
    try { if (result.myTitle && result.myTitle.count > 0) localStorage.setItem('hb_step_crowns', String(result.myTitle.count)); } catch (e) { _logSwallow('step_crowns:persist', e); }
    // W386 — thread the champion into the leader card when THIS week's #1
    // IS last week's winner (real hunters only — never a sim); otherwise
    // keep the standalone recap card (same info, different surface).
    _lbLastWeekData = result;
    try { _lbApplyLeaderLastWeek(); } catch (_) {}
    const _folded = !!document.querySelector('#lb-rank-list .lb-rank-leader .lb-leader-lastweek');
    if (_folded) { el.classList.add('hidden'); el.innerHTML = ''; }
    else { el.innerHTML = _lbLastWeekRecapHtml(result); el.classList.remove('hidden'); }
  }

  // W331 — "Sign in to join" block shown to guests on social surfaces.
  // The button routes (via a delegated [data-guest-join] handler) to the
  // W330 guest claim modal.
  function _guestJoinHtml(headline, sub) {
    return '<div class="lb-guest-join">' +
      '<div class="lb-guest-join-icon" aria-hidden="true">' +
        '<svg viewBox="0 0 24 24" width="30" height="30" fill="none">' +
          '<path d="M7 11V8a5 5 0 0 1 9.6-2" stroke="#f5b842" stroke-width="1.6" stroke-linecap="round"/>' +
          '<rect x="5" y="11" width="14" height="9" rx="2" stroke="#f5b842" stroke-width="1.6"/>' +
        '</svg>' +
      '</div>' +
      '<div class="lb-guest-join-title">' + esc(headline) + '</div>' +
      '<div class="lb-guest-join-sub">' + esc(sub) + '</div>' +
      '<button type="button" class="lb-guest-join-btn" data-guest-join>Sign in &amp; save your progress</button>' +
    '</div>';
  }

  // ── W657 — Week Recap: the Sunday ceremony ─────────────────────────────
  // First app-open after the Pacific week boundary shows last week's FINAL
  // standings + a personal recap, then gets out of the way. Pure DISPLAY —
  // nothing pauses at the boundary (scoring, habits, streaks, the live board
  // all continue). Server truth: /v1/leaderboard/recap reads the durable
  // weekly_step_records merge (never the eroding snapshots) and keeps the
  // per-user seen flag; the recap persists until dismissed. Sims are merged
  // client-side exactly like the live board — deterministic per (week, bot),
  // so the finished week re-rolls identically (full-week value, dayIdx 6).

  // Prior Sunday key: pure date math off the 'YYYY-MM-DD' key (no DST hazard).
  function _wrPriorWeek(weekKey) {
    const m = /^(\d{4})-(\d{2})-(\d{2})$/.exec(weekKey || '');
    if (!m) return null;
    const ms = Date.UTC(+m[1], +m[2] - 1, +m[3]) - 7 * 86400000;
    const d = new Date(ms);
    return d.getUTCFullYear() + '-' + String(d.getUTCMonth() + 1).padStart(2, '0') + '-' +
      String(d.getUTCDate()).padStart(2, '0');
  }
  // The 7 'YYYY-MM-DD' keys of the week starting at weekKey (Sun..Sat).
  function _wrWeekDates(weekKey) {
    const m = /^(\d{4})-(\d{2})-(\d{2})$/.exec(weekKey || '');
    if (!m) return [];
    const base = Date.UTC(+m[1], +m[2] - 1, +m[3]);
    const out = [];
    for (let i = 0; i < 7; i++) {
      const d = new Date(base + i * 86400000);
      out.push(d.getUTCFullYear() + '-' + String(d.getUTCMonth() + 1).padStart(2, '0') + '-' +
        String(d.getUTCDate()).padStart(2, '0'));
    }
    return out;
  }
  // Deterministic sim rows at FULL-week value for a finished week. Same
  // generator the live board uses, pinned to Saturday (dayIdx 6) so the
  // ceremony shows exactly what the board showed at week close.
  function _wrSimRowsForWeek(weekKey) {
    try {
      const S = window.SimulatedLeaderboard;
      if (!S || !S.SIMULATE_USERS || !Array.isArray(S.BOTS)) return [];
      if (typeof S._botStepsThroughDay !== 'function') return [];
      return S.BOTS
        .map(function (bot) { return { alias: bot.name, steps: S._botStepsThroughDay(weekKey, bot, 6) | 0, _sim: true }; })
        .filter(function (r) { return r.steps > 0; });
    } catch (_) { return []; }
  }
  // Real records + sims + (if absent) the caller's own row, ranked.
  function _wrMergedBoard(records, me, weekKey) {
    const myAlias = lbGetMyAlias() || '';
    const rows = [];
    (Array.isArray(records) ? records : []).forEach(function (r) {
      // W704 — carry avatar_id (the archive read returns it) so the crest survives
      // this rebuild; harmless undefined for the recap consumer / older payloads.
      rows.push({ alias: r.alias, steps: Number(r.steps) || 0, avatar_id: r.avatar_id || null, card_bg: r.card_bg || null, _sim: false });   // W706 — carry the member bg through the archive rebuild
    });
    if (me && me.steps > 0 && myAlias &&
        !rows.some(function (r) { return String(r.alias).toLowerCase() === myAlias.toLowerCase(); })) {
      rows.push({ alias: myAlias, steps: Number(me.steps) || 0, _sim: false });
    }
    // W657 review fix — mirror the live board's merge rules: a bot whose name
    // collides with a real hunter's alias is dropped (real row wins), and ties
    // rank the real hunter ahead of the sim instead of alphabetically.
    const _taken = {};
    rows.forEach(function (r) { _taken[String(r.alias).toLowerCase()] = true; });
    _wrSimRowsForWeek(weekKey).forEach(function (r) {
      if (!_taken[String(r.alias).toLowerCase()]) rows.push(r);
    });
    rows.sort(function (a, b) {
      return (b.steps - a.steps) ||
        ((a._sim === b._sim) ? String(a.alias).localeCompare(String(b.alias)) : (a._sim ? 1 : -1));
    });
    rows.forEach(function (r, i) { r.rank = i + 1; });
    return rows;
  }
  function _wrFindMe(rows) {
    const myAlias = (lbGetMyAlias() || '').toLowerCase();
    if (!myAlias) return null;
    for (let i = 0; i < rows.length; i++) {
      if (!rows[i]._sim && String(rows[i].alias).toLowerCase() === myAlias) return rows[i];
    }
    return null;
  }

  const _WR_DAY_NAMES = ['Sunday', 'Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday', 'Saturday'];
  const _WR_NEAR_MISS_MAX_GAP = 10000;   // "catchable" — about one good day's walk

  // Server payload → display model. All narrative lines are computed AFTER
  // the sim merge so ranks/podium/near-miss agree with what the user saw.
  function _wrBuildModel(r) {
    const week = r.week;
    const rows = _wrMergedBoard(r.records, r.me, week);
    const podium = rows.slice(0, 3);
    const meRow = (r.me && r.me.steps > 0) ? _wrFindMe(rows) : null;
    const fmt = function (n) { return (Number(n) || 0).toLocaleString('en-US'); };

    const model = {
      week: week,
      range: lbFormatWeekRange(week) || week,
      podium: podium,
      variant: 'normal',
      rank: null, movement: null,
      totalLine: null, bestDayLine: null, hookLine: null,
      cta: 'ENTER THE NEW WEEK',
    };

    if (!meRow) {
      // Zero-activity week — forward-framed, never a rebuke (owner-approved copy).
      model.variant = 'zero';
      model.hookLine = 'You weren’t on the board last week. Everyone starts at zero today — one walk puts you back on it.';
      model.cta = 'START THE WEEK';
      return model;
    }

    model.rank = meRow.rank;

    // Movement vs the week before (merged both weeks; sims re-roll identically).
    if (r.prev && (r.prev.records || []).length + (r.prev.me ? 1 : 0) > 0) {
      const prevRows = _wrMergedBoard(r.prev.records, r.prev.me, r.prev.week);
      const prevMe = (r.prev.me && r.prev.me.steps > 0) ? _wrFindMe(prevRows) : null;
      if (prevMe) {
        const delta = prevMe.rank - meRow.rank;
        model.movement = delta > 0 ? { dir: 'up', n: delta }
          : delta < 0 ? { dir: 'down', n: -delta }
          : { dir: 'held', n: 0 };
        // Week-over-week pass: the nearest hunter I finished ahead of who
        // had me the week before. ("You passed anthony — he had you by X.")
        for (let i = meRow.rank; i < rows.length; i++) {
          const below = rows[i]; // rank meRow.rank+1 onward (rows is 0-indexed)
          if (!below || below.rank <= meRow.rank) continue;
          const theirPrev = prevRows.find(function (p) { return String(p.alias).toLowerCase() === String(below.alias).toLowerCase(); });
          if (theirPrev && prevMe && theirPrev.rank < prevMe.rank) {
            model._pass = { alias: below.alias, gap: Math.max(0, (theirPrev.steps || 0) - (prevMe.steps || 0)) };
            break;
          }
        }
      } else {
        model.movement = { dir: 'new', n: 0 };
      }
    }

    // Week total + own-history ordinal ("your second-best week").
    let ordinalSuffix = '';
    if (r.myHistory && r.myHistory.totalWeeks > 1) {
      if (r.myHistory.ordinal === 1) ordinalSuffix = ' — your best week yet.';
      else if (r.myHistory.ordinal === 2) ordinalSuffix = ' — your second-best week.';
      else if (r.myHistory.ordinal === 3) ordinalSuffix = ' — your third-best week.';
    }
    model.totalLine = fmt(meRow.steps) + ' steps' + ordinalSuffix;

    // Best day — local daily map (device-side truth, ~30-day retention).
    try {
      const daily = (lbGetSnapshot() || {}).steps_daily || {};
      const dates = _wrWeekDates(week);
      let bestIdx = -1, bestVal = 0;
      dates.forEach(function (dk, i) {
        const v = Number(daily[dk]) || 0;
        if (v > bestVal) { bestVal = v; bestIdx = i; }
      });
      if (bestIdx >= 0 && bestVal > 0) {
        let monthMax = 0;
        Object.keys(daily).forEach(function (k) { const v = Number(daily[k]) || 0; if (v > monthMax) monthMax = v; });
        model.bestDayLine = 'Best day: ' + _WR_DAY_NAMES[bestIdx] + ' — ' + fmt(bestVal) +
          (bestVal >= monthMax ? ' · your biggest day this month' : '');
      }
    } catch (_) {}

    // THE HOOK — the line that points at next week. Priority:
    // champion > near-miss > the pass > plain placement.
    const total = rows.length;
    if (meRow.rank === 1) {
      model.variant = 'champion';
      const crowns = (r.myTitle && r.myTitle.count) ? r.myTitle.count : 1;
      model.hookLine = 'You took the week.' + (crowns > 1 ? ' Step Crown ×' + crowns + '.' : '') + ' Defend it.';
    } else {
      const above = rows[meRow.rank - 2];   // the row directly ahead of me
      const gap = above ? Math.max(1, above.steps - meRow.steps) : 0;
      if (above && gap <= _WR_NEAR_MISS_MAX_GAP) {
        model.hookLine = 'You finished ' + fmt(gap) + ' steps behind #' + above.rank + ' (' + above.alias + ').';
      } else if (model._pass) {
        model.hookLine = 'You passed ' + model._pass.alias +
          (model._pass.gap > 0 ? ' — they had you by ' + fmt(model._pass.gap) + ' last week.' : ' this week.');
      } else {
        model.hookLine = '#' + meRow.rank + ' of ' + total + ' hunters.';
      }
    }
    return model;
  }

  function _wrPodiumHtml(podium) {
    const fmt = function (n) { return (Number(n) || 0).toLocaleString('en-US'); };
    const pod = function (row, place) {
      if (!row) return '';
      return '<div class="wr-pod wr-pod-' + place + '">' +
        '<div class="wr-pod-rank">' + place + '</div>' +
        '<div class="wr-pod-alias">' + esc(row.alias) + '</div>' +
        '<div class="wr-pod-steps">' + fmt(row.steps) + '</div>' +
      '</div>';
    };
    // Visual order 2 · 1 · 3 (center elevated).
    return '<div class="wr-podium">' + pod(podium[1], 2) + pod(podium[0], 1) + pod(podium[2], 3) + '</div>';
  }

  function _wrHtml(model) {
    let me = '';
    if (model.variant === 'zero') {
      me = '<div class="wr-zero">' + esc(model.hookLine) + '</div>';
    } else {
      const mv = model.movement;
      const movePill = mv
        ? (mv.dir === 'up' ? '<span class="wr-move wr-move-up">▲ UP ' + mv.n + (mv.n === 1 ? ' SPOT' : ' SPOTS') + '</span>'
          : mv.dir === 'down' ? '<span class="wr-move wr-move-down">▼ DOWN ' + mv.n + (mv.n === 1 ? ' SPOT' : ' SPOTS') + '</span>'
          : mv.dir === 'held' ? '<span class="wr-move wr-move-held">HELD</span>'
          : '<span class="wr-move wr-move-held">NEW TO THE BOARD</span>')
        : '';
      me = '<div class="wr-me-rank">#' + model.rank + movePill + '</div>' +
        (model.totalLine ? '<div class="wr-line">' + esc(model.totalLine) + '</div>' : '') +
        (model.bestDayLine ? '<div class="wr-line">' + esc(model.bestDayLine) + '</div>' : '') +
        (model.hookLine ? '<div class="wr-hook">✦ ' + esc(model.hookLine) + '</div>' : '');
    }
    return '<div class="wr-card" role="document">' +
      '<div class="wr-kicker">' + (model.variant === 'champion' ? 'CHAMPION · WEEK COMPLETE' : 'WEEK COMPLETE') + '</div>' +
      '<div class="wr-range">' + esc(model.range) + '</div>' +
      _wrPodiumHtml(model.podium) +
      '<div class="wr-divider" aria-hidden="true"></div>' +
      '<div class="wr-me">' + me + '</div>' +
      '<button type="button" class="wr-cta" data-wr-dismiss>' + esc(model.cta) + '</button>' +
    '</div>';
  }

  function _wrDismiss(week) {
    try {
      const el = document.getElementById('wr-overlay');
      if (el) el.remove();
    } catch (_) {}
    try { localStorage.setItem('hb_recap_seen_week', week); } catch (_) {}
    // Server flag is the durable truth; fire-and-forget. If this POST is lost
    // (offline), the local hint quiets THIS device and another device still
    // gets its ceremony — the flag only flips on a delivered dismiss.
    try { if (window.Auth && typeof Auth.markWeekRecapSeen === 'function') Auth.markWeekRecapSeen(week); } catch (_) {}
  }

  function _wrPresent(model) {
    if (document.getElementById('wr-overlay')) return;
    const overlay = document.createElement('div');
    overlay.id = 'wr-overlay';
    overlay.className = 'wr-overlay';
    overlay.setAttribute('role', 'dialog');
    overlay.setAttribute('aria-modal', 'true');
    overlay.setAttribute('aria-label', 'Week recap');
    overlay.innerHTML = _wrHtml(model);
    overlay.addEventListener('click', function (e) {
      const btn = e.target && e.target.closest ? e.target.closest('[data-wr-dismiss]') : null;
      if (!btn) return;
      // W657 review fix — __wrDemo fixtures dismiss display-only: no local
      // hint, no /seen POST. A QA demo must never consume the account's REAL
      // unseen ceremony (the server flag is a one-way high-water).
      if (model._demo) { overlay.remove(); return; }
      _wrDismiss(model.week);
    });
    document.body.appendChild(overlay);
  }

  // ══ W723 — Members-only "Your Weekly Awakening" insights screen ══════════
  // Entry: a card in the Guild Hall (#social-panel). Members open the sheet;
  // non-members hit the paywall. Assembled almost entirely from local data;
  // only the Standing percentile comes from the backend (the one figure the
  // client can't know). Live CURRENT-week-to-date.
  const _WI_DOW = ['S', 'M', 'T', 'W', 'T', 'F', 'S'];
  const _WI_DOW_FULL = ['Sunday', 'Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday', 'Saturday'];
  const _WI_RARITY_RANK = { common: 0, rare: 1, ultra_rare: 2, mythic: 3 };
  const _WI_RARITY_LABEL = { common: 'Common', rare: 'Rare', ultra_rare: 'Ultra', mythic: 'S+' };
  function _wiWeekStartMs(weekStr) {
    const m = /^(\d{4})-(\d{2})-(\d{2})$/.exec(weekStr || '');
    return m ? Date.UTC(+m[1], +m[2] - 1, +m[3]) : 0;
  }
  function _wiNextDate(ds) {
    const m = /^(\d{4})-(\d{2})-(\d{2})$/.exec(ds || ''); if (!m) return '';
    const nx = new Date(Date.UTC(+m[1], +m[2] - 1, +m[3] + 1));
    return nx.getUTCFullYear() + '-' + String(nx.getUTCMonth() + 1).padStart(2, '0') + '-' + String(nx.getUTCDate()).padStart(2, '0');
  }
  function _wiDow(ds, full) {
    const m = /^(\d{4})-(\d{2})-(\d{2})$/.exec(ds || ''); if (!m) return '';
    const d = new Date(+m[1], +m[2] - 1, +m[3]).getDay();
    return (full ? _WI_DOW_FULL : _WI_DOW)[d];
  }

  // ── W725 — the insight ENGINE. Each candidate returns a scored pattern or
  // null; buildWeeklyInsights features the strongest. All computed over the
  // 30-day steps window (steps_daily is pruned to 30d — the binding limit).
  // Only days with a REAL steps entry are counted (absent ≠ 0). ──
  function _wiDaysAgoKey(baseKey, n) {
    const m = /^(\d{4})-(\d{2})-(\d{2})$/.exec(baseKey || ''); if (!m) return baseKey;
    const d = new Date(Date.UTC(+m[1], +m[2] - 1, +m[3] - n));
    return d.getUTCFullYear() + '-' + String(d.getUTCMonth() + 1).padStart(2, '0') + '-' + String(d.getUTCDate()).padStart(2, '0');
  }
  function _wiStepDaysInWindow(stepsDaily, startKey, endKey) {
    const out = [];
    for (const dk in stepsDaily) { if (dk >= startKey && dk <= endKey && typeof stepsDaily[dk] === 'number') out.push(dk); }
    return out;
  }
  function _wiAvg(a) { return a.length ? Math.round(a.reduce(function (x, y) { return x + y; }, 0) / a.length) : 0; }
  // Sleep → steps (7.5h+ nights). Score-weighted just under habit.
  function _wiSleepPattern(stepsDaily, sleepDaily, startKey, endKey) {
    try {
      const rested = [], short = [];
      _wiStepDaysInWindow(stepsDaily, startKey, endKey).forEach(function (dk) {
        const sl = sleepDaily[dk]; if (typeof sl !== 'number') return;
        (sl >= 7.5 ? rested : short).push(stepsDaily[dk] | 0);
      });
      if (rested.length < 6 || short.length < 6) return null;   // W726b — need a real sample each side
      const r = _wiAvg(rested), s = _wiAvg(short);
      if (s <= 0 || r <= s) return null;
      const lift = Math.round(((r - s) / s) * 100);
      if (lift < 12) return null;
      return { mode: 'sleep', liftPct: lift, restedAvg: r, shortAvg: s, n: rested.length + short.length, score: lift + 8 };
    } catch (_) { return null; }
  }
  // W729 — VERIFIED: HealthKit workout days vs non-workout days → steps. Objective
  // (workout_daily is Apple-Health minutes), so it belongs to the verified pool.
  function _wiWorkoutPattern(stepsDaily, workoutDaily, startKey, endKey) {
    try {
      if (!workoutDaily || typeof workoutDaily !== 'object') return null;
      const stepDays = _wiStepDaysInWindow(stepsDaily, startKey, endKey);
      if (stepDays.length < 14) return null;
      const on = [], off = [];
      stepDays.forEach(function (dk) { ((workoutDaily[dk] | 0) > 0 ? on : off).push(stepsDaily[dk] | 0); });
      if (on.length < 6 || off.length < 6) return null;   // ≥6 training AND ≥6 rest days
      const d = _wiAvg(on), m = _wiAvg(off);
      if (m <= 0 || d <= m) return null;
      const lift = Math.round(((d - m) / m) * 100);
      if (lift < 15) return null;
      return { mode: 'workout', liftPct: lift, doneAvg: d, missAvg: m, n: on.length + off.length, score: lift + 10 };
    } catch (_) { return null; }
  }
  // Habit → steps: the "wow" coach insight. For each active habit, avg steps on
  // days it was done vs skipped; feature the biggest positive lift.
  // A step-verified or movement habit IS its own step count, so correlating it
  // with steps is a tautology ("you walk more on days you did your walk habit").
  // Exclude those — the valuable insight is a NON-obvious habit → steps link
  // (Meditate, Read, Strength). Owner-flagged W726.
  function _wiIsStepTautologyHabit(h) {
    try {
      if (!h) return false;
      if (parseInt(h.stepGoal, 10) > 0) return true;   // step-goal habit = literally steps
      const n = String(h.name || '').toLowerCase();
      return /\b(walk|walking|run|running|jog|jogging|steps?|cardio|hike|hiking|treadmill|stroll|10k)\b/.test(n);
    } catch (_) { return false; }
  }
  // W728 — fraction of a habit's completions that were HealthKit-auto-verified
  // (source starts 'healthkit' or === 'apple_health'). >0.5 → objective, not a
  // self-reported check-box, so it does NOT belong in the "logged" pool.
  function _wiHabitVerifiedFrac(habitId, doneDates, autoMap) {
    try {
      if (!autoMap || !doneDates || !doneDates.length) return 0;
      let v = 0;
      doneDates.forEach(function (dk) {
        const rec = autoMap[dk] && autoMap[dk][habitId];
        const src = rec && rec.source;
        if (typeof src === 'string' && (src.indexOf('healthkit') === 0 || src === 'apple_health')) v++;
      });
      return v / doneDates.length;
    } catch (_) { return 0; }
  }
  function _wiHabitPattern(completions, stepsDaily, startKey, endKey, autoMap) {
    try {
      if (!completions || typeof completions !== 'object') return null;
      const stepDays = _wiStepDaysInWindow(stepsDaily, startKey, endKey);
      if (stepDays.length < 14) return null;   // W726b — a fortnight+ of steps before we claim causation
      const hs = (typeof habits !== 'undefined' && Array.isArray(habits))
        ? habits.filter(function (h) { return typeof _isActiveHabit === 'function' ? _isActiveHabit(h) : !!h; }) : [];
      let best = null;
      hs.forEach(function (h) {
        if (!h || !h.id || !h.name) return;
        if (_wiIsStepTautologyHabit(h)) return;   // W726 — skip walk/step habits (circular)
        const done = [], miss = [], doneDates = [];
        stepDays.forEach(function (dk) {
          const arr = completions[dk];
          if (Array.isArray(arr) && arr.indexOf(h.id) >= 0) { done.push(stepsDaily[dk] | 0); doneDates.push(dk); }
          else miss.push(stepsDaily[dk] | 0);
        });
        if (done.length < 6 || miss.length < 6) return;   // W726b — ≥6 done AND ≥6 skipped for a real split
        // W728 — the LOGGED pool is SELF-REPORTED habits only. A HealthKit-verified
        // habit is objective data (belongs to the verified side), not a check-box.
        if (_wiHabitVerifiedFrac(h.id, doneDates, autoMap) > 0.5) return;
        const d = _wiAvg(done), m = _wiAvg(miss);
        if (m <= 0 || d <= m) return;
        const lift = Math.round(((d - m) / m) * 100);
        if (lift < 15) return;
        if (!best || lift > best.liftPct) best = { mode: 'habit', habitName: h.name, liftPct: lift, doneAvg: d, missAvg: m, n: done.length + miss.length, score: lift + 12 };
      });
      return best;
    } catch (_) { return null; }
  }
  // Power day: the weekday with the highest average steps vs the overall average.
  function _wiPowerDay(stepsDaily, startKey, endKey) {
    try {
      const sum = [0, 0, 0, 0, 0, 0, 0], cnt = [0, 0, 0, 0, 0, 0, 0];
      let total = 0, days = 0;
      _wiStepDaysInWindow(stepsDaily, startKey, endKey).forEach(function (dk) {
        const v = stepsDaily[dk] | 0;
        const wd = new Date(dk + 'T12:00:00').getDay();
        sum[wd] += v; cnt[wd] += 1; total += v; days += 1;
      });
      if (days < 14) return null;   // W726b — ≥2 weeks before a "power day" is trustworthy
      const overall = total / days; if (overall <= 0) return null;
      let bw = -1, ba = 0;
      for (let i = 0; i < 7; i++) { if (cnt[i] >= 3) { const a = sum[i] / cnt[i]; if (a > ba) { ba = a; bw = i; } } }   // W726b — ≥3 samples of that weekday
      if (bw < 0) return null;
      const lift = Math.round(((ba - overall) / overall) * 100);
      if (lift < 20) return null;
      return { mode: 'powerday', dow: _WI_DOW_FULL[bw], liftPct: lift, avg: Math.round(ba), score: lift, n: days };
    } catch (_) { return null; }
  }
  // Groundwork for a future momentum pattern: persist this week's total so
  // trends can look back past the 30-day steps window. Local + synced (the one
  // aggregate NOT recomputable after the daily map prunes). Capped to 52 weeks.
  function _wiRecordWeek(weekStart, weekTotal) {
    try {
      let m = {}; try { m = JSON.parse(localStorage.getItem('hb_wi_weeks') || '{}') || {}; } catch (_) { m = {}; }
      if (weekStart) m[weekStart] = weekTotal | 0;
      const keys = Object.keys(m).sort();
      while (keys.length > 52) { const k = keys.shift(); delete m[k]; }
      localStorage.setItem('hb_wi_weeks', JSON.stringify(m));
    } catch (_) {}
  }

  // Assemble the whole model. Async — the percentile is a network read that
  // degrades to null (offline / non-member) so the screen still renders local.
  async function buildWeeklyInsights() {
    const M = { week: '', weekLabel: '', steps: {}, rank: {}, pattern: null, dungeon: {}, standing: null };
    let state = {}; try { state = loadLeaderboardState() || {}; } catch (_) {}
    const stepsDaily = (state && state.steps_daily) || {};
    const sleepDaily = (state && state.sleep_hours_daily) || {};
    const workoutDaily = (state && state.workout_daily) || {};   // W729 — verified HK workout minutes/day
    const weekStart = (typeof lbGetCurrentWeekStartPT === 'function') ? lbGetCurrentWeekStartPT() : '';
    const weekMs = _wiWeekStartMs(weekStart);
    const today = (typeof getDeviceLocalDate === 'function') ? getDeviceLocalDate() : '';
    M.week = weekStart;
    try { M.weekLabel = (typeof lbFormatWeekRange === 'function') ? lbFormatWeekRange(weekStart) : weekStart; } catch (_) { M.weekLabel = weekStart; }

    // Days of the current week so far (weekStart..today, ≤7).
    const days = [];
    let d = weekStart;
    for (let i = 0; i < 7 && d; i++) { days.push(d); if (d === today) break; d = _wiNextDate(d); if (!d || d > today) break; }

    // ── STEP DOMINION ──
    let weekTotal = 0; try { weekTotal = (typeof lbSumCurrentWeekSteps === 'function') ? (lbSumCurrentWeekSteps(stepsDaily) | 0) : 0; } catch (_) {}
    let lastTotal = 0;
    try {
      // W738 — PACE-MATCHED comparison. Sum only the SAME number of elapsed days
      // last week (days.length, not a full 7), so a partial current week isn't
      // judged against a complete prior week — the phantom "▼46% vs last week"
      // the owner caught (35,581 over 3 days vs a full ~65k week).
      let pd = (typeof _wrPriorWeek === 'function') ? _wrPriorWeek(weekStart) : '';
      for (let i = 0; i < days.length && pd && pd < weekStart; i++) { lastTotal += (stepsDaily[pd] | 0); pd = _wiNextDate(pd); }
    } catch (_) {}
    let peakDay = '', peakSteps = 0, activeDays = 0; const spark = [];
    days.forEach(function (ds) { const s = stepsDaily[ds] | 0; if (s > 0) activeDays++; spark.push({ dow: _wiDow(ds), steps: s }); if (s > peakSteps) { peakSteps = s; peakDay = ds; } });
    const daysElapsed = days.length;
    // "Mature" week = there's enough real movement to make superlatives + a WoW
    // comparison honest. A partial early week (e.g. 527 steps on a Sunday) must
    // NOT trigger mythic copy or a "-99% vs last week" against a full prior week.
    const mature = weekTotal >= 8000;
    const showWow = mature && lastTotal > 0;
    const wowPct = showWow ? Math.round(((weekTotal - lastTotal) / lastTotal) * 100) : null;
    let isPR = false; try { const we = state.best_7day_step_window_end || ''; isPR = !!(we && we >= weekStart && mature); } catch (_) {}
    let has100k = false; try { const a = (typeof accolades !== 'undefined' && accolades.get) ? accolades.get('step_100k_club') : null; has100k = !!(a && (a.unlocked_at | 0) >= weekMs); } catch (_) {}
    M.meta = { daysElapsed: daysElapsed, activeDays: activeDays, mature: mature };
    M.steps = { total: weekTotal, wowPct: wowPct, peakDow: peakDay ? _wiDow(peakDay, true) : '', peakSteps: peakSteps, spark: spark, isPR: isPR, has100k: has100k };

    // ── RANK (tier only; the "% to next rank" bar was cut — owner: not the value here) ──
    let tier = '', nextId = '';
    try {
      const rk = getRank(totalPoints) || {};
      tier = rk.id || '';
      // rk.next is a threshold NUMBER, not a rank id — resolve the next tier's
      // LETTER from RANKS (the old bar showed "12000-Rank", a bug).
      if (typeof RANKS !== 'undefined' && Array.isArray(RANKS)) {
        const ri = RANKS.findIndex(function (r) { return r.id === tier; });
        if (ri >= 0 && RANKS[ri + 1]) nextId = RANKS[ri + 1].id || '';
      }
    } catch (_) {}
    M.rank = { tier: tier, nextId: nextId };

    // ── THE HIDDEN PATTERN — score every candidate over the 30-day window and
    // feature the STRONGEST (habit correlation > sleep > power-day by weight);
    // a runner-up rides a secondary strip. Peak/early only when nothing qualifies. ──
    try {
      const endKey = today;
      // W726b — correlations analyze the FULL retained history (up to a year), not a
      // 30-day slice: legit causation needs a long baseline. _wiStepDaysInWindow keeps
      // only the step-days that actually exist, so this is simply "all we have".
      const startKey = _wiDaysAgoKey(today, 400);
      let autoMap = {}; try { autoMap = JSON.parse(localStorage.getItem('hb_completions_auto') || '{}') || {}; } catch (_) { autoMap = {}; }
      // W728 — VERIFIED pool: objective HealthKit signals only (sleep, steps-by-
      // weekday). Can't be gamed → carries the trust shield + may surface behavioral
      // "leaks". Strongest becomes the hero.
      const vCands = [];
      const sp = _wiSleepPattern(stepsDaily, sleepDaily, startKey, endKey); if (sp) vCands.push(sp);
      const wp = _wiWorkoutPattern(stepsDaily, workoutDaily, startKey, endKey); if (wp) vCands.push(wp);
      const pp = _wiPowerDay(stepsDaily, startKey, endKey); if (pp) vCands.push(pp);
      vCands.sort(function (a, b) { return (b.score || b.liftPct || 0) - (a.score || a.liftPct || 0); });
      if (vCands.length) { M.pattern = vCands[0]; M.pattern.verified = true; }
      // W728 — LOGGED pool: self-reported habit → steps (HealthKit-verified habits
      // filtered out inside). Only as honest as the user's logging, so it renders
      // below the divider WITHOUT the verified shield.
      const lp = _wiHabitPattern(completions, stepsDaily, startKey, endKey, autoMap);
      if (lp) M.logged = lp;
    } catch (_) {}
    if (!M.pattern) {
      // Nothing meaningful yet — a real "fiercest day" hero needs real steps
      // (527 is not "the void"); below the bar → an honest early-week teaser.
      M.pattern = (peakSteps >= 8000)
        ? { mode: 'peak', dow: _wiDow(peakDay, true), steps: peakSteps }
        : { mode: 'early', daysElapsed: daysElapsed, activeDays: activeDays };
    }
    try { _wiRecordWeek(weekStart, weekTotal); } catch (_) {}

    // ── DUNGEON — bosses this week (souls ledger) + best drop (drop ledger) ──
    let bossCount = 0;
    try {
      const led = (typeof _readSoulsLedger === 'function') ? (_readSoulsLedger() || []) : [];
      bossCount = led.filter(function (e) { return e && (e.ts | 0) >= weekMs && (e.type === 'boss_kill' || e.type === 'coop_kill'); }).length;
    } catch (_) {}
    let bestDrop = null;
    try {
      const dl = (typeof _readDropLedger === 'function') ? (_readDropLedger() || []) : [];
      dl.forEach(function (e) {
        if (!e || (e.ts | 0) < weekMs) return;
        const r = _WI_RARITY_RANK[e.rarity] != null ? _WI_RARITY_RANK[e.rarity] : -1;
        if (r < 1) return;                          // only rare+ is a "flex"
        if (!bestDrop || r > bestDrop._r || (r === bestDrop._r && (e.ts | 0) > (bestDrop._ts | 0))) {
          bestDrop = { name: e.cardName || 'a relic', rarity: e.rarity, src: e.sourceLabel || '', _r: r, _ts: e.ts | 0 };
        }
      });
    } catch (_) {}
    M.dungeon = { bosses: bossCount, drop: bestDrop };

    // ── STANDING — the one figure the client can't know (backend percentile) ──
    try {
      if (window.Auth && typeof Auth.fetchInsightsWeekly === 'function') {
        const r = await Auth.fetchInsightsWeekly();
        if (r && r.ok && r.me) M.standing = r.me;   // { weekTotal, rankTier, global, cohort }
      }
    } catch (_) {}

    return M;
  }

  // Render the model into the ported "Your Weekly Awakening" markup. Classes
  // are scoped under #wi-overlay in styles.css (device chrome stripped from the
  // ClaudeDesign mock). Two soft-blocker sub-elements from the mock — the
  // training-streak dots and the rank "~N weeks" ETA — are omitted in v1
  // (no per-day workout log / no weekly-XP-rate source); everything shown is
  // real data.
  function _wiHtml(M) {
    const s = M.steps || {}, rk = M.rank || {}, pat = M.pattern || {}, dg = M.dungeon || {}, st = M.standing;
    const nf = function (n) { return (n | 0).toLocaleString('en-US'); };

    // ── Standing — lead with the VALUE, not the rank (owner). Percentile when
    // the board's real; else fall back to this-week consistency (always honest,
    // even on day 1). The rank gem stays as quiet identity; the "% to next
    // rank" bar is gone. ──
    const meta = M.meta || {};
    let standHead, standingSub;
    if (st && st.global && !st.global.lowConfidence) {
      standHead = '<b class="num">Top ' + (st.global.topPct | 0) + '%</b>';
      standingSub = 'of all Hunters this week';
    } else if ((meta.daysElapsed | 0) > 0) {
      standHead = '<b class="num">' + (meta.activeDays | 0) + ' / ' + (meta.daysElapsed | 0) + '</b>';
      standingSub = ((meta.activeDays | 0) >= (meta.daysElapsed | 0))
        ? 'days active — a perfect run so far' : 'days active this week';
    } else {
      standHead = '<b>A new week</b>'; standingSub = 'your standing takes shape';
    }

    // ── Step dominion ──
    const delta = (s.wowPct != null)
      ? '<div class="wi-delta ' + (s.wowPct < 0 ? 'down' : '') + '">' + (s.wowPct < 0 ? '▼ ' : '▲ ') + Math.abs(s.wowPct) + '% <span>vs last week’s pace</span></div>'
      : '';
    let cohortLine = '';
    if (st && st.cohort && !st.cohort.lowConfidence && rk.tier) {
      cohortLine = '<div class="wi-pctl"><div class="wi-pctl-track"><i style="width:' + (st.cohort.beatPct | 0) + '%"></i></div>'
        + '<div class="wi-pctl-cap">Outpaced <b>' + (st.cohort.beatPct | 0) + '%</b> of ' + esc(rk.tier) + '-Rank hunters</div></div>';
    }
    const foils = [];
    if (s.isPR) foils.push('<div class="wi-foil"><span class="wi-fs">✦</span> New Personal Record</div>');
    if (s.has100k) foils.push('<div class="wi-foil"><span class="wi-fs">✦</span> 100K Club Claimed</div>');
    const foilsHtml = foils.length ? '<div class="wi-foils">' + foils.join('') + '</div>' : '';
    const sparkMax = Math.max(1, ...(s.spark || []).map(function (b) { return b.steps | 0; }));
    const sparkHtml = (s.spark || []).map(function (b) {
      const peak = (b.steps | 0) === (s.peakSteps | 0) && (s.peakSteps | 0) > 0;
      const h = Math.round(((b.steps | 0) / sparkMax) * 50) + 4;
      return '<div class="wi-b' + (peak ? ' peak' : '') + '"><i style="height:' + h + 'px"></i><em>' + esc(b.dow) + '</em></div>';
    }).join('');
    const sparkCap = (s.peakSteps | 0) > 0
      ? '<div class="wi-spark-cap"><div class="wi-sc1">Peak Day · ' + esc(s.peakDow || '') + '</div><div class="wi-sc2 num">' + nf(s.peakSteps) + '</div><div class="wi-sc3">steps in one day</div></div>'
      : '';

    // ── Hidden Pattern (signature) ──
    let heroInner;
    if (pat.mode === 'sleep') {
      const shortW = Math.max(6, Math.round(((pat.shortAvg | 0) / Math.max(1, pat.restedAvg | 0)) * 100));
      const leakPct = Math.max(0, Math.round((((pat.restedAvg | 0) - (pat.shortAvg | 0)) / Math.max(1, pat.restedAvg | 0)) * 100));
      heroInner =
        '<div class="wi-hero-reveal"><div class="wi-reveal-kick">You move</div>'
        + '<div class="wi-reveal-big"><span class="wi-reveal-num foil-text num">+' + (pat.liftPct | 0) + '%</span><span class="wi-reveal-more">more</span></div>'
        + '<div class="wi-reveal-sub">on the days after a full night’s sleep.</div></div>'
        + '<div class="wi-compare">'
        + '<div class="wi-cmp-row wi-rested"><div class="wi-cmp-head"><span class="wi-cmp-label">Rested · 7.5h+</span><span class="wi-cmp-val num">' + nf(pat.restedAvg) + '</span></div><div class="wi-cmp-bar"><i style="width:100%"></i></div></div>'
        + '<div class="wi-cmp-row wi-short"><div class="wi-cmp-head"><span class="wi-cmp-label">Short nights</span><span class="wi-cmp-val num">' + nf(pat.shortAvg) + '</span></div><div class="wi-cmp-bar"><i style="width:' + shortW + '%"></i></div></div>'
        + '<div class="wi-cmp-foot">avg / day · across ' + (pat.n | 0) + ' days</div></div>'
        + (leakPct >= 10 ? '<div class="wi-leak"><span class="wi-leak-ic">↓</span> You lose about <b>' + leakPct + '%</b> of your movement on short-sleep nights.</div>' : '');
    } else if (pat.mode === 'workout') {
      const offW = Math.max(6, Math.round(((pat.missAvg | 0) / Math.max(1, pat.doneAvg | 0)) * 100));
      heroInner =
        '<div class="wi-hero-reveal"><div class="wi-reveal-kick">On training days</div>'
        + '<div class="wi-reveal-big"><span class="wi-reveal-num foil-text num">+' + (pat.liftPct | 0) + '%</span><span class="wi-reveal-more">steps</span></div>'
        + '<div class="wi-reveal-sub">than the days you don’t train.</div></div>'
        + '<div class="wi-compare">'
        + '<div class="wi-cmp-row wi-rested"><div class="wi-cmp-head"><span class="wi-cmp-label">Training days</span><span class="wi-cmp-val num">' + nf(pat.doneAvg) + '</span></div><div class="wi-cmp-bar"><i style="width:100%"></i></div></div>'
        + '<div class="wi-cmp-row wi-short"><div class="wi-cmp-head"><span class="wi-cmp-label">Rest days</span><span class="wi-cmp-val num">' + nf(pat.missAvg) + '</span></div><div class="wi-cmp-bar"><i style="width:' + offW + '%"></i></div></div>'
        + '<div class="wi-cmp-foot">avg / day · across ' + (pat.n | 0) + ' days</div></div>';
    } else if (pat.mode === 'habit') {
      const missW = Math.max(6, Math.round(((pat.missAvg | 0) / Math.max(1, pat.doneAvg | 0)) * 100));
      heroInner =
        '<div class="wi-hero-reveal"><div class="wi-reveal-kick">On ' + esc(pat.habitName) + ' days</div>'
        + '<div class="wi-reveal-big"><span class="wi-reveal-num foil-text num">+' + (pat.liftPct | 0) + '%</span><span class="wi-reveal-more">steps</span></div>'
        + '<div class="wi-reveal-sub">than the days you skip it.</div></div>'
        + '<div class="wi-compare">'
        + '<div class="wi-cmp-row wi-rested"><div class="wi-cmp-head"><span class="wi-cmp-label">' + esc(pat.habitName) + ' days</span><span class="wi-cmp-val num">' + nf(pat.doneAvg) + '</span></div><div class="wi-cmp-bar"><i style="width:100%"></i></div></div>'
        + '<div class="wi-cmp-row wi-short"><div class="wi-cmp-head"><span class="wi-cmp-label">Other days</span><span class="wi-cmp-val num">' + nf(pat.missAvg) + '</span></div><div class="wi-cmp-bar"><i style="width:' + missW + '%"></i></div></div>'
        + '<div class="wi-cmp-foot">avg / day · across ' + (pat.n | 0) + ' days</div></div>';
    } else if (pat.mode === 'powerday') {
      heroInner =
        '<div class="wi-hero-reveal"><div class="wi-reveal-kick">Your power day</div>'
        + '<div class="wi-reveal-big"><span class="wi-reveal-num wi-reveal-word foil-text">' + esc(pat.dow) + '</span></div>'
        + '<div class="wi-reveal-sub"><b style="color:var(--wi-gold2)">+' + (pat.liftPct | 0) + '%</b> above your average — ' + esc(pat.dow) + 's are when you move most.</div>'
        + ((pat.n | 0) > 0 ? '<div class="wi-window-note">across your last ' + (pat.n | 0) + ' days</div>' : '')
        + '</div>';
    } else if (pat.mode === 'peak') {
      const pk = (pat.steps | 0);
      const pkLine = pk >= 20000 ? 'you were unstoppable.' : pk >= 13000 ? 'you refused to be still.' : 'you kept the fire lit.';
      heroInner =
        '<div class="wi-hero-reveal"><div class="wi-reveal-kick">Your fiercest day</div>'
        + '<div class="wi-reveal-big"><span class="wi-reveal-num foil-text num">' + nf(pat.steps) + '</span><span class="wi-reveal-more">steps</span></div>'
        + '<div class="wi-reveal-sub">' + esc(pat.dow || 'one day') + ', ' + pkLine + '</div></div>';
    } else {
      // Early week — honest teaser, no hollow superlatives on a handful of steps.
      const ad = (pat.activeDays | 0), de = (pat.daysElapsed | 0);
      heroInner =
        '<div class="wi-hero-reveal"><div class="wi-reveal-kick">Your pattern is forming</div>'
        + '<div class="wi-reveal-sub">Insights sharpen as the week unfolds — move, sleep, and train, and the signal reveals itself.'
        + (de > 0 ? ' Active <b style="color:var(--wi-gold2)">' + ad + ' of ' + de + '</b> days so far.' : '')
        + '</div></div>';
    }
    // W728 — VERIFIED trust shield on the hero (objective, HealthKit-sourced — can't
    // be gamed). Only the verified pool (sleep / power-day) sets pat.verified.
    const shieldHtml = (pat && pat.verified)
      ? '<div class="wi-vbadge"><span class="wi-vbadge-ic">✓</span> Verified — from data you can’t fake</div>'
      : '';
    // W728 — "From your logs" secondary: the self-reported habit correlation, below a
    // divider, with NO shield (only as honest as the user's own logging).
    let loggedHtml = '';
    const lg = M.logged;
    if (lg && lg.mode === 'habit') {
      loggedHtml = '<div class="wi-hero-div"></div>'
        + '<div class="wi-logged"><div class="wi-logged-ey">From your logs</div>'
        + '<div class="wi-logged-line">On <b>' + esc(lg.habitName) + '</b> days you move <b class="wi-lg-pct">+' + (lg.liftPct | 0) + '%</b> more'
        + '<span class="wi-logged-sub"> · ' + (lg.n | 0) + ' logged days</span></div></div>';
    }
    const heroHtml =
      '<section class="wi-hero"><div class="wi-hero-sky"><div class="wi-moon"></div>'
      + '<i class="wi-star a"></i><i class="wi-star b"></i><i class="wi-star c"></i><i class="wi-star d"></i><i class="wi-star e"></i></div>'
      + '<div class="wi-hero-ey">✦ The Hidden Pattern ✦</div>' + shieldHtml + heroInner + loggedHtml + '</section>';

    // ── Dungeon + loot ──
    let lootHtml = '';
    if (dg.drop) {
      lootHtml =
        '<div class="wi-loot"><div class="wi-loot-art"><span class="wi-loot-rank">' + esc(_WI_RARITY_LABEL[dg.drop.rarity] || '★') + '</span><span class="wi-lg">✦</span></div>'
        + '<div class="wi-loot-body"><div class="wi-loot-eb">Most Powerful Drop</div><div class="wi-loot-name">' + esc(dg.drop.name) + '</div>'
        + (dg.drop.src ? '<div class="wi-loot-src">From · ' + esc(dg.drop.src) + '</div>' : '') + '</div></div>';
    }
    const dungeonHtml = (dg.bosses | 0) > 0
      ? '<section class="wi-section"><div class="wi-eyebrow"><span class="wi-idx">✦</span> Dungeon Victories</div>'
        + '<div class="wi-dungeon"><div class="wi-dg-head"><div class="wi-dg-count num">' + (dg.bosses | 0) + '</div>'
        + '<div class="wi-dg-txt"><div class="wi-dg-t1">Bosses Defeated</div><div class="wi-dg-t2">' + ((dg.bosses | 0) >= 5 ? 'A relentless week of raids' : 'Steel met resolve') + '</div></div></div>'
        + lootHtml + '</div></section>'
      : '';

    // ── Guild reflection — the mythic line only when there's a real day behind it. ──
    const reflection = ((M.meta && M.meta.mature) && (s.peakSteps | 0) >= 8000)
      ? esc(s.peakDow || 'This week') + ', you moved like the void itself — <b>' + nf(s.peakSteps) + ' steps</b> in a single day. The Guild sings of your name, Hunter.'
      : 'The week is young, Hunter — every step from here writes the legend. The Guild is watching.';

    return ''
      + '<div class="wi-scrim" data-wi-dismiss></div>'
      + '<div class="wi-sheet" role="dialog" aria-modal="true" aria-label="Your Weekly Awakening">'
      + '<button class="wi-close" data-wi-dismiss aria-label="Close">✕</button>'
      + '<div class="wi-content">'
      + '<header class="wi-header"><div class="wi-members-chip"><span class="wi-sp">✦</span> Members Only</div>'
      + '<h1 class="wi-title foil-text">Your&nbsp;Weekly<br>Awakening</h1>'
      + '<div class="wi-dateline">' + esc(M.weekLabel || '') + '</div></header>'
      // Standing — value headline; rank gem is quiet identity, no "% to rank" bar
      + '<section class="wi-standing"><div class="wi-stand-top"><div class="wi-gem"><div class="wi-in"><span class="wi-rk">' + esc(rk.tier || '—') + '</span></div></div>'
      + '<div class="wi-stand-flex"><div class="wi-stand-ey">Your Standing</div>'
      + '<div class="wi-stand-big">' + standHead + '</div>'
      + '<div class="wi-stand-sub">' + standingSub + '</div></div></div></section>'
      // Step dominion
      + '<section class="wi-section"><div class="wi-eyebrow"><span class="wi-idx">✦</span> Step Dominion</div>'
      + '<div class="wi-band"><div class="wi-band-hero"><div class="wi-band-num num">' + nf(s.total) + '</div><div class="wi-band-unit">Steps<br>This Week</div>' + delta + '</div>'
      + cohortLine + foilsHtml
      + (sparkHtml ? '<div class="wi-spark"><div class="wi-spark-bars">' + sparkHtml + '</div>' + sparkCap + '</div>' : '')
      + '</div></section>'
      // Hidden pattern
      + heroHtml
      // Dungeon
      + dungeonHtml
      // Reflection
      + '<section class="wi-reflection"><div class="wi-ref-mark">“</div><p class="wi-ref-quote">' + reflection + '</p>'
      + '<div class="wi-ref-sign"><i></i><span>The First Awakened</span><i></i></div></section>'
      // Share + an always-reachable bottom close (belt-and-suspenders with the fixed ✕)
      + '<div class="wi-sharebar"><button class="wi-share" data-wi-share><span>Share to Guild</span></button>'
      + '<button class="wi-bottomclose" data-wi-dismiss>Close</button></div>'
      + '</div></div>';
  }

  function _wiDismiss() { try { const el = document.getElementById('wi-overlay'); if (el) el.remove(); } catch (_) {} }
  function _wiShare(M) {
    try {
      const s = (M && M.steps) || {};
      const txt = 'My Weekly Awakening — ' + ((s.total | 0).toLocaleString('en-US')) + ' steps'
        + (M && M.rank && M.rank.tier ? ', ' + M.rank.tier + '-Rank' : '') + '. #Awakened';
      if (navigator.share) { navigator.share({ title: 'Your Weekly Awakening', text: txt }).catch(function () {}); }
      else if (typeof showHabitToast === 'function') showHabitToast('Recap ready to share.');
    } catch (_) {}
  }
  function _wiPresent(M) {
    if (document.getElementById('wi-overlay')) return;
    const overlay = document.createElement('div');
    overlay.id = 'wi-overlay';
    overlay.className = 'wi-overlay';
    overlay.innerHTML = _wiHtml(M);
    overlay.addEventListener('click', function (e) {
      const t = e.target;
      if (t && t.closest && t.closest('[data-wi-share]')) { _wiShare(M); return; }
      if (t && t.closest && t.closest('[data-wi-dismiss]')) { _wiDismiss(); }
    });
    document.body.appendChild(overlay);
  }

  // Entry from the Guild Hall. Members → build + present; non-members → paywall.
  let _wiOpening = false;
  async function openWeeklyInsights() {
    try {
      const isMember = (typeof _founderOwned === 'function') ? _founderOwned() : false;
      if (!isMember) { try { if (typeof openFounder === 'function') openFounder(); } catch (_) {} return; }
      if (_wiOpening || document.getElementById('wi-overlay')) return;
      _wiOpening = true;
      let M;
      try { M = await buildWeeklyInsights(); } finally { _wiOpening = false; }
      if (M) _wiPresent(M);
    } catch (_) { _wiOpening = false; }
  }
  try { window.__wiDemo = function () { buildWeeklyInsights().then(_wiPresent); }; } catch (_) {}
  // Delegated open — the Guild Hall entry card (#wi-entry) is static markup, so
  // one document-level listener covers it whenever the panel is shown.
  try {
    document.addEventListener('click', function (e) {
      const t = e.target;
      if (t && t.closest && t.closest('[data-wi-open]')) { try { e.preventDefault(); } catch (_) {} openWeeklyInsights(); }
    });
  } catch (_) {}

  // One ceremony per finished week per session; server decides seen/eligible.
  let _wrShownForWeek = null;
  async function _wrMaybeShowWeekRecap() {
    try {
      if (!window.Auth || typeof Auth.fetchWeekRecap !== 'function') return;
      const finished = _wrPriorWeek(lbGetCurrentWeekStartPT());
      if (!finished) return;
      if (_wrShownForWeek === finished) return;
      if (document.getElementById('wr-overlay')) return;
      let hint = '';
      try { hint = localStorage.getItem('hb_recap_seen_week') || ''; } catch (_) {}
      if (hint >= finished) return;                       // dismissed on this device
      // Defer under any higher-priority beat — the flag persists, so the
      // next open retries (the "recap waits for you" contract).
      if (typeof _isAnyHigherPriorityModalActive === 'function' && _isAnyHigherPriorityModalActive()) return;
      const r = await Auth.fetchWeekRecap();
      if (!r || !r.ok) return;                            // offline → try next open
      if (!r.eligible || r.seen) {
        // Quiet this device without waiting for another round trip.
        try { localStorage.setItem('hb_recap_seen_week', r.week || finished); } catch (_) {}
        return;
      }
      // Re-check the beat guard — the fetch may have raced a modal opening.
      if (typeof _isAnyHigherPriorityModalActive === 'function' && _isAnyHigherPriorityModalActive()) return;
      if (_wrShownForWeek === finished || document.getElementById('wr-overlay')) return;
      _wrShownForWeek = finished;
      _wrPresent(_wrBuildModel(r));
    } catch (_) {}
  }

  // Preview/QA hook (matches the __pvp* convention): renders a fixture
  // ceremony without a backend. variant: 'normal' | 'champion' | 'zero'.
  window.__wrDemo = function (variant) {
    const week = _wrPriorWeek(lbGetCurrentWeekStartPT());
    const fix = {
      week: week, weekEnd: week, total: 9,
      records: [
        { rank: 1, alias: 'rendiesel', steps: 125563 },
        { rank: 2, alias: 'anthony', steps: 68740 },
        { rank: 3, alias: 'james', steps: 68400 },
      ],
      me: variant === 'zero' ? null
        : variant === 'champion' ? { rank: 1, steps: 125563 }
        : { rank: 3, steps: 68400 },
      prev: {
        week: _wrPriorWeek(week),
        records: [
          { rank: 1, alias: 'rendiesel', steps: 110000 },
          { rank: 2, alias: 'james', steps: 72000 },
          { rank: 3, alias: 'anthony', steps: 64000 },
        ],
        me: variant === 'zero' ? null
          : variant === 'champion' ? { rank: 1, steps: 110000 }
          : { rank: 9, steps: 41000 },
      },
      myHistory: { ordinal: 2, totalWeeks: 8 },
      myTitle: variant === 'champion' ? { count: 3, isNew: true } : null,
    };
    if (variant === 'champion') { fix.records[0].alias = lbGetMyAlias() || 'you'; }
    if (variant !== 'zero' && variant !== 'champion') { fix.records[2].alias = lbGetMyAlias() || 'you'; }
    const m = _wrBuildModel(fix);
    m._demo = true;   // display-only dismiss — never marks the real week seen
    _wrPresent(m);
  };

  // ── W658 — Leaderboard Archive: the week-flipper ────────────────────────
  // The Steps board's header date-range becomes navigable: ‹ steps back
  // through past weeks' FINAL standings (8-week cap, bounded by the earliest
  // real data), › steps forward and back to the live race. Steps only —
  // Highest Floor / Collection are all-time and have no per-week history.
  // Data: GET /v1/leaderboard/archive (durable weekly_step_records merge);
  // sims re-roll deterministically at full-week value via _wrMergedBoard,
  // so a past week renders exactly the board that closed that Saturday.
  let _lbArchWeek = null;          // null = live board; else the viewed week key
  let _lbArchWeeks = null;         // weeks_available from the last fetch (newest first)
  const _lbArchCache = {};         // week -> response (finished weeks are immutable)
  let _lbArchWired = false;

  function _lbArchReset() { _lbArchWeek = null; }

  // Same-month collapse ("Jul 5 – 11"), mirroring the live context line.
  function _lbArchRangeLabel(week) {
    let label = '';
    try {
      const range = lbFormatWeekRange(week);
      if (range) {
        const parts = range.split('–');
        if (parts.length === 2) {
          const a = parts[0].trim(), b = parts[1].trim();
          const mA = a.split(' ')[0], pB = b.split(' ');
          label = a + ' – ' + ((pB[0] === mA && pB[1]) ? pB[1] : b);
        } else {
          label = range;
        }
      }
    } catch (_) {}
    return label || week;
  }

  // Archive-mode context line: ‹ Jul 5 – 11 · FINAL ›. No RESETS SUNDAY, no
  // countdown — frozen history must never read as a live race.
  function _lbArchContextHtml(week) {
    const atOldest = !!(_lbArchWeeks && (!_lbArchWeeks.length || week <= _lbArchWeeks[_lbArchWeeks.length - 1])) ||
      week <= _lbArchOldestAllowed();
    return '<button type="button" class="lb-arch-nav' + (atOldest ? ' is-disabled' : '') + '"' +
        ' data-lb-arch="prev" aria-label="Earlier week"' + (atOldest ? ' disabled' : '') + '>&#8249;</button>' +
      '<span class="lb-ctx-date">' + esc(_lbArchRangeLabel(week)) + '</span>' +
      '<span class="lb-arch-final">FINAL</span>' +
      '<button type="button" class="lb-arch-nav" data-lb-arch="next" aria-label="Later week">&#8250;</button>';
  }

  // One-time delegated wiring on the persistent #lb-week-reset container.
  function _lbArchWire() {
    if (_lbArchWired) return;
    const host = document.getElementById('lb-week-reset');
    if (!host) return;
    _lbArchWired = true;
    host.addEventListener('click', function (e) {
      const btn = e.target && e.target.closest ? e.target.closest('[data-lb-arch]') : null;
      if (!btn || btn.disabled) return;
      _lbArchStep(btn.getAttribute('data-lb-arch'));
    });
  }

  // The oldest week the flipper may ever request: prior^8 of the live week
  // (mirrors the server's ARCHIVE_WEEKS_CAP so pre-floor mashing can't march
  // into 400-land before the first response teaches us the real floor).
  const _LB_ARCH_CAP = 8;
  function _lbArchOldestAllowed() {
    let k = lbGetCurrentWeekStartPT();
    for (let i = 0; i < _LB_ARCH_CAP; i++) { const p = _wrPriorWeek(k); if (!p) return k; k = p; }
    return k;
  }

  function _lbArchStep(dir) {
    if (_lbCurrentOpenMetric !== 'step_total' || _lbCurrentTab !== 'this-week') return;
    const liveWeek = lbGetCurrentWeekStartPT();
    if (dir === 'prev') {
      const target = _lbArchWeek === null ? _wrPriorWeek(liveWeek) : _wrPriorWeek(_lbArchWeek);
      if (!target) return;
      // W658 review fix — hard cap client-side (server mirrors it) …
      if (target < _lbArchOldestAllowed()) return;
      // … and bound by the learned floor. A KNOWN-EMPTY list means no
      // archived weeks exist at all — ‹ does nothing rather than 400ing.
      if (_lbArchWeeks && (!_lbArchWeeks.length || target < _lbArchWeeks[_lbArchWeeks.length - 1])) return;
      _lbRenderArchiveWeek(target);
    } else if (dir === 'next' && _lbArchWeek !== null) {
      const newestArch = _wrPriorWeek(liveWeek);
      if (_lbArchWeek >= newestArch) {
        // Forward past the newest finished week → back to the live race.
        _lbArchReset();
        _lbRenderThisWeekTab('step_total');
      } else {
        // The week AFTER the viewed one = viewed + 7 days (pure date math).
        const m = /^(\d{4})-(\d{2})-(\d{2})$/.exec(_lbArchWeek);
        if (!m) return;
        const d = new Date(Date.UTC(+m[1], +m[2] - 1, +m[3]) + 7 * 86400000);
        _lbRenderArchiveWeek(d.getUTCFullYear() + '-' + String(d.getUTCMonth() + 1).padStart(2, '0') + '-' +
          String(d.getUTCDate()).padStart(2, '0'));
      }
    }
  }

  async function _lbRenderArchiveWeek(week) {
    const listEl = document.getElementById('lb-rank-list');
    if (!listEl) return;
    _lbArchWeek = week;
    // Archive mode owns the surface: hide the This-Week-only extras.
    try {
      const _lw = document.getElementById('lb-lastweek-recap'); if (_lw) _lw.classList.add('hidden');
      const _mb = document.getElementById('lb-rank-mebest'); if (_mb) _mb.classList.add('hidden');
      const _yf = document.getElementById('lb-you-footer'); if (_yf) { _yf.innerHTML = ''; _yf.classList.add('hidden'); }
      const _sh = document.getElementById('lb-rank-sheet'); if (_sh) _sh.classList.remove('lb-has-youfoot');
    } catch (_) {}
    const _resetEl = document.getElementById('lb-week-reset');
    if (_resetEl) { _resetEl.innerHTML = _lbArchContextHtml(week); _resetEl.classList.remove('hidden'); }

    let data = _lbArchCache[week];
    if (!data) {
      listEl.innerHTML = lbBuildLoadingSkeleton();
      let result;
      try { result = await window.Auth.fetchLeaderboardArchive(week); }
      catch (e) { result = { ok: false, code: 'NETWORK' }; }
      // W658 review fix — finished weeks are immutable: bank a landed success
      // (cache + the floor) even when this render was superseded by another
      // flip, so paging back never re-fetches and the ‹ bound is learned from
      // EVERY response, not just the one still on screen.
      if (result && result.ok) {
        _lbArchCache[week] = result;
        if (Array.isArray(result.weeksAvailable)) _lbArchWeeks = result.weeksAvailable;
      }
      // The user may have flipped again / switched tab or metric mid-fetch.
      if (_lbCurrentOpenMetric !== 'step_total' || _lbCurrentTab !== 'this-week' || _lbArchWeek !== week) return;
      if (!result || !result.ok) {
        listEl.innerHTML = lbBuildErrorState(result && result.code);
        return;
      }
      data = result;
    }
    // Authoritative even when EMPTY (= no archived weeks exist yet).
    if (Array.isArray(data.weeksAvailable)) _lbArchWeeks = data.weeksAvailable;
    // Refresh the context line now that the floor is known (arrow disabling).
    if (_resetEl && _lbArchWeek === week) _resetEl.innerHTML = _lbArchContextHtml(week);

    // Deterministic full-week sim merge (dedup + real-first ties) → list rows.
    const merged = _wrMergedBoard(data.records, data.me, week);
    const rows = merged.map(function (r) {
      // W704 — avatar_id rides through so archived real hunters wear their crest
      // (without it, only sim bots would resolve portraits — backwards).
      return { rank: r.rank, alias: r.alias, current_value: r.steps, avatar_id: r.avatar_id || null, card_bg: r.card_bg || null, _sim: !!r._sim };   // W706 — archived rows keep the member bg
    });
    const meRow = _wrFindMe(merged);
    const meForList = meRow ? { rank: meRow.rank, current_value: meRow.steps } : null;
    if (!rows.length) {
      listEl.innerHTML = '<div class="lb-rank-empty">' +
        '<div class="lb-rank-empty-icon" aria-hidden="true">&#128220;</div>' +
        '<div class="lb-rank-empty-title">No final board for this week.</div>' +
        '<div class="lb-rank-empty-body">Records begin the first week hunters synced steps.</div>' +
      '</div>';
      return;
    }
    try { _lbAnnotateClub100k(rows); } catch (_) {}
    let html = lbBuildRankList('step_total', rows.slice(0, _LB_VISIBLE_CAP), meForList);
    html += '<div class="lb-list-foot">Final standings · ' + esc(_lbArchRangeLabel(week)) + '</div>';
    listEl.innerHTML = html;
  }

  async function openLeaderboardRanking(metric, opts) {
    const meta = LB_METRIC_META[metric];
    if (!meta) return;

    // v3 Phase 1z.132 — track where the detail was opened from so
    // closeLeaderboardRanking can route the X tap back to the hub
    // when applicable. Resets to null on every open so a prior
    // stale 'hub' value can't leak into a direct entry (e.g., the
    // steps-card click handler, which doesn't pass opts).
    _lbDetailReturnTarget = (opts && opts.returnTarget) || null;
    const sheet   = document.getElementById('lb-rank-sheet');
    const overlay = document.getElementById('lb-rank-overlay');
    const listEl  = document.getElementById('lb-rank-list');
    if (!sheet || !overlay || !listEl) return;
    // W331 — guests cannot post scores; nudge sign-in rather than show an
    // empty board. Show the sheet with the join prompt and skip the fetch.
    if (window.Auth && typeof Auth.isGuest === 'function' && Auth.isGuest()) {
      const _t = document.getElementById('lb-rank-title'); if (_t) _t.textContent = (meta.title || 'Leaderboard');
      ['lb-rank-tabs','lb-rank-metric-switch','lb-rank-mebest','lb-week-reset','lb-you-footer'].forEach(function (id) {
        const el = document.getElementById(id); if (el) el.classList.add('hidden');
      });
      // W386 — clear any pinned YOU-footer state left over from a prior signed-in session.
      const _yfG = document.getElementById('lb-you-footer'); if (_yfG) _yfG.innerHTML = '';
      sheet.classList.remove('lb-has-youfoot');
      const _bl = document.getElementById('lb-rank-blurb'); if (_bl) _bl.textContent = '';
      listEl.innerHTML = _guestJoinHtml('Join the leaderboard', 'Sign in to post your scores and climb against real hunters.');
      overlay.classList.remove('hidden');
      sheet.classList.remove('hidden');
      return;
    }

    // v3 Phase 1z.36 — title is "Steps" when the HoF tab is available
    // (the segmented control labels handle the "This Week" framing);
    // otherwise the per-metric title (e.g. "7+ hour sleep streak").
    const tabsEl = document.getElementById('lb-rank-tabs');
    const hasHof = LB_HOF_METRICS.has(metric);
    document.getElementById('lb-rank-title').textContent = hasHof ? 'Steps' : meta.title;
    if (tabsEl) {
      tabsEl.classList.toggle('hidden', !hasHof);
      // Reset tab state to 'this-week' on every open so a previous
      // session's HoF selection doesn't surprise users.
      const buttons = tabsEl.querySelectorAll('.lb-rank-tab');
      buttons.forEach(b => {
        const isThisWeek = b.getAttribute('data-lb-tab') === 'this-week';
        b.classList.toggle('is-active', isThisWeek);
        b.setAttribute('aria-selected', isThisWeek ? 'true' : 'false');
      });
    }

    // W274 — Steps ⇄ Highest Floor metric switch; W630 — Collection joins it
    // (the W622 board's first LIVE entry point — the old hub row was a dead
    // surface). Shown only for this trio; other metrics opened directly keep
    // their single-list header. relics_collected isn't in LB_HOF_METRICS, so
    // the sub-tabs auto-hide and the title reads the metric's own ("Collection
    // Log") — same single-list path floor_best takes.
    const switchEl = document.getElementById('lb-rank-metric-switch');
    if (switchEl) {
      const inPair = metric === 'step_total' || metric === 'floor_best' || metric === 'relics_collected';
      switchEl.classList.toggle('hidden', !inPair);
      if (inPair) {
        switchEl.querySelectorAll('.lb-metric-btn').forEach((b) => {
          const on = b.getAttribute('data-lb-metric-switch') === metric;
          b.classList.toggle('is-active', on);
          b.setAttribute('aria-selected', on ? 'true' : 'false');
        });
      }
    }

    _lbCurrentOpenMetric = metric;
    _lbCurrentTab = 'this-week';

    overlay.classList.remove('hidden');
    sheet.classList.remove('hidden');

    // v3 Phase 1z.126 / 1z.127 — opening the Flights Climbed sheet
    // forces a fresh full-week HealthKit backfill so the user-row
    // "me" value reflects every flight already in Health for this
    // week (not just what's been recorded since feature install).
    //
    // 1z.127 update: switch from `lbSubmitAllMetricsDebounced` (5-min
    // throttle, fire-and-forget) to a non-debounced AWAITED submit
    // so backend persists the refreshed value before the modal's
    // backend top fetch. Combined with the optimistic local-me
    // override in _lbMaybeSimulate, this closes the race that left
    // the modal rendering Richie=0 even though the local snapshot
    // already had the corrected weekly total.
    if (metric === 'flights_climbed' && typeof lbRefreshFlightsThisWeekFromHealth === 'function') {
      try { await lbRefreshFlightsThisWeekFromHealth({ force: true }); } catch (_) {}
      try {
        if (typeof lbSubmitAllMetrics === 'function') {
          await lbSubmitAllMetrics();
          try { localStorage.setItem('hb_lb_last_submit', String(Date.now())); } catch (e) { _logSwallow('lb_last_submit:persist', e); }
        }
      } catch (_) {}
    }
    // W632 — force a fresh full-metric submit when OPENING the Collection Log board,
    // so the caller's CURRENT relic count lands server-side BEFORE the board fetches
    // (mirrors the flights path above). relics_collected submits ONLY via the full
    // lbSubmitAllMetrics batch — and no board-open triggered it, only the debounced
    // cold-launch/sync path did (which the D1 data shows never fired the batch with
    // relics). Root cause of "the Collection board is empty even though I have relics":
    // the count was simply never submitted. Non-debounced + awaited so the value is
    // persisted before the top fetch races it.
    if (metric === 'relics_collected' && typeof lbSubmitAllMetrics === 'function') {
      try {
        await lbSubmitAllMetrics();
        try { localStorage.setItem('hb_lb_last_submit', String(Date.now())); } catch (e) { _logSwallow('lb_last_submit:persist', e); }
      } catch (_) {}
    }

    // Default tab is always This Week.
    if (metric === 'rank_band') { await _lbRenderRankBandTab(metric); }
    else { await _lbRenderThisWeekTab(metric); }
  }

  // Tab click handler — switches active tab for the current open
  // metric, refreshes the visible list. Idempotent: clicking the
  // same tab is a no-op.
  // v3 Phase 1z.52 — added 'club-100k' tab routing.
  async function _lbSwitchTab(tab) {
    if (!_lbCurrentOpenMetric) return;
    if (tab !== 'this-week' && tab !== 'hof' && tab !== 'club-100k' && tab !== 'friends') return;
    if (_lbCurrentTab === tab) return;
    _lbCurrentTab = tab;
    // W321 — the last-week recap is This-Week-only; hide on every switch
    // (the This Week render re-populates it). Keeps it off HoF/100K/Friends.
    var _lwHide = document.getElementById('lb-lastweek-recap'); if (_lwHide) _lwHide.classList.add('hidden');
    // W386 — the pinned YOU footer is This-Week-only; hide it on every switch
    // (the This Week render re-populates it). Keeps it off HoF/100K/Friends.
    var _yfHide = document.getElementById('lb-you-footer'); if (_yfHide) { _yfHide.innerHTML = ''; _yfHide.classList.add('hidden'); }
    var _shYf = document.getElementById('lb-rank-sheet'); if (_shYf) _shYf.classList.remove('lb-has-youfoot');
    const tabsEl = document.getElementById('lb-rank-tabs');
    if (tabsEl) {
      const buttons = tabsEl.querySelectorAll('.lb-rank-tab');
      buttons.forEach(b => {
        const isActive = b.getAttribute('data-lb-tab') === tab;
        b.classList.toggle('is-active', isActive);
        b.setAttribute('aria-selected', isActive ? 'true' : 'false');
      });
    }
    if (tab === 'this-week') {
      await _lbRenderThisWeekTab(_lbCurrentOpenMetric);
    } else if (tab === 'hof') {
      await _lbRenderHofTab(_lbCurrentOpenMetric);
    } else if (tab === 'club-100k') {
      await _lbRender100kClubTab(_lbCurrentOpenMetric);
    } else if (tab === 'friends') {
      await _lbRenderFriendsTab(_lbCurrentOpenMetric);
    }
  }

  // ── Global Rankings Hub (v3 Phase 1z.130) ─────────────────────
  // Bottom-sheet chooser opened from the header World Rank card
  // (#steps-card). Houses the four ranking entry points (steps,
  // sleep, workout, flights). Tapping a row hands off to the
  // existing per-metric leaderboard sheet (#lb-rank-sheet) via
  // openLeaderboardRanking(metric). Hub paints from the local
  // snapshot only (lbGetSnapshot) so it opens instantly — no
  // backend round-trips here; those happen inside the per-metric
  // sheet on row tap, preserving the established fetch / sim
  // fallback / local-me override paths unchanged.
  function _lbHubFmt(n) {
    return (Number(n) || 0).toLocaleString('en-US');
  }
  function _lbHubBuildRow(metric, iconHtml, value, label, subHtml) {
    return '<button type="button" class="lb-hub-row" data-lb-metric="' + metric + '">' +
      '<span class="lb-hub-row-icon" aria-hidden="true">' + iconHtml + '</span>' +
      '<span class="lb-hub-row-body">' +
        '<span class="lb-hub-row-headline">' +
          '<span class="lb-hub-row-value">' + value + '</span>' +
          '<span class="lb-hub-row-label">' + label + '</span>' +
        '</span>' +
        (subHtml ? '<span class="lb-hub-row-sub">' + subHtml + '</span>' : '') +
      '</span>' +
      '<span class="lb-hub-row-chev" aria-hidden="true">›</span>' +
    '</button>';
  }
  function _lbHubRender() {
    const list = document.getElementById('lb-hub-list');
    if (!list) return;
    let snap;
    try { snap = lbGetSnapshot(); } catch (_) { snap = null; }
    snap = snap || {};
    const nightWord   = n => n === 1 ? 'night' : 'nights';
    const workoutWord = n => n === 1 ? 'day' : 'days';

    const walkIcon    = '<img src="assets/habit-icons/icon-walk.png" alt="" draggable="false" loading="lazy" decoding="async">';
    const sleepIcon   = '<img src="assets/habit-icons/icon-sleep.png" alt="" draggable="false" loading="lazy" decoding="async">';
    const workoutIcon = '<img src="assets/habit-icons/icon-strength.png" alt="" draggable="false" loading="lazy" decoding="async">';
    // Flights uses an inline SVG matching the design's BootIcon —
    // existing assets don't include a stair/flight glyph and we
    // want the hub to ship without an asset roundtrip.
    const flightsIcon = '<svg viewBox="0 0 24 24" width="20" height="20" aria-hidden="true">' +
      '<path d="M3 19 H8 V14 H13 V9 H18 V4 H21 V19 H3 Z" fill="none" stroke="#f5b842" stroke-width="1.4" stroke-linejoin="round"/>' +
    '</svg>';

    const stepsVal    = _lbHubFmt(snap.steps_last_7_days);
    const stepsSub    = (snap.best_7day_step_total > 0)
      ? 'Best week: <b>' + _lbHubFmt(snap.best_7day_step_total) + '</b>'
      : 'Best week: —';

    const sleepVal    = (snap.current_sleep_streak || 0);
    const sleepSub    = 'Best: <b>' + (snap.best_sleep_streak || 0) + ' ' + nightWord(snap.best_sleep_streak || 0) + '</b>';

    const workoutVal  = (snap.current_workout_streak || 0);
    const workoutSub  = 'Best: <b>' + (snap.best_workout_streak || 0) + ' ' + workoutWord(snap.best_workout_streak || 0) + '</b>';

    const flightsVal  = _lbHubFmt(snap.flights_this_week);
    const flightsSub  = (snap.best_flights_week > 0)
      ? 'Best week: <b>' + _lbHubFmt(snap.best_flights_week) + '</b>'
      : 'Best week: —';

    // W319 — "Hunters in your rank" cohort row (local power + rank label).
    let rbPower = 0, rbRankLabel = '';
    try { rbPower = Math.max(0, Math.round(_ascPlayerPower())); } catch (_) {}
    try { const _di = getRankDivisionInfo(totalPoints); rbRankLabel = (_di && _di.fullLabel) || ''; } catch (_) {}
    const rankIcon = '<svg viewBox="0 0 24 24" width="20" height="20" aria-hidden="true"><path d="M4 18 H20 M5 18 L7 9 L12 14 L17 7 L19 18 Z" fill="none" stroke="#f5b842" stroke-width="1.4" stroke-linejoin="round"/></svg>';
    const rbSub = rbRankLabel ? ('Your rank: <b>' + esc(rbRankLabel) + '</b>') : 'Your cohort';

    // W622 — the Collection Log race row. Gem glyph (inline SVG, matches the
    // flights/rank inline style); value = unique relics currently in the log.
    let clHave = 0, clTotal = 0;
    try { const _cl = _lbRelicsLogStats(); clHave = _cl.have; clTotal = _cl.total; } catch (_) {}
    const relicIcon = '<svg viewBox="0 0 24 24" width="20" height="20" aria-hidden="true">' +
      '<path d="M12 3 L19 9 L12 21 L5 9 Z M5 9 H19 M12 3 L9 9 L12 21 M12 3 L15 9 L12 21" fill="none" stroke="#f5b842" stroke-width="1.3" stroke-linejoin="round"/>' +
    '</svg>';
    const relicSub = 'Log: <b>' + clHave + ' / ' + clTotal + '</b>';

    list.innerHTML =
      _lbHubBuildRow('step_total',     walkIcon,    stepsVal,   'steps this week',           stepsSub) +
      _lbHubBuildRow('sleep_streak',   sleepIcon,   sleepVal,   'sleep streak · 7+ hr',      sleepSub) +
      _lbHubBuildRow('workout_streak', workoutIcon, workoutVal, 'workout streak · 30+ min',  workoutSub) +
      _lbHubBuildRow('flights_climbed', flightsIcon, flightsVal, 'flights this week',         flightsSub) +
      _lbHubBuildRow('relics_collected', relicIcon,  _lbHubFmt(clHave), 'relics collected',    relicSub) +   // W622
      _lbHubBuildRow('rank_band',      rankIcon,    _lbHubFmt(rbPower), 'hunters in your rank', rbSub);
  }
  // v3 Phase 1z.132 — parent-aware close. When a detail leaderboard
  // sheet is opened from a hub row tap, _lbDetailReturnTarget is set
  // to 'hub'; closeLeaderboardRanking() reads it and, if 'hub',
  // re-opens the Global Rankings Hub instead of exiting all the way
  // to the dashboard. Direct entry points (steps card click handler,
  // legacy lb-preview-list, deep links) leave the target null and
  // get the original "close all" behaviour.
  let _lbDetailReturnTarget = null; // null | 'hub'

  function openGlobalRankingsHub() {
    const sheet   = document.getElementById('lb-hub-sheet');
    const overlay = document.getElementById('lb-hub-overlay');
    if (!sheet || !overlay) return;
    // W331 — guest nudge instead of the hub.
    if (window.Auth && typeof Auth.isGuest === 'function' && Auth.isGuest()) {
      const _hl = document.getElementById('lb-hub-list');
      if (_hl) _hl.innerHTML = _guestJoinHtml('Join the rankings', 'Sign in to compete on the global leaderboards.');
      overlay.classList.remove('hidden');
      sheet.classList.remove('hidden');
      return;
    }
    try { _lbHubRender(); } catch (_) {}
    overlay.classList.remove('hidden');
    sheet.classList.remove('hidden');
    try {
      if (typeof _addHealthVerifyBreadcrumb === 'function') {
        _addHealthVerifyBreadcrumb('global-rankings-hub-open', {});
      }
    } catch (_) {}
  }
  function closeGlobalRankingsHub() {
    const sheet   = document.getElementById('lb-hub-sheet');
    const overlay = document.getElementById('lb-hub-overlay');
    if (sheet)   sheet.classList.add('hidden');
    if (overlay) overlay.classList.add('hidden');
    try {
      if (typeof _addHealthVerifyBreadcrumb === 'function') {
        _addHealthVerifyBreadcrumb('global-rankings-hub-close', {});
      }
    } catch (_) {}
  }
  try {
    window.openGlobalRankingsHub  = openGlobalRankingsHub;
    window.closeGlobalRankingsHub = closeGlobalRankingsHub;
  } catch (_) {}

  function closeLeaderboardRanking() {
    // v3 Phase 1z.36 — reset both metric + tab so concurrent fetches
    // that land after the sheet closes drop on the floor cleanly,
    // and so the next open always defaults to This Week.
    _lbCurrentOpenMetric = null;
    _lbCurrentTab = 'this-week';
    _lbArchReset();   // W658 — closing the sheet always exits archive mode
    const meBestEl = document.getElementById('lb-rank-mebest');
    if (meBestEl) meBestEl.classList.add('hidden');
    const sheet   = document.getElementById('lb-rank-sheet');
    const overlay = document.getElementById('lb-rank-overlay');
    if (sheet)   sheet.classList.add('hidden');
    if (overlay) overlay.classList.add('hidden');

    // v3 Phase 1z.132 — if this detail was opened from the Global
    // Rankings Hub, return to the hub instead of exiting all the way.
    // Direct entry points (e.g. the steps card click handler) leave
    // _lbDetailReturnTarget null and get the original "close all"
    // behaviour. Consume the flag before re-opening so subsequent
    // X-taps on the hub itself close cleanly.
    if (_lbDetailReturnTarget === 'hub') {
      _lbDetailReturnTarget = null;
      try {
        if (typeof _addHealthVerifyBreadcrumb === 'function') {
          _addHealthVerifyBreadcrumb('leaderboard-detail-return-to-hub', {});
        }
      } catch (_) {}
      try { openGlobalRankingsHub(); } catch (_) {}
    }
  }

  // W-next — unified profile-card data resolver. Sim bots (rows flagged
  // _sim) synthesize locally; real users fetch GET /v1/users/:alias/profile.
  // Returns the same shape either way (or null on failure). The card UI
  // (ClaudeDesign, pending) renders whatever this returns.
  async function _profileCardResolve(alias, simRow) {
    try {
      if (simRow && simRow._sim && window.SimulatedLeaderboard && typeof SimulatedLeaderboard.profile === 'function') {
        const dk = (typeof getDeviceLocalDate === 'function') ? getDeviceLocalDate() : '';
        const p = SimulatedLeaderboard.profile(alias, dk);
        if (p) return p;
      }
      if (window.Auth && typeof Auth.fetchPublicProfile === 'function') {
        const res = await Auth.fetchPublicProfile(alias);
        if (res && res.ok) return res;
      }
    } catch (_) {}
    return null;
  }
  try { window.__profileCardResolve = _profileCardResolve; } catch (_) {}

  // ── W278 — Player Profile Card (ClaudeDesign "The Medallion") ──────
  const _PC_RANK_COLORS = { E: '#8b5cf6', D: '#22d3ee', C: '#34d399', B: '#fbbf24', A: '#ef4444', S: '#e879f9', 'S+': '#facc15' };
  const _PC_TIER_COLORS = { iron: '#c8c6d8', teal: '#5eead4', violet: '#a78bfa', gold: '#f5b842' };
  function _renderProfileCard(data, isOwn) {
    const body = document.getElementById('pc-body');
    if (!body) return;
    if (!data) { body.innerHTML = '<div class="pc-skeleton">Profile unavailable — try again.</div>'; return; }
    const rankLetter = data.rankTier || ((data.rankLabel || '').trim().split(' ')[0]) || 'E';
    const rankColor = _PC_RANK_COLORS[rankLetter] || '#a78bfa';
    let titleName = null, tierColor = _PC_TIER_COLORS.iron;
    try {
      if (data.arenaTitle && typeof ARENA_TITLES !== 'undefined') {
        let tid = data.arenaTitle;
        if (typeof _ARENA_TITLE_LEGACY !== 'undefined' && _ARENA_TITLE_LEGACY[tid]) tid = _ARENA_TITLE_LEGACY[tid];
        const t = ARENA_TITLES.find((x) => x.id === tid);
        if (t) { titleName = t.name; tierColor = _PC_TIER_COLORS[t.tier] || tierColor; }
      }
    } catch (_) {}
    const avatar = data.avatarId || 'avatar-base.png';
    const num = (n) => (n != null ? Number(n).toLocaleString('en-US') : '0');
    const floor = Math.max(0, data.bestFloor | 0);
    const shard = titleName ? '<div class="pc-shard" style="--pc-tier:' + tierColor + '"><i></i><span>' + esc(titleName) + '</span></div>' : '';
    const flavor = data.verifiedStreakLabel ? '<div class="pc-flavor"><i></i><span>' + esc(data.verifiedStreakLabel) + '</span></div>' : '';
    // W369 — 100K Club prestige badge (gold), shown for real members (sims never qualify).
    // ClaudeDesign "Hunter Profile - 100K Club" (W373) — the 100K STEP CLUB
    // reads as a coveted gold SEAL (hex sigil + STEP CLUB / ELITE MEMBER +
    // shimmer), not a plain pill. Repeat qualifiers keep their \u00D7N acknowledgement.
    const clubBadge = (data.club100k && typeof data.club100k === 'object')
      ? '<div class="pc-club100k"><span class="pc-club100k-shine" aria-hidden="true"></span>' +
        '<span class="pc-club100k-seal" aria-hidden="true"><svg width="30" height="30" viewBox="0 0 30 30">' +
        '<path d="M15 1.5 27 8.5 27 21.5 15 28.5 3 21.5 3 8.5Z" fill="#1a1206" stroke="rgba(255,236,180,0.55)" stroke-width="1"/>' +
        '<path d="M15 5 23.2 9.8 23.2 19.2 15 24 6.8 19.2 6.8 9.8Z" fill="none" stroke="#f5b842" stroke-width="0.8" opacity="0.6"/>' +
        '</svg><span class="pc-club100k-seal-n">100K</span></span>' +
        '<span class="pc-club100k-txt"><span class="pc-club100k-t1">STEP\u00A0CLUB</span>' +
        '<span class="pc-club100k-t2">ELITE\u00A0MEMBER' + (((data.club100k.repeatCount | 0) > 1) ? '\u2002\u00B7\u2002\u00D7' + (data.club100k.repeatCount | 0) : '') + '</span></span></div>'
      : '';
    // W453 \u2014 Prestige flex on the tapped-name card (the "stunting on noobs"
    // payoff). Gold \u2726 stars + count, shown only for S+ hunters who have
    // prestiged. data.prestige comes straight from the public-profile-get read.
    const pcPrestige = (data.rankTier === 'S+' && (data.prestige | 0) > 0)
      ? '<div class="pc-prestige"><span class="pc-prestige-stars" aria-hidden="true">' + prestigeStars(data.prestige | 0) +
        '</span><span class="pc-prestige-lbl">PRESTIGE\u00A0' + (data.prestige | 0) + '</span></div>'
      : '';
    // W656 \u2014 free Founder marker on the hunter card (own + any viewed profile;
    // founderSeq is published into public_profile_summary and read cross-user).
    const _pcFounderSeq = (data.founderSeq | 0);
    const founderBadge = _pcFounderSeq > 0
      ? '<span class="pc-founder" title="Founder #' + _pcFounderSeq + '">\u2726\u00A0FOUNDER #' + _pcFounderSeq + '</span>'
      : '';
    // W706 — the member's equipped card background paints the profile hero.
    // Own card: an explicit local state (equip OR Basic) is sole truth; a friend's
    // card reads the published data.cardBg. setProperty/removeProperty (NOT a
    // style-attribute wipe) so the drag-dismiss gesture's inline transform and
    // any open/close animation styles survive the repaint.
    let _pcBg = data.cardBg || null;
    if (isOwn) { const _pcb = _cardBgLocal(); if (_pcb.set) _pcBg = _pcb.id; }
    const _pcArt = _pcBg ? _cardBgArt(_pcBg) : '';
    try {
      const _pcSheet = document.getElementById('pc-sheet');
      if (_pcSheet) {
        _pcSheet.classList.toggle('pc--painted', !!_pcArt);
        if (_pcArt) _pcSheet.style.setProperty('--lb-row-art', "url('" + _pcArt + "')");
        else _pcSheet.style.removeProperty('--lb-row-art');
      }
    } catch (_) {}
    body.innerHTML =
      '<div class="pc-hero"><div class="pc-med-wrap">' +
        '<div class="pc-med"><span class="pc-med-ring"></span>' +
          '<span class="pc-gem n"></span><span class="pc-gem e"></span><span class="pc-gem s"></span><span class="pc-gem w"></span>' +
          '<div class="pc-med-portrait"><img src="' + esc(_bustSrc(avatar) || avatar) + '" alt="" onerror="this.style.display=\'none\'"></div></div>' +   // W711 — bust portrait (fallback full-body)
        '<div class="pc-crest" style="--pc-rank:' + rankColor + '">' + esc(rankLetter) + '</div>' +
      '</div><div class="pc-med-floor"></div>' +
      (isOwn ? '<button class="pc-skintag" type="button" data-wardrobe="1"><i></i><span>CHANGE LOOK \u203A</span></button>' : '<div class="pc-skintag"><i></i><span>DEFAULT SKIN</span></div>') + '</div>' +
      '<div class="pc-identity"><div class="pc-alias">' + esc(data.alias || '—') + '</div><div class="pc-idrow">' + shard + clubBadge + pcPrestige + founderBadge + '</div></div>' +
      '<div class="pc-stats"><div class="pc-grid">' +
        '<div class="pc-stat"><span class="k">POWER</span><span class="v gold">' + num(data.power) + '</span></div>' +
        '<div class="pc-stat"><span class="k">BOSS KILLS</span><span class="v">' + num(data.bossesSlain) + '</span></div>' +
        '<div class="pc-stat"><span class="k">AVG STEPS / DAY</span><span class="v">' + num(data.avgStepsPerDay) + '</span></div>' +
        '<div class="pc-stat"><span class="k">ULTRA-RARE DROPS</span><span class="v violet">' + num(data.ultraRareDrops) + '</span></div>' +
      '</div><div class="pc-floor"><div class="pc-floor-top"><span class="k">BEST FLOOR · THE ASCENT</span>' +
        '<span class="v">' + floor + '<small> / 100</small></span></div>' +
        '<div class="pc-floor-bar"><i style="width:' + Math.min(100, floor) + '%"></i></div></div></div>' +
      // W444 — Arena Rating row (ClaudeDesign Hunter Profile refresh): the hunter's ranked PvP
      // standing, server-authoritative. Present only for PLACED hunters (the backend returns
      // data.arena = null otherwise → row hidden). Tap → the ranked ladder.
      ((data.arena && data.arena.elo != null) ? _pcArenaRowHtml(data.arena) : '') +
      flavor +
      // W440 — "Duel a Friend's Echo": only for an accepted friend who has published a loadout
      // (canEcho). Unrated AI mirror; the server re-verifies the friendship + runs it ranked:false.
      ((!isOwn && !data._sim && !!data.canEcho && _pcIsAcceptedFriend(data.alias))
        ? '<button class="pc-echo-btn" type="button" data-pcecho="1" data-pcecho-alias="' + esc(data.alias || '') + '" data-pcecho-avatar="' + esc(data.avatarId || '') + '">' +
            '<span class="pc-echo-ic">' + _PVP_ECHO_SIG + '</span>' +
            '<span class="pc-echo-tx"><b>Spar their Echo</b><i>Unrated · an AI mirror of their loadout</i></span>' +
            '<span class="pc-echo-go">›</span></button>'
        : '') +
      '<div class="pc-prov"><span>Tapped from the global leaderboard · standings update in real time</span></div>';
  }
  // True iff `alias` is one of my accepted friends (per the warm friends cache). Conservative: an
  // empty/cold cache returns false, so the Spar-Echo button never shows on a stranger's card. The
  // server is the real friendship gate; this just keeps the button honest in the UI.
  function _pcIsAcceptedFriend(alias) {
    const a = String(alias || '').trim().toLowerCase();
    if (!a) return false;
    try {
      const list = (_friendsCache && Array.isArray(_friendsCache.friends)) ? _friendsCache.friends : [];
      return list.some(function (f) { return f && typeof f.alias === 'string' && f.alias.trim().toLowerCase() === a; });
    } catch (_) { return false; }
  }
  // W444 — the Arena Rating row for the Hunter Profile card. The backend serves only { elo, global }
  // (server-authoritative from pvp_ratings); everything else — tier name, division, progress, points
  // to the next tier — is derived here from ELO via the same tables the Arena hub uses, so the row
  // stays consistent with the live ladder.
  function _pcArenaRowHtml(arena) {
    const elo = Math.max(0, arena.elo | 0);
    const tier = _pvpTier(elo);
    const key = String(tier.name || 'silver').toLowerCase();
    const band = _PVP_TIER_BR[key] || [0, null];
    const min = band[0], max = band[1];
    const ord = _PVP_TIER_ORD[key] || 1;
    const nextName = _PVP_TIER_NEXT[key] || null;
    const pct = (max != null) ? Math.max(6, Math.min(100, ((elo - min) / (max - min)) * 100)) : 100;
    const toNext = (max != null) ? Math.max(0, (max + 1) - elo) : 0;
    const tc = tier.color || '#fbbf24';
    const globalTxt = (arena.global != null && arena.global > 0)
      ? '<span class="pc-arena-global">#' + (arena.global | 0) + ' <i>GLOBAL</i></span>' : '';
    const toNextTxt = (nextName && max != null)
      ? toNext.toLocaleString('en-US') + ' TO ' + esc(nextName.toUpperCase())
      : 'PEAK TIER';
    return '<button type="button" class="pc-arena" data-pc-arena="1" style="--at:' + tc + '">' +
      '<img class="pc-arena-crest" src="assets/pvp-tiers/pvp-tier-' + esc(key) + '.svg" alt="" onerror="this.style.display=\'none\'">' +
      '<span class="pc-arena-body">' +
        '<span class="pc-arena-top"><span class="k">ARENA RATING · SEASON 1</span>' + globalTxt + '</span>' +
        '<span class="pc-arena-mid"><span class="tier">' + esc(tier.name) + '</span><span class="sub">Tier ' + ord + '</span>' +
          '<span class="elo">' + elo.toLocaleString('en-US') + '<i> ELO</i></span></span>' +
        '<span class="pc-arena-bar"><i style="width:' + pct.toFixed(0) + '%"></i></span>' +
        '<span class="pc-arena-tonext">' + toNextTxt + '</span>' +
      '</span>' +
      '<span class="pc-arena-chev">›</span>' +
    '</button>';
  }
  let _pcOpenAlias = null;   // W633 — the alias of the currently-open profile card (guards the late friends repaint)
  async function _openProfileCard(alias, simRow) {
    const ov = document.getElementById('pc-overlay'), sh = document.getElementById('pc-sheet'), body = document.getElementById('pc-body');
    if (!ov || !sh || !body) return;
    // W706 — clear any PREVIOUS card's painted background before the skeleton so a
    // fast close+reopen never flashes the last hunter's art (the paint is re-applied
    // by _renderProfileCard once THIS card's data resolves).
    try { sh.classList.remove('pc--painted'); sh.style.removeProperty('--lb-row-art'); } catch (_) {}
    body.innerHTML = '<div class="pc-skeleton">Summoning…</div>';
    ov.classList.remove('hidden'); sh.classList.remove('hidden');
    _pcOpenAlias = alias;
    let data = null;
    try { data = await _profileCardResolve(alias, simRow); } catch (_) {}
    if (sh.classList.contains('hidden')) return;   // closed before the fetch landed
    // W633 — render NOW off the profile fetch alone. The friends fetch below used to be a SERIAL
    // blocking await here purely to gate the optional "Spar their Echo" button — but GET /v1/friends
    // is an N+1 (1 + F sequential D1 reads), so it dominated the card-open latency and got WORSE with
    // friend count (the cold-cache first open of a session was the laggy one). Render first, warm
    // friends in the background, repaint ONCE only if this hunter is an accepted friend AND the card
    // is still theirs (a fast close+reopen of another card must not repaint stale data).
    _renderProfileCard(data, _pcIsOwnAlias(alias));
    if (!_friendsCache && !_pcIsOwnAlias(alias) && !(data && data._sim) && window.Auth && Auth.fetchFriends) {
      Promise.resolve(Auth.fetchFriends()).then(function (fr) {
        if (!fr || !fr.ok) return;
        _friendsCache = fr;
        try {
          if (_pcOpenAlias === alias && !sh.classList.contains('hidden') && _pcIsAcceptedFriend(alias)) {
            _renderProfileCard(data, _pcIsOwnAlias(alias));   // reveal the Spar-Echo button a beat later
          }
        } catch (_) {}
      }, function () {});
    }
  }
  function _closeProfileCard() {
    const ov = document.getElementById('pc-overlay'), sh = document.getElementById('pc-sheet');
    if (ov) ov.classList.add('hidden');
    if (sh) sh.classList.add('hidden');
  }
  try { window.__openProfileCard = _openProfileCard; } catch (_) {}

  // ── W279 — The Wardrobe (avatar skins, Layer 1: free looks + equip) ──
  function _renderWardrobe() {
    const body = document.getElementById('wd-body');
    if (!body) return;
    const equipped = getEquippedSkin();           // '' = class default
    const classDef = _classDefaultAvatar();
    const eq = AVATAR_SKINS.find((x) => (x.file || '') === equipped);
    const tiles = AVATAR_SKINS.map((sk) => {
      const img = sk.klass ? classDef : sk.file;
      const isEq = (sk.file || '') === equipped;
      return '<div class="wd-tile' + (isEq ? ' is-equipped' : '') + '" data-skin="' + esc(sk.file) + '">' +
        (isEq ? '<span class="wd-tile-tick">\u2713</span>' : '') +
        (sk.klass ? '<span class="wd-tile-badge">CLASS</span>' : '') +
        '<div class="wd-tile-av"><img src="' + esc(img) + '" alt="" onerror="this.style.display=\'none\'"></div>' +
        '<span class="wd-tile-name">' + esc(sk.name) + '</span></div>';
    }).join('');
    // W297 — IAP-aware shop tiles. When IAP is off (default) every tile shows
    // SOON and owned is always empty, so this renders identically to before.
    const iapOn = !!(window.Auth && Auth.iapAvailable && Auth.iapAvailable());
    const shop = PREMIUM_SKINS.map((sk) => {
      const owned = isSkinOwned(sk.id);
      const isEqP = owned && (sk.file || '') === equipped;
      let badge;
      if (isEqP)        badge = '<span class="wd-tile-tick">✓</span>';
      else if (owned)   badge = '<span class="wd-tile-badge">OWNED</span>';
      // W625 — buyable tiles show the LIVE localized price ('$4.99'); 'BUY' is the
      // brief fallback until _refreshSkinPrices() lands. SOON stays for the dormant
      // (IAP-off) state — a price would imply a purchasability the app can't honor.
      else if (iapOn) { const _sp = _iapPrices[_skinProductId(sk.id)];
                        badge = '<span class="wd-tile-lockbadge wd-tile-buy">' + (_sp ? esc(_sp) : 'BUY') + '</span>'; }
      else              badge = '<span class="wd-tile-lockbadge">SOON</span>';
      return '<div class="wd-tile wd-tile--premium wd-tile--' + sk.rarity + (isEqP ? ' is-equipped' : '') +
        '" data-premium="' + esc(sk.id) + '"' + (owned ? ' data-owned="1"' : '') + '>' +
        badge +
        '<div class="wd-tile-av"><img src="' + esc(sk.file) + '" alt="" loading="lazy" onerror="this.style.display=\'none\'"></div>' +
        '<span class="wd-tile-name">' + esc(sk.name) + '</span>' +
        '<span class="wd-tile-rarity">' + (sk.rarity || '').toUpperCase() + '</span></div>';
    }).join('');
    body.innerHTML =
      '<div class="wd-hero"><div class="pc-med"><span class="pc-med-ring"></span>' +
        '<span class="pc-gem n"></span><span class="pc-gem e"></span><span class="pc-gem s"></span><span class="pc-gem w"></span>' +
        '<div class="pc-med-portrait"><img src="' + esc(_bustSrc(getAvatarSrc()) || getAvatarSrc()) + '" alt="" onerror="this.style.display=\'none\'"></div></div></div>' +   // W711 — bust portrait (fallback full-body)
      '<div class="wd-hero-name">' + esc(eq ? eq.name : 'Your Class') + '</div><div class="wd-hero-sub">Equipped Look</div>' +
      '<div class="wd-section-label"><span>YOUR LOOKS</span><span class="rule"></span></div>' +
      '<div class="wd-grid">' + tiles + '</div>' +
      _cardBgSectionHtml() +   // W706 — member card-background picker
      '<div class="wd-section-label"><span>SHOP</span><span class="rule"></span></div>' +
      '<div class="wd-grid wd-shop">' + shop + '</div>' +
      // W621 — pre-purchase Founder teaser in the shop. Gated exactly like the other
      // prompts (live IAP + non-owner) so it stays dormant until go-live and never
      // shows to an owned Founder. Tap → the Founder sheet (data-wd-founder branch
      // in the wd-body delegation).
      ((_founderIapReady() && !_founderOwned())
        ? '<button type="button" class="wd-founder-teaser" data-wd-founder="1">' +
            '<span class="ft-glyph" aria-hidden="true">✦</span>' +
            '<span class="ft-text">' +
              '<span class="ft-title">Awakened Premium · <b>' + esc(_premiumPriceStr('monthly')) + '</b>/mo</span>' +
              '<span class="ft-benefit">UNLIMITED ASCENT ATTEMPTS · NO ENTRANCE FEES</span>' +   // 2 items — 3 ellipsized at 393px
            '</span>' +
            '<span class="ft-chev" aria-hidden="true">›</span>' +
          '</button>'
        : '') +
      '<div class="wd-shop-note">' + (iapOn ? 'Tap to preview, buy, or equip. Restore purchases from Settings.' : 'Premium skins — purchasable in a future update.') + '</div>';
  }
  // W706 — the CARD BACKGROUND picker section (handoff-21 section 05). Tiles show
  // the real art; states = equipped / unlocked (tap to equip) / locked-by-
  // achievement (shows the requirement) / locked-for-non-members (MEMBERS chip →
  // the Premium paywall). "Basic" clears back to the plain card. The server
  // re-validates membership at write time — this gate is UX, not security.
  function _cardBgSectionHtml() {
    const isMember = _founderOwned();
    const eq = _cardBgEquipped();
    const tiles = CARD_BG_CATALOG.map(function (bg) {
      const unlocked = _cardBgUnlocked(bg.id);
      const isEq = eq === bg.id;
      const usable = isMember && unlocked;
      let badge = '';
      if (isEq) badge = '<span class="wd-tile-tick">✓</span>';
      else if (!isMember) badge = '<span class="cbg-chip cbg-chip--members">✦ MEMBERS</span>';
      else if (!unlocked) badge = '<span class="cbg-chip cbg-chip--locked">🔒</span>';
      return '<div class="cbg-tile' + (isEq ? ' is-equipped' : '') + (usable ? '' : ' is-locked') + '"' +
        ' data-cbg="' + esc(bg.id) + '" data-cbg-usable="' + (usable ? '1' : '0') + '">' +
        '<div class="cbg-art" style="background-image:url(\'' + _cardBgArt(bg.id) + '\')"></div>' +
        badge +
        '<span class="cbg-name">' + esc(bg.name) + '</span>' +
        '<span class="cbg-need">' + (unlocked ? 'EARNED' : esc(bg.need.toUpperCase())) + '</span>' +
      '</div>';
    }).join('');
    const basic = '<div class="cbg-tile cbg-tile--basic' + (eq === null ? ' is-equipped' : '') + '" data-cbg="" data-cbg-usable="1">' +
      (eq === null ? '<span class="wd-tile-tick">✓</span>' : '') +
      '<div class="cbg-art cbg-art--basic"></div>' +
      '<span class="cbg-name">Basic</span><span class="cbg-need">DEFAULT</span></div>';
    return '<div class="wd-section-label"><span>CARD BACKGROUND</span><span class="rule"></span></div>' +
      (isMember ? '' :
        '<div class="cbg-member-note">Card backgrounds are a <b>member</b> perk — earn them with achievements, wear them on every leaderboard.</div>') +
      '<div class="cbg-grid">' + basic + tiles + '</div>';
  }

  // W283 — premium skin preview lightbox (try-before-you-buy on a locked skin).
  function _wdPreviewSkin(id) {
    const sk = PREMIUM_SKINS.find((x) => x.id === id);
    const ov = document.getElementById('wd-preview-overlay');
    if (!sk || !ov) return;
    const img = document.getElementById('wd-preview-img'); if (img) img.src = sk.file;
    const nm = document.getElementById('wd-preview-name'); if (nm) nm.textContent = sk.name;
    const rar = document.getElementById('wd-preview-rarity');
    if (rar) { rar.textContent = (sk.rarity || '').toUpperCase(); rar.className = 'wd-preview-rarity wd-preview-rarity--' + (sk.rarity || ''); }
    const bl = document.getElementById('wd-preview-blurb'); if (bl) bl.textContent = sk.blurb || '';
    ov.classList.remove('hidden');
  }
  function _wdClosePreview() { const ov = document.getElementById('wd-preview-overlay'); if (ov) ov.classList.add('hidden'); }

  function openWardrobe() {
    const ov = document.getElementById('wd-overlay'), sh = document.getElementById('wd-sheet');
    if (!ov || !sh) return;
    _hydrateOwnedSkinsFromCache();        // W297 — instant display from cache
    _renderWardrobe();
    ov.classList.remove('hidden'); sh.classList.remove('hidden');
    try { refreshSkinEntitlements(); } catch (_) {}   // W297 — revalidate ownership from backend
    try { _maybeReconcileEntitlements(); } catch (_) {}  // W637 — self-heal a lost-webhook grant (throttled 1/day)
    try { _refreshIapPrices(); } catch (_) {}          // W625 — live localized skin + Founder prices (no-op while dormant)
  }
  function closeWardrobe() {
    const ov = document.getElementById('wd-overlay'), sh = document.getElementById('wd-sheet');
    if (ov) ov.classList.add('hidden');
    if (sh) sh.classList.add('hidden');
  }
  function _equipSkin(file) {
    setEquippedSkin(file || '');
    _renderWardrobe();
    const src = getAvatarSrc();
    try { const home = document.getElementById('sc-avatar-img'); if (home) { home.src = src; _lastAvatarSrc = src; } } catch (_) {}
    try { const sh = document.getElementById('pc-sheet'); if (sh && !sh.classList.contains('hidden')) { const im = sh.querySelector('.pc-med-portrait img'); if (im) im.src = (_bustSrc(src) || src); } } catch (_) {}   // W711 — bust portrait (fallback full-body)
    try { _maybeSubmitPublicRankSummary('avatar-change'); } catch (_) {}   // sync avatar_id
  }
  try { window.__openWardrobe = openWardrobe; } catch (_) {}


  // W655 — legacy helper names, now PREMIUM semantics: _founderIapReady() = the
  // priced paywall may be shown; _founderOwned() = the user is an active member.
  function _founderIapReady() {
    try { return !!(window.Auth && Auth.iapAvailable && Auth.iapAvailable() && typeof Auth.purchasePremium === 'function'); }
    catch (_) { return false; }
  }
  function _founderOwned() {
    try { return !!(window.Auth && typeof Auth.isMember === 'function' && Auth.isMember()); } catch (_) { return false; }
  }
  // W342 — shared Founder-prompt throttle. One mechanism for every value-peak
  // surface (rank-up, perfect-day) so a user never sees two upsells stacked.
  // Dormant while IAP is off: _founderIapReady() is false until the owner flips
  // IAP_ENABLED, so this returns false and nothing renders. Presentation-only.
  let _founderPromptsThisSession = 0;
  const FOUNDER_PROMPT_MIN_INTERVAL_MS = 3600000; // 1h minimum between any two prompts
  function _canShowFounderPrompt() {
    try {
      if (_founderOwned()) return false;              // already a member — nothing to pitch
      if (!_founderIapReady()) return false;
      if (_founderPromptsThisSession >= 1) return false;
      const last = parseInt(localStorage.getItem('hb_founder_last_prompt_ms') || '0', 10) || 0;
      if (Date.now() - last < FOUNDER_PROMPT_MIN_INTERVAL_MS) return false;
      return true;
    } catch (_) { return false; }
  }
  function _recordFounderPrompt() {
    try { localStorage.setItem('hb_founder_last_prompt_ms', String(Date.now())); } catch (_) {}
    _founderPromptsThisSession++;
  }
  // W651 — the localized premium prices (fallback to the anchor prices).
  function _premiumPriceStr(tier) {
    try {
      const pid = Auth.PREMIUM_PRODUCTS[tier];
      return _iapPrices[pid] || (tier === 'yearly' ? '$39.99' : '$4.99');
    } catch (_) { return tier === 'yearly' ? '$39.99' : '$4.99'; }
  }
  // W651/W655 — the "founder" sheet is now the Awakened Premium paywall (the
  // only paid tier). One clean paywall: active members see a receipt; everyone
  // else sees the monthly/yearly offer. Apple 3.1.2 requires the paywall itself
  // to disclose price+period, auto-renewal, and carry working Terms of Use +
  // Privacy Policy links + a Restore control — that's the fineprint/restore
  // block at the bottom; don't trim it.
  function _renderFounder() {
    const body = document.getElementById('founder-body');
    if (!body) return;
    const mo = _premiumPriceStr('monthly'), yr = _premiumPriceStr('yearly');
    const ready = _founderIapReady();
    // Active member -> receipt, no pitch.
    if (_founderOwned()) {
      body.innerHTML =
        '<div class="founder-hero"><div class="founder-crest" aria-hidden="true"><span class="founder-crest-spark">✦</span></div>' +
          '<div class="founder-title">Awakened Premium</div>' +
          '<div class="founder-tagline">You’re a member. Thank you.</div></div>' +
        '<div class="founder-owned">✓ Membership active</div>' +
        '<div class="founder-fineprint">Manage or cancel anytime in Settings → Apple ID → Subscriptions.</div>';
      return;
    }
    const soon = ready ? '' : ' founder-cta--soon';
    const benefit = function (glyph, title, bodyTxt) {
      return '<div class="founder-benefit"><span class="founder-benefit-glyph" aria-hidden="true">' + glyph + '</span>' +
        '<span class="founder-benefit-text"><span class="founder-benefit-title">' + esc(title) + '</span>' +
        '<span class="founder-benefit-body">' + esc(bodyTxt) + '</span></span></div>';
    };
    body.innerHTML =
      '<div class="founder-hero">' +
        '<div class="founder-crest" aria-hidden="true"><span class="founder-crest-spark">✦</span></div>' +
        '<div class="founder-title">Awakened Premium</div>' +
        '<div class="founder-tagline">The full membership. Cancel anytime.</div>' +
      '</div>' +
      '<div class="founder-benefits">' +
        benefit('⚔', 'Unlimited co-op hunts', 'No entrance fees, no 3-hunt limit — summon and answer freely.') +
        benefit('∞', 'Unlimited Ascent attempts', 'The daily 2-life cap is lifted — the tower never closes on you.') +
        benefit('✦', 'Member status', 'Every future membership perk, the moment it ships.') +
      '</div>' +
      '<div class="founder-cta-wrap">' +
        '<button type="button" class="founder-cta' + soon + '" data-premium-buy="monthly">' +
          '<span class="founder-cta-spark" aria-hidden="true">✦</span>Monthly — ' + esc(mo) + '/month</button>' +
        '<button type="button" class="founder-cta' + soon + '" data-premium-buy="yearly" style="margin-top:10px">' +
          '<span class="founder-cta-spark" aria-hidden="true">✦</span>Yearly — ' + esc(yr) + '/year · SAVE 33%</button>' +
        '<button type="button" class="founder-restore" data-premium-restore>Restore Purchases</button>' +
      '</div>' +
      '<div class="founder-fineprint" style="margin-top:12px">Awakened Premium is ' + esc(mo) + '/month or ' + esc(yr) + '/year. ' +
        'Payment is charged to your Apple ID. It renews automatically unless cancelled at least 24 hours before the ' +
        'end of the current period; manage or cancel anytime in Settings → Apple ID → Subscriptions.</div>' +
      '<div class="founder-fineprint" style="margin-top:8px">' +
        '<a href="#" data-ext-url="https://www.apple.com/legal/internet-services/itunes/dev/stdeula/" style="color:inherit;text-decoration:underline">Terms of Use</a>' +
        ' · ' +
        '<a href="#" data-ext-url="' + esc(AWAKENED_PRIVACY_POLICY_URL) + '" style="color:inherit;text-decoration:underline">Privacy Policy</a>' +
      '</div>';
  }

  // W651 — buy a premium subscription from the membership sheet.
  let _premiumBuyBusy = false;
  async function _premiumBuy(tier) {
    if (_premiumBuyBusy) return;
    if (!(window.Auth && typeof Auth.purchasePremium === 'function' && Auth.iapAvailable && Auth.iapAvailable())) {
      try { if (typeof showHabitToast === 'function') showHabitToast('Premium unlocks soon — thank you for the support.'); } catch (_) {}
      return;
    }
    _premiumBuyBusy = true;
    const btn = document.querySelector('[data-premium-buy="' + tier + '"]');
    if (btn) { btn.disabled = true; btn.style.opacity = '0.6'; }
    let r;
    try { r = await Auth.purchasePremium(Auth.PREMIUM_PRODUCTS[tier]); } catch (_) { r = { ok: false, code: 'ERROR' }; }
    _premiumBuyBusy = false;
    if (r && r.ok && r.member) {
      try { if (typeof showHabitToast === 'function') showHabitToast('✦ Welcome to Awakened Premium.'); } catch (_) {}
      try { if (typeof playSfx === 'function') playSfx('boss_victory'); } catch (_) {}
      _renderFounder();
    } else if (r && r.ok) {
      // W652 — flow completed but the entitlement hasn't landed yet (webhook/
      // reconcile lag or an already-subscribed restore that found nothing).
      // Honest message, no fanfare — the launch-time refresh picks it up.
      try { if (typeof showHabitToast === 'function') showHabitToast('Purchase received — your membership will appear shortly.'); } catch (_) {}
      _renderFounder();
    } else if (r && r.code === 'CANCELLED') {
      _renderFounder();   // re-enable the buttons, no noise
    } else if (r && r.code === 'NOT_SIGNED_IN') {
      // W790 — guest sessions have no backend user to attach the subscription
      // to (configurePurchases needs a real Apple sign-in). "Purchase failed"
      // read as a payments bug to a tester; it's a sign-in prerequisite.
      try { if (typeof showHabitToast === 'function') showHabitToast('Sign in with Apple first — a guest session can’t hold a membership'); } catch (_) {}
      _renderFounder();
    } else {
      try { if (typeof showHabitToast === 'function') showHabitToast('Purchase failed. Please try again.'); } catch (_) {}
      _renderFounder();
    }
  }
  // W441 — show/hide the Settings "Become a Founder" entry based on whether IAP is actually live.
  // While IAP is dormant (IAP_ENABLED=false), the entry stays hidden so no priced/dead purchase
  // surface is reachable — the canonical App Store Guideline 2.1 rejection. Re-checked on every
  // Settings open (handles RevenueCat readiness arriving async once IAP is enabled).
  function _syncFounderEntry() {
    try {
      const row = document.getElementById('settings-founder-row');
      if (row) row.style.display = (_founderIapReady() || _founderOwned()) ? '' : 'none';
    } catch (_) {}
  }
  function openFounder() {
    // App Store 2.1 — never present the priced paywall unless IAP is live; a
    // member may still open it to see their receipt. Re-checked on every open.
    if (!_founderIapReady() && !_founderOwned()) return;
    const ov = document.getElementById('founder-overlay'), sh = document.getElementById('founder-sheet');
    if (!ov || !sh) return;
    _renderFounder();
    ov.classList.remove('hidden'); sh.classList.remove('hidden');
    try { _refreshIapPrices(); } catch (_) {}   // localize the prices (repaints on land)
  }
  function closeFounder() {
    const ov = document.getElementById('founder-overlay'), sh = document.getElementById('founder-sheet');
    if (ov) ov.classList.add('hidden');
    if (sh) sh.classList.add('hidden');
  }
  // W655 — Restore Purchases from the Premium paywall (Apple requires it for subs).
  // Restore pushes Apple's receipt to RevenueCat; reconcile then adopts the
  // subscription horizon from RC's REST record before the sheet re-renders.
  function _premiumRestore() {
    if (!(window.Auth && Auth.iapAvailable && Auth.iapAvailable())) {
      if (typeof showHabitToast === 'function') showHabitToast('Restore is available once purchases are live.');
      return;
    }
    try {
      Promise.resolve(Auth.restorePurchases()).then(function () {
        var _rec = (window.Auth && typeof Auth.reconcileEntitlements === 'function') ? Auth.reconcileEntitlements() : null;
        Promise.resolve(_rec)
          .then(function () { return (typeof refreshSkinEntitlements === 'function') ? refreshSkinEntitlements() : null; })
          .then(function () { _renderFounder(); if (typeof showHabitToast === 'function') showHabitToast('Purchases restored.'); });
      }, function () { if (typeof showHabitToast === 'function') showHabitToast('Nothing to restore.'); });
    } catch (_) {}
  }

  try { window.__openFounder = openFounder; } catch (_) {}

  // ── W330 — Guest deferred sign-in claim ──────────────────────────
  // A guest (GUEST_STUB) plays the full local loop; here they sign in with
  // Apple to claim a permanent account. completeSignIn overwrites the guest
  // hb_user with the real one; on reload CloudSync.maybeSyncOnInit ADOPTS the
  // guest's local state as the cloud baseline (no merge code). Self-contained
  // (authorize + claim back-to-back, so the Apple token TTL is a non-issue).
  function _guestClaimRenderSuggestions(suggested, nameIn, box) {
    if (!box) return;
    box.innerHTML = '';
    if (!Array.isArray(suggested) || !suggested.length) { box.style.display = 'none'; return; }
    const label = document.createElement('div');
    label.className = 'signin-suggestions-label';
    label.textContent = 'Try one of these:';
    box.appendChild(label);
    suggested.forEach(function (s) {
      const chip = document.createElement('button');
      chip.type = 'button';
      chip.className = 'signin-suggestion-chip';
      chip.textContent = s;
      chip.addEventListener('click', function () { if (nameIn) { nameIn.value = s; try { nameIn.focus(); } catch (_) {} } });
      box.appendChild(chip);
    });
    box.style.display = 'block';
  }
  function openGuestClaim() {
    const ov = document.getElementById('guest-claim-overlay');
    if (!ov) return;
    const nameIn = document.getElementById('guest-claim-name');
    if (nameIn && !nameIn.value) {
      let pre = '';
      try { pre = localStorage.getItem('hb_name') || ''; } catch (_) {}
      if (!pre) { try { pre = (window.Auth && Auth.getPendingGivenName && Auth.getPendingGivenName()) || ''; } catch (_) {} }
      nameIn.value = pre;
    }
    const err = document.getElementById('guest-claim-error'); if (err) err.textContent = '';
    const sug = document.getElementById('guest-claim-suggestions'); if (sug) { sug.innerHTML = ''; sug.style.display = 'none'; }
    ov.classList.remove('hidden');
  }
  function closeGuestClaim() {
    const ov = document.getElementById('guest-claim-overlay'); if (ov) ov.classList.add('hidden');
  }
  try { window.__openGuestClaim = openGuestClaim; } catch (_) {}
  function _wireGuestClaimOnce() {
    const ov = document.getElementById('guest-claim-overlay');
    if (!ov || ov.getAttribute('data-wired') === '1') return;
    ov.setAttribute('data-wired', '1');
    const appleBtn  = document.getElementById('guest-claim-apple');
    const cancelBtn = document.getElementById('guest-claim-cancel');
    const nameIn    = document.getElementById('guest-claim-name');
    const errEl     = document.getElementById('guest-claim-error');
    const sugBox    = document.getElementById('guest-claim-suggestions');
    if (cancelBtn) cancelBtn.addEventListener('click', closeGuestClaim);
    if (appleBtn) appleBtn.addEventListener('click', async function () {
      const Auth = window.Auth;
      const name = (nameIn ? nameIn.value : '').trim();
      if (errEl) errEl.textContent = '';
      if (sugBox) { sugBox.innerHTML = ''; sugBox.style.display = 'none'; }
      if (!Auth || typeof Auth.validateAlias !== 'function' || !Auth.validateAlias(name)) {
        if (errEl) errEl.textContent = '3–20 chars · letters, numbers, spaces, _ and - only.';
        return;
      }
      if (!Auth.isNative || !Auth.isNative()) {
        if (errEl) errEl.textContent = 'Sign in with Apple is only available in the iOS app.';
        return;
      }
      appleBtn.disabled = true;
      try {
        const resp = await Auth.signInWithApple();
        if (!resp) { appleBtn.disabled = false; return; }   // user cancelled
        let result;
        try { result = await Auth.completeSignIn(name); } catch (_) { result = { ok: false, code: 'NETWORK' }; }
        if (result && result.ok) {
          // Real account written; the guest hb_user is replaced. Reload so
          // CloudSync.maybeSyncOnInit adopts the local state as the baseline.
          window.location.reload();
          return;
        }
        const code = result && result.code;
        if (code === 'ALIAS_TAKEN') {
          if (errEl) errEl.textContent = 'That name is taken — pick another.';
          _guestClaimRenderSuggestions(result.suggested, nameIn, sugBox);
        } else if (code === 'NO_PENDING_TOKEN' || code === 'APPLE_TOKEN_INVALID') {
          if (errEl) errEl.textContent = 'Sign-in expired. Tap Sign in with Apple again.';
        } else {
          if (errEl) errEl.textContent = (result && result.reason) || 'Could not sign in. Try again.';
        }
        appleBtn.disabled = false;
      } catch (e) {
        if (e && e.message === 'NATIVE_ONLY') { if (errEl) errEl.textContent = 'Sign in with Apple is only available in the iOS app.'; }
        else { if (errEl) errEl.textContent = 'Sign in failed — please try again.'; }
        appleBtn.disabled = false;
      }
    });
  }
  function _pcIsOwnAlias(alias) {
    try { const me = lbGetMyAlias(); return !!(me && alias && me.toLowerCase() === String(alias).toLowerCase()); } catch (_) { return false; }
  }

  function setupLeaderboardPreview() {
    const list = document.getElementById('lb-preview-list');
    if (list) {
      list.addEventListener('click', e => {
        const card = e.target.closest('[data-lb-metric]');
        if (!card) return;
        openLeaderboardRanking(card.getAttribute('data-lb-metric'));
      });
    }
    // v3 Phase 1z.130 — Global Rankings Hub wiring. The hub list
    // uses the same data-lb-metric attribute convention so taps
    // route through the same openLeaderboardRanking() path that
    // the (now-removed) Stats-tab preview list used.
    const hubList = document.getElementById('lb-hub-list');
    if (hubList && hubList.getAttribute('data-wired') !== '1') {
      hubList.setAttribute('data-wired', '1');
      hubList.addEventListener('click', e => {
        const row = e.target.closest('[data-lb-metric]');
        if (!row) return;
        const metric = row.getAttribute('data-lb-metric');
        try {
          if (typeof _addHealthVerifyBreadcrumb === 'function') {
            _addHealthVerifyBreadcrumb('global-rankings-hub-row-tap', { metric });
          }
        } catch (_) {}
        // v3 Phase 1z.132 — mark the detail open as a hub-child via
        // opts.returnTarget so closeLeaderboardRanking() routes its
        // X back to the hub instead of dumping the user to the
        // dashboard. Direct entry points (steps card click handler,
        // any legacy data-lb-metric paths) do not pass returnTarget
        // and continue to get the original "close all" behaviour.
        try { closeGlobalRankingsHub(); } catch (_) {}
        try { openLeaderboardRanking(metric, { returnTarget: 'hub' }); } catch (_) {}
      });
    }
    const hubClose   = document.getElementById('lb-hub-close');
    const hubOverlay = document.getElementById('lb-hub-overlay');
    if (hubClose && hubClose.getAttribute('data-wired') !== '1') {
      hubClose.setAttribute('data-wired', '1');
      hubClose.addEventListener('click', closeGlobalRankingsHub);
    }
    if (hubOverlay && hubOverlay.getAttribute('data-wired') !== '1') {
      hubOverlay.setAttribute('data-wired', '1');
      hubOverlay.addEventListener('click', closeGlobalRankingsHub);
    }
    const overlay = document.getElementById('lb-rank-overlay');
    const sheet   = document.getElementById('lb-rank-sheet');
    const close   = document.getElementById('lb-rank-close');
    if (close)   close.addEventListener('click', closeLeaderboardRanking);
    // v3 Phase 1z.40 — leaderboard sheet is X-only close.
    // TestFlight repro: scrolling the Hall of Fame list (longer than
    // any other sheet in the app) triggered the drag-dismiss gesture
    // and closed the sheet mid-scroll. Disabling both the overlay-
    // tap close AND the drag gesture for this sheet fixes the issue.
    // The X button in the top-right (#lb-rank-close, wired above) is
    // now the only close path. Other sheets keep their existing
    // dismiss behaviour — this scope change is leaderboard-only.
    // Voiding the `sheet`/`overlay` references here keeps lint happy
    // and signals intent to future readers.
    void sheet; void overlay;
    // v3 Phase 1z.36 — segmented control (This Week / Hall of Fame).
    // Delegated handler on the tabs container so the buttons can be
    // re-rendered later without rewiring.
    const tabsEl = document.getElementById('lb-rank-tabs');
    if (tabsEl) {
      tabsEl.addEventListener('click', (e) => {
        const btn = e.target && e.target.closest && e.target.closest('.lb-rank-tab');
        if (!btn) return;
        const tab = btn.getAttribute('data-lb-tab');
        if (tab) _lbSwitchTab(tab);
      });
    }
    // W274 — Steps ⇄ Highest Floor switch. Re-opens the sheet on the chosen
    // metric (preserving hub-return routing if we came from the hub).
    const metricSwitchEl = document.getElementById('lb-rank-metric-switch');
    if (metricSwitchEl) {
      metricSwitchEl.addEventListener('click', (e) => {
        const btn = e.target && e.target.closest && e.target.closest('.lb-metric-btn');
        if (!btn) return;
        const m = btn.getAttribute('data-lb-metric-switch');
        if (m && m !== _lbCurrentOpenMetric) {
          openLeaderboardRanking(m, { returnTarget: _lbDetailReturnTarget });
        }
      });
    }
    // W278 — tap a hunter row → profile card. Delegated so re-rendered rows work.
    const pcList = document.getElementById('lb-rank-list');
    if (pcList && pcList.getAttribute('data-pc-wired') !== '1') {
      pcList.setAttribute('data-pc-wired', '1');
      pcList.addEventListener('click', (e) => {
        const row = e.target && e.target.closest && e.target.closest('[data-profile-alias]');
        if (!row) return;
        const alias = row.getAttribute('data-profile-alias');
        if (!alias) return;
        _openProfileCard(alias, row.getAttribute('data-profile-sim') === '1' ? { _sim: true } : null);
      });
    }
    // W374 — the ✕ is gone; the profile sheet dismisses by swipe-down + backdrop tap.
    const pcOverlay = document.getElementById('pc-overlay');
    if (pcOverlay && pcOverlay.getAttribute('data-wired') !== '1') { pcOverlay.setAttribute('data-wired', '1'); pcOverlay.addEventListener('click', _closeProfileCard); }
    const pcSheetEl = document.getElementById('pc-sheet');
    if (pcSheetEl && pcSheetEl.getAttribute('data-drag-wired') !== '1' && typeof attachSheetDismissGesture === 'function') {
      pcSheetEl.setAttribute('data-drag-wired', '1');
      // ClaudeDesign "Hunter Profile - 100K Club" (W374) — drag the sheet down to
      // dismiss. Drag from the grabber/header, or the body when scrolled to top;
      // past ~28% of height (or a downward flick) closes, else it springs back.
      attachSheetDismissGesture(pcSheetEl, pcOverlay, _closeProfileCard, {
        baseTransform:    'translateX(-50%) ',
        handleSelector:   '.vn-drag-handle, .pc-head',
        scrollTarget:     '.pc-body',
        dismissThreshold: 0.28,
      });
    }
    // W279 — Wardrobe close / overlay / equip-tile delegation
    const wdClose = document.getElementById('wd-close');
    if (wdClose && wdClose.getAttribute('data-wired') !== '1') { wdClose.setAttribute('data-wired', '1'); wdClose.addEventListener('click', closeWardrobe); }
    const wdOverlay = document.getElementById('wd-overlay');
    if (wdOverlay && wdOverlay.getAttribute('data-wired') !== '1') { wdOverlay.setAttribute('data-wired', '1'); wdOverlay.addEventListener('click', closeWardrobe); }
    const wdPrev = document.getElementById('wd-preview-overlay');
    if (wdPrev && wdPrev.getAttribute('data-wired') !== '1') { wdPrev.setAttribute('data-wired', '1'); wdPrev.addEventListener('click', _wdClosePreview); }
    const wdBody = document.getElementById('wd-body');
    if (wdBody && wdBody.getAttribute('data-wired') !== '1') {
      wdBody.setAttribute('data-wired', '1');
      wdBody.addEventListener('click', (e) => {
        // W621 — Founder teaser strip → the offer sheet (close the wardrobe first,
        // same pattern as the Settings row: one sheet at a time).
        if (e.target && e.target.closest && e.target.closest('[data-wd-founder]')) {
          try { closeWardrobe(); } catch (_) {}
          try { openFounder(); } catch (_) {}
          return;
        }
        const tile = e.target && e.target.closest && e.target.closest('.wd-tile[data-skin]');
        if (tile) { _equipSkin(tile.getAttribute('data-skin')); return; }
        // W706 — card-background tiles: usable → equip/clear + repaint; a
        // non-member tap is the Premium funnel; locked-achievement tap explains.
        const cbg = e.target && e.target.closest && e.target.closest('.cbg-tile[data-cbg]');
        if (cbg) {
          const id = cbg.getAttribute('data-cbg') || null;
          if (cbg.getAttribute('data-cbg-usable') === '1') {
            _cardBgEquip(id);
            _renderWardrobe();
            try { showHabitToast(id ? 'Card background equipped — it now flies on every board.' : 'Back to the basic card.'); } catch (_) {}
          } else if (!_founderOwned()) {
            try { closeWardrobe(); } catch (_) {}
            try { openFounder(); } catch (_) {}
          } else {
            const def = _cardBgById(id);
            try { if (def) showHabitToast('Locked — ' + def.need + '.'); } catch (_) {}
          }
          return;
        }
        const prem = e.target && e.target.closest && e.target.closest('.wd-tile--premium[data-premium]');
        if (prem) {
          const pid = prem.getAttribute('data-premium');
          const psk = PREMIUM_SKINS.find((x) => x.id === pid);
          if (psk && isSkinOwned(pid)) { _equipSkin(psk.file); return; }                                  // W297 owned → equip
          if (psk && window.Auth && Auth.iapAvailable && Auth.iapAvailable()) { _buySkin(psk); return; }   // buyable → purchase
          _wdPreviewSkin(pid);                                                                              // else (SOON) → preview
        }
      });
    }
    const pcBodyEl = document.getElementById('pc-body');
    if (pcBodyEl && pcBodyEl.getAttribute('data-wd-wired') !== '1') {
      pcBodyEl.setAttribute('data-wd-wired', '1');
      pcBodyEl.addEventListener('click', (e) => {
        if (e.target && e.target.closest && e.target.closest('[data-wardrobe]')) { _closeProfileCard(); openWardrobe(); return; }
        const echo = e.target && e.target.closest && e.target.closest('[data-pcecho]');
        if (echo) {
          const al = echo.getAttribute('data-pcecho-alias') || '';
          const av = echo.getAttribute('data-pcecho-avatar') || '';
          try { _audCue('ui_tap'); } catch (_) {}
          _pvpEchoFriend(al, av);
          return;
        }
        // W444 — the Arena Rating row opens the ranked ladder (where this hunter places).
        if (e.target && e.target.closest && e.target.closest('[data-pc-arena]')) {
          try { _audCue('ui_tap'); } catch (_) {}
          try { _closeProfileCard(); } catch (_) {}
          try { openArena(); } catch (_) {}
          try { _pvpOpenLeaderboard(); } catch (_) {}
        }
      });
    }
  }
  try { window.openLeaderboardRanking = openLeaderboardRanking; } catch (_) {}

  // CARDS.md-spec boss card. 5:7 portrait, 6 stacked regions
  // (header / art / stat strip / flavor / kill condition / progress).
  // Tappable — opens the full-screen detail modal via openBossFullScreen.
  //
  // State variants composed via classes:
  //   .bcard--active   — streak > 0, border pulses purple-gold
  //   .bcard--defeated — kill_count > 0, gold border + corner trophy
  //
  // W589 — boss-card name class with a length bucket so long names shrink to
  // fit two lines instead of truncating (see .bcard-name--long/--xlong in CSS).
  // Deterministic at render time — no runtime measurement or font-load race.
  function _bossNameClass(name) {
    const n = (name || '').length;
    return 'bcard-name' + (n >= 22 ? ' bcard-name--xlong' : (n >= 18 ? ' bcard-name--long' : ''));
  }
  // W589 — precise auto-fit: after a boss list renders, shrink any name whose
  // wrapped height exceeds two lines until it fits, so long names ("The Forge
  // of Ten Thousand Days") are never truncated regardless of the actual font
  // metrics. The CSS length buckets get most names to the right size; this
  // guarantees the tail. Re-run on fonts.ready (Cinzel may load after paint).
  function _fitBossNames(container) {
    if (!container || typeof getComputedStyle !== 'function') return;
    const els = container.querySelectorAll('.bcard-name');
    for (let i = 0; i < els.length; i++) {
      const el = els[i];
      if (!el.clientWidth) continue;                 // not laid out (panel hidden) — skip
      el.style.fontSize = '';                         // reset to the CSS bucket/base
      let fs = parseFloat(getComputedStyle(el).fontSize) || 12;
      let guard = 0;
      // line-height is 1.1; +2px slack. Two-line budget = 2 * 1.1 * fs.
      while (guard++ < 26 && el.scrollHeight > (2 * 1.1 * fs) + 2 && fs > 7.5) {
        fs -= 0.5;
        el.style.fontSize = fs + 'px';
      }
    }
  }

  // Illustration path derives from id by swapping underscores for
  // hyphens (the_insomniac → the-insomniac.png) since the source
  // assets ship with hyphens.
  function buildBossCardHTML(id) {
    const cfg = BOSSES[id];
    const state = getBossState(id);
    const imgPath = getBossArtPath(id);
    // v3 Phase 1z.63 — flight-threshold bosses render a single
    // threshold dot (filled = boss defeated this hunt). Progress
    // detail lives in the label below. Other bosses keep the
    // streak-dots pattern.
    // v3 Phase 1z.67 — dual-condition bosses (Furnace Knight) render
    // a single threshold dot; the dual progress lines render in the
    // label below.
    const _isDualBoss = (typeof cfg.workoutMinutes === 'number' && typeof cfg.activeEnergyKcal === 'number');
    const _dualSatisfied = _isDualBoss && state.strength_done === true &&
      typeof state.energy_progress === 'number' && state.energy_progress >= cfg.activeEnergyKcal;
    // v3 Phase 1z.69 — step-threshold bosses (Marathon Wraith, also
    // applies to Steel Wolf and Glass Strider) get a single threshold
    // dot in lieu of streak dots, with the granular count in the
    // label below.
    // W262 — B-rank back-to-back bosses render run dots from the
    // qualifying_progress mirror; flagged BEFORE the step branch so the
    // Patient Flame (stepThreshold + consecutiveDays) lands here.
    const _isConsecBoss = (typeof cfg.consecutiveDays === 'number' || typeof cfg.consecutiveNights === 'number');
    const _consecTarget = _isConsecBoss ? (cfg.consecutiveDays || cfg.consecutiveNights) : 0;
    const _consecCur = _isConsecBoss ? Math.max(0, Math.min(_consecTarget,
      (typeof state.qualifying_progress === 'number') ? state.qualifying_progress : 0)) : 0;
    const _isStepBoss = (typeof cfg.stepThreshold === 'number') && !_isConsecBoss;
    const _stepSatisfied = _isStepBoss && state.kill_count > 0 &&
      typeof state.last_eval_date === 'string';
    const dots = _isDualBoss
      ? '<span class="bcard-dot' + (_dualSatisfied ? ' bcard-dot--filled' : '') + '"></span>'
      : _isConsecBoss
      ? Array.from({ length: _consecTarget }, (_, i) =>
          '<span class="bcard-dot' + (i < _consecCur ? ' bcard-dot--filled' : '') + '"></span>'
        ).join('')
      : (typeof cfg.flightThreshold === 'number')
        ? '<span class="bcard-dot' +
          ((typeof state.flight_progress === 'number' && state.flight_progress >= cfg.flightThreshold)
            ? ' bcard-dot--filled' : '') + '"></span>'
        : _isStepBoss
          ? '<span class="bcard-dot' +
            ((typeof state.step_progress === 'number' && state.step_progress >= cfg.stepThreshold)
              ? ' bcard-dot--filled' : '') + '"></span>'
          : Array.from({ length: cfg.streakTarget }, (_, i) =>
              '<span class="bcard-dot' + (i < state.streak ? ' bcard-dot--filled' : '') + '"></span>'
            ).join('');

    // Compose state classes. They stack — engaged + active + defeated
    // can all apply at once. v2.0.1 engagement-pivot adds .bcard--engaged
    // (gold border + HUNTING label), .bcard--dormant (dim, unlocked but
    // not hunted), and .bcard--preview (locked rank, view-only).
    //
    // Preview state takes precedence over dormant/engaged — a boss in
    // a locked dungeon can't be engaged (the modal renders a "Reach X
    // rank to engage" label instead of the ENGAGE button), so engaging
    // semantics don't apply. The card just shows the kit so the user
    // knows what's coming.
    const isPreview = !isGateUnlocked(cfg.rank);
    const stateClasses = [];
    if (isPreview) {
      stateClasses.push('bcard--preview');
    } else if (state.engaged === true) {
      stateClasses.push('bcard--engaged');
    } else {
      stateClasses.push('bcard--dormant');
    }
    if (state.streak > 0) stateClasses.push('bcard--active');
    if (state.kill_count > 0) stateClasses.push('bcard--defeated');
    // W676 — the W662 PERMANENT ever-felled per-boss fade is REMOVED (owner: players
    // still want to run a boss even after farming all its gear, so it must NOT grey
    // out for good). The "done for today" signal now lives on the rank GATE instead
    // (gate-cell--cleared in renderQuestsPanel, when ALL solo bosses of a rank are
    // cleared for the day). The transient per-boss daily '.bcard--cleared' below stays.
    // W298 — Rendell feedback: surface per-cadence completion on the GRID so
    // the player reads "done for now" at a glance instead of opening each boss.
    // Cleared = unlocked, not currently hunting, and the engage gate reports a
    // cadence clear (e.g. a daily defeated today -> "resets at midnight"). So
    // re-huntable bosses stay bright; this mirrors the boss-detail HUNT COMPLETE
    // pill one level up. Wrapped defensively — a bad gate never breaks the card.
    let _clearedNow = false;
    try {
      _clearedNow = !isPreview && state.engaged !== true &&
        typeof canEngageBossNow === 'function' &&
        canEngageBossNow(id, cfg).ok === false;
    } catch (_) {}
    if (_clearedNow) stateClasses.push('bcard--cleared');
    // W261 — the .bcard--burned variant (Carouser weekend forfeit) is
    // retired with the weekend mechanic; weekend_burned is never set now.
    const classAttr = ['bcard'].concat(stateClasses).join(' ');

    // Top-right corner label. Mutually exclusive between HUNTING (engaged
    // and unlocked) and PREVIEW (locked-walkable). Fills the slot where
    // the glyph used to live before the emoji-removal pass. Higher
    // z-index than the rank pill so it visually anchors the state.
    let cornerLabel = '';
    if (isPreview) {
      cornerLabel = '<span class="bcard-preview-label" aria-hidden="true">PREVIEW</span>';
    } else if (state.engaged === true) {
      cornerLabel = '<span class="bcard-hunting-label" aria-hidden="true">HUNTING</span>';
    }

    // Cadence display: capitalize first letter for the stat strip.
    const cadenceLabel = (cfg.cadence || 'daily').charAt(0).toUpperCase() +
                         (cfg.cadence || 'daily').slice(1);

    // Trophy prefix on kill-count line when count > 0 (per CARDS.md
    // line 153). Defeated state ALSO adds a corner trophy overlay
    // (line 180-182) — they're separate visual cues.
    const killText = state.kill_count > 0
      ? '🏆 Defeated: ' + state.kill_count + ' time' + (state.kill_count === 1 ? '' : 's')
      : 'Defeated: 0 times';

    // Defeated-state corner trophy. Renders as a span overlay so the
    // gold-border treatment can do its own thing on .bcard--defeated.
    const cornerTrophy = state.kill_count > 0
      ? '<span class="bcard-corner-trophy" aria-hidden="true">🏆</span>'
      : '';

    // W298 — green check overlay for a cadence-cleared boss (top-left corner;
    // the rank pill is hidden under it via CSS). Sits beside the lifetime trophy.
    const cornerCleared = _clearedNow
      ? '<span class="bcard-corner-cleared" aria-hidden="true">✓</span>'
      : '';

    return (
      '<button type="button" class="' + classAttr + '" data-boss="' + id + '" aria-label="View ' + esc(cfg.name) + ' details">' +
        cornerTrophy +
        cornerLabel +
        cornerCleared +
        // Region a: Header strip — rank pill (absolute, left) +
        // boss name (centered in the full strip width).
        '<div class="bcard-header">' +
          '<span class="bcard-rank-pill rank-badge" data-rank="' + esc(cfg.rank) + '">' + esc(cfg.rank) + '</span>' +
          '<span class="' + _bossNameClass(cfg.name) + '">' + esc(cfg.name) + '</span>' +
        '</div>' +
        // Region b: Art window — bleed-to-edge illustration.
        // v3 Phase 1z.80 — img rendered without inline src; renderBossesPanel
        // calls setBossImage(img, id) post-render so the load uses the same
        // start-hidden / onload-reveals pattern as item art (setModalCardArt).
        // The previous inline `onerror="display:none"` pattern fired on
        // transient iOS Capacitor WebView fetch races and permanently hid
        // the image even after the asset loaded fine.
        '<div class="bcard-art">' +
          '<img alt="" draggable="false" data-boss-art-id="' + esc(id) + '" style="display:none">' +
        '</div>' +
        // Region c → W776: MODE strip (owner: "the most important thing is to see
        // whether it is co-op or solo" — STAT and CADENCE were noise, and the
        // flavor line is gone so the kill condition reads big and clear).
        '<div class="bcard-stats"><span class="bcard-mode bcard-mode--solo">SOLO</span></div>' +
        // Region e: Kill condition — now the card's loud line (.bcard-cond enlarged).
        '<div class="bcard-cond">' + esc(cfg.killCondShort) + '</div>' +
        // Region f: Progress — dots + streak label + kill count.
        // v3 Phase 1z.63 — flight-threshold bosses display cumulative
        // "N / threshold flights" instead of streak progress.
        // v3 Phase 1z.67 — dual-condition bosses (Furnace Knight)
        // render a two-line summary: strength check + kcal progress.
        // v3 Phase 1z.69 — step-threshold bosses display "N / threshold
        // steps" (max-per-day inside window).
        '<div class="bcard-progress">' +
          '<div class="bcard-dots">' + dots + '</div>' +
          '<div class="bcard-progress-label">' +
            (_isDualBoss
              ? ((state.strength_done === true ? '✓' : '○') + ' strength · ' +
                  Math.max(0, Math.min(cfg.activeEnergyKcal, (typeof state.energy_progress === 'number') ? state.energy_progress : 0)) +
                  ' / ' + cfg.activeEnergyKcal + ' kcal')
              : _isConsecBoss
              ? (_consecCur + ' / ' + _consecTarget + ' ' + _bossProgressNoun(cfg) + ' · back-to-back')
              : (typeof cfg.flightThreshold === 'number'
                ? (Math.max(0, Math.min(cfg.flightThreshold, (typeof state.flight_progress === 'number') ? state.flight_progress : 0)) + ' / ' + cfg.flightThreshold + ' ' + _bossProgressNoun(cfg))
                : _isStepBoss
                  ? (Math.max(0, Math.min(cfg.stepThreshold, (typeof state.step_progress === 'number') ? state.step_progress : 0)).toLocaleString('en-US') + ' / ' + cfg.stepThreshold.toLocaleString('en-US') + ' steps')
                  : (state.streak + ' / ' + cfg.streakTarget + ' ' + _bossProgressNoun(cfg)))) +
          '</div>' +
          '<div class="bcard-kills">' + killText + '</div>' +
        '</div>' +
        // v3 Phase 1z.277C — Boss archetype pill (display-only).
        // Sits in the card footer area below the kills label so it
        // doesn't crowd the small-screen header. Rendered only when
        // BOSS_CONFIG has a valid archetype string; missing/unknown
        // values produce an empty label and skip the pill entirely.
        // Color theming via data-archetype attribute in CSS.
        (function () {
          const archLabel = bossArchetypeLabel(cfg.archetype);
          if (!archLabel) return '';
          return '<div class="boss-archetype-pill" data-archetype="' +
                  esc(cfg.archetype) + '">' + archLabel + '</div>';
        })() +
      '</button>'
    );
  }

  // Renders the boss list inside the dungeon view. Optional rankFilter
  // limits to bosses tagged with that rank (CLAUDE.md → "Where they
  // live"). Single render path as of the cleanup that removed the old
  // card style — boss-cards-only-newstyle from here on. Each card
  // renders into a 2-col grid; tap opens the full-screen detail modal.
  function renderBossesPanel(rankFilter) {
    const list = document.getElementById('bosses-list');
    if (!list) return;
    // v3 Phase 1z.117 — guard against the kill/streak paths leaking
    // an unfiltered render (rankFilter === undefined). That used to
    // dump every boss across every rank into the active dungeon's
    // body, producing the "E + D + C bosses under D-RANK DUNGEON"
    // bug after defeating a boss. Default to the in-app
    // currentDungeonRank when no explicit filter is passed.
    const effectiveRank = (typeof rankFilter === 'string' && rankFilter)
      ? rankFilter
      : ((typeof currentDungeonRank === 'string' && currentDungeonRank) ? currentDungeonRank : null);
    const bossIds = Object.keys(BOSSES).filter(id =>
      !BOSSES[id].coopOnly && (!effectiveRank || BOSSES[id].rank === effectiveRank)
    );
    try {
      if (typeof _addHealthVerifyBreadcrumb === 'function') {
        _addHealthVerifyBreadcrumb('dungeon-render', {
          rankFilterArg: rankFilter || null,
          effectiveRank,
          visibleBossCount: bossIds.length,
          visibleRanks: Array.from(new Set(bossIds.map(id => BOSSES[id] && BOSSES[id].rank))).sort(),
          totalBossCount: Object.keys(BOSSES).length,
        });
      }
    } catch (_) {}
    // W396/W397 — co-op bosses for THIS rank (each renders in the gate matching
    // its own rank). Computed before the empty guard so a rank that has a co-op
    // boss but no solo boss still renders the co-op card instead of "No bosses".
    const _coopForRank = Object.keys(COOP_BOSSES).filter(function (cid) { return COOP_BOSSES[cid].rank === effectiveRank && !COOP_BOSSES[cid].special; });   // W693 — the members raid enters only via its gate, never a rank dungeon
    if (bossIds.length === 0 && _coopForRank.length === 0) {
      list.innerHTML = '<p class="dungeon-empty">No bosses await yet. Check back as more dungeons fill.</p>';
      list.classList.remove('bosses-list--cards');
      return;
    }
    list.classList.add('bosses-list--cards');
    list.innerHTML = bossIds.map(buildBossCardHTML).join('');
    // W370 — co-op boss card(s) appended before the setBossImage loop so their
    // art wires too.
    try {
      if (_coopForRank.length) {
        const _coopHtml = _coopForRank.map(buildCoopBossCardHTML).join('');
        if (_coopHtml) list.insertAdjacentHTML('beforeend', _coopHtml);
        try { _coopApplyBadge(); _coopRefreshBadge(); } catch (_) {}
      }
    } catch (_) {}
    // v3 Phase 1z.80 — wire boss art via setBossImage post-render so the
    // robust start-hidden / onload-reveals pattern applies to every card.
    try {
      list.querySelectorAll('.bcard-art img[data-boss-art-id]').forEach(img => {
        const id = img.getAttribute('data-boss-art-id');
        if (id) setBossImage(img, id);
      });
    } catch (_) {}
    // W589 — auto-fit boss names to two lines (never truncate). Once now, and
    // again after Cinzel loads (font metrics change the wrap).
    try { _fitBossNames(list); } catch (_) {}
    try { if (document.fonts && document.fonts.ready) document.fonts.ready.then(function () { try { _fitBossNames(list); } catch (_) {} }); } catch (_) {}
  }

  // ── Full-screen boss detail modal ──────────────────────────
  // Replaces the v1.1.7 bottom-sheet detail. Tapping any boss card
  // (.bcard) opens this overlay. Closes via Back button, ESC key,
  // or any tab switch. Pulls all data from BOSSES[id] + getBossState.
  // Cadence label capitalizes for display ("daily" → "Daily").
  function openBossFullScreen(id) {
    const cfg = BOSSES[id];
    if (!cfg) return;
    const state = getBossState(id);
    const overlay = document.getElementById('boss-fs-overlay');
    if (!overlay) return;
    // v3 Phase 1z.43 — opening boss detail is a natural moment to
    // re-resolve the hunt window. If a delayed-sync kill is sitting
    // in HealthKit, fire it now so the detail screen renders the
    // post-kill state instead of a stale "still hunting" surface.
    // Fire-and-forget; the open path below renders the current
    // best-known state immediately, and the resolver will call
    // refreshBossFullScreenIfOpen if it transitions the boss.
    try { resolveBossHuntsAcrossWindow(); } catch (_) {}
    try { _sweepExpiredBossHuntsNoHealth(); } catch (_) {}

    const cadenceLabel = (cfg.cadence || 'daily').charAt(0).toUpperCase() +
                         (cfg.cadence || 'daily').slice(1);
    const imgPath = getBossArtPath(id);

    // Header — rank pill
    const rankPill = document.getElementById('bfs-rank-pill');
    if (rankPill) {
      rankPill.textContent = cfg.rank;
      rankPill.setAttribute('data-rank', cfg.rank); // per-rank color via CSS vars
    }

    // Hero art
    const heroImg = document.getElementById('bfs-hero-img');
    if (heroImg) {
      // v3 Phase 1z.80 — robust setBossImage replaces the prior raw
      // imgPath assignment that left the broken-image glyph visible
      // on transient iOS Capacitor WebView fetch races. Starts hidden,
      // onload reveals, onerror keeps hidden (clean fallback).
      heroImg.alt = cfg.name;
      setBossImage(heroImg, id);
    }

    // Name + rank label
    const nameEl = document.getElementById('bfs-name');
    if (nameEl) nameEl.textContent = cfg.name;
    const rankLabel = document.getElementById('bfs-rank-label');
    if (rankLabel) rankLabel.textContent = cfg.rank + '-RANK BOSS';

    // v3 Phase 1z.277C — Archetype identity row + disclaimer.
    // Display-only. Hides the whole row when the boss has no
    // archetype string (defensive — shouldn't happen after 1z.277C,
    // but kept null-safe for forward additions). The disclaimer
    // ("Verified behavior decides victory.") only renders when the
    // pill renders, so its presence reinforces the hard rule that
    // stats/labels never bypass real-world conditions.
    const archRow = document.getElementById('bfs-archetype-row');
    const archPill = document.getElementById('bfs-archetype-pill');
    const archDisc = document.getElementById('bfs-archetype-disclaimer');
    const archLabel = bossArchetypeLabel(cfg.archetype);
    if (archRow && archPill) {
      if (archLabel) {
        archPill.textContent = archLabel;
        archPill.setAttribute('data-archetype', cfg.archetype);
        archRow.hidden = false;
        if (archDisc) archDisc.hidden = false;
      } else {
        archPill.textContent = '';
        archPill.setAttribute('data-archetype', '');
        archRow.hidden = true;
        if (archDisc) archDisc.hidden = true;
      }
    }

    // Long flavor (italic, larger)
    const flavorEl = document.getElementById('bfs-flavor');
    if (flavorEl) flavorEl.textContent = cfg.flavorLong || cfg.flavorShort || '';

    // Stats grid
    const setStat = (id, val) => {
      const el = document.getElementById(id);
      if (el) el.textContent = val;
    };
    setStat('bfs-stat-rank',     cfg.rank);
    setStat('bfs-stat-domain',   cfg.statDomain || '—');
    setStat('bfs-stat-cadence',  cadenceLabel);
    setStat('bfs-stat-defeated',
      state.kill_count + ' time' + (state.kill_count === 1 ? '' : 's')
    );

    // Kill condition (long version)
    const killCondEl = document.getElementById('bfs-kill-cond');
    if (killCondEl) killCondEl.textContent = cfg.killCondLong || cfg.killCondShort || '';

    // v3 W202 — wearable/app requirement note for sleep/workout bosses
    // (metric-driven; empty for step/flight bosses → element hidden).
    const verifyNoteEl = document.getElementById('bfs-verify-note');
    if (verifyNoteEl) {
      const note = _bossVerifyNote(cfg);
      verifyNoteEl.textContent = note;
      verifyNoteEl.classList.toggle('hidden', !note);
    }

    // Progress dots + label (sized larger via CSS for the modal context)
    // v3 Phase 1z.63 — flight-threshold bosses (Ascendant Colossus) use
    // a cumulative-count label instead of streak dots. flight_progress
    // is written by the window resolver; when missing (e.g. permission
    // denied or first paint before the resolver returns), falls back
    // to 0 — never crashes.
    // v3 Phase 1z.67 — dual-condition bosses (Furnace Knight) render
    // a single threshold dot + two-line summary: strength verified
    // check + kcal progress toward activeEnergyKcal.
    const progressEl = document.getElementById('bfs-progress');
    if (progressEl) {
      const isDualBoss = (typeof cfg.workoutMinutes === 'number' && typeof cfg.activeEnergyKcal === 'number');
      if (isDualBoss) {
        const kcalCur = Math.max(0, Math.min(cfg.activeEnergyKcal,
          (typeof state.energy_progress === 'number') ? state.energy_progress : 0));
        const strengthOk = state.strength_done === true;
        const bothDone = strengthOk && kcalCur >= cfg.activeEnergyKcal;
        const dots = '<span class="bfs-dot' + (bothDone ? ' bfs-dot--filled' : '') + '"></span>';
        const strengthLine = (strengthOk ? '✓ ' : '○ ') + 'Strength workout' + (strengthOk ? ' verified' : '');
        const kcalLine = kcalCur + ' / ' + cfg.activeEnergyKcal + ' active kcal';
        progressEl.innerHTML =
          '<div class="bfs-dots">' + dots + '</div>' +
          '<div class="bfs-progress-label">' + esc(strengthLine) + '</div>' +
          '<div class="bfs-progress-label">' + esc(kcalLine) + '</div>';
      } else if (typeof cfg.consecutiveDays === 'number' || typeof cfg.consecutiveNights === 'number') {
        // W262 — B-rank back-to-back run: dots show the CURRENT best run
        // inside the hunt window (qualifying_progress mirror). Checked
        // before the step branch so the Patient Flame (stepThreshold +
        // consecutiveDays) lands here.
        const target = cfg.consecutiveDays || cfg.consecutiveNights;
        const cur = Math.max(0, Math.min(target,
          (typeof state.qualifying_progress === 'number') ? state.qualifying_progress : 0));
        const dots = Array.from({ length: target }, (_, i) =>
          '<span class="bfs-dot' + (i < cur ? ' bfs-dot--filled' : '') + '"></span>'
        ).join('');
        progressEl.innerHTML =
          '<div class="bfs-dots">' + dots + '</div>' +
          '<div class="bfs-progress-label">' + cur + ' / ' + target + ' ' + _bossProgressNoun(cfg) + ' — back-to-back</div>';
      } else if (typeof cfg.flightThreshold === 'number') {
        const cur = Math.max(0, Math.min(cfg.flightThreshold,
          (typeof state.flight_progress === 'number') ? state.flight_progress : 0));
        // Single threshold-pill dot pair: filled vs. unfilled — matches
        // the streakTarget=1 visual for daily bosses, but the label
        // carries the granular count.
        const filled = cur >= cfg.flightThreshold;
        const dots = '<span class="bfs-dot' + (filled ? ' bfs-dot--filled' : '') + '"></span>';
        progressEl.innerHTML =
          '<div class="bfs-dots">' + dots + '</div>' +
          '<div class="bfs-progress-label">' + cur + ' / ' + cfg.flightThreshold + ' ' + _bossProgressNoun(cfg) + '</div>';
      } else if (typeof cfg.stepThreshold === 'number') {
        // v3 Phase 1z.69 — step-threshold bosses (Marathon Wraith,
        // Steel Wolf, Glass Strider) show max-per-day step count
        // toward the threshold. Single dot fills when defeated.
        const cur = Math.max(0, Math.min(cfg.stepThreshold,
          (typeof state.step_progress === 'number') ? state.step_progress : 0));
        const filled = cur >= cfg.stepThreshold;
        const dots = '<span class="bfs-dot' + (filled ? ' bfs-dot--filled' : '') + '"></span>';
        progressEl.innerHTML =
          '<div class="bfs-dots">' + dots + '</div>' +
          '<div class="bfs-progress-label">' + cur.toLocaleString('en-US') + ' / ' + cfg.stepThreshold.toLocaleString('en-US') + ' steps</div>';
      } else {
        const dots = Array.from({ length: cfg.streakTarget }, (_, i) =>
          '<span class="bfs-dot' + (i < state.streak ? ' bfs-dot--filled' : '') + '"></span>'
        ).join('');
        progressEl.innerHTML =
          '<div class="bfs-dots">' + dots + '</div>' +
          '<div class="bfs-progress-label">' + state.streak + ' / ' + cfg.streakTarget + ' ' + _bossProgressNoun(cfg) + '</div>';
      }
    }

    // Engagement section (v2.0.1) — three mutually-exclusive states:
    // preview (rank locked), engaged, or not-engaged-but-unlockable.
    // Stamps `data-boss-id` on the buttons so the click handlers
    // (wired once in setupBossesPanel) can dispatch.
    const engageState   = document.getElementById('bfs-engage-state');
    const engageCta     = document.getElementById('bfs-engage-cta');
    const engagePreview = document.getElementById('bfs-engage-preview');
    const engageBtn     = document.getElementById('bfs-engage-btn');
    const disengageBtn  = document.getElementById('bfs-disengage-btn');
    const engageSince   = document.getElementById('bfs-engage-since');
    const engagePreviewLabel = document.getElementById('bfs-engage-preview-label');
    const isPreview = !isGateUnlocked(cfg.rank);

    if (engageState && engageCta && engagePreview) {
      // Default-hide all three; one branch unhides exactly one.
      engageState.classList.add('hidden');
      engageCta.classList.add('hidden');
      engagePreview.classList.add('hidden');

      if (isPreview) {
        // Rank locked — static "Reach X rank to engage" label.
        // ENGAGE button is intentionally absent; engageBoss() also
        // refuses preview-state bosses defensively (see helper).
        engagePreview.classList.remove('hidden');
        if (engagePreviewLabel) {
          engagePreviewLabel.textContent = 'Reach ' + cfg.rank + ' rank to engage';
        }
      } else if (state.engaged === true) {
        engageState.classList.remove('hidden');
        // v3 Phase 1z.43 — replace the vague "HUNTING SINCE …" with a
        // concrete remaining-time readout so the user can see when
        // the hunt window closes. Falls back to the legacy copy if
        // we somehow lack hunt-window fields (defensive — the
        // engageBoss path always stamps them now, and legacy state
        // is migrated on first access via _migrateBossHuntFields).
        _migrateBossHuntFields(id, state, cfg);
        const remainingMs = _bossHuntRemainingMs(state, cfg);
        if (engageSince) {
          if (remainingMs == null) {
            engageSince.textContent = 'HUNTING SINCE ' + formatEngagedAt(state.engaged_at);
          } else if (remainingMs <= 0) {
            engageSince.textContent = 'HUNT EXPIRED';
          } else {
            engageSince.textContent = 'HUNT ENDS IN ' + _formatHuntRemaining(remainingMs);
          }
        }
        if (disengageBtn) disengageBtn.setAttribute('data-boss-id', id);
      } else {
        engageCta.classList.remove('hidden');
        const cost = engageCostSouls(cfg.rank);
        if (engageBtn) {
          engageBtn.setAttribute('data-boss-id', id);
          // v2.0.1: button text shows the souls cost. Always-tappable
          // — broke-state is handled by engageBoss's balance check
          // which fires a precise "Need N souls. You have M." toast.
          // v3 Phase 1z.6 — when kill_count > 0 AND not engaged, the
          // boss was defeated and the hunt naturally ended. Swap the
          // button copy to "HUNT AGAIN" so the framing is "resume the
          // hunt" rather than "first engagement." Cost still applies.
          const huntedBefore = (state.kill_count || 0) > 0;
          const verb = huntedBefore ? 'HUNT AGAIN' : 'ENGAGE BOSS';
          engageBtn.textContent = cost > 0
            ? verb + ' — ' + cost + ' SOULS'
            : verb;
          // v3 Phase 1z.39 — visually soften the button when broke.
          // The existing engageBoss() guard already toasts the
          // precise "Need N souls. You have M." message; this just
          // makes the UI state visible before tap so users can
          // self-discover the gate.
          let balance = 0;
          try { balance = (typeof getSoulsBalance === 'function') ? getSoulsBalance() : 0; } catch (_) {}
          engageBtn.classList.toggle('bfs-engage-btn--insufficient', cost > 0 && balance < cost);
        }
        // v3 Phase 1z.39 — populate the Souls balance readout above
        // the button. Reads from the single source of truth
        // (getSoulsBalance) — never duplicates state. Two states:
        //   sufficient   — "Souls available · {balance}" in gold
        //   insufficient — "{balance} / {cost} needed" in red
        const balanceEl    = document.getElementById('bfs-souls-balance');
        const balanceNumEl = document.getElementById('bfs-souls-balance-num');
        const balanceLabelEl = balanceEl ? balanceEl.querySelector('.bfs-souls-balance__label') : null;
        if (balanceEl && balanceNumEl) {
          let balance = 0;
          try { balance = (typeof getSoulsBalance === 'function') ? getSoulsBalance() : 0; } catch (_) {}
          const insufficient = cost > 0 && balance < cost;
          balanceEl.classList.toggle('bfs-souls-balance--insufficient', insufficient);
          if (insufficient) {
            if (balanceLabelEl) balanceLabelEl.textContent = 'Need more souls';
            balanceNumEl.textContent = balance.toLocaleString('en-US') + ' / ' + cost + ' needed';
          } else {
            if (balanceLabelEl) balanceLabelEl.textContent = 'Souls available';
            balanceNumEl.textContent = balance.toLocaleString('en-US');
          }
        }
        // Swap blurb copy for the post-defeat state.
        const blurb = engageCta.querySelector('.bfs-engage-blurb');
        if (blurb) {
          if ((state.kill_count || 0) > 0) {
            blurb.textContent = (cfg.name || 'This boss') +
              ' has been defeated. Engage again to begin a new hunt.';
          } else {
            blurb.textContent = "This boss only counts progress while you're actively hunting it. You can hunt up to 3 bosses at once.";
          }
        }
        // v3 Phase 1z.72 — generalized lock-state CTA. canEngageBossNow
        // returns the locked-state ctaText + blurb ("AVAILABLE TOMORROW" /
        // daily-reset copy for daily bosses already cleared today; the
        // 1z.58 Carouser Friday-only gate was retired in W261).
        // engageBoss enforces the same gate as the source of truth
        // (defense in depth).
        const engageGate = canEngageBossNow(id, cfg, new Date());
        if (engageBtn) {
          engageBtn.classList.toggle('bfs-engage-btn--locked', !engageGate.ok);
          if (!engageGate.ok) {
            engageBtn.disabled = true;
            engageBtn.setAttribute('aria-disabled', 'true');
            engageBtn.textContent = engageGate.ctaText || 'UNAVAILABLE';
          } else {
            engageBtn.disabled = false;
            engageBtn.removeAttribute('aria-disabled');
          }
        }
        if (blurb && !engageGate.ok && engageGate.blurb) {
          blurb.textContent = engageGate.blurb;
        }
      }
    }

    // v3 Phase 1h → 1r — RELIC MERCY readout. Three-layer protection:
    //   Guaranteed relic — any drop resets this counter.
    //   Rare mercy        — Rare or Ultra resets this counter.
    //   Ultra mercy       — only Ultra resets this counter.
    const mercyEl = document.getElementById('bfs-mercy');
    if (mercyEl) {
      try {
        const m = getDropPityDisplay(id);
        const cur1 = Math.min(m.anyDropCurrent, m.anyDropTarget);
        const cur2 = Math.min(m.rareCurrent,    m.rareTarget);
        const cur3 = Math.min(m.ultraCurrent,   m.ultraHardTarget);
        mercyEl.innerHTML =
          '<div class="bfs-mercy-row" title="Any relic resets this.">' +
            '<span class="bfs-mercy-label">Guaranteed relic</span>' +
            '<span class="bfs-mercy-val">' + cur1 + ' / ' + m.anyDropTarget + '</span>' +
          '</div>' +
          '<div class="bfs-mercy-row" title="Rare or Ultra resets this.">' +
            '<span class="bfs-mercy-label">Rare mercy</span>' +
            '<span class="bfs-mercy-val">' + cur2 + ' / ' + m.rareTarget + '</span>' +
          '</div>' +
          '<div class="bfs-mercy-row" title="Only Ultra resets this.">' +
            '<span class="bfs-mercy-label">Ultra mercy</span>' +
            '<span class="bfs-mercy-val">' + cur3 + ' / ' + m.ultraHardTarget + '</span>' +
          '</div>';
      } catch (_) {
        mercyEl.innerHTML = '';
      }
    }

    // v3 Phase 1z.7 — DEFEATED state surfaces. When the boss has at
    // least one kill AND is not currently engaged, swap the overlay
    // into its `bfs-overlay--defeated` skin and populate the new
    // hero card, last-drop callout, and hunt history mini-ledger.
    const isDefeatedState = !isPreview && state.engaged !== true && (state.kill_count || 0) > 0;
    if (isDefeatedState) {
      overlay.classList.add('bfs-overlay--defeated');
      _populateBfsDefeatedState(id, cfg, state);
    } else {
      overlay.classList.remove('bfs-overlay--defeated');
      const heroEl    = document.getElementById('bfs-defeated-hero');
      const lastDrop  = document.getElementById('bfs-last-drop');
      const histEl    = document.getElementById('bfs-hunt-history');
      const ctaEl     = document.getElementById('bfs-defeated-cta');
      if (heroEl)   heroEl.classList.add('hidden');
      if (lastDrop) lastDrop.classList.add('hidden');
      if (histEl)   histEl.classList.add('hidden');
      if (ctaEl)    ctaEl.classList.add('hidden');
    }

    // Track which boss the modal is currently showing so engage/
    // disengage actions from the helper functions can refresh it.
    bfsCurrentBossId = id;

    overlay.classList.remove('hidden');
    document.body.classList.add('bfs-locked'); // lock background scroll
  }

  // v3 Phase 1z.7 — friendly time-ago for last_defeated_at.
  // Returns "2h ago" / "yesterday" / "May 14" — never empty.
  function _formatTimeAgo(iso) {
    if (!iso) return 'recently';
    const then = Date.parse(iso);
    if (!isFinite(then)) return 'recently';
    const ms = Date.now() - then;
    if (ms < 60 * 60 * 1000)        return Math.max(1, Math.floor(ms / (60 * 1000))) + 'm ago';
    if (ms < 24 * 60 * 60 * 1000)   return Math.floor(ms / (60 * 60 * 1000)) + 'h ago';
    if (ms < 48 * 60 * 60 * 1000)   return 'yesterday';
    const days = Math.floor(ms / (24 * 60 * 60 * 1000));
    if (days < 7) return days + ' days ago';
    const d = new Date(iso);
    return d.toLocaleDateString('en-US', { month: 'short', day: 'numeric' });
  }

  // v3 Phase 1z.7 — find the most-recent inventory entries whose
  // source_boss matches this boss. Returns up to N { id, card, entry }
  // tuples sorted by first_acquired_date DESC.
  function _bossHuntHistory(bossId, limit) {
    const out = [];
    try {
      if (typeof CARDS === 'undefined' || typeof getInventory !== 'function') return out;
      const inv = getInventory();
      if (!inv || !inv.cards) return out;
      Object.keys(CARDS).forEach(cardId => {
        const card = CARDS[cardId];
        const src = card && (card.source_boss || card.sourceBoss || card.boss || card.boss_id || null);
        if (src !== bossId) return;
        const entry = inv.cards[cardId];
        if (!entry || !entry.discovered || !entry.first_acquired_date) return;
        out.push({ id: cardId, card: card, entry: entry });
      });
      out.sort((a, b) => {
        const da = a.entry.first_acquired_date || '';
        const db = b.entry.first_acquired_date || '';
        return db.localeCompare(da);
      });
    } catch (_) {}
    return out.slice(0, limit || 3);
  }

  function _populateBfsDefeatedState(id, cfg, state) {
    // Hero card
    const heroEl = document.getElementById('bfs-defeated-hero');
    if (heroEl) heroEl.classList.remove('hidden');

    const portraitImg = document.getElementById('bfs-defeated-portrait-img');
    if (portraitImg) {
      portraitImg.removeAttribute('data-art');
      portraitImg.onerror = () => { portraitImg.setAttribute('data-art', 'missing'); };
      portraitImg.onload  = () => { portraitImg.removeAttribute('data-art'); };
      portraitImg.src = getBossArtPath(id);
    }

    const rankPill = document.getElementById('bfs-defeated-rank-pill');
    if (rankPill) {
      const rank = (cfg.rank || 'E').toUpperCase();
      rankPill.textContent = rank + '-Rank · Defeated';
      rankPill.setAttribute('data-rank', rank);
    }

    const nameEl = document.getElementById('bfs-defeated-name');
    if (nameEl) nameEl.textContent = cfg.name || '—';

    const subline = document.getElementById('bfs-defeated-subline');
    if (subline) {
      const when = _formatTimeAgo(state.last_defeated_at);
      subline.textContent = 'Was defeated ' + when + '. Engage again to begin a new hunt.';
    }

    // Last drop callout — top entry from hunt history (if any).
    const history = _bossHuntHistory(id, 3);
    const lastDrop = document.getElementById('bfs-last-drop');
    if (lastDrop) {
      if (history.length > 0) {
        const top = history[0];
        lastDrop.classList.remove('hidden');
        lastDrop.setAttribute('data-card-id', top.id);
        lastDrop.setAttribute('data-rarity', top.card.rarity || 'common');
        const nameOut = document.getElementById('bfs-last-drop-name');
        if (nameOut) nameOut.textContent = top.card.name || '';
        const metaOut = document.getElementById('bfs-last-drop-meta');
        if (metaOut) {
          const rarityLabel = (RARITY_LABELS && RARITY_LABELS[top.card.rarity]) || top.card.rarity || '';
          const slotLabel = (top.card.slot || '').toUpperCase();
          metaOut.textContent = String(rarityLabel).toUpperCase() + (slotLabel ? ' · ' + slotLabel : '');
        }
        const slotIcon = document.getElementById('bfs-last-drop-slot-icon');
        if (slotIcon) slotIcon.textContent = (SLOT_ICONS && SLOT_ICONS[top.card.slot]) || '✦';
        const imgOut = document.getElementById('bfs-last-drop-img');
        if (imgOut) {
          imgOut.removeAttribute('data-art');
          imgOut.onerror = () => { imgOut.setAttribute('data-art', 'missing'); };
          imgOut.onload  = () => { imgOut.removeAttribute('data-art'); };
          if (top.card.art_path) {
            imgOut.src = top.card.art_path;
          } else {
            imgOut.removeAttribute('src');
            imgOut.setAttribute('data-art', 'missing');
          }
        }
      } else {
        lastDrop.classList.add('hidden');
      }
    }

    // Hunt history — up to 3 most recent (already the same array
    // we used for last-drop, but render all rows here including #1).
    const histSection = document.getElementById('bfs-hunt-history');
    const histList    = document.getElementById('bfs-hunt-history-list');
    if (histSection && histList) {
      if (history.length === 0) {
        histSection.classList.add('hidden');
        histList.innerHTML = '';
      } else {
        histSection.classList.remove('hidden');
        histList.innerHTML = history.map(h => {
          const when = _formatTimeAgo(h.entry.first_acquired_date);
          const rarityLabel = (RARITY_LABELS && RARITY_LABELS[h.card.rarity]) || h.card.rarity || '';
          return (
            '<div class="bfs-hunt-history-row">' +
              '<span class="bfs-hunt-history-row-dot" aria-hidden="true"></span>' +
              '<span class="bfs-hunt-history-row-when">' + esc(when) + '</span>' +
              '<span class="bfs-hunt-history-row-name">' + esc(h.card.name || '') + '</span>' +
              '<span class="bfs-hunt-history-row-rarity" data-rarity="' + esc(h.card.rarity || 'common') + '">' + esc(String(rarityLabel).toUpperCase()) + '</span>' +
            '</div>'
          );
        }).join('');
      }
    }

    // Primary CTA — hunt again with souls cost surfaced in button
    // text. Footnote framed per cadence (night / day).
    const ctaSection = document.getElementById('bfs-defeated-cta');
    const ctaBtn     = document.getElementById('bfs-defeated-hunt-again');
    const ctaFoot    = document.getElementById('bfs-defeated-cta-foot');
    if (ctaSection) ctaSection.classList.remove('hidden');
    if (ctaBtn) {
      ctaBtn.setAttribute('data-boss-id', id);
      const cost = (typeof engageCostSouls === 'function') ? engageCostSouls(cfg.rank) : 0;
      ctaBtn.textContent = cost > 0 ? ('HUNT AGAIN — ' + cost + ' SOULS') : 'HUNT AGAIN';
    }
    // W312 — boss-kill share affordance. Persistent RE-TRIGGER surface
    // (this screen reopens for any defeated boss). Append once; just
    // refresh the boss id on each open.
    if (ctaSection) {
      let _bksBtn = document.getElementById('bfs-defeated-share');
      if (!_bksBtn) {
        _bksBtn = document.createElement('button');
        _bksBtn.id = 'bfs-defeated-share';
        _bksBtn.className = 'bks-share-cta bks-share-cta--block';
        _bksBtn.setAttribute('type', 'button');
        _bksBtn.setAttribute('data-bkshare', '');
        _bksBtn.setAttribute('data-bk-source', 'dungeon');
        _bksBtn.innerHTML = _bksShareIconSvg() + 'Share this kill';
        if (ctaFoot && ctaFoot.parentNode === ctaSection) ctaSection.insertBefore(_bksBtn, ctaFoot);
        else ctaSection.appendChild(_bksBtn);
      }
      _bksBtn.setAttribute('data-boss-id', id);
    }
    if (ctaFoot) {
      const cadence = cfg.cadence || 'daily';
      // Pick a friendly "unit" — sleep/bedtime → "night"; everything else → "day".
      let unit = 'day';
      const cond = (cfg.killCondShort || cfg.killCondLong || '').toLowerCase();
      if (cond.indexOf('sleep') >= 0 || cond.indexOf('night') >= 0 || cond.indexOf('bedtime') >= 0) {
        unit = 'night';
      }
      const cadenceNote = cadence === 'weekly' ? "next weekend's hunt"
                        : cadence === 'triweekly' ? 'the next qualifying ' + unit
                        : 'next ' + unit;
      ctaFoot.textContent = 'Engages the ' + (cfg.name || 'boss') + ' · ' + cadenceNote + ' counts toward this hunt.';
    }
  }

  // Tracks the boss currently shown in the full-screen modal so
  // engage/disengage helpers can refresh the visible state without
  // each helper needing to re-resolve which boss is on screen.
  let bfsCurrentBossId = null;

  function refreshBossFullScreenIfOpen(bossId) {
    const overlay = document.getElementById('boss-fs-overlay');
    if (!overlay || overlay.classList.contains('hidden')) return;
    if (bfsCurrentBossId !== bossId) return;
    // Re-run open with the same boss to repopulate fields without
    // closing the overlay (open() already short-circuits on the
    // visible-overlay branch — it just rewrites the inner content).
    openBossFullScreen(bossId);
  }

  // Friendly date display for engaged_at. ISO 8601 stored, displayed
  // as "today" / "yesterday" / "N days ago" for recent dates and an
  // absolute "May 9, 2026" for older. Falls back to "—" if missing.
  function formatEngagedAt(isoString) {
    if (!isoString) return '—';
    const then = new Date(isoString);
    if (isNaN(then.getTime())) return '—';
    const now = new Date();
    // Compare device-local calendar days, not 24-hour windows.
    const ymdNow  = now.getFullYear() + '-' + (now.getMonth()+1) + '-' + now.getDate();
    const ymdThen = then.getFullYear() + '-' + (then.getMonth()+1) + '-' + then.getDate();
    if (ymdNow === ymdThen) return 'today';
    const ms = now.setHours(0,0,0,0) - new Date(then).setHours(0,0,0,0);
    const days = Math.round(ms / (1000 * 60 * 60 * 24));
    if (days === 1) return 'yesterday';
    if (days > 1 && days < 7) return days + ' days ago';
    // Older — absolute date, e.g., "May 9, 2026"
    return then.toLocaleDateString('en-US', { month: 'short', day: 'numeric', year: 'numeric' });
  }

  function closeBossFullScreen() {
    const overlay = document.getElementById('boss-fs-overlay');
    if (!overlay) return;
    if (overlay.classList.contains('hidden')) return;
    overlay.classList.add('hidden');
    document.body.classList.remove('bfs-locked');
    // Reset scroll position so re-opening starts from the top.
    overlay.scrollTop = 0;
  }
  try { window.openBossFullScreen = openBossFullScreen; } catch (_) {}
  try { window.closeBossFullScreen = closeBossFullScreen; } catch (_) {}

  function setupBossesPanel() {
    const list = document.getElementById('bosses-list');
    if (list) {
      list.addEventListener('click', (e) => {
        // W370 — co-op card opens its own sheet (data-coop-boss, separate path).
        const coopCard = e.target.closest('.bcard[data-coop-boss]');
        if (coopCard) { const _cid = coopCard.getAttribute('data-coop-boss'); try { _coopOpenRecruit(_cid); } catch (_) {} return; }   // W577 — card = the summon/invite entry (The Pacts strip covers progress + accepts)
        const card = e.target.closest('.bcard[data-boss]');
        if (!card) return;
        const id = card.getAttribute('data-boss');
        if (id) openBossFullScreen(id);
      });
      try { _coopWireOverlay(); } catch (_) {}
    }
    // Wire the modal's Back button + ESC key.
    const backBtn = document.getElementById('bfs-back');
    if (backBtn) backBtn.addEventListener('click', closeBossFullScreen);
    document.addEventListener('keydown', (e) => {
      if (e.key !== 'Escape') return;
      const overlay = document.getElementById('boss-fs-overlay');
      if (overlay && !overlay.classList.contains('hidden')) {
        closeBossFullScreen();
      }
    });

    // Engagement buttons (v2.0.1). The handlers read data-boss-id
    // off the button — set by openBossFullScreen at open time so
    // we don't capture a stale boss id at setup time.
    const engageBtn = document.getElementById('bfs-engage-btn');
    if (engageBtn) {
      engageBtn.addEventListener('click', () => {
        const id = engageBtn.getAttribute('data-boss-id');
        if (id) engageBoss(id);
      });
    }
    const disengageBtn = document.getElementById('bfs-disengage-btn');
    if (disengageBtn) {
      disengageBtn.addEventListener('click', () => {
        const id = disengageBtn.getAttribute('data-boss-id');
        if (!id) return;
        const cfg = BOSSES[id];
        const name = (cfg && cfg.name) || 'this boss';
        // Native confirm — accessible, iOS-WebView-styled. Custom
        // brand-matched modal would be polish; functional path here.
        const ok = window.confirm('Stop hunting ' + name + '? Your current streak will reset.');
        if (ok) disengageBoss(id);
      });
    }
    // v3 Phase 1z.7 — defeated-state Hunt Again CTA + last-drop tap.
    const defeatedCta = document.getElementById('bfs-defeated-hunt-again');
    if (defeatedCta) {
      defeatedCta.addEventListener('click', () => {
        const id = defeatedCta.getAttribute('data-boss-id');
        if (id) { try { engageBoss(id); } catch (_) {} }
      });
    }
    const lastDropBtn = document.getElementById('bfs-last-drop');
    if (lastDropBtn) {
      lastDropBtn.addEventListener('click', () => {
        const cardId = lastDropBtn.getAttribute('data-card-id');
        if (!cardId || typeof CARDS === 'undefined') return;
        try {
          const card = CARDS[cardId];
          const inv = (typeof getInventory === 'function') ? getInventory() : null;
          const entry = inv && inv.cards && inv.cards[cardId];
          if (card && entry && typeof openCardDetailModal === 'function') {
            // Close the boss detail first so the relic detail isn't
            // stacked behind it — opening the card modal from inside a
            // visible bfs is otherwise hard to dismiss back to dungeon.
            try { closeBossFullScreen(); } catch (_) {}
            openCardDetailModal(card, entry);
          }
        } catch (_) {}
      });
    }
  }

